REPLACE INTO config (k, v, note) VALUES
  ('late_points', '2', 'strikes for coming in after late_after (before noon)'),
  ('noon_points', '3', 'strikes for coming in after noon'),
  ('absent_points', '4', 'strikes for a working day you never came in (not on a trip, not sick)'),
  ('warn_points', '2', 'strikes at which the manager texts you about being on time'),
  ('final_points', '4', 'strikes at which HR emails a final written warning'),
  ('fire_points', '6', 'strikes at which you are let go: the badge no longer opens the office');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_badge', 1, 'tom', 'You walk up to the front desk on your first morning at Seaside Labs.', '시사이드 랩스 첫 출근 아침, 프런트 데스크로 다가갑니다.', 'Hi there! How can I help you?', '안녕하세요! 무엇을 도와드릴까요?', 'Let him know who you are and why you''re here this morning.', '당신이 누구인지, 오늘 아침 왜 왔는지 알려 주세요.', '[{"all":["first day"]},{"all":["start","today"]},{"all":["new","developer"]}]', 'Hi, I''m Jun. It''s my first day here. I''m joining the engineering team as a developer.', '안녕하세요, 준이라고 해요. 오늘 첫 출근이에요. 엔지니어링 팀에 개발자로 합류해요.', '["Hi, I''m Jun. I have an interview here at nine this morning. I''m a little early, I think.","Hi. Is this where I pick up a visitor pass? I''m meeting someone upstairs.","Hey! I''m Jun, the new guy. Honestly, I barely slept last night, I''m so nervous."]', '["안녕하세요, 준이에요. 오늘 아침 아홉 시에 여기서 면접이 있어요. 좀 일찍 온 것 같아요.","안녕하세요. 방문증은 여기서 받나요? 위층에서 누구 만나기로 해서요.","안녕하세요! 준이에요, 신입이요. 솔직히 너무 긴장돼서 어젯밤에 거의 못 잤어요."]', '["An interview? Hmm, I have you down as a new hire.","Sure. Who are you here to see?","Ha, deep breaths. Who are you here to see?"]', '["면접이요? 음, 신입 사원으로 등록돼 있는데요.","그럼요. 누구 만나러 오셨어요?","하하, 심호흡하세요. 누구 만나러 오셨죠?"]', '["Say: It''s my first day.","Key words: first day"]', '["It''s my first day.라고 말해 보세요.","핵심 단어: first day"]', 'tom', 'Welcome aboard! You must be the new developer.', '환영해요! 새로 온 개발자군요.'),
  ('d1_badge', 2, 'tom', 'Tom pulls up a form on his screen and points a small camera at you.', '톰이 화면에 양식을 띄우고 작은 카메라를 당신 쪽으로 돌립니다.', 'I just need to see a photo ID for the badge.', '출입증 만들게 사진 있는 신분증만 보여 주세요.', 'Give him what he asked for.', '그가 달라는 것을 건네세요.', '[{"all":["here you go"]},{"all":["here it is"]},{"all":["here you are"]},{"any":["license","passport"]}]', 'Sure, here you go. It''s my driver''s license.', '네, 여기 있어요. 운전면허증이에요.', '["Sure, here you go. It''s my credit card.","Sure. Do you need my Social Security number too?","Seriously? I already sent all that to HR."]', '["네, 여기 있어요. 신용카드예요.","네. 사회보장번호도 필요하세요?","또요? 그거 인사팀에 다 보냈는데요."]', '["Hmm, I need one with your photo on it.","No, no! Just a photo ID is fine.","I know, sorry. It''s just for the badge photo."]', '["음, 사진이 있는 걸로 주셔야 해요.","아뇨, 아뇨! 사진 있는 신분증이면 돼요.","알아요, 미안해요. 출입증 사진 때문에 그래요."]', '["Use the phrase for handing something over.","Key words: here you go"]', '["물건을 건넬 때 쓰는 표현을 쓰세요.","핵심 단어: here you go"]', 'tom', 'Thanks. Okay, smile! … Perfect. Here''s your badge.', '고마워요. 자, 웃어요! … 좋아요. 출입증 여기 있어요.'),
  ('d1_badge', 3, 'tom', 'The badge has your photo on it. It looks a little surprised.', '출입증에 당신 사진이 있습니다. 좀 놀란 표정이네요.', 'Tap it on the reader by the glass doors. It''ll get you into the building and up to three.', '유리문 옆 단말기에 대세요. 건물에 들어오고 3층까지 올라갈 수 있어요.', 'You''re worried about the day you leave it at home. Ask about that.', '출입증을 집에 두고 오는 날이 걱정됩니다. 그때는 어떻게 하는지 물어보세요.', '[{"all":["forget"]},{"all":["lose"]},{"all":["what if"]}]', 'Got it. What should I do if I forget my badge?', '알겠어요. 출입증을 깜빡하면 어떻게 해요?', '["Got it. So it works on every floor, right?","Can I take it home, or does it stay here?","Cool. Can I get a better photo? I look weird."]', '["알겠어요. 그럼 모든 층에서 되는 거죠?","집에 가져가도 돼요, 아니면 여기 두나요?","좋아요. 사진 다시 찍으면 안 돼요? 이상하게 나왔어요."]', '["Just the lobby and three. That''s where you''ll be.","Take it with you! You''ll need it every morning.","Ha! Everyone says that. It grows on you."]', '["로비랑 3층만요. 일하실 곳이 거기예요.","가져가세요! 매일 아침 필요해요.","하하! 다들 그래요. 보다 보면 정들어요."]', '["Ask: What should I do if I …?","Key words: forget, badge"]', '["What should I do if I …?로 물어보세요.","핵심 단어: forget, badge"]', 'tom', 'Just come see me. I''ll give you a temporary one for the day.', '저한테 오면 돼요. 그날 쓸 임시 출입증을 드릴게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_badge', 4, 'tom', 'Tom points past a row of plants.', '톰이 화분들 너머를 가리킵니다.', 'Maya''s expecting you on three. The elevators are right past the plants, on your left.', '마야가 3층에서 기다리고 있어요. 엘리베이터는 화분 바로 지나서 왼쪽이에요.', 'He''s been a big help. Let him know before you head up.', '그가 많이 도와줬습니다. 올라가기 전에 마음을 전하세요.', '[{"any":["thanks","thank","appreciate"]}]', 'Thanks so much, Tom. I appreciate it.', '정말 고마워요, 톰. 큰 도움이 됐어요.', '["Thanks, Tom. Elevators on the right, then?","Okay, okay. I can find it myself.","Thanks, Tom. Can you walk me up there?"]', '["고마워요, 톰. 그럼 엘리베이터는 오른쪽이죠?","네, 네. 혼자 찾아갈 수 있어요.","고마워요, 톰. 저 좀 데려다주실 수 있어요?"]', '["On your left, right past the plants.","Oh. Sure, of course.","I wish I could, but I''ve got to stay at the desk."]', '["왼쪽이에요. 화분 바로 지나서요.","아. 네, 그럼요.","그러고 싶은데 데스크를 지켜야 해서요."]', '["Say thank you, maybe with \\"I appreciate it.\\"","Key words: thanks, appreciate"]', '["고맙다고 하세요. \\"I appreciate it.\\"을 덧붙여도 좋아요.","핵심 단어: thanks, appreciate"]', 'tom', 'Anytime. Have a great first day!', '언제든지요. 좋은 첫날 보내요!'),
  ('d1_bus', 1, 'carl', 'It is your first Monday in Fairview. Your neighbor Carl, who also owns your building, is waiting at the bus stop.', '페어뷰에서 맞는 첫 월요일입니다. 이웃이자 건물 주인인 칼이 버스 정류장에서 기다리고 있습니다.', 'Well, look who''s up early! Heading into work?', '어이, 누가 이렇게 일찍 나왔나 했더니! 출근하는 거야?', 'Carl is making small talk. Tell him why today is a big day for you.', '칼이 말을 걸어옵니다. 오늘이 왜 특별한 날인지 말해 주세요.', '[{"all":["first day"]},{"all":["new job"]},{"all":["start","today"]}]', 'Yeah, it''s my first day at my new job.', '네, 오늘 새 직장에 첫 출근하는 날이에요.', '["Yeah, back to work after a long week off.","Yeah. Sorry, I''m not really a morning person.","Yeah, are you heading into work too?"]', '["네, 일주일 쉬고 다시 출근하는 거예요.","네. 죄송한데 제가 아침엔 좀 약해서요.","네, 칼도 출근하시는 길이에요?"]', '["A week off? I thought you just moved in!","Ha, fair enough. I''ll let you wake up.","I asked you first, kid! What''s the occasion?"]', '["일주일 쉬었다고? 이사 온 지 얼마 안 된 줄 알았는데!","하하, 그래. 잠 좀 깨게 놔둬야겠네.","내가 먼저 물었잖아! 무슨 날이야?"]', '["Tell him today is your first day.","Key words: first day, new job"]', '["오늘이 첫 출근이라고 말하세요.","핵심 단어: first day, new job"]', 'carl', 'No kidding! Congrats, kid.', '정말? 축하해!'),
  ('d1_bus', 2, 'carl', 'Carl folds his newspaper and turns to you.', '칼이 신문을 접고 당신 쪽으로 돌아섭니다.', 'So where''s the new gig?', '그래서 새 직장은 어디야?', 'Tell him where you work and what you do there.', '어디서 일하고 무슨 일을 하는지 말해 주세요.', '[{"all":["seaside"]},{"all":["developer"]},{"all":["software"]},{"all":["engineer"]}]', 'It''s at Seaside Labs downtown. I''m a software developer.', '시내에 있는 시사이드 랩스요. 소프트웨어 개발자예요.', '["Seaside Labs, downtown. I''m a product manager there.","It''s on the third floor, by the elevators. Nice office.","Just some tech company. You wouldn''t have heard of it."]', '["시내에 있는 시사이드 랩스요. 프로덕트 매니저예요.","3층 엘리베이터 옆이에요. 사무실이 좋더라고요.","그냥 IT 회사예요. 들어도 모르실 거예요."]', '["Huh. Your rental application said software developer.","Ha! I meant which company, kid.","Try me, kid. I read the paper every day."]', '["어? 임대 신청서엔 소프트웨어 개발자라고 돼 있던데.","하하! 무슨 회사냐고 물은 거야.","말해 봐. 나 신문은 매일 읽는다고."]', '["Say the company name and your job.","Key words: Seaside Labs, developer"]', '["회사 이름과 직업을 말하세요.","핵심 단어: Seaside Labs, developer"]', 'carl', 'Oh, the tech place by the river. Fancy!', '아, 강가에 있는 그 IT 회사. 멋지네!'),
  ('d1_bus', 3, 'carl', 'You have never taken this bus before.', '이 버스를 타는 건 처음입니다.', 'The Number 12 should be here any minute. You got your fare?', '12번 버스가 곧 올 거야. 차비는 있어?', 'You have never paid for this bus. Find out what it costs and how to pay.', '이 버스 요금을 내 본 적이 없습니다. 얼마인지, 어떻게 내는지 알아보세요.', '[{"all":["how much"]},{"all":["pay"],"any":["card","tap","phone","cash"]},{"all":["exact change"]}]', 'How much is it? Can I just tap my card?', '얼마예요? 그냥 카드 대면 되나요?', '["Yeah, I''ve got it. Thanks for asking.","How long is the ride? Is it the Number 12?","Do you have change? I only brought a twenty."]', '["네, 있어요. 물어봐 주셔서 고마워요.","얼마나 걸려요? 12번 버스 맞죠?","잔돈 있으세요? 20달러짜리밖에 없어서요."]', '["Oh yeah? How much is it, then?","Yep, the 12, like I just said. But you got your fare?","Ha, nice try. I''m not your bank, kid."]', '["그래? 그럼 얼만데?","그래, 12번이라니까. 그래서 차비는 있냐고.","하하, 어림없지. 내가 은행이냐."]', '["Ask about the price and paying with a card.","Key words: how much, card"]', '["가격과 카드 결제에 대해 물어보세요.","핵심 단어: how much, card"]', 'carl', 'Two fifty. Just tap your card on the reader when you get on.', '2달러 50센트. 탈 때 단말기에 카드를 대면 돼.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_bus', 4, 'carl', 'The bus pulls up and the doors open. Carl waves you ahead.', '버스가 서고 문이 열립니다. 칼이 먼저 타라고 손짓합니다.', 'Here it comes. After you! Have a good one.', '왔다. 먼저 타! 좋은 하루 보내.', 'He lets you get on first. Answer him warmly.', '그가 먼저 타라고 합니다. 따뜻하게 답해 주세요.', '[{"any":["thanks","thank"]},{"all":["you too"]},{"all":["good day"]}]', 'Thanks, Carl! You too.', '고마워요, 칼! 칼도요.', '["Thanks! See you at work.","Uh-huh. Whatever you say.","Thanks! Is this the 12?"]', '["고마워요! 회사에서 봬요.","네, 네. 알았다고요.","고마워요! 이게 12번이에요?"]', '["Ha! I''m not going where you''re going, kid.","Somebody got up on the wrong side of the bed.","Sure is. Now hop on before he leaves!"]', '["하하! 난 너랑 같은 데 안 가.","누가 아침부터 기분이 안 좋은가 보네.","그렇다니까. 기사 출발하기 전에 얼른 타!"]', '["Say thanks, and return the wish.","Key words: thanks, you too"]', '["고맙다고 하고 같은 인사를 돌려주세요.","핵심 단어: thanks, you too"]', 'carl', 'Knock ''em dead, kid!', '가서 한 방 보여 줘!'),
  ('d1_coffee', 1, 'nina', 'A small coffee cart stands on the corner of Lake Avenue. The barista smiles at you.', '레이크 애비뉴 모퉁이에 작은 커피 카트가 있습니다. 바리스타가 웃으며 맞이합니다.', 'Morning! What can I get started for you?', '좋은 아침이에요! 뭐 준비해 드릴까요?', 'You''d like a latte, not too big and not too small. Order it.', '라테를 마시고 싶습니다. 너무 크지도 작지도 않은 걸로 주문하세요.', '[{"all":["latte"]},{"all":["coffee"]},{"all":["cappuccino"]}]', 'Can I get a medium latte, please?', '라테 미디엄으로 하나 주시겠어요?', '["Can I get a large latte, please?","What''s good here? It''s my first time.","Latte. Medium. And make it quick."]', '["라테 라지로 하나 주시겠어요?","여기 뭐가 맛있어요? 처음 와 봐서요.","라테. 미디엄. 빨리 좀 주세요."]', '["A large? That''s our biggest cup. You sure?","Everything! But what are you in the mood for?","Okay... coming right up."]', '["라지요? 제일 큰 컵인데, 괜찮으세요?","다 맛있죠! 근데 뭐가 당기세요?","네… 바로 해 드릴게요."]', '["Order with \\"Can I get a …, please?\\"","Key words: medium, latte"]', '["\\"Can I get a …, please?\\"로 주문하세요.","핵심 단어: medium, latte"]', 'nina', 'You got it. One medium latte.', '알겠어요. 라테 미디엄 하나.'),
  ('d1_coffee', 2, 'nina', 'Nina reaches for the milk.', '니나가 우유 쪽으로 손을 뻗습니다.', 'Any milk preference? We''ve got whole, skim, oat, and almond.', '우유는 뭘로 할까요? 일반 우유, 무지방, 귀리, 아몬드 있어요.', 'You can''t have dairy, and you''re allergic to nuts. Pick your milk.', '유제품을 못 먹고 견과류 알레르기가 있습니다. 우유를 고르세요.', '[{"any":["oat","almond","whole","skim","regular"]}]', 'Oat milk, please.', '귀리 우유로 주세요.', '["Almond milk, please.","Skim milk, please.","Whatever''s fine."]', '["아몬드 우유로 주세요.","무지방 우유로 주세요.","아무거나 괜찮아요."]', '["Almond, sure. No nut allergies, right?","Skim? That''s still regular dairy, just so you know.","Then I''ll just go with whole milk. That okay?"]', '["아몬드요. 견과류 알레르기는 없으시죠?","무지방도 우유는 우유예요, 참고로요.","그럼 그냥 일반 우유로 할게요. 괜찮아요?"]', '["Name the milk you want and add \\"please\\".","Key words: oat milk"]', '["원하는 우유 이름에 please를 붙이세요.","핵심 단어: oat milk"]', 'nina', 'Oat milk. Great choice.', '귀리 우유. 좋은 선택이에요.'),
  ('d1_coffee', 3, 'nina', 'She picks up a paper cup and a marker.', '그녀가 종이컵과 마커를 집어 듭니다.', 'And what''s the name for the order?', '주문하시는 분 성함은요?', 'Give her what she needs to write on the cup.', '컵에 적을 수 있게 그녀가 묻는 것을 알려 주세요.', '[{"all":["name"]},{"all":["it is"]},{"all":["i am"]},{"any":["jun"]}]', 'It''s Jun. J-U-N.', '준이에요. J-U-N.', '["For here, thanks.","It''s June. J-U-N-E.","Why do you need it?"]', '["여기서 먹고 갈게요.","준이에요. J-U-N-E.","그건 왜 필요한데요?"]', '["Sorry, I meant your name! For the cup.","June with an E? Got it.","Just so we don''t mix up the cups!"]', '["아, 성함 여쭤본 거예요! 컵에 쓰려고요.","끝에 E 붙는 거죠? 알겠어요.","컵이 안 바뀌게 하려고요!"]', '["Say \\"It''s …\\" with your name. You can spell it.","Key words: It''s + your name"]', '["\\"It''s …\\" 뒤에 이름을 말하세요. 철자를 불러 줘도 좋아요.","핵심 단어: It''s + 이름"]', 'nina', 'Got it!', '알겠어요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_coffee', 4, 'nina', 'The card reader lights up.', '카드 단말기에 불이 들어옵니다.', 'That''ll be four seventy-five. Card or cash?', '4달러 75센트입니다. 카드예요, 현금이에요?', 'You don''t have any cash on you. Answer her.', '현금이 하나도 없습니다. 대답하세요.', '[{"any":["card","tap","cash"]}]', 'Card, please. I''ll just tap.', '카드로 할게요. 그냥 갖다 댈게요.', '["Card. Three seventy-five, right?","Cash. Can you break a twenty?","Could you add it to my tab?"]', '["카드요. 3달러 75센트 맞죠?","현금이요. 20달러 깨 주실 수 있어요?","제 앞으로 달아 두실 수 있어요?"]', '["Four seventy-five, actually.","Sure, I can. Let''s see the twenty.","Sorry, we don''t do tabs here. Card or cash?"]', '["4달러 75센트예요.","그럼요. 20달러 주세요.","죄송해요, 외상은 안 돼요. 카드예요, 현금이에요?"]', '["Answer her question: card or cash.","Key words: card"]', '["카드인지 현금인지 답하세요.","핵심 단어: card"]', 'nina', 'Perfect. The screen will ask about a tip. Totally up to you! Here''s your latte.', '좋아요. 화면에 팁을 물어볼 거예요. 전적으로 마음대로 하세요! 라테 나왔어요.'),
  ('d1_desk', 1, 'derek', 'A man in a hoodie looks up from two monitors by the window.', '창가에서 모니터 두 대를 보던 후드티 차림의 남자가 고개를 듭니다.', 'Hey! You must be the new hire. Derek. Welcome to the team!', '어이! 새로 온 분이죠? 데릭이에요. 팀에 온 걸 환영해요!', 'Return the greeting and tell him who you are.', '인사를 받고 당신이 누구인지 말하세요.', '[{"all":["nice to meet"]},{"all":["good to meet"]},{"all":["pleasure"]},{"all":["great to meet"]}]', 'Hi, I''m Jun. Nice to meet you, Derek.', '안녕하세요, 준이에요. 만나서 반가워요, 데릭.', '["Hi, I''m Jun. Nice to meet you, Tom.","Thanks. Are you my manager, then?","Yeah, hi. So which desk is mine?"]', '["안녕하세요, 준이에요. 만나서 반가워요, 톰.","고마워요. 그럼 데릭이 제 매니저세요?","네, 안녕하세요. 제 자리는 어디예요?"]', '["Derek, actually. Tom''s the guy at the front desk.","Ha, no, that''s Maya. I''m just your buddy.","Uh, right. Straight to business, huh?"]', '["데릭이에요. 톰은 프런트 데스크에 있는 사람이고요.","하하, 아뇨, 그건 마야죠. 난 그냥 버디예요.","어, 그래요. 바로 본론이네요?"]', '["Say your name and \\"Nice to meet you.\\"","Key words: nice to meet you"]', '["이름을 말하고 \\"Nice to meet you.\\"라고 하세요.","핵심 단어: nice to meet you"]', 'derek', 'Likewise. So this is your desk, right next to mine.', '저도요. 여기가 당신 자리예요, 제 바로 옆.'),
  ('d1_desk', 2, 'derek', 'Your monitor is already plugged in. A sticky note says "Welcome!"', '모니터는 이미 연결돼 있습니다. 포스트잇에 "Welcome!"이라고 쓰여 있습니다.', 'Have you set up your dev environment yet?', '개발 환경 세팅은 했어요?', 'You haven''t started yet. Ask if there are written instructions to follow.', '아직 시작도 못 했습니다. 따라 할 문서가 있는지 물어보세요.', '[{"any":["guide","readme","docs","documentation","instructions","wiki"]}]', 'Not yet. Is there a setup guide I can follow?', '아직요. 따라 할 수 있는 설치 가이드가 있어요?', '["Yeah, I finished it this morning. All good.","Not yet. Could you just set it up for me?","Not yet. Is it okay if I use my own laptop?"]', '["네, 오늘 아침에 다 끝냈어요. 문제없어요.","아직요. 그냥 대신 세팅해 주시면 안 돼요?","아직요. 제 개인 노트북 써도 괜찮아요?"]', '["Already? Wait, how''d you clone without access?","Ha, nice try. You''ll learn more doing it yourself.","Better not. Security would have my head."]', '["벌써요? 잠깐, 권한도 없이 어떻게 클론했어요?","하하, 어림없죠. 직접 해 봐야 더 많이 배워요.","안 쓰는 게 좋아요. 보안팀한테 혼나요."]', '["Ask \\"Is there a … I can follow?\\"","Key words: setup guide"]', '["\\"Is there a … I can follow?\\"로 물어보세요.","핵심 단어: setup guide"]', 'derek', 'Yep, it''s in the README. Clone the repo, run the setup script, and go grab a coffee. It takes a while.', '네, README에 있어요. 저장소를 클론하고 설치 스크립트를 돌린 다음 커피 한 잔 하고 와요. 좀 걸려요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_desk', 3, 'derek', 'The setup script starts printing hundreds of lines.', '설치 스크립트가 수백 줄을 쏟아내기 시작합니다.', 'If the tests fail on your machine, don''t worry. It happens to everybody.', '테스트가 당신 컴퓨터에서 실패해도 걱정하지 마요. 다들 그래요.', 'You want to know where to turn when something goes wrong.', '문제가 생기면 누구를 찾아가야 할지 알고 싶습니다.', '[{"all":["stuck"]},{"all":["who"],"any":["ask","help","contact"]}]', 'Good to know. Who should I ask if I get stuck?', '알아 두면 좋겠네요. 막히면 누구한테 물어봐요?', '["Good to know. So I can skip the failing tests?","That won''t happen to me. I''m pretty careful.","Okay. So how long does the script usually take?"]', '["알아 두면 좋겠네요. 그럼 실패하는 테스트는 건너뛰어도 돼요?","저한텐 그런 일 없을 거예요. 꽤 꼼꼼하거든요.","알겠어요. 근데 스크립트는 보통 얼마나 걸려요?"]', '["Whoa, no. Don''t skip them. Just don''t panic.","Famous last words, my friend.","Like I said, a while. Go grab that coffee."]', '["워, 안 돼요. 건너뛰진 말고, 당황하지 말라는 거예요.","다들 그렇게 말하죠.","말했잖아요, 좀 걸린다고. 커피나 마시고 와요."]', '["Use \\"get stuck\\" (can''t move forward).","Key words: who, stuck"]', '["get stuck(막히다)을 써 보세요.","핵심 단어: who, stuck"]', 'derek', 'Just ping me on chat. Seriously, no question is too dumb.', '채팅으로 그냥 불러요. 진짜로, 멍청한 질문은 없어요.'),
  ('d1_desk', 4, 'derek', 'Derek opens a pull request on his screen to show you.', '데릭이 보여 주려고 화면에 풀 리퀘스트를 엽니다.', 'We push code through pull requests. I''ll review your first one. Sound good?', '코드는 풀 리퀘스트로 올려요. 첫 PR은 내가 리뷰할게요. 괜찮죠?', 'You''re happy with that plan. Let him know you''re grateful.', '그렇게 하면 좋겠습니다. 고마운 마음을 전하세요.', '[{"any":["sounds good","sounds great","perfect","great","awesome","okay","ok","sure","thanks","thank"]}]', 'Sounds good. Thanks for your help, Derek.', '좋아요. 도와줘서 고마워요, 데릭.', '["Sure, but I doubt you''ll find much to fix.","Sounds good. Can I just push to main, though?","Sounds good. So Maya reviews all my PRs?"]', '["좋아요. 근데 고칠 게 별로 없을 거예요.","좋아요. 그냥 main에 푸시하면 안 돼요?","좋아요. 그럼 제 PR은 다 마야가 리뷰해요?"]', '["Ha. We''ll see about that.","Nope. Everything goes through a PR. Everything.","No, I will. At least your first one."]', '["하. 두고 보죠.","안 돼요. 전부 PR로 가요. 전부요.","아뇨, 내가 해요. 적어도 첫 번째는요."]', '["Answer \\"Sound good?\\" with the same words.","Key words: sounds good, thanks"]', '["\\"Sound good?\\"에 같은 말로 답하세요.","핵심 단어: sounds good, thanks"]', 'derek', 'Anytime. Welcome aboard, for real.', '언제든지요. 진심으로 환영해요.'),
  ('d1_lunch', 1, 'rosa', 'The diner smells like coffee and bacon. A server with a pencil behind her ear waves you to the counter.', '다이너에 커피와 베이컨 냄새가 납니다. 귀에 연필을 꽂은 종업원이 카운터로 오라고 손짓합니다.', 'Hi, hon! Just one today? Sit anywhere you like. What can I get you?', '어서 와요! 오늘 혼자예요? 아무 데나 앉아요. 뭐 드릴까요?', 'You''re in the mood for a burger with cheese on it. Order.', '치즈가 올라간 버거가 먹고 싶습니다. 주문하세요.', '[{"any":["burger","cheeseburger","sandwich","pancakes","soup","salad"]}]', 'Can I get a cheeseburger, please?', '치즈버거 하나 주시겠어요?', '["Can I get a hamburger, no cheese?","Could I see a menu first, please?","Cheeseburger. And can you hurry up?"]', '["햄버거 하나요, 치즈는 빼고요.","메뉴판 먼저 볼 수 있을까요?","치즈버거요. 좀 빨리 주실래요?"]', '["Plain hamburger, no cheese. You sure, hon?","Sure, hon. But you look like you know what you want.","Well, okay then. Coming right up."]', '["치즈 없는 그냥 햄버거요? 정말요?","그럼요. 근데 뭐 먹을지 이미 정한 얼굴인데요.","어, 그래요. 금방 나와요."]', '["Order with \\"Can I get a …?\\"","Key words: cheeseburger"]', '["\\"Can I get a …?\\"로 주문하세요.","핵심 단어: cheeseburger"]', 'rosa', 'Sure thing.', '그럼요.'),
  ('d1_lunch', 2, 'rosa', 'Rosa writes on her notepad.', '로사가 수첩에 적습니다.', 'How would you like that cooked?', '굽기는 어떻게 해 드릴까요?', 'You like your burger a little pink in the middle. Tell her.', '버거는 가운데가 살짝 분홍빛인 게 좋습니다. 말해 주세요.', '[{"any":["medium","well done","rare","medium rare","medium well"]}]', 'Medium, please.', '미디엄으로 해 주세요.', '["Well-done, please.","Rare, please.","Cheddar, please."]', '["웰던으로 해 주세요.","레어로 해 주세요.","체다 치즈로 주세요."]', '["Well-done. No pink at all, then.","Rare? That''s pretty red in there, hon.","Cheddar it is. And how cooked, hon?"]', '["웰던이요. 분홍빛은 하나도 없겠네요.","레어요? 속이 꽤 빨간데, 괜찮아요?","체다로 할게요. 그럼 굽기는요?"]', '["Burgers can be rare, medium, or well done.","Key words: medium"]', '["버거는 rare, medium, well done으로 익힙니다.","핵심 단어: medium"]', 'rosa', 'Medium, you got it.', '미디엄, 알겠어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_lunch', 3, 'rosa', 'She taps the pencil on the pad.', '그녀가 연필로 수첩을 톡톡 칩니다.', 'Comes with fries or a side salad. And is that for here or to go?', '감자튀김이나 샐러드 중에 고를 수 있어요. 여기서 드세요, 가져가세요?', 'You want the fried side, and you''re eating right here at the counter.', '튀긴 사이드를 원하고, 여기 카운터에서 먹고 갈 겁니다.', '[{"all":["for here"]},{"all":["to go"]}]', 'Fries, please. And it''s for here.', '감자튀김으로 주세요. 여기서 먹을게요.', '["Side salad, please. And I''ll eat here.","Fries. And can you make it to go?","Fries, please. And yes, it''s for one."]', '["샐러드로 주세요. 여기서 먹을게요.","감자튀김이요. 포장해 주실 수 있어요?","감자튀김이요. 네, 한 명이에요."]', '["Salad, got it. Oh, you didn''t want the fries?","Sure, I''ll box it up for you.","Got that. But for here or to go, hon?"]', '["샐러드요. 감자튀김은 싫으세요?","그럼요, 포장해 드릴게요.","그건 알아요. 근데 여기서 드세요, 가져가세요?"]', '["Answer both questions: side, and for here or to go.","Key words: fries, for here"]', '["두 질문 모두 답하세요: 사이드, 그리고 먹고 갈지 포장할지.","핵심 단어: fries, for here"]', 'rosa', 'It''ll be right out, hon.', '금방 나와요.'),
  ('d1_lunch', 4, 'rosa', 'You finish the burger. It was really good.', '버거를 다 먹었습니다. 정말 맛있었어요.', 'How was everything? Can I get you anything else?', '다 괜찮았어요? 더 필요한 거 있어요?', 'You loved it, and you''re ready to pay.', '정말 맛있었고, 이제 계산하고 싶습니다.', '[{"all":["check"]},{"all":["bill"]}]', 'It was great, thanks. Could I get the check, please?', '정말 맛있었어요, 고마워요. 계산서 좀 주시겠어요?', '["It was great, thanks. Could I get a slice of pie, too?","It was okay. The fries were a little cold, honestly.","Nope. Just the check. I''ve got to get back to work."]', '["정말 맛있었어요, 고마워요. 파이도 한 조각 주시겠어요?","그냥 그랬어요. 솔직히 감자튀김이 좀 식었더라고요.","아뇨. 계산서만 주세요. 빨리 회사 들어가 봐야 해서요."]', '["Ooh, good call. Apple or cherry?","Oh no, I''m sorry, hon. Want me to take some off?","Sure thing. Here you go."]', '["오, 좋은 선택이에요. 사과, 체리 중에 뭘로요?","어머, 미안해요. 좀 깎아 드릴까요?","그래요. 여기 있어요."]', '["In the US you ask for \\"the check\\".","Key words: check"]', '["미국에서는 계산서를 check라고 합니다.","핵심 단어: check"]', 'rosa', 'Here you go, hon. You can pay me right here.', '여기 있어요. 여기서 바로 계산하면 돼요.'),
  ('d1_lunch', 5, 'rosa', 'The check says $16.50 with tax. You have a twenty-dollar bill.', '계산서에는 세금 포함 16.50달러라고 적혀 있습니다. 20달러 지폐가 있습니다.', 'Sixteen fifty. Whenever you are ready.', '16달러 50센트예요. 준비되면 주세요.', 'Pay with the bill you have, and leave whatever is left over for her as a tip.', '가진 지폐로 내고, 남는 돈은 팁으로 주세요.', '[{"all":["keep the change"]},{"any":["tip"]}]', 'Here''s a twenty. Keep the change.', '여기 20달러요. 거스름돈은 가지세요.', '["Here''s a ten. Keep the change.","Here''s a twenty. Can I get my change?","Do I pay you or up at the register?"]', '["여기 10달러요. 거스름돈은 가지세요.","여기 20달러요. 거스름돈 주시겠어요?","여기서 내요, 아니면 계산대에서 내요?"]', '["Hon, that''s a ten. It''s sixteen fifty.","Of course. Three fifty, coming right up.","Right here''s fine, like I said."]', '["손님, 이건 10달러예요. 16달러 50센트인데요.","그럼요. 3달러 50센트 바로 드릴게요.","여기서 내면 된다니까요."]', '["Tell her she can keep the rest of the money.","Key words: keep the change"]', '["남는 돈은 가져도 된다고 말하세요.","핵심 단어: keep the change"]', 'rosa', 'Aw, thank you, hon! Come back and see us.', '어머, 고마워요! 또 와요.'),
  ('d1_market', 1, 'mike', 'You put your groceries on the belt at Fairview Market. The cashier starts scanning.', '페어뷰 마켓 계산대 벨트에 물건을 올려놓습니다. 계산원이 바코드를 찍기 시작합니다.', 'Hey there. Did you find everything okay?', '안녕하세요. 필요한 건 다 찾으셨어요?', 'Your shopping went fine. Answer him.', '장보기는 문제없었습니다. 대답하세요.', '[{"any":["yes","yeah","yep"]},{"all":["found everything"]},{"all":["found it all"]}]', 'Yeah, I found everything, thanks.', '네, 다 찾았어요. 고마워요.', '["I''m fine, thanks. How are you doing?","Not really. I couldn''t find the milk.","Yeah. Can you just ring me up?"]', '["잘 지내요, 고마워요. 그쪽은요?","아뇨. 우유를 못 찾았어요.","네. 그냥 계산이나 해 주세요."]', '["Good, thanks! So, find everything okay?","Oh, it''s in the back. Want me to call someone?","Uh, sure. That''s what I''m doing."]', '["잘 지내요! 그래서 다 찾으셨어요?","아, 그건 안쪽에 있어요. 직원 불러 드릴까요?","어, 네. 지금 하고 있잖아요."]', '["Say yes and repeat \\"found everything\\".","Key words: yeah, found everything"]', '["네라고 하고 \\"found everything\\"을 반복하세요.","핵심 단어: yeah, found everything"]', 'mike', 'Great.', '다행이네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_market', 2, 'mike', 'Mike points at a sign by the register.', '마이크가 계산대 옆 안내판을 가리킵니다.', 'Do you have our rewards card?', '저희 리워드 카드 있으세요?', 'You don''t have one. Find out whether joining costs anything.', '없습니다. 가입하는 데 돈이 드는지 알아보세요.', '[{"all":["free"]},{"all":["sign up"]},{"all":["how","join"]},{"all":["cost"]}]', 'No, I don''t. Is it free to sign up?', '아뇨, 없어요. 가입은 무료예요?', '["Yeah, I do. Let me find it in my wallet.","No. Can I still get the sale prices?","No thanks, I don''t want any more spam."]', '["네, 있어요. 지갑에서 찾아볼게요.","아뇨. 그래도 할인가 되나요?","됐어요, 스팸 문자 더 받기 싫어요."]', '["Take your time. ...Any luck?","Sorry, only with the card. It''s easy to get, though.","Fair enough. We don''t spam, I promise."]', '["천천히 찾으세요. …찾으셨어요?","죄송해요, 카드가 있어야 돼요. 만들기는 쉬워요.","그러시군요. 스팸은 안 보낸다니까요."]', '["Ask if signing up costs money.","Key words: free, sign up"]', '["가입에 돈이 드는지 물어보세요.","핵심 단어: free, sign up"]', 'mike', 'Totally free. Next time just punch in your phone number, and you''ll get the sale prices.', '완전 무료예요. 다음에 전화번호만 누르면 할인가로 살 수 있어요.'),
  ('d1_market', 3, 'mike', 'He holds up two kinds of bags.', '그가 두 종류의 봉투를 들어 보입니다.', 'Paper or plastic?', '종이로 드릴까요, 비닐로 드릴까요?', 'You''d rather skip the plastic.', '비닐봉투는 피하고 싶습니다.', '[{"any":["paper","plastic","own bag","my bag"]}]', 'Paper is fine, thanks.', '종이봉투면 돼요, 고마워요.', '["Plastic is fine, thanks.","Whatever. Doesn''t matter.","Yes, please. Thank you."]', '["비닐봉투면 돼요, 고마워요.","아무거나요. 상관없어요.","네, 주세요. 고마워요."]', '["Plastic, got it. Want it double-bagged?","Okay... I''ll just pick one, then.","Ha, that wasn''t a yes-or-no question!"]', '["비닐로요. 두 겹으로 싸 드릴까요?","네… 그럼 제가 그냥 고를게요.","하하, 네 아니오로 대답하는 질문이 아닌데요!"]', '["Choose one of the two.","Key words: paper"]', '["둘 중 하나를 고르세요.","핵심 단어: paper"]', 'mike', 'Paper it is. Bags are ten cents each, just so you know.', '종이로 할게요. 참고로 봉투는 하나에 10센트예요.'),
  ('d1_market', 4, 'mike', 'The screen shows the total.', '화면에 합계가 나옵니다.', 'Your total''s twenty-three eighty-nine. Go ahead and insert or tap whenever you''re ready.', '합계 23달러 89센트입니다. 준비되면 카드 꽂거나 대세요.', 'Pay. You want to keep the receipt, but your hands are full.', '계산하세요. 영수증은 챙기고 싶은데 손이 꽉 찼습니다.', '[{"all":["receipt"]}]', 'Thanks. Could you put the receipt in the bag?', '고마워요. 영수증은 봉투에 넣어 주시겠어요?', '["Thanks. No receipt for me, I don''t need it.","Thanks. Was that twenty-three nineteen?","Thanks. Can you carry these out to my car?"]', '["고마워요. 영수증은 필요 없어요, 버려 주세요.","고마워요. 23달러 19센트였죠?","고마워요. 이것 좀 차까지 들어다 주실래요?"]', '["Sure. Not even for returns?","Twenty-three eighty-nine.","Sorry, we don''t do carry-out. Need a cart?"]', '["그래요. 반품할 때 필요할 텐데요?","23달러 89센트예요.","죄송해요, 그건 안 해요. 카트 드릴까요?"]', '["Ask \\"Could you put … in the bag?\\"","Key words: receipt, bag"]', '["\\"Could you put … in the bag?\\"로 부탁하세요.","핵심 단어: receipt, bag"]', 'mike', 'You got it. Have a good night!', '알겠어요. 좋은 밤 보내요!'),
  ('d1_onboarding', 1, 'maya', 'Maya waves you into her office. There is a box with a new laptop on her desk.', '마야가 사무실로 들어오라고 손짓합니다. 책상에 새 노트북 상자가 있습니다.', 'Hey, you made it! I''m Maya, your manager. How was the commute?', '어, 왔네요! 저는 마야, 매니저예요. 출근길은 어땠어요?', 'Tell her how you got here this morning and how it went.', '오늘 아침 어떻게 왔고 어땠는지 말해 주세요.', '[{"all":["bus"]},{"any":["easy","fine","smooth","not bad","pretty good"]}]', 'Not bad at all. I took the bus, and it was pretty easy.', '괜찮았어요. 버스 타고 왔는데 꽤 수월했어요.', '["Not bad at all. I drove in, and parking was pretty easy.","Honestly, kind of awful. The guy next to me smelled.","Good, thanks! How long have you been at Seaside Labs?"]', '["괜찮았어요. 차 몰고 왔는데 주차도 꽤 쉬웠어요.","솔직히 좀 최악이었어요. 옆 사람한테서 냄새가 나서요.","좋았어요! 시사이드 랩스에는 얼마나 계셨어요?"]', '["Really? Easy parking downtown? That''s a first.","Oh no. Well, welcome to public transit!","Oh, a while! But how''d you get in today?"]', '["정말요? 시내에서 주차가 쉬웠다고요? 처음 듣네요.","어머. 뭐, 대중교통에 온 걸 환영해요!","꽤 됐죠! 그보다 오늘 어떻게 왔어요?"]', '["Say how it went and how you came.","Key words: bus, easy"]', '["어땠는지, 무엇을 타고 왔는지 말하세요.","핵심 단어: bus, easy"]', 'maya', 'Good to hear. Parking downtown is a nightmare.', '다행이네요. 시내 주차는 악몽이거든요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_onboarding', 2, 'maya', 'She slides the laptop box across the desk, along with a monitor cable and a headset.', '그녀가 노트북 상자와 모니터 케이블, 헤드셋을 건넵니다.', 'So, here is your laptop, a monitor, and a headset. IT already set up your email.', '자, 이건 노트북, 모니터, 헤드셋이에요. IT팀이 이메일은 벌써 설정해 놨어요.', 'You can''t do much until you can see the code. Thank her and bring that up.', '코드를 볼 수 있어야 일을 시작할 수 있습니다. 고맙다고 하고 그 얘기를 꺼내세요.', '[{"all":["access"]},{"any":["repo","repository","codebase"]}]', 'Great, thanks. When will I get access to the code repository?', '좋네요, 고마워요. 코드 저장소 접근 권한은 언제 받을 수 있어요?', '["Great, thanks. When will IT set up my work email account?","Thanks. Could I get a second monitor? One''s not really enough.","Great, thanks. I already have access to the repository, right?"]', '["좋네요, 고마워요. IT팀이 업무용 이메일은 언제 만들어 줘요?","고마워요. 모니터 하나 더 받을 수 있을까요? 하나로는 좀 부족해서요.","좋네요, 고마워요. 저장소 접근 권한은 이미 있는 거죠?"]', '["Already done! Check your inbox.","Let''s see how you do with one first, okay?","Not yet, actually. That''s on the list for today."]', '["벌써 다 됐어요! 받은편지함 확인해 봐요.","일단 하나로 해 보고 얘기해요, 알았죠?","아직요. 그건 오늘 할 일 목록에 있어요."]', '["Ask \\"When will I get access to …?\\"","Key words: access, repository"]', '["\\"When will I get access to …?\\"로 물어보세요.","핵심 단어: access, repository"]', 'maya', 'Derek will add you today. He''s your onboarding buddy.', '데릭이 오늘 추가해 줄 거예요. 그가 온보딩 버디예요.'),
  ('d1_onboarding', 3, 'maya', 'Maya opens a slide with the team photo.', '마야가 팀 사진이 있는 슬라이드를 엽니다.', 'You''ll be on the Payments team with Derek and Priya. Any questions about the team?', '데릭, 프리야와 함께 결제 팀에서 일하게 될 거예요. 팀에 대해 궁금한 거 있어요?', 'You want to know what you''ll actually be building. Ask her.', '실제로 무엇을 만들게 될지 궁금합니다. 물어보세요.', '[{"all":["working on"]},{"all":["what","team"],"any":["building","doing","project"]}]', 'What''s the team working on right now?', '지금 팀에서 무슨 일을 하고 있어요?', '["Which floor does the Payments team sit on?","How soon can I get promoted on this team?","Is it true the Payments team works late a lot?"]', '["결제 팀은 몇 층에 앉아요?","이 팀에서는 승진이 얼마나 빨라요?","결제 팀이 야근이 많다는 게 사실이에요?"]', '["Right here on three. But anything about the work?","Ha! Let''s get you through day one first.","Who told you that? We''re pretty good about hours."]', '["여기 3층이요. 일에 대해서는 궁금한 거 없어요?","하하! 일단 첫날부터 잘 보내 봐요.","누가 그래요? 우리 근무 시간 꽤 잘 지켜요."]', '["Ask \\"What is the team working on …?\\"","Key words: working on"]', '["\\"What is the team working on …?\\"으로 물어보세요.","핵심 단어: working on"]', 'maya', 'We''re rebuilding the checkout flow for our retail clients. Big project, fun stuff.', '소매업 고객들을 위해 결제 흐름을 다시 만들고 있어요. 큰 프로젝트인데 재밌어요.'),
  ('d1_onboarding', 4, 'maya', 'She closes the laptop and smiles.', '그녀가 노트북을 덮고 웃습니다.', 'Anyway, that''s a lot for day one. Let me know if you have any questions, okay? My door''s always open.', '아무튼 첫날치고는 많죠. 궁금한 거 있으면 말해요, 알았죠? 내 방은 언제든 열려 있어요.', 'She''s offering to help anytime. Accept, and show you''re grateful.', '언제든 도와주겠다고 합니다. 고마운 마음을 담아 그러겠다고 하세요.', '[{"any":["thanks","thank","will do","sounds good","appreciate"]}]', 'Thanks, Maya. I will. I really appreciate it.', '고마워요, 마야. 그럴게요. 정말 감사해요.', '["Thanks, but I''ll try not to bother you much.","Actually, yes. Can we talk about my salary?","Thanks. Oh, so is your door usually closed?"]', '["고마워요. 근데 되도록 귀찮게 안 해 드릴게요.","사실 있어요. 연봉 얘기 좀 할 수 있을까요?","고마워요. 아, 평소엔 문을 닫아 두세요?"]', '["You won''t bother me. That''s literally my job.","Uh, let''s save that for HR, okay?","Ha, no. I mean you can come to me anytime."]', '["귀찮긴요. 그게 바로 내 일인걸요.","어, 그건 인사팀이랑 얘기해요, 알았죠?","하하, 아뇨. 언제든 찾아와도 된다는 뜻이에요."]', '["Say thanks, and \\"I will.\\"","Key words: thanks, I will"]', '["고맙다고 하고 \\"I will.\\"이라고 하세요.","핵심 단어: thanks, I will"]', 'maya', 'Great. Go find Derek. He sits by the window.', '좋아요. 데릭을 찾아가 봐요. 창가에 앉아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_standup', 1, 'priya', 'Six people stand around a screen in the meeting room. Priya, the product manager, is running the meeting.', '회의실 화면 앞에 여섯 명이 서 있습니다. 프로덕트 매니저 프리야가 회의를 진행합니다.', 'Okay, let''s get started. Oh, we have someone new! Want to say a quick hello?', '자, 시작할게요. 어, 새로운 분이 있네요! 간단히 인사할래요?', 'Everyone is looking at you. Keep it short and friendly.', '모두가 당신을 보고 있습니다. 짧고 친근하게 인사하세요.', '[{"all":["developer"]},{"all":["joined"]},{"all":["new"],"any":["team","here","join"]},{"all":["first day"]}]', 'Hi, everyone. I''m Jun. I just joined as a developer. Excited to be here!', '안녕하세요, 여러분. 준이에요. 개발자로 막 합류했어요. 함께하게 돼서 기뻐요!', '["Hey, all. Jun here. I''m the new product manager, so nice to meet you.","Hi. I''m Jun. Before we start, can I ask a few questions about the project?","Hello. My name is Jun. I am a developer. That is all for now."]', '["안녕하세요, 여러분. 준이에요. 새로 온 프로덕트 매니저예요. 반가워요.","안녕하세요. 준이에요. 시작하기 전에 프로젝트에 대해 몇 가지 물어봐도 될까요?","안녕하십니까. 이름은 준입니다. 개발자입니다. 이상입니다."]', '["Ha, I think that''s me! You''re our new developer, right?","Let''s save those for after standup, okay?","Okay! Um, welcome, Jun."]', '["하하, 그건 저 같은데요! 새로 온 개발자죠?","그건 스탠드업 끝나고 물어봐요, 알았죠?","네! 어, 환영해요, 준."]', '["Say your name and your role, and that you just joined.","Key words: just joined, developer"]', '["이름과 역할, 막 합류했다는 것을 말하세요.","핵심 단어: just joined, developer"]', 'priya', 'Welcome! We''re so happy to have you.', '환영해요! 와 줘서 정말 기뻐요.'),
  ('d1_standup', 2, 'priya', 'Everyone else has already said what they did yesterday. Now it is your turn.', '다른 사람들은 어제 한 일을 이미 말했습니다. 이제 당신 차례입니다.', 'The format is yesterday, today, and blockers. Since it''s your first day, just tell us: what''s on your plate today?', '형식은 어제, 오늘, 블로커예요. 첫날이니까 그냥 말해 줘요. 오늘 할 일이 뭐예요?', 'Tell the team what you''ll spend today on. You just got your new laptop.', '오늘 무엇을 할지 팀에 말하세요. 새 노트북을 막 받았습니다.', '[{"any":["setting up","set up","setup","install","installing"]}]', 'Today I''m setting up my laptop and my dev environment.', '오늘은 노트북이랑 개발 환경을 세팅해요.', '["Yesterday I finished my HR paperwork, so nothing new.","Today I''m going to fix a few bugs and ship a feature.","Today I''m just waiting for IT to set up my email."]', '["어제 인사팀 서류를 다 끝내서 새로운 건 없어요.","오늘은 버그 몇 개 고치고 기능 하나 출시할 거예요.","오늘은 그냥 IT팀이 이메일 만들어 주길 기다려요."]', '["Sure, but what about today?","Whoa, ambitious! Maybe start with your laptop?","Oh, I think your email''s already set up. Check?"]', '["좋아요, 근데 오늘은요?","와, 의욕 넘치네요! 노트북부터 시작하는 게 어때요?","어, 이메일은 이미 설정됐을 거예요. 확인해 볼래요?"]', '["Start with \\"Today I''m …ing\\".","Key words: today, setting up"]', '["\\"Today I''m …ing\\"로 시작하세요.","핵심 단어: today, setting up"]', 'priya', 'Perfect. That''s exactly what day one should look like.', '좋아요. 첫날은 딱 그래야죠.'),
  ('d1_standup', 3, 'priya', 'Priya looks at you over her laptop.', '프리야가 노트북 너머로 당신을 봅니다.', 'Any blockers?', '블로커 있어요?', 'Mention the one thing that''s still stopping you from working on the code.', '아직 코드 작업을 못 하게 막고 있는 한 가지를 말하세요.', '[{"all":["access"]},{"any":["permission","permissions"]},{"all":["waiting","repo"]}]', 'Just one. I don''t have access to the repository yet.', '하나 있어요. 아직 저장소 접근 권한이 없어요.', '["Nope, none. Everything''s going great so far!","Yeah. Derek still hasn''t given me access to the repo.","Just one. I still don''t have my laptop from IT."]', '["아뇨, 없어요. 지금까지 다 순조로워요!","네. 데릭이 아직 저장소 권한을 안 줬어요.","하나 있어요. 아직 IT팀한테 노트북을 못 받았어요."]', '["Love that! So you''re all set up already?","Oh, it''s only ten. Give him a chance!","Really? I thought Maya handed you one this morning."]', '["좋네요! 그럼 세팅은 벌써 다 된 거예요?","아, 아직 열 시예요. 기회는 줘야죠!","정말요? 아침에 마야가 하나 줬다고 들었는데요."]', '["Say what you do not have yet.","Key words: access, yet"]', '["아직 무엇이 없는지 말하세요.","핵심 단어: access, yet"]', 'priya', 'Derek, can you help with that after standup? … Great, he says yes.', '데릭, 스탠드업 끝나고 그거 도와줄 수 있어요? … 좋아요, 된대요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d1_standup', 4, 'priya', 'The meeting took twelve minutes. People start to leave.', '회의는 12분 걸렸습니다. 사람들이 나가기 시작합니다.', 'That''s it for today. Short and sweet. Thanks, everyone!', '오늘은 여기까지예요. 짧고 굵게. 다들 고마워요!', 'The meeting started at ten. Ask Priya whether that''s the daily schedule.', '회의는 열 시에 시작했습니다. 매일 이 시간인지 프리야에게 물어보세요.', '[{"all":["every day"]},{"all":["everyday"]},{"all":["every","morning"]},{"all":["daily"]}]', 'Thanks! Is standup every day at ten?', '고마워요! 스탠드업은 매일 열 시예요?', '["Thanks! Is standup every day at nine?","Thanks! Do I have to come every day?","Thanks! Was that a long one today?"]', '["고마워요! 스탠드업은 매일 아홉 시예요?","고마워요! 저도 매일 와야 해요?","고마워요! 오늘은 긴 편이었나요?"]', '["Ten, actually. Nine''s way too early for us!","Um, yes. That''s kind of the point.","Long? That was twelve minutes!"]', '["열 시예요. 아홉 시는 너무 이르죠!","음, 네. 원래 그런 거예요.","길었다고요? 12분 했는데요!"]', '["Ask with \\"Is standup every …?\\"","Key words: every day, ten"]', '["\\"Is standup every …?\\"로 물어보세요.","핵심 단어: every day, ten"]', 'priya', 'Every weekday at ten, fifteen minutes max. See you tomorrow!', '평일 매일 열 시, 길어야 15분이에요. 내일 봐요!'),
  ('d10_approval', 1, 'maya', 'You need Maya''s sign-off before you answer Greg.', '그렉에게 답하기 전에 마야의 승인이 필요합니다.', 'How''d the call with Greg go?', '그렉이랑 통화는 어떻게 됐어요?', 'Report on the call, including what Greg asked for.', '통화 결과를 보고하세요. 그렉이 무엇을 요청했는지도요.', '[{"all":["discount"]},{"all":["165"]},{"all":["sixty five"]},{"all":["lower","price"]}]', 'It went well, but he asked for a discount. He wants to bring it down to one sixty-five.', '잘 됐는데, 할인을 요청했어요. 16만 5천으로 낮추고 싶어 해요.', '["It went well, but he asked for a discount. He wants to bring it down to one fifty.","It went well. He asked for one sixty-five, and I told him that should be totally fine.","It went great. He''s happy with the price, and we agreed on Net 45."]', '["잘 됐는데, 할인을 요청했어요. 15만으로 낮추고 싶어 해요.","잘 됐어요. 16만 5천을 요청해서, 그 정도면 전혀 문제없을 거라고 했어요.","아주 잘 됐어요. 가격에 만족하고, Net 45로 합의했어요."]', '["One fifty? That''s a big cut. Is that really his final ask?","You told him what? You can''t promise that without me.","Great. So no pushback on price at all? Really?"]', '["15만요? 많이 깎네요. 그게 정말 최종 요청이에요?","뭐라고 했다고요? 나 없이 그런 약속을 하면 안 돼요.","좋네요. 가격엔 아무 말도 없었어요? 정말요?"]', '["Report the client''s request.","Key words: discount, one sixty-five"]', '["고객의 요청을 보고하세요.","핵심 단어: discount, one sixty-five"]', 'maya', 'Figured. That''s about eight percent. What do you think we should do?', '그럴 줄 알았어요. 8% 정도네요. 어떻게 하면 좋겠어요?'),
  ('d10_approval', 2, 'maya', 'You think a smaller discount could work if Summit commits to more.', '서밋이 더 약속한다면 작은 할인은 괜찮다고 생각합니다.', 'I want to hear your take first.', '당신 생각을 먼저 듣고 싶어요.', 'Propose your idea: a 5% discount, but only if Summit signs a one-year support contract.', '당신의 생각을 제안하세요. 서밋이 1년 지원 계약을 맺는 조건으로 5% 할인입니다.', '[{"all":["support"],"any":["year","contract","commit"]},{"all":["in exchange"]},{"all":["if they"],"any":["sign","commit","agree"]}]', 'What if we offer five percent off in exchange for a one-year support contract?', '1년 지원 계약을 맺는 조건으로 5퍼센트 할인해 주면 어떨까요?', '["What if we just give him the full eight percent so we don''t risk losing the deal?","What if we offer five percent off in exchange for paying Net 30 instead?","I''m not sure. You''ve done more of these. What would you normally do?"]', '["계약을 놓칠 위험이 없게 그냥 8퍼센트 다 깎아 주면 어떨까요?","대신 Net 30으로 지급하는 조건으로 5퍼센트 할인해 주면 어떨까요?","잘 모르겠어요. 이런 건 더 많이 해 보셨잖아요. 보통 어떻게 해요?"]', '["And get nothing in return? I don''t love that.","We already settled on Net 45. Why reopen that?","I asked first. Come on, what does your gut say?"]', '["아무것도 안 받고요? 그건 별로예요.","Net 45로 이미 정했잖아요. 그걸 왜 다시 꺼내요?","내가 먼저 물었잖아요. 자, 당신 직감은 어때요?"]', '["Give something only if you get something back.","Key words: in exchange for, one-year support contract"]', '["무언가를 받는 조건으로만 양보하세요.","핵심 단어: in exchange for, one-year support contract"]', 'maya', 'I like that. It keeps the relationship going. Five percent is my limit, though.', '좋네요. 관계도 계속 이어지고요. 그래도 5%가 한계예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d10_approval', 3, 'maya', 'Maya wants the final wording checked before anything is sent.', '마야는 무엇을 보내기 전에 최종 문구를 검토받길 원합니다.', 'And don''t put anything in writing until legal reviews it, okay?', '그리고 법무팀이 검토하기 전엔 아무것도 서면으로 보내지 마요, 알겠죠?', 'Repeat back the two rules Maya just set, so she knows you''ve got them.', '마야가 정한 두 가지 원칙을 다시 말해 확인하세요.', '[{"all":["five percent"]},{"all":["5"]},{"all":["legal"],"any":["review","reviews","signs off","sign off","writing","approves"]}]', 'Got it. Five percent max, and nothing in writing until legal signs off.', '알겠어요. 최대 5퍼센트, 그리고 법무팀 승인 전엔 서면으로 아무것도 안 보낼게요.', '["Got it. Eight percent max, and nothing in writing until legal signs off.","Got it. I''ll just text Greg the five percent offer tonight so he knows.","Sure, but can''t I just send a quick email? Legal takes forever."]', '["알겠어요. 최대 8퍼센트, 그리고 법무팀 승인 전엔 서면으로 아무것도 안 보낼게요.","알겠어요. 그렉이 알 수 있게 오늘 밤 5퍼센트 제안을 문자로 보낼게요.","네, 근데 간단한 메일 정도는 괜찮지 않아요? 법무팀은 너무 오래 걸려서요."]', '["Five, not eight. That''s my limit.","A text counts as writing. Hold off until legal sees it.","I know it''s slow. But no, not this time."]', '["8이 아니라 5예요. 그게 내 한계예요.","문자도 서면이에요. 법무팀이 볼 때까지 기다려요.","느린 건 알아요. 그래도 이번엔 안 돼요."]', '["Repeat the limit and the condition.","Key words: five percent max, legal signs off"]', '["한도와 조건을 다시 말하세요.","핵심 단어: five percent max, legal signs off"]', 'maya', 'Perfect. You''re a natural at this. Go get ''em in Ridgeport.', '완벽해요. 이런 데 타고났네요. 리지포트에서 잘하고 와요.'),
  ('d10_contract_terms', 1, 'greg', 'Priya shares the proposal on screen: $180,000 for phase one, payment Net 30.', '프리야가 제안서를 화면에 띄웁니다. 1단계 18만 달러, 지급 조건 Net 30.', 'Okay, I''ve looked at the numbers. Honestly, one eighty is a bit outside our budget. We were thinking closer to one fifty.', '자, 숫자는 봤어요. 솔직히 18만은 예산을 좀 넘어요. 우린 15만 정도를 생각하고 있었어요.', 'Acknowledge his budget worry, but remind him the price also covers three months of support after launch.', '예산 걱정은 이해한다고 하되, 이 가격에 출시 후 3개월 지원이 포함된다는 걸 상기시키세요.', '[{"any":["includes","include","included"]},{"all":["understand"],"any":["price","budget","support"]},{"all":["covers"]}]', 'I understand. Keep in mind the price includes three months of support after launch.', '이해합니다. 다만 이 가격에는 출시 후 3개월 지원이 포함되어 있다는 점을 기억해 주세요.', '["I understand. If one fifty is your budget, I''m sure we can make that work.","I understand. Keep in mind the price includes a full year of support after launch.","Honestly, one eighty is already a great price. You won''t find anything cheaper."]', '["이해합니다. 예산이 15만이라면 저희가 맞춰 드릴 수 있을 거예요.","이해합니다. 다만 이 가격에는 출시 후 1년 지원이 포함되어 있다는 점을 기억해 주세요.","솔직히 18만이면 이미 아주 좋은 가격이에요. 이보다 싼 데는 없을 거예요."]', '["Really? Great. Priya, you''re good with that?","A full year? That''s not what I see in the proposal.","Maybe, but I still have to answer to my CFO."]', '["정말요? 좋네요. 프리야, 괜찮은 거죠?","1년요? 제안서엔 그렇게 안 나와 있는데요.","그럴지도요. 그래도 전 CFO한테 설명해야 해요."]', '["Explain the value before you talk about the number.","Key words: I understand, the price includes, support"]', '["숫자를 말하기 전에 가치를 설명하세요.","핵심 단어: I understand, the price includes, support"]', 'greg', 'That helps. But I still need to get the number down. Can you meet us halfway? Say, one sixty-five?', '도움이 되네요. 그래도 금액을 낮춰야 해요. 중간에서 만날 수 있을까요? 16만 5천 정도?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d10_contract_terms', 2, 'greg', 'You are not allowed to approve discounts on your own.', '당신은 혼자서 할인을 승인할 권한이 없습니다.', 'So, one sixty-five. Can we shake on that?', '그럼 16만 5천. 이걸로 악수할까요?', 'Discounts aren''t your call. Don''t say yes; tell him what you''ll do instead.', '할인은 당신이 결정할 일이 아닙니다. 승낙하지 말고, 대신 어떻게 할지 말하세요.', '[{"all":["run it by"]},{"all":["manager"],"any":["check","ask","talk","run","discuss"]},{"all":["get back","you"]}]', 'I can''t approve that on my own, but let me run it by my manager and get back to you.', '제 선에서 승인할 수는 없지만, 매니저에게 확인하고 다시 연락드릴게요.', '["Sure, one sixty-five works for us. Let''s shake on it and move on to the next item.","One sixty-five is too low. My manager would never agree to that.","I can''t say yes to that, but let me ask Priya after the call and get back to you."]', '["좋아요, 16만 5천이면 됩니다. 악수하고 다음 항목으로 넘어가죠.","16만 5천은 너무 낮아요. 저희 매니저는 절대 동의 안 할 거예요.","그건 제가 승낙할 수 없지만, 통화 끝나고 프리야에게 물어보고 다시 연락드릴게요."]', '["Great! Glad we sorted that out. Priya, you heard it.","Never? Then we''re stuck. Can you at least ask?","Priya''s sitting right next to you. Priya?"]', '["좋아요! 해결돼서 다행이네요. 프리야, 들었죠?","절대요? 그럼 막혔네요. 물어보기라도 해 줄래요?","프리야가 바로 옆에 있잖아요. 프리야?"]', '["Don''t say yes or no. Buy time.","Key words: run it by my manager, get back to you"]', '["예나 아니요로 답하지 말고 시간을 버세요.","핵심 단어: run it by my manager, get back to you"]', 'greg', 'Fair enough. While you''re at it, let''s talk payment terms.', '그러죠. 그 김에 지급 조건도 얘기합시다.'),
  ('d10_contract_terms', 3, 'greg', 'Greg wants to pay 60 days after each invoice instead of 30.', '그렉은 송장마다 30일이 아니라 60일 뒤에 지급하길 원합니다.', 'Our standard is Net 60. Net 30 is tough for our finance team.', '우리 기준은 Net 60이에요. Net 30은 재무팀이 힘들어해요.', 'Your standard is thirty days and his is sixty. Offer a compromise.', '당신 쪽 기준은 30일, 그쪽은 60일입니다. 타협안을 내세요.', '[{"any":["45","forty five","fortyfive"]}]', 'How about we meet in the middle at Net 45?', '중간에서 Net 45로 맞추면 어떨까요?', '["Net 60 works for us, no problem at all.","Sorry, Net 30 is final. We can''t budge on that.","How about we meet in the middle at Net 90?"]', '["Net 60이면 저희는 전혀 문제없어요.","죄송하지만 Net 30이 최종이에요. 그건 못 바꿔요.","중간에서 Net 90으로 맞추면 어떨까요?"]', '["Oh, great. That was easier than I thought.","That''s a tough position. I''ll have to take it upstairs.","Ninety? That''s not the middle. I''d take it, though!"]', '["오, 좋네요. 생각보다 쉬웠네요.","강경하시네요. 윗선에 올려 봐야겠어요.","90일요? 그건 중간이 아니잖아요. 저야 좋지만요!"]', '["Offer the number halfway between 30 and 60.","Key words: meet in the middle, Net 45"]', '["30과 60의 중간 숫자를 제안하세요.","핵심 단어: meet in the middle, Net 45"]', 'greg', 'Net 45… I can live with that.', 'Net 45라… 그 정도면 받아들일 수 있어요.'),
  ('d10_contract_terms', 4, 'greg', 'Next is the service level agreement, the SLA.', '다음은 서비스 수준 협약(SLA)입니다.', 'Last thing: uptime. We need a guarantee. What can you commit to?', '마지막으로 가동률이요. 보장이 필요해요. 어디까지 약속할 수 있어요?', 'Offer your team''s standard: 99.9% uptime, with critical issues answered within four hours.', '팀의 기준을 제시하세요. 가동률 99.9%, 심각한 장애는 4시간 안에 대응.', '[{"all":["99"]},{"all":["uptime"],"any":["percent","guarantee","commit"]},{"all":["four hour"]},{"all":["4 hour"]},{"all":["response time"]}]', 'We can commit to 99.9 percent uptime and a four-hour response time for critical issues.', '가동률 99.9퍼센트, 그리고 심각한 장애에는 4시간 내 대응을 약속드릴 수 있습니다.', '["We can guarantee 100 percent uptime, and we''ll fix any critical issue within an hour.","We can commit to 99 percent uptime and a four-day response time for critical issues.","Uptime depends on a lot of things. We''d rather not put a number in the contract."]', '["가동률 100퍼센트를 보장하고, 심각한 장애는 한 시간 안에 고쳐 드릴게요.","가동률 99퍼센트, 그리고 심각한 장애에는 4일 내 대응을 약속드릴 수 있습니다.","가동률은 여러 요인에 달려 있어서요. 계약서에 숫자는 안 넣었으면 해요."]', '["A hundred percent? Nobody can promise that. Let''s be realistic.","Four days? My stores can''t be in the dark for four days.","Then we have a problem. Legal won''t sign without a number."]', '["100퍼센트요? 그건 아무도 약속 못 해요. 현실적으로 가죠.","4일요? 우리 매장들이 4일이나 깜깜이일 순 없어요.","그럼 문제네요. 법무팀은 숫자 없인 서명 안 해요."]', '["Give a clear number for uptime and response time.","Key words: 99.9 percent uptime, four-hour response time"]', '["가동률과 대응 시간을 분명한 숫자로 말하세요.","핵심 단어: 99.9 percent uptime, four-hour response time"]', 'greg', 'That''s reasonable. Send me the revised terms and I''ll share them with legal.', '합리적이네요. 수정된 조건을 보내 주면 법무팀과 공유할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d10_contract_terms', 5, 'priya', 'Priya nods at you to close the call.', '프리야가 통화를 마무리하라고 고개를 끄덕입니다.', 'Nice job. Want to wrap up?', '잘했어요. 마무리할래요?', 'Close the call by recapping your next steps. You can get the revised terms to him today.', '다음에 할 일을 정리하며 통화를 마무리하세요. 수정된 조건은 오늘 중으로 보낼 수 있습니다.', '[{"all":["end of day"]},{"all":["revised"],"any":["terms","contract","send"]},{"all":["get back"]},{"all":["eod"]}]', 'Great. I''ll check the price with my manager and send you the revised terms by end of day.', '좋습니다. 가격은 매니저에게 확인하고, 수정된 조건은 오늘 업무 끝나기 전에 보내 드릴게요.', '["Great. So we''re at one sixty-five, and I''ll send you the revised terms by end of day.","Great. I''ll check the price with my manager and send the revised terms next week.","Great. Could you send us your revised terms, and we''ll take a look at them?"]', '["좋습니다. 그럼 16만 5천으로 하고, 수정된 조건은 오늘 업무 끝나기 전에 보내 드릴게요.","좋습니다. 가격은 매니저에게 확인하고, 수정된 조건은 다음 주에 보내 드릴게요.","좋습니다. 그쪽에서 수정된 조건을 보내 주시면 저희가 검토할게요."]', '["Oh, so one sixty-five is approved? I thought you had to check.","Next week? I was hoping to get this to legal sooner.","Me? I thought your side was revising them."]', '["어, 16만 5천이 승인된 거예요? 확인해야 한다면서요.","다음 주요? 법무팀에 더 빨리 넘기고 싶었는데요.","제가요? 그쪽에서 수정하는 줄 알았는데요."]', '["List the next steps and a deadline.","Key words: revised terms, end of day"]', '["다음 단계와 기한을 말하세요.","핵심 단어: revised terms, end of day"]', 'greg', 'Sounds good. Talk soon.', '좋아요. 또 얘기해요.'),
  ('d10_handoff', 1, 'derek', 'Your flight is tomorrow morning. You stop by Derek''s desk.', '비행기는 내일 아침입니다. 데릭 자리에 들릅니다.', 'So you''re off to Ridgeport, huh? What do you need from me?', '리지포트 간다면서요? 나한테 필요한 게 뭐예요?', 'You''ll be gone two days. Ask Derek to look after your main project while you''re out.', '이틀 동안 자리를 비웁니다. 그동안 당신이 맡은 주 업무를 데릭에게 부탁하세요.', '[{"all":["cover"]},{"all":["keep an eye"]},{"all":["take over"]},{"all":["while"],"any":["away","gone","out"]}]', 'Could you cover for me on the inventory API while I''m away?', '출장 가 있는 동안 재고 API 좀 대신 봐 줄 수 있어요?', '["Could you cover for me on the login page while I''m away?","Can you just finish the inventory API for me while I''m gone?","Could you cover for me next week while I''m in Ridgeport?"]', '["출장 가 있는 동안 로그인 페이지 좀 대신 봐 줄 수 있어요?","저 없는 동안 재고 API 그냥 마무리해 줄 수 있어요?","다음 주에 리지포트에 가 있는 동안 대신 봐 줄 수 있어요?"]', '["The login page? Isn''t that done already?","Finish it? I''ve got my own stuff. I can watch it, though.","Next week? I thought you were flying out tomorrow."]', '["로그인 페이지요? 그거 이미 끝나지 않았어요?","마무리요? 나도 내 일이 있어요. 지켜봐 줄 수는 있지만.","다음 주요? 내일 출발하는 줄 알았는데요."]', '["Ask him to handle your work for two days.","Key words: cover for me, while I''m away"]', '["이틀 동안 일을 맡아 달라고 하세요.","핵심 단어: cover for me, while I''m away"]', 'derek', 'Sure thing. Where are things at right now?', '물론이죠. 지금 어디까지 됐어요?'),
  ('d10_handoff', 2, 'derek', 'The API is merged, but some store IDs come back empty.', 'API는 병합됐지만 일부 매장 ID가 빈 값으로 옵니다.', 'Where are things at?', '지금 어디까지 됐어요?', 'Give him the honest status, including the problem that''s still open.', '남은 문제까지 포함해 솔직하게 현황을 알려 주세요.', '[{"all":["bug"]},{"all":["merged"]},{"all":["open","issue"]}]', 'The code is merged, but there''s one open bug. Some store IDs come back empty.', '코드는 머지됐는데, 버그가 하나 남아 있어요. 일부 매장 ID가 빈 값으로 와요.', '["It''s all merged and working. Nothing to worry about while I''m gone.","The code is still in review, and there''s one bug. Some store IDs come back empty.","It''s merged, but there''s a bug in there somewhere. You''ll figure it out, I''m sure."]', '["다 머지됐고 잘 돌아가요. 저 없는 동안 걱정할 거 없어요.","코드는 아직 리뷰 중이고, 버그가 하나 있어요. 일부 매장 ID가 빈 값으로 와요.","머지는 됐는데, 어딘가에 버그가 있어요. 당신이라면 알아낼 거예요."]', '["Nothing? Then why do you need me covering?","Still in review? I''m pretty sure it got merged.","Somewhere? I''m going to need more than that."]', '["아무것도요? 그럼 왜 나한테 봐 달라고 해요?","아직 리뷰 중이요? 머지된 걸로 아는데요.","어딘가요? 그것보단 더 알려 줘야죠."]', '["Say what is done and what is still open.","Key words: merged, one open bug"]', '["끝난 것과 남은 것을 말하세요.","핵심 단어: merged, one open bug"]', 'derek', 'Okay, I''ll keep an eye on it. Did you write it up anywhere?', '알겠어요, 지켜볼게요. 어디 정리해 뒀어요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d10_handoff', 3, 'derek', 'You documented everything in the ticket.', '모든 걸 티켓에 적어 두었습니다.', 'Did you write it up anywhere?', '어디 정리해 뒀어요?', 'Tell him where your notes are, and how he can reach you on the road.', '메모를 어디 남겼는지, 출장 중에 어떻게 연락할 수 있는지 말하세요.', '[{"all":["ticket"]},{"all":["reachable"]},{"all":["comes up"]},{"all":["chat"]},{"all":["message","me"]}]', 'Yeah, it''s all in the ticket. And I''ll be reachable on chat if anything comes up.', '네, 전부 티켓에 있어요. 그리고 무슨 일 생기면 채팅으로 연락돼요.', '["Not really, but I can walk you through all of it over the phone from Ridgeport tonight.","Yeah, it''s all in the ticket. But please don''t contact me while I''m traveling.","It''s all in the ticket. Can you also update Priya and Maya on it every day?"]', '["딱히요. 대신 오늘 밤 리지포트에서 전화로 다 설명해 줄게요.","네, 전부 티켓에 있어요. 근데 출장 중엔 연락하지 말아 주세요.","전부 티켓에 있어요. 프리야랑 마야한테 매일 진행 상황도 알려 줄래요?"]', '["Over the phone? Write it down, man. You''ll be in meetings.","Uh, okay. Hopefully nothing breaks, then.","Every day? I''m covering, not being your assistant."]', '["전화로요? 글로 남겨요. 회의 중일 거잖아요.","어, 알겠어요. 그럼 아무것도 안 깨지길 빌어야겠네요.","매일요? 대신 봐 주는 거지 비서가 아니에요."]', '["Say where the notes are and how to reach you.","Key words: in the ticket, reachable, if anything comes up"]', '["메모가 어디 있고 어떻게 연락할 수 있는지 말하세요.","핵심 단어: in the ticket, reachable, if anything comes up"]', 'derek', 'Perfect. Safe travels, and don''t let Greg push you around.', '완벽해요. 잘 다녀오고, 그렉한테 휘둘리지 마요.'),
  ('d11_checkin', 1, 'amy', 'You arrive at the Crestline Air counter with a backpack and a small suitcase.', '배낭과 작은 여행 가방을 들고 크레스트라인 항공 카운터에 도착합니다.', 'Good morning! Where are you flying today?', '안녕하세요! 오늘 어디로 가세요?', 'Tell her where you''re headed and which flight you''re on.', '어디로 가는지, 몇 시 비행기인지 말하세요.', '[{"all":["ridgeport"]},{"all":["nine thirty"]},{"all":["9 30"]},{"all":["930"]}]', 'Good morning. I''m flying to Ridgeport on the nine-thirty flight.', '안녕하세요. 9시 30분 비행기로 리지포트에 가요.', '["Good morning. I''m flying to Ridgeport on the ten-thirty flight.","Good morning. I''m flying back from Ridgeport on Friday afternoon.","Morning. Ridgeport. Just print my boarding pass, please. I''m in a hurry."]', '["안녕하세요. 10시 30분 비행기로 리지포트에 가요.","안녕하세요. 금요일 오후에 리지포트에서 돌아와요.","네. 리지포트요. 탑승권만 뽑아 주세요. 급해요."]', '["I don''t have a ten-thirty to Ridgeport. Can you check your itinerary?","That''s your return. Which flight are you on today?","I''ll be quick. I just need a few things from you first."]', '["리지포트행 10시 30분 편은 없는데요. 일정표 확인해 보시겠어요?","그건 돌아오는 편이고요. 오늘은 어느 편 타세요?","빨리 해 드릴게요. 먼저 몇 가지만 필요해요."]', '["Say where you are going and when.","Key words: flying to Ridgeport, nine-thirty"]', '["어디로, 몇 시에 가는지 말하세요.","핵심 단어: flying to Ridgeport, nine-thirty"]', 'amy', 'Great. Can I see a photo ID, please? And are you checking any bags today?', '좋아요. 사진 있는 신분증 보여 주시겠어요? 오늘 부칠 짐 있으세요?'),
  ('d11_checkin', 2, 'amy', 'Your suitcase is too big for the overhead bin. The backpack has your laptop.', '여행 가방은 기내 선반에 들어가기엔 큽니다. 배낭에는 노트북이 있습니다.', 'Photo ID, please. Any bags to check?', '사진 있는 신분증 주세요. 부칠 짐 있으세요?', 'Hand over your ID. The suitcase goes under the plane; the backpack stays with you.', '신분증을 건네세요. 여행 가방은 부치고, 배낭은 들고 탑니다.', '[{"all":["one bag"]},{"all":["check","one"]},{"all":["checking","one"]},{"all":["one","suitcase"]},{"all":["carry on"]}]', 'Here''s my driver''s license. I''m checking one bag, and the backpack is my carry-on.', '여기 운전면허증이요. 가방 하나 부치고, 배낭은 기내에 들고 탈게요.', '["Here''s my driver''s license. I''m checking both bags, the suitcase and the backpack.","Here''s my license. No bags to check. I''ll just carry the suitcase on.","Do I really need to show ID for this? It''s only a short domestic flight."]', '["여기 운전면허증이요. 여행 가방이랑 배낭 둘 다 부칠게요.","여기 면허증이요. 부칠 짐은 없어요. 여행 가방은 그냥 들고 탈게요.","이것도 신분증을 꼭 보여 줘야 해요? 짧은 국내선인데요."]', '["Sure. Any electronics in the backpack? Those have to stay with you.","That suitcase looks too big for the overhead bin, I''m afraid.","Yes, everyone needs a photo ID to fly. Sorry!"]', '["네. 배낭에 전자 기기 있으세요? 그건 들고 타셔야 해요.","그 가방은 기내 선반에 들어가기엔 너무 커 보여요.","네, 비행기 타려면 누구나 사진 신분증이 필요해요. 죄송해요!"]', '["Say how many bags you are checking.","Key words: checking one bag, carry-on"]', '["부칠 가방이 몇 개인지 말하세요.","핵심 단어: checking one bag, carry-on"]', 'amy', 'Perfect. The first checked bag is thirty-five dollars. How would you like to pay?', '좋아요. 첫 번째 위탁 수하물은 35달러예요. 어떻게 결제하시겠어요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_checkin', 3, 'amy', 'Tom said the bag fee is reimbursable.', '톰이 수하물 요금은 환급된다고 했습니다.', 'That''s thirty-five for the bag. Card or cash?', '수하물은 35달러예요. 카드로 하세요, 현금으로 하세요?', 'Pay with the card work gave you, and make sure you''ll have proof for your expense report.', '회사에서 받은 카드로 결제하고, 경비 보고용 증빙을 꼭 챙기세요.', '[{"all":["receipt"]},{"all":["company card"]},{"all":["corporate card"]}]', 'I''ll put it on my company card. Could I get a receipt, please?', '법인 카드로 할게요. 영수증 받을 수 있을까요?', '["Cash is fine. I don''t really need a receipt for this, thanks.","Thirty-five? Can''t you waive it? It''s for a business trip.","I''ll put it on my company card. It was twenty-five, right?"]', '["현금으로 할게요. 이건 영수증 필요 없어요, 고마워요.","35달러요? 면제해 주면 안 돼요? 출장인데요.","법인 카드로 할게요. 25달러 맞죠?"]', '["Okay. Just so you know, I can''t reprint it later.","Sorry, everyone pays the bag fee. Card or cash?","It''s thirty-five for the first checked bag."]', '["알겠어요. 참고로 나중에 다시 뽑아 드릴 수는 없어요.","죄송해요, 수하물 요금은 다 내셔야 해요. 카드요, 현금요?","첫 번째 위탁 수하물은 35달러예요."]', '["Pay, and remember your expense report.","Key words: company card, receipt"]', '["결제하고, 경비 정산을 기억하세요.","핵심 단어: company card, receipt"]', 'amy', 'Of course. The receipt will be in your email. You''re in seat 14C, on the aisle.', '그럼요. 영수증은 이메일로 갈 거예요. 좌석은 14C, 통로석이에요.'),
  ('d11_checkin', 4, 'amy', 'Amy prints your boarding pass.', '에이미가 탑승권을 출력합니다.', 'You''re in boarding group three. Boarding starts at eight-fifty at gate B12. Anything else?', '탑승 그룹은 3번이에요. 탑승은 8시 50분, B12 게이트에서 시작해요. 더 필요한 거 있으세요?', 'Before you go, check whether there''s any delay.', '가기 전에 지연은 없는지 확인하세요.', '[{"all":["on time"]},{"all":["delayed"]},{"all":["delay"]},{"all":["on schedule"]}]', 'Thanks. Is the flight on time?', '고마워요. 비행기 제시간에 떠요?', '["Thanks. So boarding is at nine-fifty?","Thanks. Is gate B21 far from here?","Can you make sure it leaves on time?"]', '["고마워요. 그럼 탑승이 9시 50분이죠?","고마워요. B21 게이트는 여기서 멀어요?","꼭 제시간에 뜨게 해 주실 수 있어요?"]', '["Eight-fifty. The flight leaves at nine-thirty.","B12, not B21. It''s just past security.","Ha, I wish I could. I don''t fly the plane."]', '["8시 50분이요. 비행기는 9시 30분에 떠요.","B21 말고 B12예요. 보안 검색대 지나면 바로예요.","하, 저도 그러고 싶네요. 제가 조종하는 건 아니라서요."]', '["Ask about delays.","Key words: on time"]', '["지연 여부를 물어보세요.","핵심 단어: on time"]', 'amy', 'As of now, yes. Keep an eye on the screens, though. Have a nice flight!', '현재로서는 네. 그래도 전광판을 잘 보세요. 즐거운 비행 되세요!'),
  ('d11_client_visit', 1, 'greg', 'You sign in as a visitor in Summit Retail''s lobby and get a guest badge. Greg meets you in the conference room.', '서밋 리테일 로비에서 방문자로 등록하고 방문증을 받습니다. 그렉이 회의실에서 맞이합니다.', 'Hey, you made it! Welcome to Ridgeport. How was the flight?', '어, 왔네요! 리지포트에 온 걸 환영해요. 비행은 어땠어요?', 'Tell him how the trip went. There was one small hiccup.', '오는 길이 어땠는지 말하세요. 작은 문제가 하나 있었어요.', '[{"all":["delay"]},{"all":["delayed"]},{"all":["fine"]},{"all":["smooth"]},{"all":["not bad"]}]', 'Not bad, thanks! Just a short delay, but I made it.', '나쁘지 않았어요, 고마워요! 조금 지연됐지만 잘 도착했어요.', '["Awful. Your local airline made us wait forever.","Smooth, thanks! Right on time, not a single delay.","Fine, thanks. Should we start with the pricing?"]', '["최악이었어요. 여기 항공사 때문에 한참 기다렸어요.","순조로웠어요, 고마워요! 딱 제시간에, 지연 하나 없이요.","괜찮았어요, 고마워요. 그럼 가격 얘기부터 할까요?"]', '["Oof, sorry to hear that. Not the best start.","Nice! Crestline on time? That''s a first.","Whoa, straight to business! Sit down first, relax."]', '["어휴, 안됐네요. 시작이 좋진 않았네요.","좋네요! 크레스트라인이 제시간에요? 처음 듣네요.","워, 바로 본론이네요! 일단 앉아서 좀 쉬어요."]', '["Answer the small-talk question briefly.","Key words: not bad, short delay"]', '["가벼운 질문에 짧게 답하세요.","핵심 단어: not bad, short delay"]', 'greg', 'Glad to hear it. Can I get you anything before we dive in? Coffee, water?', '다행이네요. 본론 들어가기 전에 뭐 드릴까요? 커피, 물?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_client_visit', 2, 'greg', 'There is a pot of coffee and some bottled water on the table.', '테이블에 커피 한 주전자와 생수가 있습니다.', 'Coffee, water?', '커피, 물?', 'Accept something to drink.', '마실 것을 받으세요.', '[{"any":["water","coffee"]}]', 'Water would be great, thanks.', '물 주시면 좋겠어요, 고마워요.', '["No. Let''s just get this over with.","Could I get an iced latte instead?","I''m good. I had three on the plane."]', '["아뇨. 그냥 빨리 끝내죠.","대신 아이스 라테 주실 수 있어요?","괜찮아요. 비행기에서 세 잔 마셨어요."]', '["Uh, sure. Let''s get to it, then.","Ha, we''re not a café. Coffee or water?","Ha, okay. Let me know if you change your mind."]', '["어, 그러죠. 그럼 시작합시다.","하, 여기 카페가 아니라서요. 커피, 물 중에서요?","하, 알겠어요. 생각 바뀌면 말해요."]', '["Choose a drink and say thanks.","Key words: water would be great"]', '["음료를 고르고 고맙다고 하세요.","핵심 단어: water would be great"]', 'greg', 'Coming right up. Okay, let''s look at the contract draft.', '바로 드릴게요. 자, 계약서 초안을 봅시다.'),
  ('d11_client_visit', 3, 'greg', 'The draft says Summit can cancel with only seven days'' notice. That is too short for your team.', '초안에는 서밋이 7일 전 통보만으로 해지할 수 있다고 되어 있습니다. 팀에게는 너무 짧습니다.', 'Our legal team sent back a few redlines. Anything jump out at you?', '법무팀이 수정 표시를 몇 개 보냈어요. 눈에 띄는 거 있어요?', 'One clause gives your team too little warning if Summit cancels. Raise it and suggest 30 days.', '서밋이 해지할 때 통보 기간이 너무 짧은 조항이 있습니다. 지적하고 30일을 제안하세요.', '[{"any":["thirty","30"]},{"all":["cancellation"],"any":["short","longer"]},{"all":["notice"],"any":["short","longer"]}]', 'The seven-day cancellation notice is too short for us. Could we make it thirty days?', '7일 전 해지 통보는 저희한테 너무 짧아요. 30일로 할 수 있을까요?', '["The seven-day cancellation notice is too short. Could we make it ninety days?","Everything looks fine. We can live with seven days'' notice, no problem.","Your lawyers made the cancellation terms way too one-sided. That''s not okay."]', '["7일 전 해지 통보는 너무 짧아요. 90일로 할 수 있을까요?","다 괜찮아 보여요. 7일 전 통보도 저희는 문제없어요.","그쪽 변호사들이 해지 조건을 너무 일방적으로 만들었네요. 이건 아니죠."]', '["Ninety? That''s a lot. Let''s be reasonable.","Great, that makes it easy. So we''re good?","Easy. They''re just being careful. What''s the specific issue?"]', '["90일요? 너무 길어요. 합리적으로 갑시다.","좋아요, 그럼 쉽네요. 다 된 거죠?","진정해요. 신중해서 그런 거예요. 구체적으로 뭐가 문제예요?"]', '["Name the problem clause and offer a change.","Key words: cancellation notice, too short, thirty days"]', '["문제 조항을 짚고 수정안을 내세요.","핵심 단어: cancellation notice, too short, thirty days"]', 'greg', 'That''s fair. We can do thirty. Anything else on your side?', '타당하네요. 30일로 하죠. 그쪽에서 다른 건요?'),
  ('d11_client_visit', 4, 'greg', 'You want to know who owns the code after the project ends.', '프로젝트가 끝난 뒤 코드가 누구 소유인지 알고 싶습니다.', 'Anything else on your side?', '그쪽에서 다른 건요?', 'You want to know what happens to the code once the project is over.', '프로젝트가 끝나면 코드가 어떻게 되는지 알고 싶습니다.', '[{"all":["own","code"]},{"all":["owns","code"]},{"all":["ownership"]},{"all":["intellectual property"]}]', 'Just one question: who owns the source code at the end of the project?', '질문 하나만요. 프로젝트가 끝나면 소스 코드는 누구 소유예요?', '["Just one question: who''s paying for my hotel and flight here?","Just one thing: we''ll keep the source code after the project, of course.","Just one question: who owns the store data after the project?"]', '["질문 하나만요. 여기 호텔이랑 항공권은 누가 내요?","하나만요. 프로젝트 끝나면 소스 코드는 당연히 저희가 갖는 거죠.","질문 하나만요. 프로젝트가 끝나면 매장 데이터는 누구 소유예요?"]', '["Uh, I assumed your company handles that?","Whoa, that''s not how I understood it. Let''s check the contract.","The data''s always ours. Anything else on your list?"]', '["어, 그쪽 회사에서 처리하는 줄 알았는데요?","워, 제가 이해한 거랑 다른데요. 계약서 봅시다.","데이터는 당연히 우리 거죠. 다른 질문 있어요?"]', '["Ask about ownership of the work.","Key words: who owns, source code"]', '["결과물의 소유권을 물어보세요.","핵심 단어: who owns, source code"]', 'greg', 'Summit does, once the final invoice is paid. It''s in section nine.', '최종 송장이 지급되면 서밋 소유예요. 9조에 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_client_visit', 5, 'greg', 'The meeting went well. Greg closes his laptop.', '회의가 잘 끝났습니다. 그렉이 노트북을 닫습니다.', 'I think we''re close. I''ll send the final version to legal tonight. Dinner at your hotel at seven?', '거의 다 된 것 같네요. 오늘 밤에 최종본을 법무팀에 보낼게요. 7시에 당신 호텔에서 저녁 어때요?', 'Greg invites you to dinner. Accept.', '그렉이 저녁에 초대합니다. 받아들이세요.', '[{"all":["sounds"]},{"all":["see you"]},{"all":["love to"]},{"all":["works"]},{"all":["great"]}]', 'Sounds great. See you at seven.', '좋아요. 7시에 봬요.', '["Sounds great. See you at eight.","Sure. Is it on you or on us?","Sure. Which hotel are you staying at?"]', '["좋아요. 8시에 봬요.","좋아요. 누가 내는 거예요?","좋아요. 어느 호텔에 묵으세요?"]', '["Eight? I said seven, but I can push it.","Ha, it''s on me. Don''t worry about it.","Your hotel. The Pinecrest, remember?"]', '["8시요? 7시라고 했는데, 미룰 수는 있어요.","하, 제가 살게요. 걱정 마요.","당신 호텔요. 파인크레스트 말이에요."]', '["Say yes to dinner.","Key words: sounds great, see you at seven"]', '["저녁 초대에 응하세요.","핵심 단어: sounds great, see you at seven"]', 'greg', 'Great. I made a reservation at their restaurant. See you there.', '좋아요. 호텔 레스토랑에 예약해 뒀어요. 거기서 봐요.'),
  ('d11_dinner', 1, 'greg', 'You meet Greg at the hotel restaurant. The host seats you and hands you menus.', '호텔 레스토랑에서 그렉을 만납니다. 직원이 자리로 안내하고 메뉴를 건넵니다.', 'Before the server comes by, do you have any dietary restrictions? I want to make sure this place works for you.', '서버 오기 전에요, 혹시 못 드시는 음식 있어요? 여기가 괜찮은 곳인지 확인하고 싶어서요.', 'Answer his question. You have a peanut allergy, and nothing else is off-limits.', '그의 질문에 답하세요. 땅콩 알레르기가 있고, 그 밖에 못 먹는 건 없습니다.', '[{"all":["allergic"]},{"all":["allergy"]},{"all":["no","restrictions"]},{"all":["eat","everything"]},{"all":["vegetarian"]}]', 'Thanks for asking. I''m allergic to peanuts, but other than that I eat everything.', '물어봐 주셔서 감사해요. 땅콩 알레르기가 있는데, 그거 말고는 다 잘 먹어요.', '["That''s kind of you. I can''t eat shellfish, but anything else is fine with me.","Honestly, this place isn''t really my style. Could we try somewhere else instead?","Thanks for asking. This place looks great. Have you been here with your team before?"]', '["신경 써 주셔서 고마워요. 조개나 새우 같은 건 못 먹는데, 나머지는 다 괜찮아요.","솔직히 여긴 제 취향이 아니라서요. 다른 데로 가 보면 안 될까요?","물어봐 주셔서 감사해요. 여기 분위기 좋네요. 팀분들이랑 와 보신 적 있어요?"]', '["Shellfish, got it. I''ll steer clear of the crab cakes, then.","Oh. Well, I already booked the table, but… I guess we could look around.","A couple of times, sure. But I asked about food. Anything you can''t eat?"]', '["갑각류, 알겠어요. 그럼 크랩 케이크는 피할게요.","아. 음, 이미 예약은 해 뒀는데… 다른 데를 알아볼 수는 있겠죠.","몇 번 왔죠. 그런데 음식을 물어본 거예요. 못 드시는 거 있어요?"]', '["Mention any food you can''t eat.","Key words: allergic to, other than that"]', '["못 먹는 음식을 말하세요.","핵심 단어: allergic to, other than that"]', 'greg', 'Good to know. I''ll mention it to the server.', '알아 둘게요. 서버에게 말해 둘게요.'),
  ('d11_dinner', 2, 'greg', 'The server comes to take your order. Greg gestures for you to go first.', '서버가 주문을 받으러 옵니다. 그렉이 먼저 하라고 손짓합니다.', 'Go ahead, you first.', '먼저 시키세요.', 'You''ve decided on the salmon, with a salad on the side. Order first, as Greg suggests.', '연어 요리에 샐러드를 곁들이기로 했습니다. 그렉 말대로 먼저 주문하세요.', '[{"any":["salmon","steak","fish","chicken","pasta"]}]', 'I''ll have the grilled salmon with a side salad, please.', '저는 연어 구이에 사이드 샐러드로 주세요.', '["I''ll try the Thai peanut noodles with a side salad, please.","Oh, you''re the host. Why don''t you just order for both of us?","Salmon. Salad on the side. And make it quick, we''re busy."]', '["저는 태국식 땅콩 국수에 사이드 샐러드로 주세요.","아, 오늘 초대하신 분이니까 그냥 둘 다 시켜 주실래요?","연어요. 샐러드 따로. 그리고 빨리 좀 주세요, 바빠서요."]', '["Peanut noodles? Didn''t you just say you''re allergic to peanuts?","No, no, go ahead. I want you to get what you like.","Whoa, easy. We''re in no hurry tonight."]', '["땅콩 국수요? 방금 땅콩 알레르기 있다고 하지 않았어요?","아니에요, 어서 시켜요. 드시고 싶은 걸로 드셔야죠.","워, 천천히 해요. 오늘 밤은 급할 거 없잖아요."]', '["Order a main dish and a side.","Key words: I''ll have the grilled salmon"]', '["메인 요리와 곁들임을 주문하세요.","핵심 단어: I''ll have the grilled salmon"]', 'greg', 'I''ll do the steak, medium rare. And let''s get the calamari to share.', '저는 스테이크, 미디엄 레어로요. 그리고 오징어 튀김 하나 나눠 먹죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_dinner', 3, 'greg', 'Over dinner, the talk moves away from work.', '식사하며 대화가 일 얘기에서 벗어납니다.', 'So, enough about contracts. What do you like to do on the weekends?', '자, 계약 얘기는 그만하고요. 주말엔 뭐 하는 걸 좋아해요?', 'Open up a little about your weekends. You enjoy the outdoors and exploring places to eat.', '주말 이야기를 조금 들려주세요. 야외 활동과 맛집 탐방을 좋아합니다.', '[{"any":["hiking","hike","restaurants","cooking","reading","soccer","running","movies","games","music"]},{"any":["i like","i love","i enjoy"]}]', 'I like hiking, and I love trying new restaurants around town.', '하이킹을 좋아하고, 동네 새 식당 가 보는 것도 정말 좋아해요.', '["Honestly, I mostly catch up on work. The dashboard won''t build itself.","Not much, really. I''d rather keep my weekends to myself, if that''s okay.","I''m into video games, and I usually just stay home and order in."]', '["솔직히 주로 밀린 일 해요. 대시보드가 저절로 만들어지진 않으니까요.","별거 없어요. 주말 얘기는 그냥 안 하고 싶은데, 괜찮죠?","게임을 좋아해서 보통은 집에서 배달시켜 먹으며 지내요."]', '["Ha, you sound like my team. Come on, there''s more to life than work.","Oh. Sure, of course. Sorry, didn''t mean to pry.","Ha, a homebody. Nothing wrong with that."]', '["하, 우리 팀 애들 같네요. 에이, 인생에 일만 있는 건 아니잖아요.","아. 그럼요, 물론이죠. 미안해요, 캐물으려던 건 아니었어요.","하, 집돌이시구나. 그것도 나쁘지 않죠."]', '["Share a hobby or two.","Key words: I like, hiking, restaurants"]', '["취미 한두 개를 말하세요.","핵심 단어: I like, hiking, restaurants"]', 'greg', 'Oh, then you have to try the lake trail here. Great views.', '오, 그럼 여기 호수 산책로에 꼭 가 봐요. 경치가 끝내줘요.'),
  ('d11_dinner', 4, 'greg', 'The check arrives and Greg reaches for it. Maya said client dinners go on the company card.', '계산서가 오자 그렉이 손을 뻗습니다. 마야는 고객 식사는 법인 카드로 하라고 했습니다.', 'Here, let me get this.', '자, 이건 제가 낼게요.', 'Don''t let Greg pay. Be gracious about it.', '그렉이 계산하게 두지 마세요. 정중하게요.', '[{"all":["get this one"]},{"all":["my treat"]},{"all":["i got this"]},{"all":["on us"]},{"all":["company card"]},{"all":["i will get"]},{"all":["let me get"]}]', 'Oh no, I''ll get this one. It''s on us.', '아니에요, 이번엔 제가 낼게요. 저희가 대접하는 거예요.', '["Oh, thank you! That''s really kind of you.","How about we split it? Half and half?","Put that away. Maya would kill me."]', '["아, 감사합니다! 정말 친절하시네요. 잘 먹었어요.","그냥 반반 나눠서 낼까요? 각자 반씩 내는 걸로요.","넣어 두세요. 그랬다간 마야한테 저 죽어요."]', '["Happy to. Though usually the vendor fights me for it.","Split it? Come on, one of us should just take it.","Ha! Okay, okay. I wouldn''t want to get you in trouble."]', '["기꺼이요. 보통은 업체 쪽에서 서로 내겠다고 하던데.","반반이요? 에이, 그냥 한 사람이 내죠.","하! 알았어요, 알았어. 곤란하게 만들면 안 되죠."]', '["Take the check yourself.","Key words: I''ll get this one, it''s on us"]', '["계산서를 직접 가져가세요.","핵심 단어: I''ll get this one, it''s on us"]', 'greg', 'Well, thank you. I''ll get the next one when you''re in town again.', '그럼 고마워요. 다음에 또 오면 제가 살게요.'),
  ('d11_dinner', 5, 'greg', 'The bill is $164 before tip. In the US, about 20 percent is normal for good service.', '팁 전 금액이 164달러입니다. 미국에서는 서비스가 좋으면 20% 정도가 보통입니다.', 'Service was great tonight, wasn''t it?', '오늘 서비스 정말 좋았죠?', 'Agree about the service, and say how much you''ll tip.', '서비스에 동의하고, 팁을 얼마나 줄지 말하세요.', '[{"any":["20","twenty","33","thirty three"]}]', 'It was. I''ll leave a twenty percent tip, so about thirty-three dollars.', '그러게요. 팁은 20% 남길게요. 그럼 33달러쯤이네요.', '["Definitely. I''ll leave a twenty percent tip, so around sixteen dollars.","It was okay. I''ll just leave five bucks. They get paid anyway, right?","It was. Do people usually tip here? I''m not sure how it works."]', '["정말요. 팁은 20% 줄게요. 그러니까 16달러쯤이요.","그냥 그랬어요. 5달러만 둘게요. 어차피 월급 받잖아요?","맞아요. 여기선 보통 팁을 주나요? 잘 몰라서요."]', '["Sixteen? I think twenty percent of one sixty-four is a bit more than that.","Uh, not really. Servers here mostly live on tips, you know.","Sure do. Twenty percent is pretty standard for good service."]', '["16달러요? 164달러의 20%면 그거보다 좀 더 될 텐데요.","어, 그렇진 않아요. 여기 서버들은 거의 팁으로 먹고살아요.","그럼요. 서비스 좋으면 20%가 보통이에요."]', '["Work out the tip: 20 percent of $164.","Key words: twenty percent, thirty-three dollars"]', '["164달러의 20%를 계산하세요.","핵심 단어: twenty percent, thirty-three dollars"]', 'greg', 'Very generous. Get some rest. Big day tomorrow!', '후하네요. 푹 쉬어요. 내일 중요한 날이잖아요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_gate', 1, 'amy', 'At gate B12, the screen changes to DELAYED. Amy is now working the gate desk.', 'B12 게이트 전광판이 지연(DELAYED)으로 바뀝니다. 에이미가 이제 게이트 데스크를 맡고 있습니다.', 'Attention, passengers on flight 482 to Ridgeport. We have a thirty-minute delay due to a late incoming aircraft.', '리지포트행 482편 승객 여러분께 안내 말씀드립니다. 도착 항공기 지연으로 30분 지연되겠습니다.', 'Go up to the desk and find out when you''ll leave now.', '데스크에 가서 이제 언제 출발하는지 알아보세요.', '[{"all":["new","time"]},{"all":["departure","time"]},{"all":["when"],"any":["leave","depart","departing","board","boarding","take off"]},{"all":["what time"]}]', 'Excuse me, what''s the new departure time?', '실례합니다, 새 출발 시각이 언제예요?', '["Excuse me, is the flight to Ridgeport canceled?","This is ridiculous. Why is it always late?","Excuse me, so it''s leaving an hour late now?"]', '["실례합니다, 리지포트행 비행기 결항이에요?","말도 안 돼요. 왜 맨날 늦어요?","실례합니다, 그럼 이제 한 시간 늦게 떠요?"]', '["No, just delayed thirty minutes. Nothing''s canceled.","I''m sorry. The plane''s coming in late from another city.","Just thirty minutes. Not too bad."]', '["아뇨, 30분 지연일 뿐이에요. 결항은 없어요.","죄송해요. 다른 도시에서 오는 비행기가 늦게 들어와서요.","30분만요. 그렇게 나쁘진 않아요."]', '["Ask when the plane will leave now.","Key words: new departure time"]', '["이제 언제 출발하는지 물어보세요.","핵심 단어: new departure time"]', 'amy', 'We''re now looking at ten o''clock, with boarding at nine-thirty.', '이제 10시 출발, 탑승은 9시 30분 예정이에요.'),
  ('d11_gate', 2, 'amy', 'Your meeting at Summit Retail is at two.', '서밋 리테일과의 회의는 2시입니다.', 'Do you have a connecting flight?', '연결편 있으세요?', 'Answer her, and mention your 2 p.m. meeting. You''re worried about being late.', '대답하고, 오후 2시 회의를 언급하세요. 늦을까 걱정됩니다.', '[{"all":["meeting"]},{"all":["make it"]},{"all":["still"],"any":["arrive","land","there"]}]', 'No, it''s nonstop. But I have a meeting at two. Will I still make it?', '아뇨, 직항이에요. 그런데 2시에 회의가 있어요. 늦지 않을까요?', '["Yes, I have a connection in Ridgeport. Will I still make it?","No, it''s nonstop. My meeting''s at four, so I''m not worried.","No, but I have a two o''clock meeting. You have to get me there on time."]', '["네, 리지포트에서 갈아타요. 그래도 시간 맞을까요?","아뇨, 직항이에요. 회의가 4시라서 걱정 안 해요.","아뇨, 그런데 2시에 회의가 있어요. 무조건 제시간에 데려다주셔야 해요."]', '["Ridgeport''s your final stop, though. It''s a nonstop.","Great, then you''ll have plenty of time.","I''ll do what I can, but I don''t fly the plane."]', '["리지포트가 최종 목적지인데요. 직항편이에요.","좋네요, 그럼 시간은 충분하겠어요.","최선을 다하겠지만, 제가 조종하는 건 아니라서요."]', '["Explain your plans and ask if the delay is a problem.","Key words: meeting at two, will I still make it"]', '["일정을 설명하고 지연이 문제가 될지 물어보세요.","핵심 단어: meeting at two, will I still make it"]', 'amy', 'You should land around twelve-fifteen, so you''ll have plenty of time.', '12시 15분쯤 도착하니까 시간은 충분할 거예요.'),
  ('d11_gate', 3, 'amy', 'The flight is full. Your laptop is in your backpack.', '비행기가 만석입니다. 노트북은 배낭에 있습니다.', 'The flight is full today, so we''re offering free gate checks for carry-on bags. Would you like to check yours?', '오늘 만석이라 기내 가방은 게이트에서 무료로 부쳐 드리고 있어요. 부치시겠어요?', 'Turn down her offer, and say why.', '그 제안을 거절하고 이유를 말하세요.', '[{"all":["no thanks"]},{"all":["no thank you"]},{"all":["rather","keep"]},{"all":["keep","with me"]}]', 'No thanks. My laptop is in there, so I''d rather keep it with me.', '괜찮아요. 노트북이 들어 있어서 들고 타는 게 좋겠어요.', '["Sure, take it. Saves me lugging it around the airport.","No, and honestly, you should''ve warned us earlier that the flight was full.","Is it really free? Then could you check my suitcase too?"]', '["네, 가져가세요. 공항에서 들고 다니기 귀찮았는데 잘됐네요.","아뇨, 그리고 솔직히 만석이면 더 일찍 알려 줬어야죠.","정말 무료예요? 그럼 제 여행 가방도 부쳐 주실래요?"]', '["Okay. Just take out any laptops or batteries first.","I''m sorry. It''s just an option, no pressure.","Your suitcase was already checked at the counter."]', '["네. 노트북이나 배터리는 먼저 꺼내 주세요.","죄송해요. 그냥 선택 사항이에요, 부담 갖지 마세요.","여행 가방은 카운터에서 이미 부치셨어요."]', '["Decline politely and give a reason.","Key words: no thanks, I''d rather keep it with me"]', '["이유를 대며 정중히 거절하세요.","핵심 단어: no thanks, I''d rather keep it with me"]', 'amy', 'Totally understand. Thanks for your patience today.', '충분히 이해해요. 오늘 기다려 주셔서 감사해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_gate', 4, 'amy', 'Boarding begins at last.', '드디어 탑승이 시작됩니다.', 'We''re now boarding group three. Group three, welcome aboard.', '지금 3번 그룹 탑승합니다. 3번 그룹, 어서 오세요.', 'Hand over your pass, and show you appreciate how she handled the delay.', '탑승권을 건네고, 지연 동안 그녀가 잘 대처해 준 것에 고마움을 표하세요.', '[{"any":["thank","thanks","appreciate"]}]', 'Here''s my boarding pass. Thanks for keeping us updated.', '여기 탑승권이요. 계속 안내해 주셔서 고마워요.', '["Here''s my boarding pass. I''m in group one, by the way.","Here''s my boarding pass. Next time, try to leave on time.","Here you go. Do I still have time to grab a coffee?"]', '["여기 탑승권이요. 참고로 저 1번 그룹이에요.","여기 탑승권이요. 다음엔 제시간에 좀 떠 주세요.","여기요. 커피 한 잔 사 올 시간 있어요?"]', '["It says group three here. But you''re good to go.","Noted. Enjoy your flight.","Not really, we''re boarding now. Go on in!"]', '["여기 3번 그룹이라고 돼 있네요. 그래도 타시면 돼요.","참고하죠. 즐거운 비행 되세요.","아뇨, 지금 탑승 중이에요. 들어가세요!"]', '["Say thank you as you board.","Key words: thanks for keeping us updated"]', '["탑승하며 감사 인사를 하세요.","핵심 단어: thanks for keeping us updated"]', 'amy', 'My pleasure. Enjoy your flight!', '천만에요. 즐거운 비행 되세요!'),
  ('d11_hotel_checkin', 1, 'kelly', 'You arrive at the Pinecrest Hotel around lunchtime. Check-in is usually at three.', '점심때쯤 파인크레스트 호텔에 도착합니다. 체크인은 보통 3시입니다.', 'Welcome to the Pinecrest! Checking in?', '파인크레스트에 오신 걸 환영해요! 체크인하세요?', 'It''s only lunchtime, hours before check-in. Confirm your booking and see if your room can be ready now.', '아직 점심때라 체크인 시간 전입니다. 예약을 확인하고 지금 방에 들어갈 수 있는지 물어보세요.', '[{"all":["reservation"]},{"all":["early","check in"]},{"all":["early","checkin"]},{"all":["room","ready"]},{"all":["booking"]}]', 'Yes, I have a reservation under my name. Is early check-in possible?', '네, 제 이름으로 예약했어요. 일찍 체크인할 수 있을까요?', '["Yes, I have a reservation for two nights. Can I check in now?","Yes, and I''d like to get into my room right now, please. It''s been a long day.","Yes, it should be under Summit Retail. Is early check-in possible?"]', '["네, 2박 예약했어요. 지금 체크인할 수 있어요?","네, 지금 바로 방에 들어가고 싶어요. 오늘 힘든 하루였거든요.","네, 서밋 리테일 이름으로 돼 있을 거예요. 일찍 체크인할 수 있을까요?"]', '["Hmm, I only see one night here. Is that right?","I''ll see what I can do, but check-in is normally at three.","Nothing under Summit Retail. Who made the booking?"]', '["음, 여기엔 1박만 있는데요. 맞으세요?","알아볼게요, 근데 체크인은 보통 3시예요.","서밋 리테일로는 없는데요. 누가 예약하셨어요?"]', '["Mention your reservation and ask about checking in early.","Key words: reservation under my name, early check-in"]', '["예약했다고 말하고 이른 체크인을 물어보세요.","핵심 단어: reservation under my name, early check-in"]', 'kelly', 'Let me see… You''re in luck. A room just opened up. One night, checking out Friday?', '잠시만요… 운이 좋으시네요. 방이 막 비었어요. 1박, 금요일 체크아웃 맞으시죠?'),
  ('d11_hotel_checkin', 2, 'kelly', 'The room is on the company card, but Kelly asks for another card.', '객실은 법인 카드로 결제됐는데, 켈리가 카드를 하나 더 달라고 합니다.', 'That''s right. I''ll just need a card for incidentals.', '맞아요. 부대비용용 카드만 하나 주시면 돼요.', 'You''re not sure why they need another card. Ask what it''s for.', '왜 카드가 하나 더 필요한지 모르겠습니다. 무엇을 위한 건지 물어보세요.', '[{"all":["incidentals"]},{"all":["incidental"]},{"all":["hold"],"any":["what","how much"]},{"all":["deposit"]}]', 'Sure. What exactly is the incidentals hold for?', '네. 부대비용 보증금은 정확히 뭘 위한 거예요?', '["The room''s already paid. Why charge me twice?","Sure. Is that for my early check-in fee?","Do I have to? I don''t plan on spending anything."]', '["방값은 이미 냈는데요. 왜 두 번 결제해요?","네. 그거 얼리 체크인 요금이에요?","꼭 해야 해요? 아무것도 안 쓸 건데요."]', '["It''s not a charge, just a hold. Let me explain.","No, early check-in''s free today. It''s for extras.","Sorry, it''s required for every guest."]', '["결제가 아니라 보증금이에요. 설명해 드릴게요.","아뇨, 오늘 얼리 체크인은 무료예요. 추가 비용용이에요.","죄송해요, 모든 손님께 받고 있어요."]', '["Ask why she needs the card.","Key words: what is the hold for, incidentals"]', '["카드가 왜 필요한지 물어보세요.","핵심 단어: what is the hold for, incidentals"]', 'kelly', 'It''s fifty dollars a night for extras like room service or the minibar. It''s released when you check out.', '룸서비스나 미니바 같은 추가 비용용으로 1박에 50달러예요. 체크아웃하면 풀려요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_hotel_checkin', 3, 'kelly', 'Kelly hands you two key cards for room 612.', '켈리가 612호 키 카드 두 장을 건넵니다.', 'Here are your key cards. You''re in room 612.', '키 카드 여기 있어요. 612호예요.', 'Find out when you can eat in the morning.', '아침에 언제 먹을 수 있는지 물어보세요.', '[{"all":["breakfast"],"any":["time","when","hours","served","start","open"]}]', 'Thanks. What time is breakfast served?', '고마워요. 아침 식사는 몇 시에 나와요?', '["Thanks. How much is breakfast, by the way?","Thanks. So I''m in 216, on the second floor?","Thanks. What time does the gym open?"]', '["고마워요. 그런데 아침 식사는 얼마예요?","고마워요. 그럼 2층 216호죠?","고마워요. 헬스장은 몇 시에 열어요?"]', '["It''s included with your rate. No charge.","Six-twelve, sixth floor. Elevators are on the right.","Five a.m. Was there anything else you wanted to know?"]', '["요금에 포함돼 있어요. 무료예요.","612호, 6층이에요. 엘리베이터는 오른쪽에 있어요.","새벽 5시요. 다른 거 궁금한 거 있으세요?"]', '["Ask about breakfast hours.","Key words: what time, breakfast served"]', '["조식 시간을 물어보세요.","핵심 단어: what time, breakfast served"]', 'kelly', 'Six-thirty to ten, in the restaurant off the lobby.', '6시 30분부터 10시까지, 로비 옆 레스토랑에서요.'),
  ('d11_hotel_checkin', 4, 'kelly', 'Your flight home on Friday is in the afternoon.', '금요일 귀국편은 오후입니다.', 'Anything else I can help you with?', '더 도와드릴 거 있으세요?', 'Your flight home isn''t until the afternoon. Ask to keep the room a bit longer.', '귀국편이 오후입니다. 방을 좀 더 오래 쓸 수 있는지 물어보세요.', '[{"all":["late checkout"]},{"all":["late check out"]},{"all":["check out","later"]},{"all":["checkout","later"]}]', 'Could I get a late checkout on Friday?', '금요일에 늦게 체크아웃할 수 있을까요?', '["Could I get a late checkout on Saturday?","Could I stay until five on Friday for free?","Could I get an early checkout on Friday?"]', '["토요일에 늦게 체크아웃할 수 있을까요?","금요일 5시까지 무료로 있어도 될까요?","금요일에 일찍 체크아웃할 수 있을까요?"]', '["Saturday? You''re checking out Friday, right?","Five''s a bit much. Let me see what I can do.","Early? Sure, just drop the keys whenever you leave."]', '["토요일요? 금요일 체크아웃이시잖아요?","5시는 좀 무리예요. 알아볼게요.","일찍요? 그럼요, 나가실 때 키만 두고 가세요."]', '["Ask to leave the room later than usual.","Key words: late checkout"]', '["평소보다 늦게 방을 비워도 되는지 물어보세요.","핵심 단어: late checkout"]', 'kelly', 'I can do one p.m. at no charge. Enjoy your stay!', '오후 1시까지 무료로 해 드릴게요. 즐거운 시간 보내세요!'),
  ('d11_security', 1, 'lee', 'You reach the TSA checkpoint. Officer Lee holds out his hand.', 'TSA 검색대에 도착합니다. 리 요원이 손을 내밉니다.', 'Boarding pass and ID, please.', '탑승권이랑 신분증 주세요.', 'Hand over what he asked for.', '그가 달라는 것을 건네세요.', '[{"any":["here you go","here you are","here it is","here they are","here are"]}]', 'Sure, here you go.', '네, 여기 있어요.', '["Just the pass, right?","Didn''t I just show it?","Shoes off, too?"]', '["탑승권만 드리면 되죠?","방금 보여 주지 않았어요?","신발도 벗어요?"]', '["And your ID, please.","That was the airline. This is TSA. ID, please.","One thing at a time. Pass and ID first."]', '["신분증도 주세요.","그건 항공사고요. 여긴 TSA입니다. 신분증 주세요.","하나씩 하죠. 탑승권이랑 신분증 먼저요."]', '["Say the phrase you use when you hand something over.","Key words: here you go"]', '["무언가를 건넬 때 쓰는 말을 하세요.","핵심 단어: here you go"]', 'lee', 'Thanks. Laptops out in a separate bin. Empty your pockets, please.', '감사합니다. 노트북은 따로 바구니에 꺼내 주세요. 주머니도 비워 주세요.'),
  ('d11_security', 2, 'lee', 'You put your laptop in a bin. You are not sure about your shoes.', '노트북을 바구니에 넣습니다. 신발은 어떻게 해야 할지 모르겠습니다.', 'Laptops out, pockets empty. Next!', '노트북 꺼내고, 주머니 비우세요. 다음!', 'You''re not sure what to do about your shoes. Ask.', '신발을 어떻게 해야 할지 모르겠습니다. 물어보세요.', '[{"all":["shoes"]},{"all":["belt"]},{"all":["jacket"]}]', 'Do I need to take my shoes off too?', '저 신발도 벗어야 하나요?', '["Do I need to take my laptop out too?","Do I have to do all this every time?","Can I leave my shoes on? I''m in a hurry."]', '["노트북도 꺼내야 해요?","매번 이걸 다 해야 해요?","신발 그냥 신어도 돼요? 급해서요."]', '["I just said laptops out. You already did, right?","Every time. Keep it moving, please.","Not in this line. Rules are the same for everyone."]', '["방금 노트북 꺼내라고 했죠. 이미 꺼냈잖아요?","매번요. 빨리 진행해 주세요.","이 줄에선 안 됩니다. 규칙은 모두 똑같아요."]', '["Ask about your shoes.","Key words: shoes off"]', '["신발에 대해 물어보세요.","핵심 단어: shoes off"]', 'lee', 'Yes, shoes off, unless you have TSA PreCheck. Then you''d use the other line.', '네, 신발 벗으세요. TSA 프리체크가 있으면 다른 줄로 가면 되고요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d11_security', 3, 'lee', 'The scanner beeps. You forgot a full water bottle in your bag.', '검색기가 삑 소리를 냅니다. 가방에 물이 가득 든 병을 깜빡했습니다.', 'Is this your bag? There''s a water bottle in here. It''s over the limit.', '이거 본인 가방이에요? 안에 물병이 있네요. 허용량 초과예요.', 'It''s yours, and you forgot about it. Own up and give it up.', '당신 것이 맞고, 깜빡했습니다. 인정하고 포기하세요.', '[{"all":["sorry"]},{"all":["forgot"]},{"all":["throw","away"]},{"all":["toss","it"]},{"all":["my bad"]}]', 'Oh, sorry, I totally forgot about it. You can throw it away.', '아, 죄송해요, 완전히 깜빡했어요. 버리셔도 돼요.', '["That''s not my bag. Someone else must have put it there.","Seriously? It''s just water. Can''t you let it go this once?","Oh, sorry, I forgot. Can you put it in my checked suitcase?"]', '["제 가방 아니에요. 누가 거기 둔 게 분명해요.","진짜요? 그냥 물인데요. 이번 한 번만 봐주면 안 돼요?","아, 죄송해요, 깜빡했어요. 부친 가방에 넣어 주실 수 있어요?"]', '["It''s got your laptop right next to it. Come on.","Sorry, rules are rules. Liquids over the limit can''t go.","Your checked bag''s long gone, I''m afraid."]', '["바로 옆에 당신 노트북이 있는데요. 이러지 마세요.","죄송하지만 규칙은 규칙입니다. 한도 넘는 액체는 안 돼요.","부친 가방은 이미 한참 전에 갔어요."]', '["Apologize and let it go.","Key words: sorry, forgot, throw it away"]', '["사과하고 포기하세요.","핵심 단어: sorry, forgot, throw it away"]', 'lee', 'No problem. Next time, empty it before security and fill it up at the gate. You''re all set.', '괜찮아요. 다음엔 검색 전에 비우고 게이트에서 채우세요. 다 됐습니다.'),
  ('d11_security', 4, 'lee', 'You put your shoes back on and grab your laptop.', '신발을 다시 신고 노트북을 챙깁니다.', 'You''re all set. Have a good flight.', '다 됐습니다. 즐거운 비행 되세요.', 'You''re done here. Ask for directions to your gate.', '검색이 끝났습니다. 게이트로 가는 길을 물어보세요.', '[{"all":["gate"]},{"all":["b12"]},{"all":["b 12"]}]', 'Thanks. Which way is gate B12?', '고마워요. B12 게이트는 어느 쪽이에요?', '["Thanks. Which way is gate B21?","Thanks. Which way is baggage claim?","Where''s my gate? You should know."]', '["고마워요. B21 게이트는 어느 쪽이에요?","고마워요. 수하물 찾는 곳은 어느 쪽이에요?","제 게이트 어디예요? 아실 거 아니에요."]', '["B21? Double-check your pass. I think it''s another gate.","That''s for arrivals. You''re departing, right?","I don''t know your flight. What does your pass say?"]', '["B21요? 탑승권 다시 보세요. 다른 게이트 같은데요.","그건 도착하는 분들용이에요. 출발하시는 거죠?","손님 항공편은 제가 모르죠. 탑승권에 뭐라고 돼 있어요?"]', '["Ask for directions to your gate.","Key words: which way, gate B12"]', '["게이트로 가는 길을 물어보세요.","핵심 단어: which way, gate B12"]', 'lee', 'Down the hall, on your left. About a five-minute walk.', '복도 따라 왼쪽이에요. 걸어서 5분쯤이요.'),
  ('d12_checkout', 1, 'kelly', 'You roll your suitcase to the front desk.', '여행 가방을 끌고 프런트로 갑니다.', 'Good morning! Checking out? How was your stay?', '좋은 아침이에요! 체크아웃하시나요? 묵으시는 동안 어떠셨어요?', 'You''re leaving today. Answer her, and say how your time at the hotel went: you enjoyed it.', '오늘 떠납니다. 그녀에게 답하고, 묵는 동안 어땠는지 말하세요. 좋았습니다.', '[{"all":["check out"]},{"all":["checkout"]},{"all":["checking out"]}]', 'Good morning. I''d like to check out, please. The stay was great.', '좋은 아침이에요. 체크아웃할게요. 아주 잘 지냈어요.', '["Good morning. Could I extend my stay one more night, please?","Yeah, checking out. Can we hurry this up? I have a flight to catch.","Morning. I''m checking out. Honestly, the room was pretty noisy."]', '["좋은 아침이에요. 하룻밤 더 연장할 수 있을까요?","네, 체크아웃이요. 좀 빨리 해 줄래요? 비행기 타야 해서요.","안녕하세요. 체크아웃할게요. 솔직히 방이 꽤 시끄러웠어요."]', '["One more night? Let me see… it shows you checking out today.","Of course. I''ll be as quick as I can.","Oh, I''m sorry to hear that. I''ll pass it along to our manager."]', '["하룻밤 더요? 어디 보자… 오늘 체크아웃으로 되어 있는데요.","물론이죠. 최대한 빨리 해 드릴게요.","아, 죄송해요. 매니저에게 전달해 둘게요."]', '["Say you are leaving today.","Key words: I''d like to check out"]', '["오늘 떠난다고 말하세요.","핵심 단어: I''d like to check out"]', 'kelly', 'Glad to hear it! Here''s your folio. Take a look and let me know if everything''s correct.', '다행이에요! 여기 청구서예요. 확인해 보시고 맞는지 알려 주세요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d12_checkout', 2, 'kelly', 'The bill shows a $14 minibar charge. You never opened the minibar.', '청구서에 미니바 14달러가 있습니다. 미니바는 열지도 않았습니다.', 'Does everything look okay?', '다 괜찮아 보이세요?', 'Point out the charge on the bill that shouldn''t be there.', '청구서에 있으면 안 되는 요금을 짚어 주세요.', '[{"all":["minibar"]},{"all":["mini bar"]},{"all":["recognize"]},{"all":["charge"],"any":["wrong","mistake","error"]}]', 'Actually, there''s a minibar charge I don''t recognize. I didn''t use the minibar.', '사실 모르는 미니바 요금이 있어요. 미니바는 쓰지 않았거든요.', '["Actually, there''s a room service charge here. I never ordered any.","You''ve charged me for the minibar. Are you guys trying to rip people off?","Looks fine, thanks. The company''s paying for it anyway, so it doesn''t really matter."]', '["사실 여기 룸서비스 요금이 있네요. 룸서비스는 시킨 적이 없어요.","미니바 요금을 붙였네요. 여기 사람들 바가지 씌우는 거예요?","괜찮아 보여요. 어차피 회사가 내니까 상관없어요."]', '["Room service? I don''t see any room service here. Which line do you mean?","Of course not, sir. Let me look into it.","Okay… just so you know, there''s a fourteen-dollar charge on there."]', '["룸서비스요? 여기엔 룸서비스가 없는데요. 어느 줄 말씀이세요?","그럴 리가요, 손님. 확인해 보겠습니다.","네… 참고로 말씀드리면, 14달러짜리 항목이 하나 있어요."]', '["Point out the wrong charge.","Key words: a charge I don''t recognize, minibar"]', '["잘못된 요금을 짚으세요.","핵심 단어: a charge I don''t recognize, minibar"]', 'kelly', 'I''m so sorry about that. I''ve taken it off. The room itself is on the company card.', '정말 죄송해요. 빼 드렸어요. 객실 요금은 법인 카드로 처리됐어요.'),
  ('d12_checkout', 3, 'kelly', 'You need the receipt for your expense report.', '경비 정산을 하려면 영수증이 필요합니다.', 'Would you like a copy of the receipt?', '영수증 사본 드릴까요?', 'You need a receipt for your expenses, broken down line by line and sent to your email.', '경비 처리용 영수증이 필요합니다. 항목별로 나온 것을 이메일로 받으세요.', '[{"all":["itemized"]},{"all":["email"],"any":["receipt","copy","it"]},{"all":["send","receipt"]}]', 'Yes, please. Could you email me an itemized receipt? I need it for my expense report.', '네, 부탁드려요. 항목별 영수증을 이메일로 보내 주실 수 있어요? 경비 보고서에 필요해서요.', '["Yes, please. Could you just print out the total for me? I need it for my expense report.","No, thanks. I''ll just take a photo of the screen for my expense report.","Yes. Email it now, itemized. Accounting is very strict, so don''t mess it up."]', '["네, 부탁드려요. 합계만 출력해 주실래요? 경비 보고서에 필요해서요.","아뇨, 괜찮아요. 경비 보고서용으로 화면만 사진 찍어 갈게요.","네. 지금 항목별로 메일 보내요. 회계팀이 깐깐하니까 실수하지 마시고요."]', '["Just the total? For expenses they usually want every charge listed.","Um, okay… you sure? I can email you a proper copy.","I''ll be very careful."]', '["합계만요? 경비 처리할 때는 보통 항목이 다 나와야 하던데요.","음, 그러세요… 괜찮으시겠어요? 제대로 된 사본을 메일로 보내 드릴 수 있어요.","아주 조심하겠습니다."]', '["Ask for a detailed receipt by email.","Key words: email, itemized receipt"]', '["자세한 영수증을 이메일로 달라고 하세요.","핵심 단어: email, itemized receipt"]', 'kelly', 'Done. It should be in your inbox. Anything else?', '보냈어요. 메일함에 있을 거예요. 더 필요한 거 있으세요?'),
  ('d12_checkout', 4, 'kelly', 'Your flight home leaves this afternoon.', '귀국편은 오늘 오후에 출발합니다.', 'Anything else I can do for you?', '또 도와드릴 건 없으세요?', 'Ask how to get to the airport. The hotel runs a free ride there.', '공항에 어떻게 가는지 물어보세요. 호텔에서 무료 차편을 운행합니다.', '[{"all":["shuttle"]},{"all":["airport"],"any":["get","how","ride"]}]', 'Yes, where can I catch the shuttle to the airport?', '네, 공항 가는 셔틀은 어디서 타요?', '["Yes, where can I catch the shuttle to the train station?","No, I''m all set, thanks. Have a great day!","Yes. Can someone drive me to the airport right now?"]', '["네, 기차역 가는 셔틀은 어디서 타요?","아뇨, 다 됐어요. 감사해요. 좋은 하루 보내세요!","네. 누가 지금 공항까지 태워다 줄 수 있어요?"]', '["The train station? We only run a shuttle to the airport, I''m afraid.","You too! Oh, will you need a ride to the airport?","I''m afraid we don''t have drivers on call, but there is another option."]', '["기차역이요? 죄송하지만 셔틀은 공항만 가요.","손님도요! 아, 공항까지 가는 차편은 필요 없으세요?","죄송하지만 대기 중인 기사는 없어요. 대신 다른 방법이 있어요."]', '["Ask how to get to the airport.","Key words: catch the shuttle, airport"]', '["공항 가는 방법을 물어보세요.","핵심 단어: catch the shuttle, airport"]', 'kelly', 'Right outside the main doors, every thirty minutes. Safe travels!', '정문 바로 밖에서 30분마다 있어요. 조심히 가세요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d12_flight_home', 1, 'amy', 'At the gate for your flight home, Amy makes an announcement.', '귀국편 게이트에서 에이미가 안내 방송을 합니다.', 'Folks, this flight is overbooked. We''re looking for one volunteer to take the next flight, three hours later, for a travel voucher.', '여러분, 이 항공편이 초과 예약됐습니다. 세 시간 뒤 다음 항공편으로 옮겨 주실 분 한 분을 찾습니다. 여행 바우처를 드려요.', 'You might volunteer, but first find out what the offer is.', '자원할 수도 있지만, 먼저 보상이 얼마인지 알아보세요.', '[{"all":["how much"]},{"all":["worth"]},{"all":["voucher"],"any":["value","amount","what"]}]', 'Excuse me, how much is the voucher worth?', '저기요, 그 바우처는 얼마짜리예요?', '["Excuse me, what time does the next flight leave?","I''ll do it, but I want first class on the next one.","Seriously? You sold more seats than you have?"]', '["저기요, 다음 비행기는 몇 시에 출발해요?","할게요. 대신 다음 편은 일등석으로요.","진짜요? 좌석보다 표를 더 팔았다고요?"]', '["Three hours after this one. I just announced it, sir.","Let''s start with the voucher. First class isn''t on the table.","I know, I''m sorry. It happens. Would you be willing to volunteer?"]', '["이 편보다 세 시간 뒤예요. 방금 안내해 드렸어요, 손님.","바우처 얘기부터 하죠. 일등석은 어려워요.","알아요, 죄송해요. 가끔 이래요. 혹시 자원해 주실 수 있으세요?"]', '["Find out the value first.","Key words: how much, voucher, worth"]', '["먼저 가치를 알아보세요.","핵심 단어: how much, voucher, worth"]', 'amy', 'Three hundred dollars toward any future flight.', '다음 항공권에 쓸 수 있는 300달러예요.'),
  ('d12_flight_home', 2, 'amy', 'You are not in a hurry tonight, but three hundred feels a little low.', '오늘 밤 급하지는 않지만 300달러는 조금 적게 느껴집니다.', 'Would you be interested?', '관심 있으세요?', 'You''re open to it, but push for more: four hundred dollars.', '할 마음은 있지만 더 받아 내세요. 400달러로요.', '[{"any":["400","four hundred"]},{"all":["bump","up"]},{"all":["if"],"any":["more","higher"]}]', 'I might be. Would you do four hundred if I take the later flight?', '그럴 수도 있어요. 나중 비행기를 타면 400달러로 해 주실 수 있어요?', '["Maybe. Would you go up to three hundred if I take the later one?","Not for three hundred. Make it a thousand, or find somebody else.","Sure, I''ll take it. Three hundred is fine, sign me up."]', '["아마도요. 나중 비행기를 타면 300달러까지 올려 주실 수 있어요?","300달러로는 안 해요. 1,000달러 주든지 다른 사람 찾으세요.","네, 할게요. 300달러면 됐어요, 저로 해 주세요."]', '["Three hundred is what I''m offering already.","A thousand? I''m sorry, that''s way outside what I can do.","Great! Let me get your new boarding pass."]', '["300달러는 이미 드리는 금액인데요.","1,000달러요? 죄송하지만 제 권한을 훨씬 넘어요.","좋아요! 새 탑승권 뽑아 드릴게요."]', '["Make a counteroffer with a higher number.","Key words: would you do four hundred"]', '["더 높은 금액으로 역제안하세요.","핵심 단어: would you do four hundred"]', 'amy', 'Let me check… Okay, I can do four hundred, plus a fifteen-dollar meal voucher.', '확인해 볼게요… 좋아요, 400달러에 15달러 식사 쿠폰도 드릴게요.'),
  ('d12_flight_home', 3, 'amy', 'You want to be sure you won''t get bumped again.', '다시 밀려나지 않을지 확실히 하고 싶습니다.', 'Four hundred plus a meal voucher. Deal?', '400달러에 식사 쿠폰까지. 괜찮으세요?', 'Take the offer, but make sure you won''t get bumped from the next flight too.', '제안을 받아들이되, 다음 비행기에서도 밀려나지 않는지 확인하세요.', '[{"all":["confirmed"]},{"all":["confirm"]},{"all":["guaranteed"]},{"all":["seat"],"any":["later","next","guarantee"]}]', 'Deal. Just to confirm, I''m guaranteed a seat on the later flight?', '좋아요. 확인차 여쭤보는데, 나중 비행기 좌석은 확실히 보장되는 거죠?', '["Deal. Just to confirm, that''s five hundred plus the meal voucher?","Deal. Is there a lounge I can wait in for the next three hours?","Fine. But if I get bumped again, I''m filing a formal complaint."]', '["좋아요. 확인차 묻는 건데, 500달러에 식사 쿠폰 맞죠?","좋아요. 세 시간 동안 기다릴 라운지가 있나요?","알았어요. 근데 또 밀리면 정식으로 항의할 거예요."]', '["Four hundred, sir, plus fifteen for a meal.","Not with this ticket, sorry. Anything else before I print these?","Understood. There''s no need for that, sir."]', '["400달러예요, 손님. 그리고 식사비 15달러요.","죄송하지만 이 항공권으론 안 돼요. 출력하기 전에 다른 건 없으세요?","알겠습니다. 그러실 필요는 없을 거예요, 손님."]', '["Say yes, but protect yourself.","Key words: deal, guaranteed a seat"]', '["수락하되 확실히 해 두세요.","핵심 단어: deal, guaranteed a seat"]', 'amy', 'Yes, you''re confirmed in seat 9A. Here are your vouchers. Thanks for helping us out!', '네, 9A 좌석으로 확정됐어요. 여기 바우처요. 도와주셔서 감사해요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d12_flight_home', 4, 'amy', 'You have three hours to kill at the airport.', '공항에서 세 시간을 보내야 합니다.', 'Is there anything else I can do for you?', '또 도와드릴 일 있으세요?', 'You''re getting hungry. Find out what you can do with the fifteen-dollar coupon.', '배가 고파 옵니다. 15달러짜리 쿠폰으로 뭘 할 수 있는지 알아보세요.', '[{"all":["where"],"any":["use","voucher","eat"]},{"all":["restaurant"]},{"all":["food court"]}]', 'Where can I use the meal voucher?', '식사 쿠폰은 어디서 쓸 수 있어요?', '["Where can I use the travel voucher?","Can I get a cash refund instead?","Where''s the nearest hotel to the airport?"]', '["여행 바우처는 어디서 쓸 수 있어요?","대신 현금으로 돌려받을 수 있어요?","공항에서 제일 가까운 호텔은 어디예요?"]', '["The travel voucher''s for a future flight. You can''t use it here.","I''m sorry, the vouchers can''t be cashed out.","A hotel? Your flight''s in three hours, sir."]', '["여행 바우처는 다음 항공권용이에요. 여기서는 못 써요.","죄송하지만 바우처는 현금으로 바꿀 수 없어요.","호텔이요? 비행기가 세 시간 뒤인데요, 손님."]', '["Ask where the voucher works.","Key words: where, use, meal voucher"]', '["쿠폰을 어디서 쓸 수 있는지 물어보세요.","핵심 단어: where, use, meal voucher"]', 'amy', 'Any restaurant in this terminal. The burger place across the hall is pretty good.', '이 터미널의 식당 어디든요. 맞은편 버거집이 꽤 괜찮아요.'),
  ('d12_signing', 1, 'greg', 'Legal approved the final version overnight. Greg has the contract up on the screen.', '밤사이 법무팀이 최종본을 승인했습니다. 그렉이 계약서를 화면에 띄워 둡니다.', 'Morning! Legal signed off. Thirty days'' notice, Net 45, five percent off with the support contract. Does that match your notes?', '좋은 아침이에요! 법무팀 승인 났어요. 30일 전 통지, Net 45, 지원 계약 포함 시 5% 할인. 메모하신 거랑 맞아요?', 'The terms are exactly what you negotiated. Confirm it.', '협상한 조건 그대로입니다. 확인해 주세요.', '[{"all":["in agreement"]},{"any":["matches","match"]},{"all":["agreed"]},{"all":["looks right"]},{"all":["looks good"]}]', 'Yes, that matches my notes. I think we''re in agreement.', '네, 제 메모랑 일치해요. 합의가 된 것 같네요.', '["Almost. I had Net 30 in my notes, not Net 45. Can we check?","Sure, whatever legal says. Let''s just sign and get it over with.","Let me run it by Maya first, and I''ll get back to you next week."]', '["거의요. 제 메모엔 Net 30으로 돼 있어요. 확인해 볼까요?","네, 법무팀이 된다면 뭐. 그냥 서명하고 끝내죠.","먼저 마야한테 확인해 보고 다음 주에 연락드릴게요."]', '["Net 30? We settled on Net 45 last week. It''s right here in the email.","Ha. Well, it''s a pretty big contract, so let''s at least read it.","Next week? I thought we were signing today."]', '["Net 30이요? 지난주에 Net 45로 정했잖아요. 메일에 그대로 있어요.","하. 그래도 꽤 큰 계약이니까 읽어는 보죠.","다음 주요? 오늘 서명하는 줄 알았는데요."]', '["Confirm the terms.","Key words: matches my notes, in agreement"]', '["조건을 확인하세요.","핵심 단어: matches my notes, in agreement"]', 'greg', 'Fantastic. I''ll send it out for e-signature now.', '좋아요. 지금 전자 서명 요청을 보낼게요.'),
  ('d12_signing', 2, 'greg', 'Maya signs from the office, then Greg signs.', '마야가 사무실에서 서명하고, 이어서 그렉이 서명합니다.', 'And… done! It''s official. Welcome to the Summit family.', '그리고… 끝! 공식적으로 계약됐어요. 서밋 가족이 된 걸 환영해요.', 'The deal is done. Show your appreciation and your enthusiasm.', '계약이 끝났습니다. 고마움과 기대감을 전하세요.', '[{"all":["excited"]},{"all":["thank","trust"]},{"all":["looking forward"]},{"all":["thank"],"any":["partnership","opportunity"]}]', 'Thank you for your trust, Greg. We''re really excited to get started.', '믿어 주셔서 감사해요, 그렉. 저희도 시작하게 돼서 정말 기대돼요.', '["Thanks, Greg. I promise you''ll never see a single bug, guaranteed.","Great. I''ll forward it to accounting so they can send the invoice.","Phew. Honestly, I wasn''t sure we''d get here after the discount talk."]', '["감사해요, 그렉. 버그는 단 하나도 없을 거라고 약속드려요, 장담해요.","좋네요. 회계팀에 넘겨서 청구서 보내라고 할게요.","휴. 솔직히 할인 얘기 나왔을 때 여기까지 올 줄 몰랐어요."]', '["Ha, let''s not get carried away. Nobody ships zero bugs.","Uh, sure. Not exactly the champagne moment I expected, but okay.","Really? Ha. Well, glad it worked out."]', '["하, 너무 앞서가진 말죠. 버그 없는 소프트웨어는 없어요.","어, 그래요. 샴페인 터뜨릴 순간치고는 좀 건조하네요.","정말요? 하. 뭐, 잘 풀려서 다행이네요."]', '["Show appreciation and enthusiasm.","Key words: thank you for your trust, excited to get started"]', '["감사와 기대를 표현하세요.","핵심 단어: thank you for your trust, excited to get started"]', 'greg', 'So are we. So, what happens next?', '저희도요. 그럼 다음은 뭐죠?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d12_signing', 3, 'greg', 'Greg wants a clear plan for the next few weeks.', '그렉은 앞으로 몇 주의 분명한 계획을 원합니다.', 'What are the next steps?', '다음 단계는 뭐죠?', 'Give him the plan: both teams meet for the first time next week, then he gets a written update at the end of every week, on Fridays.', '계획을 알려 주세요. 다음 주에 양 팀이 처음 모이고, 그 뒤로는 매주 금요일에 진행 상황을 보냅니다.', '[{"all":["weekly"]},{"all":["next week"]},{"all":["every friday"]},{"all":["status"],"any":["update","report","meeting"]}]', 'Next, we''ll set up a kickoff with both teams next week, and send a weekly status update every Friday.', '다음 주에 양 팀 킥오프를 잡고, 매주 금요일마다 주간 현황 보고를 보내 드릴게요.', '["First, we''ll get both teams together for a kickoff next month, then send a status report every Monday.","We''ll start coding tomorrow, and you''ll have a working version on your desk by the end of next week.","What would you like the next steps to be? We''re flexible, so just tell us what works for your team."]', '["먼저 다음 달에 양 팀이 모여 킥오프를 하고, 매주 월요일마다 현황 보고를 드릴게요.","내일부터 바로 개발을 시작해서, 다음 주 말까지 돌아가는 버전을 드릴게요.","다음 단계는 어떻게 하고 싶으세요? 저희는 맞출 수 있으니 편하신 대로 말씀해 주세요."]', '["Next month? I was hoping we''d get going sooner than that.","By next week? That''s… ambitious. Let''s be realistic here.","I was kind of hoping you''d tell me. You''re the experts."]', '["다음 달이요? 그보다는 빨리 시작했으면 했는데요.","다음 주까지요? 그건… 야심 차네요. 현실적으로 가죠.","그건 그쪽에서 말해 주길 바랐는데요. 전문가시잖아요."]', '["Describe what happens after signing.","Key words: kickoff next week, weekly status update"]', '["서명 후에 무엇을 하는지 말하세요.","핵심 단어: kickoff next week, weekly status update"]', 'greg', 'Perfect. And who''s my point of contact day to day?', '완벽해요. 평소에는 누구에게 연락하면 되죠?'),
  ('d12_signing', 4, 'greg', 'Priya manages the project. You handle the technical side.', '프로젝트는 프리야가 관리하고, 기술 쪽은 당신이 맡습니다.', 'Who should I reach out to day to day?', '평소에는 누구한테 연락하면 돼요?', 'Tell him who handles what on your side.', '당신 쪽에서 누가 무엇을 맡는지 알려 주세요.', '[{"all":["point of contact"]},{"all":["priya"]},{"all":["technical"]}]', 'Priya will be your main point of contact, and I''ll handle any technical questions.', '주 담당자는 프리야이고, 기술적인 질문은 제가 맡을게요.', '["Maya will be your main point of contact, and Priya will cover the technical side.","Just call me anytime, nights and weekends included. I''ll handle everything myself.","You can find the whole team on our website. Anyone there can help you out."]', '["주 담당자는 마야이고, 기술 쪽은 프리야가 맡을 거예요.","언제든 저한테 전화하세요, 밤이든 주말이든요. 제가 다 처리할게요.","저희 웹사이트에 팀 전원이 나와 있어요. 아무한테나 연락하셔도 돼요."]', '["Priya on the technical side? I thought that was you.","Ha, that''s generous, but you''ll burn out. Who''s actually running the project?","Hmm, I''d rather have one name. Who''s my go-to?"]', '["기술 쪽이 프리야요? 그건 당신인 줄 알았는데요.","하, 고맙지만 그러다 지쳐요. 프로젝트는 실제로 누가 맡아요?","음, 이름 하나만 알려 주면 좋겠어요. 누구한테 하면 되죠?"]', '["Name the right people.","Key words: point of contact, Priya, technical questions"]', '["담당자를 정확히 말하세요.","핵심 단어: point of contact, Priya, technical questions"]', 'greg', 'Sounds good. Safe travels home, and thanks again. This was a great trip.', '좋아요. 조심히 돌아가고, 다시 한번 고마워요. 정말 좋은 출장이었어요.'),
  ('d15_expenses', 1, 'linda', 'You bring your trip receipts to Linda in HR.', '출장 영수증을 들고 인사팀 린다에게 갑니다.', 'Hi there! What can I do for you?', '안녕하세요! 뭘 도와줄까요?', 'Tell Linda why you''re here: you have costs from the Ridgeport trip to claim.', '왜 왔는지 말하세요. 리지포트 출장 비용을 청구하려고 합니다.', '[{"all":["expense report"]},{"all":["expenses"]},{"all":["receipts"]},{"any":["reimbursement","reimbursed"]}]', 'Hi Linda. I''d like to submit an expense report for my trip to Ridgeport.', '안녕하세요, 린다. 리지포트 출장 경비 보고서를 제출하고 싶어요.', '["Hi Linda. I''d like to request some vacation days for next month.","Hi, Linda. I''d like to turn in an expense report for my trip to Fairview.","Hi. I paid for a bunch of trip stuff myself. When do I get my money?"]', '["안녕하세요, 린다. 다음 달에 휴가를 좀 신청하고 싶어요.","안녕하세요, 린다. 페어뷰 출장 경비 보고서를 제출하고 싶어요.","안녕하세요. 출장 때 제 돈으로 낸 게 많은데, 돈은 언제 받아요?"]', '["Vacation? Sure. But aren''t those receipts in your hand?","Fairview? That''s here. Don''t you mean Ridgeport?","Okay… let''s start with an expense report, then."]', '["휴가요? 그래요. 근데 손에 든 건 영수증 아니에요?","페어뷰요? 여기잖아요. 리지포트 말하는 거죠?","그래요… 그럼 경비 보고서부터 시작하죠."]', '["Say why you came.","Key words: submit an expense report"]', '["찾아온 이유를 말하세요.","핵심 단어: submit an expense report"]', 'linda', 'Sure! Did you keep all your receipts?', '그럼요! 영수증은 다 챙겼어요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d15_expenses', 2, 'linda', 'You have every receipt except one: the rideshare from the airport.', '영수증이 다 있는데 하나, 공항에서 탄 차량 호출 영수증이 없습니다.', 'Do you have receipts for everything?', '영수증은 다 있어요?', 'Be honest about the one receipt you''re missing, and ask how to handle it.', '없는 영수증 하나를 솔직히 말하고, 어떻게 처리하면 되는지 물어보세요.', '[{"all":["lost"]},{"all":["missing"]},{"all":["cannot","find"]},{"all":["do not have","receipt"]}]', 'Almost. I lost the receipt for the rideshare from the airport. What should I do?', '거의요. 공항에서 탄 차량 호출 영수증을 잃어버렸어요. 어떻게 하면 돼요?', '["Almost. I''m actually missing the hotel receipt. Can I just leave that one out, then?","Yes, everything''s here. I''ll just write the rideshare amount by hand.","Yes, all of them. Do you need the originals, or are copies okay?"]', '["거의요. 호텔 영수증이 없어요. 그럼 그건 그냥 빼도 돼요?","네, 다 있어요. 차량 호출 금액만 손으로 적어 넣을게요.","네, 전부 있어요. 원본이 필요해요, 아니면 사본도 돼요?"]', '["The hotel? Didn''t they email you an itemized receipt?","Handwritten amounts won''t fly, I''m afraid. We need proof.","Copies are fine. So you''ve got every single one, then?"]', '["호텔이요? 항목별 영수증을 메일로 받지 않았어요?","손으로 적은 금액은 안 돼요. 증빙이 있어야 해요.","사본도 돼요. 그럼 하나도 빠짐없이 다 있는 거죠?"]', '["Admit the missing receipt and ask for help.","Key words: lost the receipt, what should I do"]', '["영수증이 없다고 말하고 방법을 물어보세요.","핵심 단어: lost the receipt, what should I do"]', 'linda', 'No problem. The ride app keeps a copy in your trip history. Just download it from there.', '괜찮아요. 앱의 이용 기록에 사본이 있어요. 거기서 내려받으면 돼요.'),
  ('d15_expenses', 3, 'linda', 'Your meals stayed under the $65 limit, and the client dinner went on the company card.', '식비는 65달러 한도 이내였고, 고객 저녁은 법인 카드로 냈습니다.', 'Did you go over the per diem on any day?', '하루라도 일비 한도를 넘은 날 있어요?', 'Answer her question, and mention how the client dinner was paid.', '질문에 답하고, 고객 저녁은 어떻게 결제했는지도 말하세요.', '[{"all":["under"]},{"all":["company card"]},{"all":["within"]}]', 'No, I stayed under the per diem. The client dinner was on the company card.', '아뇨, 한도 안에서 썼어요. 고객 저녁은 법인 카드로 냈어요.', '["No, I stayed under it every day. I put the client dinner on my own card, though.","Just once, at the client dinner. That came to $164 before tip.","Sorry, what''s the per diem again? I just kept all my receipts."]', '["아뇨, 매일 한도 안이었어요. 고객 저녁은 제 개인 카드로 냈지만요.","딱 한 번, 고객 저녁 때요. 팁 빼고 164달러 나왔어요.","죄송한데, 일비가 뭐였죠? 영수증은 그냥 다 챙겼어요."]', '["Your own card? Client meals should''ve gone on the company card.","Wait, didn''t that one go on the company card?","It''s your daily meal limit, sixty-five dollars. Did you go over?"]', '["개인 카드요? 고객 식사는 법인 카드로 했어야죠.","잠깐, 그건 법인 카드로 내지 않았어요?","하루 식비 한도요, 65달러. 넘은 적 있어요?"]', '["Say you kept to the limit.","Key words: stayed under the per diem, company card"]', '["한도를 지켰다고 말하세요.","핵심 단어: stayed under the per diem, company card"]', 'linda', 'Perfect. You''ll be reimbursed by direct deposit. Anything else?', '완벽해요. 계좌로 환급될 거예요. 또 필요한 거 있어요?'),
  ('d15_expenses', 4, 'linda', 'Your first paycheck came in two weeks ago, and it was much lower than the salary in your offer letter.', '2주 전에 첫 급여가 들어왔는데 제안서의 연봉보다 훨씬 적었습니다.', 'Anything else?', '또 필요한 거 있어요?', 'Bring up your first paycheck: it was much smaller than your offer letter made you think. Find out why.', '첫 급여 이야기를 꺼내세요. 제안서를 보고 생각한 것보다 훨씬 적었습니다. 이유를 알아보세요.', '[{"all":["paycheck"]},{"all":["lower"]},{"all":["less"]},{"all":["take home"]},{"all":["net pay"]}]', 'Yes, actually. My paycheck is lower than I expected. Why is that?', '네, 사실 있어요. 급여가 생각보다 적게 들어왔어요. 왜 그런 거예요?', '["Yes. I think payroll made a mistake. My paycheck is way too low.","Yes. My first paycheck still hasn''t come in yet. When will I get paid?","Yes, actually. Can I get my salary raised? It seems really low."]', '["네. 급여팀이 실수한 것 같아요. 월급이 너무 적게 들어왔어요.","네. 첫 급여가 아직 안 들어왔어요. 언제 받을 수 있어요?","네, 사실은요. 연봉 좀 올려 줄 수 있어요? 너무 적은 것 같아요."]', '["A mistake? Let''s look first. It''s probably just taxes.","Hmm, I see a deposit two weeks ago. Did you check your bank?","That''s a conversation for your manager, not me."]', '["실수요? 먼저 봐요. 아마 세금 때문일 거예요.","음, 2주 전에 입금된 게 보이는데요. 은행 확인해 봤어요?","그건 저 말고 매니저랑 할 얘기예요."]', '["Ask about the difference.","Key words: paycheck, lower than I expected"]', '["차이에 대해 물어보세요.","핵심 단어: paycheck, lower than I expected"]', 'linda', 'That''s gross versus net. Federal and state taxes, Social Security, Medicare and your 401(k) all come out before it hits your account.', '세전과 세후의 차이예요. 연방·주 소득세, 사회보장세, 메디케어, 401(k)가 계좌에 들어가기 전에 빠져요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d15_expenses', 5, 'linda', 'Linda checks your benefits page.', '린다가 복리후생 페이지를 확인합니다.', 'Right now you''re putting three percent into your 401(k). The company matches up to six.', '지금 401(k)에 3%를 넣고 있어요. 회사는 6%까지 매칭해 줘요.', 'You don''t want to leave any of the company''s money on the table. Tell her what to change.', '회사가 주는 돈을 하나도 놓치고 싶지 않습니다. 무엇을 바꿀지 말하세요.', '[{"any":["six","6"]},{"all":["full match"]},{"all":["increase"]},{"all":["raise","contribution"]}]', 'Then I''d like to raise my contribution to six percent to get the full match.', '그럼 적립률을 6%로 올려서 매칭을 전부 받고 싶어요.', '["Then I''d like to bump it up to four percent so I get the full match.","Then I''d like to stop contributing for now. I really need more take-home pay.","Great, so the company already puts in six percent for me, right?"]', '["그럼 4%로 올려서 매칭을 전부 받고 싶어요.","그럼 당분간 적립을 멈추고 싶어요. 실수령액이 더 필요해서요.","좋네요, 그럼 회사가 이미 6%를 넣어 주는 거죠?"]', '["Four? The match goes up to six. You''d leave some on the table.","You can, but you''d lose the company match, too.","Not quite. They match what you put in, up to six."]', '["4%요? 매칭은 6%까지예요. 일부를 놓치게 돼요.","그래도 되지만, 회사 매칭도 같이 못 받아요.","그건 아니에요. 본인이 넣는 만큼 6%까지 맞춰 주는 거예요."]', '["Don''t leave free money on the table.","Key words: raise my contribution, six percent, full match"]', '["공짜 돈을 놓치지 마세요.","핵심 단어: raise my contribution, six percent, full match"]', 'linda', 'Smart move. That''s free money. It''ll start with your next paycheck.', '현명해요. 공짜 돈이잖아요. 다음 급여부터 적용돼요.'),
  ('d15_raise', 1, 'maya', 'It is your check-in with Maya. After the Summit deal, you want to talk about your pay.', '마야와의 정기 면담입니다. 서밋 계약 후라 급여 이야기를 하고 싶습니다.', 'Great work on Summit. Greg emailed me to say you were a pleasure to work with. What''s on your mind?', '서밋 건 정말 잘했어요. 그렉이 같이 일하기 정말 좋았다고 메일을 보냈더라고요. 무슨 얘기 하고 싶어요?', 'Thank her for the kind words, then bring up your pay.', '칭찬에 감사하고, 급여 이야기를 꺼내세요.', '[{"any":["compensation","salary","raise","pay"]}]', 'Thanks, Maya. I''d like to discuss my compensation, if now is a good time.', '고마워요, 마야. 지금 괜찮으시면 제 보상 문제를 이야기하고 싶어요.', '["Thanks. Since Greg likes me so much, I think I deserve a raise now.","Thanks, Maya. Nothing much, really. I just wanted to stop by and say hi today.","Thanks, Maya. Honestly, I''ve been looking at some other offers."]', '["고마워요. 그렉이 그렇게 좋아하니까, 이제 연봉 올려 받을 만한 것 같아요.","고마워요, 마야. 별건 없고요. 오늘은 그냥 인사하러 들렀어요.","고마워요, 마야. 솔직히 다른 데서 온 제안을 좀 보고 있어요."]', '["Okay… that''s a bit direct. Let''s talk it through.","Oh. Okay. Well, it''s your time. Anything at all on your mind?","Oh. That''s… not what I expected. Are you unhappy here?"]', '["그래요… 좀 직설적이네요. 차근차근 얘기해 봐요.","아. 그래요. 당신 시간이니까요. 정말 아무 얘기도 없어요?","아. 그건… 예상 못 했네요. 여기서 지내는 게 힘들어요?"]', '["Bring up the topic directly but politely.","Key words: discuss my compensation"]', '["주제를 정중하지만 분명히 꺼내세요.","핵심 단어: discuss my compensation"]', 'maya', 'Of course. Tell me what you''re thinking.', '물론이죠. 생각하는 걸 말해 봐요.'),
  ('d15_raise', 2, 'maya', 'You looked it up: developers with your skills in Fairview make about ten percent more.', '찾아보니 페어뷰에서 비슷한 역량의 개발자는 10%쯤 더 받습니다.', 'Tell me what you''re thinking.', '생각하는 걸 말해 봐요.', 'Make your case with the numbers you found.', '찾아본 숫자로 근거를 대세요.', '[{"all":["market"]},{"all":["below"]},{"all":["research"]}]', 'I''ve done some research, and my salary is about ten percent below the market rate for my role.', '조사를 좀 해 봤는데, 제 연봉이 같은 직무 시장 수준보다 10%쯤 낮아요.', '["I''ve looked into it, and developers with my skills in Fairview make about twenty percent more.","I just feel like I should be making more, given how hard I''ve been working lately.","I found out Derek makes a lot more than I do, and that just doesn''t seem fair to me."]', '["알아봤는데, 페어뷰에서 저 같은 개발자는 20%쯤 더 받더라고요.","요즘 얼마나 열심히 했는지 생각하면 더 받아야 할 것 같아요.","데릭이 저보다 훨씬 많이 받는다는 걸 알았는데, 그건 공평하지 않은 것 같아요."]', '["Twenty? I''d like to see your source. That seems high for Fairview.","I hear you. But do you have anything concrete I can take to HR?","I can''t discuss other people''s pay. Let''s keep this about you."]', '["20%요? 출처 좀 보고 싶네요. 페어뷰치고는 높은데.","무슨 말인지 알아요. 그런데 인사팀에 가져갈 구체적인 근거가 있어요?","다른 사람 급여는 얘기할 수 없어요. 당신 얘기만 해요."]', '["Use data, not feelings.","Key words: research, below the market rate"]', '["감정이 아니라 데이터를 쓰세요.","핵심 단어: research, below the market rate"]', 'maya', 'I appreciate you bringing data. I can''t change it mid-cycle, but I can make a case for you in the next review.', '데이터를 가져와 줘서 고마워요. 주기 중간에는 못 바꾸지만, 다음 평가 때 당신을 위해 근거를 마련할 수 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d15_raise', 3, 'maya', 'You want to know how to earn a bigger raise.', '더 큰 인상을 받으려면 어떻게 해야 하는지 알고 싶습니다.', 'I''ll make a case for you at the next review.', '다음 평가 때 당신을 위해 근거를 마련해 볼게요.', 'Accept that it can''t happen right now, and find out how you could grow into a bigger role.', '지금은 안 된다는 걸 받아들이고, 더 큰 역할로 성장하려면 어떻게 해야 하는지 알아보세요.', '[{"all":["what would it take"]},{"all":["next level"]},{"all":["promotion"]},{"all":["what","need","do"]}]', 'I understand. What would it take to get to the next level?', '알겠어요. 다음 단계로 올라가려면 뭐가 필요할까요?', '["Can''t you make an exception? The next review is so far away.","Okay. So when exactly is the next review, then?","Thanks. Can you promise me a twenty percent raise then?"]', '["예외로 해 주면 안 돼요? 다음 평가는 너무 멀잖아요.","알겠어요. 그럼 다음 평가는 정확히 언제예요?","고마워요. 그럼 그때 20% 인상을 약속해 줄 수 있어요?"]', '["I''m afraid not. Budgets are set for the year.","In the spring. But let''s talk about what gets you there.","I can''t promise a number. But I can tell you what helps."]', '["아쉽지만 안 돼요. 예산이 연 단위로 정해져 있어요.","봄이에요. 그보다 거기까지 가려면 뭐가 필요한지 얘기해요.","숫자는 약속 못 해요. 대신 뭐가 도움이 되는지는 말해 줄 수 있어요."]', '["Ask about the path forward.","Key words: what would it take, next level"]', '["앞으로의 방향을 물어보세요.","핵심 단어: what would it take, next level"]', 'maya', 'Keep owning projects like Summit, and start mentoring new hires. How about we write down three goals?', '서밋 같은 프로젝트를 계속 책임지고, 신입 멘토링도 시작해요. 목표 세 개를 적어 볼까요?'),
  ('d15_raise', 4, 'maya', 'Maya opens a document for your goals.', '마야가 목표를 적을 문서를 엽니다.', 'Let''s write down three goals and check in every month.', '목표 세 개를 적고 매달 확인해요.', 'Agree to the goals, and suggest a checkpoint a quarter from now.', '목표 정리에 동의하고, 석 달 뒤에 한 번 점검하자고 제안하세요.', '[{"any":["three months","3 months","quarter"]},{"all":["sounds good"]},{"all":["progress"]}]', 'That sounds good. Could we review my progress again in three months?', '좋아요. 3개월 뒤에 제 진행 상황을 다시 검토해 볼 수 있을까요?', '["That works. Could we look at my progress again next week, too?","Sure. But could you write the goals for me? You know best.","Fine. But if I hit all three goals, I expect the raise in three months."]', '["좋아요. 다음 주에도 제 진행 상황을 한번 볼 수 있을까요?","좋아요. 근데 목표는 마야가 적어 주실래요? 제일 잘 아시잖아요.","좋아요. 대신 세 개 다 달성하면 3개월 뒤엔 인상해 주셔야 해요."]', '["Next week''s a bit soon to see progress, don''t you think?","I can help, but these should be your goals, not mine.","Let''s not lock in promises yet. Let''s see how it goes."]', '["다음 주면 진행 상황을 보기엔 좀 이르지 않아요?","도와줄 순 있지만, 이건 내 목표가 아니라 당신 목표여야 해요.","아직 약속을 못 박지는 말죠. 어떻게 되는지 봐요."]', '["Agree and set a date to follow up.","Key words: sounds good, review my progress, three months"]', '["동의하고 다시 이야기할 시점을 정하세요.","핵심 단어: sounds good, review my progress, three months"]', 'maya', 'Deal. I''ll put it on the calendar. And seriously, great job this month.', '좋아요. 캘린더에 넣어 둘게요. 그리고 진심으로, 이번 달 정말 잘했어요.'),
  ('d15_sick_call', 1, 'maya', 'It is Monday night. You have a fever and a sore throat, so you call Maya from home.', '월요일 밤입니다. 열이 나고 목이 아파서 집에서 마야에게 전화합니다.', 'Hey, it''s Maya. Everything okay?', '여보세요, 마야예요. 별일 없죠?', 'It''s late. Apologize for the hour, and tell her how you''re feeling.', '늦은 시간입니다. 늦게 전화해 미안하다고 하고, 몸 상태를 말하세요.', '[{"all":["not feeling"]},{"all":["sick"]},{"all":["fever"]},{"all":["under the weather"]},{"all":["sore throat"]}]', 'Hi Maya. Sorry to call so late. I''m not feeling well. I have a fever and a sore throat.', '마야, 안녕하세요. 늦게 전화해서 죄송해요. 몸이 안 좋아요. 열이 나고 목이 아파요.', '["Hey, sorry for the late call. I''ve got a terrible stomach bug and can''t keep food down.","Hi Maya. Sorry, but I think I''m dying here. Worst fever of my life. I can barely talk.","Hi Maya. Quick question about tomorrow''s planning meeting. Is it still at ten?"]', '["늦게 전화해서 죄송해요. 장염이 심하게 걸려서 아무것도 못 먹겠어요.","마야, 죄송한데 저 죽을 것 같아요. 살면서 이런 열은 처음이에요. 말도 겨우 해요.","마야, 안녕하세요. 내일 기획 회의 때문에 잠깐 여쭤볼게요. 아직 10시 맞죠?"]', '["Oh no, a stomach bug? You poor thing.","Oh no! Do you need to go to urgent care?","It is. But it''s late. Is everything okay? You sound awful."]', '["어머, 장염이요? 고생이 많네요.","어머! 응급 진료소라도 가야 하는 거 아니에요?","맞아요. 근데 시간이 늦었잖아요. 괜찮아요? 목소리가 안 좋아요."]', '["Explain how you feel.","Key words: not feeling well, fever"]', '["몸 상태를 설명하세요.","핵심 단어: not feeling well, fever"]', 'maya', 'Oh no, I''m sorry to hear that. Do you want to take tomorrow off?', '어머, 안됐네요. 내일 쉴래요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d15_sick_call', 2, 'maya', 'You need rest, not meetings.', '회의가 아니라 휴식이 필요합니다.', 'Do you want to take tomorrow off?', '내일 쉴래요?', 'You need to rest. Answer her offer.', '쉬어야 합니다. 그녀의 제안에 답하세요.', '[{"all":["sick day"]},{"all":["day off"]},{"all":["take","off"]},{"all":["stay home"]},{"all":["rest"]}]', 'Yes, I think I''m going to take a sick day tomorrow.', '네, 내일은 병가를 내야 할 것 같아요.', '["No, I''ll be fine. I''ll just come in and take it easy.","Maybe I''ll take the whole week off, just in case.","Can I decide in the morning? I''ll text you at nine."]', '["아뇨, 괜찮아요. 그냥 출근해서 살살 할게요.","혹시 모르니 이번 주를 통째로 쉴까 봐요.","아침에 정해도 돼요? 9시에 문자 드릴게요."]', '["Please don''t. You''ll just get everyone else sick.","Let''s start with tomorrow and see how you feel.","I''d rather know now so I can plan. Just take it."]', '["제발 그러지 마요. 다른 사람들까지 아파져요.","일단 내일만 쉬고 상태를 봐요.","계획을 세워야 하니 지금 알고 싶어요. 그냥 쉬어요."]', '["Say you won''t come in tomorrow.","Key words: take a sick day"]', '["내일 출근하지 않겠다고 말하세요.","핵심 단어: take a sick day"]', 'maya', 'Of course. Just rest. Is there anything that needs covering?', '그럼요. 푹 쉬어요. 대신 맡아야 할 일 있어요?'),
  ('d15_sick_call', 3, 'maya', 'You have the phase one planning meeting at ten tomorrow.', '내일 10시에 1단계 기획 회의가 있습니다.', 'Is there anything that needs covering?', '대신 맡아야 할 일 있어요?', 'Your ten o''clock meeting needs someone to run it, and Derek knows the project. Also say how she can still reach you if it''s urgent.', '10시 회의를 맡을 사람이 필요하고, 데릭이 프로젝트를 잘 압니다. 급한 일이 생기면 어떻게 연락이 닿는지도 말하세요.', '[{"all":["derek"]},{"all":["cover"]},{"all":["urgent"]}]', 'Could Derek cover the planning meeting at ten? I''ll check email if anything is urgent.', '데릭이 10시 기획 회의를 대신 맡아 줄 수 있을까요? 급한 일 있으면 메일은 확인할게요.', '["Just the client call at ten. Could Derek take it? I''ll be on email if anything''s urgent.","No, it''s fine. I''ll join the ten o''clock meeting from bed with my camera off.","Can we just cancel the planning meeting? Nobody will miss it anyway, honestly."]', '["10시 고객 통화만요. 데릭이 맡아 줄 수 있을까요? 급한 일 있으면 메일 볼게요.","아니에요, 괜찮아요. 10시 회의는 카메라 끄고 침대에서 들어갈게요.","기획 회의는 그냥 취소하면 안 돼요? 솔직히 아무도 아쉬워 안 할 거예요."]', '["A client call? I thought it was the phase one planning meeting.","Absolutely not. You''re on sick leave. Let''s get you covered.","We can''t cancel it. Phase one starts soon. Who could run it?"]', '["고객 통화요? 1단계 기획 회의인 줄 알았는데요.","절대 안 돼요. 병가잖아요. 대신 맡을 사람을 정해요.","취소는 못 해요. 곧 1단계 시작이잖아요. 누가 진행할 수 있어요?"]', '["Suggest who can take your meeting.","Key words: Derek, cover, urgent"]', '["회의를 누가 대신할지 제안하세요.","핵심 단어: Derek, cover, urgent"]', 'maya', 'I''ll ask Derek. Don''t worry about work. Feel better, okay?', '데릭에게 부탁할게요. 일 걱정은 말고요. 얼른 나아요.'),
  ('d15_sick_call', 4, 'maya', 'Maya is about to hang up.', '마야가 전화를 끊으려 합니다.', 'Feel better, okay? Let me know how you''re doing.', '얼른 나아요, 알았죠? 상태 어떤지 알려 주고요.', 'Say goodbye, and promise to let her know how you''re doing.', '작별 인사를 하고, 몸 상태를 알려 주겠다고 약속하세요.', '[{"all":["keep you posted"]},{"all":["let you know"]},{"any":["thank","thanks"]}]', 'Thanks, Maya. I''ll keep you posted.', '고마워요, 마야. 계속 소식 전할게요.', '["Thanks. See you at ten tomorrow, then.","Fine. Just don''t call me tomorrow, okay?","Thanks. I''ll be back by noon, promise."]', '["고마워요. 그럼 내일 10시에 봬요.","네. 내일은 전화하지 마세요, 알았죠?","고마워요. 점심 전엔 복귀할게요, 약속해요."]', '["No, you won''t. You''re taking the day, remember?","Oh, I wasn''t planning to. Rest up.","Don''t rush it. Take the whole day."]', '["아니, 안 봐요. 내일 쉬기로 했잖아요, 기억나요?","아, 그럴 생각 없었어요. 푹 쉬어요.","서두르지 마요. 하루 통째로 쉬어요."]', '["Say thanks and promise an update.","Key words: thanks, keep you posted"]', '["고맙다고 하고 소식을 전하겠다고 하세요.","핵심 단어: thanks, keep you posted"]', 'maya', 'Take care. Get some sleep.', '몸조심해요. 푹 자고요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d15_trip_report', 1, 'derek', 'It is the Monday standup. Everyone wants to hear about Ridgeport.', '월요일 스탠드업입니다. 모두 리지포트 이야기를 듣고 싶어 합니다.', 'Welcome back! So, how was the trip? Give us the highlights.', '돌아온 걸 환영해요! 그래서 출장 어땠어요? 하이라이트만 들려줘요.', 'Give the team the headline: the deal is done, and the first phase starts next week.', '팀에 핵심을 전하세요. 계약이 끝났고, 첫 단계는 다음 주에 시작합니다.', '[{"all":["signed"]},{"all":["phase one"]},{"all":["closed"]},{"all":["contract"],"any":["done","signed","official"]}]', 'It went great. The contract is signed, and phase one kicks off next week.', '아주 잘 됐어요. 계약 체결됐고, 1단계는 다음 주에 시작해요.', '["Really well. We signed, and phase one starts first thing tomorrow morning.","Long story. The hotel was nice, and the client dinner was amazing.","Honestly, I carried the whole thing. Greg basically loved me."]', '["정말 잘 됐어요. 계약했고, 1단계는 내일 아침부터 바로 시작해요.","얘기하자면 길어요. 호텔 좋았고, 고객 저녁은 끝내줬어요.","솔직히 제가 다 했죠. 그렉이 저를 완전 좋아했어요."]', '["Tomorrow? Wait, I thought kickoff was next week.","Ha, glad you ate well. But did we get the deal?","Ha, okay, hotshot. So we got it?"]', '["내일이요? 잠깐, 킥오프는 다음 주인 줄 알았는데.","하, 잘 먹었다니 다행이네. 근데 계약은 따낸 거예요?","하, 그래요, 잘난 양반. 그래서 따낸 거죠?"]', '["Share the main result first.","Key words: contract is signed, phase one, next week"]', '["핵심 결과부터 말하세요.","핵심 단어: contract is signed, phase one, next week"]', 'derek', 'Awesome! What does that mean for our sprint?', '멋지다! 우리 스프린트엔 어떤 의미예요?'),
  ('d15_trip_report', 2, 'derek', 'The dashboard is due on November first.', '대시보드 마감은 11월 1일입니다.', 'What does that mean for our sprint?', '우리 스프린트엔 어떤 의미예요?', 'Tell the team what to focus on now, and when it''s due.', '이제 무엇에 집중해야 하고 마감이 언제인지 팀에 말하세요.', '[{"all":["priority"]},{"all":["november"]},{"all":["deadline"]},{"all":["dashboard"]}]', 'The dashboard is our top priority now. The deadline is November first.', '이제 대시보드가 최우선이에요. 마감은 11월 1일이에요.', '["Everything else waits. The dashboard is due on November fifteenth.","We all need to work weekends until the dashboard ships, no exceptions.","Not much changes. Let''s keep going with the sprint as planned."]', '["나머지는 다 미뤄요. 대시보드 마감은 11월 15일이에요.","대시보드 나갈 때까지 다들 주말에도 일해야 해요. 예외 없이요.","크게 달라지는 건 없어요. 계획대로 스프린트 계속 가죠."]', '["The fifteenth? My notes say November first.","Whoa. Weekends? Let''s talk to Maya before we promise that.","Really? A signed contract doesn''t change anything?"]', '["15일이요? 제 메모엔 11월 1일인데.","워. 주말에도요? 그런 약속은 마야랑 얘기하고 해요.","정말요? 계약까지 했는데 달라지는 게 없다고요?"]', '["Tell the team what comes first.","Key words: top priority, dashboard, deadline"]', '["무엇이 먼저인지 팀에 알리세요.","핵심 단어: top priority, dashboard, deadline"]', 'derek', 'Got it. Oh, and I fixed that store ID bug while you were out, by the way.', '알겠어요. 아, 그리고 당신 없는 동안 매장 ID 버그 고쳐 뒀어요.'),
  ('d15_trip_report', 3, 'derek', 'Derek covered for you while you were away.', '출장 중에 데릭이 당신 일을 맡아 주었습니다.', 'It was a quick fix. No big deal.', '금방 고친 거예요. 별거 아니에요.', 'He''s playing it down, but he handled your work while you were away. Show you appreciate it.', '별일 아니라지만, 출장 중에 당신 일을 처리해 줬습니다. 고마움을 표하세요.', '[{"any":["thank","thanks"]},{"all":["appreciate"]},{"all":["owe you"]}]', 'Thanks for covering for me. I owe you one.', '대신 맡아 줘서 고마워요. 신세 졌네요.', '["Cool. I was going to fix it when I got back.","Thanks. Somebody should''ve told me it was broken.","Right, no big deal. Anything else for standup?"]', '["그래요. 돌아와서 고치려고 했는데.","고마워요. 고장 났으면 누가 말해 줬어야죠.","그렇죠, 별거 아니죠. 스탠드업 더 할 거 있어요?"]', '["Uh, okay. You''re welcome, I guess.","Hey, nobody needed to tell you. You were traveling.","Ha, sure. A thank-you would''ve been nice, but okay."]', '["어, 그래요. 천만에요, 라고 해야 하나.","에이, 말할 필요 없었죠. 출장 중이었잖아요.","하, 그래요. 고맙다는 말 정도는 들을 줄 알았는데, 뭐."]', '["Show your appreciation.","Key words: thanks for covering, I owe you one"]', '["고마움을 표현하세요.","핵심 단어: thanks for covering, I owe you one"]', 'derek', 'Anytime. Alright, that''s standup. Let''s go build this thing.', '언제든지요. 자, 스탠드업 끝. 이제 만들러 갑시다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_code_review', 1, 'derek', 'Derek rolls his chair over to your desk with his coffee.', '데릭이 커피를 들고 의자를 굴려 당신 자리로 옵니다.', 'Morning! I left a few comments on your pull request. Did you get a chance to look?', '좋은 아침! 풀 리퀘스트에 코멘트 몇 개 남겼어요. 봤어요?', 'You glanced at them, but you''re not done. Be honest.', '훑어보긴 했지만 아직 다 보지는 못했습니다. 솔직하게 말하세요.', '[{"all":["saw"]},{"all":["yet"]},{"all":["went through"]},{"all":["looked"]}]', 'I saw them, but I haven''t gone through all of them yet.', '봤는데, 아직 전부 다 살펴보지는 못했어요.', '["Yeah, I fixed all of them last night already. Take a look!","Not yet. Honestly, I didn''t know you''d left any comments.","I saw them. Honestly, I think most of them are just nitpicks."]', '["네, 어젯밤에 벌써 다 고쳤어요. 한번 봐 주세요!","아직요. 솔직히 코멘트 남기신 줄도 몰랐어요.","봤어요. 솔직히 대부분 그냥 트집 같던데요."]', '["All of them? Huh, I don''t see a new push yet.","Oh! They should be right there on the PR.","Some are. But a couple of them really matter."]', '["다요? 어, 아직 새로 푸시된 게 안 보이는데.","아! PR에 바로 달려 있을 거예요.","몇 개는 그렇죠. 근데 두어 개는 진짜 중요해요."]', '["Say \\"I saw them, but … yet.\\"","Key words: saw, not yet"]', '["\\"I saw them, but … yet.\\"으로 말하세요.","핵심 단어: saw, not yet"]', 'derek', 'No rush. Most of them are just nits.', '급할 거 없어요. 대부분 사소한 거예요.'),
  ('d2_code_review', 2, 'derek', 'He points at one comment on your screen.', '그가 화면의 코멘트 하나를 가리킵니다.', 'The main one is about error handling. Right now, if the payment call fails, we just swallow the error.', '제일 중요한 건 에러 처리예요. 지금은 결제 호출이 실패하면 에러를 그냥 삼켜 버려요.', 'Ask for his advice on a better way to handle it.', '더 나은 처리 방법에 대해 그의 조언을 구하세요.', '[{"all":["suggest"]},{"all":["recommend"]},{"all":["what","instead"]},{"all":["how","handle"]}]', 'Got it. What do you suggest I do instead?', '알겠어요. 대신 어떻게 하는 게 좋을까요?', '["Got it. So I should just delete the try-catch?","But it works fine. The call never fails.","Okay. I copied that part from Priya''s code."]', '["알겠어요. 그럼 try-catch를 그냥 지울까요?","근데 잘 돌아가요. 그 호출은 실패 안 해요.","네. 그 부분은 프리야 코드에서 가져왔어요."]', '["Whoa, no. Then the whole checkout crashes.","Never fails on your laptop. Production is different.","Priya doesn''t write code, man. Let''s just fix it."]', '["워, 아뇨. 그럼 결제가 통째로 죽어요.","당신 노트북에선 안 죽죠. 운영 환경은 달라요.","프리야는 코드 안 짜요. 그냥 고칩시다."]', '["Ask for his suggestion.","Key words: suggest, instead"]', '["그의 제안을 물어보세요.","핵심 단어: suggest, instead"]', 'derek', 'Log it, and show the user a friendly message. Maybe add one retry.', '로그를 남기고 사용자에게 친절한 메시지를 보여 줘요. 재시도도 한 번 넣고요.'),
  ('d2_code_review', 3, 'derek', 'Derek scrolls down to a smaller comment.', '데릭이 작은 코멘트로 스크롤을 내립니다.', 'Also, a nit: some of your variable names are a little vague, like ''data2''.', '그리고 사소한 건데, 변수 이름 몇 개가 좀 모호해요. ''data2'' 같은 거요.', 'He has a point. Tell him how you''ll fix it.', '맞는 말입니다. 어떻게 고칠지 말하세요.', '[{"all":["rename"]},{"all":["fair"]},{"all":["fix"]},{"all":["change"],"any":["names","name","them"]}]', 'That''s fair. I''ll rename them and push an update.', '맞는 말이에요. 이름 바꿔서 업데이트 푸시할게요.', '["Really? ''data2'' is pretty clear if you read the code.","Fair. I''ll rewrite the whole thing from scratch tonight.","That''s fair. Should I rename them in a new PR later?"]', '["그래요? 코드 읽어 보면 ''data2''도 꽤 명확한데요.","맞아요. 오늘 밤에 처음부터 다 새로 짤게요.","맞아요. 이름은 나중에 다른 PR에서 바꿀까요?"]', '["If I have to read the code to get it, it''s not clear.","Whoa, no need. Just rename a few things.","Nah, just do it in this one. It''s quick."]', '["코드를 읽어야 알면 명확한 게 아니죠.","워, 그럴 필요 없어요. 이름 몇 개만 바꿔요.","아뇨, 이번 PR에서 해요. 금방이잖아요."]', '["Agree with \\"That''s fair\\" and say what you will do.","Key words: fair, rename"]', '["\\"That''s fair\\"로 인정하고 할 일을 말하세요.","핵심 단어: fair, rename"]', 'derek', 'Cool. I''ll approve it once the tests pass.', '좋아요. 테스트 통과하면 승인할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_code_review', 4, 'derek', 'He finishes his coffee.', '그가 커피를 마저 마십니다.', 'One more thing: can you add a unit test for the failure case?', '하나 더요. 실패 케이스 단위 테스트 추가해 줄래요?', 'Agree, and give him a deadline: before you leave today.', '그러겠다고 하고, 기한을 알려 주세요. 오늘 퇴근 전입니다.', '[{"all":["end of day"]},{"all":["end of the day"]},{"all":["eod"]},{"all":["today"]},{"all":["this afternoon"]}]', 'Sure thing. I''ll have it done by end of day.', '그럼요. 오늘 퇴근 전까지 끝낼게요.', '["Sure thing. I''ll have it done by end of week.","Sure. I''ll add tests for every case while I''m at it.","Do I have to? The code''s already pretty simple."]', '["그럼요. 이번 주 안에 끝낼게요.","그럼요. 하는 김에 테스트 전부 다 넣을게요.","꼭 해야 돼요? 코드가 꽤 단순한데요."]', '["End of week? I was hoping to merge this today.","Ha, let''s not go crazy. Just the failure case.","Yeah, you do. That''s the bug we just talked about."]', '["이번 주요? 오늘 머지하고 싶었는데.","하하, 너무 나가지 말고요. 실패 케이스만요.","네, 해야 돼요. 방금 얘기한 그 버그잖아요."]', '["Promise a time with \\"by …\\".","Key words: by end of day"]', '["\\"by …\\"로 언제까지 할지 약속하세요.","핵심 단어: by end of day"]', 'derek', 'Awesome. Thanks for being open to feedback. Not everyone is.', '좋아요. 피드백을 잘 받아 줘서 고마워요. 다 그렇진 않거든요.'),
  ('d2_it_laptop', 1, 'sam', 'The IT help desk is a small room full of cables. Sam has three monitors and a cold brew.', 'IT 헬프데스크는 케이블이 가득한 작은 방입니다. 샘 앞에는 모니터 세 대와 콜드브루가 있습니다.', 'Hey, what''s up? You filed the ticket about your laptop, right?', '안녕하세요, 무슨 일이에요? 노트북 건으로 티켓 올리신 분 맞죠?', 'Confirm it, and explain the problem: it locks up whenever you run the tests.', '맞다고 하고 문제를 설명하세요. 테스트를 돌릴 때마다 먹통이 됩니다.', '[{"any":["freezing","freezes","froze","frozen","crashing","crashes","hangs","slow"]}]', 'Yeah, that''s me. My laptop keeps freezing when I run the tests.', '네, 저예요. 테스트를 돌리면 노트북이 자꾸 멈춰요.', '["Yeah, that''s me. My laptop won''t turn on at all since this morning.","Yeah. Honestly, this laptop is garbage. Can I just get a new one?","Yeah, that''s me. My laptop''s been running a little slow lately."]', '["네, 저예요. 오늘 아침부터 노트북이 아예 안 켜져요.","네. 솔직히 이 노트북 완전 고물이에요. 그냥 새 거 주시면 안 돼요?","네, 저예요. 요즘 노트북이 전체적으로 좀 느려요."]', '["Won''t turn on? Then how''d you file the ticket?","Whoa, let''s figure out what''s wrong first.","Slow how? Like, all the time, or when you do something?"]', '["안 켜진다고요? 그럼 티켓은 어떻게 올렸어요?","워, 일단 뭐가 문제인지부터 봐요.","어떻게 느린데요? 항상요, 아니면 뭘 할 때요?"]', '["Use \\"keeps …ing\\" for a problem that repeats.","Key words: keeps freezing"]', '["반복되는 문제에는 \\"keeps …ing\\"를 쓰세요.","핵심 단어: keeps freezing"]', 'sam', 'Ugh, yeah. The older models do that.', '아, 네. 구형 모델이 그래요.'),
  ('d2_it_laptop', 2, 'sam', 'Sam leans back in his chair.', '샘이 의자에 등을 기댑니다.', 'Have you tried restarting it?', '재시작은 해 봤어요?', 'You''ve already done that two times. Tell him.', '벌써 두 번이나 해 봤습니다. 말하세요.', '[{"any":["restarted","rebooted","restart","reboot"]},{"all":["turned it off"]}]', 'Yes, I''ve restarted it twice already.', '네, 벌써 두 번 재시작했어요.', '["Yes, I restarted it once this morning.","Of course I have. I''m a developer, you know.","No, but I''ve closed all my other apps."]', '["네, 오늘 아침에 한 번 재시작했어요.","당연하죠. 저 개발자거든요.","아뇨, 그래도 다른 앱은 다 껐어요."]', '["Just once? Try it one more time for me.","Hey, I have to ask. Everybody says that.","Okay, let''s start with a restart, then."]', '["한 번만요? 한 번만 더 해 봐요.","저기, 물어봐야 하는 거예요. 다들 그렇게 말해요.","그럼 재시작부터 해 봐요."]', '["Use the present perfect: I''ve …ed.","Key words: restarted, twice"]', '["현재완료 I''ve …ed를 쓰세요.","핵심 단어: restarted, twice"]', 'sam', 'Okay, then it''s probably the memory. Let me check.', '그럼 아마 메모리 문제예요. 확인해 볼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_it_laptop', 3, 'sam', 'He types a few commands on your laptop.', '그가 당신 노트북에 명령어 몇 개를 입력합니다.', 'Yeah, you''ve only got eight gigs of RAM. I can swap it for a new one, but it''ll take about an hour to set up.', '네, 램이 8기가밖에 없네요. 새 걸로 바꿔 줄 수 있는데, 세팅하는 데 한 시간쯤 걸려요.', 'You can''t just sit around for an hour. Ask about something to work on until then.', '한 시간 동안 손 놓고 있을 수는 없습니다. 그동안 쓸 게 있는지 물어보세요.', '[{"all":["meantime"]},{"all":["loaner"]},{"all":["while"],"any":["wait","work","waiting"]},{"all":["borrow"]}]', 'That works. Can I use a loaner in the meantime?', '좋아요. 그동안 대여용 노트북 써도 될까요?', '["That works. So it''ll be ready in ten minutes?","An hour? Can''t you just add more RAM to this one?","That works. Can I take the rest of the day off, then?"]', '["좋아요. 그럼 10분이면 준비되는 거죠?","한 시간이요? 그냥 이거에 램만 추가하면 안 돼요?","좋아요. 그럼 오늘은 그냥 퇴근해도 될까요?"]', '["More like an hour. Setup takes a while.","It''s soldered in, sadly. Swapping is faster.","Ha, that''s between you and Maya."]', '["한 시간쯤이요. 세팅이 좀 걸려요.","아쉽게도 램이 납땜돼 있어요. 바꾸는 게 빨라요.","하하, 그건 마야랑 얘기해요."]', '["A \\"loaner\\" is a device you borrow for a while.","Key words: loaner, in the meantime"]', '["loaner는 잠시 빌려 쓰는 기기입니다.","핵심 단어: loaner, in the meantime"]', 'sam', 'Sure, grab this one. Just log in with your company account.', '그럼요, 이거 가져가요. 회사 계정으로 로그인하면 돼요.'),
  ('d2_it_laptop', 4, 'sam', 'Sam hands you a scratched but working laptop.', '샘이 긁힌 자국은 있지만 잘 돌아가는 노트북을 건넵니다.', 'Your new machine should be ready by four. I''ll ping you.', '새 노트북은 네 시까지 준비될 거예요. 메시지 줄게요.', 'Thank him, and check where you''ll get the new one.', '고맙다고 하고, 새 노트북을 어디서 받는지 확인하세요.', '[{"all":["pick"],"any":["up"]},{"all":["come back"]},{"all":["where"]}]', 'Thanks, Sam. Should I pick it up here?', '고마워요, 샘. 여기로 찾으러 오면 돼요?', '["Thanks, Sam. So I''ll come back at two?","Thanks. Can I just keep this one instead?","Thanks, Sam. Should I email you at four?"]', '["고마워요, 샘. 그럼 두 시에 다시 올까요?","고마워요. 그냥 이걸 계속 쓰면 안 돼요?","고마워요, 샘. 네 시에 제가 메일 드릴까요?"]', '["Four, not two. I''ll ping you.","Ha, no. That one''s a loaner. It has to come back.","No need. I''ll ping you when it''s ready."]', '["두 시 말고 네 시요. 메시지 줄게요.","하하, 안 돼요. 그건 대여용이라 돌려줘야 해요.","그럴 필요 없어요. 준비되면 내가 메시지 줄게요."]', '["Use \\"pick it up\\".","Key words: pick up"]', '["pick it up(찾아가다)을 쓰세요.","핵심 단어: pick up"]', 'sam', 'Yep, right here. Or I can drop it off at your desk.', '네, 여기요. 아니면 자리로 갖다줄 수도 있어요.'),
  ('d2_reschedule', 1, 'priya', 'Priya catches you after standup with her laptop open.', '스탠드업이 끝나고 프리야가 노트북을 연 채 당신을 붙잡습니다.', 'Hey, do you have a sec? I want to go over the checkout designs with you. Does one o''clock work?', '저기, 잠깐 시간 있어요? 결제 화면 디자인 같이 보고 싶어서요. 한 시 괜찮아요?', 'One o''clock is taken: IT is looking at your laptop then. Let her know.', '한 시엔 안 됩니다. 그때 IT팀이 노트북을 봐 주기로 했어요. 알려 주세요.', '[{"any":["appointment","conflict","booked"]},{"all":["something","one"]}]', 'Sorry, I have an appointment with IT at one.', '죄송해요, 한 시에 IT팀이랑 약속이 있어요.', '["Sure, one o''clock works great. See you then!","Sorry, I have an appointment with IT at two.","No, I can''t. I''ve got way too much going on."]', '["네, 한 시 좋아요. 그때 봬요!","죄송해요, 두 시에 IT팀이랑 약속이 있어요.","아뇨, 안 돼요. 할 일이 너무 많아서요."]', '["Perfect! I''ll grab us a room.","Oh, at two? So one would work, then?","Oh. Okay, sorry to bother you."]', '["좋아요! 회의실 잡아 둘게요.","아, 두 시요? 그럼 한 시는 되겠네요?","아. 네, 귀찮게 해서 미안해요."]', '["Explain what you already have at one.","Key words: appointment, at one"]', '["한 시에 이미 무엇이 있는지 설명하세요.","핵심 단어: appointment, at one"]', 'priya', 'Oh, no worries.', '아, 괜찮아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d2_reschedule', 2, 'priya', 'She opens her calendar.', '그녀가 캘린더를 엽니다.', 'Could we do it later this afternoon, then?', '그럼 오후 늦게 하면 어때요?', 'Your IT appointment should be over by two. Suggest a time.', 'IT 약속은 두 시 전에 끝날 겁니다. 시간을 제안하세요.', '[{"any":["two","2","2pm","2 00"]},{"all":["after","appointment"]}]', 'Could we move it to two o''clock instead?', '대신 두 시로 옮겨도 될까요?', '["Could we push it to tomorrow morning instead?","Could we move it to one thirty instead?","Sure. Just put something on my calendar."]', '["대신 내일 아침으로 미뤄도 될까요?","대신 한 시 반으로 옮겨도 될까요?","네. 그냥 아무 때나 잡아 주세요."]', '["Hmm, I was hoping to get it done today.","One thirty? Won''t you still be with IT?","Okay, but what time''s good for you?"]', '["음, 오늘 안에 끝내고 싶었는데요.","한 시 반이요? 그때도 IT팀이랑 있지 않아요?","알겠어요, 근데 몇 시가 좋아요?"]', '["Use \\"Could we move it to …?\\"","Key words: move it to two"]', '["\\"Could we move it to …?\\"를 쓰세요.","핵심 단어: move it to two"]', 'priya', 'Two works for me. I''ll send you a calendar invite.', '두 시 좋아요. 캘린더 초대 보낼게요.'),
  ('d2_reschedule', 3, 'priya', 'Priya types the invite.', '프리야가 초대를 입력합니다.', 'How long do you think we need? Usually thirty minutes, but I can book an hour.', '얼마나 필요할 것 같아요? 보통 30분인데, 한 시간 잡아도 돼요.', 'You don''t think this needs a long meeting. Tell her.', '회의가 길 필요는 없을 것 같습니다. 그렇게 말하세요.', '[{"any":["thirty","30","half an hour","half hour"]}]', 'Thirty minutes should be plenty.', '30분이면 충분하고도 남을 거예요.', '["Let''s book the full hour, just in case.","Fifteen minutes, tops. I''m really busy.","Two works for me. Book whatever room."]', '["혹시 모르니 한 시간 다 잡죠.","길어야 15분이요. 제가 많이 바빠서요.","두 시 좋아요. 방은 아무 데나 잡아요."]', '["An hour? Okay, if you think we need it.","Oh. Okay, I''ll try to be quick.","Right, two. But how long do we need?"]', '["한 시간이요? 필요하다면 그렇게 해요.","아. 네, 빨리 끝내 볼게요.","네, 두 시요. 근데 얼마나 필요해요?"]', '["Give a length of time.","Key words: thirty minutes"]', '["시간의 길이를 말하세요.","핵심 단어: thirty minutes"]', 'priya', 'Great. I''ll book the small room by the kitchen.', '좋아요. 탕비실 옆 작은 방을 예약할게요.'),
  ('d2_reschedule', 4, 'priya', 'Your laptop dings. The invite is already there.', '노트북에서 알림이 울립니다. 초대가 벌써 와 있습니다.', 'And if something comes up, just decline it and suggest a new time.', '그리고 무슨 일 생기면 그냥 거절하고 새 시간을 제안해요.', 'Agree, and promise to tell her if anything changes.', '알겠다고 하고, 바뀌는 게 있으면 알려 주겠다고 하세요.', '[{"all":["posted"]},{"all":["let you know"]},{"any":["sounds good","will do","okay","ok","got it"]}]', 'Will do. I''ll keep you posted.', '그럴게요. 계속 상황 알려 드릴게요.', '["Okay. I''ll just skip it if I''m busy.","Sure. I''ll decline it right now, then.","Will do. See you at one, then!"]', '["네. 바쁘면 그냥 안 갈게요.","네. 그럼 지금 바로 거절할게요.","그럴게요. 그럼 한 시에 봬요!"]', '["Um, please don''t just skip it. Let me know.","Wait, why? Didn''t two work for you?","Two, remember? You''ve got IT at one."]', '["음, 그냥 빠지진 말고 알려 줘요.","어, 왜요? 두 시 괜찮다고 하지 않았어요?","두 시예요, 기억하죠? 한 시엔 IT 약속 있잖아요."]', '["Promise to update her.","Key words: keep you posted"]', '["소식을 알려 주겠다고 약속하세요.","핵심 단어: keep you posted"]', 'priya', 'Perfect. See you at two!', '좋아요. 두 시에 봐요!'),
  ('d3_lunch', 1, 'derek', 'It is almost noon. Derek stands up and grabs his jacket.', '거의 정오입니다. 데릭이 일어나 재킷을 집어 듭니다.', 'Hey, a few of us are grabbing tacos from the food truck. Wanna come?', '저기, 몇 명이서 푸드트럭에 타코 사러 가는데. 같이 갈래요?', 'You''d like to go. Say yes and get ready to head out.', '가고 싶습니다. 좋다고 하고 나갈 준비를 하세요.', '[{"any":["love to","sure","yes","yeah","count me in","sounds great","absolutely","why not"]}]', 'Sure, I''d love to. Let me grab my wallet.', '좋아요, 같이 가요. 지갑만 챙길게요.', '["Maybe later? I''ll catch up after this ticket.","Tacos? Ugh, I''m not really into food trucks.","Sure, I''d love to. Is it the diner on Lake Avenue?"]', '["이따 갈까요? 이 티켓 끝내고 따라갈게요.","타코요? 으, 푸드트럭은 별로라서요.","좋아요, 같이 가요. 레이크 애비뉴 다이너예요?"]', '["Your call, but the line gets brutal after twelve.","Oh. Okay, no pressure.","No, the food truck. It''s right out front."]', '["알아서 해요. 근데 열두 시 넘으면 줄이 장난 아니에요.","아. 그래요, 부담 갖지 마요.","아뇨, 푸드트럭이요. 바로 앞에 있어요."]', '["Say yes warmly.","Key words: sure, I''d love to"]', '["반갑게 좋다고 하세요.","핵심 단어: sure, I''d love to"]', 'derek', 'Nice! The line gets long after twelve, so let''s go.', '좋아요! 열두 시 넘으면 줄이 길어지니까 가요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_lunch', 2, 'derek', 'You wait in line at the food truck.', '푸드트럭 앞에서 줄을 서 있습니다.', 'So, any big plans for the weekend?', '그래서 주말에 무슨 큰 계획 있어요?', 'Nothing big is planned, but you''d like to see the park and get to know the town.', '큰 계획은 없지만 공원에도 가 보고 동네를 알아 가고 싶습니다.', '[{"any":["park","explore","exploring","check out","checking out","walk","relax","relaxing","nothing much","rest"]}]', 'Not really. I''m thinking of checking out the park and exploring the city.', '딱히요. 공원에도 가 보고 시내 구경이나 할까 해요.', '["Yeah, I''m flying back to Seoul for the weekend to see my family and friends.","Not really. I''ll probably just catch up on work all weekend.","Not really. Why, are you and the team doing something fun this weekend?"]', '["네, 주말에 가족이랑 친구들 보러 서울에 다녀오려고요.","딱히요. 아마 주말 내내 밀린 일이나 할 것 같아요.","딱히요. 왜요, 팀 사람들이랑 이번 주말에 뭐 재밌는 거 해요?"]', '["Whoa, for two days? That''s a long flight!","Dude, no. It''s your first week. Go outside!","Nah, just chores. But what about you? Anything?"]', '["와, 이틀 동안요? 비행기만 한참인데!","에이, 안 돼요. 첫 주잖아요. 밖에 좀 나가요!","아뇨, 그냥 집안일이요. 근데 당신은요? 뭐 없어요?"]', '["Use \\"I''m thinking of …ing\\".","Key words: check out, park"]', '["\\"I''m thinking of …ing\\"를 쓰세요.","핵심 단어: check out, park"]', 'derek', 'Oh, you should hit the farmers market at Seaside Park on Saturday. It''s great.', '아, 토요일에 시사이드 공원 파머스 마켓에 꼭 가 봐요. 좋아요.'),
  ('d3_lunch', 3, 'derek', 'You sit on a bench with your tacos.', '타코를 들고 벤치에 앉습니다.', 'Where did you live before you moved here?', '여기 이사 오기 전엔 어디 살았어요?', 'Tell him about your hometown, Seoul, and that you came over about a month ago.', '고향이 서울이고, 한 달쯤 전에 왔다고 말하세요.', '[{"any":["from","lived","grew up","moved","korea","seoul"]}]', 'I''m originally from Seoul. I moved here about a month ago.', '원래 서울 출신이에요. 한 달쯤 전에 이사 왔어요.', '["I''m originally from Seoul. I moved here about a year ago.","I live on Maple Street now. It''s a nice neighborhood.","Somewhere pretty far away. It''s kind of a long story."]', '["원래 서울 출신이에요. 1년쯤 전에 이사 왔어요.","지금은 메이플 스트리트에 살아요. 동네 좋아요.","꽤 먼 데서요. 얘기하자면 좀 길어요."]', '["A year? Huh, I thought you just got here.","Nice. But where were you before Fairview?","Oh. Okay, no worries, you don''t have to say."]', '["1년이요? 어, 막 온 줄 알았는데.","좋네요. 근데 페어뷰 오기 전엔요?","아. 그래요, 괜찮아요, 말 안 해도 돼요."]', '["Use \\"I''m originally from …\\".","Key words: originally from, moved"]', '["\\"I''m originally from …\\"를 쓰세요.","핵심 단어: originally from, moved"]', 'derek', 'No way! I''ve always wanted to go.', '정말요? 늘 가 보고 싶었어요.'),
  ('d3_lunch', 4, 'derek', 'Derek wipes salsa off his hands.', '데릭이 손에 묻은 살사를 닦습니다.', 'So how are you liking Fairview so far?', '그래서 페어뷰는 지금까지 어때요?', 'You''re enjoying it, but one American custom still confuses you: how much extra to leave for servers.', '아주 좋지만 미국 관습 하나가 아직 헷갈립니다. 종업원에게 돈을 얼마나 더 남겨야 하는지요.', '[{"any":["tipping","tip","tips","getting used"]}]', 'I like it a lot, but I''m still getting used to tipping.', '정말 좋아요. 근데 팁 문화엔 아직 적응 중이에요.', '["I like it a lot, but I''m still getting used to driving here.","It''s fine, I guess. Kind of boring compared to Seoul.","I like it a lot. I already know how everything works here."]', '["정말 좋아요. 근데 여기서 운전하는 건 아직 적응 중이에요.","그냥 그래요. 서울에 비하면 좀 심심해요.","정말 좋아요. 여기 돌아가는 건 벌써 다 알아요."]', '["Driving? I thought you took the bus.","Ouch. Give it time, it grows on you.","Already? Even the weird stuff? Impressive."]', '["운전이요? 버스 타고 다니는 줄 알았는데.","아야. 시간을 좀 줘 봐요, 점점 좋아져요.","벌써요? 이상한 것까지 다요? 대단하네요."]', '["Use \\"I''m still getting used to …\\".","Key words: getting used to, tipping"]', '["\\"I''m still getting used to …\\"를 쓰세요.","핵심 단어: getting used to, tipping"]', 'derek', 'Ha! Everyone struggles with that. Rule of thumb: fifteen to twenty percent at sit-down places.', '하! 다들 그걸 어려워해요. 대충 기준은 앉아서 먹는 곳이면 15~20퍼센트예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_one_on_one', 1, 'maya', 'Maya has two cups of tea on her desk, one for you.', '마야의 책상에 차 두 잔이 있습니다. 하나는 당신 것입니다.', 'So, first week. How are you settling in?', '그래서, 첫 주네요. 적응은 잘하고 있어요?', 'Things are good, and your teammates have made it easy. Tell her.', '잘 지내고 있고, 팀원들 덕분에 수월했습니다. 말하세요.', '[{"all":["helpful"]},{"all":["going well"]},{"any":["settling","great","good","well"]}]', 'It''s going well. Everyone''s been really helpful.', '잘 되고 있어요. 다들 정말 많이 도와줬어요.', '["Pretty well, though Derek''s code reviews are kind of harsh.","Honestly, I''m a bit lost. Nobody really explains anything.","Good! The tea''s great, by the way. What kind is it?"]', '["잘 지내요. 근데 데릭 코드 리뷰가 좀 가혹하더라고요.","솔직히 좀 헤매요. 아무도 설명을 잘 안 해 줘요.","좋아요! 그나저나 차 맛있네요. 무슨 차예요?"]', '["Oh? He''s thorough, but I''ll keep that in mind.","Oh no. That''s not great. What''s been unclear?","Ha, just chamomile. But how''s work going?"]', '["그래요? 꼼꼼한 편이긴 한데, 기억해 둘게요.","저런. 그건 좀 문제네요. 뭐가 헷갈렸어요?","하하, 그냥 캐모마일이에요. 그래서 일은 어때요?"]', '["Say how it is going, and say something about the people.","Key words: going well, helpful"]', '["어떻게 되고 있는지, 사람들은 어떤지 말하세요.","핵심 단어: going well, helpful"]', 'maya', 'Love to hear that. Derek says you''re picking things up fast.', '반가운 얘기네요. 데릭이 당신이 빨리 배운대요.'),
  ('d3_one_on_one', 2, 'maya', 'She opens a short list on her laptop.', '그녀가 노트북에서 짧은 목록을 엽니다.', 'Let''s talk priorities. For the next two weeks, I''d like you to focus on the checkout bug backlog. Does that make sense?', '우선순위 얘기해 봐요. 앞으로 2주 동안은 결제 버그 백로그에 집중해 줬으면 해요. 이해되죠?', 'You''re on board. Ask where in the backlog to begin.', '동의합니다. 백로그 중 어디부터 시작할지 물어보세요.', '[{"all":["which"],"any":["first","start","bug","bugs"]},{"all":["start with"]},{"all":["priority"]},{"all":["most important"]}]', 'Makes sense. Which bugs should I start with?', '이해했어요. 어떤 버그부터 시작할까요?', '["Makes sense. Should I fix all of them in two days?","Sure. But honestly, I''d rather build new features.","Makes sense. Is it the checkout backlog or login?"]', '["이해했어요. 이틀 안에 다 고치면 될까요?","네. 근데 솔직히 새 기능 만드는 게 더 좋은데요.","이해했어요. 결제 백로그예요, 로그인 쪽이에요?"]', '["Two weeks, not two days! No need to rush.","I hear you. Bugs first, though. Features come later.","Checkout. That''s where the team is right now."]', '["이틀 말고 2주요! 서두를 필요 없어요.","알아요. 그래도 버그가 먼저예요. 기능은 나중에.","결제요. 지금 팀이 거기에 있어요."]', '["Ask \\"Which … should I start with?\\"","Key words: which, start with"]', '["\\"Which … should I start with?\\"로 물어보세요.","핵심 단어: which, start with"]', 'maya', 'Start with anything tagged P1. Priya can walk you through them.', 'P1 태그가 붙은 것부터요. 프리야가 자세히 설명해 줄 거예요.'),
  ('d3_one_on_one', 3, 'maya', 'Maya closes the list and turns to you.', '마야가 목록을 닫고 당신을 봅니다.', 'Is there anything I can do to support you better?', '내가 더 잘 도와줄 수 있는 게 있을까요?', 'You''d like to understand the bigger picture: what the product does and who uses it.', '제품이 무엇을 하고 누가 쓰는지, 큰 그림을 이해하고 싶습니다.', '[{"all":["context"]},{"all":["background"]},{"all":["more","about","product"]}]', 'It would help to get more context about the product and our customers.', '제품이랑 우리 고객에 대해 배경을 더 알면 도움이 될 것 같아요.', '["Honestly, a raise would help a lot. Rent in Fairview is pretty steep.","I think I''m good. Maybe just fewer meetings? Standup feels long.","It would help if Derek reviewed my pull requests a lot faster."]', '["솔직히 연봉 인상이 제일 도움 돼요. 페어뷰 월세가 꽤 비싸서요.","괜찮은 것 같아요. 회의만 좀 줄면요? 스탠드업이 길게 느껴져요.","데릭이 제 풀 리퀘스트를 훨씬 빨리 리뷰해 주면 도움이 될 것 같아요."]', '["Ha. Let''s revisit that at your review, okay?","Really? Standup''s fifteen minutes, tops.","Hmm. Have you told Derek that yourself?"]', '["하하. 그건 평가 때 다시 얘기해요, 알았죠?","그래요? 스탠드업 길어야 15분인데요.","음. 데릭한테 직접 얘기해 봤어요?"]', '["Use \\"It would help to …\\".","Key words: context, product"]', '["\\"It would help to …\\"를 쓰세요.","핵심 단어: context, product"]', 'maya', 'Totally fair. I''ll set you up with a product demo next week.', '충분히 그래요. 다음 주에 제품 데모를 잡아 줄게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_one_on_one', 4, 'maya', 'She writes a note.', '그녀가 메모를 합니다.', 'And how do you like to get feedback? In the moment, or saved up for our one-on-ones?', '그리고 피드백은 어떻게 받는 게 좋아요? 그때그때, 아니면 모아 뒀다가 1:1에서?', 'You don''t like waiting a week to find out what you did wrong. Tell her.', '잘못한 걸 일주일 뒤에야 아는 건 싫습니다. 그렇게 말하세요.', '[{"any":["right away","in the moment","immediately","as soon as","real time","right then"]}]', 'I''d prefer to hear it right away, in the moment.', '그때그때 바로바로 듣는 게 더 좋아요.', '["I''d prefer to save it up for our one-on-ones, if possible.","Honestly, I''d prefer not to get much feedback at all.","I''d prefer it in writing, so I can show it to HR."]', '["되도록이면 모아 뒀다가 1:1에서 듣고 싶어요.","솔직히 피드백은 별로 안 받고 싶어요.","인사팀에 보여 줄 수 있게 글로 받고 싶어요."]', '["Okay, so you''d rather wait a week to hear it?","Hmm. Everyone needs some, though.","HR? It''s not that kind of feedback, Jun."]', '["그럼 일주일 기다렸다가 듣는 게 좋다는 거죠?","음. 그래도 다들 조금은 필요해요.","인사팀이요? 그런 피드백이 아니에요, 준."]', '["Use \\"I''d prefer …\\".","Key words: right away"]', '["\\"I''d prefer …\\"를 쓰세요.","핵심 단어: right away"]', 'maya', 'Noted.', '알겠어요.'),
  ('d3_one_on_one', 5, 'maya', 'The 1:1 is almost over.', '1:1이 거의 끝나 갑니다.', 'Let''s keep this weekly. Same time next Wednesday?', '이거 매주 해요. 다음 주 수요일 같은 시간 어때요?', 'That schedule suits you. Say so.', '그 일정이 좋습니다. 그렇게 말하세요.', '[{"any":["works","sounds good","perfect","sure","great","see you"]}]', 'Sounds good. Same time works for me.', '좋아요. 같은 시간 괜찮아요.', '["Sounds good. See you next Thursday, then.","Weekly? Isn''t that a bit much, honestly?","Sure! I''ll bring the tea next time."]', '["좋아요. 그럼 다음 주 목요일에 봬요.","매주요? 솔직히 좀 많지 않아요?","좋아요! 다음엔 제가 차 가져올게요."]', '["Wednesday, actually. Same as today.","Trust me, it helps. Let''s try it.","Ha, deal. So Wednesday works?"]', '["수요일이에요. 오늘이랑 같은 요일.","믿어 봐요, 도움 돼요. 일단 해 봐요.","하하, 좋아요. 그래서 수요일 괜찮아요?"]', '["Say the time works for you.","Key words: works for me"]', '["그 시간이 괜찮다고 하세요.","핵심 단어: works for me"]', 'maya', 'Great. Keep up the good work!', '좋아요. 계속 잘해 줘요!'),
  ('d3_planning', 1, 'priya', 'The whole team is in the meeting room. A board full of tickets is on the screen.', '팀 전원이 회의실에 있습니다. 화면에 티켓이 가득한 보드가 떠 있습니다.', 'Welcome to your first sprint planning! We''ll go through the tickets and estimate each one in story points.', '첫 스프린트 플래닝에 온 걸 환영해요! 티켓을 하나씩 보면서 스토리 포인트로 추정할 거예요.', 'Teams measure these differently. Find out how this team sizes its work.', '팀마다 기준이 다릅니다. 이 팀은 일의 크기를 어떻게 매기는지 알아보세요.', '[{"all":["story point"]},{"all":["point"],"any":["what","mean"]},{"all":["points"],"any":["what","mean"]}]', 'Quick question: what does one story point mean for this team?', '잠깐 질문이요. 이 팀에서 스토리 포인트 1은 어느 정도예요?', '["Quick question: how many tickets do we usually finish a sprint?","Honestly, story points are kind of pointless. Can we use hours?","Got it. I''ve used story points before, so I''ll just jump in."]', '["잠깐 질문이요. 한 스프린트에 보통 티켓을 몇 개 끝내요?","솔직히 스토리 포인트는 좀 쓸모없지 않아요? 시간으로 하면 안 돼요?","알겠어요. 스토리 포인트는 써 봤으니까 바로 할게요."]', '["Depends on the sprint. You''ll get a feel for it!","Ha, that''s a debate for another day.","Great, but every team''s scale is a bit different."]', '["스프린트마다 달라요. 곧 감이 올 거예요!","하하, 그건 다음에 토론해요.","좋아요. 근데 팀마다 기준이 좀 달라요."]', '["Ask \\"What does … mean?\\"","Key words: story point, mean"]', '["\\"What does … mean?\\"으로 물어보세요.","핵심 단어: story point, mean"]', 'priya', 'Good question. It''s about effort and complexity, not hours. A one is tiny, an eight is big.', '좋은 질문이에요. 시간이 아니라 노력과 복잡도예요. 1은 아주 작고 8은 커요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d3_planning', 2, 'priya', 'Priya opens the first ticket.', '프리야가 첫 번째 티켓을 엽니다.', 'First ticket: add a ''save card for later'' checkbox to checkout. What would you estimate?', '첫 번째 티켓: 결제 화면에 ''카드 저장'' 체크박스 추가. 얼마로 추정해요?', 'Give your estimate, a three, and your reasoning: easy screen work, but card data needs thorough checking.', '추정치 3을 말하고 이유를 대세요. 화면 작업은 쉽지만 카드 데이터라 꼼꼼히 확인해야 합니다.', '[{"any":["one","two","three","five","eight","1","2","3","5","8"]}]', 'I''d say a three. The UI is simple, but we need to test it carefully.', '3이요. UI는 간단한데 테스트는 꼼꼼히 해야 해요.', '["I''d say an eight. The UI is simple, but testing will take a bit.","Maybe three hours? It''s just one checkbox on the page.","That''s a one. It''s just a checkbox. No real testing needed."]', '["8이요. UI는 간단한데 테스트에 시간이 좀 걸려요.","세 시간쯤요? 페이지에 체크박스 하나잖아요.","그건 1이죠. 체크박스 하나라 테스트도 필요 없어요."]', '["An eight? That''s our biggest. For a checkbox?","Points, not hours, remember?","Hmm, it''s people''s card info, though. Risky."]', '["8이요? 제일 큰 건데요. 체크박스 하나에?","시간 말고 포인트요, 기억하죠?","음, 그래도 사람들 카드 정보잖아요. 위험해요."]', '["Start with \\"I''d say a …\\" and a number.","Key words: I''d say, three"]', '["\\"I''d say a …\\"와 숫자로 시작하세요.","핵심 단어: I''d say, three"]', 'priya', 'Derek said three too. Three it is.', '데릭도 3이래요. 3으로 하죠.'),
  ('d3_planning', 3, 'priya', 'The next ticket has only one line: "Refunds sometimes fail."', '다음 티켓에는 딱 한 줄뿐입니다: "환불이 가끔 실패함."', 'Next one''s the refund bug. It''s pretty vague. Anybody want to take it?', '다음은 환불 버그예요. 꽤 모호해요. 맡을 사람?', 'Volunteer for it, but say what you''d need before you start.', '맡겠다고 나서되, 시작하기 전에 필요한 게 있다고 말하세요.', '[{"all":["details"]},{"all":["more info"]},{"all":["information"]},{"all":["clarify"]},{"all":["take it"]}]', 'I can take it, but I''ll need more details first.', '제가 맡을게요. 근데 먼저 세부 정보가 더 필요해요.', '["I''ll take it. Should be fixed by tomorrow, easy.","Not me. That ticket is way too vague to work on.","I can take it. What''s the story point estimate?"]', '["제가 할게요. 내일까지 쉽게 고칠 수 있어요.","전 빠질게요. 그 티켓은 너무 모호해서 못 해요.","제가 맡을게요. 스토리 포인트는 몇이에요?"]', '["Bold! It''s only one line, though. You sure?","Fair, but someone has to take it.","We haven''t estimated it yet. It''s that vague."]', '["자신만만하네요! 근데 딱 한 줄인데, 괜찮겠어요?","그렇긴 한데, 누군가는 맡아야 해요.","아직 추정 안 했어요. 그만큼 모호해요."]', '["Volunteer with \\"I can take it, but …\\".","Key words: take it, more details"]', '["\\"I can take it, but …\\"로 자원하세요.","핵심 단어: take it, more details"]', 'priya', 'Love it. I''ll add the customer''s steps to the ticket.', '좋아요. 고객이 겪은 단계를 티켓에 추가할게요.'),
  ('d3_planning', 4, 'priya', 'The sprint board is full now.', '이제 스프린트 보드가 꽉 찼습니다.', 'Okay, I think we''re at capacity. Does anyone feel like this sprint is too much?', '자, 이제 꽉 찬 것 같아요. 이번 스프린트가 너무 많다고 느끼는 사람 있어요?', 'You think the team can handle it. Say so.', '팀이 해낼 수 있다고 생각합니다. 그렇게 말하세요.', '[{"any":["doable","manageable","reasonable","fine","okay","good"]}]', 'It looks doable to me.', '제가 보기엔 할 만해요.', '["Way too much, honestly.","Yes, it looks fine to me.","Sure, I''ll take more."]', '["솔직히 너무 많아요.","네, 괜찮아 보여요.","네, 더 맡을게요."]', '["Oh? Which part feels like too much?","Wait, yes it''s too much, or it''s fine?","Ha, easy, tiger. It''s your first sprint."]', '["그래요? 어느 부분이 많아요?","잠깐, 많다는 거예요, 괜찮다는 거예요?","하하, 진정해요. 첫 스프린트잖아요."]', '["Use \\"It looks … to me.\\"","Key words: doable"]', '["\\"It looks … to me.\\"를 쓰세요.","핵심 단어: doable"]', 'priya', 'Great. Let''s lock it in. Thanks, everyone!', '좋아요. 이걸로 확정해요. 다들 고마워요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_benefits', 1, 'linda', 'Linda has a folder with your name on it.', '린다 앞에 당신 이름이 적힌 폴더가 있습니다.', 'Hi! Thanks for coming by. We just need to finish your new-hire paperwork. Did you fill out your W-4 yet?', '안녕하세요! 와 줘서 고마워요. 신입 사원 서류만 마무리하면 돼요. W-4는 작성했어요?', 'You haven''t, and you don''t really know what that form does. Ask.', '아직 안 했고, 그 양식이 뭘 하는 건지 잘 모릅니다. 물어보세요.', '[{"all":["what"],"any":["for","does","is"]}]', 'Not yet. What''s the W-4 for, exactly?', '아직요. W-4는 정확히 뭐 하는 거예요?', '["Yes, I sent it in last week.","Not yet. Can you just fill it out for me?","Not yet. Is that the health insurance form?"]', '["네, 그건 지난주에 이미 제출했어요.","아직요. 그냥 대신 써 주시면 안 돼요?","아직요. 그게 건강보험 양식이에요?"]', '["Hmm, I don''t see it in here. Are you sure?","I can''t, sorry. It has to come from you.","No, that comes next. This one''s different."]', '["음, 여기엔 없는데요. 확실해요?","죄송해요, 그건 안 돼요. 본인이 직접 써야 해요.","아뇨, 그건 다음이에요. 이건 다른 거예요."]', '["Ask \\"What''s … for?\\"","Key words: what''s it for"]', '["\\"What''s … for?\\"로 물어보세요.","핵심 단어: what''s it for"]', 'linda', 'It tells payroll how much federal income tax to withhold from each paycheck.', '급여팀에 매 급여에서 연방 소득세를 얼마나 떼어 둘지 알려 주는 양식이에요.'),
  ('d4_benefits', 2, 'linda', 'She puts two brochures in front of you.', '그녀가 안내 책자 두 개를 당신 앞에 놓습니다.', 'Next, health insurance. The PPO costs more per paycheck. The HMO is cheaper, but you need a referral to see a specialist.', '다음은 건강보험이에요. PPO는 급여마다 더 많이 나가요. HMO는 싸지만 전문의를 보려면 의뢰서가 필요해요.', 'You want to know which plan makes you pay less yourself before the insurance kicks in.', '보험이 적용되기 전에 본인이 내야 하는 돈이 어느 쪽이 더 적은지 알고 싶습니다.', '[{"all":["deductible"]},{"all":["which","plan"]},{"all":["difference"]}]', 'Which plan has the lower deductible?', '어느 플랜이 공제액이 더 낮아요?', '["Which plan has the lower monthly cost?","So the HMO doesn''t need referrals, right?","Whichever one''s cheaper. I never get sick."]', '["어느 플랜이 매달 더 싸요?","그럼 HMO는 의뢰서가 필요 없는 거죠?","그냥 싼 걸로 할게요. 전 안 아파요."]', '["The HMO, like I said. Cheaper per paycheck.","No, it''s the other way around. The HMO needs them.","Ha, nobody plans to. Want the details first?"]', '["말했듯이 HMO요. 급여마다 덜 나가요.","아뇨, 반대예요. HMO가 필요해요.","하하, 아프려고 아픈 사람은 없죠. 자세히 들어 볼래요?"]', '["A \\"deductible\\" is what you pay before insurance starts paying.","Key words: which plan, deductible"]', '["deductible은 보험이 지급하기 전에 내가 먼저 내는 금액입니다.","핵심 단어: which plan, deductible"]', 'linda', 'The PPO. Its deductible is five hundred dollars. The HMO''s is fifteen hundred.', 'PPO요. 공제액이 500달러예요. HMO는 1,500달러고요.'),
  ('d4_benefits', 3, 'linda', 'You look at the monthly costs.', '월 비용을 살펴봅니다.', 'A lot of people your age go with the HMO. But if you see doctors a lot, the PPO is worth it. Which one would you like?', '또래분들은 HMO를 많이 골라요. 근데 병원을 자주 가면 PPO가 값을 해요. 어느 걸로 할래요?', 'Pick the plan where you don''t need anyone''s permission to see a specialist, and say why.', '전문의를 볼 때 누구 허락도 필요 없는 플랜을 고르고 이유를 말하세요.', '[{"any":["ppo","hmo"]}]', 'I''ll go with the PPO. I''d like to choose my own doctors.', 'PPO로 할게요. 의사를 제가 직접 고르고 싶어요.', '["I''ll go with the HMO. I''d like to choose my own doctors.","I''ll take the PPO. I''ll see doctors less, so it''s worth it.","Can I sign up for both of them, just to be safe?"]', '["HMO로 할게요. 의사를 제가 직접 고르고 싶어요.","PPO로 할게요. 병원은 별로 안 가니까 그게 낫겠어요.","혹시 모르니까 둘 다 가입하면 안 돼요?"]', '["With the HMO, you''d need a referral first, though.","Hmm, the PPO pays off if you go a lot, though.","Ha, no. Just one plan per person."]', '["HMO는 먼저 의뢰서가 필요한데요.","음, PPO는 병원을 자주 가야 이득인데요.","하하, 안 돼요. 한 사람당 하나예요."]', '["Choose with \\"I''ll go with …\\".","Key words: I''ll go with, PPO or HMO"]', '["\\"I''ll go with …\\"로 고르세요.","핵심 단어: I''ll go with, PPO 또는 HMO"]', 'linda', 'Good choice. Open enrollment closes in thirty days, so you can still change your mind.', '좋은 선택이에요. 가입 기간이 30일 뒤에 끝나니까 그 전에는 바꿀 수 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_benefits', 4, 'linda', 'Linda turns to the last page.', '린다가 마지막 장을 넘깁니다.', 'Last thing: the 401(k). The company matches up to four percent. Want to sign up?', '마지막으로 401(k)요. 회사가 4퍼센트까지 매칭해 줘요. 가입할래요?', 'Sign up, and put in exactly enough to get all of the company''s money.', '가입하세요. 회사가 주는 돈을 전부 받을 만큼만 정확히 넣으세요.', '[{"all":["match"]},{"any":["four percent","4 percent","4%","contribute","enroll"]}]', 'Definitely. I''ll contribute four percent to get the full match.', '물론이죠. 매칭을 다 받게 4퍼센트 넣을게요.', '["Definitely. I''ll contribute two percent and get the full match.","Maybe later. I''d rather keep all my paycheck for now.","Sure. Can I take the money out whenever I want?"]', '["물론이죠. 2퍼센트 넣어서 매칭을 다 받을게요.","나중에 할게요. 지금은 월급을 다 받고 싶어요.","네. 그 돈은 아무 때나 뺄 수 있어요?"]', '["Two percent only gets you half the match, though.","You''d be leaving money on the table.","Not without a penalty. It''s for retirement."]', '["2퍼센트면 매칭을 절반밖에 못 받아요.","받을 수 있는 돈을 그냥 두고 가는 건데요.","벌금 없이는 안 돼요. 은퇴 자금이거든요."]', '["Say how much you will contribute.","Key words: four percent, full match"]', '["얼마를 넣을지 말하세요.","핵심 단어: four percent, full match"]', 'linda', 'Smart move. That''s free money. And you''re all set!', '현명해요. 공짜 돈이니까요. 이제 다 됐어요!'),
  ('d4_deadline', 1, 'priya', 'Priya stops by the meeting room door with her coffee.', '프리야가 커피를 들고 회의실 문 앞에 멈춰 섭니다.', 'How''s the refund bug coming along? Are we still on track for Friday?', '환불 버그는 어떻게 돼 가요? 금요일 일정은 아직 맞출 수 있어요?', 'It''s not going as fast as you hoped. Don''t hide it.', '생각만큼 빨리 진행되지 않고 있습니다. 숨기지 마세요.', '[{"all":["longer"]},{"any":["behind","delayed","tricky","complicated","harder"]}]', 'Honestly, it''s taking longer than I expected.', '솔직히 생각보다 오래 걸리고 있어요.', '["Yep, totally on track. No problems at all.","Not great. Whoever wrote that code made a mess.","It''s going. Why, did the deadline move up?"]', '["네, 완전 일정대로예요. 아무 문제 없어요.","별로예요. 그 코드 짠 사람이 엉망으로 짰어요.","하고는 있어요. 왜요, 마감이 당겨졌어요?"]', '["Great! So I can tell the client Friday?","Okay... but where are you with it?","No, still Friday. Are we on track?"]', '["좋아요! 그럼 고객한테 금요일이라고 해도 되죠?","음… 그래서 어디까지 됐어요?","아뇨, 그대로 금요일이에요. 맞출 수 있어요?"]', '["Use \\"It''s taking longer than …\\".","Key words: taking longer"]', '["\\"It''s taking longer than …\\"을 쓰세요.","핵심 단어: taking longer"]', 'priya', 'Okay. Thanks for flagging it early.', '알겠어요. 일찍 알려 줘서 고마워요.'),
  ('d4_deadline', 2, 'priya', 'She sits down across from you.', '그녀가 맞은편에 앉습니다.', 'What''s slowing you down?', '뭐 때문에 늦어지고 있어요?', 'Explain the cause: the code is years old, and nothing checks it automatically.', '원인을 설명하세요. 몇 년 된 코드인데, 자동으로 확인해 주는 장치가 하나도 없습니다.', '[{"any":["tests","test","legacy","old code","documentation"]}]', 'The bug is in some old code, and there are no tests for it.', '버그가 오래된 코드에 있는데, 테스트가 하나도 없어요.', '["Derek''s been too busy to review anything I send him.","The bug is in brand-new code, and the tests keep failing.","Honestly, I''ve been really tired this week. New city and all."]', '["데릭이 바빠서 제가 보낸 걸 리뷰를 못 해 줘요.","버그가 완전 새 코드에 있는데 테스트가 계속 실패해요.","솔직히 이번 주에 너무 피곤했어요. 새 도시라서요."]', '["Hmm, I''ll talk to him. But what about the bug itself?","New code? I thought refunds were the old system.","That''s totally normal. But is something blocking the bug?"]', '["음, 얘기해 볼게요. 그래도 버그 자체는 어때요?","새 코드요? 환불은 옛날 시스템인 줄 알았는데.","충분히 그럴 수 있죠. 근데 버그 쪽에 막힌 게 있어요?"]', '["Say where the bug is and what is missing.","Key words: old code, no tests"]', '["버그가 어디 있고 무엇이 없는지 말하세요.","핵심 단어: old code, no tests"]', 'priya', 'Ah, the legacy stuff. That makes sense.', '아, 레거시 코드군요. 그럴 만하네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_deadline', 3, 'priya', 'Priya taps her pen on the table.', '프리야가 펜으로 테이블을 톡톡 칩니다.', 'So what do you need? More time?', '그래서 뭐가 필요해요? 시간이 더 필요해요?', 'You''d need until next Tuesday. Ask for that.', '다음 주 화요일까지는 필요합니다. 그렇게 해 줄 수 있는지 물어보세요.', '[{"all":["push"],"any":["deadline","tuesday","back"]},{"all":["tuesday"]},{"all":["extend"]},{"all":["more time"]},{"all":["extension"]}]', 'Could we push the deadline to next Tuesday?', '마감을 다음 주 화요일로 미룰 수 있을까요?', '["Could we push the deadline to next Thursday?","Yes. I need until Tuesday, no matter what.","Could you give the ticket to Derek instead?"]', '["마감을 다음 주 목요일로 미룰 수 있을까요?","네. 무슨 일이 있어도 화요일까지는 필요해요.","그 티켓 그냥 데릭한테 넘겨도 될까요?"]', '["Thursday? That''s a whole week late.","Whoa. Let''s talk options before \\"no matter what.\\"","Hmm, he''s swamped. Let''s figure this out together."]', '["목요일이요? 꼬박 일주일 늦는 건데요.","워. ''무슨 일이 있어도'' 전에 방법부터 얘기해요.","음, 데릭은 일이 꽉 찼어요. 같이 방법을 찾아봐요."]', '["Use \\"Could we push … to …?\\"","Key words: push the deadline, Tuesday"]', '["\\"Could we push … to …?\\"를 쓰세요.","핵심 단어: push the deadline, Tuesday"]', 'priya', 'Hmm. Tuesday''s tough. The client demo is on Monday.', '음. 화요일은 힘들어요. 고객 데모가 월요일이거든요.'),
  ('d4_deadline', 4, 'priya', 'She thinks for a moment.', '그녀가 잠시 생각합니다.', 'Is there any way to cut the scope and ship part of it on Friday?', '범위를 줄여서 금요일에 일부라도 내보낼 방법은 없을까요?', 'Offer a split: the card payments part on Friday, everything else after.', '나눠서 하자고 제안하세요. 카드 결제 부분은 금요일에, 나머지는 그 뒤에요.', '[{"all":["first"]},{"all":["next week"]},{"all":["rest","later"]},{"all":["phase"]}]', 'We could ship the fix for card payments first and do the rest next week.', '카드 결제 수정부터 먼저 내보내고 나머지는 다음 주에 할 수 있어요.', '["I could just stay late every night this week and ship all of it Friday.","We could skip the tests for now and ship the whole fix Friday.","We could ship the fix for gift cards first and do the rest on Tuesday."]', '["제가 이번 주 매일 밤 늦게까지 남아서 금요일에 전부 내보낼게요.","일단 테스트는 건너뛰고 금요일에 전체 수정을 내보내면 돼요.","기프트 카드 수정부터 먼저 내보내고 나머지는 화요일에 해요."]', '["Please don''t. I''d rather cut scope than burn you out.","No tests on refunds? That scares me a little.","Gift cards? I thought card payments were the big one."]', '["그러지 마요. 무리하느니 범위를 줄이는 게 나아요.","환불에 테스트가 없다고요? 그건 좀 무서운데요.","기프트 카드요? 카드 결제가 제일 큰 거 아니었어요?"]', '["Suggest with \\"We could … first and … next week.\\"","Key words: first, next week"]', '["\\"We could … first and … next week.\\"로 제안하세요.","핵심 단어: first, next week"]', 'priya', 'That''s a great compromise. Let''s do that. I''ll update the ticket.', '좋은 절충안이에요. 그렇게 해요. 티켓을 고칠게요.'),
  ('d4_pto', 1, 'maya', 'You knock on the frame of Maya''s open door.', '마야의 열린 문틀을 똑똑 두드립니다.', 'Hey, come on in. What''s up?', '어, 들어와요. 무슨 일이에요?', 'Your friend''s wedding is coming up. Say what you came to ask about, briefly.', '친구 결혼식이 다가옵니다. 무엇 때문에 왔는지 짧게 말하세요.', '[{"any":["time off","pto","vacation","day off","days off","leave"]}]', 'I had a quick question about time off.', '휴가에 대해 잠깐 여쭤볼 게 있어서요.', '["I need a week off next month. Is that cool?","I had a quick question about my paycheck.","Sorry, is now a bad time? I can come back."]', '["다음 달에 일주일 쉬어야 하는데 괜찮죠?","급여에 대해 잠깐 여쭤볼 게 있어서요.","죄송해요, 지금 바쁘세요? 이따 다시 올게요."]', '["A whole week? Let''s talk. What''s going on?","Sure. Though Linda in HR knows that best.","No, you''re fine. Come in. What''s up?"]', '["일주일 통째로요? 얘기해 봐요. 무슨 일인데요?","그래요. 근데 그건 인사팀 린다가 제일 잘 알아요.","아뇨, 괜찮아요. 들어와요. 무슨 일이에요?"]', '["Use \\"I had a quick question about …\\".","Key words: question, time off"]', '["\\"I had a quick question about …\\"을 쓰세요.","핵심 단어: question, time off"]', 'maya', 'Sure, shoot.', '그럼요, 말해 봐요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d4_pto', 2, 'maya', 'Maya turns away from her screen.', '마야가 화면에서 몸을 돌립니다.', 'What do you want to know?', '뭐가 궁금해요?', 'Start with the basics: how much paid vacation you get each year.', '기본부터 물어보세요. 1년에 유급 휴가를 얼마나 받는지요.', '[{"all":["how many"],"any":["days","pto","vacation"]},{"all":["how much"],"any":["pto","time off","vacation"]}]', 'How many PTO days do we get a year?', '유급휴가는 1년에 며칠이에요?', '["How many sick days do we get a year?","How many PTO days does Derek get a year?","Is it true we can take unlimited PTO here?"]', '["병가는 1년에 며칠이에요?","데릭은 유급휴가가 1년에 며칠이에요?","유급휴가 무제한이라는 게 사실이에요?"]', '["Five, but that''s just for when you''re sick.","That''s between me and Derek. What about yours?","Unlimited? Where''d you hear that?"]', '["5일이요. 근데 그건 아플 때만 쓰는 거예요.","그건 나랑 데릭 사이 일이죠. 당신 건요?","무제한이요? 어디서 들었어요?"]', '["Start with \\"How many …\\".","Key words: how many, PTO days"]', '["\\"How many …\\"로 시작하세요.","핵심 단어: how many, PTO days"]', 'maya', 'Fifteen days of PTO, plus ten company holidays. It builds up a little every paycheck.', '유급휴가 15일에 회사 휴일이 10일이에요. 급여마다 조금씩 쌓여요.'),
  ('d4_pto', 3, 'maya', 'She smiles.', '그녀가 웃습니다.', 'Why, got a trip coming up?', '왜요, 여행 계획 있어요?', 'Explain: a friend''s wedding next month. Ask for two days.', '다음 달에 친구 결혼식이 있다고 설명하고, 이틀을 쉬어도 되는지 물어보세요.', '[{"all":["wedding"]},{"all":["married"]},{"all":["two days"]},{"all":["take","off"]}]', 'Yeah, my friend is getting married next month. Could I take two days off?', '네, 다음 달에 친구가 결혼해요. 이틀 쉬어도 될까요?', '["Yeah, my friend is getting married next week. Could I take two days off?","Yeah, a wedding next month. I''m taking two weeks off for it.","Kind of. It''s personal, but I''ll need some days off next month."]', '["네, 다음 주에 친구가 결혼해요. 이틀 쉬어도 될까요?","네, 다음 달에 결혼식이 있어요. 2주 쉴 거예요.","비슷해요. 개인적인 일인데 다음 달에 며칠 쉬어야 해요."]', '["Next week? That''s short notice, but okay.","Two weeks? Whoa, let''s talk about that.","No need to share. But how many days are we talking?"]', '["다음 주요? 좀 급하긴 한데, 알겠어요.","2주요? 워, 그건 얘기 좀 해 봐요.","얘기 안 해도 돼요. 근데 며칠이나요?"]', '["Use \\"Could I take … off?\\"","Key words: getting married, take two days off"]', '["\\"Could I take … off?\\"를 쓰세요.","핵심 단어: getting married, take two days off"]', 'maya', 'Of course! Just put it in the HR portal and I''ll approve it.', '물론이죠! HR 포털에 올리면 승인할게요.'),
  ('d4_pto', 4, 'maya', 'Maya adds one more thing.', '마야가 한 가지를 덧붙입니다.', 'And if you''re ever sick, don''t come in. Just message me before standup.', '그리고 혹시 아프면 출근하지 마요. 스탠드업 전에 메시지만 줘요.', 'You want to know if being sick eats into your vacation days.', '아프면 휴가 일수가 깎이는지 알고 싶습니다.', '[{"all":["separate"]},{"all":["sick days"]},{"all":["sick"],"any":["count","different","same"]}]', 'Good to know. Are sick days separate from PTO?', '알겠어요. 병가는 유급휴가랑 따로예요?', '["Good to know. Should I message you after standup?","Don''t worry, I never get sick. I''ll be here.","Good to know. Do I need a doctor''s note?"]', '["알겠어요. 스탠드업 끝나고 메시지 드리면 돼요?","걱정 마세요. 전 안 아파요. 꼭 나올게요.","알겠어요. 의사 소견서도 필요해요?"]', '["Before standup, ideally. So we can plan.","Ha. Still, please stay home if you do.","Not for a day or two. Anything else?"]', '["되도록 스탠드업 전에요. 계획을 짜야 하니까요.","하하. 그래도 아프면 꼭 집에 있어요.","하루 이틀은 필요 없어요. 또 궁금한 거 있어요?"]', '["Ask \\"Are … separate from …?\\"","Key words: sick days, separate"]', '["\\"Are … separate from …?\\"로 물어보세요.","핵심 단어: sick days, separate"]', 'maya', 'Yep, you get five sick days. And please actually use them if you need to!', '네, 병가는 5일이에요. 필요하면 진짜로 써요!'),
  ('d5_demo', 1, 'priya', 'The team and a few people from sales are in the meeting room.', '회의실에 팀원들과 영업팀 몇 명이 있습니다.', 'Okay, demo time! You''re up first. Want to show us the card payment fix?', '자, 데모 시간이에요! 첫 순서예요. 카드 결제 수정 보여 줄래요?', 'Get ready to show everyone what''s on your laptop.', '노트북 화면을 모두에게 보여 줄 준비를 하세요.', '[{"all":["share"]},{"all":["screen"]}]', 'Sure. Let me share my screen.', '네. 제 화면 공유해 드릴게요.', '["Sure. Can someone else drive?","Sure. Let me share the refund fix.","Uh, do I have to? I''m not ready."]', '["네. 누가 대신 띄워 줄래요?","네. 환불 수정 화면 공유할게요.","어, 꼭 해야 돼요? 준비 안 됐는데."]', '["It''s your fix! You should show it.","Card payments first, please. Refunds are next week.","You''ll be great. Just show what you did."]', '["당신이 고친 거잖아요! 직접 보여 줘요.","카드 결제 먼저요. 환불은 다음 주예요.","잘할 거예요. 한 걸 그냥 보여 주면 돼요."]', '["Use \\"Let me …\\".","Key words: share my screen"]', '["\\"Let me …\\"를 쓰세요.","핵심 단어: share my screen"]', 'priya', 'We can see it. Go ahead.', '보여요. 시작해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_demo', 2, 'priya', 'The checkout page is on the big screen.', '큰 화면에 결제 페이지가 떠 있습니다.', 'Walk us through what changed.', '뭐가 바뀌었는지 차근차근 설명해 줘요.', 'Explain what happens now when a payment doesn''t go through: what the user sees, and what the system does.', '이제 결제가 실패하면 어떻게 되는지 설명하세요. 사용자에게 무엇이 보이고 시스템은 무엇을 하는지요.', '[{"any":["error message","retry","retries","message","error"]}]', 'Now, if a payment fails, the user sees a clear error message, and we retry once automatically.', '이제 결제가 실패하면 사용자에게 분명한 오류 메시지가 보이고, 자동으로 한 번 재시도해요.', '["If a payment fails, we now retry it five times in a row before showing an error.","So I refactored the PaymentClient class and wrapped the async payment call in a try-catch block.","Before, the old code just swallowed errors. Honestly, whoever wrote it should''ve known better."]', '["결제가 실패하면 이제 오류를 보여 주기 전에 다섯 번 연속으로 재시도해요.","PaymentClient 클래스를 리팩터링하고 비동기 결제 호출을 try-catch 블록으로 감쌌어요.","전에는 옛날 코드가 에러를 그냥 삼켰어요. 솔직히 그걸 짠 사람이 잘못한 거죠."]', '["Five times? Won''t that charge people twice?","Um, maybe in plain English for the sales folks?","Let''s keep it to what changed, okay?"]', '["다섯 번이요? 그럼 돈이 두 번 빠지지 않아요?","음, 영업팀 분들도 알아듣게 쉽게 말해 줄래요?","바뀐 것만 얘기하죠, 네?"]', '["Say what happens now when a payment fails.","Key words: error message, retry"]', '["이제 결제가 실패하면 어떻게 되는지 말하세요.","핵심 단어: error message, retry"]', 'priya', 'Nice! That''ll cut down on support tickets for sure.', '좋아요! 고객 문의 티켓이 확실히 줄겠네요.'),
  ('d5_demo', 3, 'priya', 'After the demo, Priya draws two columns on the whiteboard.', '데모가 끝나고 프리야가 화이트보드에 두 칸을 그립니다.', 'Let''s switch to the retro. What went well this sprint?', '이제 회고로 넘어가요. 이번 스프린트에서 잘된 건 뭐예요?', 'Give credit to your teammates and to the feedback you got on your work.', '팀원들과, 작업에 대해 받은 피드백에 공을 돌리세요.', '[{"any":["supportive","helpful","team","reviews","review","support"]}]', 'The team was really supportive, and the code reviews were super helpful.', '팀이 정말 많이 도와줬고, 코드 리뷰가 엄청 도움이 됐어요.', '["I fixed the card payment bug on time, mostly on my own, which felt great.","Honestly, the refund ticket was way too vague. That really slowed me down.","The team was really supportive, and Maya''s code reviews helped a lot."]', '["카드 결제 버그를 거의 혼자 제때 고쳤는데, 그게 뿌듯했어요.","솔직히 환불 티켓이 너무 모호했어요. 그것 때문에 많이 늦어졌어요.","팀이 정말 많이 도와줬고, 마야의 코드 리뷰가 많이 도움이 됐어요."]', '["Nice! Though I think Derek helped a bit too, no?","Hold that thought for the next column!","Maya''s? I think Derek did your reviews."]', '["좋네요! 근데 데릭도 좀 도와주지 않았어요?","그건 다음 칸에 써요!","마야요? 리뷰는 데릭이 해 준 걸로 아는데요."]', '["Name something good about working together.","Key words: supportive, code reviews"]', '["함께 일하면서 좋았던 점을 말하세요.","핵심 단어: supportive, code reviews"]', 'priya', 'Aw, love that.', '와, 좋네요.'),
  ('d5_demo', 4, 'priya', 'Priya points at the second column.', '프리야가 두 번째 칸을 가리킵니다.', 'And what could we do better?', '그럼 더 잘할 수 있는 건 뭐예요?', 'Bring up a problem with how work was prepared, using the bug that slowed you down as an example.', '일을 준비하는 과정의 문제를 꺼내세요. 당신을 늦어지게 한 버그를 예로 들어서요.', '[{"any":["clearer","clear","details","detail","requirements","vague"]}]', 'Some tickets could be clearer before planning. The refund bug was a little vague.', '플래닝 전에 티켓이 좀 더 명확하면 좋겠어요. 환불 버그는 좀 모호했거든요.', '["Priya, your tickets are always confusing. The refund one made no sense at all.","Some tickets could be clearer before planning. The checkbox one was really vague.","Honestly, nothing. Everything went perfectly this sprint, no complaints."]', '["프리야, 티켓이 항상 헷갈려요. 환불 건은 아예 말이 안 됐어요.","플래닝 전에 티켓이 좀 더 명확하면 좋겠어요. 체크박스 건이 정말 모호했거든요.","솔직히 없어요. 이번 스프린트는 다 완벽했어요, 불만 없어요."]', '["Oof. Okay, noted. Maybe a little gentler next time?","The checkbox? I thought that one was pretty clear.","Come on, there''s always something. Even small stuff?"]', '["아이고. 네, 알겠어요. 다음엔 좀 부드럽게 말해 줄래요?","체크박스요? 그건 꽤 명확했던 것 같은데요.","에이, 항상 뭔가 있잖아요. 사소한 거라도요?"]', '["Give polite, useful feedback about the work.","Key words: tickets, clearer"]', '["일에 대해 정중하고 쓸모 있는 피드백을 주세요.","핵심 단어: tickets, clearer"]', 'priya', 'Totally fair. I''ll add acceptance criteria to every ticket from now on.', '맞는 말이에요. 앞으로 모든 티켓에 인수 조건을 적을게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_happy_hour', 1, 'derek', 'It is Friday afternoon. Derek is packing up his laptop.', '금요일 오후입니다. 데릭이 노트북을 챙기고 있습니다.', 'Hey, a bunch of us are going to happy hour at the Anchor after work. You in?', '저기, 우리 몇 명이 퇴근하고 앵커에 해피 아워 가는데. 같이 갈래요?', 'You''re exhausted after your first week. Turn him down without hurting his feelings.', '첫 주를 보내고 녹초가 됐습니다. 기분 상하지 않게 거절하세요.', '[{"any":["wiped","tired","exhausted","beat","next time","rain check"]},{"all":["love to","but"]}]', 'Thanks for the invite! I''d love to, but I''m pretty wiped out this week.', '초대해 줘서 고마워요! 가고 싶은데, 이번 주는 완전히 녹초가 됐어요.', '["No thanks. I don''t really drink with coworkers, so I''ll pass.","Sure, I''m in! What time are you heading over to the Anchor?","Thanks, but honestly, this job is wearing me down. I''m kind of miserable."]', '["됐어요. 동료들이랑은 술 잘 안 마셔서, 전 빠질게요.","좋아요, 저도 갈게요! 앵커에는 몇 시쯤 출발해요?","고맙지만, 솔직히 이 일 때문에 너무 지쳐요. 좀 비참한 기분이에요."]', '["Oh. Okay, sure. No worries.","Awesome! Around five-thirty. You sure? You look pretty beat.","Oh no, really? Hey, if you want to talk about it, I''m around."]', '["아. 네, 그래요. 괜찮아요.","좋아요! 다섯 시 반쯤요. 진짜 괜찮아요? 많이 지쳐 보이는데.","아이고, 정말요? 얘기하고 싶으면 언제든 말해요."]', '["Use \\"I''d love to, but …\\".","Key words: I''d love to, but, tired"]', '["\\"I''d love to, but …\\"를 쓰세요.","핵심 단어: I''d love to, but, tired"]', 'derek', 'Totally get it. The first week is exhausting.', '완전 이해해요. 첫 주는 진 빠지죠.'),
  ('d5_happy_hour', 2, 'derek', 'He zips up his bag.', '그가 가방 지퍼를 올립니다.', 'No pressure at all. We go pretty much every other Friday.', '전혀 부담 갖지 마요. 거의 격주 금요일마다 가거든요.', 'Let him know you''d really like to join another time.', '다른 때에는 꼭 같이 가고 싶다고 전하세요.', '[{"any":["rain check","next time","count me in"]}]', 'Can I take a rain check? I''ll definitely come next time.', '다음으로 미뤄도 될까요? 다음번엔 꼭 갈게요.', '["Cool. So the next one is tomorrow? I could do that.","Good, because honestly, happy hours aren''t really my thing.","Is it okay if I just stop by for five minutes, then?"]', '["좋아요. 그럼 다음 건 내일이에요? 그건 갈 수 있어요.","다행이네요, 솔직히 해피 아워는 제 취향이 아니라서요.","그럼 5분만 잠깐 들러도 괜찮아요?"]', '["Tomorrow''s Saturday. Next one''s in two weeks.","Oh. Alright, fair enough.","Sure, but you just said you''re wiped. Go home and rest!"]', '["내일은 토요일이에요. 다음은 2주 뒤고요.","아. 그래요, 알겠어요.","그래도 되는데, 방금 녹초라면서요. 집에 가서 쉬어요!"]', '["\\"Take a rain check\\" = accept later instead.","Key words: rain check, next time"]', '["take a rain check는 다음에 받겠다는 뜻입니다.","핵심 단어: rain check, next time"]', 'derek', 'Rain check it is. I''m holding you to that!', '다음으로 미루죠. 약속 지켜요!'),
  ('d5_happy_hour', 3, 'derek', 'Derek puts on his jacket.', '데릭이 재킷을 입습니다.', 'Any plans for tonight, then?', '그럼 오늘 밤엔 뭐 해요?', 'Tell him your low-key plan: a quick stop at the store, then a quiet night.', '소박한 계획을 말하세요. 가게에 잠깐 들렀다가 조용히 쉴 거예요.', '[{"any":["groceries","grocery","relax","rest","sleep","home","chill","nothing much"]}]', 'Just grabbing some groceries and getting some rest.', '그냥 장 좀 보고 푹 쉬려고요.', '["Probably going out downtown with some friends.","Not sure yet. What are you guys doing after the Anchor?","Why, do you need me to work on something tonight?"]', '["아마 친구들이랑 시내에 놀러 갈 것 같아요.","아직 모르겠어요. 앵커 다음엔 다들 뭐 해요?","왜요, 오늘 밤에 제가 뭐 작업해야 해요?"]', '["Oh, I thought you were too tired? Ha, okay.","Ha, probably tacos. But I thought you were heading home?","No, no! Just making small talk. Relax, it''s Friday."]', '["어, 피곤하다고 하지 않았어요? 하, 그래요.","하, 아마 타코요. 그런데 집에 간다고 하지 않았어요?","아뇨, 아뇨! 그냥 하는 말이에요. 긴장 풀어요, 금요일이잖아요."]', '["Start with \\"Just …ing\\".","Key words: groceries, rest"]', '["\\"Just …ing\\"로 시작하세요.","핵심 단어: groceries, rest"]', 'derek', 'Sounds perfect. You earned it.', '딱 좋네요. 그럴 자격 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_happy_hour', 4, 'derek', 'He stops at the door and turns around.', '그가 문 앞에서 멈춰 돌아봅니다.', 'Oh, and great job at the demo today, by the way.', '아, 그리고 오늘 데모 정말 잘했어요.', 'Take the compliment graciously and say goodbye for the weekend.', '칭찬을 기분 좋게 받고 주말 인사를 하세요.', '[{"any":["thanks","thank","appreciate"]}]', 'Thanks, that means a lot! Have a great weekend.', '고마워요, 그 말 들으니 정말 힘이 나요! 주말 잘 보내요.', '["Oh, it wasn''t that good. I messed up a lot of it.","Thanks! See you at the Anchor tomorrow, then.","Thanks. Did Maya say anything about it to you?"]', '["에이, 그렇게 잘하진 않았어요. 많이 망쳤는데요.","고마워요! 그럼 내일 앵커에서 봐요.","고마워요. 마야가 그것에 대해 뭐라고 했어요?"]', '["Come on, take the compliment! It was good.","Tomorrow? It''s tonight, and you''re skipping it, remember?","Not to me. But I''m sure she liked it. Go home!"]', '["에이, 칭찬은 그냥 받아요! 잘했다니까요.","내일요? 오늘 밤이고, 당신은 안 오잖아요.","저한텐 아무 말 없었어요. 분명 좋아했을 거예요. 집에 가요!"]', '["Thank him, then say goodbye for the weekend.","Key words: thanks, great weekend"]', '["고맙다고 하고 주말 인사를 하세요.","핵심 단어: thanks, great weekend"]', 'derek', 'You too! See you Monday.', '당신도요! 월요일에 봐요.'),
  ('d5_paystub', 1, 'linda', 'Your first paycheck hit your bank account this morning. You bring the pay stub to HR.', '오늘 아침 첫 급여가 계좌에 들어왔습니다. 급여명세서를 들고 인사팀에 갑니다.', 'Happy payday! What can I do for you?', '월급날 축하해요! 뭘 도와드릴까요?', 'Your first paycheck came in smaller than you expected. Tell Linda why you came by.', '첫 월급이 생각보다 적게 들어왔습니다. 린다에게 찾아온 이유를 말하세요.', '[{"any":["pay stub","paystub","paycheck","stub","payslip","pay slip"]}]', 'Hi, Linda. I have a question about my pay stub.', '안녕하세요, 린다. 급여명세서에 대해 궁금한 게 있어서요.', '["Hi, Linda. I think my direct deposit didn''t come in.","Hi, Linda. I think payroll messed up my paycheck.","Hi, Linda. Could you tell me when the next payday is?"]', '["안녕하세요, 린다. 월급이 계좌에 안 들어온 것 같아요.","안녕하세요, 린다. 급여팀이 제 월급을 잘못 계산한 것 같아요.","안녕하세요, 린다. 다음 월급날이 언제인지 알려 주실래요?"]', '["Oh no! Hm, it shows it went out this morning. Did you check?","Well, let''s not jump to conclusions. Let''s take a look first.","Every other Friday. But you look like something''s bugging you?"]', '["어머! 음, 오늘 아침에 나간 걸로 나오는데요. 확인해 봤어요?","음, 성급하게 단정하진 말고요. 일단 같이 봐요.","격주 금요일이에요. 그런데 뭔가 신경 쓰이는 게 있는 얼굴인데요?"]', '["The paper that shows your pay is a \\"pay stub\\".","Key words: question, pay stub"]', '["급여 내역서는 pay stub이라고 합니다.","핵심 단어: question, pay stub"]', 'linda', 'Sure! Let''s pull it up together.', '그럼요! 같이 열어 봐요.'),
  ('d5_paystub', 2, 'linda', 'Linda points at the top of the stub.', '린다가 명세서 맨 위를 가리킵니다.', 'This top number, thirty-six fifty-four, is your gross pay. That''s before anything comes out.', '맨 위 숫자, 3,654달러가 총급여예요. 아무것도 떼기 전 금액이죠.', 'Point to the next line, the federal tax taken out, and ask what it is.', '다음 줄, 연방 세금으로 떼인 항목을 가리키며 뭔지 물어보세요.', '[{"all":["withholding"]},{"all":["federal"]},{"all":["tax"]}]', 'What''s this line, federal withholding?', '이 줄은 뭐예요? 연방 원천징수요?', '["So my take-home is thirty-six fifty-four?","Why is the government taking so much?","And what''s this one, health insurance?"]', '["그럼 제 실수령액이 3,654달러예요?","정부는 왜 이렇게 많이 떼 가요?","그리고 이건 뭐예요, 건강보험이요?"]', '["No, that''s gross. Your take-home is at the very bottom.","Ha, everybody says that. Let''s go line by line.","That''s further down. Look at the line right under gross pay."]', '["아뇨, 그건 총액이에요. 실수령액은 맨 아래에 있어요.","하, 다들 그렇게 말해요. 한 줄씩 봐요.","그건 더 아래예요. 총급여 바로 밑의 줄을 보세요."]', '["Read the words on the line and ask about them.","Key words: federal withholding"]', '["그 줄의 단어를 읽고 물어보세요.","핵심 단어: federal withholding"]', 'linda', 'That''s federal income tax, based on your W-4. You settle up when you file your taxes in April.', 'W-4에 따라 떼는 연방 소득세예요. 4월에 세금 신고할 때 정산해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d5_paystub', 3, 'linda', 'Below that there are more lines: FICA, state tax, health insurance, 401(k).', '그 아래에 더 많은 줄이 있습니다: FICA, 주세, 건강보험, 401(k).', 'Then FICA. That''s Social Security and Medicare. Everyone pays that, seven point six five percent.', '그다음이 FICA예요. 사회보장세랑 메디케어요. 누구나 내요, 7.65퍼센트.', 'You signed up for the company retirement plan. Ask where it shows up on the stub.', '회사 퇴직연금에 가입했습니다. 그게 명세서 어디에 나오는지 물어보세요.', '[{"all":["401"]},{"all":["retirement"]},{"all":["contribution"]}]', 'Got it. And where''s my 401(k) contribution?', '알겠어요. 그럼 제 401(k) 납입액은 어디 있어요?', '["Got it. So FICA is the state income tax?","Seven point six five? That''s way too much.","Got it. And where''s my health insurance?"]', '["알겠어요. 그럼 FICA가 주 소득세예요?","7.65퍼센트요? 너무 많은데요.","알겠어요. 그럼 제 건강보험은 어디 있어요?"]', '["No, state tax is its own line. FICA''s Social Security and Medicare.","Ha, tell that to Congress. It''s the same for everyone.","Just below state tax. Was there something else you were looking for?"]', '["아뇨, 주세는 따로 있어요. FICA는 사회보장세랑 메디케어예요.","하, 그건 의회에 말해요. 누구나 똑같아요.","주세 바로 아래요. 혹시 다른 걸 찾고 있었어요?"]', '["Ask \\"Where''s my …?\\"","Key words: 401(k) contribution"]', '["\\"Where''s my …?\\"로 물어보세요.","핵심 단어: 401(k) contribution"]', 'linda', 'Right here: four percent, a hundred forty-six dollars. It comes out pre-tax.', '여기요. 4퍼센트, 146달러예요. 세전으로 빠져요.'),
  ('d5_paystub', 4, 'linda', 'At the bottom is the number you saw in your bank account.', '맨 아래에 은행 계좌에서 본 숫자가 있습니다.', 'After all that, your net pay, your take-home, is twenty-six hundred. It goes straight to your bank by direct deposit.', '그걸 다 빼고 나면 실수령액, 손에 쥐는 돈이 2,600달러예요. 직접 입금으로 바로 계좌에 들어가요.', 'Now you see where the money went. Wrap things up with Linda.', '이제 돈이 어디로 갔는지 알겠습니다. 린다와 대화를 마무리하세요.', '[{"any":["makes sense","thanks","thank","clear","got it","understand"]}]', 'That makes a lot more sense now. Thanks, Linda!', '이제 훨씬 이해가 되네요. 고마워요, 린다!', '["Got it, so twenty-two hundred goes to my bank. Thanks!","Okay. Still feels like a lot less than I was promised.","So should I switch to getting paper checks instead?"]', '["알겠어요, 그러니까 2,200달러가 계좌로 가는 거죠. 고마워요!","네. 그래도 약속받은 것보다 훨씬 적은 느낌이네요.","그럼 차라리 종이 수표로 받는 게 나을까요?"]', '["Twenty-six hundred, actually. Look at the bottom line.","Your salary''s the same. It''s taxes and benefits. Want to go over it again?","You could, but it won''t change the amount. Is it clearer now?"]', '["2,600달러예요. 맨 아랫줄을 보세요.","연봉은 그대로예요. 세금이랑 복리후생이에요. 다시 볼까요?","그래도 되지만 금액은 똑같아요. 이제 좀 이해됐어요?"]', '["Say you understand now, and thank her.","Key words: makes sense, thanks"]', '["이제 이해했다고 하고 고맙다고 하세요.","핵심 단어: makes sense, thanks"]', 'linda', 'Anytime! And hey, don''t spend it all in one place.', '언제든지요! 그리고 한 번에 다 쓰지 마요.'),
  ('d8_kickoff', 1, 'priya', 'You join Priya in the meeting room. Greg from Summit Retail is on the video call.', '회의실에서 프리야와 함께합니다. 서밋 리테일의 그렉이 화상 통화에 들어와 있습니다.', 'Greg, this is our new developer. They''ll be building most of the dashboard. Want to say hi?', '그렉, 이쪽은 우리 새 개발자예요. 대시보드 대부분을 만들 거예요. 인사할래요?', 'Introduce yourself to the client and start off on the right foot.', '고객에게 인사하고 좋은 첫인상을 남기세요.', '[{"all":["looking forward"]},{"all":["nice","meet"]},{"all":["great","meet"]},{"all":["excited","work"]}]', 'Hi Greg, nice to meet you. I''m looking forward to working with you.', '안녕하세요, 그렉. 반갑습니다. 함께 일하게 되어 기대돼요.', '["Hey Greg! What''s up, man? So you''re the client, huh?","Hi Greg, nice to meet you. I''ll be helping out with the mobile app.","Hi Greg. Don''t worry, I''ll have your dashboard done in no time."]', '["어, 그렉! 잘 지내요? 그쪽이 고객이구나?","안녕하세요, 그렉. 반갑습니다. 저는 모바일 앱 쪽을 도울 거예요.","안녕하세요, 그렉. 걱정 마세요, 대시보드는 금방 만들어 드릴게요."]', '["Ha… yes, that''s me. Nice to meet you too.","Oh, I thought Priya said you''d be on the dashboard?","Ha, I like the confidence. Let''s see what we''re dealing with first."]', '["하… 네, 접니다. 저도 반가워요.","어, 프리야가 대시보드를 맡는다고 하지 않았어요?","하, 자신감 좋네요. 일단 뭘 다뤄야 하는지부터 보죠."]', '["Say hello and that you are happy to work together.","Key words: nice to meet you, looking forward"]', '["인사하고 함께 일하게 되어 기쁘다고 말하세요.","핵심 단어: nice to meet you, looking forward"]', 'greg', 'Likewise! We''ve got a lot riding on this project, so I''m glad you''re on board.', '저도요! 이 프로젝트에 걸린 게 많아서, 함께하게 되어 기뻐요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d8_kickoff', 2, 'greg', 'Greg explains that his store managers can''t see stock levels in one place.', '그렉은 매장 관리자들이 재고를 한곳에서 볼 수 없다고 설명합니다.', 'Basically, our store managers are flying blind. We want one dashboard with live inventory for all forty stores.', '한마디로 우리 매장 관리자들은 깜깜이로 일하고 있어요. 매장 40곳 전부의 실시간 재고가 나오는 대시보드 하나를 원해요.', 'Before going any further, check that you''ve understood his request correctly.', '더 나가기 전에, 그의 요청을 제대로 이해했는지 확인하세요.', '[{"all":["make sure","understand"]},{"all":["if i understand"]},{"all":["so you want"],"any":["dashboard","inventory","stores"]},{"all":["understand","correctly"]}]', 'Just to make sure I understand, you want one dashboard that shows live inventory for all forty stores?', '제가 제대로 이해했는지 확인하고 싶은데요, 매장 40곳 전부의 실시간 재고를 보여 주는 대시보드 하나를 원하시는 거죠?', '["So if I''ve got this right, you want a dashboard with live inventory for your fourteen stores?","That sounds simple enough. We can have live inventory for all forty stores up in a couple of weeks.","Got it. So should each store manager get their own separate dashboard for their store?"]', '["그러니까 제가 맞게 이해했다면, 매장 14곳의 실시간 재고가 나오는 대시보드를 원하시는 거죠?","그 정도면 간단하네요. 매장 40곳 전부 실시간 재고를 2주면 띄울 수 있어요.","알겠어요. 그럼 매장 관리자마다 자기 매장만 보는 대시보드를 따로 드리면 될까요?"]', '["Forty, actually. Four-zero. It''s a lot of stores.","A couple of weeks? Wow. Let''s hear the details first.","No, that''s the whole problem. We want it all in one place."]', '["40곳이에요. 사십. 매장이 많아요.","2주요? 와. 일단 자세한 얘기부터 듣죠.","아뇨, 그게 바로 문제예요. 전부 한곳에서 보고 싶어요."]', '["Repeat his request back to him to confirm it.","Key words: just to make sure I understand, dashboard"]', '["그의 요청을 다시 말해 확인하세요.","핵심 단어: just to make sure I understand, dashboard"]', 'greg', 'Exactly. And live means it updates within a few minutes, not overnight.', '바로 그거예요. 그리고 실시간이란 밤사이가 아니라 몇 분 안에 갱신된다는 뜻이에요.'),
  ('d8_kickoff', 3, 'greg', 'You don''t know how their stores record sales today.', '그들의 매장이 지금 판매 데이터를 어떻게 기록하는지 모릅니다.', 'Our point-of-sale system is kind of old, though. Is that going to be a problem?', '그런데 우리 POS 시스템이 좀 오래됐어요. 그게 문제가 될까요?', 'You can''t answer yet. Find out how their stores get sales data out of the system now.', '아직 답할 수 없습니다. 지금 매장 시스템에서 판매 데이터가 어떻게 나오는지 알아보세요.', '[{"all":["walk","through"]},{"all":["how","data"],"any":["send","sends","export","work","works","get"]},{"all":["explain","how"]},{"all":["tell","more","system"]}]', 'It depends. Could you walk me through how your point-of-sale system sends data today?', '상황에 따라 달라요. 지금 POS 시스템이 데이터를 어떻게 보내는지 차근차근 설명해 주실 수 있을까요?', '["Not at all. We work with old systems like that all the time, so it won''t be a problem.","Probably. Honestly, you should replace that system before we start anything.","It depends. Could you send us a list of all your store locations?"]', '["전혀 문제없어요. 저희는 오래된 시스템도 늘 다뤄 봤으니까 걱정 마세요.","아마도요. 솔직히 저희가 시작하기 전에 그 시스템부터 바꾸셔야 해요.","상황에 따라 달라요. 매장 위치 목록 전체를 보내 주실 수 있을까요?"]', '["Great, that''s a relief. Wait, you haven''t even seen it yet.","Replace it? That''s a huge project. Not happening this year.","Sure, but how does that help with the old system?"]', '["좋네요, 다행이에요. 잠깐, 아직 보지도 않았잖아요.","바꾸라고요? 그건 엄청난 프로젝트예요. 올해는 안 돼요.","그럼요, 근데 그게 오래된 시스템이랑 무슨 상관이죠?"]', '["Ask him to explain the current process step by step.","Key words: walk me through, how, data"]', '["현재 과정을 단계별로 설명해 달라고 하세요.","핵심 단어: walk me through, how, data"]', 'greg', 'Sure. Right now each store exports a file every night at midnight, and someone uploads it by hand.', '그럼요. 지금은 매장마다 매일 밤 자정에 파일을 내보내고, 누군가 그걸 손으로 올려요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d8_kickoff', 4, 'priya', 'A nightly file can''t give Greg live data. Priya looks at you to raise it.', '하루 한 번 올리는 파일로는 실시간 데이터가 나올 수 없습니다. 프리야가 말해 보라는 눈짓을 합니다.', 'Hmm. That could affect the timeline. Want to flag that for Greg?', '음. 일정에 영향이 있을 수도 있겠네요. 그렉에게 짚어 줄래요?', 'Raise it with Greg: explain why the nightly file is a problem, and what you''ll need instead (API access).', '그렉에게 말하세요. 매일 밤 파일이 왜 문제인지, 대신 무엇이 필요한지(API 접근) 설명하세요.', '[{"all":["api"],"any":["need","access","require"]},{"all":["nightly","enough"]},{"all":["real time"],"any":["need","api","access"]},{"all":["live","need"]}]', 'Nightly files won''t be enough for live data, so we''ll need API access to your point-of-sale system.', '매일 밤 파일로는 실시간 데이터가 안 돼서, POS 시스템에 대한 API 접근 권한이 필요해요.', '["Nightly files should work fine for now, and we can add live updates later on.","Honestly, a nightly file is pretty outdated. Your IT team should''ve fixed this years ago.","Nightly files won''t be enough for live data, so we''ll need someone to upload them every hour instead."]', '["당분간은 매일 밤 파일로 충분하고, 실시간 갱신은 나중에 넣으면 돼요.","솔직히 매일 밤 파일은 꽤 구식이에요. IT 팀이 몇 년 전에 고쳤어야죠.","매일 밤 파일로는 실시간 데이터가 부족하니까, 대신 누가 매시간 파일을 올려 주셔야 해요."]', '["Later? But live data is the whole point for us.","Well… I''ll pass that along, I guess.","Every hour? By hand? We don''t have the staff for that."]', '["나중에요? 우리한텐 실시간 데이터가 핵심인데요.","음… 전해는 드릴게요.","매시간요? 손으로요? 그럴 인력이 없어요."]', '["Explain what you need instead of the nightly file.","Key words: not enough, API access, need"]', '["매일 밤 파일 대신 무엇이 필요한지 설명하세요.","핵심 단어: not enough, API access, need"]', 'greg', 'Got it. I''ll loop in our IT folks and get you what you need by Wednesday.', '알겠어요. 우리 IT 팀을 참여시켜서 수요일까지 필요한 걸 드릴게요.'),
  ('d8_kickoff', 5, 'priya', 'The call is almost over.', '통화가 거의 끝나 갑니다.', 'Great. Anything else before we let Greg go?', '좋아요. 그렉 보내 드리기 전에 더 할 말 있어요?', 'Offer to follow up in writing today so everyone knows what happens next.', '다음에 할 일을 모두가 알 수 있게 오늘 중으로 글로 정리해 보내겠다고 하세요.', '[{"all":["recap"]},{"all":["summary"],"any":["send","email"]},{"all":["follow up"],"any":["email","today"]},{"all":["send","notes"]},{"all":["next steps"]}]', 'I''ll send a recap email with the next steps later today.', '오늘 중으로 다음 단계를 정리한 요약 메일을 보내 드릴게요.', '["I''ll send a recap email with the next steps sometime next week.","I''ll send over the finished dashboard design by tomorrow morning.","Could you send us a summary of everything we talked about today?"]', '["다음 주 중에 다음 단계를 정리한 요약 메일을 보내 드릴게요.","내일 아침까지 완성된 대시보드 디자인을 보내 드릴게요.","오늘 얘기한 내용 전부 정리해서 저희한테 보내 주실 수 있을까요?"]', '["Next week? Today would be better, while it''s fresh.","Tomorrow? Wow, that''s fast. Are you sure about that?","Uh, I was kind of hoping your side would do that."]', '["다음 주요? 기억 생생할 때 오늘 주시면 좋겠는데요.","내일요? 와, 빠르네요. 정말 괜찮겠어요?","어, 그건 그쪽에서 해 주실 줄 알았는데요."]', '["Promise a written summary after the call.","Key words: recap email, next steps"]', '["통화 후 서면 요약을 약속하세요.","핵심 단어: recap email, next steps"]', 'greg', 'Perfect. Talk soon, everyone.', '좋아요. 다들 또 얘기해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d8_standup', 1, 'derek', 'The team gathers by Derek''s desk for the Monday standup. It is your turn.', '팀이 월요일 스탠드업을 하러 데릭 자리 옆에 모였습니다. 당신 차례입니다.', 'Alright, you''re up. What did you get done last week, and what''s on your plate today?', '자, 당신 차례예요. 지난주에 뭘 끝냈고, 오늘은 뭘 할 거예요?', 'Give your update: the login page is done, and the inventory API is next, starting today.', '업데이트를 하세요. 로그인 페이지는 끝났고, 오늘부터 재고 API를 시작합니다.', '[{"all":["finished"],"any":["login","last week"]},{"all":["wrapped up"]},{"all":["done","login"]},{"all":["today"],"any":["starting","start on","work on","working on"]}]', 'Last week I finished the login page. Today I''m starting on the inventory API.', '지난주에 로그인 페이지를 끝냈어요. 오늘은 재고 API를 시작해요.', '["Last week I started the login page. Today I''m finishing the inventory API.","Honestly, it was a tough week. I''m still figuring out how everything works.","I''m not sure what to pick up next. What do you think I should work on?"]', '["지난주에 로그인 페이지를 시작했어요. 오늘은 재고 API를 마무리해요.","솔직히 힘든 한 주였어요. 아직 다 어떻게 돌아가는지 파악 중이에요.","다음에 뭘 맡아야 할지 모르겠어요. 뭘 하면 좋을까요?"]', '["Finishing it? I thought you hadn''t touched the API yet.","Totally normal. But for standup, just the quick version: done and doing.","Didn''t you already have a ticket assigned? Check the board."]', '["마무리요? API는 아직 손도 안 댄 줄 알았는데요.","당연해요. 그래도 스탠드업에선 짧게요. 한 일, 할 일.","이미 배정된 티켓 있지 않았어요? 보드 확인해 봐요."]', '["Say what you finished and what you are starting today.","Key words: finished, today, starting"]', '["끝낸 일과 오늘 시작할 일을 말하세요.","핵심 단어: finished, today, starting"]', 'derek', 'Nice. The inventory API is a big one.', '좋아요. 재고 API는 큰 작업이죠.'),
  ('d8_standup', 2, 'derek', 'You can''t test the API because you still don''t have access to the staging database.', '스테이징 데이터베이스 접근 권한이 아직 없어서 API를 테스트할 수 없습니다.', 'Any blockers?', '막히는 거 있어요?', 'Something is keeping you from testing the API. Bring it up.', 'API를 테스트하지 못하게 막는 문제가 있습니다. 그걸 말하세요.', '[{"all":["blocked"],"any":["access","database","staging"]},{"all":["access"],"any":["staging","database"]},{"all":["blocker"],"any":["access","database","staging"]}]', 'Yeah, I''m blocked on one thing. I still don''t have access to the staging database.', '네, 하나 막힌 게 있어요. 아직 스테이징 데이터베이스 접근 권한이 없어요.', '["Nope, no blockers. I''ll sort out the database access on my own later.","Yeah. IT still hasn''t given me staging database access, which is getting pretty frustrating.","Yeah, one thing. I still don''t have access to the production database."]', '["아뇨, 없어요. 데이터베이스 권한은 나중에 제가 알아서 할게요.","네. IT가 아직도 스테이징 데이터베이스 권한을 안 줘서 점점 답답해요.","네, 하나요. 아직 운영 데이터베이스 접근 권한이 없어요."]', '["You sure? Access stuff usually needs IT. Don''t sit on it.","Okay, easy. That one''s actually on me, not on Sam.","Production? You won''t get prod for a while. Which one do you need?"]', '["정말요? 권한 문제는 보통 IT가 해야 해요. 붙잡고 있지 마요.","자, 진정해요. 그건 사실 샘이 아니라 제 잘못이에요.","운영요? 운영은 한동안 못 받아요. 어느 걸 말하는 거예요?"]', '["Say what is blocking you.","Key words: blocked, access, staging database"]', '["무엇 때문에 막혀 있는지 말하세요.","핵심 단어: blocked, access, staging database"]', 'derek', 'Ugh, that''s on me. I''ll ping Sam in IT right after this.', '아, 그건 제 잘못이에요. 끝나자마자 IT의 샘에게 연락할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d8_standup', 3, 'derek', 'Before the standup ends, you remember the client call later this morning.', '스탠드업이 끝나기 전, 오늘 오전의 고객 통화가 떠오릅니다.', 'Anything else before we wrap up?', '마무리하기 전에 더 할 말 있어요?', 'There''s a client call later this morning. Remind the team: it''s Summit Retail, at 11.', '오늘 오전 고객 통화를 팀에 상기시키세요. 서밋 리테일, 11시입니다.', '[{"all":["kickoff"],"any":["eleven","11","call","summit"]},{"all":["kick off"]},{"all":["summit","call"]},{"all":["call"],"any":["eleven","11"]}]', 'Just a reminder that we have the kickoff call with Summit Retail at eleven.', '다들 잊지 마세요. 11시에 서밋 리테일과 킥오프 콜이 있어요.', '["Just a reminder that we have the kickoff call with Summit Retail at one.","Can someone else take the Summit Retail call at eleven? I don''t think I''m ready.","Quick question: is the Summit Retail call today or tomorrow?"]', '["다들 잊지 마세요. 1시에 서밋 리테일과 킥오프 콜이 있어요.","11시 서밋 리테일 통화는 다른 분이 맡아 주실래요? 전 아직 준비가 안 된 것 같아요.","잠깐 질문요. 서밋 리테일 통화가 오늘이에요, 내일이에요?"]', '["One? I''ve got eleven on my calendar. Double-check that.","You''ll be fine. You just listen and ask good questions.","Today, isn''t it? Check your calendar, it''s your project."]', '["1시요? 제 캘린더엔 11시로 돼 있는데요. 다시 확인해 봐요.","괜찮을 거예요. 잘 듣고 좋은 질문만 하면 돼요.","오늘 아니에요? 캘린더 확인해 봐요, 당신 프로젝트잖아요."]', '["Remind the team about the client meeting.","Key words: kickoff call, Summit, eleven"]', '["고객 회의가 있다고 팀에 알려 주세요.","핵심 단어: kickoff call, Summit, eleven"]', 'derek', 'Good call. Priya''s running it, so bring your questions. Okay, that''s a wrap, everyone.', '좋아요. 프리야가 진행하니까 질문 준비해 와요. 자, 오늘은 여기까지!'),
  ('d8_trip_approval', 1, 'maya', 'After the call, Greg invited you to Ridgeport to go over the contract in person. You stop by Maya''s office.', '통화 후 그렉이 리지포트에서 직접 계약을 검토하자고 초대했습니다. 마야의 사무실에 들릅니다.', 'Hey, come on in. What''s up?', '어, 들어와요. 무슨 일이에요?', 'Greg wants you in Ridgeport on Thursday and Friday. Ask Maya for the green light.', '그렉이 목요일과 금요일에 리지포트로 와 달라고 했습니다. 마야에게 허락을 구하세요.', '[{"all":["would it be okay"]},{"all":["would it be ok"]},{"all":["okay","if","go"]},{"all":["could","go","ridgeport"]},{"all":["permission"]},{"all":["approve","trip"]}]', 'Would it be okay if I went to Ridgeport on Thursday and Friday to meet the client?', '목요일하고 금요일에 고객 만나러 리지포트에 다녀와도 괜찮을까요?', '["Would it be okay if I went to Ridgeport next Monday and Tuesday to meet the client?","Just a heads-up, I''m flying to Ridgeport on Thursday and Friday to meet the client.","Greg wants someone in Ridgeport on Thursday. Could you go, or maybe Derek?"]', '["다음 주 월요일하고 화요일에 고객 만나러 리지포트에 다녀와도 괜찮을까요?","미리 말씀드려요, 목요일하고 금요일에 고객 만나러 리지포트에 가요.","그렉이 목요일에 리지포트에 누가 와 주길 원해요. 직접 가시거나 데릭이 가면 어때요?"]', '["Next week? I thought Greg wanted you there this week.","Oh. Well, it would''ve been nice to be asked first.","Me? He asked for you, didn''t he? Why not go yourself?"]', '["다음 주요? 그렉은 이번 주에 와 달라고 한 줄 알았는데요.","아. 음, 먼저 물어봐 줬으면 좋았을 텐데요.","저요? 그렉이 당신을 부른 거 아니에요? 직접 가요."]', '["Ask politely for permission to travel.","Key words: would it be okay if, Ridgeport"]', '["출장 가도 되는지 정중히 허락을 구하세요.","핵심 단어: would it be okay if, Ridgeport"]', 'maya', 'Oh nice, Greg asked for you? Sure. It''s a good chance to meet them face to face.', '오, 그렉이 당신을 불렀어요? 좋아요. 직접 만날 좋은 기회예요.'),
  ('d8_trip_approval', 2, 'maya', 'Maya pulls up the travel policy on her screen.', '마야가 화면에 출장 규정을 띄웁니다.', 'Just stick to the travel policy. Economy flights, and hotels under two hundred a night.', '출장 규정만 지켜요. 비행기는 이코노미, 호텔은 1박 200달러 미만.', 'Find out how much you can spend on food each day.', '하루에 식비를 얼마까지 쓸 수 있는지 물어보세요.', '[{"all":["per diem"]},{"all":["meals"],"any":["how much","budget","limit","allowance","cover"]},{"all":["food"],"any":["budget","limit","allowance"]}]', 'Got it. What''s the per diem for meals?', '알겠어요. 식비 일일 한도는 얼마예요?', '["Got it. Can I book a business-class seat?","Okay. Can I stay somewhere nicer, though?","Got it. Is there a limit on hotel costs?"]', '["알겠어요. 비즈니스석으로 예약해도 돼요?","네. 그래도 좀 더 좋은 데서 묵으면 안 돼요?","알겠어요. 호텔비에 한도가 있어요?"]', '["Economy, remember? It''s in the policy.","Not on our budget. Under two hundred, please.","I just said: under two hundred a night."]', '["이코노미라고 했잖아요. 규정에 있어요.","우리 예산으론 안 돼요. 200달러 미만으로요.","방금 말했잖아요. 1박 200달러 미만이요."]', '["Ask about the daily meal allowance.","Key words: per diem, meals"]', '["하루 식비 한도를 물어보세요.","핵심 단어: per diem, meals"]', 'maya', 'Sixty-five dollars a day. Keep your receipts, and client dinners go on the company card.', '하루 65달러예요. 영수증은 챙기고, 고객과의 저녁은 법인 카드로 해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d8_trip_approval', 3, 'maya', 'You have never booked a business trip here before.', '이 회사에서 출장을 예약해 본 적이 없습니다.', 'Anything else you need from me?', '그 밖에 나한테 필요한 거 있어요?', 'Ask whether you book the trip yourself or have Tom, the office manager, do it.', '출장 예약을 직접 하는지, 사무실 관리자인 톰에게 맡기는지 물어보세요.', '[{"all":["book"],"any":["myself","tom","who"]},{"all":["go through","tom"]},{"all":["tom"],"any":["handle","booking","book"]}]', 'Should I book everything myself, or go through Tom?', '예약은 제가 다 직접 해요, 아니면 톰을 통해서 해요?', '["Should I just put everything on my own credit card?","Could you book the flight and hotel for me?","Should I book everything myself, or go through Derek?"]', '["그냥 전부 제 개인 신용카드로 결제하면 돼요?","비행기랑 호텔 좀 대신 예약해 주실래요?","예약은 제가 다 직접 해요, 아니면 데릭을 통해서 해요?"]', '["Please don''t. We don''t want you fronting the money.","Ha, I''m not your travel agent. There''s a process.","Derek? He doesn''t handle travel. Think front desk."]', '["그러지 마요. 당신 돈으로 먼저 내게 하고 싶지 않아요.","하, 내가 여행사 직원은 아니잖아요. 절차가 있어요.","데릭요? 데릭은 출장 담당이 아니에요. 프런트 쪽이요."]', '["Ask who handles the booking.","Key words: book, myself, go through Tom"]', '["예약을 누가 하는지 물어보세요.","핵심 단어: book, myself, go through Tom"]', 'maya', 'Go through Tom. He has the company card and knows the policy inside out. I''ll approve the trip in the system now.', '톰을 통해요. 법인 카드도 있고 규정을 훤히 알아요. 지금 시스템에서 출장을 승인할게요.'),
  ('d9_code_review', 1, 'derek', 'Your inventory API pull request is ready. Derek is at his desk.', '재고 API 풀 리퀘스트가 준비됐습니다. 데릭이 자리에 있습니다.', 'Hey, what''s up?', '어, 무슨 일이에요?', 'Your inventory API code is ready. Ask Derek to look it over.', '재고 API 코드가 준비됐습니다. 데릭에게 봐 달라고 하세요.', '[{"all":["review"],"any":["pull request","pr","code","changes"]},{"all":["take a look"]},{"all":["look at"],"any":["pr","code","pull request"]}]', 'Do you have a few minutes to review my pull request?', '제 풀 리퀘스트 리뷰해 줄 시간 좀 있어요?', '["Can you approve my pull request? It''s ready to merge now.","Could you take over my pull request? I''m kind of stuck.","Do you have a few minutes to review my login page PR?"]', '["제 풀 리퀘스트 승인해 줄래요? 이제 머지하면 돼요.","제 풀 리퀘스트 좀 맡아 줄래요? 좀 막혀서요.","제 로그인 페이지 PR 리뷰해 줄 시간 좀 있어요?"]', '["Approve it without looking? Ha, nice try. Send me the link.","Stuck? I thought you said it was done. What''s going on?","The login page? Didn''t that merge last week?"]', '["보지도 않고 승인하라고요? 하, 꿈도 커요. 링크 보내요.","막혀요? 다 됐다고 한 줄 알았는데. 무슨 일이에요?","로그인 페이지요? 그거 지난주에 머지되지 않았어요?"]', '["Ask for a code review.","Key words: review, pull request"]', '["코드 리뷰를 부탁하세요.","핵심 단어: review, pull request"]', 'derek', 'Sure, send me the link. Give me twenty minutes.', '그럼요, 링크 보내 줘요. 20분만 줘요.'),
  ('d9_code_review', 2, 'derek', 'Derek left a comment: one function is too long and has no tests.', '데릭이 댓글을 남겼습니다. 함수 하나가 너무 길고 테스트가 없습니다.', 'Looks good overall. But this function is doing a lot. Mind splitting it up and adding a couple of tests?', '전체적으로 좋아요. 근데 이 함수가 하는 일이 너무 많네요. 쪼개고 테스트 몇 개 추가해 줄래요?', 'Take his suggestions well and say you''ll make the changes.', '그의 제안을 잘 받아들이고 고치겠다고 하세요.', '[{"all":["thanks"],"any":["split","tests","test","feedback"]},{"all":["thank you"],"any":["split","tests","test","feedback"]},{"all":["good point"]},{"all":["split"],"any":["test","tests"]}]', 'Thanks for the feedback. Good point, I''ll split it up and add some tests.', '피드백 고마워요. 좋은 지적이에요, 함수 나누고 테스트도 추가할게요.', '["It works fine, though. Do we really need tests for something this small?","Thanks for the feedback. I''ll rename the variables and add some comments.","Sorry, I''m still new. I should''ve known better. I''ll redo the whole thing."]', '["그래도 잘 돌아가는데요. 이렇게 작은 것까지 테스트가 꼭 필요해요?","피드백 고마워요. 변수 이름 바꾸고 주석 좀 달게요.","죄송해요, 아직 신입이라. 제가 더 잘했어야 했는데. 전부 다시 할게요."]', '["Small things break too. Humor me, okay?","That''s not really what I meant. Read my comment again?","Whoa, no need to redo it. It''s a small change."]', '["작은 것도 깨져요. 그냥 해 줘요, 네?","그런 뜻은 아니었는데요. 제 댓글 다시 읽어 볼래요?","워, 다시 할 필요 없어요. 작은 수정이에요."]', '["Accept the feedback gracefully.","Key words: thanks for the feedback, split, tests"]', '["피드백을 기분 좋게 받아들이세요.","핵심 단어: thanks for the feedback, split, tests"]', 'derek', 'Appreciate it. Oh, and I''ve got one for you too, if you have time.', '고마워요. 아, 나도 하나 부탁할 게 있는데, 시간 되면요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d9_code_review', 3, 'derek', 'You review Derek''s code. A variable named data2 is confusing.', '데릭의 코드를 리뷰합니다. data2라는 변수 이름이 헷갈립니다.', 'Be honest. Anything you''d change?', '솔직하게 말해 줘요. 바꾸고 싶은 거 있어요?', 'One variable name in his code confused you. Point it out kindly.', '그의 코드에서 변수 이름 하나가 헷갈렸습니다. 부드럽게 짚어 주세요.', '[{"all":["rename"]},{"all":["name"],"any":["clearer","confusing","descriptive","better"]},{"all":["maybe","call","it"]}]', 'It looks great. One small thing: maybe rename data2 to something clearer, like storeInventory?', '아주 좋아요. 사소한 거 하나만요. data2를 storeInventory처럼 더 분명한 이름으로 바꾸면 어때요?', '["Honestly, data2 is a pretty bad name. Nobody''s going to understand what it means.","It looks great. Honestly, I wouldn''t change anything. You''re way more senior than me.","It looks great. One small thing: maybe add a few more tests for the store lookup?"]', '["솔직히 data2는 꽤 나쁜 이름이에요. 아무도 그게 뭔지 모를 거예요.","아주 좋아요. 솔직히 바꿀 건 하나도 없어요. 저보다 훨씬 선배시잖아요.","아주 좋아요. 사소한 거 하나만요. 매장 조회 테스트를 몇 개 더 넣으면 어때요?"]', '["Oof. Okay, fair, but you could''ve been a little nicer.","Come on, I asked you to be honest. Nothing at all?","Tests are already there, at the bottom. Anything else catch your eye?"]', '["윽. 그래요, 맞는 말인데, 좀 부드럽게 말해도 됐잖아요.","에이, 솔직하게 말해 달라고 했잖아요. 정말 하나도 없어요?","테스트는 맨 아래에 이미 있어요. 다른 건 눈에 띈 거 없어요?"]', '["Start with something positive, then make one small suggestion.","Key words: one small thing, rename, clearer"]', '["좋은 점을 먼저 말하고 작은 제안 하나를 하세요.","핵심 단어: one small thing, rename, clearer"]', 'derek', 'Ha, fair. data2 was a placeholder I forgot about. Nice catch. Coffee later?', '하, 맞아요. data2는 임시로 붙이고 잊어버린 거예요. 잘 찾았네요. 이따 커피 할래요?'),
  ('d9_code_review', 4, 'derek', 'Derek wants to grab coffee this afternoon.', '데릭이 오후에 커피 한잔하자고 합니다.', 'Want to grab coffee later? My treat for the review.', '이따 커피 한잔할래요? 리뷰해 준 답례로 내가 살게요.', 'Accept, and suggest meeting at 3 p.m.', '좋다고 하고 오후 3시를 제안하세요.', '[{"any":["three","3"]},{"all":["sounds good"]},{"all":["sure"]}]', 'Sure, how about around three?', '좋아요, 3시쯤 어때요?', '["Sure, how about around ten?","Sure. You''re paying, right?","Can''t, I''m too busy this week."]', '["좋아요, 10시쯤 어때요?","좋아요. 당신이 사는 거죠?","안 돼요, 이번 주는 너무 바빠요."]', '["Ten? I meant this afternoon.","Uh, yeah, I just said my treat.","Oh. No worries, another time then."]', '["10시요? 오늘 오후 말한 건데요.","어, 네, 방금 내가 산다고 했잖아요.","아. 괜찮아요, 그럼 다음에요."]', '["Say yes and name a time.","Key words: sure, around three"]', '["좋다고 하고 시간을 정하세요.","핵심 단어: sure, around three"]', 'derek', 'Three works. I''ll swing by your desk.', '3시 좋아요. 자리로 들를게요.'),
  ('d9_scope', 1, 'greg', 'Greg is back on the video call with Priya and you. He sounds rushed.', '그렉이 다시 화상 통화에 들어왔습니다. 급해 보입니다.', 'So, our board wants the dashboard and the mobile checkout app live by November first. Can you make that happen?', '그래서, 이사회가 대시보드랑 모바일 결제 앱을 11월 1일까지 오픈하길 원해요. 가능하겠어요?', 'Both by November first isn''t realistic. Tell him so, tactfully.', '11월 1일까지 둘 다는 현실적으로 불가능합니다. 요령 있게 그렇게 말하세요.', '[{"all":["commit"]},{"all":["cannot","both"]},{"all":["not","realistic"]},{"all":["tight"],"any":["date","deadline","timeline"]}]', 'I understand the pressure, but we can''t commit to that date for both projects.', '압박이 크신 건 이해하지만, 두 프로젝트 모두 그 날짜까지는 약속드릴 수 없어요.', '["I understand the pressure. We''ll make it work and get both done by November first.","That''s not realistic at all. Your board needs to be a little more reasonable.","I understand. Could your board move the date up to mid-October instead?"]', '["압박이 크신 건 이해해요. 어떻게든 11월 1일까지 둘 다 끝낼게요.","그건 전혀 현실적이지 않아요. 이사회가 좀 더 합리적이어야죠.","이해해요. 이사회에서 날짜를 10월 중순으로 당겨 줄 수 있을까요?"]', '["Really? Both? That''s great. Priya, you''re okay with that?","Well, I''ll be sure to tell them you said that.","October? That''s even sooner. Did you mean later?"]', '["정말요? 둘 다요? 좋네요. 프리야, 괜찮은 거죠?","그럼, 그렇게 말씀하셨다고 꼭 전하죠.","10월요? 그건 더 빠르잖아요. 늦추자는 말 아니었어요?"]', '["Say no to the date, but politely.","Key words: can''t commit, that date"]', '["그 날짜는 안 된다고 정중히 말하세요.","핵심 단어: can''t commit, that date"]', 'greg', 'Hmm. I was afraid you''d say that. So what can you do?', '음. 그렇게 말할까 봐 걱정했어요. 그럼 뭘 할 수 있죠?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d9_scope', 2, 'greg', 'The dashboard alone will take about eight weeks. The mobile app needs another eight.', '대시보드만 약 8주, 모바일 앱은 8주가 더 걸립니다.', 'What can you realistically deliver by November first?', '11월 1일까지 현실적으로 뭘 해 줄 수 있어요?', 'Propose doing them one after the other: the dashboard by the deadline, the app in January.', '하나씩 순서대로 하자고 제안하세요. 대시보드는 마감일까지, 앱은 1월에.', '[{"any":["phase","phased","phases","phasing"]},{"all":["dashboard"],"any":["january","later"]},{"all":["what if"],"any":["dashboard","january","split"]}]', 'What if we phased it? We deliver the dashboard by November first and the mobile app in January.', '단계를 나누면 어떨까요? 11월 1일까지 대시보드를, 1월에 모바일 앱을 드리는 거죠.', '["What if we phased it? We deliver the mobile app by November first and the dashboard in January.","We could deliver both by November first if your team tests everything every day.","Realistically? Probably not much. It depends on how fast your team gets back to us."]', '["단계를 나누면 어떨까요? 11월 1일까지 모바일 앱을, 1월에 대시보드를 드리는 거죠.","그쪽 팀이 매일 전부 테스트해 주시면 11월 1일까지 둘 다 드릴 수 있어요.","현실적으로요? 별로 없을 거예요. 그쪽 팀이 얼마나 빨리 답을 주느냐에 달렸죠."]', '["The app first? But the dashboard is what my managers need most.","Wait, you just said you couldn''t do both. Which is it?","That''s not really an answer. Give me something I can take to the board."]', '["앱 먼저요? 우리 관리자들한테 제일 급한 건 대시보드인데요.","잠깐, 방금 둘 다는 안 된다고 했잖아요. 뭐가 맞아요?","그건 답이 아니죠. 이사회에 가져갈 만한 걸 주세요."]', '["Offer to split the work into two stages.","Key words: what if we phased it, dashboard, January"]', '["일을 두 단계로 나누자고 제안하세요.","핵심 단어: what if we phased it, dashboard, January"]', 'greg', 'Phased… okay, I could sell that to the board. But what if we paid more?', '단계별이라… 좋아요, 그거면 이사회를 설득할 수 있겠어요. 그런데 돈을 더 내면요?'),
  ('d9_scope', 3, 'greg', 'Priya shakes her head slightly. Adding people late would not speed things up.', '프리야가 살짝 고개를 젓습니다. 늦게 사람을 더 넣는다고 빨라지지 않습니다.', 'Could you add more people and still do it all by November?', '사람을 더 넣어서 11월까지 전부 할 수는 없을까요?', 'Priya doesn''t think more people would help. Explain to Greg why.', '프리야는 사람을 늘려도 소용없다고 봅니다. 그 이유를 그렉에게 설명하세요.', '[{"any":["trade off","tradeoff"]},{"all":["quality"],"any":["suffer","risk","drop","worse"]},{"all":["more people"],"any":["faster","slower","help"]},{"all":["adding","people"]}]', 'Honestly, adding people this late won''t make it much faster, and quality would suffer. That''s the trade-off.', '솔직히 이렇게 늦게 사람을 넣어도 크게 빨라지지 않고, 품질이 떨어질 거예요. 그게 득실이에요.', '["Sure. If you cover the extra cost, we can bring in five more developers and hit November.","Honestly, more people won''t help much. The real problem is that your team keeps changing the requirements.","Honestly, we''d need at least twenty more people to do both, and we just don''t have them."]', '["그럼요. 추가 비용을 내 주시면 개발자 다섯 명을 더 넣어서 11월에 맞출 수 있어요.","솔직히 사람을 늘려도 별 도움이 안 돼요. 진짜 문제는 그쪽 팀이 요구 사항을 자꾸 바꾸는 거예요.","솔직히 둘 다 하려면 최소 스무 명은 더 필요한데, 저희한테 그만한 인력이 없어요."]', '["Great, let''s do it. Priya, why are you shaking your head?","We''ve had exactly one call. I''m not sure that''s fair.","So it''s just headcount? Then I''ll find you contractors."]', '["좋아요, 그렇게 하죠. 프리야, 왜 고개를 저어요?","통화 딱 한 번 했는데요. 그건 좀 억울하네요.","그럼 인원 문제일 뿐이네요? 계약직을 구해 드리죠."]', '["Explain why money and people won''t solve it.","Key words: adding people, quality, trade-off"]', '["돈과 사람으로 해결되지 않는 이유를 설명하세요.","핵심 단어: adding people, quality, trade-off"]', 'greg', 'Fair enough. I''d rather have it done right. Let''s go with the phased plan.', '그럴 만하네요. 제대로 하는 게 낫죠. 단계별 계획으로 갑시다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d9_scope', 4, 'priya', 'Priya is taking notes.', '프리야가 메모하고 있습니다.', 'Great. I''ll update the timeline. Can you confirm the plan with Greg before we hang up?', '좋아요. 제가 일정 업데이트할게요. 끊기 전에 그렉과 계획을 확인해 줄래요?', 'Recap what you agreed on, and promise the revised schedule by tomorrow.', '합의한 내용을 다시 정리하고, 수정된 일정을 내일까지 보내겠다고 하세요.', '[{"all":["confirm"]},{"all":["send","timeline"]},{"all":["phase one"],"any":["november","first","dashboard"]},{"all":["updated","timeline"]}]', 'So to confirm, phase one is the dashboard on November first, and we''ll send an updated timeline tomorrow.', '확인차 말씀드리면, 1단계는 11월 1일 대시보드이고, 내일 수정된 일정을 보내 드릴게요.', '["So to confirm, phase one is the mobile app on November first, and we''ll send a timeline tomorrow.","So to confirm, phase one is the dashboard on December first, and we''ll send an updated timeline tomorrow.","So could you send us an updated timeline from your side by tomorrow, and we''ll go from there?"]', '["확인차 말씀드리면, 1단계는 11월 1일 모바일 앱이고, 내일 일정을 보내 드릴게요.","확인차 말씀드리면, 1단계는 12월 1일 대시보드이고, 내일 수정된 일정을 보내 드릴게요.","그럼 그쪽에서 내일까지 수정된 일정을 보내 주시면, 거기서부터 진행할까요?"]', '["Wait, the dashboard comes first, right? That''s what we agreed.","December? We said November first. Let''s not slip already.","From my side? I thought Priya was updating it."]', '["잠깐, 대시보드가 먼저죠? 그렇게 합의했잖아요.","12월요? 11월 1일이라고 했잖아요. 벌써 밀리면 안 되죠.","우리 쪽에서요? 프리야가 업데이트하는 줄 알았는데요."]', '["Repeat the agreement and the next step.","Key words: to confirm, phase one, timeline"]', '["합의 내용과 다음 단계를 다시 말하세요.","핵심 단어: to confirm, phase one, timeline"]', 'greg', 'Sounds like a plan. Thanks for being straight with me.', '좋은 계획이네요. 솔직하게 말해 줘서 고마워요.'),
  ('d9_travel_booking', 1, 'tom', 'You go to the front desk to book your trip with Tom.', '출장 예약을 하러 프런트의 톰에게 갑니다.', 'Maya told me you''re heading to Ridgeport. What dates are we looking at?', '마야가 리지포트 간다고 하던데요. 날짜가 어떻게 돼요?', 'Give Tom your dates: out early on Thursday, home later on Friday.', '톰에게 날짜를 말하세요. 목요일 일찍 떠나서 금요일 늦게 돌아옵니다.', '[{"all":["thursday","friday"]},{"all":["fly out"],"any":["thursday","morning"]},{"all":["leave","thursday"]}]', 'I need to fly out Thursday morning and come back Friday afternoon.', '목요일 아침에 출발해서 금요일 오후에 돌아와야 해요.', '["I need to fly out Wednesday morning and come back Friday afternoon.","Thursday morning, and can we make it first class? It''s a long day.","I''m not sure yet. Could you check with Greg what works for him?"]', '["수요일 아침에 출발해서 금요일 오후에 돌아와야 해요.","목요일 아침이요. 그리고 일등석으로 해 주실래요? 긴 하루라서요.","아직 모르겠어요. 그렉한테 언제가 좋은지 물어봐 주실래요?"]', '["Wednesday? Maya''s approval says Thursday and Friday.","Sorry, economy only. Maya would have my head.","Me? It''s your trip. Didn''t you two already set the dates?"]', '["수요일요? 마야 승인엔 목요일, 금요일로 돼 있는데요.","미안해요, 이코노미만 돼요. 마야한테 혼나요.","제가요? 당신 출장이잖아요. 둘이 날짜 정한 거 아니었어요?"]', '["Give the departure and return days.","Key words: fly out Thursday, back Friday"]', '["출발일과 귀환일을 말하세요.","핵심 단어: fly out Thursday, back Friday"]', 'tom', 'Okay, there''s a nine-thirty on Thursday with Crestline Air. It''s a nonstop, about two hours.', '좋아요, 목요일 9시 30분 크레스트라인 항공편이 있어요. 직항이고 약 두 시간이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('d9_travel_booking', 2, 'tom', 'Tom is filling out the booking form.', '톰이 예약 양식을 채우고 있습니다.', 'Aisle or window? And do you have a frequent flyer number?', '통로석, 창가석? 그리고 마일리지 회원 번호 있어요?', 'Tell him you prefer the aisle, and that you haven''t joined their miles program.', '통로석을 원한다고 하고, 그 항공사 마일리지 프로그램에 가입하지 않았다고 하세요.', '[{"any":["aisle","window"]}]', 'Aisle, please. And I don''t have a frequent flyer number yet.', '통로석으로 부탁해요. 그리고 마일리지 회원 번호는 아직 없어요.', '["Window, please. And I don''t have a frequent flyer number yet.","Aisle. And can you get me extra legroom? I''m kind of tall.","Aisle, please. My frequent flyer number should be in my file."]', '["창가석으로 부탁해요. 그리고 마일리지 회원 번호는 아직 없어요.","통로석요. 그리고 다리 공간 넓은 자리로 해 주실래요? 제가 키가 좀 커서요.","통로석으로 부탁해요. 마일리지 번호는 제 기록에 있을 거예요."]', '["Window? I had you down as an aisle person. Okay, window.","That costs extra. Policy''s plain economy, sorry.","Hmm, I don''t see one here. Are you sure you have one?"]', '["창가요? 통로 좋아하는 줄 알았는데. 알겠어요, 창가로.","그건 추가 요금이에요. 규정상 일반 이코노미예요, 미안해요.","음, 여기엔 없는데요. 번호 있는 거 확실해요?"]', '["Choose a seat by the aisle or the window.","Key words: aisle or window"]', '["통로 쪽이나 창가 쪽을 고르세요.","핵심 단어: aisle 또는 window"]', 'tom', 'Aisle it is. I''ll sign you up for their program so you get the miles.', '통로석으로 할게요. 마일리지 받게 회원 가입도 해 둘게요.'),
  ('d9_travel_booking', 3, 'tom', 'Now the hotel. The policy cap is two hundred dollars a night.', '이제 호텔입니다. 규정상 한도는 1박 200달러입니다.', 'There''s the Pinecrest Hotel near Summit''s office, one eighty-nine a night. That''s under the cap.', '서밋 사무실 근처에 파인크레스트 호텔이 있어요. 1박 189달러. 한도 안이에요.', 'Before he books it, find out how far it is from Summit''s office and whether you get a morning meal.', '예약하기 전에 서밋 사무실에서 얼마나 먼지, 아침이 나오는지 물어보세요.', '[{"all":["walking distance"]},{"all":["breakfast"],"any":["included","include","includes","come with"]},{"all":["walk"],"any":["office","client"]},{"all":["how far"]}]', 'Is it within walking distance of their office? And is breakfast included?', '고객사 사무실까지 걸어갈 수 있는 거리예요? 그리고 아침 식사 포함이에요?', '["One eighty-nine? Isn''t that over the two hundred cap, though?","Can we find something nicer? I''d like a place with a pool.","Is it close to the airport? And does it have free parking for guests?"]', '["189달러요? 그거 200달러 한도 넘지 않아요?","좀 더 좋은 데 없을까요? 수영장 있는 데면 좋겠어요.","공항에서 가까운 편이에요? 그리고 투숙객 무료 주차도 되나요?"]', '["No, it''s under. One eighty-nine is less than two hundred.","On a two-hundred cap? This is about as nice as it gets.","Airport''s twenty minutes. But you won''t have a car, right?"]', '["아뇨, 안 넘어요. 189는 200보다 적잖아요.","200달러 한도로요? 이 정도면 제일 좋은 편이에요.","공항은 20분이요. 근데 차 없잖아요?"]', '["Ask about the distance and the breakfast.","Key words: walking distance, breakfast included"]', '["거리와 아침 식사를 물어보세요.","핵심 단어: walking distance, breakfast included"]', 'tom', 'Five-minute walk, and yes, breakfast is included. I''ll put it all on the company card.', '걸어서 5분이고, 네, 조식 포함이에요. 전부 법인 카드로 할게요.'),
  ('d9_travel_booking', 4, 'tom', 'You will also need to get from the Ridgeport airport to the hotel.', '리지포트 공항에서 호텔까지도 가야 합니다.', 'Ground transportation is on you, but it''s reimbursable. Just keep the receipts.', '현지 교통비는 본인이 내는데, 환급돼요. 영수증만 챙겨요.', 'Ask whether you can use a ride-hailing app from the airport or should stick to the shuttle.', '공항에서 차량 호출 앱을 써도 되는지, 셔틀을 타야 하는지 물어보세요.', '[{"all":["rideshare"]},{"all":["ride share"]},{"all":["taxi"]},{"all":["cab"]},{"all":["shuttle"]}]', 'Is it okay to take a rideshare from the airport, or should I take the shuttle?', '공항에서 차량 호출 서비스를 타도 괜찮아요, 아니면 셔틀을 타야 해요?', '["Can I just rent a car at the airport and keep it for the whole trip instead?","So I have to pay for the ride myself? That doesn''t seem fair.","Could you put the airport ride on the company card for me now?"]', '["그냥 공항에서 차를 빌려서 출장 내내 써도 돼요?","그럼 차비를 제가 내야 해요? 그건 좀 불공평한데요.","공항 가는 차비도 지금 법인 카드로 결제해 주실래요?"]', '["You could, but the hotel''s a five-minute walk from Summit.","You get it back. Just keep the receipts, like I said.","I can''t. Ground transportation''s on you, then you expense it."]', '["그래도 되지만, 호텔에서 서밋까지 걸어서 5분이에요.","돌려받아요. 말했듯이 영수증만 챙기면 돼요.","그건 안 돼요. 현지 교통비는 직접 내고 경비 청구해요."]', '["Ask how you should get to the hotel.","Key words: rideshare, taxi, shuttle"]', '["호텔까지 무엇을 타고 가야 하는지 물어보세요.","핵심 단어: rideshare, taxi, shuttle"]', 'tom', 'A rideshare is fine, up to fifty bucks each way. Here''s your itinerary. Have a good trip!', '차량 호출 괜찮아요, 편도 50달러까지요. 여기 여행 일정표예요. 잘 다녀와요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_buddy', 1, 'maya', 'Monday morning. Maya waves at you from her office door with a checklist in her hand.', '월요일 아침입니다. 마야가 체크리스트를 든 채 사무실 문 앞에서 손짓합니다.', 'Morning, Derek. Got a minute? I have a favor to ask.', '좋은 아침이에요, 데릭. 잠깐 시간 돼요? 부탁할 게 있어요.', 'You have some time. Let her know, and find out what she needs.', '시간은 있습니다. 그렇게 말하고, 무슨 일인지 알아보세요.', '[{"all":["what is up"]},{"all":["what do you need"]},{"any":["sure","absolutely"]},{"all":["of course"]}]', 'Sure, I''ve got a few minutes. What''s up?', '그럼요, 몇 분 정도는 괜찮아요. 무슨 일이에요?', '["Not really. Could you put it in an email?","Sure, whatever it is, the answer is yes.","Sure. Uh-oh, did I break something?"]', '["별로요. 메일로 보내 주실 수 있어요?","그럼요, 뭔지 몰라도 무조건 할게요. 다 좋아요.","네. 이런, 제가 뭐 망가뜨렸어요?"]', '["It''s quicker in person. Two minutes, I promise.","Careful. You haven''t even heard it yet.","No, nothing''s broken. It''s a favor, remember?"]', '["직접 말하는 게 빨라요. 2분이면 돼요, 약속해요.","조심해요. 아직 들어 보지도 않았잖아요.","아뇨, 망가진 건 없어요. 부탁이라니까요."]', '["Show you have time, then ask what she needs.","Key words: sure, what''s up"]', '["시간이 있다고 하고, 무엇이 필요한지 물어보세요.","핵심 단어: sure, what''s up"]', 'maya', 'Our new developer, Jun, starts today. I''d like you to be his onboarding buddy.', '새 개발자 준이 오늘 입사해요. 당신이 온보딩 버디를 맡아 주면 좋겠어요.'),
  ('dk_d1_buddy', 2, 'maya', 'She turns her laptop so you can see the onboarding checklist.', '그녀가 노트북을 돌려 온보딩 체크리스트를 보여 줍니다.', 'It means showing him the ropes for the first few weeks: the setup, the codebase, how we work. Are you up for it?', '처음 몇 주 동안 이것저것 알려 주는 거예요. 개발 환경 설정, 코드베이스, 우리가 일하는 방식 같은 거요. 해 줄 수 있어요?', 'Agree, and find out what experience he''s coming in with.', '수락하고, 그가 어떤 경력을 가지고 오는지 알아보세요.', '[{"all":["happy to"]},{"all":["glad to"]},{"all":["love to"]},{"any":["background","experience"]},{"all":["count me in"]}]', 'I''d be happy to. What''s his background?', '기꺼이 할게요. 어떤 경력이 있는 사람이에요?', '["I guess so. Does it have to be me, though?","I''d be happy to. When does he start, then?","Sure. Is he any good, or just a body?"]', '["그러죠, 뭐. 근데 꼭 제가 해야 해요?","기꺼이 할게요. 그럼 언제부터 출근해요?","그러죠. 잘하는 사람이에요, 아니면 그냥 머릿수예요?"]', '["It doesn''t have to be, but you''re my first choice.","Today, Derek. He''s probably in the lobby already.","He''s a person, Derek. And yes, he''s good."]', '["꼭 그런 건 아니지만, 당신이 1순위예요.","오늘이요, 데릭. 아마 벌써 로비에 와 있을 거예요.","사람이에요, 데릭. 그리고 네, 잘해요."]', '["Accept warmly with \\"I''d be happy to.\\"","Key words: happy to, background"]', '["\\"I''d be happy to.\\"로 흔쾌히 수락하세요.","핵심 단어: happy to, background"]', 'maya', 'Three years of backend work in Seoul. This is his first job in the US, so a lot will be new to him.', '서울에서 백엔드 개발을 3년 했어요. 미국에서는 첫 직장이라 낯선 게 많을 거예요.'),
  ('dk_d1_buddy', 3, 'maya', 'Maya knows your sprint is already full.', '마야는 당신의 스프린트가 이미 꽉 찼다는 것을 압니다.', 'I know you''re busy with the checkout rebuild. Do you have the bandwidth for this?', '결제 개편으로 바쁜 거 알아요. 이것까지 맡을 여유가 있어요?', 'Say yes, but be honest that your sprint is full and something may have to slip.', '하겠다고 하되, 스프린트가 꽉 차서 뭔가 밀릴 수도 있다고 솔직히 말하세요.', '[{"all":["make time"]},{"all":["push"],"any":["ticket","tickets","sprint"]},{"all":["bandwidth"]}]', 'I can make time, but I might need to push one of my tickets to the next sprint.', '시간은 낼 수 있어요. 다만 제 티켓 하나는 다음 스프린트로 미뤄야 할 수도 있어요.', '["No problem at all. I can easily do it on top of everything else without anything slipping.","Honestly, I don''t. Could you ask someone else to take him this time?","I can make time, but I''ll need you to cancel all of my meetings for the next month."]', '["전혀 문제없어요. 다른 일 하나도 안 밀리고 전부 거뜬히 같이 할 수 있어요.","솔직히 여유가 없어요. 이번엔 다른 사람한테 부탁해 주실 수 있어요?","시간은 낼게요. 대신 한 달 동안 제 회의를 전부 빼 주셔야 해요."]', '["Derek, your sprint is already full. Let''s be realistic.","Hm. I was really hoping it''d be you.","All of them? That''s a lot. What''s the smallest thing that would help?"]', '["데릭, 스프린트 이미 꽉 찼잖아요. 현실적으로 생각해요.","음. 꼭 당신이 맡아 주길 바랐는데요.","전부요? 그건 좀 많네요. 최소한 뭐가 있으면 될까요?"]', '["Say yes, and name the cost honestly.","Key words: make time, push a ticket"]', '["하겠다고 하되, 그 대가를 솔직히 말하세요.","핵심 단어: make time, push a ticket"]', 'maya', 'That''s reasonable. Tell Priya which one, and I''ll back you up.', '그럴 만해요. 어느 티켓인지 프리야에게 말해요. 제가 힘을 실어 줄게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_buddy', 4, 'maya', 'She checks a box on her list.', '그녀가 목록의 칸 하나에 체크합니다.', 'One more thing. When you review his first pull request, be kind but honest, okay?', '하나 더요. 그 친구 첫 풀 리퀘스트를 리뷰할 때, 친절하되 솔직하게 해 줘요, 알았죠?', 'Agree, and promise to keep a close eye on him during his first week.', '그러겠다고 하고, 첫 주 동안 그를 꼼꼼히 챙기겠다고 약속하세요.', '[{"all":["check in"]},{"all":["checking in"]},{"all":["every day"]}]', 'Of course. I''ll check in with him every day this week.', '물론이죠. 이번 주에는 매일 그 친구 상황을 살필게요.', '["Of course. I''ll just approve it so he doesn''t feel bad.","Sure, but I don''t sugarcoat. He''ll have to toughen up.","Of course. I''ll have Priya review it. She knows the code."]', '["물론이죠. 기분 상하지 않게 그냥 승인해 줄게요.","네, 근데 전 돌려 말 안 해요. 알아서 버텨야죠.","물론이죠. 프리야한테 리뷰를 맡길게요. 코드를 잘 아니까요."]', '["Kind, yes. But honest, too. A rubber stamp won''t help him.","It''s his first day, Derek. Kind and honest. Both.","Priya? She''s our PM. I need you on the code review."]', '["친절하게는 맞아요. 하지만 솔직하게도요. 무조건 승인은 도움이 안 돼요.","입사 첫날이에요, 데릭. 친절하고 솔직하게. 둘 다요.","프리야요? 그녀는 PM이에요. 코드 리뷰는 당신이 해 줘야죠."]', '["\\"Check in with someone\\" = talk briefly to see how they are doing.","Key words: check in with him, every day"]', '["check in with someone은 잘 지내는지 잠깐 이야기해 본다는 뜻입니다.","핵심 단어: check in with him, every day"]', 'maya', 'Perfect. Let me know if you have any questions.', '좋아요. 궁금한 게 있으면 말해 줘요.'),
  ('dk_d1_coffee', 1, 'nina', 'The coffee cart on Lake Avenue. Nina spots you in line and is already reaching for a large cup.', '레이크 애비뉴의 커피 카트입니다. 줄 서 있는 당신을 본 니나가 벌써 큰 컵을 집어 듭니다.', 'Morning, Derek! The usual?', '좋은 아침이에요, 데릭! 늘 드시던 걸로요?', 'Nina already knows your order. Go along with it.', '니나는 이미 당신 주문을 알고 있습니다. 그대로 부탁하세요.', '[{"all":["usual"]},{"all":["same as always"]}]', 'Morning, Nina! Yeah, the usual, please.', '좋은 아침이에요, 니나! 네, 늘 먹던 걸로 주세요.', '["Morning! Hmm, let me look at the menu first.","Morning, Nina! Yeah, a small iced tea, please.","Obviously. Same as every day, Nina."]', '["좋은 아침이에요! 음, 메뉴 먼저 좀 볼게요.","좋은 아침이에요, 니나! 네, 아이스티 스몰로 주세요.","당연하죠. 맨날 먹는 그거요, 뻔하잖아요, 니나."]', '["Take your time. It''s the same menu as yesterday, though.","Iced tea? You? I already grabbed a large cup for your dark roast.","Okay... somebody''s not a morning person today."]', '["천천히 보세요. 근데 어제랑 메뉴 똑같아요.","아이스티요? 데릭이요? 다크 로스트 하려고 벌써 큰 컵 집었는데요.","네... 오늘은 아침부터 기분이 별로신가 봐요."]', '["A regular does not need to name the drink.","Key words: the usual"]', '["단골은 음료 이름을 말할 필요가 없습니다.","핵심 단어: the usual"]', 'nina', 'One large dark roast with room for cream. Coming right up!', '다크 로스트 라지, 크림 넣을 자리 남겨서. 바로 나와요!'),
  ('dk_d1_coffee', 2, 'nina', 'Nina fills the cup while she talks.', '니나가 이야기하면서 컵을 채웁니다.', 'So how''s your morning going? Busy day ahead?', '아침은 어때요? 오늘 바쁜 하루예요?', 'Make a little small talk: things are fine, but today will be packed.', '가볍게 대화하세요. 지내는 건 괜찮지만 오늘은 일이 많을 거라고요.', '[{"all":["complain"]},{"any":["busy","hectic","packed","slammed"]}]', 'Can''t complain. It''s going to be a busy one, though.', '그럭저럭 괜찮아요. 근데 오늘은 바쁠 것 같아요.', '["Pretty quiet, actually. I''ve got nothing on my calendar.","Honestly, terrible. I barely slept and my inbox is a disaster.","Busy. Can we just do the coffee, please?"]', '["사실 한가해요. 일정이 하나도 없어요.","솔직히 최악이에요. 잠도 거의 못 잤고 메일함은 엉망이에요.","바빠요. 그냥 커피나 주시면 안 될까요?"]', '["Lucky you! Enjoy the slow day.","Oh no. Well... I''ll make it extra strong, I guess.","Sure. Sorry, didn''t mean to hold you up."]', '["부럽네요! 여유로운 하루 즐기세요.","어머. 음... 그럼 특별히 진하게 해 드릴게요.","네. 붙잡으려던 건 아니었어요, 미안해요."]', '["Answer the small talk briefly: fine, but a lot to do.","Key words: can''t complain, busy"]', '["잡담에 짧게 답하세요. 괜찮지만 할 일이 많다고요.","핵심 단어: can''t complain, busy"]', 'nina', 'Then you''ll need this. I made it extra strong.', '그럼 이게 필요하겠네요. 특별히 진하게 내렸어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_coffee', 3, 'nina', 'A tray of muffins sits next to the register. They smell great.', '계산대 옆에 머핀 한 판이 놓여 있습니다. 냄새가 아주 좋습니다.', 'Want anything to eat with that? The blueberry muffins just came in.', '같이 드실 거 있어요? 블루베리 머핀 방금 들어왔어요.', 'The muffins look good, but you''re watching your sugar. Say no nicely.', '머핀이 맛있어 보이지만 당분을 조절하는 중입니다. 기분 좋게 거절하세요.', '[{"all":["i am good"]},{"all":["cut back"]},{"all":["cutting back"]},{"all":["no thanks"]},{"all":["i will pass"]}]', 'I''m good, thanks. I''m trying to cut back on sweets.', '괜찮아요, 고마워요. 단것 좀 줄이는 중이라서요.', '["Sure, I''ll take one. Blueberry sounds great.","No. Those things are basically cake, you know.","I''m good, thanks. I''m trying to cut back on coffee."]', '["좋아요, 하나 주세요. 블루베리 맛있겠네요.","됐어요. 그거 사실상 케이크잖아요.","괜찮아요, 고마워요. 커피를 좀 줄이는 중이라서요."]', '["Sure! Wait, didn''t you tell me last week you were off sweets?","Wow. Okay. I''ll let the bakery know.","Cut back on coffee? You''re about to get a large dark roast, Derek."]', '["그래요! 잠깐, 지난주에 단것 끊는다고 하지 않았어요?","와. 네. 빵집에 그렇게 전해 둘게요.","커피를 줄인다고요? 지금 다크 로스트 라지 받으려는 참이잖아요, 데릭."]', '["In the US, \\"I''m good\\" is a polite way to say no.","Key words: I''m good, cut back on"]', '["미국에서 \\"I''m good\\"은 정중하게 사양하는 말입니다.","핵심 단어: I''m good, cut back on"]', 'nina', 'Good for you. More for me, then!', '대단하네요. 그럼 제가 더 먹죠!'),
  ('dk_d1_coffee', 4, 'nina', 'She stamps your punch card. It is full.', '그녀가 쿠폰 카드에 도장을 찍습니다. 칸이 다 찼습니다.', 'That''s four fifty. And your card is full, so the next one''s on the house.', '4달러 50센트예요. 그리고 쿠폰이 다 찼으니까 다음 잔은 공짜예요.', 'Pay, let her keep the difference, and say goodbye warmly.', '계산하면서 남는 돈은 가지라고 하고, 다정하게 인사하세요.', '[{"all":["keep the change"]},{"all":["good one"]},{"all":["good day"]},{"all":["great day"]}]', 'Thanks, Nina. Keep the change. Have a good one!', '고마워요, 니나. 잔돈은 됐어요. 좋은 하루 보내요!', '["Thanks, Nina. So that''s three fifty, right? Here.","Oh, so this one''s free? Thanks a lot, Nina!","Here''s five. Fifty cents back, please. Bye."]', '["고마워요, 니나. 그러면 3달러 50센트죠? 여기요.","오, 그럼 이번 건 공짜예요? 정말 고마워요, 니나!","여기 5달러요. 50센트 거슬러 주세요. 그럼."]', '["It''s four fifty, Derek. Prices went up in the spring.","Ha, nice try. The next one''s free, not this one.","Oh. Sure, here''s your fifty cents."]', '["4달러 50센트예요, 데릭. 봄에 가격 올랐잖아요.","하, 어림없죠. 공짜는 다음 잔이에요, 이번 거 말고요.","아. 네, 여기 50센트요."]', '["Leave the change as a tip and say goodbye.","Key words: keep the change, have a good one"]', '["거스름돈을 팁으로 남기고 작별 인사를 하세요.","핵심 단어: keep the change, have a good one"]', 'nina', 'You too, Derek! Don''t work too hard.', '데릭도요! 너무 무리하지 말고요.'),
  ('dk_d1_standup', 1, 'priya', 'The team stands around the screen in the meeting room. Jun, the new hire, has just introduced himself.', '팀이 회의실 화면 앞에 둘러서 있습니다. 신입 준이 방금 자기소개를 마쳤습니다.', 'Okay, let''s keep going. Derek, you''re up. Where are we with the checkout API?', '자, 계속하죠. 데릭 차례예요. 결제 API는 어디까지 됐어요?', 'Give your update: you finished the checkout API work last week, and it''s waiting on a reviewer.', '근황을 말하세요. 결제 API 작업은 지난주에 끝났고, 지금 리뷰를 기다리고 있습니다.', '[{"all":["wrapped up"]},{"all":["in review"]},{"any":["finished","merged"]}]', 'Last week I wrapped up the checkout API changes. They''re in review now.', '결제 API 수정은 지난주에 마무리했어요. 지금 리뷰 중이에요.', '["Last week I wrapped up the checkout API changes. They''re live in production now.","Well, it''s a long story. Let me walk you through every file I touched.","It''s done, but nobody has reviewed it yet. Not sure what everyone''s doing."]', '["결제 API 수정은 지난주에 끝냈고요. 지금 운영 환경에 배포돼 있어요.","음, 얘기가 길어요. 제가 고친 파일을 하나하나 다 설명할게요.","다 됐는데 아직 아무도 리뷰를 안 했어요. 다들 뭐 하는지 모르겠네요."]', '["Live already? I thought it still needed a review.","Maybe the short version? We''ve got a few more people to go.","Okay... let''s not call people out in standup."]', '["벌써 배포됐어요? 아직 리뷰가 필요한 줄 알았는데요.","짧게 해 줄래요? 아직 몇 명 더 남았어요.","음... 스탠드업에서 누굴 탓하진 말죠."]', '["Say what is done and where it is now.","Key words: wrapped up, in review"]', '["무엇을 끝냈고 지금 어떤 상태인지 말하세요.","핵심 단어: wrapped up, in review"]', 'priya', 'Nice. One less thing on the board.', '좋아요. 보드에서 하나 줄었네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_standup', 2, 'priya', 'Priya moves your card on the board.', '프리야가 보드에서 당신의 카드를 옮깁니다.', 'And what''s on your plate today?', '그럼 오늘은 뭐 해요?', 'Tell her your plan for today: the saved cards ticket, plus getting Jun up and running.', '오늘 계획을 말하세요. 저장된 카드 티켓, 그리고 준이 일을 시작할 수 있게 돕는 것.', '[{"all":["picking up"]},{"all":["working on"]},{"all":["set up"]},{"all":["helping","jun"]}]', 'Today I''m picking up the saved cards ticket and helping Jun get set up.', '오늘은 저장된 카드 티켓을 시작하고, 준의 환경 설정을 도울 거예요.', '["Today I''m picking up the gift card ticket and helping Jun get his laptop set up.","I''m mostly blocked today, so not much going on until I hear back from someone.","Today I''m finishing saved cards and gift cards, and onboarding Jun."]', '["오늘은 기프트 카드 티켓을 시작하고, 준의 노트북 환경 설정을 도울 거예요.","오늘은 거의 막혀 있어서, 누가 답을 줄 때까진 별로 할 게 없어요.","오늘 저장된 카드랑 기프트 카드 다 끝내고, 준 온보딩도 할게요."]', '["Gift cards? That''s not even on the board yet.","Hold that thought, we''ll get to blockers. What are you picking up?","All in one day? Let''s be realistic, Derek."]', '["기프트 카드요? 그건 아직 보드에도 없는데요.","그건 잠깐만요, 블로커는 이따 해요. 오늘 맡을 건요?","그걸 하루에 다요? 현실적으로 가요, 데릭."]', '["\\"Pick up a ticket\\" = start working on it.","Key words: picking up, get set up"]', '["pick up a ticket은 그 일을 시작한다는 뜻입니다.","핵심 단어: picking up, get set up"]', 'priya', 'Great. Thanks for looking after him.', '좋아요. 준을 챙겨 줘서 고마워요.'),
  ('dk_d1_standup', 3, 'priya', 'She looks up from her laptop.', '그녀가 노트북에서 고개를 듭니다.', 'Any blockers?', '블로커 있어요?', 'Summit Retail still hasn''t sent you their API keys. Ask Priya to chase it.', '서밋 리테일이 아직 API 키를 보내지 않았습니다. 프리야에게 챙겨 달라고 하세요.', '[{"all":["waiting on"]},{"all":["waiting for"]},{"all":["follow up"]},{"all":["blocked"]}]', 'Just one. I''m still waiting on the API keys from Summit Retail. Could you follow up with them?', '하나 있어요. 서밋 리테일 API 키를 아직 기다리고 있어요. 그쪽에 확인 좀 해 주시겠어요?', '["Nope, nothing''s really blocking me. I''ll ping you later if the Summit Retail keys don''t show up.","Just one. I''m still waiting on the API keys from Sam in IT. Could you follow up with him?","Just one. Summit Retail is dragging their feet as usual. Can you light a fire under Greg''s team?"]', '["아뇨, 딱히 막힌 건 없어요. 서밋 리테일 키가 안 오면 나중에 말씀드릴게요.","하나 있어요. IT팀 샘한테서 API 키를 아직 기다리고 있어요. 그쪽에 확인 좀 해 주시겠어요?","하나 있어요. 서밋 리테일이 늘 그렇듯 늑장을 부리네요. 그렉네 팀에 불 좀 붙여 주실래요?"]', '["Wait, you don''t have their keys yet? That sounds like a blocker.","Sam? I thought the keys were coming from the client.","Easy. Greg''s a client, not a teammate."]', '["잠깐, 아직 키를 못 받았어요? 그게 블로커 같은데요.","샘이요? 키는 고객사에서 오는 줄 알았는데요.","진정해요. 그렉은 고객이지, 우리 팀원이 아니에요."]', '["Name what you are waiting on, and ask for help.","Key words: waiting on, follow up"]', '["무엇을 기다리는지 말하고 도움을 청하세요.","핵심 단어: waiting on, follow up"]', 'priya', 'I''ll ping Greg''s team right after this.', '끝나자마자 그렉 팀에 연락할게요.'),
  ('dk_d1_standup', 4, 'priya', 'The standup is at minute twelve. Priya remembers one more thing.', '스탠드업이 12분째입니다. 프리야가 한 가지를 더 떠올립니다.', 'Oh, and Summit Retail asked about gift card support. Derek, how big is that? Can we talk it through now?', '아, 그리고 서밋 리테일이 기프트 카드 지원에 대해 물어봤어요. 데릭, 그거 얼마나 큰 일이에요? 지금 같이 얘기해 볼 수 있을까요?', 'This would eat up everyone''s time. Suggest discussing it later, just the two of you.', '다 같이 시간을 뺏길 이야기입니다. 나중에 둘이서 따로 이야기하자고 하세요.', '[{"all":["offline"]},{"all":["after standup"]},{"all":["after the standup"]},{"any":["separately"]}]', 'Let''s take that offline. I don''t want to hold up the standup.', '그건 따로 얘기하죠. 스탠드업을 붙잡아 두고 싶진 않아요.', '["Sure, let''s dig in right now. So first, the payment form would need...","That''s small. Probably two days. You can tell them yes.","Not now, Priya. This isn''t the place for that."]', '["좋아요, 지금 바로 파 보죠. 우선 결제 양식에 필요한 게...","그건 작아요. 아마 이틀이면 돼요. 된다고 하셔도 돼요.","지금은 아니에요, 프리야. 여기서 할 얘기가 아니에요."]', '["Hmm, we''re at minute twelve already...","Two days? You''re sure? I''ll pass that on to Greg.","Okay. No need to snap at me."]', '["음, 벌써 12분째인데요...","이틀이요? 확실해요? 그렉한테 그렇게 전할게요.","알겠어요. 쏘아붙일 필요까진 없잖아요."]', '["\\"Take it offline\\" = discuss it later, outside this meeting.","Key words: take that offline"]', '["take it offline은 이 회의 밖에서 나중에 이야기하자는 뜻입니다.","핵심 단어: take that offline"]', 'priya', 'Good call. I''ll put thirty minutes on our calendars for tomorrow.', '좋은 판단이에요. 내일 30분 일정을 잡아 둘게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_welcome', 1, 'jun', 'A young man is unpacking a new laptop at the desk next to yours. You stuck a "Welcome!" note on his monitor this morning.', '당신 옆자리에서 한 청년이 새 노트북을 꺼내고 있습니다. 오늘 아침 당신이 그의 모니터에 "Welcome!" 쪽지를 붙여 두었습니다.', 'Oh, hi. Excuse me, are you Derek? Maya said I should come find you.', '아, 안녕하세요. 실례지만 데릭 맞으세요? 마야가 찾아가 보라고 해서요.', 'This is the new hire. Confirm who you are and make him feel welcome.', '새로 온 직원입니다. 당신이 누군지 확인해 주고 반갑게 맞아 주세요.', '[{"all":["welcome"]}]', 'That''s me. You must be Jun. Welcome to the team!', '네, 저예요. 준이죠? 팀에 온 걸 환영해요!', '["That''s me. You must be Tom. Welcome to the team!","Yeah. Give me a minute, I''m in the middle of something.","That''s me. Did Maya send over your paperwork?"]', '["네, 저예요. 톰이죠? 팀에 온 걸 환영해요!","네. 잠깐만요, 지금 하던 게 있어서요.","네, 저예요. 마야가 서류 같은 거 보내라던가요?"]', '["Um, it''s Jun, actually. Jun Kim.","Oh, sorry. I''ll... wait over here.","Paperwork? I don''t think so. She just said to find you."]', '["어, 준이에요. 준 김이요.","아, 죄송해요. 저기서... 기다릴게요.","서류요? 아닐 거예요. 그냥 데릭을 찾아가라고만 했어요."]', '["Confirm who you are, then welcome him.","Key words: you must be Jun, welcome"]', '["당신이 맞다고 하고 환영하세요.","핵심 단어: you must be Jun, welcome"]', 'jun', 'Thank you! Nice to meet you. I''m a little nervous, honestly.', '감사합니다! 만나서 반갑습니다. 사실 조금 긴장돼요.'),
  ('dk_d1_welcome', 2, 'jun', 'Jun opens the laptop. The screen is still empty.', '준이 노트북을 엽니다. 화면은 아직 텅 비어 있습니다.', 'I haven''t set up my dev environment yet. Where should I start?', '아직 개발 환경 설정을 못 했어요. 어디서부터 시작하면 될까요?', 'Offer to guide him step by step, and point him to the setup doc in the repo.', '차근차근 같이 하자고 하고, 저장소의 설치 안내 문서부터 보라고 하세요.', '[{"all":["walk you through"]},{"any":["readme"]},{"all":["setup guide"]},{"all":["show you"]}]', 'No worries. Let me walk you through it. Start with the README in the repo.', '걱정 마요. 제가 하나씩 알려 줄게요. 저장소의 README부터 시작해요.', '["It''s all in the docs somewhere in the wiki. You''ll figure it out on your own, I''m sure.","No worries. Skip the docs and just start fixing bugs right away.","Let me just set it all up for you tonight. You don''t really need to learn any of it."]', '["위키 어딘가 문서에 다 있어요. 혼자서도 알아서 할 수 있을 거예요.","걱정 마요. 문서는 건너뛰고, 그냥 바로 버그부터 고치기 시작해요.","오늘 밤에 제가 다 설정해 둘게요. 그런 건 굳이 하나도 배울 필요 없어요."]', '["Oh... okay. I''ll try to find it.","Without setting anything up? Won''t the code fail to run?","That''s kind, but I''d like to learn how it works."]', '["아... 네. 한번 찾아볼게요.","아무것도 설정 안 하고요? 그럼 코드가 안 돌지 않나요?","감사하지만, 저도 어떻게 하는지 배우고 싶어요."]', '["\\"Walk someone through\\" = explain step by step.","Key words: walk you through, README"]', '["walk someone through는 단계별로 설명해 준다는 뜻입니다.","핵심 단어: walk you through, README"]', 'jun', 'Great. I''ll clone the repo right now.', '좋아요. 지금 바로 저장소를 클론할게요.'),
  ('dk_d1_welcome', 3, 'jun', 'The setup script prints a wall of red text. Jun''s face falls.', '설치 스크립트가 빨간 글씨를 가득 쏟아 냅니다. 준의 얼굴이 어두워집니다.', 'Um, the tests are failing on my machine. Did I break something?', '어, 제 컴퓨터에서 테스트가 실패해요. 제가 뭘 망가뜨린 건가요?', 'He''s panicking. Calm him down: this is normal for a first day.', '그가 당황했습니다. 진정시키세요. 첫날에는 흔한 일이라고요.', '[{"all":["happens to"]},{"any":["worry","worries"]},{"all":["did not break"]},{"all":["not your fault"]}]', 'Don''t worry, you didn''t break anything. It happens to everybody on day one.', '걱정 마요, 망가뜨린 거 없어요. 첫날엔 다들 이래요.', '["Hmm, maybe. Did you change any of the config before you ran the setup script?","Don''t worry about the tests. Just skip them for now and push your code anyway.","Wow, day one and you already broke the build? That''s a record."]', '["음, 그럴 수도요. 스크립트 돌리기 전에 설정 뭐 건드렸어요?","테스트는 신경 쓰지 마요. 일단 건너뛰고 그냥 코드 올려요.","와, 첫날부터 빌드를 깨뜨렸어요? 신기록이네요."]', '["No, I just ran it like the README said...","Skip them? Is that... allowed here?","Oh no. I knew it."]', '["아뇨, README에 나온 대로 실행만 했는데요...","건너뛰라고요? 여기선 그래도... 돼요?","아, 이런. 그럴 줄 알았어요."]', '["Tell him it is normal and not his fault.","Key words: don''t worry, happens to everybody"]', '["흔한 일이고 그의 잘못이 아니라고 말해 주세요.","핵심 단어: don''t worry, happens to everybody"]', 'jun', 'That''s a relief. I thought I broke the build on my first day.', '다행이네요. 첫날부터 빌드를 깨뜨린 줄 알았어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d1_welcome', 4, 'jun', 'You fix the missing setting together. The tests turn green.', '빠진 설정을 함께 고칩니다. 테스트가 초록색으로 바뀝니다.', 'Sorry, I have so many questions. I don''t want to bother you.', '죄송해요, 질문이 너무 많네요. 귀찮게 해 드리고 싶진 않은데.', 'Make it clear his questions are welcome, whenever he has them.', '질문은 언제든 환영이라는 걸 확실히 알려 주세요.', '[{"all":["ping me"]},{"any":["anytime","dumb","stupid"]},{"all":["any time"]},{"all":["not bothering"]}]', 'You''re not bothering me. Just ping me anytime. There are no dumb questions.', '전혀 귀찮지 않아요. 언제든 메시지 보내요. 바보 같은 질문은 없어요.', '["That''s okay. Maybe save them up, though, and ask me all at once at the end of the day.","Most of it is in the docs. Try searching there before you ask me.","Don''t worry. I''ll ask Maya to find you someone with more time."]', '["괜찮아요. 근데 모아 뒀다가 퇴근할 때 한꺼번에 물어봐요.","웬만한 건 문서에 있어요. 저한테 묻기 전에 먼저 찾아봐요.","걱정 마요. 마야한테 시간 여유 있는 사람을 찾아 달라고 할게요."]', '["Oh, okay. I''ll write them down and wait.","Right. Sorry. I''ll look there first.","Oh, no, I didn''t mean... I''m happy working with you."]', '["아, 네. 적어 두고 기다릴게요.","그렇죠. 죄송해요. 먼저 찾아볼게요.","아, 아니에요, 그런 뜻이 아니라... 데릭이랑 하는 게 좋아요."]', '["Make it safe to ask: \\"ping me\\", \\"no dumb questions\\".","Key words: ping me anytime, no dumb questions"]', '["편하게 물어볼 수 있게 해 주세요. \\"ping me\\", \\"no dumb questions\\".","핵심 단어: ping me anytime, no dumb questions"]', 'jun', 'Thanks, Derek. That really helps.', '고마워요, 데릭. 정말 도움이 돼요.'),
  ('dk_d1_welcome', 5, 'jun', 'Jun opens the ticket board.', '준이 티켓 보드를 엽니다.', 'What should I work on first, once everything is running?', '다 돌아가게 되면, 뭐부터 하면 될까요?', 'Suggest an easy first task, and say you''ll look at his code tomorrow morning.', '부담 없는 첫 과제를 권하고, 내일 아침에 그의 코드를 봐 주겠다고 하세요.', '[{"all":["pull request"]},{"all":["small"],"any":["bug","ticket","fix","issue"]},{"any":["review"]}]', 'Start with a small bug fix and open a pull request. I''ll review it first thing tomorrow.', '작은 버그 수정부터 해서 풀 리퀘스트를 올려요. 내일 아침에 제일 먼저 리뷰할게요.', '["Start with the checkout rebuild. It''s the biggest project we have right now.","Start with a small bug fix and open a pull request. I''ll review it sometime late next week.","Just read the code for a few weeks. Don''t open any pull requests yet."]', '["결제 개편부터 해요. 지금 우리 프로젝트 중에 제일 큰 거예요.","작은 버그 수정부터 해서 풀 리퀘스트를 올려요. 다음 주 후반쯤 리뷰할게요.","몇 주 동안은 코드만 읽어요. 풀 리퀘스트는 아직 올리지 말고요."]', '["The whole rebuild? On my first day?","Next week? Okay... I''ll just wait, then.","A few weeks? I was hoping to ship something soon."]', '["개편 전체를요? 첫날에요?","다음 주요? 네... 그럼 기다릴게요.","몇 주나요? 빨리 뭔가 올려 보고 싶었는데요."]', '["Give him a small first task and promise a review.","Key words: small bug fix, pull request, review"]', '["작은 첫 과제를 주고 리뷰를 약속하세요.","핵심 단어: small bug fix, pull request, review"]', 'jun', 'Sounds good. I''ll have it up by tonight.', '좋아요. 오늘 밤까지 올릴게요.'),
  ('dk_d10_handoff', 1, 'jun', 'Wednesday afternoon. Jun flies to Ridgeport tomorrow morning. He stops by your desk with his laptop and a long list.', '수요일 오후입니다. 준은 내일 아침 리지포트로 떠납니다. 그가 노트북과 긴 목록을 들고 당신 자리에 들릅니다.', 'Could you cover for me on the inventory API while I''m away?', '저 없는 동안 재고 API 좀 맡아 주실 수 있어요?', 'Agree to cover for him, and get a picture of where the work is right now.', '대신 맡아 주겠다고 하고, 지금 일이 어디까지 와 있는지 파악하세요.', '[{"all":["where things stand"]},{"all":["where do things stand"]},{"all":["things stand"]}]', 'Of course. Where do things stand right now?', '물론이죠. 지금 상황이 어디까지 왔어요?', '["Sure, but I won''t touch any bugs while you''re gone.","Of course. Have a great time in Ridgeport next week.","Of course. What time is your flight tomorrow?"]', '["그래요, 근데 없는 동안 버그는 안 건드릴 거예요.","물론이죠. 다음 주에 리지포트 잘 다녀와요.","물론이죠. 내일 비행기 몇 시예요?"]', '["Oh. Well, there is one bug...","Tomorrow, actually. That''s why I''m here.","Early, seven thirty. But about the API..."]', '["아. 그게, 버그가 하나 있는데...","사실 내일이에요. 그래서 온 거예요.","일찍이요, 일곱 시 반. 그런데 API 말인데요..."]', '["\\"Where do things stand?\\" asks for the current state of the work.","Key words: where do things stand"]', '["\\"Where do things stand?\\"는 일의 현재 상태를 묻는 말입니다.","핵심 단어: where do things stand"]', 'jun', 'The code is merged, but there''s one open bug. Some store IDs come back empty.', '코드는 머지됐는데, 버그가 하나 남아 있어요. 일부 매장 ID가 빈 값으로 와요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_handoff', 2, 'jun', 'Jun turns his laptop toward you. The ticket is open.', '준이 노트북을 당신 쪽으로 돌립니다. 티켓이 열려 있습니다.', 'I wrote down everything I know about the bug.', '버그에 대해 아는 건 다 적어 놨어요.', 'Make sure you both have the same picture: find out what''s finished and what still needs work.', '둘이 똑같이 알고 있는지 확인하세요. 무엇이 끝났고 무엇이 아직 남았는지 알아보세요.', '[{"all":["what is left"]},{"all":["same page"]},{"all":["left to do"]}]', 'Just so we''re on the same page: what''s done, and what''s left?', '서로 같은 내용을 알고 있게 확인하자면요. 끝난 건 뭐고, 남은 건 뭐예요?', '["Great. So you''ve already fixed the store ID bug, right?","Why is there still an open bug? You should''ve fixed it before you go.","Thanks. Can you also write up notes from the Ridgeport meeting?"]', '["좋아요. 그럼 매장 ID 버그는 이미 다 고쳐 놓은 거죠?","왜 아직 버그가 열려 있어요? 가기 전에 고쳐 놨어야죠.","고마워요. 리지포트 회의 내용도 정리해 줄 수 있어요?"]', '["No, it''s still open. That''s the whole problem.","I tried. It''s just... tricky. Sorry.","Sure, after the trip. But the bug first?"]', '["아니요, 아직 열려 있어요. 그게 문제예요.","해 봤어요. 그냥... 까다로워요. 죄송해요.","네, 출장 다녀와서요. 그런데 버그부터 볼까요?"]', '["Split the work into finished and unfinished.","Key words: on the same page, what''s done, what''s left"]', '["일을 끝난 것과 남은 것으로 나누어 물어보세요.","핵심 단어: on the same page, what''s done, what''s left"]', 'jun', 'Done: I can reproduce it. Left: finding out why. It only happens with some of the stores.', '끝난 것은 버그를 재현할 수 있다는 거예요. 남은 것은 원인 찾기예요. 일부 매장에서만 일어나요.'),
  ('dk_d10_handoff', 3, 'jun', 'You skim the ticket. It is detailed, but something is missing.', '티켓을 훑어봅니다. 자세하지만 빠진 게 있습니다.', 'It''s all in the ticket. Well, most of it.', '다 티켓에 있어요. 음, 대부분은요.', 'He said "most of it." Find out where the documentation is, and what he hasn''t written down.', '그는 "대부분"이라고 했습니다. 문서가 어디 있는지, 그리고 그가 적지 않은 게 뭔지 알아내세요.', '[{"any":["docs","documentation","documented"]},{"all":["in your head"]},{"all":["written down"]}]', 'Where do the docs live? And is there anything that''s only in your head?', '문서는 어디 있어요? 그리고 준 머릿속에만 있는 건 없어요?', '["Most of it is good enough. I''ll figure out the rest on my own.","Most of it? Jun, a handoff needs everything. Go back and finish writing it.","Okay. Could you print the ticket out for me before you go?"]', '["대부분이면 충분해요. 나머지는 제가 알아서 할게요.","대부분이요? 준, 인수인계는 전부여야죠. 돌아가서 마저 다 써요.","알겠어요. 가기 전에 티켓 좀 출력해 줄 수 있어요?"]', '["Are you sure? Some of it isn''t written anywhere.","Oh. Sorry. I''ll... add more tonight.","Sure. But some of it isn''t in the ticket."]', '["정말요? 어디에도 안 적힌 것도 있는데요.","아. 죄송해요. 오늘 밤에... 더 적을게요.","네. 그런데 티켓에 없는 것도 좀 있어요."]', '["The riskiest knowledge is the kind nobody wrote down.","Key words: where do the docs live, only in your head"]', '["가장 위험한 지식은 아무도 적어 두지 않은 것입니다.","핵심 단어: where do the docs live, only in your head"]', 'jun', 'Good question. The test data is on my laptop. I''ll upload it to the shared drive before I go.', '좋은 질문이에요. 테스트 데이터가 제 노트북에 있어요. 가기 전에 공유 드라이브에 올릴게요.'),
  ('dk_d10_handoff', 4, 'jun', 'He adds "upload test data" to his list.', '그가 목록에 "테스트 데이터 올리기"를 추가합니다.', 'Summit Retail''s IT team might write to you, too.', '서밋 리테일 IT 팀이 데릭한테 메일을 보낼 수도 있어요.', 'Find out who you should talk to on the client''s side if there''s a problem.', '문제가 생기면 고객사 쪽에서 누구와 이야기해야 하는지 알아내세요.', '[{"all":["point of contact"]},{"any":["contact"]},{"all":["reach out to"]}]', 'Who''s my point of contact at Summit Retail if something comes up?', '무슨 일이 생기면 서밋 리테일 쪽 담당자는 누구예요?', '["Then I''ll just forward everything to you in Ridgeport.","Should I just call Greg directly if something comes up?","I''d rather not deal with the client. Can Priya handle them for me?"]', '["그럼 오는 건 다 리지포트에 있는 준한테 넘길게요.","무슨 일 생기면 그냥 그렉한테 바로 전화하면 돼요?","고객 상대는 안 하고 싶어요. 프리야가 대신 맡아 주면 안 돼요?"]', '["I''ll be in meetings all day. That won''t really work.","Greg? He''s not really the technical one.","Priya can help, but they''ll want someone technical."]', '["저 하루 종일 회의예요. 그건 좀 어려워요.","그렉이요? 그분은 기술 쪽 사람이 아니에요.","프리야도 도와줄 순 있는데, 그쪽은 기술 담당을 원할 거예요."]', '["Ask for one name on the client''s side.","Key words: point of contact, if something comes up"]', '["고객사 쪽 사람 한 명의 이름을 물어보세요.","핵심 단어: point of contact, if something comes up"]', 'jun', 'Greg''s IT lead. Her name is Dana. Her email is in the ticket, and Priya knows her, too.', '그렉 팀의 IT 책임자예요. 이름은 데이나고요. 메일 주소는 티켓에 있고, 프리야도 그분을 알아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_handoff', 5, 'jun', 'Jun checks his itinerary.', '준이 출장 일정을 확인합니다.', 'I''ll be reachable on chat if anything comes up.', '무슨 일 있으면 채팅으로 연락돼요.', 'Promise not to bother him on the trip unless it''s an emergency, ask how to reach him, and let the rest wait until he''s back on Monday.', '급한 일이 아니면 출장 중에 방해하지 않겠다고 약속하고, 연락 방법을 묻고, 나머지는 그가 돌아오는 월요일까지 미루세요.', '[{"all":["best way to reach"]},{"any":["urgent"]},{"all":["can wait"]}]', 'I''ll only call if it''s urgent. What''s the best way to reach you? Anything else can wait until Monday.', '급할 때만 전화할게요. 제일 연락하기 좋은 방법이 뭐예요? 다른 건 월요일까지 기다려도 돼요.', '["Great, I''ll message you a few times a day with updates, just to keep you in the loop while you''re away.","I''ll only call if it''s urgent. Anything else can wait until you''re back on Wednesday.","Don''t worry, I won''t contact you at all, no matter what happens. Just enjoy the trip."]', '["좋아요, 없는 동안에도 상황을 알 수 있게 하루에 몇 번씩 진행 상황을 메시지로 보낼게요.","급할 때만 전화할게요. 다른 건 수요일에 돌아오면 그때 해도 돼요.","걱정 마요, 무슨 일이 있어도 절대 연락 안 할게요. 출장 즐겨요."]', '["A few times a day? I''ll be with the client most of the time.","Wednesday? I''m back on Monday.","Not even if something breaks? Please do call me then."]', '["하루에 몇 번이요? 저 거의 고객이랑 같이 있을 텐데요.","수요일이요? 저 월요일에 돌아와요.","뭐가 망가져도요? 그럴 땐 꼭 전화 주세요."]', '["Promise to respect his time on the trip.","Key words: urgent, best way to reach you, can wait"]', '["출장 중인 그의 시간을 존중하겠다고 약속하세요.","핵심 단어: urgent, best way to reach you, can wait"]', 'jun', 'Chat is best. If it''s urgent, call my cell. I''ll be in meetings with Greg from two o''clock.', '채팅이 제일 좋아요. 급하면 휴대전화로 전화 주세요. 두 시부터는 그렉과 회의예요.'),
  ('dk_d10_handoff', 6, 'jun', 'He hesitates before he goes.', '그가 가려다 말고 머뭇거립니다.', 'One more thing. The alert you gave me is only half done. There''s a draft pull request. Do you want to finish it?', '하나 더요. 주신 경보 작업이 반밖에 안 됐어요. 초안 풀 리퀘스트가 있는데요. 데릭이 마무리하실래요?', 'Don''t take the alert back. Make it clear it stays his, and send him off on his trip.', '경보 일을 도로 가져가지 마세요. 그 일은 계속 그의 것이라는 걸 분명히 하고, 출장을 잘 다녀오라고 보내 주세요.', '[{"all":["leave it for you"]},{"all":["safe travels"]},{"all":["all yours"]},{"all":["safe trip"]}]', 'No, it''s all yours. I''ll leave it for you. Safe travels, and don''t let Greg push you around.', '아니요, 그건 전부 준 거예요. 그대로 둘게요. 잘 다녀와요. 그렉한테 휘둘리지 말고요.', '["Sure, I''ll finish it up for you while you''re gone. It''s really no trouble at all. Safe travels, Jun.","No, it''s yours. Just make sure it''s done by the time you''re back on Monday.","No, let''s hand it to Sam. He owns the expiry alert now, right? Safe travels."]', '["그래요, 없는 동안 제가 대신 마무리할게요. 정말 어려운 일도 아니에요. 잘 다녀와요, 준.","아니요, 준 거예요. 대신 월요일에 돌아올 때까지는 꼭 끝내 놔요.","아니요, 샘한테 넘기죠. 이제 만료 경보는 샘 담당이잖아요? 잘 다녀와요."]', '["Oh. Okay. I kind of wanted to finish it myself.","By Monday? I thought you said there was no rush.","Sam? I thought it came from you to me."]', '["아. 네. 사실 제가 끝내고 싶었는데요.","월요일까지요? 급하지 않다고 하신 줄 알았어요.","샘이요? 데릭이 저한테 주신 거잖아요."]', '["Do not take the task back. It can wait for him.","Key words: all yours, leave it for you, safe travels"]', '["일을 도로 가져오지 마세요. 그가 돌아올 때까지 기다려도 됩니다.","핵심 단어: all yours, leave it for you, safe travels"]', 'jun', 'Ha! I won''t. Thanks, Derek. See you Monday!', '하하! 안 그럴게요. 고마워요, 데릭. 월요일에 봬요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_stretch', 1, 'maya', 'Wednesday, cloudy and chilly. You asked Maya for fifteen minutes. The one-page plan she asked for last week is in your hand.', '수요일, 흐리고 쌀쌀합니다. 마야에게 15분을 내 달라고 했습니다. 지난주에 그녀가 말한 한 장짜리 계획이 손에 들려 있습니다.', 'Come on in, Derek. You wanted to follow up on something?', '들어와요, 데릭. 뭐 이어서 얘기할 게 있다고요?', 'Tell her why you''re here: you''ve finished the one-page plan from your last 1:1.', '찾아온 이유를 말하세요. 지난 1:1에서 말한 한 장짜리 계획을 다 만들었다고요.', '[{"all":["circle back"]},{"all":["one page plan"]},{"all":["put together"]}]', 'I wanted to circle back to our 1:1. I put together the one-page plan you asked for.', '지난 1:1 얘기를 이어서 하고 싶었어요. 말씀하신 한 장짜리 계획을 만들어 왔어요.', '["I wanted to follow up on last month''s 1:1. Here''s the five-page plan you asked for.","Nothing big. Just a plan I threw together. You can skim it whenever you like.","Do you have a minute to talk about the Summit Retail timeline with Priya?"]', '["지난달 1:1 얘기를 이어서 하고 싶었어요. 말씀하신 다섯 장짜리 계획이에요.","별건 아니에요. 그냥 대충 만든 계획이에요. 시간 날 때 훑어보세요.","혹시 프리야랑 같이 서밋 리테일 일정 얘기할 시간 좀 있으세요?"]', '["Five pages? I asked for one, Derek.","Threw together? Let''s see what you''ve got.","We can, but I thought this was about something else."]', '["다섯 장이요? 한 장이라고 했잖아요, 데릭.","대충 만들었다고요? 어디 한번 봐요.","그래도 되는데, 다른 얘기인 줄 알았어요."]', '["\\"Circle back to\\" = return to a topic you discussed before.","Key words: circle back, one-page plan"]', '["circle back to는 전에 이야기한 주제로 돌아간다는 뜻입니다.","핵심 단어: circle back, one-page plan"]', 'maya', 'Already? I said next month. I''m impressed.', '벌써요? 다음 달이라고 했는데. 놀랍네요.'),
  ('dk_d10_stretch', 2, 'maya', 'She reads the page carefully, then looks up.', '그녀가 종이를 꼼꼼히 읽고 고개를 듭니다.', 'This covers the gift card project. But I also asked you to delegate. How''s that going?', '기프트 카드 프로젝트는 다 들어 있네요. 그런데 일을 맡기라고도 했잖아요. 그건 어떻게 돼 가요?', 'Show her you listened: tell her which task you gave to Jun rather than doing it yourself.', '그녀의 말을 새겨들었다는 걸 보여 주세요. 직접 하지 않고 준에게 맡긴 일이 무엇인지 말하세요.', '[{"all":["to heart"]},{"all":["handed"],"any":["jun","alert"]},{"all":["instead of doing it myself"]}]', 'I took your feedback to heart. I handed the certificate alert to Jun instead of doing it myself.', '주신 피드백을 마음에 새겼어요. 인증서 경보는 제가 하지 않고 준에게 맡겼어요.', '["I really took your feedback to heart. I handed the expiry alert to Sam instead of doing it myself.","I''m working on it. It''s hard to delegate when Jun is still so new, you know?","I gave the alert to Jun, but I''m keeping an eye on every commit, just in case."]', '["주신 피드백을 정말 마음에 새겼어요. 만료 경보는 제가 하지 않고 샘에게 맡겼어요.","노력 중이에요. 준이 아직 너무 신입이라 맡기기가 어렵더라고요, 아시죠?","경보는 준에게 줬는데, 혹시 몰라서 커밋을 하나하나 다 지켜보고 있어요."]', '["Sam? I thought Sam had the calendar.","He''s new, but he''s not that new. Give him a chance.","Every commit? That''s not really letting go, is it?"]', '["샘이요? 샘은 달력을 맡은 줄 알았는데요.","신입이긴 해도 그 정도는 아니에요. 기회를 줘 봐요.","커밋 하나하나요? 그건 손을 놓은 게 아니잖아요?"]', '["Show that you acted on the feedback, with a real example.","Key words: took your feedback to heart, handed … to Jun"]', '["실제 사례를 들어 피드백대로 행동했다는 것을 보여 주세요.","핵심 단어: took your feedback to heart, handed … to Jun"]', 'maya', 'Good. That''s exactly what I wanted to see.', '좋아요. 제가 보고 싶었던 게 바로 그거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_stretch', 3, 'maya', 'Maya smiles a little.', '마야가 살짝 웃습니다.', 'Be honest. Was it hard to let go?', '솔직히 말해 봐요. 손 떼기 힘들었죠?', 'Be honest: it wasn''t easy, and you were tempted to take over.', '솔직하게 말하세요. 쉽지 않았고, 직접 나서고 싶은 마음이 들었다고요.', '[{"all":["old habits die hard"]},{"all":["resist the urge"]},{"all":["jump in"]}]', 'Honestly, yes. Old habits die hard. I had to resist the urge to jump in.', '솔직히, 네. 오랜 습관은 쉽게 안 고쳐지더라고요. 끼어들고 싶은 걸 참아야 했어요.', '["Not at all, honestly. It was easy, and I don''t miss doing it one bit.","Honestly, yes. In the end, I quietly finished half of it myself last night.","Honestly, yes. Jun asks a lot of questions, and it slows me down."]', '["솔직히 전혀요. 쉬웠고, 제가 직접 하던 게 하나도 아쉽지 않아요.","솔직히, 네. 결국 어젯밤에 절반은 제가 몰래 끝내 버렸어요.","솔직히, 네. 준이 질문을 너무 많이 해서 제 일이 느려져요."]', '["Not even a little? I don''t quite buy that.","Wait, you finished half of it? Then he doesn''t own it.","Questions are good. That''s how he learns."]', '["조금도요? 그 말은 잘 안 믿기는데요.","잠깐, 절반을 끝냈다고요? 그럼 그건 준의 일이 아니잖아요.","질문은 좋은 거예요. 그렇게 배우는 거죠."]', '["Honesty about a struggle builds trust with your manager.","Key words: old habits die hard, resist the urge"]', '["어려웠던 점을 솔직히 말하면 매니저와 신뢰가 쌓입니다.","핵심 단어: old habits die hard, resist the urge"]', 'maya', 'That urge never goes away completely. You just get better at noticing it.', '그 마음은 완전히 없어지지 않아요. 알아차리는 데 능숙해질 뿐이죠.'),
  ('dk_d10_stretch', 4, 'maya', 'She puts the page down on her desk.', '그녀가 종이를 책상에 내려놓습니다.', 'So what''s the ask?', '그래서, 원하는 게 뭐예요?', 'Ask for a bigger role: technical lead on the Summit Retail dashboard, while Jun does most of the hands-on work.', '더 큰 역할을 요청하세요. 서밋 리테일 대시보드의 기술 책임을 맡고, 실제 구현은 대부분 준이 하는 거예요.', '[{"all":["step up"]},{"all":["technical side"]},{"any":["dashboard"]}]', 'I''d like to step up and own the technical side of the Summit Retail dashboard, with Jun doing most of the building.', '한 단계 더 나서서 서밋 리테일 대시보드의 기술 쪽을 맡고 싶어요. 구현은 대부분 준이 하고요.', '["I''d like to step up and own the technical side of the gift card project, with Jun doing most of the testing.","I''d like a promotion and a raise. I''ve been here long enough, and honestly, I think I''ve more than earned it by now.","I''d like to take over the Summit Retail dashboard and build it myself, so Jun can focus on smaller tasks."]', '["한 단계 더 나서서 기프트 카드 프로젝트의 기술 쪽을 맡고 싶어요. 테스트는 대부분 준이 하고요.","승진이랑 연봉 인상을 원해요. 여기 있을 만큼 있었고, 솔직히 이제 그럴 자격은 충분하다고 생각해요.","서밋 리테일 대시보드를 넘겨받아서 제가 직접 만들고 싶어요. 준은 작은 일에 집중하고요."]', '["The gift card project is already yours. Think bigger.","Whoa. Let''s talk about the work first, then the title.","Build it yourself? That''s the opposite of what we discussed."]', '["기프트 카드 프로젝트는 이미 데릭 거잖아요. 더 크게 생각해 봐요.","워워. 직함보다 일 얘기부터 하죠.","직접 만든다고요? 우리가 얘기한 거랑 정반대잖아요."]', '["Be specific about the role you are asking for.","Key words: step up, own the technical side"]', '["요청하는 역할을 구체적으로 말하세요.","핵심 단어: step up, own the technical side"]', 'maya', 'That''s a bigger stage than gift cards. I think you''re ready. Let''s make it official for phase one.', '기프트 카드보다 큰 무대네요. 준비가 된 것 같아요. 1단계부터 공식적으로 그렇게 하죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d10_stretch', 5, 'maya', 'Maya opens her calendar.', '마야가 달력을 엽니다.', 'How will we know it''s working?', '잘되고 있는지 어떻게 알 수 있을까요?', 'Propose short check-ins every other week and a bigger review when the quarter ends.', '격주로 짧게 점검하고, 분기가 끝날 때 크게 한번 돌아보자고 제안하세요.', '[{"all":["every two weeks"]},{"all":["take stock"]},{"all":["end of the quarter"]},{"any":["biweekly"]}]', 'How about we check in every two weeks and take stock at the end of the quarter?', '2주마다 점검하고, 분기 말에 전체를 돌아보는 건 어때요?', '["How about we check in every two months, and then take stock at the end of the year?","We''ll know when Summit Retail signs the contract. That''s all that matters.","Trust me, you''ll just know. I don''t think we need anything formal."]', '["두 달마다 점검하고, 그다음에 연말에 전체를 돌아보는 건 어때요?","서밋 리테일이 계약하면 알게 되겠죠. 중요한 건 그것뿐이에요.","믿어 보세요, 그냥 알게 될 거예요. 공식적인 건 필요 없을 것 같아요."]', '["Every two months? That''s a long time to wait for feedback.","That matters, but I want to see how you''re growing, too.","I''d still like something on the calendar, Derek."]', '["두 달마다요? 피드백을 기다리기엔 너무 길어요.","그것도 중요하지만, 데릭이 어떻게 성장하는지도 보고 싶어요.","그래도 달력에 뭔가 잡아 두고 싶어요, 데릭."]', '["Offer a rhythm for checking and a date for judging the result.","Key words: every two weeks, take stock, end of the quarter"]', '["점검할 주기와 결과를 평가할 날짜를 제안하세요.","핵심 단어: every two weeks, take stock, end of the quarter"]', 'maya', 'Every two weeks, and a review at the end of the quarter. I''ll put it in writing. Let me know if you have any questions.', '2주마다, 그리고 분기 말에 평가. 문서로 남겨 둘게요. 궁금한 게 있으면 말해 줘요.'),
  ('dk_d11_call', 1, 'jun', 'Thursday, a clear day. Jun is in Ridgeport. Priya needs to know by the end of the day which stores have the empty-ID bug, and the list is not in the ticket. You tried chat first. No answer, so you call his cell from your desk.', '목요일, 맑은 날입니다. 준은 리지포트에 있습니다. 프리야는 어느 매장에서 빈 ID 버그가 나는지 오늘 안에 알아야 하는데, 그 목록이 티켓에 없습니다. 먼저 채팅을 보냈지만 답이 없어서, 자리에서 그의 휴대전화로 전화를 겁니다.', 'Hello, this is Jun.', '여보세요, 준입니다.', 'Say who''s calling, apologize for interrupting his trip, and check that he can talk right now.', '누군지 밝히고, 출장 중에 방해해서 미안하다고 하고, 지금 통화할 수 있는지 확인하세요.', '[{"all":["good time"]},{"all":["bad time"]},{"all":["sorry to bother"]},{"all":["have a minute"]}]', 'Hey, Jun, it''s Derek. Sorry to bother you on the road. Is this a good time?', '준, 저 데릭이에요. 출장 중에 방해해서 미안해요. 지금 통화 괜찮아요?', '["Hey, it''s Derek. Why aren''t you answering your chat? I need something.","Hey, Jun, it''s Derek. Quick one: where''s the store list? It''s not in the ticket.","Hey, Jun, it''s Derek. How was the meeting with Greg? Did it go well?"]', '["저 데릭이에요. 채팅은 왜 답이 없어요? 필요한 게 있다고요.","준, 저 데릭이에요. 간단한 건데, 매장 목록 어디 있어요? 티켓에 없던데요.","준, 저 데릭이에요. 그렉이랑 회의는 어땠어요? 잘됐어요?"]', '["Sorry! I was checking in. Is something wrong?","Uh, hi. Hang on, I just got to the hotel.","Not yet. It''s at two. Is everything okay?"]', '["죄송해요! 체크인하고 있었어요. 무슨 일 있어요?","어, 안녕하세요. 잠깐만요, 방금 호텔에 왔어요.","아직이요. 두 시예요. 별일 없죠?"]', '["On the phone, say who you are and ask before you start.","Key words: sorry to bother you, is this a good time"]', '["전화에서는 누구인지 밝히고, 용건을 꺼내기 전에 먼저 물어보세요.","핵심 단어: sorry to bother you, is this a good time"]', 'jun', 'Hi, Derek! Yes, I just checked in at the hotel. I have a few minutes before I head over to Summit Retail.', '안녕하세요, 데릭! 네, 방금 호텔에 체크인했어요. 서밋 리테일로 가기 전에 몇 분 시간이 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_call', 2, 'jun', 'His voice sounds tense.', '그의 목소리가 긴장한 듯합니다.', 'Is everything okay? Did something break?', '괜찮은 거죠? 뭐가 고장 났어요?', 'Calm him down, and promise this will only take a minute.', '그를 진정시키고, 금방 끝날 거라고 약속하세요.', '[{"all":["on fire"]},{"all":["keep it short"]},{"all":["keep this short"]},{"all":["quick question"]}]', 'Nothing''s on fire. I''ll keep it short. I just have one quick question.', '급한 불 난 거 아니에요. 짧게 할게요. 간단한 질문 하나만 있어요.', '["Well, kind of. The inventory API went down this morning.","Not yet, but it might if I can''t find what I need from you.","Everything''s fine here. So how''s Ridgeport? Is the hotel nice? Good flight?"]', '["음, 좀 그래요. 오늘 아침에 재고 API가 다운됐어요.","아직은요. 그런데 필요한 걸 못 찾으면 그렇게 될지도 몰라요.","여긴 다 괜찮아요. 그래서 리지포트는 어때요? 호텔은 좋아요? 비행기는 괜찮았어요?"]', '["What? Down? Oh no. What happened?","Okay, now I''m nervous. What do you need?","It''s nice. But I only have a few minutes."]', '["네? 다운이요? 이런. 무슨 일이에요?","아, 이제 긴장되네요. 뭐가 필요하세요?","좋아요. 근데 저 몇 분밖에 없어요."]', '["Calm him first, then promise not to take much of his time.","Key words: nothing''s on fire, keep it short"]', '["먼저 안심시키고, 시간을 많이 뺏지 않겠다고 약속하세요.","핵심 단어: nothing''s on fire, keep it short"]', 'jun', 'Phew. You scared me for a second.', '휴. 잠깐 놀랐어요.'),
  ('dk_d11_call', 3, 'jun', 'You hear an elevator bell on his end of the line.', '수화기 너머로 엘리베이터 벨 소리가 들립니다.', 'Okay, what do you need?', '네, 뭐가 필요하세요?', 'Ask for the list of stores with the bug, which wasn''t in the ticket.', '버그가 나는 매장 목록을 물어보세요. 티켓에는 없었어요.', '[{"all":["affected stores"]},{"any":["list"]}]', 'Where''s the list of affected stores? I couldn''t find it in the ticket.', '영향받는 매장 목록 어디 있어요? 티켓에서는 못 찾았어요.', '["Where''s the test data? I couldn''t find it on the shared drive.","Can you walk me through the whole bug, from the beginning?","Why didn''t you put the store list in the ticket? I''ve been looking for an hour."]', '["테스트 데이터 어디 있어요? 공유 드라이브에서 못 찾았어요.","버그 전체를 처음부터 하나하나 설명해 줄 수 있어요?","매장 목록은 왜 티켓에 안 넣었어요? 한 시간째 찾고 있어요."]', '["I uploaded it last night. Is that what you need?","The whole thing? I don''t really have time right now.","Sorry! I thought I had. Let me think."]', '["어젯밤에 올렸는데요. 그게 필요하신 거예요?","전부요? 지금은 시간이 별로 없어요.","죄송해요! 넣은 줄 알았어요. 잠깐 생각해 볼게요."]', '["One clear question, with the reason you are asking.","Key words: the list of affected stores"]', '["묻는 이유를 곁들여 분명한 질문 하나만 하세요.","핵심 단어: the list of affected stores"]', 'jun', 'Oh no, I forgot to attach it. It''s a spreadsheet on the shared drive, in the folder called "inventory-bugs". Seven stores.', '아, 첨부하는 걸 깜빡했어요. 공유 드라이브의 "inventory-bugs" 폴더에 있는 스프레드시트예요. 매장 일곱 곳이에요.'),
  ('dk_d11_call', 4, 'jun', 'You find the spreadsheet while he is still talking.', '그가 말하는 동안 스프레드시트를 찾았습니다.', 'I''m so sorry. I should have put it in the ticket. Do you want me to look at the bug tonight?', '정말 죄송해요. 티켓에 넣었어야 했는데. 오늘 밤에 제가 버그 볼까요?', 'Let him off the hook: he should put his energy into the client while you handle the bug.', '그의 부담을 덜어 주세요. 그는 고객에게 힘을 쏟고, 버그는 당신이 처리하면 돼요.', '[{"all":["take it from here"]},{"all":["all i needed"]},{"all":["focus on"]}]', 'No worries, that''s all I needed. You focus on the client. I''ll take it from here.', '괜찮아요, 필요한 건 그게 다였어요. 준은 고객한테 집중해요. 여기서부턴 제가 할게요.', '["That would help, actually. Maybe after your dinner with the client?","It''s fine. Just remember for next time: if it''s not in the ticket, it doesn''t exist.","No worries. I''ll have Priya finish the fix while you''re in meetings."]', '["사실 그러면 도움이 되긴 해요. 고객이랑 저녁 먹고 나서 볼래요?","괜찮아요. 대신 다음번엔 꼭 기억해요. 티켓에 없으면 없는 거예요.","괜찮아요. 준이 회의하는 동안 프리야한테 수정을 마무리하라고 할게요."]', '["Oh. Sure, I can try after dinner...","Right. Sorry again. I''ll do better.","Priya? Isn''t she a product manager?"]', '["아. 네, 저녁 먹고 해 볼게요...","네. 다시 한번 죄송해요. 잘할게요.","프리야요? 프리야는 PM이잖아요?"]', '["Do not let him work at night on a business trip.","Key words: that''s all I needed, take it from here"]', '["출장 중에 밤까지 일하게 두지 마세요.","핵심 단어: that''s all I needed, take it from here"]', 'jun', 'Thank you. That''s a weight off my mind.', '고마워요. 마음이 한결 놓이네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_call', 5, 'jun', 'It is almost time for him to go.', '그가 나가야 할 시간이 다 됐습니다.', 'I''m meeting Greg in person at two. Any advice?', '두 시에 그렉을 직접 만나요. 조언 있으세요?', 'Give him a confidence boost, and end the call so he can get going.', '그에게 자신감을 북돋아 주고, 그가 출발할 수 있게 통화를 마무리하세요.', '[{"all":["got this"]},{"all":["let you go"]},{"all":["be yourself"]}]', 'You''ve got this. Just be yourself. Anyway, I''ll let you go. Good luck!', '준은 해낼 거예요. 평소대로만 해요. 아무튼 이만 끊을게요. 행운을 빌어요!', '["Don''t mess it up. The whole quarter depends on this deal.","Make sure you cover the pilot, the timeline, the API, and the data.","You''ve got this. Say hi to Dana for me. She''s the one who runs the account."]', '["제발 망치지만 마요. 이번 분기가 다 이 계약에 달렸어요.","시범 운영, 일정, API, 데이터까지 빠짐없이 꼭 다 짚어요.","준은 해낼 거예요. 데이나한테 안부 전해 줘요. 그 계정 책임자잖아요."]', '["Gee, thanks. No pressure, then.","Okay... that''s a lot. I''ll try to remember.","Dana''s their IT lead. Greg runs the account."]', '["와, 고마워요. 부담 하나도 안 되네요.","네... 많네요. 기억해 볼게요.","데이나는 IT 책임자예요. 계정은 그렉이 맡고요."]', '["\\"I''ll let you go\\" is the polite way to end a call.","Key words: you''ve got this, I''ll let you go"]', '["\\"I''ll let you go\\"는 통화를 정중하게 끝내는 말입니다.","핵심 단어: you''ve got this, I''ll let you go"]', 'jun', 'Thanks, Derek. I''ll message you after the meeting. Bye!', '고마워요, 데릭. 회의 끝나고 메시지 보낼게요. 끊을게요!'),
  ('dk_d11_unblock', 1, 'priya', 'Priya is typing fast. An email from Dana, the IT lead at Summit Retail, is open on her screen.', '프리야가 빠르게 타자를 치고 있습니다. 화면에는 서밋 리테일 IT 책임자 데이나의 메일이 열려 있습니다.', 'Derek, thank goodness. Dana wants to know which stores have the empty-ID bug, and I''m stuck. Jun''s not answering his chat.', '데릭, 살았다. 데이나가 어느 매장에서 빈 ID 버그가 나는지 알고 싶어 하는데, 저 막혔어요. 준은 채팅에 답이 없고요.', 'Tell her you''ve already reached Jun, and give her the answer: seven stores, all new this year.', '이미 준과 연락이 닿았다고 하고, 답을 알려 주세요. 매장 일곱 곳이고, 모두 올해 새로 연 곳이에요.', '[{"all":["got off the phone"]},{"all":["seven stores"]},{"all":["7 stores"]},{"all":["opened this year"]}]', 'I just got off the phone with him. It''s seven stores, all of which opened this year.', '방금 준이랑 통화했어요. 매장 일곱 곳이고, 전부 올해 문을 연 곳이에요.', '["I just got off the phone with him. It''s eleven stores, all of which opened last year.","Relax. Jun''s busy with the client, and this can wait until he''s back on Monday.","I''ll call him right now. Give me ten minutes, and I''ll get you the full list."]', '["방금 준이랑 통화했어요. 매장 열한 곳이고, 전부 작년에 문을 연 곳이에요.","진정해요. 준은 고객 일로 바쁘니까, 이건 월요일에 돌아올 때까지 기다려도 돼요.","지금 바로 전화해 볼게요. 10분만 주면 전체 목록을 갖다줄게요."]', '["Eleven? That''s more than I expected. Are you sure?","Monday? Dana needs this today, Derek.","Haven''t you talked to him already? You look like you know something."]', '["열한 곳이요? 생각보다 많네요. 확실해요?","월요일이요? 데이나는 오늘 필요해요, 데릭.","벌써 통화한 거 아니에요? 뭔가 아는 얼굴인데요."]', '["Give the fact and where you got it.","Key words: got off the phone, seven stores"]', '["사실과 그 출처를 함께 말하세요.","핵심 단어: got off the phone, seven stores"]', 'priya', 'You called him? You''re a lifesaver.', '전화했어요? 덕분에 살았어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_unblock', 2, 'priya', 'You looked at the seven stores before you came over, and the pattern jumped out at you.', '오기 전에 그 일곱 매장을 살펴봤더니 공통점이 바로 눈에 들어왔습니다.', 'Dana also asks why it happens. Keep it simple, please. I have to explain it to Greg.', '데이나가 왜 그런지도 물어봐요. 간단하게 부탁해요. 그렉한테 설명해야 하거든요.', 'Explain the cause so Greg could follow it: newer stores have longer IDs, and the old system chops them short.', '그렉도 알아들을 수 있게 원인을 설명하세요. 새 매장들은 ID가 더 긴데, 옛 시스템이 그걸 짧게 잘라 버린다고요.', '[{"all":["plain english"]},{"all":["cuts it off"]},{"all":["longer id"]}]', 'In plain English: the new stores have a longer ID, and the old system cuts it off.', '쉽게 말하면, 새 매장들은 ID가 더 긴데 옛 시스템이 그걸 잘라 버리는 거예요.', '["The POS export truncates the store_id field to eight characters, so the join returns null.","In short: the new stores have a shorter ID, and the new dashboard rejects it.","Basically, their old system is junk, and Dana''s team should have caught this."]', '["POS export가 store_id 필드를 여덟 글자로 잘라서 join 결과가 null이 나와요.","간단히 말하면, 새 매장들은 ID가 더 짧은데 새 대시보드가 그걸 거부하는 거예요.","한마디로 그쪽 옛 시스템이 엉터리고, 데이나 팀이 진작 잡았어야 했어요."]', '["You lost me at \\"export.\\" Simpler, please.","Shorter? I thought the new ones were the long ones.","I can''t send that to Greg. Let''s keep it friendly."]', '["''export''에서부터 못 알아듣겠어요. 더 쉽게요.","더 짧다고요? 새 매장 ID가 긴 줄 알았는데요.","그걸 그렉한테 보낼 순 없어요. 좀 부드럽게 가죠."]', '["No jargon. Say it so a manager can repeat it.","Key words: in plain English, a longer ID, cuts it off"]', '["전문 용어 없이, 관리자가 그대로 옮길 수 있게 말하세요.","핵심 단어: in plain English, a longer ID, cuts it off"]', 'priya', 'A longer ID that gets cut off. Even I understand that.', '긴 ID가 잘린다. 그건 저도 이해되네요.'),
  ('dk_d11_unblock', 3, 'priya', 'She starts typing her reply to Dana, then stops.', '그녀가 데이나에게 답장을 쓰기 시작하다가 멈춥니다.', 'Is it safe to tell her it''ll be fixed by Monday?', '월요일까지 고쳐진다고 말해도 괜찮을까요?', 'Don''t let her commit to Monday. The fix is easy, but testing needs real data from those stores, so suggest a safer day: Wednesday.', '월요일로 약속하지 못하게 하세요. 수정은 쉽지만 테스트하려면 그 매장들의 실제 데이터가 필요하니, 더 안전한 수요일을 제안하세요.', '[{"any":["caveat"]},{"all":["would not promise"]},{"any":["overpromise"]},{"all":["to be safe"]}]', 'I wouldn''t promise Monday. The fix looks simple, but there''s one caveat: we need real data from those stores to test it. Let''s say Wednesday, to be safe.', '월요일은 약속 안 하는 게 좋겠어요. 수정은 간단해 보이는데, 단서가 하나 있어요. 그 매장들의 실제 데이터로 테스트해야 해요. 넉넉하게 수요일로 하죠.', '["Yes, go ahead and tell her Monday. The fix looks simple, and we can always test it after it goes out to the stores.","I wouldn''t promise Monday. The fix looks simple, but there''s one catch: we need real data from those stores to test it. Let''s say next month, just to be safe.","Hard to say right now. Just tell her we''re looking into it, and we''ll get back to her when we know a lot more about it."]', '["네, 그냥 월요일이라고 말해요. 수정은 간단해 보이고, 테스트는 매장에 내보낸 다음에 언제든 해 봐도 되니까요.","월요일은 약속 안 하는 게 좋겠어요. 수정은 간단해 보이는데, 걸리는 게 하나 있어요. 그 매장들의 실제 데이터로 테스트해야 해요. 넉넉하게 다음 달로 하죠.","지금은 뭐라 말하기 어려워요. 그냥 살펴보는 중이라고만 하고, 더 많이 알게 되면 그때 다시 연락하겠다고 해요."]', '["Test it after it''s live? That makes me nervous.","Next month? For a fix you just called simple?","She''ll want a date, Derek. Give me something."]', '["내보낸 다음에 테스트한다고요? 그건 불안한데요.","다음 달이요? 방금 간단하다고 한 수정인데요?","데이나는 날짜를 원할 거예요, 데릭. 뭐라도 줘요."]', '["Give a date you can keep, and say what it depends on.","Key words: I wouldn''t promise, one caveat, to be safe"]', '["지킬 수 있는 날짜를 말하고, 무엇에 달렸는지 밝히세요.","핵심 단어: I wouldn''t promise, one caveat, to be safe"]', 'priya', 'Under-promise and over-deliver. Wednesday it is.', '약속은 적게, 결과는 그 이상으로. 수요일로 하죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d11_unblock', 4, 'priya', 'Priya looks at the clock. She has another meeting in fifteen minutes.', '프리야가 시계를 봅니다. 15분 뒤에 다른 회의가 있습니다.', 'Can you write that up for me? Two or three sentences.', '그거 좀 정리해 줄 수 있어요? 두세 문장으로요.', 'Promise her a brief write-up within ten minutes, written so she can pass it straight to Dana.', '10분 안에 짧게 정리해 주겠다고 약속하세요. 그녀가 데이나에게 바로 넘길 수 있게요.', '[{"all":["as is"]},{"any":["summary"]},{"all":["feel free"]}]', 'I''ll send you a short summary in ten minutes. Feel free to forward it as is.', '10분 안에 짧게 정리해서 보낼게요. 그대로 전달하셔도 돼요.', '["I''ll send you a short summary in about an hour. Feel free to forward it as is.","Can''t you write it? I already explained it, and I''ve got my own work.","I''ll email Dana myself in ten minutes, so you don''t have to bother."]', '["한 시간쯤 뒤에 짧게 정리해서 보낼게요. 그대로 전달하셔도 돼요.","직접 쓰면 안 돼요? 설명은 다 했고, 저도 제 일이 있어요.","10분 안에 제가 데이나한테 직접 메일 보낼게요. 신경 안 쓰셔도 돼요."]', '["An hour? I''m in a meeting in fifteen minutes.","Wow. Okay. I just thought you''d say it better.","Please don''t. I''m the one talking to Dana."]', '["한 시간이요? 저 15분 뒤에 회의예요.","와. 알겠어요. 데릭이 더 잘 쓸 것 같아서 그랬죠.","그러지 마요. 데이나랑은 제가 얘기하고 있어요."]', '["Save her time: write it so she does not have to rewrite it.","Key words: a short summary, feel free, as is"]', '["그녀의 시간을 아껴 주세요. 고쳐 쓸 필요가 없게 써 주세요.","핵심 단어: a short summary, feel free, as is"]', 'priya', 'Perfect. And copy Jun, so he''s in the loop when he gets back.', '완벽해요. 준도 참조에 넣어 줘요. 돌아왔을 때 상황을 알 수 있게요.'),
  ('dk_d11_unblock', 5, 'priya', 'She picks up her laptop to go.', '그녀가 가려고 노트북을 집어 듭니다.', 'One last thing. If Dana wants to talk it through tomorrow, would you join?', '마지막으로 하나만요. 내일 데이나가 직접 얘기하자고 하면 같이 들어와 줄래요?', 'Agree to join, ask to be added to the email conversation, and say you''re open any time after ten.', '참여하겠다고 하고, 메일 대화에 넣어 달라고 하고, 열 시 이후엔 언제든 된다고 하세요.', '[{"all":["hop on"]},{"all":["loop me in"]},{"all":["jump on"]}]', 'Sure, I can hop on a call. Just loop me in on the email thread. I''m free any time after ten.', '그럼요, 통화 들어갈 수 있어요. 메일 스레드에만 넣어 줘요. 열 시 이후엔 언제든 괜찮아요.', '["Sure, I can hop on a call. Just loop me in on the email thread. I''m only free before ten, though.","Do I have to? Jun knows this better. Can''t it wait until he''s back on Monday?","Sure, but forward me every email Dana sends from now on, not just this one."]', '["그럼요, 통화 들어갈 수 있어요. 메일 스레드에만 넣어 줘요. 근데 저는 열 시 전에만 돼요.","꼭 들어가야 돼요? 준이 더 잘 알잖아요. 월요일에 준 돌아오면 하면 안 돼요?","그래요, 대신 이것만 말고 앞으로 데이나가 보내는 메일은 전부 저한테 넘겨줘요."]', '["Before ten? Let me see if she can do that early.","Derek, you''re the one who found the cause.","Every email? Let''s just start with this thread."]', '["열 시 전이요? 데이나가 그렇게 일찍 되는지 볼게요.","데릭, 원인을 찾은 건 데릭이잖아요.","전부요? 일단 이 스레드부터 하죠."]', '["Offer to join, and ask to be included in the emails.","Key words: hop on a call, loop me in"]', '["참여하겠다고 하고, 메일에 넣어 달라고 부탁하세요.","핵심 단어: hop on a call, loop me in"]', 'priya', 'Done. You really kept things moving today. I''ll make sure Maya knows.', '그렇게 할게요. 오늘 덕분에 일이 멈추지 않았어요. 마야도 꼭 알게 할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_panel', 1, 'linda', 'Friday morning, partly sunny. Linda has three resumes spread out on her desk.', '금요일 아침, 구름 사이로 해가 납니다. 린다의 책상에 이력서 세 장이 펼쳐져 있습니다.', 'Derek, thanks for stopping by. We''re hiring a backend developer, and I''d like you on the interview panel next week. Can I count on you?', '데릭, 들러 줘서 고마워요. 백엔드 개발자를 뽑는데, 다음 주 면접관으로 들어와 줬으면 해요. 부탁해도 될까요?', 'Accept, find out when the interviews are, and promise to keep that time free.', '수락하고, 면접이 언제인지 묻고, 그 시간을 비워 두겠다고 약속하세요.', '[{"all":["block off"]},{"all":["sit in"]},{"all":["which days"]}]', 'I''d be glad to sit in. Which days? I''ll block off my calendar.', '기꺼이 들어갈게요. 무슨 요일이에요? 달력에 시간 비워 둘게요.', '["I guess so, if nobody else can. How long will it take?","I''d be glad to sit in. Is it this Friday? I''ll block off my calendar.","Sure, put me down for all of them. I can do every interview."]', '["뭐, 다른 사람이 안 된다면요. 얼마나 걸려요?","기꺼이 들어갈게요. 이번 금요일이에요? 달력에 시간 비워 둘게요.","그럼요, 전부 넣어 주세요. 면접은 다 들어갈 수 있어요."]', '["Only if you want to. I''d rather have someone who''s interested.","This Friday? No, it''s next week.","All of them? Let''s start with these three."]', '["원할 때만요. 관심 있는 사람이 들어오는 게 나아요.","이번 금요일이요? 아니요, 다음 주예요.","전부요? 일단 이 세 명부터 하죠."]', '["Say yes, then ask for the dates so you can keep them free.","Key words: sit in, which days, block off"]', '["수락하고, 시간을 비워 둘 수 있게 날짜를 물어보세요.","핵심 단어: sit in, which days, block off"]', 'linda', 'Tuesday and Thursday afternoon. Three candidates, forty-five minutes each.', '화요일과 목요일 오후예요. 지원자 세 명, 한 명에 45분씩이에요.'),
  ('dk_d12_panel', 2, 'linda', 'She hands you a blank scorecard.', '그녀가 빈 평가표를 건넵니다.', 'You''ll run the technical part. What will you be looking for?', '기술 면접은 데릭이 맡아요. 뭘 보실 거예요?', 'Explain that you care about how candidates reason, not gotcha puzzles, and say how you''ll see it.', '함정 퍼즐이 아니라 지원자가 어떻게 생각하는지가 중요하다고 설명하고, 그걸 어떻게 볼지 말하세요.', '[{"all":["how they think"]},{"all":["talk me through"]},{"all":["trick questions"]}]', 'I care less about trick questions and more about how they think. I''ll have them talk me through a real problem.', '함정 문제보다는 어떻게 생각하는지를 봐요. 실제 문제 하나를 말로 풀어 보게 할 거예요.', '["I''ll give them a hard puzzle and a ten-minute timer. If they crack under pressure, they''re out. It''s as simple as that.","Mostly whether they''d fit in. You know, someone I''d want to grab a beer with after work.","I''ll mostly look at where they went to school and which big companies they''ve worked for."]', '["어려운 퍼즐 하나 주고 10분 타이머를 걸 거예요. 압박에 무너지면 탈락이에요. 간단하죠.","주로 잘 어울릴지 봐요. 그러니까, 퇴근하고 맥주 한잔하고 싶은 사람인지요.","주로 어느 학교를 나왔는지, 어떤 큰 회사에서 일했는지를 볼 거예요."]', '["Hmm. I''d rather see how they work than how they panic.","A beer? Careful. That''s how bias creeps in.","We have their resumes for that. I need to know how they code."]', '["음. 당황하는 모습보다 일하는 방식을 보고 싶은데요.","맥주요? 조심해요. 편견은 그렇게 끼어들어요.","그건 이력서에 다 있어요. 코딩을 어떻게 하는지 알고 싶어요."]', '["Say what matters to you, and how you will find it out.","Key words: how they think, talk me through"]', '["무엇을 중요하게 보는지, 그것을 어떻게 알아낼지 말하세요.","핵심 단어: how they think, talk me through"]', 'linda', 'Good. That''s what the scorecard is for. Same questions for everyone, so it''s fair.', '좋아요. 평가표가 그래서 있는 거예요. 공정하도록 모두에게 같은 질문을 하는 거죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_panel', 3, 'linda', 'Linda picks up her pen.', '린다가 펜을 듭니다.', 'And what''s a red flag for you?', '그럼 데릭한테 위험 신호는 뭐예요?', 'Name the warning sign you watch for: a candidate who hogs the credit or blames their former coworkers.', '당신이 경계하는 신호를 말하세요. 공을 독차지하거나 예전 동료들을 탓하는 지원자요.', '[{"all":["under the bus"]},{"all":["all the credit"]},{"any":["blames","blaming"]}]', 'Someone who takes all the credit, or throws their old team under the bus.', '공을 혼자 다 차지하거나, 예전 팀한테 책임을 떠넘기는 사람이요.', '["Someone who''s been out of work for a while. Gaps on a resume worry me.","Someone who says \\"I don''t know.\\" That means they''re not ready yet.","Someone who shows up even five minutes late, or wears jeans to the interview."]', '["한동안 일을 쉰 사람이요. 이력서에 공백이 있으면 걱정돼요.","\\"모르겠어요\\"라고 하는 사람이요. 아직 준비가 안 됐다는 뜻이니까요.","단 5분이라도 늦게 오거나, 면접에 청바지를 입고 오는 사람이요."]', '["Gaps happen for lots of reasons. Let''s not go there.","Hmm. I''d rather hear \\"I don''t know\\" than a made-up answer.","Jeans? Half our office wears jeans, Derek."]', '["공백은 여러 이유로 생겨요. 그쪽으로는 가지 말죠.","음. 지어낸 답보다는 \\"모르겠어요\\"가 나아요.","청바지요? 우리 사무실 절반이 청바지 입어요, 데릭."]', '["A red flag is a warning sign. Name a behavior, not a skill.","Key words: all the credit, under the bus"]', '["red flag는 위험 신호입니다. 기술이 아니라 행동을 말하세요.","핵심 단어: all the credit, under the bus"]', 'linda', 'Agreed. How people talk about their last team tells you a lot.', '동의해요. 전 팀을 어떻게 말하는지 보면 많은 걸 알 수 있죠.'),
  ('dk_d12_panel', 4, 'linda', 'She becomes more serious.', '그녀의 표정이 진지해집니다.', 'Now, my part. Small talk is fine, but there are questions we can''t ask. Do you know where the line is?', '이제 제 담당이요. 가벼운 잡담은 괜찮지만, 물어보면 안 되는 질문들이 있어요. 선이 어디인지 아세요?', 'Show her you know which personal topics are off-limits, and what you''ll talk about instead.', '어떤 사적인 주제가 금지인지 알고 있다는 걸 보여 주고, 대신 무엇을 이야기할지 말하세요.', '[{"all":["steer clear"]},{"all":["stick to"]},{"any":["personal"]}]', 'I''ll steer clear of anything personal, like age, family, or where someone is from, and stick to the job.', '나이, 가족, 출신 같은 사적인 건 피하고, 업무 얘기만 할게요.', '["I''ll avoid anything personal, like age or family. But asking where someone''s from is fine, right? It''s just small talk.","I''ll keep it casual. Asking about their kids or weekend plans helps them relax.","Honestly, I''ll ask whatever I need to ask. HR rules shouldn''t get in the way of that."]', '["나이나 가족은 피할게요. 근데 출신 묻는 건 잡담이니 괜찮죠?","편하게 할게요. 아이나 주말 계획을 물으면 긴장이 풀리잖아요.","솔직히 저는 물어볼 건 물어볼 거예요. 인사팀 규칙이 방해하면 안 되죠."]', '["Actually, no. That one''s off-limits, too.","Their kids? No. That''s exactly the kind of thing we can''t ask.","They''re not HR rules, Derek. They''re the law."]', '["아니요, 사실 그것도 금지예요.","아이요? 안 돼요. 그게 바로 물어보면 안 되는 거예요.","인사팀 규칙이 아니에요, 데릭. 법이에요."]', '["In a US interview, questions about age, family, religion or origin are off-limits.","Key words: steer clear of, anything personal, stick to the job"]', '["미국 면접에서는 나이, 가족, 종교, 출신에 대한 질문이 금지입니다.","핵심 단어: steer clear of, anything personal, stick to the job"]', 'linda', 'Exactly. Even "Are you married?" as small talk is off-limits. When in doubt, don''t ask.', '바로 그거예요. 가벼운 잡담으로 "결혼하셨어요?"라고 묻는 것도 금지예요. 애매하면 묻지 마세요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_panel', 5, 'linda', 'She writes your name on the panel list.', '그녀가 면접관 명단에 당신의 이름을 적습니다.', 'One more thing. Please write down your feedback before we debrief, not after.', '하나 더요. 평가 회의 전에 피드백을 적어 두세요. 끝나고 말고요.', 'Agree, and give the reason it matters: so one strong personality in the debrief doesn''t sway everyone else.', '동의하고, 그게 왜 중요한지 이유를 말하세요. 평가 회의에서 목소리 센 한 사람이 다른 사람들을 흔들지 않도록요.', '[{"any":["swayed","sway"]},{"all":["loudest voice"]},{"all":["makes sense"]}]', 'That makes sense. That way, nobody gets swayed by the loudest voice in the room.', '일리가 있네요. 그래야 회의실에서 목소리 제일 큰 사람한테 아무도 휩쓸리지 않죠.', '["Can''t I just share my thoughts in the debrief? Writing it up takes time.","That makes sense. That way, we can all agree on one score before we write it down.","Sure. I''ll write it up the week after, once I''ve had some time to think."]', '["그냥 평가 회의에서 생각을 말하면 안 돼요? 글로 쓰려면 시간이 걸려서요.","일리가 있네요. 그래야 적기 전에 다 같이 점수 하나로 맞출 수 있죠.","그럴게요. 좀 생각할 시간을 갖고 그다음 주에 정리해서 쓸게요."]', '["It does take time, but it''s worth it. Trust me.","No, the point is that you don''t agree first.","The week after? We''ll all have forgotten by then."]', '["시간은 걸려도 그럴 가치가 있어요. 믿어 봐요.","아니요, 요점은 먼저 맞추지 않는 거예요.","그다음 주요? 그때면 다 잊어버려요."]', '["Agree, and show that you understand the reason for the rule.","Key words: makes sense, swayed, the loudest voice"]', '["동의하고, 그 규칙의 이유를 이해한다는 것을 보여 주세요.","핵심 단어: makes sense, swayed, the loudest voice"]', 'linda', 'You''ve done this before. I''ll send the invites today.', '해 보신 분이네요. 오늘 초대장을 보낼게요.'),
  ('dk_d12_panel', 6, 'linda', 'You have a question of your own for HR.', '인사팀에 물어볼 것이 하나 있습니다.', 'Anything else I can help you with while you''re here?', '온 김에 제가 더 도와드릴 거 있어요?', 'Ask whether you get time off in return for being on call all of last week, weekend included.', '지난주 내내 주말까지 온콜이었던 것에 대해 보상 휴가를 받을 수 있는지 물어보세요.', '[{"all":["comp time"]},{"any":["entitled"]},{"all":["time off"]},{"all":["day off"]}]', 'Actually, yes. I was on call all last week, including the weekend. Am I entitled to any comp time?', '사실 있어요. 지난주 내내 주말까지 온콜이었는데요. 보상 휴가를 받을 수 있나요?', '["Actually, yes. I was on call last night, until about midnight. Am I entitled to any comp time for that?","Actually, yes. I was on call all last week. I expect at least three days off for that.","Actually, yes. How many vacation days do I have left this year? I''ve lost track."]', '["사실 있어요. 어젯밤 자정쯤까지 온콜이었는데요. 그것도 보상 휴가를 받을 수 있나요?","사실 있어요. 지난주 내내 온콜이었으니까 적어도 사흘은 쉬어야겠어요.","사실 있어요. 올해 휴가가 며칠 남았어요? 세다가 잊어버렸어요."]', '["Just one night? That doesn''t really count, I''m afraid.","Three days? Let''s see what the policy says first.","I can check that. But was there something about on call?"]', '["하룻밤이요? 그건 안타깝지만 해당이 안 돼요.","사흘이요? 규정부터 확인해 보죠.","그건 확인해 드릴게요. 그런데 온콜 얘기도 있지 않았어요?"]', '["\\"Comp time\\" = paid time off that you get in return for extra hours.","Key words: on call, entitled to, comp time"]', '["comp time은 추가로 일한 시간에 대해 받는 유급 휴가입니다.","핵심 단어: on call, entitled to, comp time"]', 'linda', 'You are. A week on call earns you half a day. Put in the request, and Maya will approve it. Just use it within sixty days.', '받을 수 있어요. 온콜 한 주에 반일이 나와요. 신청하면 마야가 승인할 거예요. 60일 안에만 쓰세요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_signed', 1, 'jun', 'Friday afternoon. Your phone rings at your desk. It is Jun, calling from the airport in Ridgeport.', '금요일 오후입니다. 자리에서 전화가 울립니다. 리지포트 공항에서 준이 건 전화입니다.', 'Derek! It''s Jun. We signed the contract this morning!', '데릭! 준이에요. 오늘 아침에 계약서에 사인했어요!', 'Share his excitement, and give him the credit.', '그의 기쁨을 함께 나누고, 공을 그에게 돌리세요.', '[{"any":["congratulations","congrats"]},{"all":["pulled it off"]},{"all":["that is huge"]}]', 'Congratulations! That''s huge. You pulled it off!', '축하해요! 엄청난 일이에요. 준이 해냈어요!', '["Great! I knew my prep notes would come in handy.","Oh, good. Did you read the fine print first?","Congrats! So Greg''s signing for all fifty stores?"]', '["잘됐네요! 제 준비 노트가 쓸모 있을 줄 알았어요.","아, 잘됐네요. 깨알 같은 조항은 먼저 읽었어요?","축하해요! 그럼 그렉이 매장 쉰 곳 전부 계약한 거예요?"]', '["Uh... yeah. They did help, I guess.","Priya did. Aren''t you even a little happy for me?","Forty, Derek. Starting with the five-store pilot."]', '["어... 네. 도움이 되긴 했죠.","프리야가 읽었어요. 저 잘된 거 조금도 안 기뻐요?","마흔 곳이에요, 데릭. 다섯 곳 시범 운영부터요."]', '["Share his joy first. Work can wait a minute.","Key words: congratulations, that''s huge, pulled it off"]', '["먼저 함께 기뻐해 주세요. 일 이야기는 잠시 뒤에 해도 됩니다.","핵심 단어: congratulations, that''s huge, pulled it off"]', 'jun', 'Thank you! Greg shook my hand. I still can''t believe it.', '감사합니다! 그렉이 악수를 청했어요. 아직도 믿기지 않아요.'),
  ('dk_d12_signed', 2, 'jun', 'You hear a boarding announcement behind him.', '그의 뒤로 탑승 안내 방송이 들립니다.', 'But I''ve been worried about the inventory bug. How bad is it?', '그런데 재고 버그가 계속 걱정됐어요. 얼마나 심해요?', 'Put his mind at ease: you found what was causing it, and the fix only needs his review.', '그를 안심시키세요. 원인을 찾아냈고, 수정 코드는 그의 리뷰만 남았다고요.', '[{"all":["taken care of"]},{"all":["tracked down"]},{"all":["tracked it down"]},{"all":["waiting for your review"]}]', 'It''s all taken care of. I tracked down the cause, and the fix is waiting for your review.', '다 처리됐어요. 원인 찾아냈고, 수정한 건 준 리뷰만 기다리고 있어요.', '["It''s all taken care of. Priya tracked down the cause, and the fix already went out this morning.","Pretty bad, honestly. Dana''s been emailing all week. We''ll talk on Monday.","Don''t ask. It took me two late nights, and Dana was not happy with us at all."]', '["다 처리됐어요. 프리야가 원인을 찾았고, 수정본은 오늘 아침에 벌써 나갔어요.","솔직히 꽤 심해요. 데이나가 일주일 내내 메일 보냈어요. 월요일에 얘기해요.","묻지 마요. 이틀 밤을 새웠고, 데이나는 우리한테 전혀 안 좋아했어요."]', '["Priya? Really? And it''s already live?","Oh no. Now I''m going to worry all weekend.","Two late nights? I''m so sorry, Derek."]', '["프리야가요? 정말요? 벌써 나갔다고요?","이런. 이제 주말 내내 걱정하겠네요.","이틀 밤이요? 정말 죄송해요, 데릭."]', '["Report the result, and leave the last step to him: it is his code.","Key words: taken care of, tracked down, waiting for your review"]', '["결과를 알려 주고 마지막 단계는 그에게 남기세요. 그의 코드니까요.","핵심 단어: taken care of, tracked down, waiting for your review"]', 'jun', 'Already? I owe you one.', '벌써요? 제가 신세 졌네요.'),
  ('dk_d12_signed', 3, 'jun', 'Jun laughs, then turns suspicious.', '준이 웃다가 의심스러운 목소리로 바뀝니다.', 'And the alert? You finished that too, didn''t you?', '그럼 경보는요? 그것도 다 끝내 놓으셨죠?', 'Reassure him you left the alert alone; it''s his, and there''s no hurry.', '경보에는 손대지 않았다고 안심시키세요. 그의 일이고, 서두를 것 없다고요.', '[{"all":["lay a finger"]},{"all":["did not touch"]},{"all":["still yours"]}]', 'Nope. I didn''t lay a finger on it. It''s still yours, and it can wait till Monday.', '아니요. 손끝 하나 안 댔어요. 아직 준 거예요. 월요일까지 기다려도 돼요.', '["Just a little. I wrapped up the tests, but the rest is still yours.","Nope. I didn''t touch it. It''s still yours. Could you finish it on the plane tonight?","Yep, it''s done and merged. I figured you''d be too busy for it."]', '["조금만요. 테스트는 제가 마무리했고, 나머지는 아직 준 거예요.","아니요. 손 안 댔어요. 아직 준 거예요. 오늘 밤 비행기에서 끝내 줄 수 있어요?","네, 다 끝내서 머지했어요. 준은 너무 바쁠 것 같아서요."]', '["The tests? Aw, I wanted to write those.","On the plane? I was hoping to sleep.","Oh. Okay. I really wanted to finish that one."]', '["테스트요? 아, 그건 제가 쓰고 싶었는데요.","비행기에서요? 자려고 했는데요.","아. 네. 그건 정말 제가 끝내고 싶었어요."]', '["You delegated it, so you left it alone. Say so.","Key words: didn''t lay a finger on it, still yours"]', '["맡긴 일이니 건드리지 않았습니다. 그렇게 말하세요.","핵심 단어: didn''t lay a finger on it, still yours"]', 'jun', 'Good. I want to finish that one myself.', '다행이에요. 그건 제 손으로 끝내고 싶어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d12_signed', 4, 'jun', 'He sounds tired but happy.', '그는 지쳤지만 기쁜 목소리입니다.', 'My flight is overbooked, so I''m taking a later one. I can work on the alert at the gate tonight.', '비행기가 초과 예약돼서 더 늦은 걸로 타요. 오늘 밤 게이트에서 경보 작업 좀 할 수 있겠어요.', 'He wants to work at the gate tonight. As his teammate, look out for him.', '그는 오늘 밤 공항 게이트에서 일하겠다고 합니다. 동료로서 그를 챙겨 주세요.', '[{"all":["call it a day"]},{"any":["unplug"]},{"all":["earned it"]}]', 'Don''t you dare. Call it a day. You''ve earned it. And unplug this weekend.', '절대 안 돼요. 오늘은 여기까지 해요. 그럴 자격 충분해요. 그리고 주말엔 일에서 완전히 손 떼요.', '["Good idea. If you push it tonight, we can merge it Monday.","Don''t. And take Monday off, too. Maya already approved it.","Up to you, I guess. Just don''t send me anything this weekend. I''m offline."]', '["좋은 생각이에요. 오늘 밤에 올려 두면 월요일 아침에 바로 머지할 수 있겠네요.","하지 마요. 그리고 월요일도 쉬어요. 마야가 이미 승인해 줬어요. 푹 쉬어요.","그건 뭐, 알아서 해요. 대신 이번 주말엔 저한테 아무것도 보내지 마요. 저 쉬어요."]', '["Really? I thought you''d tell me to rest.","Maya approved it? When did she do that?","Oh. Okay. I''ll keep it to myself, then."]', '["정말요? 쉬라고 하실 줄 알았는데요.","마야가 승인했다고요? 언제요?","아. 네. 그럼 혼자 하고 말게요."]', '["A good lead protects people''s rest.","Key words: call it a day, earned it, unplug"]', '["좋은 리더는 팀원의 휴식을 지켜 줍니다.","핵심 단어: call it a day, earned it, unplug"]', 'jun', 'Okay, okay. No laptop. I promise.', '알겠어요, 알겠어요. 노트북은 안 열게요. 약속해요.'),
  ('dk_d12_signed', 5, 'jun', 'The announcement behind him gets louder.', '그의 뒤에서 안내 방송 소리가 커집니다.', 'Thanks for covering for me, Derek. Really.', '대신 맡아 줘서 고마워요, 데릭. 진짜로요.', 'Tell him it was no trouble, that''s what a team is for, and say goodbye until Monday morning.', '별일 아니었다고, 팀이 그러라고 있는 거라고 하고, 월요일 아침까지 인사하세요.', '[{"all":["what teammates are for"]},{"all":["bright and early"]},{"all":["what friends are for"]}]', 'Anytime. That''s what teammates are for. See you bright and early on Monday.', '언제든지요. 팀이 그러라고 있는 거죠. 월요일 아침 일찍 봐요.', '["No problem. You owe me one, though. I''ll collect next week.","Anytime. That''s what teammates are for. See you at the office bright and early tomorrow.","Sure. Just don''t make it a habit. I have my own work, too."]', '["별말씀을요. 대신 하나 빚진 거예요. 다음 주에 받아 갈게요.","언제든지요. 팀이 그러라고 있는 거죠. 내일 아침 일찍 사무실에서 봐요.","그래요. 버릇 되진 않게 해요. 저도 제 일이 있으니까요."]', '["Ha. Okay. I''ll buy the coffee.","Tomorrow''s Saturday, Derek. You said no work!","Oh. Sorry. I didn''t mean to dump it on you."]', '["하하. 네. 커피는 제가 살게요.","내일은 토요일이에요, 데릭. 일하지 말라면서요!","아. 죄송해요. 떠넘기려던 건 아니었어요."]', '["Accept thanks lightly, and say goodbye.","Key words: that''s what teammates are for, bright and early"]', '["고맙다는 말을 가볍게 받고 작별 인사를 하세요.","핵심 단어: that''s what teammates are for, bright and early"]', 'jun', 'See you Monday! Oh, they''re calling my flight. Bye!', '월요일에 봬요! 아, 제 비행기 탑승 안내가 나와요. 끊을게요!'),
  ('dk_d2_diner', 1, 'rosa', 'The lunch crowd has not arrived yet. Rosa is already pouring a glass of water at your usual seat.', '점심 손님이 아직 몰리기 전입니다. 로사가 벌써 당신이 늘 앉는 자리에 물을 따르고 있습니다.', 'Well, look who it is! Hi, hon. Your usual spot at the counter?', '어머, 이게 누구야! 안녕, 자기. 늘 앉던 카운터 자리죠?', 'Take your usual seat, and find out what she''s featuring today.', '늘 앉던 자리에 앉고, 오늘 따로 내놓은 메뉴가 뭔지 알아보세요.', '[{"any":["special","specials"]}]', 'Yes, please. What''s the special today?', '네, 그럴게요. 오늘 스페셜은 뭐예요?', '["Actually, could I get a booth today?","Yes, please. The turkey club, as usual.","Sure. I''m in a hurry, so make it quick."]', '["아, 오늘은 부스 자리 앉아도 될까요?","네, 그럴게요. 늘 먹던 터키 클럽으로요.","네. 바쁘니까 좀 빨리 해 주세요."]', '["A booth? You''ve sat at this counter for years, hon.","Already? You''re not even curious what''s new today?","Well, hello to you too, grumpy."]', '["부스요? 몇 년째 이 카운터에 앉았잖아요, 자기.","벌써요? 오늘 새로 뭐 있는지 안 궁금해요?","어머, 반가워요, 까칠 씨."]', '["Diners have a dish of the day called \\"the special\\".","Key words: the special"]', '["다이너에는 the special이라는 오늘의 메뉴가 있습니다.","핵심 단어: the special"]', 'rosa', 'Patty melt with fries, thirteen ninety-five.', '패티 멜트에 감자튀김, 13달러 95센트예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_diner', 2, 'rosa', 'She takes the pencil from behind her ear.', '그녀가 귀에 꽂은 연필을 뺍니다.', 'Or I can put in your usual: turkey club, no mayo.', '아니면 늘 먹던 걸로 넣어 줄까요? 터키 클럽, 마요 빼고.', 'You want today''s special, but with salad on the side, not fries.', '오늘은 스페셜을 먹고 싶은데, 감자튀김 말고 샐러드를 곁들이고 싶습니다.', '[{"all":["instead of"]},{"any":["swap","substitute"]},{"all":["side salad"]}]', 'I''ll go with the special. Could I get a side salad instead of the fries?', '스페셜로 할게요. 감자튀김 대신 사이드 샐러드로 바꿔 주실 수 있어요?', '["Yeah, let''s do the usual. Turkey club, no mayo, side salad.","I''ll go with the special. Could I get the onion rings instead of the fries, please?","I''ll go with the special, but no fries. Take a dollar off for that."]', '["네, 늘 먹던 걸로 할게요. 터키 클럽, 마요 빼고, 샐러드로요.","스페셜로 할게요. 감자튀김 대신 어니언 링으로 바꿔 주실 수 있어요?","스페셜로 할게요. 감자튀김은 빼고, 그만큼 1달러 깎아 주세요."]', '["The usual? I thought the patty melt caught your eye.","Onion rings? Sure, hon. That''s a dollar extra.","Hon, I don''t set the prices. It''s thirteen ninety-five."]', '["늘 먹던 거요? 패티 멜트에 눈이 가는 줄 알았는데.","어니언 링이요? 그럼요, 자기. 1달러 추가예요.","자기, 가격은 내가 정하는 게 아니에요. 13달러 95센트예요."]', '["Choose with \\"I''ll go with …\\" and swap the side.","Key words: go with, instead of the fries"]', '["\\"I''ll go with …\\"로 고르고 사이드를 바꾸세요.","핵심 단어: go with, instead of the fries"]', 'rosa', 'Sure thing, hon. Salad it is.', '그럼요. 샐러드로 할게요.'),
  ('dk_d2_diner', 3, 'rosa', 'Rosa holds up the coffee pot.', '로사가 커피포트를 들어 보입니다.', 'Coffee while you wait?', '기다리는 동안 커피 한잔할래요?', 'You''ve had enough caffeine for one day. Decline the coffee.', '오늘은 카페인을 충분히 마셨습니다. 커피는 사양하세요.', '[{"any":["water"]},{"all":["iced tea"]}]', 'Just water is fine, thanks. I''ve already had two cups today.', '물이면 돼요, 고마워요. 오늘 벌써 두 잔 마셨어요.', '["Sure, why not? Fill it up. I can always use more.","Just water is fine, thanks. I haven''t had any coffee yet today.","No, thanks. To be honest, your coffee''s not really my thing."]', '["좋죠, 뭐. 가득 채워 주세요. 커피는 많을수록 좋아요.","물이면 돼요, 고마워요. 오늘 아직 커피를 한 잔도 안 마셨어요.","됐어요. 솔직히 여기 커피는 제 취향이 아니라서요."]', '["Here you go, hon. Fresh pot.","No coffee yet? Then you definitely need a cup, hon.","Ouch. Well, the water''s free, at least."]', '["여기요, 자기. 방금 내린 거예요.","아직 한 잔도 안 마셨다고요? 그럼 꼭 한 잔 해야죠, 자기.","아야. 뭐, 물은 공짜니까요."]', '["Say what you want instead of coffee.","Key words: just water"]', '["커피 대신 원하는 것을 말하세요.","핵심 단어: just water"]', 'rosa', 'Smart. Be right back.', '현명하네요. 금방 올게요.'),
  ('dk_d2_diner', 4, 'rosa', 'You clean your plate. Rosa comes by with the pie menu.', '접시를 깨끗이 비웠습니다. 로사가 파이 메뉴를 들고 옵니다.', 'How was everything? Did you save room for pie?', '다 괜찮았어요? 파이 먹을 배는 남겨 뒀죠?', 'The food was great, but you can''t eat another bite. Wrap things up.', '음식은 아주 좋았지만 더는 못 먹겠습니다. 마무리하세요.', '[{"any":["check","bill"]},{"all":["hit the spot"]},{"any":["stuffed"]}]', 'It really hit the spot, but I''m stuffed. Just the check, please.', '정말 딱 좋았어요. 근데 배가 터질 것 같아요. 계산서만 주세요.', '["Delicious. Sure, I''ll have a slice of the apple pie, too.","It was fine, I guess. The salad was a little sad. Check, please.","It really hit the spot. The fries were perfect. Just the check, please."]', '["맛있었어요. 그럼 애플파이도 한 조각 주실래요?","그냥 그랬어요. 샐러드가 좀 시들했네요. 계산서 주세요.","정말 딱 좋았어요. 감자튀김이 완벽했어요. 계산서만 주세요."]', '["Apple pie it is! Warm, with ice cream?","Sad, huh? Well, I''ll tell the cook.","The fries? Hon, you had the salad."]', '["애플파이요! 따뜻하게, 아이스크림 올려서?","시들했다고요? 요리사한테 전할게요.","감자튀김이요? 자기, 샐러드 먹었잖아요."]', '["Praise the food, say you are full, ask for the check.","Key words: hit the spot, stuffed, the check"]', '["음식을 칭찬하고, 배부르다고 하고, 계산서를 부탁하세요.","핵심 단어: hit the spot, stuffed, the check"]', 'rosa', 'Here you go, hon. No rush.', '여기 있어요. 천천히 해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_diner', 5, 'rosa', 'The check says $15.10 with tax. You put a ten, a five and three ones on the counter.', '계산서에는 세금 포함 15.10달러라고 적혀 있습니다. 10달러, 5달러, 1달러 석 장을 카운터에 놓습니다.', 'Fifteen ten. Whenever you''re ready, hon.', '15달러 10센트예요. 편할 때 줘요, 자기.', 'Pay with the bills on the counter, and let her know you don''t need change.', '카운터에 놓은 돈으로 계산하고, 거스름돈은 필요 없다고 알려 주세요.', '[{"all":["all set"]},{"all":["keep the change"]},{"all":["no change"]}]', 'Here''s eighteen. We''re all set.', '여기 18달러요. 이거면 됐어요.', '["Here''s fifteen. We''re all set.","That''s eighteen. Can I get two back?","Here''s a twenty. Keep it all, Rosa."]', '["여기 15달러요. 이거면 됐어요.","여기 18달러요. 2달러 거슬러 줄래요?","여기 20달러요. 전부 가져요, 로사."]', '["Hon, it''s fifteen ten. You''re a dime short.","Two back? Sure... coming right up.","A twenty? I see a ten, a five and three ones, hon."]', '["자기, 15달러 10센트예요. 10센트 모자라요.","2달러 거슬러 달라고요? 네... 금방 줄게요.","20달러요? 내 눈엔 10달러, 5달러, 1달러 석 장인데요."]', '["\\"We''re all set\\" with cash means: I do not need change.","Key words: all set"]', '["현금을 내며 \\"We''re all set\\"이라고 하면 거스름돈은 필요 없다는 뜻입니다.","핵심 단어: all set"]', 'rosa', 'Thanks, hon! Tell that new kid at your office to come by.', '고마워요! 사무실에 새로 온 친구한테도 들르라고 해요.'),
  ('dk_d2_estimate', 1, 'priya', 'The thirty minutes Priya booked yesterday. She has the roadmap on the big screen.', '어제 프리야가 잡아 둔 30분 회의입니다. 큰 화면에 로드맵이 떠 있습니다.', 'Thanks for making time. Summit Retail wants gift card support in checkout. I told them it''s probably a two-day job. Does that sound right?', '시간 내 줘서 고마워요. 서밋 리테일이 결제에 기프트 카드 지원을 원해요. 아마 이틀이면 될 거라고 말해 뒀어요. 맞는 것 같아요?', 'You disagree: you think this will take about a week. Say so tactfully.', '동의하지 않습니다. 일주일쯤 걸릴 것 같아요. 정중하게 말하세요.', '[{"all":["push back"]},{"all":["more like"]},{"any":["week","optimistic","underestimate"]}]', 'I''d push back on that. Honestly, it''s more like a week.', '그건 좀 아닌 것 같아요. 솔직히 일주일은 걸려요.', '["Sounds about right. Two days should be plenty.","You promised two days without asking me? Seriously?","I''d push back on that. Honestly, it''s more like a month."]', '["얼추 맞는 것 같아요. 이틀이면 충분하죠.","저한테 묻지도 않고 이틀이라고 약속하셨어요? 진짜요?","그건 좀 아닌 것 같아요. 솔직히 한 달은 걸려요."]', '["Great. I''ll confirm with Greg this afternoon.","Okay, fair. But let''s focus on the estimate.","A month?! I can''t tell Greg a month for one field."]', '["좋아요. 오늘 오후에 그렉한테 확정해 줄게요.","네, 그 말도 맞아요. 근데 추정치에 집중해요.","한 달이요?! 입력란 하나에 한 달이라고 그렉한테 말 못 해요."]', '["Disagree with the number, not the person.","Key words: push back, more like a week"]', '["사람이 아니라 숫자에 반대하세요.","핵심 단어: push back, more like a week"]', 'priya', 'A week? Okay, help me understand.', '일주일요? 알겠어요, 이해할 수 있게 설명해 줘요.'),
  ('dk_d2_estimate', 2, 'priya', 'Priya pulls up the design. It shows one new field on the payment form.', '프리야가 디자인을 띄웁니다. 결제 양식에 새 입력란 하나가 보입니다.', 'What makes it so big? It looks like one extra field on the form.', '왜 그렇게 커요? 양식에 입력란 하나 더 생기는 것 같은데.', 'Explain where the real work is: behind the form, in old payment code nobody has tests for.', '진짜 일이 어디 있는지 설명하세요. 양식 뒤편, 테스트가 하나도 없는 오래된 결제 코드요.', '[{"any":["legacy"]},{"all":["no tests"]},{"all":["old code"]},{"all":["under the hood"]}]', 'The form is the easy part. Under the hood, it touches the legacy payment code, and that has no tests.', '양식은 쉬운 부분이에요. 내부적으로는 레거시 결제 코드를 건드리는데, 거기엔 테스트가 없어요.', '["The form is the easy part. Under the hood, it touches the login code, and that has no tests.","It''s not just one field, Priya. You''d understand that if you''d ever read the code.","It''s hard to explain in a meeting. You''ll just have to trust me that it''s a lot bigger than it looks."]', '["양식은 쉬운 부분이에요. 내부적으로는 로그인 코드를 건드리는데, 거기엔 테스트가 없어요.","그냥 입력란이 아니에요, 프리야. 코드를 한 번이라도 봤으면 아셨을 거예요.","회의에서 설명하기는 좀 어려워요. 보기보다 훨씬 큰 일이라는 것만 그냥 믿어 주세요."]', '["The login code? What does that have to do with gift cards?","Wow. Okay. I''m asking because I have to explain it to Greg.","I do trust you. But Greg won''t accept \\"trust me.\\""]', '["로그인 코드요? 그게 기프트 카드랑 무슨 상관이에요?","와. 네. 그렉한테 설명해야 해서 묻는 건데요.","믿어요. 근데 그렉은 ''믿어 달라''로는 안 넘어가요."]', '["Give the technical reason in plain words.","Key words: under the hood, legacy, no tests"]', '["기술적인 이유를 쉬운 말로 설명하세요.","핵심 단어: under the hood, legacy, no tests"]', 'priya', 'Ah. The legacy stuff again.', '아. 또 레거시군요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_estimate', 3, 'priya', 'She taps her pen on the table.', '그녀가 펜으로 테이블을 톡톡 칩니다.', 'I hear you. But Greg is expecting a date. What can I tell him?', '무슨 말인지 알아요. 하지만 그렉이 날짜를 기다리고 있어요. 뭐라고 말하면 될까요?', 'You can''t give a date yet. Ask for a single day to investigate before you commit to one.', '아직 날짜는 못 줍니다. 약속하기 전에 하루만 조사할 시간을 달라고 하세요.', '[{"any":["timebox","timeboxed","spike"]},{"all":["real estimate"]},{"all":["one day"],"any":["estimate","investigate"]}]', 'Can we timebox it? Give me one day for a spike, and I''ll come back with a real estimate.', '기간을 정해 두면 어떨까요? 하루만 사전 조사할 시간을 주시면 제대로 된 추정치를 가져올게요.', '["Just tell him next Friday for sure. I''ll work the weekend if I have to.","Can we timebox it? Give me a full week for a spike, and I''ll come back with a real estimate.","Tell him whatever you want. You''re the one who promised him two days."]', '["그냥 다음 주 금요일이라고 확실히 말하세요. 필요하면 주말에 일할게요.","기간을 정해 두면 어떨까요? 일주일 꼬박 사전 조사하면 제대로 된 추정치를 가져올게요.","그냥 마음대로 말하세요. 처음에 이틀이면 된다고 약속한 건 프리야잖아요."]', '["I don''t want you working weekends, Derek. That''s not a plan.","A week just to estimate? Greg will hit the roof.","Okay, I deserved that. But I still need something to tell him."]', '["주말에 일하는 건 싫어요, 데릭. 그건 계획이 아니잖아요.","추정만 하는 데 일주일요? 그렉이 펄쩍 뛸 거예요.","네, 그 말 들어도 싸요. 그래도 뭐라고는 말해야 해요."]', '["Offer a small, fixed amount of time to find out.","Key words: timebox, spike, real estimate"]', '["알아보는 데 쓸 짧고 정해진 시간을 제안하세요.","핵심 단어: timebox, spike, real estimate"]', 'priya', 'A one-day spike. I can sell that.', '하루짜리 사전 조사. 그건 설득할 수 있어요.'),
  ('dk_d2_estimate', 4, 'priya', 'Priya looks at the sprint board. It is full.', '프리야가 스프린트 보드를 봅니다. 꽉 차 있습니다.', 'And if it really is a week, something has to give. What would you drop?', '그리고 정말 일주일이면 뭔가는 포기해야 해요. 뭘 빼겠어요?', 'Name what you''d give up this sprint to make room.', '자리를 만들려면 이번 스프린트에서 무엇을 뺄지 말하세요.', '[{"all":["next sprint"]},{"all":["trade off"]},{"any":["tradeoff","deprioritize"]},{"all":["saved cards"]}]', 'It''s a trade-off. I''d move saved cards to the next sprint.', '하나를 얻으려면 하나는 내줘야죠. 저장된 카드를 다음 스프린트로 옮길게요.', '["It''s a trade-off. I''d stop helping Jun for a while.","Nothing has to give. I''ll just stay late every night this week.","It''s a trade-off. I''d move the checkout API to next sprint."]', '["하나를 얻으려면 하나는 내줘야죠. 당분간 준을 돕는 걸 멈출게요.","포기할 건 없어요. 이번 주에 매일 밤 늦게까지 남으면 돼요.","하나를 얻으려면 하나는 내줘야죠. 결제 API를 다음 스프린트로 옮길게요."]', '["Jun? It''s his first week. That can''t be the thing we drop.","Every night? No. Something has to come off the board.","Isn''t that already done and in review?"]', '["준이요? 입사 첫 주잖아요. 그걸 뺄 순 없어요.","매일 밤이요? 안 돼요. 보드에서 뭔가는 빠져야 해요.","그건 벌써 끝나서 리뷰 중 아니에요?"]', '["Name what moves out if this moves in.","Key words: trade-off, next sprint"]', '["이 일이 들어오면 무엇이 빠지는지 말하세요.","핵심 단어: trade-off, next sprint"]', 'priya', 'Okay. I''d rather give him an honest date than a missed one. Thanks for being straight with me.', '알겠어요. 못 지킬 날짜보다 정직한 날짜를 주는 게 낫죠. 솔직하게 말해 줘서 고마워요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_review', 1, 'jun', 'You roll your chair over to Jun''s desk with your coffee. He has your review open on his screen.', '커피를 들고 의자를 굴려 준의 자리로 갑니다. 그의 화면에 당신의 리뷰가 열려 있습니다.', 'Good morning. I saw your comments on my pull request. There are twelve of them. Is it that bad?', '좋은 아침이에요. 제 풀 리퀘스트에 남기신 코멘트 봤어요. 열두 개나 되던데요. 그렇게 별로예요?', 'He''s worried about the twelve comments. Put them in perspective: the work is good, and most are minor.', '코멘트 열두 개에 걱정이 많습니다. 작업은 좋았고 대부분은 사소한 것이라고 짚어 주세요.', '[{"any":["nits","nit","nitpicks"]},{"all":["solid"]},{"all":["good start"]},{"any":["minor"]}]', 'Not at all. It''s a solid first pull request. Most of my comments are just nits.', '전혀요. 첫 풀 리퀘스트로 탄탄해요. 코멘트 대부분은 그냥 사소한 거예요.', '["Not at all. It''s a solid first pull request. I only left two or three comments.","Honestly, it needs a lot of work. Twelve comments is a lot for one PR.","Don''t worry about the comments yet. We can go through them sometime next week."]', '["전혀요. 첫 풀 리퀘스트로 탄탄해요. 코멘트는 두세 개밖에 안 남겼어요.","솔직히 손볼 게 많아요. PR 하나에 코멘트 열두 개면 많은 거죠.","코멘트는 아직 신경 쓰지 마요. 다음 주쯤 같이 훑어봐요."]', '["Two or three? I counted twelve...","Oh. I see. I''ll... try harder.","Next week? But I''d like to fix them today."]', '["두세 개요? 저는 열두 개로 셌는데요...","아. 그렇군요. 더... 열심히 할게요.","다음 주요? 오늘 고치고 싶은데요."]', '["Start with what is good. A \\"nit\\" is a tiny, optional fix.","Key words: solid, just nits"]', '["좋은 점부터 말하세요. nit은 아주 사소한, 선택적인 수정입니다.","핵심 단어: solid, just nits"]', 'jun', 'Oh, good. I was worried all night.', '아, 다행이에요. 밤새 걱정했어요.'),
  ('dk_d2_review', 2, 'jun', 'Jun scrolls through the comments.', '준이 코멘트를 쭉 내려 봅니다.', 'Which comment is the most important one?', '어떤 코멘트가 제일 중요해요?', 'Point out the real issue: a failed payment call goes unnoticed.', '진짜 문제를 짚어 주세요. 결제 호출이 실패해도 아무도 모르고 넘어간다는 거요.', '[{"all":["error handling"]},{"any":["swallow","swallowed","swallows"]},{"all":["payment"],"any":["fails","fail","failure"]}]', 'The main one is error handling. Right now, if the payment call fails, we swallow the error.', '제일 중요한 건 오류 처리예요. 지금은 결제 호출이 실패하면 오류를 그냥 삼켜 버려요.', '["The main one is the variable names. Names like \\"data2\\" make the code hard to follow.","The main one is error handling. Right now, if the payment call fails, the whole app crashes.","They''re all equally important, honestly. Just go through them one by one."]', '["제일 중요한 건 변수 이름이에요. \\"data2\\" 같은 이름은 코드를 따라가기 힘들게 해요.","제일 중요한 건 오류 처리예요. 지금은 결제 호출이 실패하면 앱 전체가 죽어요.","솔직히 열두 개 다 똑같이 중요해요. 처음부터 하나씩 차례로 고쳐 봐요."]', '["The names? I thought you said those were just nits.","It crashes? I tested it, and nothing crashed...","All twelve? Okay... that''s a lot."]', '["이름이요? 그건 사소한 거라고 하셨잖아요.","앱이 죽는다고요? 테스트해 봤는데 안 죽던데요...","열두 개 전부요? 네... 많네요."]', '["Say \\"we\\", not \\"you\\": the problem is in the code, not in him.","Key words: error handling, swallow the error"]', '["you 대신 we를 쓰세요. 문제는 사람이 아니라 코드에 있습니다.","핵심 단어: error handling, swallow the error"]', 'jun', 'I see. So the user never finds out that it failed.', '그렇군요. 그러면 사용자는 실패한 줄도 모르겠네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d2_review', 3, 'jun', 'He opens the file.', '그가 파일을 엽니다.', 'What should I do instead?', '그럼 대신 어떻게 해야 할까요?', 'Suggest recording the error and telling the user kindly, and get his view on trying again.', '오류를 기록하고 사용자에게 친절히 알리자고 제안하고, 한 번 더 시도하는 것에 대한 그의 생각을 물어보세요.', '[{"any":["log","logging"]},{"any":["retry"]},{"all":["friendly message"]},{"all":["error message"]}]', 'I''d suggest logging it and showing the user a friendly message. What do you think about adding one retry?', '로그를 남기고 사용자한테 친절한 메시지를 보여 주는 게 좋겠어요. 재시도 한 번 넣는 건 어떻게 생각해요?', '["Just wrap it in a try-catch and ignore it. Users won''t notice one failed payment anyway.","Log it, show the user a friendly message, and add five retries. Don''t argue with me, just do it.","I''d suggest logging it and showing the user the full error message and stack trace. Any thoughts on that?"]', '["그냥 try-catch로 감싸고 무시해요. 결제 한 번 실패한 건 사용자들이 어차피 모를 거예요.","로그 남기고, 친절한 메시지 보여 주고, 재시도 다섯 번 넣어요. 토 달지 말고 그냥 해요.","로그를 남기고 사용자한테 전체 오류 메시지랑 스택 트레이스를 보여 주는 게 좋겠어요. 어떻게 생각해요?"]', '["But isn''t that what the code does now? Swallow it?","Oh. Okay. Five retries, got it.","A stack trace? Won''t that scare the users?"]', '["근데 그게 지금 코드가 하는 거 아니에요? 그냥 삼키는 거요?","아. 네. 재시도 다섯 번, 알겠어요.","스택 트레이스요? 사용자들이 놀라지 않을까요?"]', '["Soften it: \\"I''d suggest …\\", \\"What do you think about …?\\"","Key words: I''d suggest, logging, retry"]', '["\\"I''d suggest …\\", \\"What do you think about …?\\"로 부드럽게 말하세요.","핵심 단어: I''d suggest, logging, retry"]', 'jun', 'A retry makes sense. I''ll add that.', '재시도가 맞겠네요. 넣을게요.'),
  ('dk_d2_review', 4, 'jun', 'Jun points at a smaller comment.', '준이 작은 코멘트 하나를 가리킵니다.', 'And the variable names. Is "data2" really a problem?', '그리고 변수 이름이요. "data2"가 정말 문제예요?', 'Admit it''s minor, but explain why naming still matters.', '사소한 거라고 인정하되, 그래도 이름이 왜 중요한지 설명하세요.', '[{"all":["nit"]},{"any":["clearer","readable","descriptive"]},{"all":["next person"]}]', 'It''s a nit, but a clearer name helps the next person who reads the code.', '사소한 거긴 한데, 이름이 분명하면 다음에 코드 읽는 사람한테 도움이 돼요.', '["Yes, it''s a serious problem. I can''t approve the PR with names like that.","No, not really. Leave it as it is. Names don''t matter much anyway.","It''s a nit, but Maya hates names like that, so you''d better change it."]', '["네, 심각한 문제예요. 이름이 저러면 PR 승인 못 해요.","아뇨, 별로요. 그냥 둬요. 어차피 이름은 크게 상관없어요.","사소하긴 한데, 마야가 저런 이름을 싫어해서 바꾸는 게 좋을 거예요."]', '["Really? I thought it was a small thing.","Then why did you leave the comment?","Oh. So it''s about Maya, not the code?"]', '["정말요? 작은 건 줄 알았는데요.","그럼 왜 코멘트를 다셨어요?","아. 그럼 코드 때문이 아니라 마야 때문이에요?"]', '["Call it small, and give the reason.","Key words: nit, clearer name"]', '["사소하다고 말하고 이유를 덧붙이세요.","핵심 단어: nit, clearer name"]', 'jun', 'That''s fair. I''ll rename them.', '맞는 말이에요. 이름을 바꿀게요.'),
  ('dk_d2_review', 5, 'jun', 'He writes a short to-do list.', '그가 할 일을 짧게 적습니다.', 'I''ll add a unit test for the failure case, too. Anything else?', '실패하는 경우에 대한 단위 테스트도 추가할게요. 다른 건요?', 'Nothing more to fix. Tell him what happens next, and give him some credit.', '더 고칠 건 없습니다. 다음 단계가 뭔지 알려 주고 칭찬도 해 주세요.', '[{"any":["approve"]},{"all":["nice work"]},{"all":["good job"]},{"all":["great job"]},{"all":["looks good"]}]', 'That''s it. Once the tests pass, I''ll approve it. Nice work, by the way.', '그거면 돼요. 테스트 통과하면 승인할게요. 그나저나 잘했어요.', '["That''s it. Once the tests pass, Priya will approve it and merge it. Nice work.","Actually, while you''re at it, could you also rewrite the whole module?","That''s it. Once the tests pass, I''ll approve it. Took a while, though."]', '["그거면 돼요. 테스트 통과하면 프리야가 승인하고 머지할 거예요. 잘했어요.","아, 하는 김에 모듈 전체도 다시 짜 줄 수 있어요?","그거면 돼요. 테스트 통과하면 승인할게요. 좀 오래 걸리긴 했네요."]', '["Priya? I thought you were reviewing it.","The whole module? For my first PR?","Oh. Sorry it took so long."]', '["프리야요? 데릭이 리뷰하시는 줄 알았는데요.","모듈 전체를요? 첫 PR인데요?","아. 오래 걸려서 죄송해요."]', '["Close with the next step and a compliment.","Key words: approve, nice work"]', '["다음 단계와 칭찬으로 마무리하세요.","핵심 단어: approve, nice work"]', 'jun', 'Thank you! I''ll push an update by end of day.', '감사합니다! 오늘 퇴근 전까지 수정해서 올릴게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_one_on_one', 1, 'maya', 'Rain taps on the window of Maya''s office. She closes her laptop and turns to you.', '마야의 사무실 창문에 빗방울이 부딪힙니다. 그녀가 노트북을 덮고 당신을 봅니다.', 'So, six years at Seaside. Where do you see yourself going from here?', '그래서, 시사이드에서 6년이네요. 앞으로 어떤 방향으로 가고 싶어요?', 'Tell her the career direction you''d like: leading the team technically.', '원하는 커리어 방향을 말하세요. 팀을 기술적으로 이끄는 쪽으로요.', '[{"all":["tech lead"]},{"all":["technical lead"]},{"all":["lead"],"any":["team","role","track"]}]', 'I''ve been thinking about that. I''m interested in the tech lead track.', '저도 그 생각을 하고 있었어요. 테크 리드 트랙에 관심이 있어요.', '["I''ve been thinking about that. I''d like to move into product management.","Honestly, I''m happy where I am. I just want to keep coding.","I''ve been thinking about that. I want a promotion by next quarter."]', '["저도 그 생각을 하고 있었어요. 프로덕트 매니지먼트 쪽으로 가고 싶어요.","솔직히 지금이 좋아요. 그냥 계속 코딩만 하고 싶어요.","저도 그 생각을 하고 있었어요. 다음 분기까지는 승진하고 싶어요."]', '["Product? Like Priya? That''s a surprise.","That''s fine, too. But I sense there''s more.","Let''s talk about the path first, not the date."]', '["프로덕트요? 프리야처럼요? 의외네요.","그것도 괜찮아요. 근데 뭔가 더 있는 것 같은데요.","날짜보다 방향부터 이야기해요."]', '["Name the role you want with \\"I''m interested in …\\".","Key words: interested in, tech lead track"]', '["\\"I''m interested in …\\"으로 원하는 역할을 말하세요.","핵심 단어: interested in, tech lead track"]', 'maya', 'I was hoping you''d say that.', '그렇게 말해 주길 바랐어요.'),
  ('dk_d3_one_on_one', 2, 'maya', 'Maya leans back in her chair.', '마야가 의자에 등을 기댑니다.', 'What draws you to it? You''d write less code, you know.', '왜 끌리는 거예요? 코드는 덜 짜게 될 텐데요.', 'Explain your reasons: you like helping people grow, and you want more influence over technical choices.', '이유를 설명하세요. 사람들이 성장하도록 돕는 게 좋고, 기술적인 선택에 더 영향력을 갖고 싶다고요.', '[{"any":["mentoring","mentor"]},{"all":["technical decisions"]},{"all":["a say"]},{"any":["architecture"]}]', 'I know. But I really enjoy mentoring, and I''d like more of a say in our technical decisions.', '알아요. 하지만 멘토링이 정말 즐겁고, 우리 기술 결정에 더 목소리를 내고 싶어요.', '["I know. Honestly, it''s mostly the raise, and I''m getting a little tired of writing code all day.","I know. But some of our technical decisions lately have been pretty bad, frankly.","Less code? Oh. I didn''t know that. Then maybe I''m not so sure about it after all."]', '["알아요. 솔직히 연봉 때문이 제일 크고, 하루 종일 코딩하는 것도 좀 지겨워졌어요.","알아요. 근데 솔직히 요즘 우리 기술 결정 중에 꽤 별로인 게 많았어요.","코드를 덜 짜요? 아, 몰랐어요. 그럼 다시 생각해 봐야겠네요."]', '["The raise is real, but that alone won''t carry you.","Bad how? That sounds like a different conversation.","Hm. Then let''s figure out what you really want."]', '["연봉이 오르는 건 맞지만, 그것만으로는 버티기 힘들어요.","어떻게 별로였는데요? 그건 다른 얘기 같네요.","음. 그럼 정말 원하는 게 뭔지부터 찾아보죠."]', '["Give your reasons: what you enjoy and what you want.","Key words: mentoring, a say in decisions"]', '["이유를 말하세요. 무엇이 즐겁고 무엇을 원하는지.","핵심 단어: mentoring, a say in decisions"]', 'maya', 'It shows. Jun already told me how much you''ve helped him.', '눈에 보여요. 준이 벌써 당신이 얼마나 도와줬는지 말하더군요.'),
  ('dk_d3_one_on_one', 3, 'maya', 'She chooses her words carefully.', '그녀가 조심스럽게 말을 고릅니다.', 'To be candid, there''s one gap. You tend to take everything on yourself. A lead has to delegate.', '솔직히 말하면, 부족한 점이 하나 있어요. 뭐든 혼자 떠안는 경향이 있어요. 리드는 일을 맡길 줄 알아야 해요.', 'It stings a little, but she''s right. Take it well.', '조금 아프지만 맞는 말입니다. 좋게 받아들이세요.', '[{"all":["fair"]},{"all":["work on"]},{"all":["working on"]},{"any":["delegate","delegating"]}]', 'That''s fair. Delegating is something I need to work on.', '맞는 말이에요. 일을 맡기는 건 제가 노력해야 할 부분이에요.', '["That''s not really fair. Nobody else would do it right.","That''s only because we''re short-staffed, though.","Got it. From now on, I''ll just hand all of my work to Jun."]', '["그건 좀 억울해요. 다른 사람은 제대로 못 하잖아요.","그건 우리 팀 인원이 부족해서 그런 거잖아요.","알겠어요. 그럼 앞으로는 제 일을 전부 준한테 넘길게요."]', '["That''s exactly the habit I''m talking about.","Maybe. But leads delegate, whatever the team size.","Everything? To Jun? In his first week?"]', '["제가 말하는 게 바로 그 습관이에요.","그럴 수도요. 하지만 인원이 몇 명이든 리드는 일을 맡겨요.","전부요? 준한테요? 입사 첫 주에?"]', '["Do not argue. Agree, and name what you will improve.","Key words: that''s fair, work on"]', '["반박하지 말고, 동의한 뒤 무엇을 고칠지 말하세요.","핵심 단어: that''s fair, work on"]', 'maya', 'Knowing it is half the battle.', '아는 것만으로도 절반은 된 거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_one_on_one', 4, 'maya', 'Maya opens her notes.', '마야가 메모를 엽니다.', 'So what would help you get there?', '그럼 거기까지 가려면 뭐가 도움이 될까요?', 'Ask to run the upcoming gift card work yourself, as a challenge to grow into.', '곧 시작할 기프트 카드 작업을 직접 맡아 이끌고 싶다고, 성장할 기회로 삼겠다고 하세요.', '[{"all":["take the lead"]},{"all":["lead"],"any":["project","gift"]},{"any":["stretch"]},{"all":["run point"]}]', 'I''d like to take the lead on the gift card project. It would be a good stretch assignment.', '기프트 카드 프로젝트를 제가 이끌어 보고 싶어요. 좋은 도전 과제가 될 것 같아요.', '["I''d like to take the lead on the checkout API. It would be a good stretch assignment.","Honestly, a new title would help most. Can we start calling me tech lead now?","I''d like to do all of the gift card work by myself, start to finish, without anyone''s help."]', '["결제 API를 제가 이끌어 보고 싶어요. 좋은 도전 과제가 될 것 같아요.","솔직히 새 직함이 제일 도움이 될 거예요. 지금부터 테크 리드라고 불러 주면 안 돼요?","기프트 카드 작업을 처음부터 끝까지 누구 도움도 없이 저 혼자 다 해 보고 싶어요."]', '["That one''s already done and in review, isn''t it?","Titles come after the work, Derek.","Without help? Didn''t we just talk about delegating?"]', '["그건 이미 끝나서 리뷰 중이잖아요?","직함은 일을 해낸 다음에 따라와요, 데릭.","도움 없이요? 방금 일을 맡기는 얘기 했잖아요?"]', '["Ask for a concrete chance to practice.","Key words: take the lead, stretch assignment"]', '["연습할 구체적인 기회를 요청하세요.","핵심 단어: take the lead, stretch assignment"]', 'maya', 'I like it. Put together a one-page plan, and we''ll revisit this next month.', '좋아요. 한 장짜리 계획을 만들어 봐요. 다음 달에 다시 이야기하죠.'),
  ('dk_d3_one_on_one', 5, 'maya', 'She writes a note and looks at the clock. Standup is soon.', '그녀가 메모를 하고 시계를 봅니다. 곧 스탠드업입니다.', 'Anything else on your mind?', '다른 할 얘기 있어요?', 'Ask her what you''d need to show to earn a promotion.', '승진하려면 무엇을 보여 줘야 하는지 물어보세요.', '[{"all":["next level"]},{"all":["what would it take"]},{"any":["promotion","promoted"]}]', 'Just one thing. What would it take to get to the next level?', '하나만요. 다음 단계로 올라가려면 뭐가 필요할까요?', '["Just one thing. How much more would the tech lead role actually pay?","Nope, I think I''m all set. I''ll see you at standup.","Just one thing. Why didn''t I get promoted last year?"]', '["하나만요. 테크 리드가 되면 연봉이 실제로 얼마나 더 올라요?","아뇨, 다 된 것 같아요. 스탠드업에서 봬요.","하나만요. 작년엔 제가 왜 승진을 못 했죠?"]', '["We''ll get to comp later. Let''s focus on growth first.","Okay. You''re sure there''s nothing else?","Fair question, but let''s look forward, not back."]', '["보상은 나중에 얘기해요. 우선 성장에 집중하죠.","그래요. 정말 다른 건 없어요?","그럴 만한 질문이지만, 뒤 말고 앞을 봐요."]', '["Ask \\"What would it take to …?\\"","Key words: what would it take, next level"]', '["\\"What would it take to …?\\"로 물어보세요.","핵심 단어: what would it take, next level"]', 'maya', 'Lead one project end to end, and show me you can delegate. Let me know if you have any questions.', '프로젝트 하나를 처음부터 끝까지 이끌고, 일을 맡길 줄 안다는 걸 보여 줘요. 궁금한 게 있으면 말해 줘요.'),
  ('dk_d3_planning', 1, 'priya', 'The whole team is in the meeting room. Rain runs down the windows. Priya has the backlog on the screen.', '팀 전체가 회의실에 있습니다. 창문에 빗물이 흘러내립니다. 프리야가 화면에 백로그를 띄웠습니다.', 'Okay, sprint planning. First up: gift cards. Derek, how did the spike go?', '자, 스프린트 계획이에요. 첫 번째는 기프트 카드. 데릭, 사전 조사는 어땠어요?', 'Share what the spike showed: possible, but larger than expected at 8 points. Suggest splitting the work.', '사전 조사 결과를 공유하세요. 할 수는 있지만 생각보다 커서 8포인트입니다. 작업을 나누자고 하세요.', '[{"any":["eight","8","split"]},{"all":["break"],"any":["down","up","into"]},{"all":["bigger than"]}]', 'It''s doable, but it''s bigger than it looks. I''d say eight points, so let''s break it into two tickets.', '할 수는 있는데 보기보다 커요. 8포인트 정도니까 티켓 두 개로 나누죠.', '["It''s doable, but it''s bigger than it looks. I''d say three points, so it fits in one ticket.","Easy, actually. You were right, it''s basically a two-day job. No need to split it.","It was rough. I stayed at the office until midnight, and the legacy code is honestly a total nightmare."]', '["할 수는 있는데 보기보다 커요. 3포인트 정도라 티켓 하나면 돼요.","사실 쉬워요. 프리야 말이 맞았어요, 거의 이틀이면 돼요. 나눌 필요도 없어요.","힘들었어요. 자정까지 사무실에 남았는데, 레거시 코드가 솔직히 완전 악몽이에요."]', '["Three points? That''s a lot smaller than the week you warned me about.","Really? Yesterday you said a week.","Sorry to hear it. But what''s the estimate?"]', '["3포인트요? 일주일 걸린다고 했던 것보다 훨씬 작은데요.","정말요? 어제는 일주일이라면서요.","고생했네요. 그래서 추정치는요?"]', '["Give the result, the size, and a suggestion.","Key words: doable, eight points, break it into"]', '["결과와 크기, 제안을 말하세요.","핵심 단어: doable, eight points, break it into"]', 'priya', 'Two tickets. Works for me.', '티켓 두 개. 좋아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_planning', 2, 'priya', 'Priya drags a ticket to the top. Jun is sitting next to you, taking notes.', '프리야가 티켓 하나를 맨 위로 끌어 올립니다. 준이 옆에 앉아 메모를 하고 있습니다.', 'Next, the refund bug. I was thinking of giving it to Jun. Is that too much for his first week?', '다음은 환불 버그. 준한테 줄까 생각 중인데요. 첫 주에 너무 무리일까요?', 'Vouch for Jun, and offer to work alongside him if he runs into trouble.', '준을 믿는다고 말하고, 막히면 옆에서 같이 작업하겠다고 하세요.', '[{"all":["handle"]},{"any":["pair","pairing"]},{"all":["help him"]},{"all":["he is ready"]}]', 'I think he can handle it. I''ll pair with him if he gets stuck.', '해낼 수 있을 것 같아요. 막히면 제가 같이 붙어서 할게요.', '["Probably too much. Let''s give him something easier for now.","I think it''s too risky for him. I''ll just take the refund bug myself.","He can handle it alone. He won''t need any help from anyone."]', '["아마 무리일 거예요. 일단 더 쉬운 걸 주죠.","그 친구한텐 너무 위험해요. 환불 버그는 그냥 제가 맡을게요.","혼자서도 충분해요. 누구 도움도 필요 없을 거예요."]', '["Hm. Jun''s sitting right here, you know.","You? You''ve already got gift cards on your plate.","No help at all? It''s his first week, Derek."]', '["음. 준이 바로 옆에 있는데요.","데릭이요? 이미 기프트 카드도 맡고 있잖아요.","도움이 하나도 필요 없다고요? 첫 주예요, 데릭."]', '["Show trust in him, and offer a safety net.","Key words: handle it, pair with him"]', '["그를 믿는다는 걸 보이고, 안전망을 제안하세요.","핵심 단어: handle it, pair with him"]', 'jun', 'Thanks, Derek. I''ll do my best!', '고마워요, 데릭. 최선을 다할게요!'),
  ('dk_d3_planning', 3, 'priya', 'The sprint is full. Priya scrolls to one more item.', '스프린트가 꽉 찼습니다. 프리야가 항목 하나를 더 찾아 내려갑니다.', 'One more. Sales wants the export report in this sprint, too. Can we squeeze it in?', '하나 더요. 영업팀이 이번 스프린트에 내보내기 리포트도 원해요. 끼워 넣을 수 있을까요?', 'Say no: the sprint is full, and adding it would mean dropping something.', '안 된다고 하세요. 스프린트가 꽉 찼고, 그걸 넣으면 다른 걸 빼야 합니다.', '[{"all":["at capacity"]},{"all":["come out"]},{"all":["something else"]},{"all":["on our plate"]}]', 'I don''t think so. We''re at capacity. If that goes in, something else has to come out.', '안 될 것 같아요. 이미 여력이 꽉 찼어요. 그게 들어오면 다른 게 빠져야 해요.', '["Sure, we can probably squeeze it in if everyone puts in a little extra.","Sales always does this. Tell them to plan ahead for once in their lives.","I don''t think so. Jun''s pretty free this sprint, but the rest of us are already at capacity."]', '["네, 다들 조금씩 더 하면 아마 끼워 넣을 수 있을 거예요.","영업팀은 맨날 이래요. 제발 한 번이라도 미리 계획하라고 하세요.","안 될 것 같아요. 준은 이번에 꽤 여유가 있지만 나머지는 이미 꽉 찼어요."]', '["Extra hours again? That''s how we burn people out.","I''ll pass on the message, minus the attitude.","Jun''s free? We just gave him the refund bug."]', '["또 야근이요? 그러다 다들 지쳐요.","말은 전할게요. 그 말투는 빼고요.","준이 한가하다고요? 방금 환불 버그 줬잖아요."]', '["Say no with a reason and a choice.","Key words: at capacity, something else has to come out"]', '["이유와 선택지를 들어 거절하세요.","핵심 단어: at capacity, something else has to come out"]', 'priya', 'I was afraid you''d say that. Okay, it goes to the backlog.', '그렇게 말할 줄 알았어요. 알겠어요, 백로그로 보내죠.'),
  ('dk_d3_planning', 4, 'priya', 'Priya looks around the table.', '프리야가 테이블을 둘러봅니다.', 'So what can we commit to?', '그럼 우리 뭘 약속할 수 있죠?', 'Say what the team can promise this sprint, and what''s only a maybe.', '이번 스프린트에서 팀이 약속할 수 있는 것과, 되면 좋은 것을 나눠 말하세요.', '[{"any":["commit"]},{"all":["stretch goal"]},{"any":["stretch"]}]', 'Let''s commit to the refund bug and the first gift card ticket. The rest is a stretch goal.', '환불 버그랑 첫 번째 기프트 카드 티켓은 약속하죠. 나머지는 도전 목표로 하고요.', '["Let''s commit to both gift card tickets, the refund bug, and the export report.","Let''s commit to the refund bug and saved cards. Both gift card tickets can be a stretch goal.","I''d rather not commit to anything this time. Let''s just see how far we get."]', '["기프트 카드 티켓 두 개랑 환불 버그, 내보내기 리포트까지 다 약속하죠.","환불 버그랑 저장된 카드는 약속하죠. 기프트 카드 티켓 두 개는 도전 목표로 하고요.","이번엔 아무것도 약속 안 하는 게 좋겠어요. 어디까지 가나 보죠, 뭐."]', '["The export report? You just said we''re at capacity.","Saved cards? I thought we moved that to next sprint.","I can''t take \\"let''s see\\" to Greg, Derek."]', '["내보내기 리포트요? 방금 여력이 없다고 했잖아요.","저장된 카드요? 그건 다음 스프린트로 옮긴 줄 알았는데요.","그렉한테 ''두고 보자''라고 할 순 없어요, 데릭."]', '["Separate what is promised from what is a bonus.","Key words: commit to, stretch goal"]', '["약속하는 것과 덤인 것을 구분하세요.","핵심 단어: commit to, stretch goal"]', 'priya', 'Commit, plus a stretch. Let''s lock it in.', '약속한 것에 도전 목표 하나. 이걸로 확정해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_tacos', 1, 'jun', 'It is almost noon, and the rain has let up for a while. Jun is eating crackers at his desk, staring at his screen.', '거의 정오이고 비가 잠시 그쳤습니다. 준이 자리에서 크래커를 먹으며 화면을 들여다보고 있습니다.', 'Oh, hi, Derek. I was just going to work through lunch.', '아, 데릭. 점심은 그냥 일하면서 때우려고요.', 'Don''t let him eat crackers at his desk. Invite him along: a few of you are getting tacos from the truck.', '자리에서 크래커로 때우게 두지 마세요. 몇 명이서 타코 트럭에 가는데 같이 가자고 하세요.', '[{"any":["tacos","taco"]},{"all":["food truck"]},{"all":["join us"]},{"all":["come with"]}]', 'Come on, you need a break. A few of us are grabbing tacos from the food truck. Want to join us?', '에이, 좀 쉬어야죠. 몇 명이서 푸드트럭에 타코 사러 가는데, 같이 갈래요?', '["Good call. When you''re new, it''s smart to show everyone how hard you''re working.","Nope, you''re coming. Close the laptop. I''m not taking no for an answer, Jun.","Come on, you need a break. A few of us are grabbing pizza and wings at the Anchor. Want to join us?"]', '["잘 생각했어요. 신입 때는 다들 보는 앞에서 열심히 일하는 걸 보여 주는 게 좋아요.","안 돼요, 같이 가요. 노트북 덮어요. 거절은 안 받을 거예요, 준.","에이, 좀 쉬어야죠. 몇 명이서 앵커에 피자랑 윙 먹으러 가는데, 같이 갈래요?"]', '["Oh. Right. Then I''ll stay here.","Okay, okay! Let me at least save my work.","The Anchor? Isn''t that a bar? At noon?"]', '["아. 그렇죠. 그럼 여기 있을게요.","알았어요, 알았어요! 저장이라도 하게 해 줘요.","앵커요? 거기 술집 아니에요? 대낮에요?"]', '["Invite him with \\"Want to join us?\\"","Key words: tacos, food truck, join us"]', '["\\"Want to join us?\\"로 초대하세요.","핵심 단어: tacos, food truck, join us"]', 'jun', 'Tacos? Sure, I''d love to. Let me grab my wallet.', '타코요? 좋아요, 가고 싶어요. 지갑 가져올게요.'),
  ('dk_d3_tacos', 2, 'jun', 'You wait in line under the awning of the food truck. Jun studies the menu board.', '푸드트럭 차양 아래에서 줄을 서 있습니다. 준이 메뉴판을 유심히 봅니다.', 'I''ve never ordered from a food truck. What do you recommend?', '푸드트럭에서는 주문해 본 적이 없어요. 뭐가 맛있어요?', 'Suggest the fish tacos, and make it clear you''re paying.', '피시 타코를 추천하고, 당신이 계산할 거라고 분명히 하세요.', '[{"all":["my treat"]},{"all":["on me"]},{"any":["recommend"]},{"all":["go wrong"]},{"all":["fish tacos"]}]', 'You can''t go wrong with the fish tacos. And put your wallet away. It''s my treat.', '피시 타코는 실패가 없어요. 그리고 지갑은 넣어 둬요. 내가 살게요.', '["You can''t go wrong with the fish tacos. Oh, I forgot my wallet. Can you cover me?","You can''t go wrong with the beef burritos. And put your wallet away. It''s my treat.","The fish tacos are great here. Let''s just each pay for our own, though."]', '["피시 타코는 실패가 없어요. 아, 지갑을 두고 왔네. 대신 내 줄 수 있어요?","소고기 부리토는 실패가 없어요. 그리고 지갑은 넣어 둬요. 내가 살게요.","여기 피시 타코 맛있어요. 근데 계산은 각자 하죠."]', '["Oh! Sure, no problem. I''ve got it.","Burritos? The guy ahead of us said the tacos are the best.","Oh, sure. Of course."]', '["아! 네, 괜찮아요. 제가 낼게요.","부리토요? 앞사람은 타코가 제일 맛있다던데요.","아, 네. 물론이죠."]', '["Recommend a dish, then offer to pay.","Key words: can''t go wrong with, my treat"]', '["메뉴를 추천한 다음 계산하겠다고 하세요.","핵심 단어: can''t go wrong with, my treat"]', 'jun', 'Really? Thank you! The next one is on me.', '정말요? 감사합니다! 다음엔 제가 살게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d3_tacos', 3, 'jun', 'You eat at a picnic table that is still a little wet.', '아직 조금 젖은 피크닉 테이블에서 먹습니다.', 'Can I ask you something? At the diner, I never know how much to tip.', '뭐 하나 물어봐도 돼요? 다이너에서 팁을 얼마나 줘야 할지 항상 모르겠어요.', 'Tell him the norm at sit-down restaurants is 15 to 20 percent, and that at a truck like this it''s optional.', '앉아서 먹는 식당에서는 15~20퍼센트가 보통이고, 이런 트럭에서는 자유라고 알려 주세요.', '[{"all":["rule of thumb"]},{"any":["fifteen","15","twenty","20","percent"]},{"all":["sit down"]}]', 'Rule of thumb: fifteen to twenty percent at sit-down places. At a truck like this, it''s up to you.', '대략 앉아서 먹는 식당은 15에서 20퍼센트예요. 이런 트럭은 알아서 하면 돼요.', '["Rule of thumb: about ten percent at sit-down places like the diner. At a truck like this, it''s up to you.","Rule of thumb: fifteen to twenty percent everywhere, even at a truck like this one.","Honestly, tipping is optional everywhere. Nobody really expects it from you."]', '["대략 다이너 같은 앉아서 먹는 식당은 10퍼센트 정도예요. 이런 트럭은 알아서 하면 돼요.","대략 어디서나 15에서 20퍼센트예요. 이런 트럭에서도 마찬가지고요.","솔직히 팁은 어디서든 선택이에요. 아무도 준한테 기대 안 해요."]', '["Ten? I thought it was more than that here.","Even here? But we ordered at the window.","Really? I don''t think Rosa would agree with that."]', '["10퍼센트요? 여기선 그것보다 많은 줄 알았는데요.","여기서도요? 창구에서 주문했는데요.","정말요? 로사는 그렇게 생각 안 할 것 같은데요."]', '["Give a simple rule with numbers.","Key words: rule of thumb, fifteen to twenty percent"]', '["숫자가 들어간 간단한 기준을 알려 주세요.","핵심 단어: rule of thumb, fifteen to twenty percent"]', 'jun', 'Fifteen to twenty. Got it. I''ll remember that.', '15에서 20. 알겠어요. 기억해 둘게요.'),
  ('dk_d3_tacos', 4, 'jun', 'Jun finishes his second taco.', '준이 두 번째 타코를 다 먹습니다.', 'Do you have any plans for the weekend?', '주말에 무슨 계획 있어요?', 'Tell him you''re grilling for some friends at your place, if it doesn''t rain.', '비만 안 오면 집에서 친구들과 바비큐를 한다고 하세요.', '[{"any":["barbecue","bbq","cookout","grill","grilling"]},{"all":["friends over"]}]', 'I''m having a few friends over for a barbecue, as long as the weather holds.', '날씨만 괜찮으면 친구 몇 명 불러서 바비큐 할 거예요.', '["I''m going to a barbecue at a friend''s place this weekend, as long as the weather holds.","Just work, probably. I''ll be catching up on tickets all weekend.","Not really your business, but I''ll be around. Why do you ask?"]', '["날씨만 괜찮으면 이번 주말에 친구네 집 바비큐에 갈 거예요.","아마 일하겠죠. 주말 내내 밀린 티켓 처리할 거예요.","알 필요는 없지만, 근처에 있을 거예요. 왜요?"]', '["Oh, whose place? Someone from work?","All weekend? Derek, you just told me to take a break.","Oh, sorry. I was just making conversation."]', '["아, 누구네요? 회사 사람이에요?","주말 내내요? 데릭, 방금 저한테 쉬라고 하셨잖아요.","아, 죄송해요. 그냥 얘기나 하려던 거였어요."]', '["\\"Have people over\\" = invite them to your home.","Key words: friends over, barbecue"]', '["have people over는 사람들을 집에 초대한다는 뜻입니다.","핵심 단어: friends over, barbecue"]', 'jun', 'That sounds fun. I hope the rain is gone by then.', '재미있겠네요. 그때까지 비가 그쳤으면 좋겠어요.'),
  ('dk_d3_tacos', 5, 'jun', 'You walk back to the office. A few drops start to fall again.', '사무실로 걸어 돌아갑니다. 빗방울이 다시 떨어지기 시작합니다.', 'By the way, thank you for this week. I was really nervous on Monday.', '그런데 이번 주에 고마웠어요. 월요일엔 정말 긴장했거든요.', 'Encourage him: tell him how well he''s been doing.', '격려해 주세요. 그가 얼마나 잘하고 있는지 말해 주세요.', '[{"all":["doing great"]},{"all":["doing well"]},{"all":["doing fine"]},{"all":["picking"],"any":["up"]},{"all":["fast learner"]}]', 'You''re doing great. You''re picking things up faster than I did.', '아주 잘하고 있어요. 나보다 훨씬 빨리 배우고 있어요.', '["No problem. You''re doing okay, but you still ask a lot of questions.","No problem. Honestly, you''d be lost without me, so you''re welcome.","Yeah, I could tell. You looked pretty scared on Monday, to be honest."]', '["천만에요. 잘하고는 있는데, 아직 질문이 좀 많아요.","천만에요. 솔직히 나 없었으면 헤맸을 테니까, 고마워할 만하죠.","네, 티 났어요. 솔직히 월요일엔 꽤 겁먹은 얼굴이었어요."]', '["Oh... sorry. I''ll try to ask fewer.","Ha. Yeah, probably. Thanks, I guess.","Was it that obvious? That''s embarrassing."]', '["아... 죄송해요. 덜 물어보도록 할게요.","하. 네, 그렇겠죠. 고마워요, 뭐.","그렇게 티 났어요? 창피하네요."]', '["Encourage him with a specific compliment.","Key words: doing great, picking things up"]', '["구체적인 칭찬으로 격려하세요.","핵심 단어: doing great, picking things up"]', 'jun', 'That means a lot. Thanks for lunch, Derek!', '큰 힘이 돼요. 점심 잘 먹었어요, 데릭!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d4_incident', 1, 'sam', 'A gray Thursday morning. Your phone buzzes with an alert from production. You are on call this week, so you head straight to Sam''s room.', '흐린 목요일 아침입니다. 운영 환경 경보로 전화기가 울립니다. 이번 주 온콜 담당이라 곧장 샘의 방으로 갑니다.', 'Hey, Derek. Your phone''s going off too, huh? What are you seeing?', '어, 데릭. 당신 전화도 울리네요? 뭐가 보여요?', 'Describe the alert: more checkout errors than normal since about 9 a.m.', '경보 내용을 말하세요. 9시쯤부터 결제 오류가 평소보다 많습니다.', '[{"all":["error rates"]},{"all":["error rate"]},{"any":["elevated","errors","failing","timeouts"]}]', 'We''re seeing elevated error rates on checkout. It started around nine.', '결제 쪽 오류율이 올라갔어요. 아홉 시쯤부터 시작됐어요.', '["We''re seeing elevated error rates on login. It started around nine.","Somebody must have pushed bad code. Was it Jun? He''s new here.","Everything''s broken! I have no idea what''s going on. It''s a total disaster."]', '["로그인 쪽 오류율이 올라갔어요. 아홉 시쯤부터 시작됐어요.","누가 잘못된 코드를 올렸나 봐요. 준인가? 신입이잖아요.","전부 다 망가졌어요! 무슨 일인지 하나도 모르겠어요, 완전 난리예요."]', '["Login? My dashboard says checkout.","Whoa, let''s not point fingers before we even look.","Whoa, deep breath. What exactly is failing?"]', '["로그인이요? 제 대시보드엔 결제라고 나오는데요.","워, 보기도 전에 누구 탓하지 말죠.","워, 심호흡해요. 정확히 뭐가 실패해요?"]', '["Report what you see and since when.","Key words: elevated error rates, started around"]', '["무엇이 보이는지, 언제부터인지 보고하세요.","핵심 단어: elevated error rates, started around"]', 'sam', 'Yeah, my dashboard''s all red. Have you tried restarting it? Kidding. Mostly.', '네, 제 대시보드도 온통 빨개요. 재시작은 해 봤어요? 농담이에요. 반쯤은요.'),
  ('dk_d4_incident', 2, 'sam', 'Sam pulls up the logs on his middle monitor.', '샘이 가운데 모니터에 로그를 띄웁니다.', 'Did anything go out this morning?', '오늘 아침에 뭐 나간 거 있어요?', 'Nobody has shipped code since Tuesday. Say what that tells you, and ask about his side.', '화요일 이후로 코드를 배포한 사람이 없습니다. 그게 무슨 뜻인지 말하고, 그쪽 사정을 물어보세요.', '[{"any":["deploy","deploys","deployed","deployment"]},{"all":["rule out"]},{"all":["on your end"]},{"all":["your side"]}]', 'No deploys since Tuesday, so we can rule out a code change. Did anything change on your end?', '화요일 이후로 배포가 없었으니까 코드 변경은 아니에요. 그쪽에서 바뀐 거 있어요?', '["Yes, we deployed at eight thirty, so it''s probably our code. Should we roll back?","No deploys since Tuesday, so it must be on your end. What did your team break?","Not sure, I haven''t really checked yet. Can you just restart all the servers and see what happens?"]', '["네, 8시 반에 배포했으니까 우리 코드 문제일 거예요. 롤백할까요?","화요일 이후로 배포가 없었으니 그쪽 문제겠네요. 그쪽 팀이 뭘 망가뜨렸어요?","모르겠어요, 아직 확인을 못 해 봤어요. 그냥 서버 전부 재시작해 보면 안 돼요?"]', '["Eight thirty? The deploy log says Tuesday was the last one.","Whoa. Let me check before you blame my team.","I was kidding about restarting, Derek."]', '["8시 반이요? 배포 기록엔 화요일이 마지막인데요.","워. 우리 팀 탓하기 전에 확인부터 할게요.","재시작은 농담이었어요, 데릭."]', '["Rule out one cause, then ask about his side.","Key words: no deploys, rule out, on your end"]', '["원인 하나를 배제하고, 그쪽 상황을 물어보세요.","핵심 단어: no deploys, rule out, on your end"]', 'sam', 'Let me look. Oh. The certificate on the payment gateway expired at 8:57.', '어디 봐요. 아. 결제 게이트웨이 인증서가 8시 57분에 만료됐네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d4_incident', 3, 'sam', 'Customers cannot pay right now. Every minute counts.', '지금 고객들이 결제를 못 하고 있습니다. 1분 1초가 급합니다.', 'I can renew it, but it takes about twenty minutes to roll out. What do you want to do in the meantime?', '갱신할 수는 있는데, 적용되는 데 20분쯤 걸려요. 그동안 어떻게 할까요?', 'Customers can''t pay until the renewal is out. Ask Sam for a quick fix in the meantime: route payments to the backup gateway.', '갱신이 끝날 때까지 고객이 결제를 못 합니다. 그동안 결제를 백업 게이트웨이로 돌려 달라고 샘에게 부탁하세요.', '[{"any":["workaround","backup","failover"]},{"all":["stop the bleeding"]},{"all":["fail over"]}]', 'Let''s stop the bleeding first. As a workaround, can you switch traffic to the backup gateway?', '우선 피해부터 막죠. 임시방편으로 트래픽을 백업 게이트웨이로 돌려 줄 수 있어요?', '["Honestly, I''d just wait it out. Twenty minutes isn''t that long, and customers can try again later.","Let''s stop the bleeding first. Can you roll back Tuesday''s deploy while you renew it?","Let''s get Maya and the whole team in here first and talk through all our options."]', '["솔직히 그냥 기다리죠. 20분이면 그렇게 길지 않고, 고객은 나중에 다시 하면 돼요.","우선 피해부터 막죠. 갱신하는 동안 화요일 배포를 롤백해 줄 수 있어요?","먼저 마야랑 팀 전체를 불러서 어떻게 할지 같이 얘기해 보죠."]', '["Twenty minutes of no sales? Maya won''t love that.","Roll back? You just said it''s not a code change.","A meeting? Customers can''t pay right now, man."]', '["20분 동안 매출이 0이라고요? 마야가 싫어할걸요.","롤백이요? 방금 코드 변경은 아니라면서요.","회의요? 지금 고객들이 결제를 못 하고 있다고요."]', '["Reduce the damage now; the real fix can follow.","Key words: stop the bleeding, workaround, backup"]', '["지금은 피해를 줄이고, 제대로 된 수정은 그다음입니다.","핵심 단어: stop the bleeding, workaround, backup"]', 'sam', 'Switching now. Done. Error rates are dropping.', '지금 돌려요. 됐어요. 오류율이 떨어지고 있어요.'),
  ('dk_d4_incident', 4, 'maya', 'Maya appears in the doorway with her laptop under her arm.', '마야가 노트북을 옆구리에 끼고 문 앞에 나타납니다.', 'I just saw the alert. What''s the status? Give me the short version.', '방금 경보 봤어요. 상황이 어때요? 짧게 말해 줘요.', 'Give Maya a quick status: about forty minutes of failed payments, under control now, and you''re still watching it.', '마야에게 간단히 보고하세요. 40분쯤 결제가 실패했고, 지금은 잡혔고, 계속 지켜보는 중입니다.', '[{"any":["mitigated","mitigation"]},{"any":["monitoring","monitor"]},{"all":["under control"]},{"any":["recovered","recovering"]}]', 'Short version: checkout was failing for about forty minutes. It''s mitigated now, and we''re monitoring it.', '짧게 말하면, 결제가 40분쯤 실패했어요. 지금은 완화됐고 모니터링 중이에요.', '["Short version: checkout was failing for about four minutes. It''s mitigated now, and we''re monitoring it closely.","Short version: it''s completely fixed. Nothing to worry about, so we can all move on now.","So around nine my phone buzzed, and I came down here, and then Sam pulled up the logs, and after that..."]', '["짧게 말하면, 결제가 4분쯤 실패했어요. 지금은 완화됐고 계속 꼼꼼히 모니터링 중이에요.","짧게 말하면, 완전히 해결됐어요. 걱정할 거 없으니 이제 다들 넘어가면 돼요.","그러니까 아홉 시쯤 전화가 울려서 내려왔는데, 샘이 로그를 띄웠고, 그다음에..."]', '["Four minutes? The alert went off way before that.","Completely? Sam still looks pretty busy over there.","Derek. The short version, please."]', '["4분이요? 경보는 그보다 훨씬 전에 울렸는데요.","완전히요? 샘은 아직 꽤 바빠 보이는데요.","데릭. 짧게요, 부탁해요."]', '["Impact first, then the current state.","Key words: mitigated, monitoring"]', '["영향을 먼저, 그다음 현재 상태를 말하세요.","핵심 단어: mitigated, monitoring"]', 'maya', 'Okay. Good.', '알겠어요. 다행이네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d4_incident', 5, 'maya', 'Maya opens a new page in her notes.', '마야가 메모장의 새 페이지를 엽니다.', 'Do we know the root cause?', '근본 원인은 알아요?', 'Explain what actually broke, based on what Sam found, and what he''s doing about it.', '샘이 찾아낸 내용으로 실제 원인을 설명하고, 그가 어떻게 처리하고 있는지 말하세요.', '[{"any":["certificate","cert","expired"]}]', 'The root cause was an expired certificate on the payment gateway. Sam is renewing it now.', '근본 원인은 결제 게이트웨이의 인증서 만료였어요. 지금 샘이 갱신하고 있어요.', '["The root cause was a bad deploy on the payment gateway. Sam is rolling it back now.","Sam''s team let the certificate on the payment gateway expire. That one''s on them.","The root cause was an expired certificate on the payment gateway. It renewed itself already."]', '["근본 원인은 결제 게이트웨이의 잘못된 배포였어요. 지금 샘이 롤백하고 있어요.","샘 팀이 결제 게이트웨이 인증서를 만료되게 놔뒀어요. 그건 그쪽 책임이에요.","근본 원인은 결제 게이트웨이의 인증서 만료였어요. 벌써 자동으로 갱신됐어요."]', '["A deploy? Didn''t you say nothing went out since Tuesday?","Let''s keep this blameless, Derek. We fix systems, not people.","Already? Then why is Sam still typing?"]', '["배포요? 화요일 이후엔 나간 게 없다면서요?","누구 탓은 하지 말죠, 데릭. 고칠 건 사람이 아니라 시스템이에요.","벌써요? 그럼 샘은 왜 아직 뭘 치고 있어요?"]', '["Name the cause and who is fixing it.","Key words: root cause, expired certificate"]', '["원인과 누가 고치고 있는지 말하세요.","핵심 단어: root cause, expired certificate"]', 'sam', 'Ten more minutes and the new one is live.', '10분만 더 있으면 새 인증서가 적용돼요.'),
  ('dk_d4_incident', 6, 'maya', 'She looks from Sam to you.', '그녀가 샘을 보다가 당신을 봅니다.', 'Summit Retail is going to ask about this. What are the next steps?', '서밋 리테일이 이 건에 대해 물어볼 거예요. 다음 단계는 뭐예요?', 'Lay out the follow-up: a written report on what happened by tomorrow, a warning before certificates run out, and regular updates.', '후속 조치를 말하세요. 내일까지 경위 보고서, 인증서가 만료되기 전에 울리는 경보, 그리고 꾸준한 상황 공유.', '[{"any":["postmortem","alert","reminder"]},{"all":["post mortem"]},{"all":["posted"]},{"all":["write up"]}]', 'I''ll write up a postmortem by tomorrow and add an alert for expiring certificates. I''ll keep you posted.', '내일까지 사후 분석 보고서를 쓰고, 인증서 만료 경보를 추가할게요. 계속 상황 공유할게요.', '["I''ll write up a postmortem by next month and add an alert for expiring certificates. I''ll keep you posted.","Honestly, I''d rather not tell Summit Retail anything at all. It was only forty minutes.","I''ll promise Greg it will never happen again, and we''ll give them a free month of service."]', '["다음 달까지 사후 분석 보고서를 쓰고, 인증서 만료 경보를 추가할게요. 계속 상황 공유할게요.","솔직히 서밋 리테일한텐 아무 말 안 하는 게 좋겠어요. 40분밖에 안 됐잖아요.","그렉한테 다시는 이런 일 없다고 약속하고, 한 달 서비스를 무료로 해 줄게요."]', '["Next month? They''ll want answers this week.","We don''t hide incidents from clients. Not here.","Whoa. A free month isn''t your call to make."]', '["다음 달이요? 그쪽은 이번 주에 답을 원할 거예요.","우리는 고객한테 장애를 숨기지 않아요. 여기선요.","워. 한 달 무료는 데릭이 정할 일이 아니에요."]', '["Say what you will do, by when, and promise updates.","Key words: postmortem, alert, keep you posted"]', '["무엇을 언제까지 할지 말하고, 소식을 전하겠다고 약속하세요.","핵심 단어: postmortem, alert, keep you posted"]', 'maya', 'Perfect. Nicely handled, both of you.', '완벽해요. 두 사람 다 잘 처리했어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_demo', 1, 'priya', 'Friday. The team and a few people from sales are in the meeting room. Jun is holding his laptop tightly.', '금요일입니다. 회의실에 팀원들과 영업팀 몇 명이 있습니다. 준이 노트북을 꼭 쥐고 있습니다.', 'Okay, demo time! Derek, do you want to show us the card payment fix?', '자, 데모 시간이에요! 데릭, 카드 결제 수정 보여 줄래요?', 'Jun did most of the work on this. Make sure he gets the spotlight.', '이 작업은 준이 대부분 했습니다. 그가 주목받게 해 주세요.', '[{"all":["heavy lifting"]},{"all":["hand it over"]},{"all":["hand it off"]},{"any":["credit"]},{"all":["let jun"]}]', 'Actually, Jun did the heavy lifting on that one, so I''ll hand it over to him.', '사실 그건 준이 거의 다 했어요. 그래서 준한테 넘길게요.', '["Sure. It was a tough one, but I got it working in the end. Let me share my screen.","Jun can show it. It''s a small fix, so even a new guy can demo it.","Actually, Sam did the heavy lifting on that one, so I''ll hand it over to him."]', '["네. 꽤 까다로웠는데 결국 제가 돌아가게 만들었어요. 화면 공유할게요.","준이 보여 주면 돼요. 작은 수정이라 신입도 데모할 수 있어요.","사실 그건 샘이 거의 다 했어요. 그래서 샘한테 넘길게요."]', '["Oh. I thought Jun wrote most of it?","Okay... maybe give him a little more credit than that.","Sam? Sam''s in IT. Jun built this, didn''t he?"]', '["아. 준이 거의 다 짠 줄 알았는데요?","음... 그것보단 좀 더 인정해 줘도 될 텐데요.","샘이요? 샘은 IT잖아요. 이건 준이 만든 거 아니에요?"]', '["Give the credit to the person who did the work.","Key words: heavy lifting, hand it over"]', '["일을 한 사람에게 공을 돌리세요.","핵심 단어: heavy lifting, hand it over"]', 'priya', 'Love it. Jun, you''re up first!', '좋아요. 준, 첫 순서예요!'),
  ('dk_d5_demo', 2, 'priya', 'Jun finishes his demo, and people clap. Someone from sales raises a hand.', '준이 데모를 마치자 사람들이 박수를 칩니다. 영업팀의 누군가가 손을 듭니다.', 'A question from sales: how many failed payments will this save us per month? Derek?', '영업팀 질문이에요. 이걸로 한 달에 실패하는 결제가 몇 건이나 줄어요? 데릭?', 'You don''t know the figure right now. Be honest, and promise an answer on Monday.', '그 수치는 지금 모릅니다. 솔직하게 말하고 월요일에 답을 주겠다고 약속하세요.', '[{"all":["top of my head"]},{"all":["get back to"]},{"all":["find out"]},{"all":["look into"]}]', 'I don''t have that number off the top of my head. Let me get back to you by Monday.', '그 숫자는 지금 바로는 모르겠어요. 월요일까지 알려 드릴게요.', '["Probably around a thousand a month, give or take. Don''t quote me on that, though.","I don''t have that number off the top of my head. Let me get back to you next month.","That''s more of a question for sales, isn''t it? We just write the code."]', '["아마 한 달에 천 건 정도일 거예요. 그렇다고 이 숫자를 인용하진 마세요.","그 숫자는 지금 바로는 모르겠어요. 다음 달까지 알려 드릴게요.","그건 영업팀이 알아야 할 질문 아니에요? 우리는 코드만 짜는데요."]', '["Hmm, sales will quote you on that. Let''s get the real number.","Next month is a long time. Can we do sooner?","Well, they''re asking you, Derek."]', '["음, 영업팀은 그대로 인용할 거예요. 진짜 숫자를 구하죠.","다음 달은 너무 늦어요. 좀 더 빨리 안 될까요?","음, 데릭한테 묻는 건데요."]', '["Do not guess. Promise an answer and a date.","Key words: off the top of my head, get back to you"]', '["짐작하지 말고, 답과 날짜를 약속하세요.","핵심 단어: off the top of my head, get back to you"]', 'priya', 'Fair enough. I''ll note it as an action item.', '그럴 수 있죠. 할 일 목록에 적어 둘게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_demo', 3, 'priya', 'Priya looks at the agenda.', '프리야가 안건을 봅니다.', 'Your turn. Anything to show for gift cards?', '당신 차례예요. 기프트 카드는 보여 줄 거 있어요?', 'Nothing to demo yet. Give a progress report: one of the two tickets is finished, the other is due next week.', '아직 보여 줄 건 없습니다. 진행 상황을 보고하세요. 티켓 두 개 중 하나는 끝났고, 나머지는 다음 주 예정입니다.', '[{"all":["work in progress"]},{"all":["in progress"]},{"all":["on track"]}]', 'It''s still a work in progress. The first ticket is done, and the second is on track for next week.', '아직 진행 중이에요. 첫 번째 티켓은 끝났고, 두 번째는 다음 주 일정대로 가고 있어요.', '["It''s all done, actually. Both tickets are finished and tested, so we can ship it to Greg''s team today.","It''s still a work in progress. Neither ticket is done yet, but we should be fine.","Not really. The incident ate my whole week, so don''t blame me if it''s late."]', '["사실 다 끝났어요. 티켓 두 개 다 끝나고 테스트도 마쳐서 오늘 그렉네 팀에 내보낼 수 있어요.","아직 진행 중이에요. 티켓은 하나도 안 끝났지만 괜찮을 거예요.","별로요. 장애 때문에 이번 주가 통째로 날아갔으니 늦어도 제 탓 하지 마세요."]', '["Both? I thought the second one was planned for next week.","Neither? I thought the first one was closed.","Nobody''s blaming you. Just tell us where it stands."]', '["둘 다요? 두 번째는 다음 주 예정인 줄 알았는데요.","하나도요? 첫 번째는 끝난 줄 알았는데요.","아무도 탓 안 해요. 어디까지 됐는지만 말해 줘요."]', '["Say what is done and what is coming.","Key words: work in progress, on track"]', '["끝난 것과 앞으로 할 것을 말하세요.","핵심 단어: work in progress, on track"]', 'priya', 'Good enough for me. Let''s switch to the retro.', '그 정도면 충분해요. 회고로 넘어가요.'),
  ('dk_d5_demo', 4, 'priya', 'Priya draws two columns on the whiteboard.', '프리야가 화이트보드에 두 칸을 그립니다.', 'What went well this sprint?', '이번 스프린트에서 잘된 건 뭐예요?', 'Recognize two people: Sam for how he handled the outage, and Jun for how quickly he got up to speed.', '두 사람을 칭찬하세요. 장애 때 샘의 대처, 그리고 준이 얼마나 빨리 적응했는지.', '[{"all":["shout out"]},{"any":["shoutout","kudos","incident"]},{"all":["ramped up"]}]', 'Shout-out to Sam for the quick fix during the incident. And Jun ramped up really fast.', '장애 때 빠르게 고쳐 준 샘한테 박수를. 그리고 준이 정말 빨리 적응했어요.', '["Honestly, I handled the incident pretty well, and I carried most of the sprint.","Shout-out to Jun for the quick fix during the incident. And Sam ramped up really fast.","Not much, honestly. We had an outage, and the gift cards still aren''t done."]', '["솔직히 장애는 제가 꽤 잘 처리했고, 스프린트도 거의 제가 끌고 갔죠.","장애 때 빠르게 고쳐 준 준한테 박수를. 그리고 샘이 정말 빨리 적응했어요.","솔직히 별로 없어요. 장애도 났고 기프트 카드도 아직 안 끝났잖아요."]', '["Okay... anyone else you''d like to thank?","Wait, wasn''t it the other way around?","That''s the next column, Derek. What went well?"]', '["음... 다른 고마운 사람은 없어요?","잠깐, 반대 아니에요?","그건 다음 칸이에요, 데릭. 잘된 건요?"]', '["Praise people by name for specific things.","Key words: shout-out to, ramped up"]', '["이름을 들어 구체적인 일을 칭찬하세요.","핵심 단어: shout-out to, ramped up"]', 'priya', 'Agreed on both. Kudos, Sam and Jun!', '둘 다 동의해요. 샘, 준, 잘했어요!'),
  ('dk_d5_demo', 5, 'priya', 'She points at the second column.', '그녀가 두 번째 칸을 가리킵니다.', 'And what could we do better?', '그럼 더 잘할 수 있는 건 뭐예요?', 'Name the problem: plans kept shifting during the sprint. Propose freezing what''s in once it begins.', '문제를 짚으세요. 스프린트 도중에 계획이 자꾸 바뀌었습니다. 시작하면 더는 바꾸지 말자고 제안하세요.', '[{"all":["mid sprint"]},{"any":["scope","requirements"]},{"all":["going forward"]}]', 'Too much changed mid-sprint. Going forward, let''s lock the scope once the sprint starts.', '스프린트 도중에 너무 많이 바뀌었어요. 앞으로는 스프린트가 시작되면 범위를 고정하죠.', '["You keep adding work mid-sprint, Priya. Please stop doing that to the team.","Too much changed mid-sprint. Going forward, let''s skip formal planning and just go with the flow.","Honestly, nothing. Everything went perfectly this sprint, from start to finish."]', '["프리야가 스프린트 도중에 자꾸 일을 추가하잖아요. 팀한테 제발 그러지 마세요.","스프린트 도중에 너무 많이 바뀌었어요. 앞으로는 정식 계획 없이 그냥 흐름대로 가죠.","솔직히 없어요. 이번 스프린트는 처음부터 끝까지 완벽했어요."]', '["Ouch. That felt a little personal.","Skip planning? I think that would make it worse.","Perfectly? We had an outage on Thursday."]', '["아야. 좀 저 들으라고 하는 말 같네요.","계획을 건너뛰자고요? 더 나빠질 것 같은데요.","완벽했다고요? 목요일에 장애가 났잖아요."]', '["Name the problem, then suggest a rule for the future.","Key words: mid-sprint, going forward, scope"]', '["문제를 말한 뒤 앞으로의 규칙을 제안하세요.","핵심 단어: mid-sprint, going forward, scope"]', 'priya', 'Ouch, but fair. I''ll push back on late requests myself.', '아프지만 맞는 말이에요. 늦게 들어오는 요청은 제가 막을게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_happy_hour', 1, 'tom', 'Friday afternoon. Jun has already told you he is too tired to come tonight. You stop at the front desk on your way out.', '금요일 오후입니다. 준은 너무 피곤해서 오늘은 못 가겠다고 이미 말했습니다. 나가는 길에 프런트 데스크에 들릅니다.', 'Happy Friday, Derek! Heading out already?', '즐거운 금요일이에요, 데릭! 벌써 퇴근해요?', 'Tell Tom about the after-work drinks at the Anchor, and invite him along.', '퇴근 후 앵커에서 한잔하는 자리를 알려 주고 톰을 초대하세요.', '[{"all":["happy hour"]},{"all":["you in"]},{"all":["join us"]},{"any":["anchor"]}]', 'Almost. A bunch of us are going to happy hour at the Anchor. Are you in?', '거의요. 몇 명이서 앵커에 해피아워 가는데, 같이 갈래요?', '["Almost. A bunch of us are going to happy hour at the Sunny Side. Are you in?","Pretty much. Just dropping off my badge. Have a good weekend, Tom!","Almost. We''re going to the Anchor, and you''re coming whether you like it or not."]', '["거의요. 몇 명이서 서니 사이드에 해피아워 가는데, 같이 갈래요?","그런 셈이에요. 출입증만 놓고 가려고요. 주말 잘 보내요, 톰!","거의요. 앵커에 가는데, 톰도 싫든 좋든 같이 가는 거예요."]', '["The diner? Since when does Rosa serve beer?","You too! Doing anything fun tonight?","Whoa, easy. Ask me nicely and I might say yes."]', '["그 다이너요? 로사네가 언제부터 맥주를 팔았어요?","데릭도요! 오늘 밤에 뭐 재밌는 거 해요?","워, 진정해요. 좋게 물어보면 갈 수도 있죠."]', '["Say where the group is going and ask \\"Are you in?\\"","Key words: happy hour, are you in"]', '["어디로 가는지 말하고 \\"Are you in?\\"으로 물어보세요.","핵심 단어: happy hour, are you in"]', 'tom', 'The Anchor? With the patio? Count me in.', '앵커요? 야외 자리 있는 데? 저도 갈게요.'),
  ('dk_d5_happy_hour', 2, 'tom', 'Tom checks the clock above the elevators.', '톰이 엘리베이터 위의 시계를 봅니다.', 'What time are you all heading over?', '다들 몇 시에 가요?', 'Give the time, 5:30, and let him know you''re buying the first drinks.', '시간은 5시 반이라고 알려 주고, 처음 마실 건 당신이 산다고 하세요.', '[{"all":["five thirty"]},{"all":["5 30"]},{"all":["on me"]},{"all":["first round"]}]', 'Around five thirty. And the first round''s on me.', '다섯 시 반쯤이요. 그리고 첫 잔은 제가 살게요.', '["Around six thirty. And the first round''s on me.","Around five thirty. Everyone pays for their own, though.","Right now, actually. Can you leave the desk early?"]', '["여섯 시 반쯤이요. 그리고 첫 잔은 제가 살게요.","다섯 시 반쯤이요. 근데 계산은 각자 해요.","지금 바로요. 데스크 일찍 비우고 나올 수 있어요?"]', '["Six thirty? That''s late. The patio fills up by then.","Fair enough. I''ll bring my wallet.","Leave early? Somebody has to lock up, Derek."]', '["여섯 시 반이요? 늦네요. 그때면 야외 자리 다 차요.","그러죠. 지갑 챙길게요.","일찍 나가라고요? 누군가는 문단속해야죠, 데릭."]', '["Give the time, then offer to pay for the first drinks.","Key words: five thirty, first round''s on me"]', '["시간을 말하고, 첫 잔을 사겠다고 하세요.","핵심 단어: five thirty, first round''s on me"]', 'tom', 'Now you''re talking!', '그거 좋네요!'),
  ('dk_d5_happy_hour', 3, 'tom', 'He grins.', '그가 활짝 웃습니다.', 'So what''s the occasion?', '그래서 무슨 날이에요?', 'Explain why you''re celebrating: the outage you got through, and the new guy''s first week.', '무엇을 축하하는지 설명하세요. 장애를 넘긴 것, 그리고 신입의 첫 주요.', '[{"all":["first week"]},{"any":["incident","survived","celebrate","celebrating"]}]', 'We survived an incident, and Jun made it through his first week. That calls for a drink.', '장애를 무사히 넘겼고, 준이 첫 주를 잘 버텼거든요. 한잔할 만하죠.', '["We survived an incident, and Jun made it through his first month. That calls for a drink.","Checkout was down for forty minutes and Summit Retail is furious. Long story.","No occasion, really. It''s just Friday, and I need a drink after this week."]', '["장애를 무사히 넘겼고, 준이 첫 달을 잘 버텼거든요. 한잔할 만하죠.","결제가 40분 동안 먹통이었고 서밋 리테일은 엄청 화났어요. 얘기하면 길어요.","딱히 이유는 없어요. 그냥 금요일이고, 이번 주는 한잔해야겠어요."]', '["His first month? He started on Monday, didn''t he?","Yikes. Maybe don''t say that too loud in the lobby.","Ha, fair. Rough week?"]', '["첫 달이요? 월요일에 왔잖아요?","이런. 로비에서 그렇게 크게 말하진 마요.","하, 그럴 만하네요. 힘든 한 주였어요?"]', '["Give the reasons to celebrate.","Key words: survived, first week, calls for"]', '["축하할 이유를 말하세요.","핵심 단어: survived, first week, calls for"]', 'tom', 'I''ll drink to that.', '그건 건배할 만하네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d5_happy_hour', 4, 'tom', 'Tom looks toward the elevators.', '톰이 엘리베이터 쪽을 봅니다.', 'Is Jun coming along?', '준도 같이 가요?', 'Jun is skipping tonight because he''s exhausted, but he wants to join next time. Explain.', '준은 너무 지쳐서 오늘은 빠지지만 다음엔 오고 싶어 합니다. 설명하세요.', '[{"all":["rain check"]},{"all":["next time"]},{"all":["wiped out"]}]', 'He''s taking a rain check. He''s pretty wiped out, but he says he''ll come next time.', '다음으로 미룬대요. 꽤 녹초가 됐는데, 다음번엔 오겠대요.', '["Yeah, he''s meeting us there around six. He''s just finishing up a ticket.","Nah, he bailed on us. Kind of antisocial, if you ask me. Maybe he''s just not a bar guy.","No, he doesn''t really drink, so I didn''t even bother inviting him."]', '["네, 여섯 시쯤 거기서 만나기로 했어요. 티켓 하나만 마무리하고요.","아뇨, 빠졌어요. 좀 비사교적이에요. 술자리 체질이 아닌가 봐요.","아뇨, 준은 술을 별로 안 마셔서 아예 안 불렀어요."]', '["Really? He just walked past me with his bag on.","Come on, the kid''s had a long week.","You didn''t even ask him? That''s cold, Derek."]', '["그래요? 방금 가방 메고 제 앞을 지나갔는데요.","에이, 그 친구 한 주가 길었잖아요.","물어보지도 않았어요? 좀 차갑네요, 데릭."]', '["\\"Take a rain check\\" = say no now, yes another time.","Key words: rain check, next time"]', '["take a rain check는 이번엔 못 가지만 다음에 가겠다는 뜻입니다.","핵심 단어: rain check, next time"]', 'tom', 'Poor guy. The first week will do that to you.', '안됐네요. 첫 주는 원래 그래요.'),
  ('dk_d5_happy_hour', 5, 'tom', 'Tom starts to tidy up the front desk.', '톰이 프런트 데스크를 정리하기 시작합니다.', 'Mind if I bring Linda? She said she was free tonight.', '린다 데려가면 곤란할까요? 오늘 밤 시간 된다던데.', 'You''d love to have Linda there, too. Say so, and promise them seats.', '린다도 오면 좋겠습니다. 그렇게 말하고, 두 사람 자리를 맡아 두겠다고 하세요.', '[{"all":["more the merrier"]},{"all":["save you"]},{"all":["not at all"]},{"all":["bring her"]}]', 'Not at all. The more, the merrier. I''ll save you both a seat.', '전혀요. 많을수록 좋죠. 두 사람 자리 맡아 둘게요.', '["Yes, I do mind. It''s more of a team thing tonight, sorry.","Not at all. But I''m only buying the first round for the team.","Yes, of course! Bring her. I''ll save you both a seat."]', '["네, 좀 곤란해요. 오늘은 팀끼리 하는 자리라서요, 미안해요.","전혀요. 근데 첫 잔은 우리 팀 것만 사는 거예요.","네, 그럼요! 데려와요. 두 사람 자리 맡아 둘게요."]', '["Oh. Okay. Never mind, then.","Ha, generous. I''ll tell her to bring cash.","Wait. Yes, you mind? Or yes, she can come?"]', '["아. 네. 그럼 됐어요.","하, 통 크시네. 현금 챙기라고 할게요.","잠깐만요. 곤란하다는 거예요, 데려오라는 거예요?"]', '["Answer \\"Mind if …?\\" with \\"Not at all\\" to say yes.","Key words: not at all, the more the merrier"]', '["\\"Mind if …?\\"에는 \\"Not at all\\"이 좋다는 대답입니다.","핵심 단어: not at all, the more the merrier"]', 'tom', 'See you there. Let me just lock up here.', '거기서 봐요. 여기 문단속만 하고요.'),
  ('dk_d8_coffee', 1, 'nina', 'Monday morning. Fog hangs over Lake Avenue, and you can barely see the coffee cart until you are standing in front of it.', '월요일 아침입니다. 레이크 애비뉴에 안개가 자욱해서 바로 앞에 설 때까지 커피 카트가 잘 보이지 않습니다.', 'Morning, Derek! I can barely see across the street. How was the drive in?', '좋은 아침이에요, 데릭! 길 건너편도 잘 안 보여요. 운전해서 오는 거 어땠어요?', 'Tell her about your slow commute in the fog.', '안개 때문에 느렸던 출근길 이야기를 해 주세요.', '[{"any":["crawling","crawl","crawled"]},{"all":["twice as long"]},{"all":["bumper to bumper"]}]', 'Traffic was crawling the whole way. It took me twice as long as usual.', '오는 내내 차가 기어갔어요. 평소보다 두 배는 걸렸어요.', '["Smooth, actually. The roads were empty. I got here early for once.","It''s supposed to burn off by noon, though. At least that''s what they said.","Awful. Everyone in this town drives like an idiot in the fog."]', '["사실 순조로웠어요. 길이 텅 비어서 웬일로 일찍 왔어요.","그래도 정오쯤엔 걷힌대요. 적어도 그렇게들 말하더라고요.","최악이었어요. 이 동네 사람들은 안개만 끼면 운전을 엉망으로 해요."]', '["Really? Half my regulars are stuck out there.","Sure, but I asked about your drive.","Whoa. Somebody needs coffee."]', '["정말요? 단골 절반이 길에서 꼼짝 못 하고 있는데요.","그렇죠, 근데 운전은 어땠냐고 물은 건데요.","워. 누가 커피가 급하네요."]', '["Describe slow traffic and compare it with a normal day.","Key words: crawling, twice as long"]', '["느린 교통 상황을 묘사하고 평소와 비교하세요.","핵심 단어: crawling, twice as long"]', 'nina', 'I believe it. Half my regulars are running late. It''s supposed to burn off by noon, though.', '그럴 만해요. 단골 절반이 늦고 있어요. 그래도 정오쯤엔 걷힌대요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_coffee', 2, 'nina', 'She reaches for a large cup, then stops.', '그녀가 큰 컵을 집으려다 멈춥니다.', 'The usual? Oh, wait. Your card was full last week. This one''s on the house, so get whatever you want.', '늘 드시던 걸로요? 아, 잠깐만요. 지난주에 쿠폰 다 찼었죠. 이건 공짜니까 마음대로 골라요.', 'Since it''s free, go for something fancier than usual: a big latte with one more shot of espresso.', '공짜니까 평소보다 좋은 걸로 하세요. 큰 사이즈 라테에 에스프레소 샷 하나 더요.', '[{"all":["treat myself"]},{"all":["extra shot"]},{"any":["latte"]}]', 'In that case, I''ll treat myself. Make it a large latte with an extra shot.', '그렇다면 오늘은 호사 좀 부려 볼게요. 샷 추가해서 라테 라지로 주세요.', '["Just the usual is fine. Large dark roast with room for cream.","In that case, I''ll treat myself. Make it a small iced tea, please.","In that case, I''ll take two large lattes and a couple of muffins, all on the house."]', '["그냥 늘 먹던 걸로 주세요. 다크 로스트 라지, 크림 넣을 자리 남겨서요.","그렇다면 오늘은 호사 좀 부려 볼게요. 아이스티 스몰로 주세요.","그렇다면 라테 라지 두 잔이랑 머핀 두어 개, 전부 공짜로 할게요."]', '["The usual? You''re sure? It''s free, Derek.","Iced tea? In this fog? That''s your treat?","Ha! One free drink, Derek. Not the whole cart."]', '["늘 먹던 거요? 진짜요? 공짜라니까요, 데릭.","아이스티요? 이 안개에? 그게 호사예요?","하! 공짜는 한 잔이에요, 데릭. 카트 전부가 아니고요."]', '["A free drink is a chance for something nicer than usual.","Key words: treat myself, make it a, extra shot"]', '["공짜 음료는 평소보다 좋은 것을 고를 기회입니다.","핵심 단어: treat myself, make it a, extra shot"]', 'nina', 'A latte! Look at you, living on the edge.', '라테라니! 오늘 아주 과감하시네요.'),
  ('dk_d8_coffee', 3, 'nina', 'The milk steamer hisses. Nina talks over it.', '우유 스티머가 쉭쉭 소리를 냅니다. 니나가 그 소리 너머로 말합니다.', 'So how was the barbecue? Mike told me you nearly bought out the market.', '그래서 바비큐는 어땠어요? 마이크 말로는 마트를 거의 다 털었다던데.', 'Tell her how the weekend went: perfect weather, and Carl''s side dish was the big hit.', '주말이 어땠는지 말해 주세요. 날씨는 최고였고, 칼이 가져온 음식이 제일 인기였다고요.', '[{"all":["a blast"]},{"all":["stole the show"]},{"all":["could not have been better"]},{"all":["potato salad"]}]', 'It was a blast. The weather couldn''t have been better, and my neighbor''s potato salad stole the show.', '정말 재밌었어요. 날씨는 더할 나위 없었고, 이웃집 감자 샐러드가 주인공이었어요.', '["It was a blast. It rained a bit in the afternoon, but my neighbor''s potato salad totally stole the show.","It was fine. My neighbor showed up with potato salad nobody asked for, though.","Honestly, exhausting. Too many people, and I was cleaning up until midnight."]', '["정말 재밌었어요. 오후에 비가 좀 왔지만, 이웃집 감자 샐러드가 완전 주인공이었어요.","그냥 그랬어요. 근데 이웃이 아무도 부탁 안 한 감자 샐러드를 들고 왔더라고요.","솔직히 진이 빠졌어요. 사람이 너무 많았고, 자정까지 치웠어요."]', '["Rain? It was sunny all weekend here.","Aw, that''s not very neighborly.","Oh no. Was it at least fun?"]', '["비요? 여긴 주말 내내 맑았는데요.","에이, 이웃한테 너무하네요.","저런. 그래도 재밌긴 했어요?"]', '["Say how much fun it was, and what everybody liked best.","Key words: a blast, couldn''t have been better, stole the show"]', '["얼마나 즐거웠는지, 모두가 무엇을 가장 좋아했는지 말하세요.","핵심 단어: a blast, couldn''t have been better, stole the show"]', 'nina', 'A potato salad beat your burgers? Ouch.', '감자 샐러드가 데릭의 버거를 이겼어요? 저런.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_coffee', 4, 'nina', 'She snaps a lid on the cup and slides it across the counter.', '그녀가 컵에 뚜껑을 딱 닫아 카운터 너머로 밀어 줍니다.', 'Here you go. Big week ahead?', '여기요. 이번 주 바빠요?', 'Say a new project starts today, and joke that you''ll need plenty of coffee.', '오늘 새 프로젝트가 시작된다고 하고, 커피가 잔뜩 필요할 거라고 농담하세요.', '[{"any":["kicking off","kicks off","kickoff","caffeine"]},{"all":["kick off"]}]', 'We''ve got a new project kicking off today, so I''ll need all the caffeine I can get.', '오늘 새 프로젝트가 시작돼서, 카페인이 있는 대로 다 필요할 거예요.', '["We''ve got a new project kicking off next month, so this week should be pretty easy.","Our client''s furious about last week''s outage, so I might get chewed out today.","Last week was crazy. We had an outage and a new hire. Glad it''s over."]', '["새 프로젝트는 다음 달에 시작이라 이번 주는 꽤 한가할 거예요.","지난주 장애 때문에 고객사가 엄청 화나서, 오늘 한 소리 들을지도 몰라요.","지난주가 정신없었어요. 장애도 나고 신입도 오고. 끝나서 다행이에요."]', '["Lucky you. Enjoy the quiet while it lasts.","Yikes. I didn''t need to know that, but good luck.","Glad for you. But I asked about this week."]', '["좋겠네요. 조용할 때 즐겨요.","이런. 몰라도 될 얘기 같지만, 행운을 빌어요.","다행이네요. 근데 이번 주 얘기 물은 건데요."]', '["\\"Kick off\\" = start (a project, a meeting, a game).","Key words: kicking off, caffeine"]', '["kick off는 프로젝트나 회의, 경기를 시작한다는 뜻입니다.","핵심 단어: kicking off, caffeine"]', 'nina', 'Then go get ''em. And drive safe tonight!', '그럼 가서 멋지게 해내요. 저녁에 운전 조심하고요!'),
  ('dk_d8_postmortem', 1, 'maya', 'Monday afternoon in Sam''s room. Your postmortem of last Thursday''s outage is on the big monitor. Maya has pulled up a chair.', '월요일 오후, 샘의 방입니다. 지난 목요일 장애에 대해 당신이 쓴 사후 분석 보고서가 큰 모니터에 떠 있습니다. 마야가 의자를 끌어다 앉았습니다.', 'Thanks for writing this up, Derek. Before we start: how do you want to run this?', '정리해 줘서 고마워요, 데릭. 시작하기 전에, 어떤 식으로 진행하고 싶어요?', 'Set the tone: this meeting is about fixing how things work, and nobody here is in trouble.', '분위기를 정하세요. 이 자리는 일하는 방식을 고치려는 것이고, 여기 있는 누구도 혼나는 게 아니라고요.', '[{"any":["blameless"]},{"all":["point fingers"]},{"all":["pointing fingers"]},{"all":["fix the process"]}]', 'Let''s keep it blameless. We''re here to fix the process, not to point fingers.', '누구 탓도 하지 말고 하죠. 손가락질하려는 게 아니라 절차를 고치려고 모인 거니까요.', '["Let''s start with who missed the certificate, and then talk about how to fix it.","Let''s keep it quick. Everyone''s read the doc, so we can just sign off on it.","However you like, Maya. It''s your meeting, so I''ll just follow your lead."]', '["인증서를 누가 놓쳤는지부터 보고, 그다음에 어떻게 고칠지 얘기하죠.","빨리 끝내죠. 다들 문서 읽었으니까 그냥 승인하고 넘어가면 돼요.","편하신 대로 하세요, 마야. 마야 회의니까 저는 따라갈게요."]', '["Hold on. We don''t start with who. That''s not how we do these.","Quick is fine, but we do need to talk it through first.","It''s your postmortem, Derek. You set the tone."]', '["잠깐만요. ''누가''부터 시작하진 않아요. 우리는 이런 걸 그렇게 안 해요.","빨리 하는 건 좋은데, 먼저 같이 짚어 보긴 해야 해요.","데릭이 쓴 사후 분석이잖아요. 분위기는 데릭이 정해요."]', '["Set the rule first: look for causes, not for someone to blame.","Key words: blameless, point fingers"]', '["규칙부터 정하세요. 탓할 사람이 아니라 원인을 찾는다고요.","핵심 단어: blameless, point fingers"]', 'sam', 'Good, because I''ve been losing sleep over that certificate.', '다행이네요. 그 인증서 때문에 잠을 설쳤거든요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_postmortem', 2, 'sam', 'Sam stares at the timeline on the screen: "8:57, certificate expires."', '샘이 화면의 타임라인을 물끄러미 봅니다. "8:57, 인증서 만료."', 'Be honest, though. It was my certificate. I should have caught it.', '그래도 솔직히요. 제 인증서였잖아요. 제가 잡았어야 했어요.', 'Sam is beating himself up. Reassure him, and point out that the renewal email was going to a coworker who quit two years ago.', '샘이 자책하고 있습니다. 그를 안심시키고, 갱신 알림 메일이 2년 전에 그만둔 직원에게 가고 있었다는 점을 짚어 주세요.', '[{"all":["happened to anyone"]},{"all":["happen to anyone"]},{"any":["reminder","reminders"]},{"all":["not on you"]}]', 'It could have happened to anyone. The renewal reminder went to someone who left two years ago.', '누구라도 그럴 수 있었어요. 갱신 알림이 2년 전에 퇴사한 사람한테 가고 있었잖아요.', '["It could have happened to anyone. The renewal reminder went to Maya, and she was out that week.","Well, yes, you probably should have caught it. But let''s not dwell on it now.","That''s not important right now. Let''s just get through the timeline first, okay?"]', '["누구라도 그럴 수 있었어요. 갱신 알림이 마야한테 갔는데, 마야가 그 주에 자리에 없었잖아요.","뭐, 그렇죠, 잡았어야 했던 건 맞아요. 그래도 지금은 그 얘기에 매달리지 말죠.","그건 지금 중요하지 않아요. 일단 타임라인부터 끝까지 봐요, 알았죠?"]', '["Wait, it went to Maya? I thought it went to some old inbox.","Ouch. I thought this was supposed to be blameless.","Right. Sorry. I''ll just sit here and feel bad, then."]', '["잠깐, 마야한테 갔다고요? 안 쓰는 옛날 메일함으로 간 줄 알았는데요.","아프네요. 누구 탓도 안 하기로 한 줄 알았는데.","네. 죄송해요. 그럼 그냥 여기 앉아서 자책하고 있을게요."]', '["Move the talk from the person to the system.","Key words: could have happened to anyone, reminder"]', '["이야기를 사람에서 시스템으로 옮기세요.","핵심 단어: could have happened to anyone, reminder"]', 'sam', 'Yeah. An inbox nobody reads. That''s the real bug.', '그러게요. 아무도 안 읽는 메일함. 그게 진짜 버그네요.'),
  ('dk_d8_postmortem', 3, 'maya', 'Maya scrolls to the section called "Causes".', '마야가 "원인" 항목으로 화면을 내립니다.', 'So what''s the root cause, as opposed to the trigger?', '그럼 계기 말고 근본 원인은 뭐예요?', 'Separate what set the outage off from what really went wrong underneath.', '장애를 터뜨린 것과, 그 밑에서 실제로 잘못된 것을 구분해서 말하세요.', '[{"all":["fell through the cracks"]},{"all":["root cause"]},{"all":["nobody owned"]},{"all":["no owner"]}]', 'The expired certificate was just the trigger. The root cause is that nobody owned the renewal, so it fell through the cracks.', '만료된 인증서는 계기였을 뿐이에요. 근본 원인은 갱신을 맡은 사람이 없어서 그냥 빠져 버렸다는 거예요.', '["The root cause was the expired certificate itself. The trigger was that nobody owned the renewal, so it fell through the cracks.","The root cause is that Sam didn''t check his calendar. The expired certificate was just the trigger.","The certificate expired at 8:57, and the site was down for everyone until the backup kicked in."]', '["근본 원인은 만료된 인증서 그 자체예요. 계기는 갱신을 맡은 사람이 없어서 그냥 빠져 버렸다는 거고요.","근본 원인은 샘이 달력을 확인하지 않은 거예요. 만료된 인증서는 계기였을 뿐이고요.","인증서가 8시 57분에 만료됐고, 백업이 돌기 전까지 모두가 사이트를 못 썼어요."]', '["Hmm, isn''t that backwards? The expiry is what set it off.","Derek, we just agreed to keep this blameless.","That''s what happened. I''m asking why it happened."]', '["음, 거꾸로 아니에요? 일을 터뜨린 건 만료잖아요.","데릭, 방금 누구 탓도 안 하기로 했잖아요.","그건 무슨 일이 있었는지고요. 저는 왜 일어났는지를 묻는 거예요."]', '["The trigger is what set it off; the root cause is why it was possible at all.","Key words: trigger, root cause, fell through the cracks"]', '["trigger는 일을 터뜨린 계기이고, root cause는 그 일이 가능했던 이유입니다.","핵심 단어: trigger, root cause, fell through the cracks"]', 'maya', 'No owner. That''s the line I want at the top of the page.', '담당자 없음. 그 문장을 보고서 맨 위에 두고 싶네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_postmortem', 4, 'maya', 'She opens an empty table with three columns: what, who, when.', '그녀가 무엇, 누가, 언제의 세 칸짜리 빈 표를 엽니다.', 'Okay, action items. What do we do, who owns it, and by when?', '좋아요, 조치 항목이요. 뭘 하고, 누가 맡고, 언제까지 해요?', 'Assign the two fixes: the shared renewal calendar goes to Sam, due Friday, and the expiry alert is yours.', '두 가지 조치를 배정하세요. 공유 갱신 달력은 샘이 금요일까지, 만료 경보는 당신이 맡는다고요.', '[{"all":["shared calendar"]},{"any":["alert","own","owns"]},{"all":["by friday"]}]', 'Sam moves the renewals to a shared calendar by Friday, and I''ll own the expiry alert.', '샘이 금요일까지 갱신 일정을 공유 달력으로 옮기고, 만료 경보는 제가 맡을게요.', '["Sam moves the renewals to a shared calendar by next month, and I''ll own the expiry alert.","We should probably set up a shared calendar and some kind of alert at some point.","I''ll take both, the calendar and the alert. It''s faster if I just do it myself."]', '["샘이 다음 달까지 갱신 일정을 공유 달력으로 옮기고, 만료 경보는 제가 맡을게요.","언젠가는 공유 달력이랑 무슨 경보 같은 걸 만들어 둬야 할 것 같아요.","달력이랑 경보 둘 다 제가 할게요. 그냥 제가 하는 게 빨라요."]', '["Next month? That''s a long time to leave it open. Can we tighten that?","At some point isn''t a date, Derek. Who, and when?","Both? You''ve got enough on your plate. Let''s spread it out."]', '["다음 달이요? 그동안 열어 두기엔 너무 길어요. 좀 당길 수 있어요?","''언젠가''는 날짜가 아니에요, 데릭. 누가, 언제요?","둘 다요? 이미 할 일이 많잖아요. 나눠서 하죠."]', '["Every action item needs a task, a name and a date.","Key words: shared calendar, by Friday, I''ll own"]', '["후속 조치에는 할 일, 이름, 날짜가 모두 있어야 합니다.","핵심 단어: shared calendar, by Friday, I''ll own"]', 'maya', 'Every item with a name and a date. I like it.', '항목마다 이름과 날짜가 있네요. 마음에 들어요.'),
  ('dk_d8_postmortem', 5, 'maya', 'One empty heading is left at the bottom of the page.', '보고서 맨 아래에 빈 제목 하나가 남아 있습니다.', 'Last section. Lessons learned?', '마지막 항목이에요. 얻은 교훈은요?', 'Sum up the lesson: everything hung on one weak spot, and the backup working was a fluke you can''t plan around.', '교훈을 정리하세요. 모든 게 약한 고리 하나에 걸려 있었고, 백업이 동작한 건 계획에 넣을 수 없는 요행이었다고요.', '[{"all":["in hindsight"]},{"all":["single point of failure"]},{"all":["count on luck"]}]', 'In hindsight, we had a single point of failure. We were lucky the backup worked, and we shouldn''t count on luck.', '돌이켜 보면 단일 장애점이 있었어요. 백업이 동작한 건 운이 좋았던 거고, 운에 기대면 안 돼요.', '["In hindsight, the system worked exactly as designed. The backup kicked in, so there''s nothing big we need to change.","Lesson learned: IT needs to keep a much closer eye on certificates. That''s really the whole story.","In hindsight, we had a single point of failure. The backup failed too, so we were down all day."]', '["돌이켜 보면 시스템은 설계대로 정확히 동작했어요. 백업이 돌았으니까 크게 바꿀 건 없어요.","교훈은 IT 쪽이 인증서를 훨씬 더 잘 챙겨야 한다는 거예요. 사실 그게 전부예요.","돌이켜 보면 단일 장애점이 있었어요. 백업까지 실패해서 하루 종일 멈춰 있었고요."]', '["Nothing to change? We got lucky, Derek. Let''s not pretend otherwise.","That puts it all on Sam again. Try that one more time.","Down all day? The backup kicked in. Check the timeline."]', '["바꿀 게 없다고요? 운이 좋았던 거예요, 데릭. 아닌 척하지 말죠.","그러면 또 전부 샘 탓이 되잖아요. 다시 한번 말해 봐요.","하루 종일요? 백업이 돌았잖아요. 타임라인 봐요."]', '["Look back honestly: what do you see now that you did not see then?","Key words: in hindsight, single point of failure"]', '["솔직하게 돌아보세요. 그때는 못 봤지만 지금은 보이는 게 무엇인가요?","핵심 단어: in hindsight, single point of failure"]', 'maya', 'Well said. Send it to the team, and I''ll share a summary with Summit Retail. Let me know if you have any questions.', '잘 말했어요. 팀에 공유해 줘요. 서밋 리테일에는 제가 요약본을 보낼게요. 궁금한 게 있으면 말해 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_risk', 1, 'priya', 'The kickoff call with Summit Retail has just ended. Jun has gone back to his desk. Priya closes the door of the meeting room.', '서밋 리테일 킥오프 콜이 방금 끝났습니다. 준은 자리로 돌아갔습니다. 프리야가 회의실 문을 닫습니다.', 'Okay, you heard Greg. Live inventory for forty stores. Give it to me straight: how risky is this?', '좋아요, 그렉 말 들었죠. 매장 마흔 곳의 실시간 재고. 돌려 말하지 말고요. 이거 얼마나 위험해요?', 'Give her your honest read: which part is easy, and where the real uncertainty is, which is their old store checkout system.', '솔직한 판단을 말해 주세요. 어느 부분이 쉽고, 진짜 불확실한 건 어디인지요. 바로 그쪽의 오래된 매장 계산 시스템이에요.', '[{"any":["unknown","unknowns","straightforward"]},{"all":["point of sale"]}]', 'The dashboard itself is straightforward. The big unknown is their point-of-sale system.', '대시보드 자체는 어렵지 않아요. 가장 큰 변수는 그쪽 POS 시스템이에요.', '["The dashboard is the hard part. Their point-of-sale system should plug right in.","Honestly, there''s no real risk here. We''ve built dashboards like this a dozen times before.","Forty stores is a lot. How many people does Greg have on his IT team, anyway?"]', '["어려운 건 대시보드 쪽이에요. 그쪽 POS 시스템은 그냥 바로 연결될 거예요.","솔직히 위험할 건 없어요. 이런 대시보드는 전에도 열 번은 넘게 만들어 봤어요.","매장 마흔 곳이면 많네요. 그런데 그렉 쪽 IT 팀은 몇 명이에요?"]', '["Plug right in? Greg made their system sound pretty ancient.","No risk at all? I''ve heard that before. Give me the real version.","I can find out. But I asked you how risky this is."]', '["바로 연결된다고요? 그렉 얘기로는 꽤 오래된 시스템 같던데요.","위험이 하나도 없다고요? 그런 말 전에도 들어 봤어요. 진짜를 말해 줘요.","그건 알아볼 수 있어요. 그런데 제가 물은 건 얼마나 위험하냐예요."]', '["Separate the easy part from the part nobody knows yet.","Key words: straightforward, the big unknown"]', '["쉬운 부분과 아직 아무도 모르는 부분을 나누어 말하세요.","핵심 단어: straightforward, the big unknown"]', 'priya', 'The old one that spits out a file every night. Right.', '매일 밤 파일을 하나씩 뱉어 내는 그 오래된 시스템 말이죠. 그렇군요.'),
  ('dk_d8_risk', 2, 'priya', 'Priya opens the timeline on her laptop.', '프리야가 노트북에서 일정표를 엽니다.', 'So can we hit November first or not? I need a yes or a no.', '그래서 11월 1일 맞출 수 있어요, 없어요? 예스냐 노냐가 필요해요.', 'She wants a yes or no, but the honest answer hinges on getting API access this week. Give her an answer she can work with.', '그녀는 예, 아니오를 원하지만, 정직한 답은 이번 주에 API 접근 권한을 받느냐에 달려 있습니다. 그녀가 써먹을 수 있는 답을 주세요.', '[{"all":["depends on"]},{"all":["at risk"]},{"all":["good shape"]}]', 'It depends on how soon we get API access. If we get it this week, we''re in good shape. If not, the date is at risk.', 'API 접근 권한을 얼마나 빨리 받느냐에 달렸어요. 이번 주에 받으면 문제없고요. 못 받으면 그 날짜는 위험해요.', '["It depends on how soon we get API access. If we get it by the end of the month, we''re in good shape for November first.","Yes, absolutely. We''ll hit November first no matter what happens with their API access.","Hard to say. There are a lot of moving parts, so let''s revisit it in a couple of weeks."]', '["API 접근 권한을 얼마나 빨리 받느냐에 달렸어요. 이달 말까지만 받으면 11월 1일은 문제없어요.","네, 당연하죠. 그쪽 API 접근 권한이 어떻게 되든 11월 1일은 맞출 거예요.","지금은 뭐라 말하기 어렵네요. 변수가 워낙 많으니까 2주쯤 뒤에 다시 얘기해 봐요."]', '["End of the month? That''s cutting it close. I thought we needed it sooner.","No matter what? I''m going to quote you on that. Are you sure?","A couple of weeks? I need something to tell Greg today."]', '["이달 말이요? 너무 빠듯한데요. 더 빨리 받아야 하는 줄 알았어요.","무슨 일이 있어도요? 그 말 그대로 인용할 거예요. 확실해요?","2주 뒤요? 오늘 그렉한테 할 말이 있어야 해요."]', '["Do not stop at \\"it depends\\". Say what it depends on, and what happens either way.","Key words: it depends on, in good shape, at risk"]', '["\\"it depends\\"에서 멈추지 마세요. 무엇에 달렸는지, 경우마다 어떻게 되는지 말하세요.","핵심 단어: it depends on, in good shape, at risk"]', 'priya', 'Okay. That''s an "it depends" I can actually use.', '좋아요. 그건 제가 실제로 써먹을 수 있는 "상황에 따라"네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_risk', 3, 'priya', 'She types a note: "API access this week."', '그녀가 "이번 주 안에 API 접근 권한"이라고 메모합니다.', 'Ballpark, how long is phase one? I won''t hold you to it.', '대충, 1단계는 얼마나 걸려요? 그대로 지키라고 하진 않을게요.', 'Give her a range, six to eight weeks, and name the one thing it depends on.', '6주에서 8주라는 범위로 말하고, 그게 무엇에 달려 있는지 한 가지를 짚어 주세요.', '[{"any":["assuming","range"]},{"all":["six to eight"]},{"all":["6 to 8"]}]', 'Ballpark, six to eight weeks, assuming their API does what they say it does.', '대충 6주에서 8주요. 그쪽 API가 말한 대로 동작한다는 전제로요.', '["Ballpark, eight to ten weeks, assuming we get the API access sometime this week.","Exactly seven weeks. You can put that in the contract with Greg.","Ballpark, six to eight people, assuming Jun stays on it full time."]', '["대충 8주에서 10주요. 이번 주 중에 API 접근 권한을 받는다는 전제로요.","딱 7주요. 그렉하고 맺는 계약서에 그대로 넣어도 돼요.","대충 여섯에서 여덟 명이요. 준이 전담으로 붙어 있다는 전제로요."]', '["Eight to ten? That blows right past November. Is that right?","Whoa, I said I won''t hold you to it. Don''t make it a promise.","People? I meant time. How many weeks?"]', '["8주에서 10주요? 그럼 11월을 훌쩍 넘기는데요. 맞아요?","잠깐만요, 그대로 지키라고 안 한다고 했잖아요. 약속으로 만들진 마요.","사람이요? 기간을 물은 거예요. 몇 주요?"]', '["Give a range and name the assumption behind it.","Key words: six to eight weeks, assuming"]', '["범위로 말하고 그 뒤에 깔린 전제를 밝히세요.","핵심 단어: six to eight weeks, assuming"]', 'priya', 'Six to eight, with an assumption attached. Got it.', '6주에서 8주, 전제 하나 붙여서. 알겠어요.'),
  ('dk_d8_risk', 4, 'priya', 'Priya puts down her pen.', '프리야가 펜을 내려놓습니다.', 'And what keeps you up at night?', '그럼 밤잠 못 이루게 하는 건 뭐예요?', 'Tell her the worst case you see in the stores'' data, and when you would want to learn about it.', '매장 데이터에서 보이는 최악의 경우와, 그걸 언제 알고 싶은지 말하세요.', '[{"all":["worst case"]},{"any":["messy","dirty"]},{"all":["find that out early"]},{"all":["find out early"]}]', 'Worst case, the data from the stores is messy. I''d rather find that out early than in October.', '최악의 경우는 매장 데이터가 엉망인 거예요. 그건 10월보다 일찍 알아내는 게 나아요.', '["Worst case, the data from the stores is messy. We''ll deal with that in October, at launch.","Honestly? My kid''s been sick all week, so I''m barely sleeping as it is.","Worst case, Greg''s team sends us garbage data and then blames us for it. Clients always do that."]', '["최악의 경우는 매장 데이터가 엉망인 거예요. 그건 10월에 오픈할 때 처리하면 돼요.","솔직히요? 애가 일주일 내내 아파서, 안 그래도 잠을 거의 못 자요.","최악의 경우는 그렉 팀이 쓰레기 데이터를 보내 놓고 우리 탓을 하는 거죠. 고객들은 늘 그래요."]', '["October? That''s way too late to find out, Derek.","Oh no, I''m sorry. I meant on the project, though.","Let''s not go there. We''ve never even worked with them before."]', '["10월이요? 그때 알면 너무 늦어요, 데릭.","어머, 안됐네요. 그런데 프로젝트 얘기였어요.","그렇게까지 가진 말죠. 그쪽이랑 일해 본 적도 없잖아요."]', '["Name the worst thing that could happen, and when you want to know.","Key words: worst case, messy, find that out early"]', '["일어날 수 있는 가장 나쁜 일과, 그것을 언제 알고 싶은지 말하세요.","핵심 단어: worst case, messy, find that out early"]', 'priya', 'Agreed. Bad news doesn''t get better with age.', '동의해요. 나쁜 소식은 묵힌다고 좋아지지 않죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d8_risk', 5, 'priya', 'She stands at the whiteboard with a marker.', '그녀가 마커를 들고 화이트보드 앞에 섭니다.', 'So how do we take some of that risk off the table?', '그럼 그 위험을 어떻게 좀 덜 수 있을까요?', 'Suggest starting small with five stores, and only then going to all forty.', '처음엔 매장 다섯 곳으로 작게 시작하고, 그다음에야 마흔 곳 전체로 가자고 제안하세요.', '[{"any":["pilot","phased"]},{"all":["roll it out"]},{"all":["five stores"]}]', 'I''d propose a phased rollout. We pilot with five stores first, then roll it out to the rest.', '단계별로 적용하자고 제안할게요. 먼저 매장 다섯 곳에서 시범 운영하고, 그다음에 나머지로 넓히는 거예요.', '["I''d propose a phased rollout. We pilot with fifteen stores first, then do the other twenty-five.","Let''s just tell Greg forty stores is too many and cut the scope down to twenty.","We could add people. If Maya gives us two more developers, we''d be totally fine."]', '["단계별로 적용하자고 제안할게요. 먼저 매장 열다섯 곳에서 시범 운영하고, 그다음에 나머지 스물다섯 곳을 하는 거예요.","그냥 그렉한테 매장 마흔 곳은 너무 많다고 말하고, 범위를 스무 곳으로 줄여 버려요.","사람을 늘리면 돼요. 마야가 개발자 두 명만 더 주면 전혀 문제없을 거예요."]', '["Fifteen? That''s a big pilot. I thought you''d want it smaller.","Cut the scope? Greg just asked for forty. I can''t sell that.","More people won''t fix messy data, though. What else?"]', '["열다섯 곳이요? 시범치고는 크네요. 더 작게 하자고 할 줄 알았어요.","범위를 줄여요? 그렉이 방금 마흔 곳을 원했는데요. 그건 못 팔아요.","사람을 늘린다고 엉망인 데이터가 고쳐지진 않잖아요. 다른 건요?"]', '["Start small, learn, then expand.","Key words: phased rollout, pilot, roll it out"]', '["작게 시작해서 배우고, 그다음 넓히세요.","핵심 단어: phased rollout, pilot, roll it out"]', 'priya', 'A five-store pilot. I love it. I''ll float it with Greg on tomorrow''s call.', '매장 다섯 곳 시범 운영. 아주 좋아요. 내일 통화에서 그렉에게 슬쩍 제안해 볼게요.'),
  ('dk_d9_delegate', 1, 'jun', 'Tuesday morning. Rain streaks the office windows. You had already opened the editor to write the certificate alert yourself when you remembered what Maya said about delegating. You walk over to Jun''s desk.', '화요일 아침입니다. 사무실 창문에 빗줄기가 흘러내립니다. 인증서 경보를 직접 만들려고 편집기를 열었다가, 일을 맡기라던 마야의 말이 떠올랐습니다. 준의 자리로 갑니다.', 'Morning, Derek! Did you need something?', '안녕하세요, 데릭! 뭐 필요한 거 있으세요?', 'Hand him a task: the certificate expiry alert that came out of the postmortem.', '그에게 일을 하나 맡기세요. 사후 분석에서 나온 인증서 만료 경보예요.', '[{"all":["take on"]},{"all":["take over"]},{"any":["alert"]}]', 'I''ve got something I''d like you to take on: the certificate expiry alert from the postmortem.', '준이 맡아 줬으면 하는 일이 있어요. 사후 분석에서 나온 인증서 만료 경보요.', '["I''ve got something I''d like you to take on: the shared renewal calendar from the postmortem.","Drop whatever you''re working on right now. You''re building the certificate alert, starting today.","I''m building the certificate expiry alert. Want to sit with me and watch how I do it?"]', '["준이 맡아 줬으면 하는 일이 있어요. 사후 분석에서 나온 공유 갱신 달력이요.","지금 하던 거 다 내려놔요. 오늘부터 인증서 경보 만드는 거예요, 당장.","제가 인증서 만료 경보를 만들 건데요. 옆에 앉아서 어떻게 하는지 볼래요?"]', '["The calendar? I thought Sam was doing that one.","Oh. Okay. But what about the Summit Retail work?","Sure, I can watch. You don''t need me to do anything?"]', '["달력이요? 그건 샘이 하는 줄 알았는데요.","아. 네. 그런데 서밋 리테일 일은요?","네, 볼 수는 있어요. 제가 할 건 없는 거예요?"]', '["\\"Take on\\" a task = accept it as yours.","Key words: take on, alert"]', '["take on은 일을 자기 것으로 맡는다는 뜻입니다.","핵심 단어: take on, alert"]', 'jun', 'Me? Sure! But I''ve never touched the monitoring setup.', '저요? 좋아요! 그런데 모니터링 쪽은 한 번도 건드려 본 적이 없어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_delegate', 2, 'jun', 'Jun opens a new page in his notebook.', '준이 공책의 새 페이지를 폅니다.', 'What exactly do you need? I don''t want to build the wrong thing.', '정확히 뭐가 필요하세요? 엉뚱한 걸 만들고 싶지 않아서요.', 'Spell out the finish line: thirty days'' warning before any certificate expires, posted to the on-call channel.', '어디까지 하면 끝인지 분명히 말하세요. 어떤 인증서든 만료 30일 전에 알리고, 온콜 채널에 올라오게 하는 거예요.', '[{"all":["done looks like"]},{"all":["thirty days"]},{"all":["30 days"]},{"any":["fires","expires"]}]', 'Here''s what done looks like: an alert that fires thirty days before any certificate expires and posts to the on-call channel.', '완료 기준은 이거예요. 어떤 인증서든 만료 30일 전에 울려서 온콜 채널에 올라오는 경보요.', '["Here''s what done looks like: an alert that fires three days before any certificate expires and sends an email to Sam''s inbox.","Just something that warns us before certificates expire. You''ll figure out the details as you go.","Build it exactly the way I would: copy my disk-space alert line by line and just change the names."]', '["완료 기준은 이거예요. 어떤 인증서든 만료 사흘 전에 울려서 샘의 메일함으로 메일이 가는 경보요.","그냥 인증서 만료되기 전에 알려 주는 거면 돼요. 세부 사항은 하면서 알아서 정해요.","제가 할 방식 그대로 만들어요. 제 디스크 용량 경보를 한 줄씩 복사해서 이름만 바꾸면 돼요."]', '["Three days? Isn''t that cutting it a little close?","Okay... but how will I know when it''s done?","Line by line? Um, okay. I thought I''d get to design it."]', '["사흘이요? 좀 빠듯하지 않아요?","네... 그런데 언제 끝난 건지 어떻게 알죠?","한 줄씩이요? 음, 네. 제가 설계해 보는 줄 알았어요."]', '["Describe the finished result, not the steps.","Key words: what done looks like, fires thirty days before"]', '["과정이 아니라 완성된 결과를 설명하세요.","핵심 단어: what done looks like, fires thirty days before"]', 'jun', 'Thirty days before, to the on-call channel. That''s clear.', '30일 전에, 온콜 채널로. 분명하네요.'),
  ('dk_d9_delegate', 3, 'jun', 'He writes it down and underlines it.', '그가 받아 적고 밑줄을 긋습니다.', 'When do you need it by? I''m flying to Ridgeport on Thursday.', '언제까지 필요하세요? 저 목요일에 리지포트로 출장 가거든요.', 'Take the pressure off: give him until the end of next week, and remind him the client work comes first.', '부담을 덜어 주세요. 다음 주 말까지 시간을 주고, 고객 일이 먼저라는 걸 상기시켜 주세요.', '[{"all":["takes priority"]},{"all":["end of next week"]},{"all":["comes first"]},{"any":["priority"]}]', 'No rush. The end of next week is fine. The Summit Retail work takes priority.', '급하지 않아요. 다음 주 말까지면 돼요. 서밋 리테일 일이 먼저예요.', '["I''d like it before Thursday, so it''s done before your trip. Can you swing that?","No rush. The end of next week is fine. Just put it ahead of the Summit Retail stuff.","Ridgeport, huh? Nice. Is that the Summit Retail trip Priya mentioned?"]', '["목요일 전에 됐으면 좋겠어요. 출장 가기 전에 끝나게요. 할 수 있겠어요?","급하지 않아요. 다음 주 말까지면 돼요. 대신 서밋 리테일 일보다 먼저 해요.","리지포트요? 좋네요. 프리야가 말한 그 서밋 리테일 출장이에요?"]', '["Before Thursday? I''ll try, but I''ve still got the trip to prep.","Ahead of Summit Retail? Are you sure? Priya won''t like that.","Yes, that one. But when do you need the alert?"]', '["목요일 전이요? 해 볼게요. 그런데 출장 준비도 남았어요.","서밋 리테일보다 먼저요? 정말요? 프리야가 싫어할 텐데요.","네, 그거요. 그런데 경보는 언제까지 필요하세요?"]', '["Give a deadline, and say which of his tasks comes first.","Key words: no rush, end of next week, takes priority"]', '["마감을 알려 주고, 그의 일 가운데 무엇이 먼저인지 말하세요.","핵심 단어: no rush, end of next week, takes priority"]', 'jun', 'Got it. Trip first, alert second.', '알겠어요. 출장이 먼저, 경보는 그다음.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_delegate', 4, 'jun', 'Jun taps his pen on the notebook.', '준이 펜으로 공책을 톡톡 칩니다.', 'How should I build it? Is there a design you want me to follow?', '어떻게 만들까요? 따랐으면 하는 설계가 있으세요?', 'Let him decide how to build it himself, and let him know he can come to you if he gets stuck.', '어떻게 만들지는 그가 직접 정하게 하고, 막히면 당신에게 오면 된다고 알려 주세요.', '[{"all":["your call"]},{"all":["up to you"]},{"all":["hit a wall"]},{"all":["hits a wall"]}]', 'How you build it is your call. I''m here if you hit a wall.', '어떻게 만들지는 준이 정해요. 막히면 제가 있으니까요.', '["Follow my design doc to the letter, and run every change by me first.","That''s up to you. Don''t come to me with it, though. I''m swamped.","There''s a design review every Monday. Ask Maya to add you to it."]', '["제 설계 문서를 그대로 따르고, 바꿀 땐 먼저 저한테 물어봐요.","그건 알아서 해요. 대신 저한테 가져오진 마요. 저 정신없어요.","매주 월요일에 설계 리뷰가 있어요. 마야한테 넣어 달라고 해요."]', '["Every change? Okay... I thought you said I could own it.","Oh. Okay. I''ll try not to bother you.","Sure, but do you have a design in mind or not?"]', '["뭘 바꾸든요? 네... 제가 맡는 거라고 하신 줄 알았어요.","아. 네. 귀찮게 안 해 드릴게요.","네, 그런데 생각해 두신 설계가 있다는 거예요, 없다는 거예요?"]', '["Say the \\"how\\" belongs to him, and that help is there if he needs it.","Key words: your call, hit a wall"]', '["방법은 그가 정할 몫이고, 필요하면 도움을 받을 수 있다고 말하세요.","핵심 단어: your call, hit a wall"]', 'jun', 'Really? Okay. I''ll sketch something and show you.', '정말요? 알겠어요. 구상을 그려서 보여 드릴게요.'),
  ('dk_d9_delegate', 5, 'jun', 'He looks a little worried that he will let you down.', '그는 당신을 실망시킬까 봐 조금 걱정하는 눈치입니다.', 'Should I send you an update every day?', '매일 진행 상황을 보내 드릴까요?', 'Daily reports would be overkill. Suggest a single check-in on Wednesday afternoon, before his trip.', '매일 보고는 지나칩니다. 그가 출장 가기 전인 수요일 오후에 한 번만 이야기하자고 제안하세요.', '[{"all":["touch base"]},{"all":["touching base"]},{"all":["daily updates"]}]', 'No need for daily updates. Let''s touch base Wednesday afternoon, before you leave.', '매일 보고할 필요는 없어요. 수요일 오후에, 떠나기 전에 잠깐 얘기해요.', '["No need for daily updates. Let''s touch base Thursday afternoon, after you land.","Yes, every day, at the end of the day, in writing. I want to know exactly where it stands.","Don''t bother me with updates. Just tell me when it''s done, okay?"]', '["매일 보고할 필요는 없어요. 목요일 오후에, 도착하고 나서 잠깐 얘기해요.","네, 매일 퇴근 전에 글로 보내요. 어디까지 됐는지 정확히 알고 싶어요.","진행 상황으로 귀찮게 하지 마요. 다 되면 그때 말해요, 알았죠?"]', '["Thursday? I''ll be in meetings in Ridgeport all afternoon.","Every day? Okay... I''ll set a reminder.","Oh. Okay. I''ll just figure it out on my own, then."]', '["목요일이요? 그날 오후엔 리지포트에서 내내 회의예요.","매일이요? 네... 알림 맞춰 둘게요.","아. 네. 그럼 혼자 알아서 해 볼게요."]', '["Check in without micromanaging: one short talk, not a daily report.","Key words: no need, touch base"]', '["일일이 간섭하지 않고 살피세요. 매일 보고가 아니라 짧은 대화 한 번이면 됩니다.","핵심 단어: no need, touch base"]', 'jun', 'Wednesday works. Thanks for trusting me with this, Derek.', '수요일 좋아요. 이 일을 믿고 맡겨 줘서 고마워요, 데릭.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_lunch', 1, 'sam', 'Noon. Rain is hammering the kitchen windows. Sam stands there with an empty mug, looking out at the wet parking lot.', '정오입니다. 비가 탕비실 창문을 세차게 두드립니다. 샘이 빈 머그잔을 들고 젖은 주차장을 내다보고 있습니다.', 'Look at that. I was going to walk to the taco truck, but no way am I going out in this.', '저것 좀 봐요. 타코 트럭까지 걸어가려고 했는데, 이 날씨엔 절대 못 나가요.', 'You don''t want to go out in this either. Suggest getting food delivered and sharing one with him.', '당신도 이 비에 나가기 싫습니다. 음식을 배달시키고 같이 하나 나눠 먹자고 하세요.', '[{"all":["order in"]},{"all":["ordering in"]},{"all":["go in on"]},{"any":["pizza","delivery"]}]', 'Me neither. Let''s order in. Want to go in on a pizza?', '저도요. 시켜 먹어요. 피자 하나 같이 시킬래요?', '["Come on, it''s just water. Grab an umbrella and let''s walk over.","Me neither. The taco truck delivers, right? Let''s order from them.","Me neither. I''m ordering a pizza for myself. Good luck out there."]', '["에이, 그냥 물이잖아요. 우산 챙겨서 같이 걸어가요.","저도요. 타코 트럭도 배달해 주죠? 거기서 시켜요.","저도요. 저는 혼자 피자 시킬 거예요. 나가는 거 잘해 봐요."]', '["In this? You''re braver than me.","The truck? They don''t deliver. Ever.","Wow. Okay. I''ll just eat crackers, then."]', '["이 비에요? 저보다 용감하시네요.","트럭이요? 거긴 배달 안 해요. 절대로요.","와. 네. 그럼 저는 크래커나 먹을게요."]', '["\\"Order in\\" = have food delivered. \\"Go in on\\" = share the cost.","Key words: order in, go in on a pizza"]', '["order in은 음식을 배달시킨다는 뜻이고, go in on은 값을 나눠 낸다는 뜻입니다.","핵심 단어: order in, go in on a pizza"]', 'sam', 'You read my mind. The place on Lake Avenue delivers.', '제 마음을 읽었네요. 레이크 애비뉴에 있는 가게가 배달해 줘요.'),
  ('dk_d9_lunch', 2, 'sam', 'Sam opens the menu on his phone.', '샘이 전화기로 메뉴를 엽니다.', 'What do you want on it? I''m a pepperoni guy.', '뭐 올릴래요? 저는 페퍼로니파예요.', 'Meet him halfway on toppings: his pepperoni on one side, vegetables on the other, and no olives for you.', '토핑은 서로 양보하세요. 한쪽은 그가 좋아하는 페퍼로니, 다른 쪽은 채소로 하고, 당신은 올리브를 빼고 싶어요.', '[{"all":["half and half"]},{"all":["not picky"]},{"all":["hold the olives"]},{"all":["half pepperoni"]}]', 'I''m not picky. How about half and half? Half pepperoni, half veggie. Just hold the olives.', '저는 안 가려요. 반반 어때요? 반은 페퍼로니, 반은 채소로요. 올리브만 빼고요.', '["I''m not picky. How about half and half? Half pepperoni, half veggie. Extra olives on mine.","Pepperoni again? Let''s get something good for once. All veggie, no meat at all.","I''m not picky. Do they have a lunch special? Maybe wings, or a sub instead?"]', '["저는 안 가려요. 반반 어때요? 반은 페퍼로니, 반은 채소로요. 제 쪽엔 올리브 듬뿍이요.","또 페퍼로니요? 이번엔 좀 괜찮은 거 먹어요. 전부 채소로, 고기는 빼고요.","저는 안 가려요. 거기 점심 특선 있어요? 아니면 윙이나 샌드위치는요?"]', '["Extra olives? I thought you hated olives.","Hey, pepperoni is good. Can''t we meet halfway?","Wings? I thought we were doing pizza."]', '["올리브 듬뿍이요? 올리브 싫어하는 줄 알았는데요.","에이, 페퍼로니 맛있잖아요. 중간에서 만나면 안 돼요?","윙이요? 피자 먹기로 한 줄 알았는데요."]', '["Be easygoing, offer a compromise, and name the one thing you do not want.","Key words: not picky, half and half, hold the olives"]', '["까다롭지 않게, 절충안을 내고, 빼고 싶은 것 하나를 말하세요.","핵심 단어: not picky, half and half, hold the olives"]', 'sam', 'Half and half, no olives. A large should do it.', '반반에 올리브 빼고. 라지면 충분하겠네요.'),
  ('dk_d9_lunch', 3, 'sam', 'He adds a large pizza to the cart. The total comes up.', '그가 라지 피자를 장바구니에 담습니다. 합계가 나옵니다.', 'Okay, it''s twenty-two with tax and delivery, plus the tip. Want to split it?', '자, 세금이랑 배달비 포함해서 22달러에 팁 따로예요. 나눠 낼래요?', 'Go fifty-fifty with him, tip included.', '팁까지 포함해서 반반 내자고 하세요.', '[{"all":["down the middle"]},{"all":["chip in"]},{"any":["split"]}]', 'Sure, let''s split it down the middle. I''ll chip in for the tip, too.', '좋아요, 딱 반씩 내요. 팁도 같이 보탤게요.', '["Sure, let''s split it down the middle. But you tip. The driver doesn''t need much.","Sure, down the middle. So that''s eight each, tip and all?","No, I''ll cover the whole thing. You can get the next one."]', '["반반 내요. 근데 팁은 샘이 내요. 조금만 줘도 돼요.","좋아요, 반반이요. 그럼 팁까지 해서 한 사람에 8달러죠?","아니요, 제가 다 낼게요. 다음에 샘이 사요."]', '["Huh. It''s raining sideways out there. The driver''s earning it.","Eight? It''s twenty-two before the tip, Derek.","No way. Let''s split it. You paid last time."]', '["흠. 밖에 비가 옆으로 들이치는데요. 기사님이 고생하시는 거죠.","8달러요? 팁 빼고도 22달러예요, 데릭.","안 돼요. 나눠 내요. 지난번에 데릭이 냈잖아요."]', '["\\"Down the middle\\" = in two equal halves.","Key words: split it down the middle, chip in"]', '["down the middle은 똑같이 둘로 나눈다는 뜻입니다.","핵심 단어: split it down the middle, chip in"]', 'sam', 'Then it''s thirteen each with a four-dollar tip. Easy.', '그럼 팁 4달러를 넣어서 한 사람에 13달러네요. 간단하죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_lunch', 4, 'sam', 'Sam pays with his card. You open your wallet and find a single bill.', '샘이 자기 카드로 결제합니다. 지갑을 열어 보니 지폐가 한 장뿐입니다.', 'I put it on my card. Pay me back whenever.', '제 카드로 냈어요. 아무 때나 주세요.', 'You want to pay him now, but your only bill is a twenty.', '지금 갚고 싶은데, 가진 지폐가 20달러짜리 한 장뿐이에요.', '[{"all":["break"],"any":["twenty","20","it"]},{"all":["change for"]}]', 'All I have on me is a twenty. Can you break it?', '가진 게 20달러짜리 한 장뿐이에요. 잔돈으로 바꿔 줄 수 있어요?', '["All I have on me is a ten. Can you break it?","Cool. I''ll pay you back next week sometime, then.","You should always carry small bills. Got change?"]', '["가진 게 10달러짜리 한 장뿐이에요. 바꿔 줄 수 있어요?","좋아요. 그럼 다음 주 중에 언제 한번 갚을게요.","작은 돈은 늘 갖고 다녀야 해요. 거스름돈 있어요?"]', '["A ten? That looks like a twenty to me.","Sure, whenever. Just don''t forget.","Thanks, Dad. Do you need change or not?"]', '["10달러요? 제 눈엔 20달러짜리로 보이는데요.","네, 아무 때나요. 잊지만 마세요.","네, 아버지. 잔돈 필요하다는 거예요, 아니에요?"]', '["\\"Break\\" a bill = change it into smaller bills.","Key words: a twenty, break it"]', '["지폐를 break한다는 것은 작은 돈으로 바꾼다는 뜻입니다.","핵심 단어: a twenty, break it"]', 'sam', 'Let me see. A five and two ones. Here''s seven back.', '어디 봐요. 5달러 한 장에 1달러 두 장. 7달러 거슬러 드릴게요.'),
  ('dk_d9_lunch', 5, 'sam', 'Half an hour later the pizza is on the kitchen table, and the rain is still falling. Sam lowers his voice.', '30분 뒤 피자가 탕비실 테이블에 놓였고 비는 여전히 내립니다. 샘이 목소리를 낮춥니다.', 'So, off the record: is the new guy going to survive the Summit Retail project?', '그래서, 여기서만 하는 얘긴데요. 그 신입, 서밋 리테일 프로젝트에서 버틸 수 있을까요?', 'Stand up for Jun: you have no doubts about him.', '준의 편을 들어 주세요. 당신은 그를 전혀 의심하지 않아요.', '[{"any":["sharp"]},{"all":["holding his own"]},{"all":["be fine"]}]', 'He''ll be fine. He''s sharp, and he''s more than holding his own.', '괜찮을 거예요. 똑똑하고, 제 몫 이상을 거뜬히 해내고 있어요.', '["Between us? He''s struggling. I''ve been redoing half his code.","The project will be fine. The pilot is only five stores.","Hard to say. He''s still new, and Summit Retail is a tough client."]', '["우리끼리 얘긴데요? 힘들어해요. 코드 절반은 제가 다시 짜고 있어요.","프로젝트는 괜찮을 거예요. 시범 운영은 매장 다섯 곳뿐이거든요.","모르겠어요. 아직 신입이고, 서밋 리테일은 까다로운 고객이라서요."]', '["Really? Huh. He seems so on top of things.","Sure, but I was asking about Jun.","Ouch. You''re not exactly a fan, huh?"]', '["정말요? 흠. 일을 잘 챙기는 것 같던데요.","그렇겠죠. 그런데 저는 준 얘기를 물은 거예요.","아이고. 썩 마음에 들진 않나 보네요?"]', '["Speak well of a teammate who is not in the room.","Key words: sharp, holding his own"]', '["자리에 없는 동료를 좋게 말해 주세요.","핵심 단어: sharp, holding his own"]', 'sam', 'Good. I like him. He actually reads my emails.', '다행이네요. 저는 그 친구가 좋아요. 제 메일을 진짜로 읽거든요.'),
  ('dk_d9_review', 1, 'jun', 'Jun comes over to your desk with his laptop. His inventory API pull request is ready.', '준이 노트북을 들고 당신 자리로 옵니다. 그의 재고 API 풀 리퀘스트가 준비됐습니다.', 'Hi, Derek. Do you have a few minutes to review my pull request?', '안녕하세요, 데릭. 제 풀 리퀘스트 리뷰해 주실 시간 좀 있으세요?', 'Agree to look at it, tell him how to get it to you, and that you need twenty minutes.', '봐 주겠다고 하고, 어떻게 보내면 되는지와 20분이 필요하다는 걸 말하세요.', '[{"all":["send me the link"]},{"all":["twenty minutes"]},{"any":["link"]}]', 'Sure, send me the link. Give me twenty minutes.', '그럼요, 링크 보내 줘요. 20분만 줘요.', '["Not now. Just merge it, and I''ll look at it later.","Sure, send me the link. Give me two hours or so.","Sure. Did you get a chance to look at mine yet?"]', '["지금은 안 돼요. 그냥 머지해요. 나중에 볼게요.","그럼요, 링크 보내 줘요. 두 시간쯤 줘요.","그래요. 그런데 제 것도 봤어요?"]', '["Merge it first? That doesn''t feel right.","Two hours? Oh, okay. I thought it was a small one.","Yes, I did. But could you look at mine first?"]', '["먼저 머지하라고요? 그건 좀 아닌 것 같은데요.","두 시간이요? 아, 네. 작은 건 줄 알았어요.","네, 봤어요. 그런데 제 것부터 봐 주실 수 있어요?"]', '["Say yes, ask for the link, and say how long you need.","Key words: send me the link, twenty minutes"]', '["수락하고, 링크를 달라고 하고, 시간이 얼마나 필요한지 말하세요.","핵심 단어: send me the link, twenty minutes"]', 'jun', 'Thanks! I looked at yours, too. The gift card one.', '고마워요! 저도 데릭 것을 봤어요. 기프트 카드 풀 리퀘스트요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_review', 2, 'jun', 'Twenty minutes later you have left your comments on his code: good overall, one function that does too much. Now it is your turn, and Jun looks like he is holding something back.', '20분 뒤, 그의 코드에 코멘트를 남겼습니다. 전반적으로 좋고, 함수 하나가 너무 많은 일을 합니다. 이제 당신 차례인데, 준은 뭔가 하고 싶은 말을 참는 눈치입니다.', 'Yours looks great. Really.', '데릭 거 좋아 보여요. 진짜로요.', 'You can tell he''s holding something back. Get him to say what he really thinks.', '그가 뭔가 말을 아끼고 있다는 게 보입니다. 진짜 생각을 말하게 하세요.', '[{"all":["hold back"]},{"all":["be honest"]},{"all":["you would change"]}]', 'Don''t hold back. Be honest: is there anything you''d change?', '망설이지 말아요. 솔직하게요. 바꾸고 싶은 거 있어요?', '["Thanks! I worked hard on it. Okay, let''s merge it, then.","Great? Come on. If you found nothing, you didn''t read it.","Don''t hold back. Anything in my inventory API code you''d change?"]', '["고마워요! 공들였거든요. 좋아요, 그럼 머지하죠.","좋다고요? 에이. 아무것도 못 찾았으면 안 읽은 거죠.","망설이지 말아요. 제 재고 API 코드에서 바꿀 거 있어요?"]', '["Oh. Um, sure. If you''re sure.","I did read it! I just... didn''t want to be rude.","The inventory API is mine. You mean the gift card one?"]', '["아. 음, 네. 확실하시다면요.","읽었어요! 그냥... 무례해 보이기 싫었어요.","재고 API는 제 거잖아요. 기프트 카드 거 말씀이시죠?"]', '["A junior may be afraid to criticize a senior. Make it safe.","Key words: don''t hold back, anything you''d change"]', '["후배는 선배를 비판하기 어려워합니다. 편하게 말할 수 있게 해 주세요.","핵심 단어: don''t hold back, anything you''d change"]', 'jun', 'Well, one small thing. There''s a variable called data2. Last week you told me that was a bad name.', '음, 사소한 거 하나요. data2라는 변수가 있어요. 지난주에 저한테 그건 나쁜 이름이라고 하셨잖아요.'),
  ('dk_d9_review', 3, 'jun', 'He is right. It was a placeholder, and you forgot about it. Jun watches your face.', '그의 말이 맞습니다. 임시로 붙여 놓고 잊어버린 이름입니다. 준이 당신의 표정을 살핍니다.', 'Sorry. Is it okay that I said that?', '죄송해요. 제가 그런 말 해도 괜찮은 거죠?', 'He caught you breaking your own rule. Own it with good humor, and say you''ll fix the name.', '당신이 스스로 정한 규칙을 어긴 걸 그가 잡아냈습니다. 유머 있게 인정하고, 이름을 고치겠다고 하세요.', '[{"all":["guilty as charged"]},{"all":["practice what i preach"]},{"any":["rename","renaming"]},{"all":["nice catch"]}]', 'Guilty as charged. I should practice what I preach. I''ll rename it.', '딱 걸렸네요. 남한테 한 말은 저부터 지켜야죠. 이름 바꿀게요.', '["It''s just a placeholder. Nobody''s going to read that part anyway.","Well, it''s different for me. I know what data2 means.","You''re right. I''ll leave a comment explaining it instead of renaming."]', '["그냥 임시 이름이에요. 어차피 그 부분은 아무도 안 읽어요.","음, 저는 경우가 달라요. data2가 뭔지 저는 알거든요.","맞아요. 이름은 그대로 두고 설명하는 주석을 달게요."]', '["Oh. Okay. But you told me placeholders always stick.","Um... that''s what I said last week, too.","A comment? But you told me to just pick a better name."]', '["아. 네. 그런데 임시 이름은 꼭 그대로 남는다고 하셨잖아요.","음... 저도 지난주에 똑같이 말했는데요.","주석이요? 그냥 더 나은 이름을 고르라고 하셨잖아요."]', '["Admit it with a smile, and say what you will do.","Key words: guilty as charged, practice what I preach"]', '["웃으며 인정하고, 어떻게 할지 말하세요.","핵심 단어: guilty as charged, practice what I preach"]', 'jun', 'Phew. I was nervous about reviewing a senior developer.', '휴. 시니어 개발자를 리뷰하려니 긴장했어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_review', 4, 'jun', 'Jun scrolls to his next comment, a little braver now.', '준이 조금 용기를 얻어 다음 코멘트로 내려갑니다.', 'One more. You call the payment service for the balance every single time. I think we should cache it.', '하나 더요. 잔액 조회할 때마다 매번 결제 서비스를 호출하시더라고요. 캐시해야 할 것 같아요.', 'Acknowledge his point, but explain why caching a balance is dangerous: an out-of-date number could let a customer pay with money that''s already gone.', '그의 의견을 인정하되, 잔액을 캐시하면 왜 위험한지 설명하세요. 낡은 숫자 때문에 이미 쓴 돈으로 또 결제할 수 있다고요.', '[{"all":["where you are coming from"]},{"any":["stale"]},{"all":["spend"],"any":["twice"]},{"all":["hold off"]}]', 'I see where you''re coming from, but I''d hold off on caching. A stale balance could let someone spend the same money twice.', '무슨 말인지 알겠어요. 그런데 캐시는 보류할게요. 잔액이 옛날 값이면 같은 돈을 두 번 쓸 수 있거든요.', '["I''ve been doing this for over ten years, Jun. Trust me, I know when to cache and when not to.","Good catch. Let''s cache the balance for an hour. The payment service is slow anyway, so it should make the page a lot faster.","I see where you''re coming from, but caching won''t help. The payment service is already fast enough."]', '["저 이 일 10년 넘게 했어요, 준. 언제 캐시하고 언제 안 할지는 제가 알아요.","잘 잡았어요. 잔액을 한 시간 동안 캐시하죠. 어차피 결제 서비스가 느리니까 페이지가 훨씬 빨라질 거예요.","무슨 말인지 알겠어요. 그런데 캐시해도 소용없어요. 결제 서비스는 이미 충분히 빠르거든요."]', '["Sorry. I didn''t mean to step on your toes.","Really? Okay. But wait, could the balance be out of date?","Really? It took almost a second when I tested it."]', '["죄송해요. 기분 상하게 하려던 건 아니었어요.","정말요? 네. 근데 잠깐, 그럼 잔액이 옛날 값일 수도 있지 않아요?","그래요? 제가 테스트했을 땐 거의 1초 걸렸는데요."]', '["Show that you understood his idea before you give your reason.","Key words: I see where you''re coming from, hold off on, stale"]', '["이유를 말하기 전에 그의 생각을 이해했다는 것을 보여 주세요.","핵심 단어: I see where you''re coming from, hold off on, stale"]', 'jun', 'Oh. I didn''t think about that. Correctness first.', '아. 그건 생각 못 했어요. 정확한 게 먼저군요.'),
  ('dk_d9_review', 5, 'jun', 'Jun moves his cursor to the "Delete comment" button.', '준이 "코멘트 삭제" 버튼으로 커서를 옮깁니다.', 'So should I delete my comment?', '그럼 제 코멘트 지울까요?', 'Tell him to keep the comment, add your reasoning in a note, and leave the door open in case speed becomes a problem.', '코멘트는 남겨 두라고 하고, 당신의 이유를 메모로 덧붙이고, 속도가 문제가 되면 다시 생각해 보겠다고 여지를 남기세요.', '[{"all":["fair question"]},{"all":["open to"]},{"all":["leave it"]}]', 'No, leave it. It was a fair question. I''ll add a note explaining why, and I''m open to changing it if the page gets slow.', '아니요, 그냥 둬요. 타당한 질문이었어요. 왜 그런지 메모를 달아 둘게요. 페이지가 느려지면 바꿀 생각도 있고요.', '["Yes, go ahead and delete it. We already settled it, so there''s really no need to keep it around.","No, leave it there, but I''m not changing it. Caching a balance is never going to happen here, no matter how slow it gets.","No, leave it. I''ll ask Maya to weigh in on it, and she can decide which one of us is right."]', '["네, 그냥 지워요. 이미 얘기로 결론이 났으니까 굳이 코멘트를 남겨 둘 필요는 없어요.","아니요, 그냥 둬요. 그래도 저는 안 바꿔요. 아무리 느려져도 여기서 잔액을 캐시하는 일은 절대 없을 거예요.","아니요, 그냥 둬요. 마야한테 의견을 물어볼게요. 우리 중 누가 맞는지 마야가 정하면 돼요."]', '["Okay... but won''t the next person ask the same question?","Never? Okay. I''ll stop asking, then.","Maya? It''s just a comment. Do we really need her?"]', '["네... 그런데 다음 사람도 똑같은 걸 묻지 않을까요?","절대요? 네. 그럼 더 안 물어볼게요.","마야요? 그냥 코멘트 하나인데요. 꼭 마야까지 필요해요?"]', '["Respect the question even though you said no to the idea.","Key words: a fair question, open to"]', '["제안은 거절했어도 질문은 존중하세요.","핵심 단어: a fair question, open to"]', 'jun', 'That makes sense. I learned something today.', '이해됐어요. 오늘 하나 배웠네요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_d9_review', 6, 'jun', 'Jun closes his laptop.', '준이 노트북을 덮습니다.', 'I''ll split up my function and add the tests, like you said.', '말씀하신 대로 함수 나누고 테스트 추가할게요.', 'Show your appreciation for his review, and invite him out for coffee on you.', '리뷰해 준 것에 고마움을 표하고, 당신이 사는 커피를 마시러 가자고 하세요.', '[{"all":["grab coffee"]},{"all":["grab a coffee"]},{"any":["coffee"]},{"all":["i am buying"]}]', 'Thanks for the careful review. Want to grab coffee later? I''m buying.', '꼼꼼하게 리뷰해 줘서 고마워요. 이따 커피 한잔할래요? 제가 살게요.', '["Good. And next time, keep the nitpicks to a minimum, okay?","Thanks for the careful review. Want to grab lunch at noon? I''m buying.","Great. Send it back to me when it''s done, and I''ll merge it."]', '["좋아요. 그리고 다음엔 사소한 지적은 좀 줄여 줘요, 알았죠?","꼼꼼하게 리뷰해 줘서 고마워요. 열두 시에 점심 같이 먹을래요? 제가 살게요.","좋아요. 다 되면 다시 보내 줘요. 그럼 제가 머지할게요."]', '["Oh. Sorry. I thought you wanted honest feedback.","Lunch? I already ate. Maybe something later?","Will do. Um, was my review okay?"]', '["아. 죄송해요. 솔직한 피드백을 원하시는 줄 알았어요.","점심이요? 저 벌써 먹었어요. 이따가 다른 건 어때요?","그럴게요. 음, 제 리뷰는 괜찮았어요?"]', '["Thank the reviewer, then make a friendly offer.","Key words: grab coffee, I''m buying"]', '["리뷰어에게 고마움을 전하고, 친근하게 제안하세요.","핵심 단어: grab coffee, I''m buying"]', 'jun', 'Sure, how about around three?', '좋아요, 세 시쯤 어때요?'),
  ('dk_w_market', 1, 'mike', 'A sunny weekend. Your cart is full of burger patties, buns, and corn. Mike starts scanning.', '화창한 주말입니다. 카트에 버거 패티와 빵, 옥수수가 가득합니다. 마이크가 바코드를 찍기 시작합니다.', 'Hey, Derek! Whoa, that''s a lot of burgers. Having a party?', '어, 데릭! 와, 버거가 엄청 많네요. 파티해요?', 'Tell him what all this food is for.', '이 많은 음식이 어디에 쓸 건지 말하세요.', '[{"any":["barbecue","bbq","cookout","grilling","grill"]},{"all":["friends over"]}]', 'Yeah, I''m having some friends over for a barbecue this weekend.', '네, 이번 주말에 친구들 불러서 바비큐 하거든요.', '["Yeah, my office is having a team picnic on Monday.","Something like that. Can you just scan them, please?","No party. They were on sale, so I''m stocking up the freezer for the month."]', '["네, 월요일에 회사에서 팀 소풍을 가거든요.","뭐 그런 셈이죠. 그냥 바코드나 좀 찍어 주실래요?","파티는 아니고요. 세일하길래 한 달 치 냉동실 채워 두려고요."]', '["A team picnic on a Monday? Lucky you.","Sure thing. Just making conversation.","On sale? Not the patties. Those are full price."]', '["월요일에 팀 소풍이요? 좋겠네요.","그럼요. 그냥 말 좀 건 거예요.","세일이요? 패티는 정가인데요."]', '["Explain the reason for all the food.","Key words: friends over, barbecue"]', '["음식을 많이 사는 이유를 설명하세요.","핵심 단어: friends over, barbecue"]', 'mike', 'Nice! Perfect weather for it.', '좋네요! 바비큐 하기 딱 좋은 날씨예요.'),
  ('dk_w_market', 2, 'mike', 'Mike holds up your bag of corn.', '마이크가 옥수수 봉지를 들어 보입니다.', 'Heads-up: corn on the cob is five for two dollars this week, and you''ve only got three. Want to grab two more?', '참고로요, 옥수수가 이번 주 다섯 개에 2달러인데 세 개만 담으셨어요. 두 개 더 가져올래요?', 'Thank him for the tip, and go get the extra corn quickly.', '알려 줘서 고맙다고 하고, 얼른 옥수수를 더 가져오세요.', '[{"any":["grab"]},{"all":["be right back"]},{"all":["two more"]},{"all":["good catch"]}]', 'Good catch. I''ll run and grab two more. I''ll be right back.', '잘 봤네요. 얼른 두 개 더 가져올게요. 금방 와요.', '["Good catch. I''ll run and grab three more. I''ll be right back.","No, thanks. Three is plenty. Just ring them up as they are.","Could you go grab them for me? There''s a line behind me."]', '["잘 봤네요. 얼른 세 개 더 가져올게요. 금방 와요.","아뇨, 괜찮아요. 세 개면 충분해요. 그냥 찍어 주세요.","직접 좀 가져다줄래요? 뒤에 줄이 있어서요."]', '["Three? You only need two more to make five.","Your call. You''re paying more for fewer, though.","Sorry, I can''t leave the register."]', '["세 개요? 다섯 개 되려면 두 개만 더 있으면 돼요.","마음대로 하세요. 덜 사고 더 내는 거지만요.","죄송해요, 계산대를 비울 수가 없어요."]', '["Thank him for noticing and say you will return quickly.","Key words: good catch, grab two more, be right back"]', '["알려 줘서 고맙다고 하고 곧 돌아오겠다고 하세요.","핵심 단어: good catch, grab two more, be right back"]', 'mike', 'No problem. I''ll keep ringing you up.', '괜찮아요. 계속 계산하고 있을게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w_market', 3, 'mike', 'You come back with two more ears of corn.', '옥수수 두 개를 더 들고 돌아옵니다.', 'Did you find everything else okay?', '다른 건 다 잘 찾으셨어요?', 'One thing on your list was missing: charcoal. Ask where it is.', '목록에서 하나를 못 찾았습니다. 숯이요. 어디 있는지 물어보세요.', '[{"any":["charcoal","aisle"]},{"all":["could not find"]}]', 'Almost. I couldn''t find the charcoal. Which aisle is it in?', '거의요. 숯을 못 찾았어요. 몇 번 통로에 있어요?', '["Yep, found everything. Thanks for asking, Mike.","Almost. I couldn''t find the hot dog buns. Which aisle?","Not really. This store''s a maze. Why do you keep moving things around?"]', '["네, 다 찾았어요. 물어봐 줘서 고마워요, 마이크.","거의요. 핫도그 빵을 못 찾았어요. 몇 번 통로예요?","아뇨. 이 가게는 미로 같아요. 왜 자꾸 위치를 바꿔요?"]', '["Great! So you''re all set for the grill?","Buns? You''ve got two packs right here.","Sorry about that. Corporate likes to shuffle things."]', '["좋아요! 그럼 그릴 준비는 다 된 거죠?","빵이요? 여기 두 봉지 있잖아요.","죄송해요. 본사가 자꾸 위치를 바꾸네요."]', '["Say what you could not find and ask where it is.","Key words: couldn''t find, charcoal, which aisle"]', '["못 찾은 물건을 말하고 어디 있는지 물어보세요.","핵심 단어: couldn''t find, charcoal, which aisle"]', 'mike', 'Sorry, we''re out. The truck comes Monday. Try Fairview Hardware on Lake Avenue.', '죄송해요, 다 떨어졌어요. 월요일에 들어와요. 레이크 애비뉴의 페어뷰 철물점에 가 보세요.'),
  ('dk_w_market', 4, 'mike', 'Four full paper bags sit at the end of the belt.', '벨트 끝에 가득 찬 종이봉투 네 개가 놓여 있습니다.', 'Your total''s sixty-four twenty. Do you need a hand out to your car with all that?', '총 64달러 20센트예요. 이거 다 차까지 들어다 드릴까요?', 'Turn down the help: you can carry it, and the car is close.', '도움은 사양하세요. 혼자 들 수 있고, 차도 가까이 있습니다.', '[{"any":["manage"]},{"all":["got it"]},{"all":["i am good"]},{"any":["parked"]}]', 'No, thanks. I can manage. I''m parked right out front.', '괜찮아요. 혼자 할 수 있어요. 바로 앞에 주차했어요.', '["Yes, please. I''m parked way out at the back of the lot.","No, thanks. So that''s forty-six twenty, right?","No. I''m not that old, Mike. I can carry bags."]', '["네, 부탁해요. 주차장 저 뒤쪽 끝에 세워 놨어요.","괜찮아요. 그럼 46달러 20센트 맞죠?","아뇨. 저 그렇게 나이 안 들었어요, 마이크."]', '["Sure, let me grab someone to help you.","Sixty-four twenty, Derek. Four bags aren''t cheap.","Whoa, no offense. I ask everybody."]', '["그럼요, 도와줄 사람 부를게요.","64달러 20센트예요, 데릭. 네 봉지면 싸진 않죠.","워, 기분 나쁘라고 한 거 아니에요. 다들 물어봐요."]', '["Turn down the help politely.","Key words: I can manage, parked out front"]', '["도움을 정중히 사양하세요.","핵심 단어: I can manage, parked out front"]', 'mike', 'Alright. Enjoy the barbecue!', '알겠어요. 바비큐 맛있게 하세요!'),
  ('dk_w_park', 1, 'carl', 'A sunny morning in Seaside Park. Carl is on his usual bench with the newspaper.', '시사이드 공원의 화창한 아침입니다. 칼이 늘 앉는 벤치에서 신문을 보고 있습니다.', 'Well, if it isn''t Derek! Haven''t seen you at the bus stop lately. What have you been up to?', '아니, 데릭 아닌가! 요즘 버스 정류장에서 통 못 봤네. 어떻게 지냈나?', 'Explain you''ve been swamped at the office, and this weekend you''re finally tackling the garden chores.', '회사 일로 정신이 없었다고 하고, 이번 주말엔 드디어 마당을 손볼 거라고 하세요.', '[{"all":["yard work"]},{"any":["lawn","yard","mowing"]},{"any":["crazy","busy","hectic"]}]', 'Hey, Carl! Work''s been crazy. I''m finally catching up on yard work this weekend.', '안녕하세요, 칼! 일이 정신없었어요. 이번 주말에야 밀린 마당 일을 하고 있어요.', '["Hey, Carl! I''ve been on vacation in Mexico. Just got back last night.","Hey, Carl! Honestly, it''s been awful. My manager says I can''t delegate to save my life.","Oh, hi, Carl. Not much. Listen, I''m kind of in a hurry right now."]', '["안녕하세요, 칼! 멕시코로 휴가 갔다가 어젯밤에 막 돌아왔어요.","안녕하세요, 칼! 솔직히 최악이었어요. 매니저가 저보고 일을 맡길 줄을 전혀 모른대요.","아, 안녕하세요, 칼. 별일 없어요. 저기, 지금 좀 바빠서요."]', '["Mexico? Funny, I saw your car in the driveway all week.","Whoa, that''s a lot for a Saturday morning.","Oh. Well, don''t let me keep you."]', '["멕시코? 이상하네, 일주일 내내 자네 차가 진입로에 있던데.","어이쿠, 주말 아침부터 무거운 얘기로구먼.","아. 그럼 붙잡지 않겠네."]', '["Say how work has been and what you are doing now.","Key words: crazy, catching up on yard work"]', '["일이 어땠는지, 지금 무엇을 하는지 말하세요.","핵심 단어: crazy, catching up on yard work"]', 'carl', 'Good man. A lawn won''t mow itself.', '잘하고 있구먼. 잔디가 저절로 깎이진 않으니까.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w_park', 2, 'carl', 'Carl folds his newspaper.', '칼이 신문을 접습니다.', 'Speaking of which, how''s that old mower of yours? Still giving you trouble?', '말 나온 김에, 그 낡은 잔디 깎는 기계는 어떤가? 아직도 말썽인가?', 'Describe the problem: the engine is dead, probably the spark plug. Ask for his help.', '문제를 설명하세요. 엔진이 안 돌고, 아마 점화 플러그 문제 같습니다. 그에게 도움을 청하세요.', '[{"all":["will not start"]},{"all":["take a look"]},{"all":["taking a look"]},{"all":["spark plug"]}]', 'It won''t start. I think it''s the spark plug. Would you mind taking a look sometime?', '시동이 안 걸려요. 점화 플러그 같아요. 언제 한번 봐 주실 수 있어요?', '["It won''t stop leaking oil. I think it''s the gas tank. Would you mind taking a look?","It won''t start. You fixed buses, so you can come fix it today, right?","It''s working great now, actually. I had it fixed at the hardware store."]', '["기름이 계속 새요. 연료 탱크 같아요. 언제 한번 봐 주실 수 있어요?","시동이 안 걸려요. 버스 고치셨으니까 오늘 와서 고쳐 주실 수 있죠?","사실 지금은 아주 잘 돌아가요. 지난주에 철물점에 맡겨서 고쳤거든요."]', '["Leaking oil? Last time you said it wouldn''t even start.","Today? Pretty bossy for a fella asking a favor.","Fixed? Then what''s that sputtering I hear from your yard?"]', '["기름이 샌다고? 지난번엔 시동도 안 걸린다더니.","오늘? 부탁하는 사람치곤 꽤 당당하구먼.","고쳤다고? 그럼 자네 마당에서 들리던 털털 소리는 뭔가?"]', '["Describe the problem, then ask politely with \\"Would you mind …ing?\\"","Key words: won''t start, would you mind taking a look"]', '["문제를 설명한 뒤 \\"Would you mind …ing?\\"로 정중히 부탁하세요.","핵심 단어: won''t start, would you mind taking a look"]', 'carl', 'For you? Sure. I fixed buses for thirty years. A mower is nothing.', '자네 부탁인데, 그럼. 버스를 30년 고쳤어. 잔디 깎는 기계쯤이야.'),
  ('dk_w_park', 3, 'carl', 'He takes a small notebook out of his shirt pocket.', '그가 셔츠 주머니에서 작은 수첩을 꺼냅니다.', 'I''ll come by this afternoon. River Road, right? The house with the blue door?', '오늘 오후에 들르지. 리버 로드 맞지? 파란 문 있는 집?', 'Confirm the address, and invite him to your cookout that afternoon. You''ll start grilling at 4.', '주소가 맞다고 하고, 그날 오후 바비큐에 초대하세요. 네 시에 굽기 시작합니다.', '[{"any":["barbecue","bbq","cookout","grill","burgers"]},{"all":["stay for"]},{"all":["come over"]}]', 'That''s the one. And stay for the barbecue! I''m firing up the grill around four.', '거기 맞아요. 바비큐도 드시고 가세요! 네 시쯤 그릴에 불 붙일 거예요.', '["That''s the one. And stay for the barbecue! I''m firing up the grill around seven.","No, it''s the one with the red door. And stay for the barbecue at four!","That''s the one. Come around four, fix the mower, and then you can head home."]', '["거기 맞아요. 바비큐도 드시고 가세요! 일곱 시쯤 그릴에 불 붙일 거예요.","아뇨, 빨간 문 집이에요. 네 시에 바비큐도 드시고 가세요!","거기 맞아요. 네 시쯤 오셔서 기계 고쳐 주시고, 그다음엔 가시면 돼요."]', '["Seven? I''m usually in my pajamas by then.","Red? I could''ve sworn it was blue.","Well, all right. Like calling in a hired hand, huh?"]', '["일곱 시? 그 시간엔 난 보통 잠옷 차림이야.","빨간 문? 분명 파란색이었던 것 같은데.","흠, 알겠네. 일꾼 부르듯 하는구먼."]', '["Confirm, then invite him to stay and eat.","Key words: stay for the barbecue, fire up the grill"]', '["맞다고 확인하고, 남아서 먹고 가라고 초대하세요.","핵심 단어: stay for the barbecue, fire up the grill"]', 'carl', 'Burgers? You don''t have to ask me twice.', '버거? 두 번 말할 필요 없지.'),
  ('dk_w_park', 4, 'carl', 'Carl writes "4 p.m." in his notebook.', '칼이 수첩에 "오후 4시"라고 적습니다.', 'What can I bring?', '뭘 가져갈까?', 'He doesn''t need to bring anything. You have it all handled.', '아무것도 안 가져와도 됩니다. 다 준비해 뒀거든요.', '[{"all":["bring yourself"]},{"any":["covered","nothing"]},{"all":["all set"]}]', 'Just bring yourself. I''ve got everything covered.', '그냥 몸만 오세요. 제가 다 준비해 놨어요.', '["Bring a side dish and some drinks, if you can.","Nothing. Honestly, your cooking isn''t my thing.","Just bring yourself. I''m grilling hot dogs, not burgers."]', '["곁들일 음식이랑 음료 좀 가져와 주세요.","됐어요. 솔직히 칼 요리는 입맛에 안 맞아서요.","몸만 오세요. 버거 말고 핫도그 구워요."]', '["Drinks and a side? Sure, I can manage that.","Well! Now I''m definitely bringing my potato salad.","Hot dogs? Mike says you bought every burger in the store."]', '["음료랑 곁들일 거? 그래, 그쯤이야.","허! 이제 내 감자 샐러드는 꼭 가져가야겠군.","핫도그? 마이크 말로는 가게 버거를 싹쓸이했다던데."]', '["A host often says guests do not need to bring anything.","Key words: just bring yourself, covered"]', '["주인은 손님에게 아무것도 가져올 필요 없다고 말하곤 합니다.","핵심 단어: just bring yourself, covered"]', 'carl', 'I''ll bring my potato salad anyway. It''s famous on three bus routes.', '그래도 내 감자 샐러드는 가져가지. 버스 노선 세 개에서 유명하거든.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w_park', 5, 'carl', 'Your phone buzzes in your pocket. It is only a message from a friend.', '주머니에서 전화기가 울립니다. 친구가 보낸 메시지일 뿐입니다.', 'You young people work too hard. They don''t call you on the weekend, do they?', '젊은 사람들은 일을 너무 많이 해. 주말엔 연락 안 오지?', 'Explain that you''re the one who gets paged this week, though nothing has happened yet, and you hope it stays that way.', '이번 주는 당신이 호출 담당이지만 아직 아무 일도 없었고, 계속 그러길 바란다고 하세요.', '[{"all":["on call"]},{"all":["knock on wood"]},{"any":["quiet"]}]', 'I''m on call this week, but it''s been quiet so far. Knock on wood.', '이번 주는 온콜이라서요. 그래도 아직까지는 조용해요. 부정 타지 말아야죠.', '["I''m on call this week, and it''s been crazy. I got paged twice last night.","Never. My phone''s off all weekend, every weekend.","It''s just a friend. Why are you looking at my phone?"]', '["이번 주는 온콜인데 정신없어요. 어젯밤에만 두 번 호출받았어요.","절대요. 주말엔 매주 전화기를 아예 꺼 두거든요. 연락 올 일이 없어요.","그냥 친구 문자예요. 근데 왜 제 전화기를 들여다보세요?"]', '["Twice last night? You don''t look like you were up.","Then who''s buzzing you right now?","Easy, son. Just making small talk."]', '["어젯밤에 두 번? 밤새운 얼굴은 아닌데.","그럼 지금 울리는 건 누군가?","진정하게. 그냥 해 본 소리야."]', '["\\"Knock on wood\\" is said so that good luck continues.","Key words: on call, quiet, knock on wood"]', '["knock on wood는 행운이 이어지길 바랄 때 하는 말입니다.","핵심 단어: on call, quiet, knock on wood"]', 'carl', 'Knock on wood is right. See you at four, Derek!', '그래, 부정 타면 안 되지. 네 시에 보세, 데릭!'),
  ('dk_w2_brunch', 1, 'rosa', 'Sunday. It has been raining since dawn. The diner''s windows are fogged up, and every booth is taken. You shake off your umbrella at the door.', '일요일입니다. 새벽부터 비가 옵니다. 다이너 창문에는 김이 서렸고 부스 자리는 모두 찼습니다. 문 앞에서 우산의 물기를 텁니다.', 'Derek! Come in out of the rain, hon. It''s a twenty-minute wait for a booth, or you can sit at the counter right now.', '데릭! 비 맞지 말고 얼른 들어와요. 부스는 20분 기다려야 하고, 카운터는 지금 바로 앉을 수 있어요.', 'Take the seat that''s free now; you''re not in any rush.', '지금 비어 있는 자리에 앉겠다고 하세요. 오늘은 바쁠 게 없어요.', '[{"all":["fine by me"]},{"all":["in no hurry"]},{"any":["counter"]}]', 'The counter''s fine by me. I''m in no hurry today.', '카운터면 좋아요. 오늘은 급할 거 없어요.', '["A booth for two, please. I don''t mind the wait.","Can''t you squeeze me into a booth? I''m a regular.","The counter''s fine. Can you hurry, though? I''m starving."]', '["두 사람 부스로 주세요. 기다려도 괜찮아요.","부스에 좀 끼워 주면 안 돼요? 단골이잖아요.","카운터 좋아요. 근데 빨리 돼요? 배고파요."]', '["Two? Is someone joining you, hon?","Sorry, hon. Regular or not, there''s a wait.","I''ll do my best, but the kitchen''s slammed."]', '["두 분이요? 누가 같이 와요?","미안해요. 단골이어도 기다려야 해요.","최대한 해 볼게요. 그런데 주방이 정신없어요."]', '["Choose the seat and say you have time.","Key words: fine by me, in no hurry"]', '["자리를 고르고 시간 여유가 있다고 말하세요.","핵심 단어: fine by me, in no hurry"]', 'rosa', 'That''s what Sundays are for. Coffee''s on its way.', '일요일은 그러라고 있는 거죠. 커피 금방 가져올게요.'),
  ('dk_w2_brunch', 2, 'rosa', 'She pours your coffee and points her pencil at the board.', '그녀가 커피를 따르고 연필로 메뉴판을 가리킵니다.', 'What''ll it be? The brunch menu''s on the board.', '뭐로 할래요? 브런치 메뉴는 칠판에 있어요.', 'Order the veggie omelet and hash browns, cooked the way you like them: really well done and crunchy.', '채소 오믈렛에 해시 브라운을 주문하세요. 해시 브라운은 당신 취향대로, 아주 잘 익혀서 바삭바삭하게요.', '[{"all":["extra crispy"]},{"any":["omelet","omelette"]},{"all":["hash browns"]}]', 'I''ll have the veggie omelet with hash browns. Could you make them extra crispy?', '채소 오믈렛에 해시 브라운으로 할게요. 해시 브라운은 아주 바삭하게 해 주실래요?', '["I''ll have the ham and cheese omelet with hash browns. Could you make them extra crispy?","Veggie omelet, hash browns. Crispy this time, not like last week.","What do you recommend? I can''t really read the board from here."]', '["햄 치즈 오믈렛에 해시 브라운으로 할게요. 해시 브라운은 아주 바삭하게 해 주실래요?","채소 오믈렛, 해시 브라운. 이번엔 바삭하게요. 지난주처럼 말고요.","뭐가 맛있어요? 여기서는 칠판 글씨가 잘 안 보여서 못 읽겠어요."]', '["Ham and cheese? That''s new for you, hon.","Well, somebody woke up on the wrong side of the bed.","Everything''s good, hon. What are you in the mood for?"]', '["햄 치즈요? 웬일이에요.","어머, 누가 아침부터 기분이 안 좋으시네.","다 맛있어요. 뭐가 당겨요?"]', '["Order, then say exactly how you like it cooked.","Key words: omelet, hash browns, extra crispy"]', '["주문하고, 어떻게 익히면 좋은지 정확히 말하세요.","핵심 단어: omelet, hash browns, extra crispy"]', 'rosa', 'Extra crispy, you got it.', '아주 바삭하게, 알겠어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_brunch', 3, 'rosa', 'She keeps writing.', '그녀가 계속 받아 적습니다.', 'It comes with toast. Wheat or sourdough? Butter on it?', '토스트가 같이 나와요. 통밀이요, 사워도우요? 버터 발라 드릴까요?', 'Pick the sourdough, and you''d like to butter it yourself.', '사워도우를 고르고, 버터는 직접 바르고 싶다고 하세요.', '[{"all":["on the side"]},{"any":["sourdough","wheat"]}]', 'Sourdough, please, with the butter on the side.', '사워도우로 주세요. 버터는 따로 주시고요.', '["Wheat toast, please, with the butter on the side.","Sourdough, please, and lots of butter on it.","No toast. Can I swap it for pancakes, free?"]', '["통밀 토스트로 주세요. 버터는 따로 주시고요.","사워도우로 주세요. 버터 듬뿍 발라서요.","토스트는 빼고요. 팬케이크로 공짜로 바꿔 줘요?"]', '["Wheat? I thought you were a sourdough guy.","Lots of butter? Your doctor won''t like that.","Pancakes are extra, hon. Toast is what it comes with."]', '["통밀이요? 사워도우파인 줄 알았는데.","버터 듬뿍이요? 의사 선생님이 싫어하겠네.","팬케이크는 추가 요금이에요. 원래 토스트가 나와요."]', '["\\"On the side\\" = in a separate dish, not on the food.","Key words: sourdough, on the side"]', '["on the side는 음식 위가 아니라 따로 담아 달라는 뜻입니다.","핵심 단어: sourdough, on the side"]', 'rosa', 'Sourdough, butter on the side. Be right back, hon.', '사워도우에 버터는 따로. 금방 올게요.'),
  ('dk_w2_brunch', 4, 'rosa', 'Your plate is half empty. Rosa comes by with the coffee pot.', '접시가 절반쯤 비었습니다. 로사가 커피포트를 들고 옵니다.', 'More coffee? So how''s that new kid doing? He was in here yesterday, telling me all about some big trip.', '커피 더 줄까요? 그래서 그 신입은 잘하고 있어요? 어제 여기 와서 무슨 큰 출장 얘기를 한참 하던데.', 'Accept a little more coffee, and share Jun''s big news with real pride.', '커피를 조금 더 받고, 준의 큰 소식을 진심으로 자랑스럽게 전하세요.', '[{"all":["warm up"]},{"any":["proud","prouder"]},{"all":["top off"]},{"all":["first deal"]}]', 'Just a warm-up, thanks. He closed his first deal this week. I couldn''t be prouder.', '조금만 더 주세요, 고마워요. 이번 주에 첫 계약을 따냈어요. 이보다 자랑스러울 수가 없어요.', '["Just a warm-up, thanks. He lost the deal, but he learned a lot from it.","Just a warm-up, thanks. He closed his first deal. I taught him everything he knows.","No more coffee, thanks. And I''d rather not talk about work on a Sunday."]', '["조금만 더 주세요, 고마워요. 계약은 놓쳤는데, 그래도 많이 배웠대요.","조금만 더 주세요, 고마워요. 첫 계약을 따냈어요. 다 제가 가르친 거예요.","커피는 됐어요, 고마워요. 그리고 일요일엔 일 얘기 안 하고 싶어요."]', '["Aw, that''s too bad. He seemed so excited.","Ha! Modest, aren''t we?","Fair enough, hon. Sundays are for resting."]', '["아이고, 안됐네요. 그렇게 들떠 있더니.","하! 겸손도 하셔라.","그래요. 일요일은 쉬는 날이죠."]', '["A \\"warm-up\\" is a little more hot coffee in your cup.","Key words: a warm-up, closed his first deal, couldn''t be prouder"]', '["warm-up은 잔에 뜨거운 커피를 조금 더 채워 주는 것입니다.","핵심 단어: a warm-up, closed his first deal, couldn''t be prouder"]', 'rosa', 'Good for him! He had a good teacher, I bet.', '잘됐네요! 좋은 선생님을 만난 덕이겠죠.'),
  ('dk_w2_brunch', 5, 'rosa', 'The omelet was huge. You put down your fork.', '오믈렛이 아주 컸습니다. 포크를 내려놓습니다.', 'You''re slowing down. Want me to wrap that up for you?', '속도가 줄었네요. 그거 싸 드릴까요?', 'Ask to take the leftovers home, and ask for the bill without rushing her.', '남은 음식을 싸 가고 싶다고 하고, 그녀를 재촉하지 않으면서 계산서를 부탁하세요.', '[{"any":["box"]},{"all":["get a chance"]},{"all":["to go"]}]', 'Yes, please. Could I get a box for the rest? And the check, whenever you get a chance.', '네, 부탁해요. 남은 거 담을 상자 하나 주실래요? 계산서도요, 시간 날 때요.', '["No, thanks. I''ll finish it here. Could I get some more coffee, though?","Yes, box it up, and bring me the check right now, please. I really need to get going soon.","Yes, please. Could you box it up and split the check between two people?"]', '["아니요, 괜찮아요. 여기서 다 먹을게요. 대신 커피 좀 더 주실래요?","네, 싸 주세요. 그리고 계산서 지금 당장 갖다주세요. 진짜 빨리 가 봐야 해요.","네, 부탁해요. 싸 주시고, 계산서는 두 사람으로 나눠 주실래요?"]', '["Sure, hon, but you looked done to me.","Okay, okay. Weren''t you in no hurry?","Two? You came in alone, hon."]', '["그래요. 근데 다 드신 것 같던데.","알았어요, 알았어요. 급할 거 없다면서요?","두 사람이요? 혼자 오셨잖아요."]', '["Taking leftovers home is normal in the US.","Key words: a box for the rest, whenever you get a chance"]', '["미국에서는 남은 음식을 싸 가는 것이 흔한 일입니다.","핵심 단어: a box for the rest, whenever you get a chance"]', 'rosa', 'One box, one check. That''s sixteen twenty-four with tax.', '상자 하나, 계산서 하나. 세금 포함 16달러 24센트예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_brunch', 6, 'rosa', 'The check says $16.24. You take a twenty out of your wallet. About eighteen percent of fifteen dollars is $2.70.', '계산서에는 16.24달러라고 적혀 있습니다. 지갑에서 20달러짜리를 꺼냅니다. 15달러의 18퍼센트쯤이면 2.70달러입니다.', 'No rush, hon.', '천천히 해요.', 'Pay with your twenty, and leave a tip of about $2.70.', '20달러로 내고, 팁은 2.70달러쯤 남기세요.', '[{"all":["dollar back"]},{"all":["rest is for you"]},{"all":["rest is yours"]}]', 'Here''s a twenty. Could I get a dollar back? The rest is for you.', '여기 20달러요. 1달러만 거슬러 주실래요? 나머지는 드릴게요.', '["Here''s a twenty. Could I get three dollars back? The rest is for you.","Here''s a twenty. I''ll need all the change back, every cent.","Can I pay by card instead? I''ll add the tip on there."]', '["여기 20달러요. 3달러 거슬러 주실래요? 나머지는 드릴게요.","여기 20달러요. 거스름돈은 한 푼도 빠짐없이 다 주세요.","카드로 내도 돼요? 팁은 거기에 같이 넣을게요."]', '["Three back? That leaves me less than a dollar, hon.","Sure thing. Every cent.","Sure, but you''ve already got a twenty out."]', '["3달러요? 그럼 저한테 1달러도 안 남는데요.","그럼요. 한 푼도 빠짐없이요.","되긴 하는데, 벌써 20달러 꺼내셨잖아요."]', '["With cash, say how much change you want; the rest is the tip.","Key words: a dollar back, the rest is for you"]', '["현금으로 낼 때는 거스름돈을 얼마 받을지 말하세요. 나머지가 팁입니다.","핵심 단어: a dollar back, the rest is for you"]', 'rosa', 'You''re a sweetheart. Stay dry out there!', '정말 다정하시네요. 비 맞지 말고 가요!'),
  ('dk_w2_market', 1, 'mike', 'Fairview Market on a warm Saturday. This week''s flyer says vanilla ice cream is buy one, get one free, but the shelf in the freezer is empty. You walk up to Mike''s lane.', '따뜻한 토요일의 페어뷰 마켓입니다. 이번 주 전단에는 바닐라 아이스크림이 하나 사면 하나 더라고 되어 있는데, 냉동고 선반이 텅 비어 있습니다. 마이크의 계산대로 갑니다.', 'Hey, Derek! Back again? Did you find everything okay?', '안녕하세요, 데릭! 또 오셨네요? 찾으시는 건 다 찾으셨어요?', 'Tell him the sale ice cream from the flyer is gone from the freezer, and ask if there''s more in the stockroom.', '전단에 나온 할인 아이스크림이 냉동고에 없다고 하고, 창고에 더 있는지 물어보세요.', '[{"all":["sold out"]},{"all":["in the back"]},{"any":["flyer"]}]', 'Not quite. The ice cream in the flyer is sold out. Do you have any more in the back?', '다는 아니에요. 전단에 나온 아이스크림이 다 팔렸더라고요. 창고에 더 있어요?', '["Not quite. The chocolate ice cream in the flyer is sold out. Is there any more in stock?","No. Your sale ice cream is gone. Why advertise it if you don''t have it?","Yes, thanks. Just this bag of chips, and that''s everything for today."]', '["다는 아니에요. 전단에 나온 초콜릿 아이스크림이 다 팔렸더라고요. 재고 더 있어요?","아니요. 할인 아이스크림이 없던데요. 없는 걸 왜 광고해요?","네, 고마워요. 이 감자칩 한 봉지만 계산하면 오늘은 다예요."]', '["Chocolate? The flyer one''s vanilla. Let me check anyway.","Whoa, easy. I don''t write the flyers, man.","Great. No ice cream today? It''s a hot one."]', '["초콜릿이요? 전단에 나온 건 바닐라예요. 그래도 확인해 볼게요.","워, 진정하세요. 전단은 제가 만드는 게 아니에요.","좋아요. 오늘 아이스크림은 안 사세요? 이렇게 더운데."]', '["Say what is missing, and ask about the stockroom.","Key words: sold out, in the back"]', '["없는 물건을 말하고, 창고에 있는지 물어보세요.","핵심 단어: sold out, in the back"]', 'mike', 'Let me check. Nope, we''re cleaned out. It went fast in this heat.', '확인해 볼게요. 없네요, 싹 다 나갔어요. 날이 더우니 금방 팔렸어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_market', 2, 'mike', 'Mike puts down the store phone.', '마이크가 매장 전화기를 내려놓습니다.', 'Sorry about that. The next truck comes on Tuesday.', '죄송해요. 다음 트럭은 화요일에 와요.', 'Ask for a slip that lets you pay the sale price later, once it''s back in stock.', '다시 들어오면 나중에 할인 가격으로 살 수 있게 해 주는 쪽지를 달라고 하세요.', '[{"all":["rain check"]},{"any":["raincheck"]},{"all":["sale price"]}]', 'Could I get a rain check, so I can get the sale price next week?', '레인 체크 하나 받을 수 있을까요? 다음 주에 할인 가격으로 사게요.', '["Could you hold two for me when the truck comes on Tuesday?","Could I just get the sale price on the fancy brand instead?","Could I get a rain check, so I can come back for the sale price tomorrow?"]', '["화요일에 트럭 오면 두 개만 따로 빼 두실 수 있어요?","그럼 대신 비싼 브랜드를 할인 가격에 주시면 안 돼요?","레인 체크 하나 받을 수 있을까요? 내일 다시 와서 할인 가격으로 사게요."]', '["Sorry, we can''t hold stock. Store policy.","Sorry, I can''t change prices at the register.","Tomorrow? The truck doesn''t come till Tuesday."]', '["죄송해요, 물건을 따로 빼 둘 수는 없어요. 매장 규정이에요.","죄송해요, 계산대에서 가격을 바꿀 수는 없어요.","내일이요? 트럭은 화요일에나 와요."]', '["Stores give a slip that keeps the sale price for later.","Key words: rain check, sale price"]', '["가게에서는 나중에도 할인 가격으로 살 수 있는 쪽지를 써 줍니다.","핵심 단어: rain check, sale price"]', 'mike', 'Sure thing. I''ll write you one. It''s good for thirty days.', '그럼요. 하나 써 드릴게요. 30일 동안 쓸 수 있어요.'),
  ('dk_w2_market', 3, 'mike', 'He takes a pad of slips from under the register.', '그가 계산대 아래에서 쪽지 묶음을 꺼냅니다.', 'How many do you want on it? There''s a limit of two deals per customer.', '몇 개로 적어 드릴까요? 손님 한 분당 두 개까지예요.', 'Take the most he''s allowed to give you.', '허용되는 최대 수량으로 받으세요.', '[{"all":["put me down"]},{"any":["two","2"]}]', 'Then put me down for two, please.', '그럼 두 개로 적어 주세요.', '["Can you make it four? I''ll be quick.","Then put me down for three, please.","Just write today''s date on it, please."]', '["네 개로 안 될까요? 금방 할게요.","그럼 세 개로 적어 주세요.","오늘 날짜만 적어 주세요."]', '["Sorry, two''s the limit. Nothing I can do.","Three? The limit''s two, remember?","Sure, but how many do you want on it?"]', '["죄송해요, 두 개가 한도예요. 저도 어쩔 수 없어요.","세 개요? 한도가 두 개라니까요.","네, 그런데 몇 개로 적어 드려요?"]', '["\\"Put me down for …\\" = write my name next to that number.","Key words: put me down for two"]', '["\\"Put me down for …\\"는 그 수량으로 내 이름을 적어 달라는 뜻입니다.","핵심 단어: put me down for two"]', 'mike', 'Two it is. Here''s your slip. Just show it at the register.', '두 개로 했어요. 여기 쪽지요. 계산할 때 보여 주기만 하면 돼요.'),
  ('dk_w2_market', 4, 'mike', 'You still need dessert for four o''clock.', '네 시에 가져갈 디저트가 여전히 필요합니다.', 'Do you still need ice cream for today? The store brand isn''t on sale, but it''s a dollar cheaper anyway.', '오늘 먹을 아이스크림은 아직 필요하세요? 자체 브랜드는 할인은 안 하는데, 그래도 1달러 더 싸요.', 'Accept the cheaper store brand: at a backyard cookout, no one will notice.', '더 싼 자체 브랜드로 하세요. 뒷마당 바비큐에서는 아무도 눈치채지 못할 거예요.', '[{"all":["that will do"]},{"all":["thatll do"]},{"all":["tell the difference"]},{"all":["store brand"]}]', 'That''ll do. At a barbecue, nobody will be able to tell the difference.', '그거면 돼요. 바비큐에서는 아무도 차이를 모를 거예요.', '["No thanks. Store brand tastes like cardboard. I''ll skip dessert.","That''ll do. Since it''s a dollar more, though, I''ll just take one carton.","That''ll do. Can I use my rain check on it today, then?"]', '["됐어요. 자체 브랜드는 종이 맛이 나요. 디저트는 그냥 안 할래요.","그거면 돼요. 근데 1달러 더 비싸니까 한 통만 살게요.","그거면 돼요. 그럼 레인 체크를 오늘 이걸로 써도 돼요?"]', '["Hey, I eat that stuff! Your call, though.","A dollar less, actually. It''s the cheaper one.","No, that''s only good for the sale brand."]', '["에이, 저 그거 먹는데요! 뭐, 알아서 하세요.","사실 1달러 싸요. 더 싼 거예요.","아니요, 그건 할인 브랜드에만 쓸 수 있어요."]', '["Accept the cheaper substitute cheerfully.","Key words: that''ll do, tell the difference"]', '["더 싼 대체품을 기분 좋게 받아들이세요.","핵심 단어: that''ll do, tell the difference"]', 'mike', 'Your secret''s safe with me. That''s four forty-nine.', '비밀은 지켜 드릴게요. 4달러 49센트예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_market', 5, 'mike', 'Mike puts the ice cream in an insulated bag.', '마이크가 아이스크림을 보냉 봉투에 담습니다.', 'Oh, and did the hardware store have your charcoal last week?', '아, 그리고 지난주에 철물점에 숯 있었어요?', 'Tell him his suggestion worked out, and thank him for it.', '그가 알려 준 게 잘 통했다고 하고, 고마워하세요.', '[{"all":["thanks for the tip"]},{"all":["saved the day"]},{"all":["thank you for the tip"]}]', 'They did. Thanks for the tip. You saved the day.', '있었어요. 알려 줘서 고마워요. 덕분에 살았어요.', '["They didn''t, but the gas station had some. Thanks anyway.","Yeah, they did. Kind of pricey there, though.","I''m using gas this time. Charcoal takes too long."]', '["없었는데, 주유소에 좀 있더라고요. 그래도 고마워요.","네, 있었어요. 거기 좀 비싸긴 하더라고요.","이번엔 가스로 해요. 숯은 너무 오래 걸려요."]', '["Huh. Sorry they let you down.","Well, better than nothing, right?","Oh. I thought you were grilling with charcoal."]', '["흠. 거기 없었다니 아쉽네요.","그래도 없는 것보단 낫죠?","아. 숯으로 구우시는 줄 알았어요."]', '["Here \\"tip\\" means a piece of advice, not money.","Key words: thanks for the tip, saved the day"]', '["여기서 tip은 돈이 아니라 도움이 되는 정보라는 뜻입니다.","핵심 단어: thanks for the tip, saved the day"]', 'mike', 'Glad to hear it. Enjoy the barbecue, and don''t let that melt!', '다행이네요. 바비큐 맛있게 하시고, 그거 녹지 않게 하세요!'),
  ('dk_w2_mower', 1, 'carl', 'Saturday, sunny and warm. Carl pulls up in front of your house with your lawn mower in the back of his pickup.', '토요일, 맑고 따뜻합니다. 칼이 픽업트럭 짐칸에 당신의 잔디 깎는 기계를 싣고 집 앞에 차를 댑니다.', 'Special delivery! She runs like new. It wasn''t the spark plug, by the way. The carburetor was all gummed up.', '특별 배송이야! 새것처럼 잘 돌아가. 그나저나 점화 플러그 문제가 아니었네. 기화기가 찌꺼기로 꽉 막혔더라고.', 'Thank him warmly: thanks to him, you didn''t have to take it anywhere to get it fixed.', '진심으로 고마워하세요. 그 덕분에 어디 가져가서 고칠 필요가 없었어요.', '[{"all":["thank you enough"]},{"all":["saved me a trip"]}]', 'Carl, I can''t thank you enough. You saved me a trip to the repair shop.', '칼, 뭐라고 감사해야 할지 모르겠어요. 덕분에 수리점에 안 가도 됐어요.', '["Thanks, Carl. I knew it was the spark plug. You saved me a trip.","Took you long enough. I needed it for the yard last weekend.","Thanks, Carl. But what''s a carburetor? Is that something I should replace?"]', '["고마워요, 칼. 점화 플러그 문제일 줄 알았어요. 덕분에 안 가도 됐네요.","꽤 오래 걸리셨네요. 지난 주말에 마당 정리하려고 했는데.","고마워요, 칼. 그런데 기화기가 뭐예요? 그거 갈아야 하는 거예요?"]', '["Spark plug? Weren''t you listening? It was the carburetor.","Well, excuse me. Next time take it to the shop.","Nah, just needed cleaning out. She''s fine now."]', '["점화 플러그? 내 말 안 들었나? 기화기였다니까.","거참, 미안하게 됐네. 다음엔 가게에 맡기게.","아니, 청소만 하면 됐어. 이제 멀쩡해."]', '["A big favor deserves more than \\"thanks\\".","Key words: can''t thank you enough, saved me a trip"]', '["큰 도움에는 thanks보다 더 큰 말이 어울립니다.","핵심 단어: can''t thank you enough, saved me a trip"]', 'carl', 'Those shops charge ninety bucks just to look at it. Robbery.', '그런 가게는 들여다보기만 해도 90달러를 받아. 날강도지.'),
  ('dk_w2_mower', 2, 'carl', 'You pull the cord. The engine starts on the first try.', '줄을 당깁니다. 엔진이 한 번에 걸립니다.', 'Hear that? Purring like a kitten.', '들리나? 고양이처럼 그르렁거리잖아.', 'Offer to pay for whatever parts he bought, and don''t take no for an answer.', '그가 산 부품값을 내겠다고 하고, 거절해도 물러서지 마세요.', '[{"all":["owe you"]},{"any":["insist"]},{"all":["pay you back"]}]', 'What do I owe you for the parts? I insist.', '부품값은 얼마 드리면 돼요? 꼭 드리고 싶어요.', '["Here''s ninety. That''s what the shop would charge.","Nice. How often should I change the oil on it?","What do I owe you for the spark plug? I insist."]', '["여기 90달러요. 가게에 맡겼으면 그만큼 냈을 거예요.","좋네요. 오일은 얼마나 자주 갈아야 해요?","점화 플러그값은 얼마 드리면 돼요? 꼭 드릴게요."]', '["Put that away. I''m not a repair shop.","Every spring. Read the manual, son.","It wasn''t the spark plug. I told you."]', '["넣어 두게. 내가 수리점인가.","봄마다 한 번. 설명서 좀 읽게, 이 사람아.","점화 플러그가 아니었다니까. 말했잖나."]', '["Offer to pay at least for the parts. \\"I insist\\" shows you mean it.","Key words: what do I owe you, I insist"]', '["적어도 부품값은 내겠다고 하세요. \\"I insist\\"는 진심이라는 표시입니다.","핵심 단어: what do I owe you, I insist"]', 'carl', 'Eleven dollars for a gasket. Keep your money. Buy me a coffee sometime.', '개스킷 하나에 11달러 들었네. 돈은 넣어 두게. 언제 커피나 한 잔 사.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_mower', 3, 'carl', 'Carl opens his toolbox on the tailgate.', '칼이 트럭 뒷문 위에 공구함을 엽니다.', 'Anything else need fixing while I''ve got my tools out?', '공구 꺼낸 김에 또 고칠 거 있나?', 'Bring up the gutter over the front door, leaking since Tuesday, and ask whether it''s a job you could do on your own.', '화요일부터 새는 현관 위 빗물받이 얘기를 꺼내고, 그게 혼자서도 할 수 있는 일인지 물어보세요.', '[{"any":["gutter","leaking","leak","leaks"]},{"all":["now that you mention it"]}]', 'Now that you mention it, the gutter over the front door has been leaking since Tuesday. Is that something I can fix myself?', '말씀하시니까 생각났는데, 현관 위 빗물받이가 화요일부터 새요. 그거 제가 직접 고칠 수 있는 건가요?', '["Now that you mention it, the kitchen faucet has been dripping since Tuesday. Could you take a look at it while you''re here?","Yes, the gutter over the front door is leaking. As my landlord, you should have fixed it already.","No, I think we''re all good. I''ll call a guy about that leaky gutter over the front door next week."]', '["말씀하시니까 생각났는데, 부엌 수도꼭지가 화요일부터 물이 떨어져요. 오신 김에 한번 봐 주실래요?","네, 현관 위 빗물받이가 새요. 집주인이시니까 그런 건 진작 고쳐 주셨어야죠.","아니요, 다 괜찮아요. 현관 위 빗물받이는 다음 주에 사람 불러서 할게요."]', '["The faucet? Funny, I saw water by your front door, not the kitchen.","Should have? Hold your horses. You never told me.","A guy? Why pay a guy? I''m standing right here."]', '["수도꼭지? 이상하군. 물기는 부엌이 아니라 현관 앞에서 봤는데.","진작? 진정하게. 자네가 말을 안 했잖나.","사람을? 왜 돈을 써? 내가 바로 여기 있는데."]', '["\\"Now that you mention it\\" introduces something his question reminded you of.","Key words: now that you mention it, gutter, leaking"]', '["\\"Now that you mention it\\"은 상대의 말 덕분에 떠오른 이야기를 꺼낼 때 씁니다.","핵심 단어: now that you mention it, gutter, leaking"]', 'carl', 'Probably just clogged with leaves. Get a ladder and a pair of gloves. Twenty minutes, tops. I''ll hold the ladder.', '낙엽으로 막혔을 뿐일 걸세. 사다리하고 장갑을 가져오게. 길어야 20분이야. 사다리는 내가 잡아 주지.'),
  ('dk_w2_mower', 4, 'carl', 'Twenty minutes later the gutter is clear, and your gloves are full of wet leaves.', '20분 뒤 빗물받이가 뚫렸고, 장갑에는 젖은 낙엽이 가득합니다.', 'You should do this every fall, you know. Before the rain, not after.', '이건 가을마다 해야 해. 비 오기 전에, 오고 나서 말고.', 'Own up to procrastinating, and say you''re relieved it''s done before the weather turns tomorrow.', '미루기만 했다고 인정하고, 내일 날씨가 궂어지기 전에 끝내서 다행이라고 하세요.', '[{"all":["putting it off"]},{"all":["put it off"]},{"all":["got to it"]},{"all":["get around to it"]}]', 'I know, I keep putting it off. I''m glad we got to it before tomorrow''s rain.', '알아요, 자꾸 미루게 되더라고요. 내일 비 오기 전에 해서 다행이에요.', '["I know, I keep putting it off. Good thing we beat the big storm coming tonight.","It''s your house, Carl. Shouldn''t the landlord do this every fall?","Every fall? Next time I''ll just pay someone. I''m not a fan of ladders."]', '["알아요, 자꾸 미루게 되더라고요. 오늘 밤 오는 폭풍 전에 해서 다행이에요.","칼 집이잖아요. 가을마다 하는 건 집주인 일 아니에요?","가을마다요? 다음엔 그냥 사람 쓸래요. 사다리는 별로라서요."]', '["Tonight? The paper says tomorrow, all day.","Says the fella I just helped for free.","Pay someone? For twenty minutes of work?"]', '["오늘 밤? 신문엔 내일 종일이라던데.","방금 내가 공짜로 도와준 사람이 할 소리는 아니지.","사람을 써? 20분짜리 일에?"]', '["\\"Put off\\" = delay something you do not feel like doing.","Key words: keep putting it off, got to it"]', '["put off는 하기 싫은 일을 미룬다는 뜻입니다.","핵심 단어: keep putting it off, got to it"]', 'carl', 'Just in time. Showers all day tomorrow, the paper says.', '딱 맞춰 했구먼. 신문에 내일은 종일 소나기라더군.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('dk_w2_mower', 5, 'carl', 'Carl closes his toolbox and wipes his hands.', '칼이 공구함을 닫고 손을 닦습니다.', 'Now it''s my turn. I''m grilling at my place today at four. Jun from my building is coming, too. You in?', '이제 내 차례야. 오늘 네 시에 우리 집에서 고기 굽네. 우리 건물 사는 준도 와. 올 텐가?', 'Accept the invitation, and offer to bring something sweet as a thank-you.', '초대를 받아들이고, 고마움의 표시로 단 걸 가져가겠다고 하세요.', '[{"all":["would not miss it"]},{"all":["least i can do"]},{"any":["dessert"]}]', 'I wouldn''t miss it. Let me bring dessert. It''s the least I can do.', '절대 안 빠지죠. 디저트는 제가 가져갈게요. 그 정도는 해야죠.', '["I wouldn''t miss it. See you at six, then. Let me bring the dessert.","Maybe. I''ll see how I feel later and let you know, okay?","I''m in, but I''ll only stay a few minutes. I''ve got work to do."]', '["절대 안 빠지죠. 그럼 여섯 시에 봬요. 디저트는 제가 가져갈게요.","글쎄요. 이따가 컨디션 보고 알려 드릴게요, 괜찮죠?","갈게요. 근데 몇 분만 있다 갈게요. 할 일이 있어서요."]', '["Six? I said four. The coals will be cold by six.","Suit yourself. There''ll be plenty of food.","On a Saturday? You work too much, Derek."]', '["여섯 시? 네 시라고 했네. 여섯 시면 숯불 다 식어.","마음대로 하게. 음식은 넉넉할 거야.","토요일에? 자넨 일을 너무 해, 데릭."]', '["Accept warmly and return the favor in a small way.","Key words: wouldn''t miss it, the least I can do"]', '["흔쾌히 수락하고 작게나마 보답하세요.","핵심 단어: wouldn''t miss it, the least I can do"]', 'carl', 'Dessert works. Nothing with raisins. See you at four, Derek!', '디저트 좋지. 건포도 들어간 것만 빼고. 네 시에 보세, 데릭!'),
  ('pr_d1_coffee', 1, 'nina', 'Nina''s coffee cart on Lake Avenue. You stop here every morning on your way in.', '레이크 애비뉴에 있는 니나의 커피 카트입니다. 출근길에 매일 아침 들르는 곳이에요.', 'Morning, Priya! The usual?', '좋은 아침이에요, 프리야! 늘 드시던 걸로요?', 'Say yes to your usual. (Your usual: a medium latte made with oat milk.)', '평소 마시던 걸로 하겠다고 하세요. (평소 메뉴: 귀리 우유로 만든 라테, 미디엄)', '[{"any":["latte","usual"]}]', 'Yes, please. A medium oat milk latte.', '네, 부탁해요. 귀리 우유 라테 미디엄이요.', '["Yes, please. A large oat milk latte.","Obviously. Same as every single day, Nina.","Hmm, what do you recommend today?"]', '["네, 부탁해요. 귀리 우유 라테 라지요.","당연하죠. 매일 똑같은 거잖아요, 니나.","음, 오늘은 뭐가 괜찮아요? 추천해 줄래요?"]', '["A large? Switching it up today?","Whoa, okay. Somebody needs their coffee.","Oh! I thought you''d want the usual."]', '["라지요? 오늘은 바꿔 보시게요?","워, 알았어요. 누가 커피가 급하시네.","어머! 늘 드시던 걸로 하실 줄 알았는데."]', '["Say yes and name your drink: size, milk, drink.","Key words: the usual, medium oat milk latte"]', '["네라고 하고 음료를 말하세요. 크기, 우유, 음료 순서로.","핵심 단어: the usual, medium oat milk latte"]', 'nina', 'One medium oat latte, coming up.', '귀리 우유 라테 미디엄 하나, 바로 나갑니다.'),
  ('pr_d1_coffee', 2, 'nina', 'Nina reaches for a cup.', '니나가 컵을 집어 듭니다.', 'Hot or iced today?', '오늘은 따뜻한 걸로요, 아이스로요?', 'Hot today. You need extra caffeine to get through this week.', '오늘은 따뜻한 걸로요. 이번 주를 버티려면 카페인이 더 필요합니다.', '[{"all":["shot"]},{"all":["espresso"]}]', 'Hot, please. And can I get an extra shot? It''s a big week.', '따뜻한 걸로 주세요. 그리고 샷 하나 추가해 줄래요? 중요한 한 주라서요.', '["Iced, please. And can I get an extra shot? It''s a big week.","Hot, please. Could you make it decaf? It''s a big week.","Hot. Ugh, don''t even ask. This week is going to be a nightmare."]', '["아이스로 주세요. 그리고 샷 하나 추가해 줄래요? 중요한 한 주라서요.","따뜻한 걸로 주세요. 디카페인으로 해 줄래요? 중요한 한 주라서요.","따뜻한 거요. 아, 말도 마요. 이번 주는 완전 악몽일 거예요."]', '["Iced, huh? Okay, iced with an extra shot.","Decaf? For a big week? You sure?","Oof. Want something to help with that?"]', '["아이스요? 알겠어요, 아이스에 샷 추가.","디카페인이요? 중요한 주에? 정말요?","이런. 그럼 뭐 좀 도움 될 만한 거 드릴까요?"]', '["Ask with \\"Can I get …?\\" for one more shot of espresso.","Key words: extra shot, big week"]', '["\\"Can I get …?\\"으로 에스프레소 샷을 하나 더 부탁하세요.","핵심 단어: extra shot, big week"]', 'nina', 'Uh-oh, an extra-shot kind of week. You got it.', '이런, 샷 추가가 필요한 한 주군요. 알겠어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_coffee', 3, 'nina', 'The smell of fresh muffins comes from the cart.', '카트에서 갓 구운 머핀 냄새가 납니다.', 'Anything to eat with that? The muffins just came out.', '같이 드실 건요? 머핀이 방금 나왔어요.', 'You don''t want anything to eat. Turn it down nicely.', '먹을 건 필요 없습니다. 기분 좋게 사양하세요.', '[{"all":["no"],"any":["thanks","thank"]},{"all":["i am good"]},{"all":["all set"]},{"all":["just the latte"]}]', 'I''m good, thanks. Just the latte.', '괜찮아요, 고마워요. 라테만 주세요.', '["No. I don''t eat that kind of stuff.","Sure, I''ll take a blueberry one.","Not those. They look kind of dry."]', '["아뇨. 그런 건 안 먹어요.","좋아요, 블루베리로 하나 주세요.","그건 됐어요. 좀 퍽퍽해 보여서요."]', '["Oh. Okay, then.","One blueberry muffin, coming right up!","Dry? They just came out of the oven!"]', '["아. 네, 그럼.","블루베리 머핀 하나, 바로 드릴게요!","퍽퍽해요? 방금 오븐에서 나온 건데요!"]', '["\\"I''m good\\" is a friendly way to say no, thank you.","Key words: I''m good, just the latte"]', '["\\"I''m good\\"는 괜찮다고 상냥하게 거절하는 말입니다.","핵심 단어: I''m good, just the latte"]', 'nina', 'No problem. Maybe tomorrow.', '그럼요. 내일은 드셔 보세요.'),
  ('pr_d1_coffee', 4, 'nina', 'You hold your card over the reader.', '카드를 단말기에 갖다 댑니다.', 'That''s five even. Big day today?', '딱 5달러예요. 오늘 중요한 날이에요?', 'Tell her what''s happening today: someone new joins your team, and you''re leading the ten o''clock meeting.', '오늘 무슨 일이 있는지 말하세요. 팀에 새 사람이 오고, 10시 회의를 당신이 진행합니다.', '[{"any":["new developer","new hire","standup","starts today","new person","new engineer"]}]', 'Yeah. A new developer starts today, and I''m running standup at ten.', '네. 오늘 새 개발자가 첫 출근하고, 10시에 제가 스탠드업을 진행해요.', '["Kind of. A new designer starts today, and I''m running standup at ten.","Every day''s a big day here. Can I just pay, please? I''m running late.","Yeah. A client might drop us if Monday''s demo goes badly, so…"]', '["그런 셈이에요. 오늘 새 디자이너가 오고, 10시에 제가 스탠드업을 진행해요.","여긴 매일이 중요한 날이에요. 그냥 계산해도 돼요? 늦었거든요.","네. 월요일 데모 망치면 고객이 우리랑 끊을 수도 있어서요…"]', '["A designer? Fun! Send them my way.","Oh. Sure, sorry. You''re all set.","Yikes. Well, good luck with that."]', '["디자이너요? 재밌겠네요! 저한테도 보내 주세요.","아. 네, 죄송해요. 다 됐어요.","아이고. 뭐, 잘 되길 바랄게요."]', '["Say who starts today and what you are running at ten.","Key words: new developer, running standup"]', '["오늘 누가 새로 오는지, 열 시에 무엇을 진행하는지 말하세요.","핵심 단어: new developer, running standup"]', 'nina', 'Fun! Send the new hire my way. Here''s your latte. Have a good one!', '재밌겠네요! 새로 온 분한테 여기 알려 주세요. 라테 나왔어요. 좋은 하루 보내요!'),
  ('pr_d1_priorities', 1, 'maya', 'Maya''s office. Sunlight falls on the checklist on her desk.', '마야의 사무실입니다. 책상 위 체크리스트에 햇빛이 비칩니다.', 'Morning, Priya. Do you have a few minutes to sync before standup?', '좋은 아침이에요, 프리야. 스탠드업 전에 몇 분만 맞춰 볼 시간 있어요?', 'You''re happy to talk. You were hoping to agree on what comes first this sprint.', '기꺼이 이야기하세요. 마침 이번 스프린트에서 무엇을 먼저 할지 맞추고 싶었습니다.', '[{"any":["align","priorities","same page"]}]', 'Sure. I wanted to align on this sprint''s priorities anyway.', '그럼요. 어차피 이번 스프린트 우선순위를 맞추고 싶었어요.', '["Sorry, I''m swamped. Can we do it after standup instead?","Sure. I wanted to talk about next quarter''s budget anyway, actually.","Sure, but make it quick. I''ve got a lot on my plate."]', '["미안해요, 너무 바빠요. 스탠드업 끝나고 하면 안 될까요?","그럼요. 어차피 다음 분기 예산 얘기를 하고 싶었어요.","좋아요, 근데 빨리 해 주세요. 할 일이 산더미라서요."]', '["After standup''s too late. It''s about the sprint.","Budget? Hmm, I was thinking more about this sprint.","Okay… I''ll keep it short."]', '["스탠드업 끝나면 늦어요. 스프린트 얘기거든요.","예산이요? 음, 저는 이번 스프린트 얘기를 하려던 건데.","그래요… 짧게 할게요."]', '["\\"To align on\\" something means to agree on it together.","Key words: align on, priorities"]', '["align on은 함께 의견을 맞춘다는 뜻입니다.","핵심 단어: align on, priorities"]', 'maya', 'Great minds think alike. Have a seat.', '마음이 통했네요. 앉아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_priorities', 2, 'maya', 'She opens the roadmap on her screen.', '마야가 화면에 로드맵을 띄웁니다.', 'So, what''s the top priority for this sprint?', '그래서 이번 스프린트 최우선은 뭐예요?', 'Tell her what comes first: the checkout work, because of the client demo next Monday.', '무엇이 먼저인지 말하세요. 결제 쪽 작업입니다. 다음 주 월요일에 고객 데모가 있어요.', '[{"all":["checkout"]}]', 'Our top priority is the new checkout flow. The client demo is next Monday.', '최우선은 새 결제 흐름이에요. 고객 데모가 다음 주 월요일이거든요.', '["The new checkout flow, definitely. The client demo is this Thursday.","Everything''s important. I''d rather not rank things this early on.","The wish list feature. Greg keeps bringing it up, so let''s just do it first."]', '["당연히 결제 흐름이죠. 고객 데모가 이번 주 목요일이에요.","다 중요해요. 이렇게 일찍부터 순위를 매기고 싶진 않아요.","위시리스트 기능이요. 그렉이 계속 물어보니까 그것부터 하죠."]', '["Thursday? I had the demo down for next Monday.","Priya, that''s the whole point of this meeting.","Really? I thought the demo needs the checkout."]', '["목요일이요? 데모는 다음 주 월요일로 적어 뒀는데.","프리야, 그걸 정하려고 지금 만난 거잖아요.","정말요? 데모엔 결제 쪽이 필요한 줄 알았는데."]', '["Start with \\"Our top priority is …\\" and give the reason.","Key words: top priority, checkout flow, client demo"]', '["\\"Our top priority is …\\"로 시작하고 이유를 덧붙이세요.","핵심 단어: top priority, checkout flow, client demo"]', 'maya', 'Agreed. That''s the must-have.', '동의해요. 그건 꼭 해야 하는 일이죠.'),
  ('pr_d1_priorities', 3, 'maya', 'Maya scrolls down the list.', '마야가 목록을 아래로 내립니다.', 'What about the wish list feature? Greg keeps bringing it up.', '위시리스트 기능은요? 그렉이 계속 얘기하던데.', 'You don''t think it''s urgent. Suggest when to do it.', '급하다고 생각하지 않습니다. 언제 할지 제안하세요.', '[{"any":["nice to have","next sprint","push it","backlog"]}]', 'That''s a nice-to-have. I''d push it to the next sprint.', '그건 있으면 좋은 정도예요. 다음 스프린트로 미룰게요.', '["It''s a must-have, honestly. Let''s squeeze it into this sprint.","Greg can keep asking. We''re never doing that one.","Let''s just tell Greg it''ll be done by Monday''s demo."]', '["그건 꼭 해야 해요. 이번 스프린트에 끼워 넣죠.","그렉이야 계속 물어보라죠. 그건 절대 안 할 거예요.","그냥 그렉한테 월요일 데모까지 된다고 하죠."]', '["This sprint? On top of the checkout? That''s a lot.","Never? He''s our biggest client. Let''s not burn that bridge.","By Monday? We''d be promising something we can''t deliver."]', '["이번 스프린트에요? 결제 작업까지 있는데? 너무 많아요.","절대요? 제일 큰 고객인데요. 관계를 망치진 말죠.","월요일까지요? 못 지킬 약속을 하는 거예요."]', '["Must-have or nice-to-have? Say when you would do it.","Key words: nice-to-have, push it to the next sprint"]', '["꼭 필요한 것인지 있으면 좋은 것인지, 그리고 언제 할지 말하세요.","핵심 단어: nice-to-have, push it to the next sprint"]', 'maya', 'Makes sense. I''ll tell Greg it''s on the roadmap, just not yet.', '좋아요. 그렉에게는 로드맵에 있지만 아직은 아니라고 말할게요.'),
  ('pr_d1_priorities', 4, 'maya', 'She checks one more item on her list.', '마야가 목록에서 한 가지를 더 확인합니다.', 'One more thing. Jun, the new developer, starts today. Can you keep his load light?', '하나 더요. 새 개발자 준이 오늘 첫 출근이에요. 일을 가볍게 줄 수 있어요?', 'Agree, and say how you''ll ease him in.', '동의하고, 어떻게 천천히 적응시킬지 말하세요.', '[{"any":["small ticket","one ticket","small task","easy ticket","starter","light"]}]', 'Of course. I''ll give him one small ticket to start with.', '물론이죠. 처음엔 작은 티켓 하나만 줄게요.', '["Sure. I''ll put him on the checkout flow right away.","Sure, but I can''t babysit him. He''ll have to figure things out.","Of course. Should he join the client demo on Monday?"]', '["그럼요. 바로 결제 흐름에 투입할게요.","네, 근데 애 보듯 할 순 없어요. 알아서 해야죠.","물론이죠. 월요일 고객 데모에 같이 들어가게 할까요?"]', '["The checkout? That''s our must-have. Let''s start him smaller.","Nobody''s asking you to babysit. Just go easy on him.","Let''s not throw him into a client demo in week one."]', '["결제요? 그건 꼭 해야 하는 일이잖아요. 더 작은 걸로 시작해요.","애 보라는 게 아니에요. 그냥 살살 해 주라는 거죠.","첫 주부터 고객 데모에 던져 넣지는 말죠."]', '["Promise a small piece of work: \\"I''ll give him …\\".","Key words: one small ticket, to start with"]', '["작은 일을 주겠다고 약속하세요. \\"I''ll give him …\\".","핵심 단어: one small ticket, to start with"]', 'maya', 'Perfect. Nobody should drown in week one.', '좋아요. 첫 주부터 일에 파묻히면 안 되죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_priorities', 5, 'maya', 'It is almost ten. You stand up.', '열 시가 다 되어 갑니다. 당신은 자리에서 일어납니다.', 'Anything you need from me?', '제가 도와줄 건 없어요?', 'You''re worried the client will try to add features. Ask for her support.', '고객이 기능을 더 넣어 달라고 할까 봐 걱정입니다. 마야의 지원을 부탁하세요.', '[{"any":["back me up","support me","scope","have my back"]}]', 'Could you back me up if the client asks for more scope?', '고객이 범위를 더 늘려 달라고 하면 제 편 좀 들어 줄래요?', '["Could you handle the client demo on Monday for me?","Nope, I think I''m all set. See you at standup in a bit.","Could you just tell Greg to stop asking for new stuff?"]', '["월요일 고객 데모를 저 대신 좀 맡아 줄 수 있어요?","아뇨, 다 된 것 같아요. 이따 스탠드업에서 봬요.","그렉한테 새 기능 그만 요청하라고 좀 말해 줄래요?"]', '["The demo''s yours, Priya. You know the product best.","Okay. Shout if anything comes up.","I can''t just tell a client that. But I can support you."]', '["데모는 프리야 몫이에요. 제품은 프리야가 제일 잘 알잖아요.","그래요. 무슨 일 있으면 불러요.","고객한테 그렇게 말할 순 없죠. 하지만 힘은 실어 줄 수 있어요."]', '["\\"Back me up\\" means support me when someone pushes.","Key words: back me up, more scope"]', '["back me up은 누가 밀어붙일 때 내 편을 들어 달라는 뜻입니다.","핵심 단어: back me up, more scope"]', 'maya', 'Absolutely. Send him my way. And let me know if you have any questions.', '그럼요. 저한테 넘겨요. 궁금한 게 있으면 말해 주고요.'),
  ('pr_d1_room', 1, 'tom', 'The front desk. Tom has the room calendar open on his screen.', '프런트 데스크입니다. 톰의 화면에 회의실 달력이 떠 있습니다.', 'Hey, Priya! What can I do for you?', '안녕하세요, 프리야! 뭘 도와드릴까요?', 'Book a room for Wednesday afternoon. It''s a big meeting, so you need the large one.', '수요일 오후에 쓸 회의실을 예약하세요. 사람이 많으니 큰 방이 필요합니다.', '[{"all":["wednesday"],"any":["book","reserve"]}]', 'I''d like to book the large meeting room for Wednesday afternoon.', '수요일 오후에 큰 회의실을 예약하고 싶어요.', '["I''d like to book the small room by the kitchen for Wednesday afternoon.","Could I get the large meeting room for Thursday morning?","I need the big room Wednesday. Just kick out whoever has it."]', '["수요일 오후에 탕비실 옆 작은 방을 예약하고 싶어요.","목요일 오전에 큰 회의실 쓸 수 있을까요?","수요일에 큰 방 필요해요. 누가 쓰든 그냥 빼 주세요."]', '["The small room? For sprint planning? It only fits four.","Thursday morning? Isn''t sprint planning on Wednesday?","Whoa. Let me at least check who has it first."]', '["작은 방이요? 스프린트 플래닝에요? 네 명밖에 안 들어가요.","목요일 오전이요? 스프린트 플래닝은 수요일 아니었어요?","워. 누가 쓰는지 먼저 좀 볼게요."]', '["\\"I''d like to book …\\" plus the room and the day.","Key words: book, large meeting room, Wednesday afternoon"]', '["\\"I''d like to book …\\" 뒤에 회의실과 요일을 말하세요.","핵심 단어: book, large meeting room, Wednesday afternoon"]', 'tom', 'Sprint planning, right? Let me take a look.', '스프린트 플래닝이죠? 한번 볼게요.'),
  ('pr_d1_room', 2, 'tom', 'He runs a finger down the calendar.', '톰이 손가락으로 달력을 짚어 내려갑니다.', 'The sales team has it until two. Is two to four okay?', '영업팀이 두 시까지 써요. 두 시부터 네 시 괜찮아요?', 'His suggestion fits your plans. Take it.', '그가 제안한 시간이 괜찮습니다. 받아들이세요.', '[{"any":["works","perfect","fine","great"]}]', 'Two to four works for me.', '두 시부터 네 시면 괜찮아요.', '["One to three works for me.","I guess. If I have to.","Can''t sales just move?"]', '["한 시부터 세 시면 괜찮아요.","뭐, 어쩔 수 없죠.","영업팀이 옮기면 안 돼요?"]', '["Sales has it until two, though.","Uh, okay. I''ll put you down.","Sorry, they booked it weeks ago."]', '["근데 영업팀이 두 시까지 써요.","어, 네. 적어 둘게요.","죄송해요, 몇 주 전에 잡은 거라서요."]', '["Accept the time slot: \\"… works for me.\\"","Key words: two to four, works for me"]', '["시간대를 받아들이세요. \\"… works for me.\\"","핵심 단어: two to four, works for me"]', 'tom', 'Done. It''s yours from two to four.', '됐어요. 두 시부터 네 시까지 쓰세요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_room', 3, 'tom', 'Tom keeps the calendar open.', '톰이 달력을 그대로 열어 둡니다.', 'Anything else while I''m in here?', '들어온 김에 더 할 거 있어요?', 'Also set up the ten o''clock standup so the room is held for it automatically, Monday to Friday.', '10시 스탠드업도 월요일부터 금요일까지 자동으로 방이 잡히게 해 달라고 하세요.', '[{"any":["recurring","every weekday","every day","repeat","standing"]}]', 'Could you make the ten o''clock standup a recurring booking, every weekday?', '10시 스탠드업을 평일마다 반복 예약으로 해 줄 수 있어요?', '["Could you book the room for the ten o''clock standup, but just for tomorrow?","Yes. Can you block nine to nine fifteen every weekday for standup?","No, I think that''s everything for now. Thanks, Tom. See you later."]', '["10시 스탠드업 때 쓸 방을 내일 하루만 잡아 줄 수 있어요?","네. 평일마다 9시부터 9시 15분까지 스탠드업으로 잡아 줄래요?","아뇨, 지금은 그게 다인 것 같아요. 고마워요, 톰. 이따 봐요."]', '["Just tomorrow? You meet every day, though, right?","Nine? I thought standup was at ten.","Alright! Holler if you think of anything."]', '["내일만요? 매일 모이지 않아요?","9시요? 스탠드업은 10시인 줄 알았는데.","그래요! 생각나는 거 있으면 불러요."]', '["A booking that repeats is a \\"recurring\\" booking.","Key words: recurring booking, every weekday"]', '["반복되는 예약은 recurring booking이라고 합니다.","핵심 단어: recurring booking, every weekday"]', 'tom', 'You got it. Ten to ten fifteen, Monday through Friday.', '알겠어요. 월요일부터 금요일까지 10시부터 10시 15분.'),
  ('pr_d1_room', 4, 'tom', 'Tom lowers his voice a little.', '톰이 목소리를 조금 낮춥니다.', 'Heads-up, though: somebody keeps leaving coffee cups in that room.', '근데 미리 말해 둘게요. 누가 자꾸 그 방에 커피 컵을 두고 가요.', 'It''s your team''s mess. Own it, and say you''ll take care of it.', '당신 팀이 어질러 놓은 겁니다. 인정하고, 처리하겠다고 하세요.', '[{"any":["remind","clean up","tell the team","clean"]}]', 'Sorry about that. I''ll remind the team to clean up after themselves.', '죄송해요. 팀원들한테 쓴 건 각자 치우라고 말해 둘게요.', '["That''s probably the sales team. They had the room right before we did, I think.","It''s just coffee cups, Tom. Can''t the cleaners get them?","Oh, sorry. Should I stop bringing coffee to meetings, then?"]', '["아마 영업팀일 거예요. 우리 바로 전에 그 방을 썼던 것 같아요.","그냥 커피 컵이잖아요, 톰. 청소하시는 분이 치우면 되잖아요?","아, 죄송해요. 그럼 회의에 커피를 안 가져갈까요?"]', '["Maybe, but it''s your team''s cups. I''ve seen the stickers.","The cleaners come once a week, Priya.","No, no. Just get folks to take their cups with them."]', '["그럴 수도 있지만, 프리야 팀 컵이에요. 스티커 봤어요.","청소는 일주일에 한 번 와요, 프리야.","아니, 아니에요. 다들 자기 컵만 챙겨 가게 해 줘요."]', '["Say sorry, then say what you will do about it.","Key words: sorry about that, remind the team, clean up"]', '["미안하다고 한 뒤 어떻게 할지 말하세요.","핵심 단어: sorry about that, remind the team, clean up"]', 'tom', 'Appreciate it. You''re the best.', '고마워요. 역시 프리야예요.'),
  ('pr_d1_room', 5, 'tom', 'He picks up a pen.', '톰이 펜을 집어 듭니다.', 'Do you need anything in the room? Markers, the speakerphone?', '방에 필요한 거 있어요? 마커나 스피커폰이요?', 'A client is dialing in this week. Ask him to check the phone in the room.', '이번 주에 고객과 통화가 있습니다. 회의실 전화기를 점검해 달라고 하세요.', '[{"any":["speakerphone","phone","client call"]}]', 'Could you make sure the speakerphone works? I have a client call this week.', '스피커폰이 잘 되는지 확인해 줄 수 있어요? 이번 주에 고객 통화가 있어서요.', '["Just some fresh markers, please. The old ones are all dried out.","Could you make sure the projector works? I have a client demo today.","Make sure the speakerphone actually works this time. The last call was a mess."]', '["새 마커만 좀 주세요. 있던 건 다 말라 버렸어요.","프로젝터가 잘 되는지 확인해 줄래요? 오늘 고객 데모가 있어요.","이번엔 스피커폰 제대로 되게 해 주세요. 지난번 통화 엉망이었어요."]', '["Sure, markers. Nothing else you need in there?","Today? I thought the demo was Monday. But sure, I''ll check it.","I''ll test it. No need for the tone, though."]', '["네, 마커요. 그 방에 다른 건 필요 없어요?","오늘이요? 데모는 월요일인 줄 알았는데. 그래도 확인해 볼게요.","확인할게요. 근데 그런 말투는 필요 없잖아요."]', '["\\"Could you make sure …?\\" asks someone to check something.","Key words: make sure, speakerphone, client call"]', '["\\"Could you make sure …?\\"는 확인해 달라고 부탁하는 말입니다.","핵심 단어: make sure, speakerphone, client call"]', 'tom', 'I''ll test it this afternoon and leave fresh markers, too.', '오늘 오후에 시험해 보고, 새 마커도 갖다 놓을게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_standup', 1, 'derek', 'Ten o''clock sharp. The team is standing around the table in the meeting room.', '열 시 정각입니다. 팀이 회의실 탁자 주위에 서 있습니다.', 'Morning, Priya. Everybody''s here, including Jun, the new guy.', '좋은 아침이에요, 프리야. 새로 온 준까지 다 모였어요.', 'It''s time. Open the meeting and give the new guy the floor.', '시간이 됐습니다. 회의를 열고, 새로 온 사람에게 말할 기회를 주세요.', '[{"all":["get started"]},{"all":["let us start"]},{"all":["kick"]},{"any":["quick hello","say hello","say hi","introduce yourself"]}]', 'Okay, let''s get started. Jun, want to say a quick hello?', '자, 시작하죠. 준, 짧게 인사 한마디 해 줄래요?', '["Alright, let''s begin. Derek, want to introduce yourself?","Let''s wait five more minutes. People are always late anyway.","Let''s start. Jun, you can skip updates. You haven''t done anything yet."]', '["좋아요, 시작하죠. 데릭, 자기소개 해 줄래요?","5분만 더 기다리죠. 어차피 늘 누군가 늦으니까요.","시작하죠. 준은 업데이트 건너뛰어요. 아직 한 게 없잖아요."]', '["Me? Everyone knows me. Isn''t it Jun''s first day?","Everybody''s already here, though.","Ouch. Go easy on him, it''s his first day."]', '["저요? 다들 저 알잖아요. 오늘 준이 첫날 아니에요?","근데 다들 벌써 와 있어요.","아야. 살살 해요, 첫날이잖아요."]', '["Open with \\"Let''s get started\\", then invite Jun to speak.","Key words: let''s get started, a quick hello"]', '["\\"Let''s get started\\"로 열고 준에게 말할 기회를 주세요.","핵심 단어: let''s get started, a quick hello"]', 'jun', 'Hi, everyone. I''m Jun. I just joined as a developer. Excited to be here!', '안녕하세요, 여러분. 준입니다. 개발자로 막 입사했어요. 함께하게 되어 기쁩니다!'),
  ('pr_d1_standup', 2, 'jun', 'Jun looks a little nervous.', '준이 조금 긴장한 것 같습니다.', 'Sorry, how does this meeting work?', '죄송한데, 이 회의는 어떻게 하는 거예요?', 'Walk him through the three things each person shares.', '한 사람씩 말하는 세 가지를 설명해 주세요.', '[{"all":["blockers"]},{"all":["yesterday","today"]}]', 'It''s simple: what you did yesterday, what you''re doing today, and any blockers.', '간단해요. 어제 한 일, 오늘 할 일, 그리고 막힌 게 있으면 말하면 돼요.', '["It''s simple: what you did last week, your goals for the month, and any questions.","You''ll figure it out. Just watch everyone else and copy what they do.","It''s every morning at ten, here in this room, for about fifteen minutes."]', '["간단해요. 지난주에 한 일, 이번 달 목표, 그리고 궁금한 게 있으면 말하면 돼요.","하다 보면 알게 돼요. 그냥 다른 사람들 보고 따라 해요.","매일 아침 10시에 이 방에서 해요. 15분쯤 걸리고요."]', '["Last week? Sorry, I just started today.","Oh… okay. I''ll try.","Got it. But what do I actually say?"]', '["지난주요? 죄송한데 저 오늘 입사했어요.","아… 네. 해 볼게요.","알겠어요. 근데 실제로 무슨 말을 하면 돼요?"]', '["Three parts. The last one is what is stopping you.","Key words: yesterday, today, blockers"]', '["세 가지입니다. 마지막은 일을 막고 있는 것입니다.","핵심 단어: yesterday, today, blockers"]', 'jun', 'Got it. Today I''m setting up my laptop and my dev environment.', '알겠습니다. 오늘은 노트북과 개발 환경을 세팅합니다.'),
  ('pr_d1_standup', 3, 'jun', 'He glances at Derek.', '준이 데릭을 흘끗 봅니다.', 'I do have one blocker. I don''t have access to the repository yet.', '막힌 게 하나 있긴 해요. 아직 저장소 권한이 없어요.', 'Clear his blocker: get Derek, his onboarding buddy, to sort it out once the meeting''s over.', '막힌 걸 풀어 주세요. 회의가 끝나면 그의 온보딩 버디인 데릭이 해결해 주게 하세요.', '[{"all":["derek"],"any":["help","access","take care","sort"]},{"all":["after standup"]}]', 'Derek, can you help Jun with that after standup?', '데릭, 스탠드업 끝나고 준 그거 좀 도와줄래요?', '["Derek, can you drop everything and fix that now?","Okay. Just file a ticket with IT and wait.","Jun, can you ask Maya about that after standup?"]', '["데릭, 하던 거 다 멈추고 지금 그것 좀 해결해 줄래요?","알겠어요. IT에 티켓 올리고 기다려요.","준, 그건 스탠드업 끝나고 마야한테 물어볼래요?"]', '["Um, right now? Isn''t the meeting still going?","Oh. Okay. How long does that usually take?","Maya? I thought Derek was my onboarding buddy."]', '["어, 지금요? 아직 회의 중 아니에요?","아. 네. 그거 보통 얼마나 걸려요?","마야요? 데릭이 제 온보딩 버디인 줄 알았는데요."]', '["Give the blocker an owner: name the person and the time.","Key words: Derek, help, after standup"]', '["막힌 점에 담당자를 정하세요. 사람 이름과 시점을 말합니다.","핵심 단어: Derek, help, after standup"]', 'derek', 'Sure thing. I''ll get him access right after this.', '그럼요. 끝나자마자 권한을 받게 해 줄게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_standup', 4, 'derek', 'Derek leans on the table. He is just getting started.', '데릭이 탁자에 몸을 기댑니다. 이야기가 길어질 기세입니다.', 'While we''re all here: I think we should rewrite the payment module. I have a whole plan.', '다들 모인 김에요. 결제 모듈을 다시 짜야 할 것 같아요. 계획도 다 있어요.', 'It''s a real issue, but not one for standup. Cut him off politely and offer another time.', '중요한 얘기지만 스탠드업에서 할 건 아닙니다. 정중하게 끊고 다른 시간을 제안하세요.', '[{"all":["offline"]},{"any":["park that","park it","separately","after the meeting"]}]', 'Good topic, but let''s take that offline. Can you stay for five minutes after?', '좋은 주제인데, 그건 따로 얘기해요. 끝나고 5분만 남아 줄래요?', '["Derek, not now. Honestly, nobody here wants to hear about the payment module.","Good idea. Go ahead and walk us through the whole plan right now.","I love it. Let''s go ahead and rewrite it this sprint, then."]', '["데릭, 지금은 아니에요. 솔직히 결제 모듈 얘기는 아무도 안 듣고 싶어 해요.","좋은 생각이에요. 지금 바로 계획 전체를 설명해 줘요.","좋네요. 그럼 이번 스프린트에 아예 다시 짜 버리죠."]', '["Wow. Okay. Noted.","Really? Okay! So first, the database layer…","Seriously? I thought the checkout was our must-have."]', '["와. 그래요. 알겠습니다.","정말요? 좋아요! 그럼 먼저 데이터베이스 계층부터…","진짜요? 결제 흐름이 꼭 해야 할 일인 줄 알았는데."]', '["\\"Take it offline\\" = talk about it outside this meeting.","Key words: good topic, take that offline"]', '["take it offline은 이 회의 밖에서 따로 이야기한다는 뜻입니다.","핵심 단어: good topic, take that offline"]', 'derek', 'Fair enough. No rush.', '그래요. 급한 건 아니에요.'),
  ('pr_d1_standup', 5, 'derek', 'The clock on the wall says 10:13.', '벽시계가 10시 13분을 가리킵니다.', 'That''s everybody, I think.', '이제 다 한 것 같아요.', 'Everyone has spoken, and it''s 10:13. Close the meeting.', '모두 말했고, 10시 13분입니다. 회의를 마치세요.', '[{"any":["that is it","thanks everyone","thank you everyone","same time","wrap"]}]', 'That''s it for today. Thanks, everyone! Same time tomorrow.', '오늘은 여기까지요. 다들 고마워요! 내일 같은 시간에 봐요.', '["That''s all for today. Thanks, everyone! Same time next week.","Great. Now let''s go around one more time, just to be safe.","Okay, we''re done here. Back to work, everyone. Go."]', '["오늘은 여기까지요. 다들 고마워요! 다음 주 같은 시간에 봐요.","좋아요. 혹시 모르니 한 바퀴 더 돌아가면서 말해 보죠.","자, 끝났어요. 다들 일하러 가요. 어서요."]', '["Next week? It''s a daily standup, Priya.","Again? We''d blow past fifteen minutes.","Yes, ma''am. Bit of a drill sergeant today."]', '["다음 주요? 매일 하는 스탠드업이잖아요, 프리야.","또요? 그럼 15분 훌쩍 넘어요.","네, 대장님. 오늘 좀 군기반장 같네요."]', '["Close the meeting in three short sentences.","Key words: that''s it for today, thanks everyone, same time tomorrow"]', '["짧은 세 문장으로 회의를 닫으세요.","핵심 단어: that''s it for today, thanks everyone, same time tomorrow"]', 'derek', 'Thirteen minutes. A new record.', '13분이네요. 신기록이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_contract', 1, 'greg', 'A gray, chilly morning. The proposal is on the screen: $180,000 for phase one, payment Net 30.', '흐리고 쌀쌀한 아침입니다. 화면에 제안서가 떠 있습니다. 1단계 18만 달러, 지급 조건 Net 30.', 'I''ve looked at the numbers. Honestly, one eighty is outside our budget. We were thinking closer to one fifty.', '숫자를 봤어요. 솔직히 18만은 우리 예산을 벗어나요. 우리는 15만 정도를 생각하고 있었거든요.', 'Don''t come down on the price. Show him you hear him, then tie the number to what it covers: 40 stores, live data and 3 months of support.', '가격을 내리지 마세요. 그의 입장을 이해한다고 보여 주고, 그 금액에 매장 40곳, 실시간 데이터, 3개월 지원이 들어 있다는 점을 짚으세요.', '[{"any":["reflects","months of support","forty stores"]}]', 'I understand. The price reflects the work: forty stores, live data, and three months of support.', '이해합니다. 그 가격에는 일의 크기가 반영되어 있어요. 매장 40곳, 실시간 데이터, 그리고 3개월 지원까지요.', '["I understand. The price reflects a lot of work: thirty stores, live data, and six months of support.","I hear you. If one fifty is your budget, I think we can probably make that work for you.","Honestly, that''s your budget problem, not ours. One eighty is what this work costs, period."]', '["이해합니다. 그 가격에는 많은 일이 들어 있어요. 매장 30곳, 실시간 데이터, 그리고 6개월 지원까지요.","무슨 말씀인지 알아요. 예산이 15만이라면, 아마 그 금액으로 맞춰 드릴 수 있을 것 같아요.","솔직히 그건 그쪽 예산 문제지 우리 문제가 아니에요. 이 일은 18만이에요. 그게 끝이에요."]', '["Thirty stores? We''re rolling out to forty. Did the scope change?","Really? That was easier than I expected. Can I get that in writing?","Whoa. I was hoping we could have a conversation here, Priya."]', '["30곳이요? 우리는 40곳에 도입하는데요. 범위가 바뀌었나요?","정말요? 생각보다 쉽네요. 그거 서면으로 받을 수 있을까요?","이런. 저는 대화를 좀 해 보고 싶었는데요, 프리야."]', '["Do not move the number. Explain what is inside it.","Key words: I understand, the price reflects the work, three months of support"]', '["숫자는 움직이지 말고, 그 안에 무엇이 들어 있는지 설명하세요.","핵심 단어: I understand, the price reflects the work, three months of support"]', 'greg', 'That helps. But I still need the number to come down. Can you meet us halfway? Say, one sixty-five?', '도움이 되네요. 그래도 금액을 낮춰야 해요. 중간에서 만날 수 있을까요? 16만 5천 정도?'),
  ('pr_d10_contract', 2, 'greg', 'You are not allowed to approve a discount on your own. Maya is.', '당신에게는 혼자서 할인을 승인할 권한이 없습니다. 마야에게는 있습니다.', 'One sixty-five. Can we shake on that?', '16만 5천. 그걸로 악수할까요?', 'Discounts aren''t yours to approve. Don''t commit either way today.', '할인은 당신이 승인할 수 있는 일이 아닙니다. 오늘은 어느 쪽으로도 확답하지 마세요.', '[{"any":["not in a position","run that by","run it by"]}]', 'I''m not in a position to agree to that today. I''ll need to run that by my manager.', '오늘 그 자리에서 동의할 수 있는 입장은 아니에요. 매니저와 상의해 봐야 해요.', '["One sixty-five sounds fair to me. Let''s shake on it, and I''ll update the proposal.","I''m not able to agree to that today. I''ll need to check with Derek, our lead developer.","No. One eighty is final, and there''s nothing more to talk about on the price."]', '["16만 5천이면 저는 괜찮은 것 같아요. 악수하죠. 제안서는 제가 고쳐 둘게요.","오늘은 동의해 드릴 수가 없어요. 수석 개발자인 데릭에게 확인해 봐야 해요.","안 돼요. 18만이 최종이고, 가격에 대해서는 더 이야기할 게 없어요."]', '["Great, I''ll tell finance. You''re sure you can sign off on that yourself?","Derek? I thought pricing went through your manager, not engineering.","That''s a pretty hard no. I was hoping for a little more flexibility."]', '["좋아요, 재무팀에 말할게요. 그런데 그걸 혼자 승인하셔도 되는 거 맞죠?","데릭이요? 가격은 개발팀이 아니라 매니저를 거치는 줄 알았는데요.","꽤 단호하시네요. 조금은 여지가 있기를 바랐는데요."]', '["Neither yes nor no. Say who has to decide.","Key words: not in a position to, run that by my manager"]', '["예도 아니요도 아닙니다. 누가 결정해야 하는지 말하세요.","핵심 단어: not in a position to, run that by my manager"]', 'greg', 'Fair enough. While you''re at it, payment terms. Our standard is Net 60.', '그러죠. 그 김에 지급 조건도 봅시다. 우리 기준은 Net 60이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_contract', 3, 'greg', 'Net 60 means waiting two months for every payment. You can give a little, if you get something back.', 'Net 60이면 돈을 받을 때마다 두 달을 기다려야 합니다. 조금 양보할 수는 있습니다. 받는 것이 있다면요.', 'Net 30 is tough for our finance team.', 'Net 30은 우리 재무팀한테 좀 힘들어요.', 'Meet him partway at Net 45, but only in exchange for a purchase order this week.', '중간인 Net 45로 양보하되, 이번 주 안에 발주서를 받는 것을 조건으로 거세요.', '[{"any":["45","forty five","purchase order"]}]', 'If you can commit to a purchase order this week, we can do Net 45.', '이번 주 안에 발주서를 약속해 주시면, Net 45로 해 드릴 수 있어요.', '["Okay, we can do Net 60 for you. We want your finance team happy.","If your finance team can sign by next month, we could look at Net 45.","Net 30 is our standard too. I''m afraid your finance team will need to adjust."]', '["좋아요, Net 60으로 해 드릴게요. 재무팀이 만족하셔야죠.","재무팀이 다음 달까지 서명해 주시면, Net 45를 검토해 볼 수 있어요.","Net 30은 우리 기준이기도 해요. 죄송하지만 재무팀이 맞춰 주셔야겠어요."]', '["Net 60, no strings? Well, I won''t argue with that.","Next month? I could probably get a PO out sooner than that.","So no movement at all? That makes this harder to sell internally."]', '["아무 조건 없이 Net 60이요? 뭐, 저야 마다할 이유가 없죠.","다음 달이요? 발주서는 그보다 빨리 낼 수 있을 것 같은데요.","조금도 못 움직인다고요? 그러면 내부를 설득하기가 더 어려워져요."]', '["Never give for free: \\"If you can …, we can …\\".","Key words: if you can commit to, a purchase order, we can do Net 45"]', '["그냥 내주지 마세요. \\"If you can …, we can …\\".","핵심 단어: if you can commit to, a purchase order, we can do Net 45"]', 'greg', 'A PO this week for Net 45… I can live with that.', '이번 주 발주서에 Net 45라… 그 정도면 받아들일 수 있어요.'),
  ('pr_d10_contract', 4, 'greg', 'Next is the service level agreement, the SLA.', '다음은 서비스 수준 협약(SLA)입니다.', 'Last thing: uptime. We need a guarantee. What can you commit to?', '마지막으로 가동률이요. 보장이 필요해요. 어디까지 약속할 수 있어요?', 'Commit only to what you can actually deliver: 99.9% uptime, and a response within four hours for critical issues.', '실제로 지킬 수 있는 것만 약속하세요. 가동률 99.9퍼센트, 그리고 심각한 장애에는 4시간 안에 대응입니다.', '[{"all":["99"]},{"any":["stand behind","four hour","response time"]}]', 'We only promise what we can stand behind: 99.9 percent uptime and a four-hour response time for critical issues.', '우리는 책임질 수 있는 것만 약속해요. 가동률 99.9퍼센트, 그리고 심각한 장애에는 4시간 안에 대응합니다.', '["We can guarantee one hundred percent uptime, and we''ll respond to any issue within the hour.","We only commit to what we can actually deliver: 99 percent uptime and a twenty-four-hour response for critical issues.","Uptime depends on a lot of things on your side, so it''s hard for us to promise any specific number."]', '["가동률 100퍼센트를 보장해 드릴 수 있고, 어떤 문제든 한 시간 안에 대응할게요.","우리는 실제로 지킬 수 있는 것만 약속해요. 가동률 99퍼센트, 그리고 심각한 장애에는 24시간 안에 대응합니다.","가동률은 그쪽 사정에도 많이 달려 있어서, 구체적인 숫자를 약속하기는 어려워요."]', '["A hundred percent? Nobody can promise that. Are you sure?","Twenty-four hours for a critical issue? Our stores can''t wait a whole day.","I need a number, Priya. Legal won''t accept \\"it depends.\\""]', '["100퍼센트요? 그런 약속은 아무도 못 해요. 정말이에요?","심각한 장애에 24시간이요? 우리 매장들은 하루를 통째로 기다릴 수 없어요.","숫자가 필요해요, 프리야. 법무팀은 \\"상황에 따라 다르다\\"는 말을 안 받아 줘요."]', '["Give clear numbers for uptime and for how fast you answer.","Key words: stand behind, 99.9 percent uptime, four-hour response time"]', '["가동률과 대응 속도를 분명한 숫자로 말하세요.","핵심 단어: stand behind, 99.9 percent uptime, four-hour response time"]', 'greg', 'That''s reasonable. Send me the revised terms and I''ll share them with legal.', '합리적이네요. 수정된 조건을 보내 주면 법무팀과 공유할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_contract', 5, 'greg', 'He comes back to the price one more time.', '그렉이 한 번 더 가격 이야기로 돌아옵니다.', 'And the price? I need something to tell finance today.', '가격은요? 오늘 재무팀에 뭐라도 말해 줘야 해요.', 'Don''t move on the price yet, but tell him he''ll hear from you before the day is over. Keep it friendly.', '아직 가격은 움직이지 마세요. 대신 오늘 안에 답을 주겠다고 하세요. 상냥하게요.', '[{"any":["stands","answer for you"]}]', 'For now, one eighty stands. I''ll have an answer for you by end of day.', '지금으로서는 18만 그대로예요. 오늘 퇴근 전까지 답을 드릴게요.', '["Tell finance one sixty-five for now, and I''ll confirm it by end of day.","The price stays at one eighty for now. I''ll get back to you next week.","Tell them one eighty. That''s the price, and I don''t have anything else for you."]', '["재무팀에는 일단 16만 5천이라고 하세요. 오늘 퇴근 전까지 확정해 드릴게요.","가격은 당분간 18만 그대로예요. 다음 주에 다시 연락드릴게요.","18만이라고 하세요. 그게 가격이고, 더 드릴 말씀은 없어요."]', '["One sixty-five, then. Finance will be happy. I''ll hold you to that.","Next week? I said I need something for finance today.","Okay. That''s... not very helpful, Priya."]', '["그럼 16만 5천이네요. 재무팀이 좋아하겠어요. 그 말 꼭 지키세요.","다음 주요? 오늘 재무팀에 줄 게 필요하다고 했잖아요.","그래요. 그건… 별로 도움이 안 되네요, 프리야."]', '["A price that \\"stands\\" has not changed. Then say when he will hear from you.","Key words: for now, one eighty stands, an answer for you, by end of day"]', '["가격이 stands한다는 것은 바뀌지 않았다는 뜻입니다. 그리고 언제 답을 줄지 말하세요.","핵심 단어: for now, one eighty stands, an answer for you, by end of day"]', 'greg', 'You drive a hard bargain, Priya. End of day, then.', '만만치 않게 협상하시네요, 프리야. 그럼 오늘 퇴근 전까지로 합시다.'),
  ('pr_d10_contract', 6, 'greg', 'Almost noon. Derek and Jun have not said a word about money, just as you agreed.', '정오가 다 되어 갑니다. 약속한 대로 데릭과 준은 돈 이야기를 한마디도 하지 않았습니다.', 'So where does that leave us?', '그래서 우리는 어디까지 온 거죠?', 'Wrap up the meeting: go over what you agreed on and what is still undecided.', '합의한 것과 아직 정해지지 않은 것을 정리하며 회의를 마무리하세요.', '[{"any":["where we landed","still open","landed"]}]', 'Here''s where we landed: Net 45 with a PO this week, 99.9 percent uptime, and the price is still open.', '여기까지 정리하면 이래요. 이번 주 발주서를 조건으로 Net 45, 가동률 99.9퍼센트, 그리고 가격은 아직 미정이에요.', '["Here''s where we are: Net 60 with a PO this week, 99.9 percent uptime, and the price is still open for now.","So we''ve agreed: Net 45 with a PO this week, 99.9 percent uptime, and one sixty-five on price.","I think we made good progress today. Let''s set up another call next week to go over everything."]', '["지금까지 이래요. 이번 주 발주서를 조건으로 Net 60, 가동률 99.9퍼센트, 그리고 가격은 아직은 미정이에요.","그러니까 합의한 건 이래요. 이번 주 발주서 조건으로 Net 45, 가동률 99.9퍼센트, 가격은 16만 5천.","오늘 진전이 꽤 있었던 것 같아요. 다음 주에 통화를 한 번 더 잡아서 전부 다시 훑어보죠."]', '["Net 60? I thought we settled on Net 45 for a PO this week.","One sixty-five? I thought you still had to check with your manager.","Sure, but before we hang up, can you recap where things stand?"]', '["Net 60이요? 이번 주 발주서를 주는 대신 Net 45로 정한 줄 알았는데요.","16만 5천이요? 아직 매니저한테 확인해야 한다고 하지 않았어요?","좋아요. 그런데 끊기 전에 지금 상황을 한번 정리해 줄래요?"]', '["List what is agreed, then say honestly what is not agreed yet.","Key words: here''s where we landed, Net 45, still open"]', '["합의된 것을 나열하고, 아직 합의되지 않은 것을 솔직히 말하세요.","핵심 단어: here''s where we landed, Net 45, still open"]', 'greg', 'That matches my notes. Talk soon.', '제 메모와 같네요. 또 이야기합시다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_refund', 1, 'derek', 'A chilly afternoon. Derek has his hood up and a fresh mug of coffee.', '쌀쌀한 오후입니다. 데릭은 후드를 뒤집어쓰고 갓 내린 커피를 들고 있습니다.', 'Uh-oh. You''ve got that "is it done yet" look.', '아이고. "아직이에요?" 하는 얼굴이네요.', 'He''s caught you. Own it, and ask how the gift card refund fix is coming along.', '들켰습니다. 순순히 인정하고, 기프트 카드 환불 수정이 어떻게 되어 가는지 물어보세요.', '[{"any":["where do we stand","stand on","where are we"]}]', 'Guilty. Where do we stand on the gift card refund fix?', '들켰네요. 기프트 카드 환불 수정은 어디까지 됐어요?', '["Guilty. How''s the checkout page redesign coming along?","You bet. Greg''s waiting, so it had better be done today.","Not at all. When''s the gift card fix supposed to go out?"]', '["들켰네요. 결제 페이지 개편은 어떻게 되어 가요?","당연하죠. 그렉이 기다리니까 오늘은 꼭 끝나 있어야 해요.","전혀요. 기프트 카드 수정은 언제 나갈 예정이었죠?"]', '["The redesign? That''s next quarter. I thought you were here about the refunds.","Whoa, easy. Hello to you too, Priya.","\\"Supposed to\\"? Today, Priya. You''re the one who promised Greg Wednesday."]', '["개편이요? 그건 다음 분기예요. 환불 때문에 온 줄 알았는데요.","워워, 진정해요. 나도 반가워요, 프리야.","\\"예정\\"이요? 오늘이잖아요, 프리야. 그렉한테 수요일이라고 약속한 사람이 프리야예요."]', '["\\"Where do we stand on …?\\" asks for the current status.","Key words: where do we stand on, the gift card refund fix"]', '["\\"Where do we stand on …?\\"은 지금 상태가 어떤지 묻는 말입니다.","핵심 단어: where do we stand on, the gift card refund fix"]', 'derek', 'It went out at noon. It''s live in production.', '정오에 나갔어요. 운영 환경에 올라가 있어요.'),
  ('pr_d10_refund', 2, 'derek', 'On time. But "live" and "working" are not the same thing.', '제때 나갔습니다. 하지만 올라간 것과 잘 돌아가는 것은 다릅니다.', 'Jun wrote the tests, and I did the release.', '테스트는 준이 짰고, 릴리스는 제가 했어요.', 'Be glad, but check whether it has actually been tried for real since it went out.', '기뻐하되, 나간 뒤로 실제로 제대로 써 봤는지 확인하세요.', '[{"any":["tested","real gift card","since the release"]}]', 'That''s great news. Has anyone tested it with a real gift card since the release?', '정말 좋은 소식이네요. 릴리스한 뒤로 실제 기프트 카드로 시험해 본 사람이 있어요?', '["That''s great news. I''ll email Greg right now and tell him everything''s fixed for good.","Great news. Did Jun also do the release, or was that someone else?","Okay, but Jun''s new. Are you sure his tests actually cover everything?"]', '["정말 좋은 소식이네요. 지금 바로 그렉한테 완전히 다 고쳐졌다고 메일 보낼게요.","좋은 소식이네요. 릴리스도 준이 했어요, 아니면 다른 사람이 했어요?","그래요. 그런데 준은 신입이잖아요. 그 테스트가 정말 다 잡아낼까요?"]', '["Hold on. Before you email anyone, there''s something you should know.","Uh, I just said I did the release. You okay?","Jun''s tests are solid. I reviewed every one of them."]', '["잠깐만요. 누구한테 메일 보내기 전에 알아 둘 게 있어요.","어, 릴리스는 제가 했다고 방금 말했는데요. 괜찮아요?","준의 테스트는 탄탄해요. 제가 하나하나 다 검토했어요."]', '["Praise first, then check: \\"Has anyone …?\\"","Key words: great news, has anyone tested it, a real gift card, since the release"]', '["먼저 칭찬하고, \\"Has anyone …?\\"으로 확인하세요.","핵심 단어: great news, has anyone tested it, a real gift card, since the release"]', 'derek', 'Jun ran three refunds an hour ago. All three went through. There''s one catch, though.', '준이 한 시간 전에 환불을 세 건 해 봤어요. 세 건 다 처리됐고요. 그런데 걸리는 게 하나 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_refund', 3, 'derek', 'There is always a catch.', '걸리는 점은 늘 있기 마련입니다.', 'Gift cards from before last March still fail. It''s maybe one refund in a hundred.', '작년 3월 이전에 산 기프트 카드는 아직 실패해요. 백 건에 한 건 정도요.', 'Find out how those customers can get their money back until it''s properly fixed.', '제대로 고쳐지기 전까지 그 고객들이 어떻게 환불을 받을 수 있는지 알아보세요.', '[{"any":["workaround","in the meantime","work around"]}]', 'Is there a workaround for those in the meantime?', '그동안 그런 경우에 쓸 수 있는 우회 방법이 있어요?', '["Is that only for cards from before last May?","Can you fix those too before I email Greg today?","One in a hundred? Nobody will even notice that."]', '["그거 작년 5월 이전 카드만 그런 거예요?","오늘 그렉한테 메일 보내기 전에 그것도 고쳐 줄 수 있어요?","백 건에 한 건이요? 그건 아무도 눈치 못 챌 거예요."]', '["March. Anything bought before last March.","Today? No way. That''s a whole different code path.","Somebody will. And they''ll call support angry."]', '["3월이요. 작년 3월 전에 산 건 전부요.","오늘이요? 절대 안 돼요. 그건 아예 다른 코드 경로예요.","누군가는 알아챌 거예요. 그리고 화가 나서 지원팀에 전화하겠죠."]', '["A \\"workaround\\" gets the job done another way until the real fix is ready.","Key words: a workaround, in the meantime"]', '["workaround는 제대로 된 수정이 나올 때까지 다른 길로 일을 해내는 방법입니다.","핵심 단어: a workaround, in the meantime"]', 'derek', 'Support can refund them by hand. I''ll have a real fix next sprint.', '지원팀이 손으로 환불해 줄 수 있어요. 제대로 된 수정은 다음 스프린트에 할게요.'),
  ('pr_d10_refund', 4, 'derek', 'One in a hundred. Greg might never notice. Or he might.', '백 건에 한 건. 그렉은 끝내 모를 수도 있습니다. 알게 될 수도 있고요.', 'Do you want to tell Greg now, or wait until it''s perfect?', '그렉한테 지금 말할 거예요, 아니면 완벽해질 때까지 기다릴 거예요?', 'You''ve decided to be upfront with Greg. Say when you''ll tell him, and why.', '그렉에게 솔직하게 말하기로 했습니다. 언제 말할지, 그리고 왜 그런지 말하세요.', '[{"any":["known issue","surprises","tell him today"]}]', 'I''ll tell him today, known issue and all. I don''t want any surprises.', '오늘 말할 거예요. 알려진 문제까지 전부요. 나중에 놀랄 일은 만들고 싶지 않아요.', '["Let''s wait until next sprint. I''d rather tell him once it''s perfect.","I''ll tell him today that it''s fixed. The rest can wait until next sprint.","I''ll tell him today, and make it clear the old cards are your team''s problem."]', '["다음 스프린트까지 기다리죠. 완벽해진 다음에 말하는 게 낫겠어요.","오늘 고쳐졌다고만 말할게요. 나머지는 다음 스프린트까지 미뤄도 되잖아요.","오늘 말할게요. 옛날 카드 문제는 데릭네 팀 문제라고 분명히 해 둘게요."]', '["Hmm. And if he hits one of those old cards before then?","That''s not the whole story, though. What if he finds out?","My team''s problem? We''re the same team, Priya."]', '["흠. 그 전에 그렉이 옛날 카드에 걸리면요?","그건 반쪽짜리 이야기잖아요. 나중에 알게 되면 어쩌려고요?","우리 팀 문제요? 우리 같은 팀이에요, 프리야."]', '["\\"… and all\\" = including the part that is not so nice.","Key words: tell him today, known issue and all, no surprises"]', '["\\"… and all\\"은 좋지 않은 부분까지 포함한다는 뜻입니다.","핵심 단어: tell him today, known issue and all, no surprises"]', 'derek', 'And that''s why he trusts you.', '그래서 그렉이 프리야를 믿는 거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_refund', 5, 'derek', 'You open a new email to Greg.', '그렉에게 보낼 새 이메일을 엽니다.', 'Anything you need from me for that email?', '그 이메일에 필요한 거 있어요?', 'Ask him for a short write-up for the release notes, and thank him for seeing the fix through.', '릴리스 노트에 넣을 짧은 글을 부탁하고, 수정을 끝까지 해내 줘서 고맙다고 하세요.', '[{"any":["release notes","finish line"]}]', 'Just two lines for the release notes. And thanks for getting this over the finish line.', '릴리스 노트에 넣을 두 줄만요. 그리고 이거 끝까지 마무리해 줘서 고마워요.', '["Could you write the whole email to Greg for me? You know the details better than I do.","Just a few lines for the release notes. And thanks for writing all those tests yourself.","Just the release notes. Two lines, by four o''clock, please. No later than that."]', '["그렉한테 보낼 이메일을 통째로 써 줄 수 있어요? 자세한 건 데릭이 더 잘 알잖아요.","릴리스 노트에 넣을 몇 줄만요. 그리고 그 테스트들을 직접 다 짜 줘서 고마워요.","릴리스 노트만요. 두 줄, 네 시까지 부탁해요. 그보다 늦으면 안 돼요."]', '["Your email, your voice. I''ll give you the technical bits, though.","Jun wrote the tests, actually. I just shipped it.","Yes, ma''am. Four o''clock sharp."]', '["프리야 이메일은 프리야 목소리로 써야죠. 기술적인 부분은 드릴게요.","테스트는 사실 준이 짰어요. 저는 내보내기만 했고요.","네, 알겠습니다. 네 시 정각에요."]', '["Ask for something small and exact, then thank him for finishing.","Key words: two lines for the release notes, over the finish line"]', '["작고 구체적인 것을 부탁한 뒤, 마무리해 준 것에 고마움을 전하세요.","핵심 단어: two lines for the release notes, over the finish line"]', 'derek', 'No rush, right? Just kidding. You''ll have them in ten minutes.', '급한 건 아니죠? 농담이에요. 10분 안에 보낼게요.'),
  ('pr_d10_signoff', 1, 'maya', 'Maya''s office. She has a jacket over her shoulders and the proposal on her screen.', '마야의 사무실입니다. 마야는 어깨에 재킷을 걸치고 화면에 제안서를 띄워 놓았습니다.', 'Come on in. How''d the call with Greg go?', '들어와요. 그렉하고 통화는 어떻게 됐어요?', 'Lead with the bottom line: what Greg asked for, and where you left the price.', '결론부터 말하세요. 그렉이 무엇을 요구했고, 가격은 어디에 두고 왔는지요.', '[{"any":["held the line","short version"]}]', 'Short version: he wants one sixty-five, and I held the line at one eighty.', '짧게 말하면, 그렉은 16만 5천을 원하고, 저는 18만에서 물러서지 않았어요.', '["Quick summary: he wants one fifty, and I didn''t budge from one eighty.","Good news: he wants one sixty-five, and I told him that should be fine.","Well, it started with the numbers, then we got into payment terms, and then uptime..."]', '["간단히 말하면, 그렉은 15만을 원하고, 저는 18만에서 꿈쩍 안 했어요.","좋은 소식이에요. 그렉은 16만 5천을 원하는데, 그 정도면 괜찮다고 했어요.","음, 처음엔 숫자 얘기로 시작해서, 그다음엔 지급 조건으로 넘어갔고, 그다음엔 가동률…"]', '["One fifty? I heard he''d moved up from there. Which is it?","You told him that? Priya, you know discounts go through me.","Let''s skip the play-by-play. What''s the bottom line?"]', '["15만이요? 거기서 올라왔다고 들었는데요. 어느 쪽이에요?","그렇게 말했어요? 프리야, 할인은 나를 거쳐야 하는 거 알잖아요.","하나하나 중계는 건너뛰죠. 결론이 뭐예요?"]', '["\\"Short version:\\" tells a busy manager the summary comes first.","Key words: short version, one sixty-five, held the line"]', '["\\"Short version:\\"은 바쁜 매니저에게 요약부터 말하겠다는 신호입니다.","핵심 단어: short version, one sixty-five, held the line"]', 'maya', 'Good. That''s about eight percent off. What do you recommend?', '잘했어요. 8퍼센트쯤 깎아 달라는 거네요. 어떻게 하면 좋겠어요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_signoff', 2, 'maya', 'You thought about this over lunch.', '점심을 먹으면서 생각해 둔 것이 있습니다.', 'I want your recommendation, not just the problem.', '문제만 말고 프리야의 제안을 듣고 싶어요.', 'Propose 5% off, tied to a one-year support contract.', '5퍼센트 할인을 제안하되, 1년 지원 계약을 조건으로 거세요.', '[{"all":["support"],"any":["five percent","5 percent","one year","only if"]}]', 'My recommendation is five percent off, but only if they sign a one-year support contract.', '제 제안은 5퍼센트 할인이에요. 다만 1년 지원 계약을 맺는 경우에만요.', '["My recommendation is eight percent off, as long as they sign a one-year support contract.","Honestly, I''m not sure. What would you do? You''ve handled more deals like this.","My recommendation is five percent off, just to keep Greg happy and close it fast."]', '["제 제안은 8퍼센트 할인이에요. 1년 지원 계약을 맺는다는 조건으로요.","솔직히 잘 모르겠어요. 마야라면 어떻게 하겠어요? 이런 거래는 더 많이 해 봤잖아요.","제 제안은 5퍼센트 할인이에요. 그렉 기분도 맞춰 주고 빨리 끝내자는 거죠."]', '["Eight? That''s everything he asked for. What are we getting back?","I asked for your recommendation, Priya. Take a position.","Five percent for nothing in return? I''m not sure about that."]', '["8퍼센트요? 그건 그렉이 원한 걸 다 주는 거예요. 우리가 받는 건 뭐죠?","프리야의 제안을 물은 거예요. 입장을 정해 봐요.","아무것도 안 받고 5퍼센트를요? 그건 잘 모르겠네요."]', '["\\"My recommendation is …\\" plus the condition: \\"but only if …\\".","Key words: my recommendation is, five percent off, only if, one-year support contract"]', '["\\"My recommendation is …\\"에 \\"but only if …\\"로 조건을 붙이세요.","핵심 단어: my recommendation is, five percent off, only if, one-year support contract"]', 'maya', 'So we give a little now and get a year of steady revenue. I like it.', '지금 조금 내주고 1년 동안 안정된 매출을 얻는 거네요. 마음에 들어요.'),
  ('pr_d10_signoff', 3, 'maya', 'Maya likes to test an idea before she approves it.', '마야는 승인하기 전에 생각을 시험해 보기를 좋아합니다.', 'Let me push on that. Why not just give him the eight percent and close today?', '한번 반박해 볼게요. 그냥 8퍼센트 주고 오늘 마무리하면 왜 안 돼요?', 'Defend your plan: explain what giving him everything now would mean for the phases that come later.', '당신의 안을 지키세요. 지금 다 들어주면 이후 단계들에서 어떻게 될지 설명하세요.', '[{"any":["precedent","every phase"]}]', 'Because it would set a precedent. He''d expect a discount on every phase after this.', '선례가 되니까요. 그러면 그렉은 이다음 단계마다 매번 할인을 기대할 거예요.', '["That''s fair. Eight percent and a signature today is probably better than waiting around.","Because Greg always pushes too hard, and I don''t want him to think he''s won.","Because I already told Greg on the call that five percent is our final offer."]', '["일리 있네요. 오늘 8퍼센트 주고 서명받는 게 기다리는 것보다 낫겠어요.","그렉은 늘 너무 밀어붙이거든요. 자기가 이겼다고 생각하게 두고 싶지 않아요.","통화할 때 그렉한테 5퍼센트가 최종 제안이라고 이미 말해 버렸거든요."]', '["You''re giving in that fast? I was testing you, Priya.","Let''s keep this about the business, not about Greg.","You told him that already? I haven''t approved anything yet."]', '["그렇게 금방 물러서요? 시험해 본 거예요, 프리야.","그렉 개인 말고 사업 얘기로만 하죠.","벌써 그렇게 말했어요? 난 아직 아무것도 승인 안 했는데요."]', '["A \\"precedent\\" is something done once that people expect again.","Key words: set a precedent, a discount on every phase"]', '["precedent는 한 번 하면 다음에도 기대하게 되는 선례입니다.","핵심 단어: set a precedent, a discount on every phase"]', 'maya', 'Exactly what I wanted to hear. Five percent is my limit, though.', '바로 그 말을 듣고 싶었어요. 그래도 5퍼센트가 한계예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d10_signoff', 4, 'maya', 'There is one thing you agreed to on the call without asking her.', '통화에서 마야에게 묻지 않고 합의한 것이 하나 있습니다.', 'Anything else I should know before I sign off?', '승인하기 전에 내가 알아야 할 게 더 있어요?', 'Come clean about the payment terms you agreed to on the call without her, and check that she''s okay with them.', '통화에서 마야에게 묻지 않고 정한 지급 조건을 털어놓고, 그래도 괜찮은지 확인하세요.', '[{"any":["comfortable","net 45","purchase order"]}]', 'One more thing: I agreed to Net 45 in exchange for a purchase order this week. Are you comfortable with that?', '하나 더 있어요. 이번 주 발주서를 받는 대신 Net 45에 합의했어요. 괜찮으시겠어요?', '["One more thing: I agreed to Net 60 in exchange for a purchase order this week. Is that okay with you?","No, I think that covers it. The rest of the call was pretty standard stuff, so there''s nothing to worry about.","Also, I gave him Net 45 for a PO this week. There wasn''t time to check with you, so it''s done."]', '["하나 더 있어요. 이번 주 발주서를 받는 대신 Net 60에 합의했어요. 괜찮으시죠?","아니요, 그게 다인 것 같아요. 나머지는 흔한 얘기였으니까 걱정할 건 하나도 없어요.","그리고 이번 주 발주서 받는 대신 Net 45로 해 줬어요. 물어볼 시간이 없어서 그냥 정했어요."]', '["Net 60 for a PO? That''s giving him everything he asked for.","Nothing at all? Greg didn''t push on payment terms? That''s not like him.","Okay... next time, I''d appreciate being asked, not told."]', '["발주서 하나에 Net 60이요? 그렉이 달라는 걸 다 준 거잖아요.","아무것도요? 그렉이 지급 조건을 안 밀어붙였다고요? 그 사람답지 않은데요.","그래요… 다음엔 통보 말고 먼저 물어봐 줬으면 좋겠어요."]', '["Tell her what you already gave away, then check: \\"Are you comfortable with that?\\"","Key words: I agreed to Net 45, in exchange for, are you comfortable with that"]', '["이미 내준 것을 알리고 확인하세요. \\"Are you comfortable with that?\\"","핵심 단어: I agreed to Net 45, in exchange for, are you comfortable with that"]', 'maya', 'Very. A PO this week is worth more than fifteen days. Just don''t put the discount in writing until legal reviews it.', '그럼요. 이번 주 발주서가 15일보다 값져요. 다만 법무팀이 검토하기 전에는 할인을 서면으로 남기지 마세요.'),
  ('pr_d10_signoff', 5, 'maya', 'Maya picks up her pen.', '마야가 펜을 집어 듭니다.', 'So, are we clear on the limits?', '그럼, 한도는 확실히 정리된 거죠?', 'Repeat the limits back to her, and add that you''ll get Jun up to speed before his flight.', '한도를 다시 확인해 주고, 준이 비행기를 타기 전에 내용을 알려 주겠다고 덧붙이세요.', '[{"any":["ceiling","brief jun","legal signs off"]}]', 'Clear. Five percent is the ceiling, nothing goes out until legal signs off, and I''ll brief Jun before he flies.', '네. 5퍼센트가 상한선이고, 법무팀이 승인하기 전에는 아무것도 내보내지 않고, 준이 떠나기 전에 제가 설명해 둘게요.', '["Clear. Eight percent is the ceiling, nothing goes out until legal signs off, and I''ll brief Jun before he flies.","Got it. Five percent is the ceiling, and I''ll email Greg the discount today so Jun can just sign.","Yes. And if Greg pushes hard, Jun can go up to eight percent to close the deal, right?"]', '["네. 8퍼센트가 상한선이고, 법무팀이 승인하기 전에는 아무것도 내보내지 않고, 준이 떠나기 전에 설명해 둘게요.","알겠어요. 5퍼센트가 상한선이고, 오늘 그렉한테 할인 내용을 메일로 보내서 준은 서명만 하면 되게 할게요.","네. 그런데 그렉이 세게 나오면 준이 계약을 따내려고 8퍼센트까지 가도 되는 거죠?"]', '["Eight? I said five was my limit. Let''s get this right.","Not today. Nothing in writing until legal has reviewed it.","No. The ceiling is the ceiling, Jun included."]', '["8퍼센트요? 내 한계는 5라고 했잖아요. 제대로 정리하죠.","오늘은 안 돼요. 법무팀이 검토하기 전에는 서면으로 아무것도 안 돼요.","아니요. 상한선은 상한선이에요. 준도 마찬가지고요."]', '["Repeat the limit and the condition, and add who you will tell.","Key words: five percent is the ceiling, legal signs off, brief Jun"]', '["한도와 조건을 되짚고, 누구에게 알릴지 덧붙이세요.","핵심 단어: five percent is the ceiling, legal signs off, brief Jun"]', 'maya', 'Perfect. You have my sign-off. Let me know if you have any questions.', '완벽해요. 승인할게요. 궁금한 게 있으면 말해 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_clause', 1, 'greg', 'A clear Thursday morning. Jun is in the air. The phone in the meeting room rings.', '맑은 목요일 아침입니다. 준은 비행기 안에 있습니다. 회의실 전화가 울립니다.', 'Priya, it''s Greg. Sorry to spring this on you, but legal wants to add a clause before Jun gets here.', '프리야, 그렉이에요. 갑자기 이런 얘기 해서 미안한데, 준이 오기 전에 법무팀이 조항을 하나 넣고 싶어 해요.', 'Keep your cool. Appreciate the warning, and find out what legal wants to add.', '침착하세요. 미리 알려 준 것에 고마워하고, 법무팀이 무엇을 넣으려는지 알아보세요.', '[{"any":["what exactly","clause say","clause says"]}]', 'Thanks for telling me before the meeting. What exactly does the clause say?', '회의 전에 알려 줘서 고마워요. 그 조항이 정확히 어떤 내용이에요?', '["Seriously? The day of the meeting? That''s really not how this works, Greg.","No problem at all. Tell legal to add whatever they need, and Jun will sign it.","Thanks for telling me. Should I ask Jun to push the meeting to next week?"]', '["진심이에요? 회의 당일에요? 이건 정말 이렇게 하는 게 아니죠, 그렉.","전혀 문제없어요. 법무팀이 필요한 건 다 넣으라고 하세요. 준이 서명할 거예요.","알려 줘서 고마워요. 준한테 회의를 다음 주로 미루자고 할까요?"]', '["I know, I know. I''m not happy about it either.","Don''t you want to hear what it says first?","Let''s not go that far. Hear me out first."]', '["알아요, 알아요. 저도 이게 달갑지 않아요.","무슨 내용인지 먼저 들어 봐야 하지 않아요?","거기까지 가진 말죠. 일단 제 얘기부터 들어 봐요."]', '["First the facts. Ask \\"What exactly …?\\" before you react.","Key words: thanks for telling me, what exactly, the clause"]', '["먼저 사실부터 확인하세요. 반응하기 전에 \\"What exactly …?\\"로 물어보세요.","핵심 단어: thanks for telling me, what exactly, the clause"]', 'greg', 'A late-delivery penalty. Two percent of the contract for every week past November first.', '납기 지연 위약금이에요. 11월 1일을 넘기면 한 주마다 계약 금액의 2퍼센트.'),
  ('pr_d11_clause', 2, 'greg', 'Two percent of $171,000 is more than $3,400 a week. You write the number down.', '17만 1천 달러의 2퍼센트면 한 주에 3,400달러가 넘습니다. 당신은 그 숫자를 적어 둡니다.', 'Legal says it''s standard. Can I tell them you''re fine with it?', '법무팀은 이게 표준이래요. 괜찮다고 전해도 될까요?', 'Don''t answer yet. Repeat the terms back to check them, including whether there''s a limit on the total.', '아직 답하지 마세요. 조건을 되짚어 확인하고, 총액에 한도가 있는지도 확인하세요.', '[{"any":["have this right","no cap","got this right"]}]', 'Let me make sure I have this right: two percent a week, with no cap?', '제가 제대로 이해했는지 확인할게요. 한 주에 2퍼센트이고, 상한은 없는 거죠?', '["Just to be clear: two percent a month, with a cap at ten percent?","If legal says it''s standard, then sure, you can tell them we''re fine.","So that''s two percent of the contract for every day past November first?"]', '["확실히 해 두자면, 한 달에 2퍼센트이고 상한은 10퍼센트인 거죠?","법무팀이 표준이라고 하면, 그래요, 우리는 괜찮다고 전하세요.","그러니까 11월 1일을 넘기면 하루마다 계약 금액의 2퍼센트라는 거죠?"]', '["A week, not a month. And no, there''s no cap.","Really? Just like that? I expected more of a fight.","Every week, not every day. Still, I know it adds up."]', '["한 달이 아니라 한 주요. 그리고 아니요, 상한은 없어요.","정말요? 그렇게 쉽게요? 좀 더 버틸 줄 알았는데요.","하루가 아니라 한 주마다요. 그래도 쌓이면 크다는 건 알아요."]', '["Repeat the terms as a question. A \\"cap\\" is an upper limit.","Key words: make sure I have this right, two percent a week, no cap"]', '["조건을 질문으로 되짚으세요. cap은 상한선입니다.","핵심 단어: make sure I have this right, two percent a week, no cap"]', 'greg', 'No cap. I know how that sounds.', '상한은 없어요. 어떻게 들릴지 저도 압니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_clause', 3, 'greg', 'He wants an answer now. You do not have to give one.', '그렉은 지금 답을 원합니다. 하지만 지금 답할 필요는 없습니다.', 'I need an answer before Jun walks in at two. Yes or no?', '두 시에 준이 들어오기 전에 답이 필요해요. 예스예요, 노예요?', 'Don''t let him rush you. Ask for an hour, and promise him an answer.', '재촉에 넘어가지 마세요. 한 시간만 달라고 하고, 답을 주겠다고 약속하세요.', '[{"any":["on the spot","give me an hour","call you back"]}]', 'I can''t agree to that on the spot. Give me an hour, and I''ll call you back with an answer.', '이 자리에서 바로 동의할 수는 없어요. 한 시간만 주세요. 답을 갖고 다시 전화할게요.', '["Fine, yes. We''ll hit November first anyway, so the penalty shouldn''t matter.","No. And honestly, springing this on us today is not a great look for your side.","I can''t agree to that right now. Give me until tomorrow morning, and I''ll get back to you then."]', '["좋아요, 예스예요. 어차피 11월 1일은 맞출 거니까 위약금은 상관없을 거예요.","노예요. 그리고 솔직히 오늘 이걸 갑자기 들이미는 건 그쪽 모양새가 좋지 않아요.","지금 당장은 동의할 수 없어요. 내일 아침까지 시간을 주시면 그때 다시 연락드릴게요."]', '["Good. I''ll let legal know right away.","Wow. Okay. I''m just the messenger here, Priya.","Tomorrow? Jun walks in at two today."]', '["좋아요. 법무팀에 바로 알릴게요.","와. 알겠어요. 저는 말을 전하는 것뿐이에요, 프리야.","내일이요? 준은 오늘 두 시에 들어와요."]', '["Buy time with a clear limit: how long, and what he gets then.","Key words: can''t agree on the spot, give me an hour, call you back"]', '["분명한 기한을 두고 시간을 버세요. 얼마 동안인지, 그때 무엇을 받게 되는지 말합니다.","핵심 단어: can''t agree on the spot, give me an hour, call you back"]', 'greg', 'An hour. Fine. But I''m telling you, the board won''t sign without something.', '한 시간. 좋아요. 그래도 말해 두는데, 이사회는 뭐라도 없으면 서명하지 않을 겁니다.'),
  ('pr_d11_clause', 4, 'greg', '"Without something." So the penalty itself may not be the point.', '"뭐라도 없으면." 그렇다면 위약금 자체가 핵심은 아닐지도 모릅니다.', 'They were very clear about that.', '그 부분은 아주 분명하게 말하더라고요.', 'The penalty may not be what they really care about. Find out what is.', '그들이 정말 신경 쓰는 건 위약금이 아닐 수도 있습니다. 진짜 걱정이 무엇인지 알아내세요.', '[{"any":["help me understand","concern behind","what is the concern"]}]', 'Help me understand. What''s the concern behind the clause?', '제가 이해할 수 있게 도와주세요. 그 조항 뒤에 있는 걱정이 뭐예요?', '["Would legal take one percent a week instead of two, then?","Then they''ll have to be clear about it without our signature.","Is this because our team missed a date with you?"]', '["그럼 법무팀이 한 주에 2퍼센트 말고 1퍼센트면 받아 줄까요?","그렇다면 우리 서명 없이 분명하게 하셔야겠네요, 그렉.","혹시 우리 팀이 날짜를 못 지킨 적이 있어서인가요?"]', '["Maybe. But I don''t think the number is really the point for them.","Come on, Priya. Nobody wants this deal to fall apart.","No, no. Your team''s been great. This isn''t about you."]', '["그럴 수도 있죠. 그런데 그들한테 숫자가 핵심인 것 같진 않아요.","왜 이래요, 프리야. 이 계약이 깨지길 바라는 사람은 없어요.","아니, 아니요. 그쪽 팀은 훌륭했어요. 그쪽 때문이 아니에요."]', '["Ask about the worry, not about the wording.","Key words: help me understand, the concern behind the clause"]', '["문구가 아니라 걱정이 무엇인지 물어보세요.","핵심 단어: help me understand, the concern behind the clause"]', 'greg', 'They got burned by a vendor last year. Six months late, and nobody said a word until the last week.', '작년에 어떤 업체한테 크게 데었어요. 6개월이나 늦었는데, 마지막 주까지 아무도 말을 안 해 줬죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_clause', 5, 'greg', 'So it is about surprises, not about money.', '그렇다면 문제는 돈이 아니라 뒤늦게 알게 되는 일입니다.', 'They don''t want to be surprised again.', '다시는 뒤통수 맞고 싶지 않은 거죠.', 'Offer something in place of the penalty that answers their real fear: updates every week, and a written warning the moment a deadline looks shaky.', '위약금 대신 그들의 진짜 걱정을 풀어 줄 안을 내놓으세요. 매주 진행 상황을 알리고, 기한이 흔들리는 순간 서면으로 알리는 것이요.', '[{"any":["status report","written notice","weekly"]}]', 'What if we offered a weekly status report, and written notice as soon as any date is at risk, in place of a penalty?', '위약금 대신 주간 현황 보고를 드리고, 어떤 날짜든 위험해지는 즉시 서면으로 알려 드리면 어떨까요?', '["What if we kept the penalty in, but capped it at five percent of the whole contract and only started it two weeks late?","What if we sent a monthly status report, and told you about any risks at the end of each quarter?","Honestly, we''ve never missed a date with you, so tell them there''s nothing to worry about. Trust us."]', '["위약금은 그대로 두되, 계약 금액의 5퍼센트로 상한을 두고 2주 늦은 시점부터 적용하면 어떨까요?","월간 현황 보고를 보내 드리고, 위험 요소는 분기가 끝날 때마다 알려 드리면 어떨까요?","솔직히 우리는 날짜를 어긴 적이 한 번도 없잖아요. 걱정할 것 없다고 전해 주세요. 믿으셔도 돼요."]', '["A cap helps, but it''s still a penalty. That''s not really what they''re after.","Once a quarter? That''s how they got burned last time.","That''s what the last vendor said, too. \\"Trust us\\" won''t fly with the board."]', '["상한이 있으면 낫긴 하지만, 그래도 위약금이잖아요. 그들이 원하는 건 그게 아니에요.","분기에 한 번이요? 지난번에 그렇게 당한 거예요.","지난 업체도 그렇게 말했어요. \\"믿어 달라\\"는 이사회에서 안 통해요."]', '["Solve the worry another way: \\"What if we offered …?\\"","Key words: what if we offered, a weekly status report, written notice, in place of a penalty"]', '["걱정을 다른 방법으로 풀어 주세요. \\"What if we offered …?\\"","핵심 단어: what if we offered, a weekly status report, written notice, in place of a penalty"]', 'greg', 'No surprises in place of penalties… I could take that to legal. Can you put it in an email?', '위약금 대신 놀랄 일을 없앤다… 그거라면 법무팀에 가져가 볼 수 있겠어요. 이메일로 보내 줄 수 있어요?'),
  ('pr_d11_clause', 6, 'greg', 'Maya said it yesterday: nothing in writing until she and legal have seen it.', '어제 마야가 말했습니다. 마야와 법무팀이 보기 전에는 아무것도 서면으로 남기지 말라고요.', 'Five lines would do.', '다섯 줄이면 돼요.', 'Don''t send anything yet. Tell him what has to happen on your side first, and when he''ll get it.', '아직 아무것도 보내지 마세요. 이쪽에서 먼저 거쳐야 할 단계와, 언제 받게 될지를 말하세요.', '[{"any":["loop in maya","loop maya in","signs off"]}]', 'Let me loop in Maya first. You''ll have it in writing as soon as she signs off.', '먼저 마야에게 알릴게요. 마야가 승인하는 대로 서면으로 보내 드릴게요.', '["Sure, I''ll write it up now and send it over in the next ten minutes.","Let me run it by Derek first. You''ll have it in writing once he''s okay with it.","I can''t put anything in writing. You''ll have to take my word for it, Greg."]', '["그럼요, 지금 바로 써서 10분 안에 보내 드릴게요.","먼저 데릭에게 확인받을게요. 데릭이 괜찮다고 하면 서면으로 보내 드릴게요.","서면으로는 아무것도 못 드려요. 제 말을 믿으셔야 해요, 그렉."]', '["Ten minutes? Great. That''s faster than I expected.","Derek? I thought Maya made the calls on contract terms.","My word won''t get past legal. They need something on paper."]', '["10분이요? 좋네요. 생각보다 빠르네요.","데릭이요? 계약 조건은 마야가 결정하는 줄 알았는데요.","제 말로는 법무팀을 못 넘어요. 종이로 된 게 필요해요."]', '["Say who has to see it first, and when he will get it.","Key words: loop in Maya first, in writing, as soon as she signs off"]', '["누가 먼저 봐야 하는지, 그리고 그렉이 언제 받게 되는지 말하세요.","핵심 단어: loop in Maya first, in writing, as soon as she signs off"]', 'greg', 'Fair enough. And Priya? Thanks for not just saying no.', '그러죠. 그리고 프리야, 그냥 안 된다고만 하지 않아서 고마워요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_jun', 1, 'jun', 'Your phone buzzes on your desk. It is Jun, calling from the Pinecrest Hotel in Ridgeport.', '책상 위에서 휴대전화가 울립니다. 리지포트의 파인크레스트 호텔에서 준이 건 전화입니다.', 'Hi, Priya. I just checked in. The meeting with Greg is at two, and honestly, I''m a little nervous.', '안녕하세요, 프리야. 방금 체크인했어요. 그렉하고 회의는 두 시인데, 솔직히 좀 긴장돼요.', 'Reassure him, and remind him how well he knows this project.', '안심시켜 주세요. 그가 이 프로젝트를 얼마나 잘 아는지 일깨워 주세요.', '[{"any":["normal","better than anyone"]}]', 'That''s completely normal. You know this project better than anyone in that room.', '그건 아주 당연해요. 그 회의실에서 이 프로젝트를 준보다 잘 아는 사람은 없어요.', '["Don''t be nervous. It''s just a meeting, so try not to overthink it, okay?","You should be a little nervous. This deal is the biggest one we''ve had all year.","That''s normal. Just remember the meeting with Greg is at three, so you have time."]', '["긴장하지 마요. 그냥 회의일 뿐이니까 너무 깊이 생각하지 말고요, 알았죠?","좀 긴장하는 게 맞아요. 이번 계약이 올해 우리가 한 것 중에 제일 크거든요.","당연해요. 그렉하고 회의는 세 시니까, 시간은 충분하다는 것만 기억해요."]', '["I know. It''s just... easier said than done.","Wow. That''s not making me feel any better, Priya.","Three? My calendar says two. Did it move?"]', '["알아요. 그냥… 말처럼 쉽지가 않네요.","와. 그 말 들으니까 더 떨리는데요, 프리야.","세 시요? 제 일정엔 두 시로 되어 있는데요. 바뀌었어요?"]', '["First the feeling, then a fact that gives him confidence.","Key words: completely normal, better than anyone, in that room"]', '["먼저 마음을 받아 주고, 자신감을 줄 사실을 말하세요.","핵심 단어: completely normal, better than anyone, in that room"]', 'jun', 'Thanks. I needed that.', '고마워요. 그 말이 필요했어요.'),
  ('pr_d11_jun', 2, 'jun', 'You hear him turn a page in his notebook.', '준이 공책을 넘기는 소리가 들립니다.', 'So what should I focus on?', '그럼 저는 뭐에 집중하면 돼요?', 'Tell him to keep to the terms you''ve already agreed on, and go through them.', '이미 합의한 조건에서 벗어나지 말라고 하고, 하나씩 짚어 주세요.', '[{"any":["stick to","agreed on","what we agreed"]}]', 'Stick to what we agreed on: Net 45, five percent with the support contract, and 99.9 percent uptime.', '우리가 합의한 것만 지켜요. Net 45, 지원 계약을 조건으로 5퍼센트, 그리고 가동률 99.9퍼센트요.', '["Keep to the plan we agreed on: Net 45, eight percent with the support contract, and 99.9 percent uptime.","Focus on the basics: Net 30, five percent off no matter what, and a hundred percent uptime.","Focus on the tech. Leave the business side to Greg, and agree to whatever he proposes."]', '["합의한 계획대로만 해요. Net 45, 지원 계약을 조건으로 8퍼센트, 그리고 가동률 99.9퍼센트요.","기본만 챙겨요. Net 30, 무슨 일이 있어도 5퍼센트 할인, 그리고 가동률 100퍼센트요.","기술 쪽에만 집중해요. 사업 얘기는 그렉한테 맡기고, 그쪽이 뭘 제안하든 동의하고요."]', '["Eight? I thought Maya said five was the limit.","Net 30? And a hundred percent? That''s not what''s in my notes.","Agree to anything? That doesn''t sound right."]', '["8퍼센트요? 마야는 5가 한도라고 한 줄 알았는데요.","Net 30이요? 그리고 100퍼센트요? 제 메모랑 다른데요.","뭐든 동의하라고요? 그건 좀 아닌 것 같은데요."]', '["\\"Stick to\\" = do not move away from. Then list the three terms.","Key words: stick to what we agreed on, Net 45, five percent, 99.9 percent"]', '["stick to는 거기서 벗어나지 않는다는 뜻입니다. 그리고 조건 세 가지를 말하세요.","핵심 단어: stick to what we agreed on, Net 45, five percent, 99.9 percent"]', 'jun', 'Net 45, five percent, 99.9. They''re on the first page of my notes.', 'Net 45, 5퍼센트, 99.9. 메모 첫 장에 적어 뒀어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_jun', 3, 'jun', 'Greg likes to ask for one more thing at the end of a meeting.', '그렉은 회의가 끝날 때쯤 하나만 더 하며 부탁하기를 좋아합니다.', 'What if he asks for something new? A bigger discount, or another feature?', '그렉이 새로운 걸 요구하면요? 할인을 더 해 달라거나, 기능을 하나 더 넣어 달라거나요.', 'Tell him not to commit to anything new on the spot, and give him a line he can use to buy time.', '새로운 건 그 자리에서 약속하지 말라고 하고, 시간을 벌 수 있는 한마디를 알려 주세요.', '[{"any":["take that back","take it back","in the room"]}]', 'Don''t promise anything in the room. Just say, "Let me take that back to the team."', '그 자리에서는 아무것도 약속하지 마요. 그냥 "Let me take that back to the team."이라고 하면 돼요.', '["If it''s something small, just say yes. We want Greg happy, and we can figure it out later.","Just say no to anything new. Tell him, \\"That''s not in the contract, period.\\"","You can go up to eight percent if you need to. Anything more, just say no."]', '["사소한 거면 그냥 예스라고 해요. 그렉이 만족해야 하니까, 나머지는 나중에 해결하면 돼요.","새로운 건 전부 거절해요. 그렉한테 \\"계약서에 없는 건 안 됩니다. 이상입니다.\\"라고 딱 잘라 말하고요.","필요하면 할인은 8퍼센트까지는 가도 괜찮아요. 그 이상을 요구하면 그냥 안 된다고 하고요."]', '["Really? Even a new feature? Derek''s team is already stretched.","Isn''t that a little harsh? Greg''s the client.","Eight? Maya said five percent was the ceiling."]', '["정말요? 새 기능도요? 데릭 팀은 이미 빠듯한데요.","그건 좀 심하지 않아요? 그렉은 고객이잖아요.","8이요? 마야는 5퍼센트가 상한선이라고 했어요."]', '["Give him one sentence he can use when he feels pushed.","Key words: don''t promise anything in the room, take that back to the team"]', '["밀린다고 느낄 때 쓸 수 있는 문장 하나를 알려 주세요.","핵심 단어: don''t promise anything in the room, take that back to the team"]', 'jun', '"Let me take that back to the team." Okay. That buys me time.', '"Let me take that back to the team." 알겠어요. 그러면 시간을 벌 수 있겠네요.'),
  ('pr_d11_jun', 4, 'jun', 'You read the contract draft last night. One line jumped out at you.', '어젯밤에 계약서 초안을 읽었습니다. 한 줄이 눈에 걸렸습니다.', 'Is there anything I should watch out for in the draft?', '초안에서 조심해야 할 부분이 있어요?', 'Point him to the line that bothered you: the draft gives only seven days'' notice to cancel, and you want thirty.', '마음에 걸린 줄을 짚어 주세요. 초안에는 해지 통보가 7일 전으로 되어 있는데, 30일은 필요합니다.', '[{"any":["push back","thirty","30"]}]', 'Yes. Push back on the seven-day cancellation notice. We need thirty days.', '네. 7일 전 해지 통보 조항은 받아들이지 말고 반박해요. 30일은 필요해요.', '["Yes, the cancellation notice. It says thirty days, and we need at least ninety.","Not really. Legal already went through it, so you can just sign where they tell you.","Yes. Watch the uptime section. They want a hundred percent, and we can''t do that."]', '["네, 해지 통보요. 30일로 되어 있는데, 우리는 최소 90일이 필요해요.","딱히 없어요. 법무팀이 이미 다 봤으니까, 하라는 곳에 서명만 하면 돼요.","네. 가동률 부분을 조심해요. 100퍼센트를 원하는데, 우린 그건 못 해요."]', '["Thirty? My copy says seven days. Are we looking at the same draft?","Sign? I thought Maya was signing, not me.","Uptime? I thought we''d already settled on 99.9 with Greg."]', '["30일이요? 제 사본엔 7일로 되어 있는데요. 같은 초안 보고 있는 거 맞아요?","서명이요? 서명은 제가 아니라 마야가 하는 줄 알았는데요.","가동률이요? 그건 그렉하고 99.9로 이미 정리된 줄 알았는데요."]', '["\\"Push back on\\" = disagree with politely. Name the clause and the number you need.","Key words: push back on, seven-day cancellation notice, thirty days"]', '["push back on은 정중하게 이의를 제기한다는 뜻입니다. 조항과 필요한 숫자를 말하세요.","핵심 단어: push back on, seven-day cancellation notice, thirty days"]', 'jun', 'Seven days is too short. Ask for thirty. Got it.', '7일은 너무 짧다. 30일을 요청한다. 알겠습니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d11_jun', 5, 'jun', 'It is almost one thirty. Jun has to leave for Summit Retail soon.', '한 시 반이 다 되어 갑니다. 준은 곧 서밋 리테일로 출발해야 합니다.', 'And what if I get stuck?', '그리고 제가 막히면요?', 'Tell him he can always reach you, and send him off with some confidence.', '언제든 연락할 수 있다고 하고, 자신감을 실어 보내 주세요.', '[{"any":["phone call away","step out","you have got this"]}]', 'Then step out and call me. I''m only a phone call away. You''ve got this.', '그럼 잠깐 나와서 나한테 전화해요. 전화 한 통이면 닿아요. 잘할 거예요.', '["Then just do your best. I''m in meetings all afternoon, so I can''t pick up.","Then just agree with Greg. We can always fix it later. You''ll be fine.","Then let Greg do the talking. Honestly, you''re new, so nobody expects much."]', '["그럼 그냥 최선을 다해요. 나는 오후 내내 회의라서 전화를 못 받아요.","그럼 그냥 그렉 말에 동의해요. 나중에 언제든 고치면 돼요. 괜찮을 거예요.","그럼 그렉이 말하게 둬요. 솔직히 준은 신입이라 다들 기대도 별로 안 해요."]', '["Oh. Okay. I guess I''m on my own, then.","Agree with him? You just told me not to promise anything.","Ouch. Thanks, I guess."]', '["아. 네. 그럼 저 혼자 해야겠네요.","동의하라고요? 방금 아무것도 약속하지 말라고 했잖아요.","아야. 뭐, 고마워요."]', '["Tell him what to do, where you are, and that you believe in him.","Key words: step out and call me, a phone call away, you''ve got this"]', '["어떻게 하면 되는지, 당신이 어디에 있는지, 그리고 그를 믿는다는 것을 말하세요.","핵심 단어: step out and call me, a phone call away, you''ve got this"]', 'jun', 'Thanks, Priya. I''ll text you when it''s over.', '고마워요, 프리야. 끝나면 문자 드릴게요.'),
  ('pr_d12_headcount', 1, 'maya', 'Maya''s office, Friday afternoon. The signed contract is on her screen.', '금요일 오후, 마야의 사무실입니다. 화면에 서명이 끝난 계약서가 떠 있습니다.', 'Congratulations, Priya. You ran a great negotiation.', '축하해요, 프리야. 협상 정말 잘했어요.', 'Accept the praise, but make sure Maya knows what Jun and Derek each did.', '칭찬은 받되, 준과 데릭이 각각 무엇을 했는지 마야가 알게 하세요.', '[{"any":["credit","jun closed","derek kept"]}]', 'Thank you. Credit where it''s due: Jun closed it in the room, and Derek kept every date we promised.', '고마워요. 그런데 공은 제대로 돌려야죠. 현장에서 마무리한 건 준이고, 약속한 날짜를 다 지킨 건 데릭이에요.', '["Thank you. It took a lot of late nights, but honestly, I''m proud of how I handled Greg this time around.","Thank you. Credit to the team: Derek closed it in the room, and Jun kept every date we promised.","Oh, it was nothing. Honestly, Greg was ready to sign from the very start anyway."]', '["고마워요. 늦게까지 일한 날이 많았지만, 솔직히 이번에 그렉을 상대한 건 제가 생각해도 뿌듯해요.","고마워요. 공은 팀에 있어요. 현장에서 마무리한 건 데릭이고, 약속한 날짜를 다 지킨 건 준이에요.","에이, 별거 아니었어요. 솔직히 그렉은 처음부터 어차피 서명할 생각이었던 것 같아요."]', '["You did. And the team? I hear Jun did well in Ridgeport.","Derek was in Ridgeport? I thought Jun made the trip.","Ready to sign? He asked for a penalty clause the day before."]', '["잘했죠. 그런데 팀은요? 준이 리지포트에서 잘했다던데요.","데릭이 리지포트에 갔어요? 출장은 준이 간 줄 알았는데요.","서명할 생각이었다고요? 전날에 위약금 조항까지 요구했잖아요."]', '["Accept the praise, then name who did what.","Key words: credit where it''s due, Jun closed it, Derek kept every date"]', '["칭찬을 받아들인 뒤, 누가 무엇을 했는지 이름을 들어 말하세요.","핵심 단어: credit where it''s due, Jun closed it, Derek kept every date"]', 'maya', 'Noted. I''ll mention both of them to the leadership team.', '기억해 둘게요. 경영진에게 두 사람 이야기를 꼭 할게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_headcount', 2, 'maya', 'Maya opens the project plan. She always looks ahead.', '마야가 프로젝트 계획을 엽니다. 마야는 언제나 앞일을 봅니다.', 'So. Phase one by November first. Are we staffed for it?', '자, 1단계는 11월 1일까지예요. 인원은 충분해요?', 'Be straight with her about how the team is coping with only two developers.', '개발자 두 명뿐인 팀이 어떻게 버티고 있는지 솔직하게 말하세요.', '[{"any":["stretched thin","not quite","stretched"]}]', 'Honestly, not quite. With two developers, we''re stretched thin.', '솔직히 충분하지는 않아요. 개발자 두 명으로는 빠듯해요.', '["Absolutely. Jun and Derek can handle it, no problem at all.","Not quite. Even with three developers, we''re stretched thin.","Not really, and that''s because hiring has been so slow this year."]', '["그럼요. 준이랑 데릭이면 충분히 해내요. 전혀 문제없어요.","충분하지는 않아요. 개발자가 세 명인데도 빠듯해요.","별로요. 그건 올해 채용이 너무 느렸기 때문이에요."]', '["Really? Derek told me last week he''s at capacity.","Three? Who''s the third? I count two.","Let''s not point fingers. What do you need?"]', '["정말요? 데릭은 지난주에 이미 한계라고 하던데요.","세 명이요? 세 번째가 누구예요? 내가 보기엔 두 명인데요.","남 탓은 하지 말죠. 뭐가 필요해요?"]', '["\\"Not quite\\" is a soft no. \\"Stretched thin\\" = too much work for too few people.","Key words: honestly, not quite, stretched thin"]', '["\\"Not quite\\"는 부드러운 부정입니다. stretched thin은 사람에 비해 일이 너무 많다는 뜻입니다.","핵심 단어: honestly, not quite, stretched thin"]', 'maya', 'I was afraid of that. What are you asking for?', '그럴까 봐 걱정했어요. 뭘 요청하려는 거예요?'),
  ('pr_d12_headcount', 3, 'maya', 'Bottom line first. You have practiced this sentence.', '결론부터입니다. 이 문장은 미리 연습해 두었습니다.', 'Go ahead. I''m listening.', '말해 봐요. 듣고 있어요.', 'Lead with your ask: you want to add one developer to the team.', '요청부터 말하세요. 팀에 개발자를 한 명 더 두고 싶습니다.', '[{"any":["make the case","one more developer","another developer","headcount"]}]', 'I''d like to make the case for one more developer on the team.', '팀에 개발자가 한 명 더 필요한 이유를 말씀드리고 싶어요.', '["I''d like to ask for two more developers, starting next week.","So, as you know, the last few weeks have been really busy for us.","We need another developer. Without one, I can''t promise anything."]', '["다음 주부터 개발자 두 명을 더 요청하고 싶어요.","음, 아시다시피 지난 몇 주 동안 저희가 정말 바빴잖아요.","개발자가 한 명 더 있어야 해요. 없으면 아무것도 약속 못 해요."]', '["Two? That''s a big ask in a tight year.","Priya. Bottom line, please.","That sounds like an ultimatum. Try me again."]', '["두 명이요? 빠듯한 해에 그건 큰 요청이에요.","프리야. 결론부터요.","최후통첩처럼 들리네요. 다시 말해 봐요."]', '["\\"Make the case for\\" = explain why something is needed.","Key words: make the case for, one more developer"]', '["make the case for는 그것이 왜 필요한지 근거를 대며 설명한다는 뜻입니다.","핵심 단어: make the case for, one more developer"]', 'maya', 'Headcount is tight this year. Why can''t we do it with the people we have?', '올해는 인원 예산이 빠듯해요. 지금 있는 사람들로는 왜 안 되죠?'),
  ('pr_d12_headcount', 4, 'maya', 'You have the numbers ready: two developers, eight weeks, no room for anything to go wrong.', '숫자는 준비되어 있습니다. 개발자 두 명에 8주, 그리고 무엇 하나 어긋날 여유가 없습니다.', 'Convince me.', '날 설득해 봐요.', 'Make your case with the risk: what happens to the deadline if someone is out.', '위험으로 설득하세요. 누군가 빠지면 마감이 어떻게 되는지요.', '[{"any":["no slack","out for a week","any slack"]}]', 'With two developers, we have no slack. If one of them is out for a week, November first slips.', '개발자 두 명으로는 여유가 전혀 없어요. 한 명이 한 주만 빠져도 11월 1일은 밀려요.', '["We have zero room for error. If either of them is out for even a week, we''d miss December first.","Derek has been working late every night, and honestly, I think he might quit soon.","Everyone''s really busy, and I just think another person would make things much easier."]', '["실수할 여유가 전혀 없어요. 둘 중 한 명이라도 단 한 주만 빠지면 12월 1일을 놓칠 거예요.","데릭이 매일 밤늦게까지 일하고 있어요. 솔직히 곧 그만둘 것 같기도 해요.","다들 정말 바빠요. 그냥 한 사람만 더 있으면 일이 훨씬 수월해질 것 같아요."]', '["December? The deadline''s November first.","That''s a serious thing to say. Has Derek told you that?","\\"Easier\\" won''t get past finance. I need something concrete."]', '["12월이요? 마감은 11월 1일이에요.","그건 가볍게 할 말이 아니에요. 데릭이 그렇게 말했어요?","\\"수월해진다\\"로는 재무팀을 못 넘어요. 구체적인 게 필요해요."]', '["\\"Slack\\" = extra time or people for when things go wrong.","Key words: no slack, out for a week, November first slips"]', '["slack은 일이 틀어질 때를 대비한 여분의 시간이나 사람입니다.","핵심 단어: no slack, out for a week, November first slips"]', 'maya', 'That''s a real risk. What about a contractor? That would be faster.', '그건 실제로 있을 수 있는 위험이네요. 계약직은 어때요? 그쪽이 더 빠를 텐데요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_headcount', 5, 'maya', 'A contractor could start in two weeks. But the work will not end in November.', '계약직은 2주 뒤면 시작할 수 있습니다. 하지만 일은 11월에 끝나지 않습니다.', 'Would that solve it?', '그러면 해결될까요?', 'Accept a contractor for the short term, but argue that the work won''t stop after November.', '당장은 계약직을 받아들이되, 일은 11월 뒤에도 계속된다고 주장하세요.', '[{"any":["bridge the gap","open to","long term"]}]', 'I''m open to a contractor to bridge the gap. But with phase two and the support contract, this is long-term work.', '공백을 메우는 데는 계약직도 좋아요. 하지만 2단계와 지원 계약까지 있으니, 이건 장기적인 일이에요.', '["A contractor would solve it. Let''s go with that, and we can forget about a full-time hire.","No, a contractor won''t work. It has to be full-time, or I don''t think we can do this at all.","I''m open to a contractor to bridge the gap. But with phase two and a three-year support contract, it''s long-term."]', '["계약직이면 해결되겠네요. 그걸로 가죠. 정규직 채용 얘기는 이제 없던 걸로 해요.","아니요, 계약직으로는 안 돼요. 정규직이어야 해요. 아니면 이 일은 못 할 것 같아요.","공백을 메우는 데는 계약직도 좋아요. 하지만 2단계와 3년짜리 지원 계약이 있으니, 이건 장기적인 일이에요."]', '["Are you sure? What happens after November?","That''s a bit rigid. I''m trying to meet you halfway.","Three years? I thought Greg signed for one."]', '["정말요? 11월 다음엔 어떻게 하고요?","좀 융통성이 없네요. 나도 중간에서 맞춰 보려는 건데요.","3년이요? 그렉은 1년으로 서명한 줄 알았는데요."]', '["Accept part of her idea, then say why it is not enough.","Key words: open to, a contractor, bridge the gap, long-term work"]', '["마야의 생각을 일부 받아들인 뒤, 그것만으로는 부족한 이유를 말하세요.","핵심 단어: open to, a contractor, bridge the gap, long-term work"]', 'maya', 'Fair. A contractor now, and one full-time position. I''ll approve it. Talk to Linda about opening the job.', '맞아요. 지금은 계약직, 그리고 정규직 한 자리. 승인할게요. 채용 공고는 린다와 이야기해요.'),
  ('pr_d12_headcount', 6, 'maya', 'One position, approved. You try not to smile too much.', '한 자리가 승인됐습니다. 너무 활짝 웃지 않으려고 애씁니다.', 'Is there anything else?', '다른 건 없어요?', 'Wrap up and thank her. You''ll send Linda the job description this afternoon.', '마무리하며 고맙다고 하세요. 오늘 오후에 린다에게 직무 기술서를 보낼 겁니다.', '[{"any":["job description","linda"]}]', 'That''s all. Thank you, Maya. I''ll get the job description to Linda this afternoon.', '그게 다예요. 고마워요, 마야. 오늘 오후에 린다에게 직무 기술서를 넘길게요.', '["Actually, yes. While we''re here, could we also talk about opening a second position?","Nothing else, thanks. I''ll send the job description to Derek this afternoon.","That''s it. Thanks, Maya. I''ll get to the job description sometime next week."]', '["사실 있어요. 이왕 얘기 나온 김에, 두 번째 자리를 여는 것도 얘기해 볼 수 있을까요?","다른 건 없어요, 고마워요. 오늘 오후에 데릭에게 직무 기술서를 보낼게요.","그게 다예요. 고마워요, 마야. 직무 기술서는 다음 주 중에 쓸게요."]', '["Let''s not push our luck, Priya. One position.","Derek? Linda''s the one who opens the job.","Next week? We just said we''re short on time."]', '["욕심부리지 말죠, 프리야. 한 자리예요.","데릭이요? 채용 공고를 여는 건 린다예요.","다음 주요? 시간이 없다고 방금 얘기했잖아요."]', '["Close, thank her, and say your next step.","Key words: that''s all, the job description, to Linda, this afternoon"]', '["마무리하고, 고맙다고 하고, 다음에 할 일을 말하세요.","핵심 단어: that''s all, the job description, to Linda, this afternoon"]', 'maya', 'Good. And Priya? Take the weekend off. Let me know if you have any questions.', '좋아요. 그리고 프리야, 주말에는 푹 쉬어요. 궁금한 게 있으면 말해 줘요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_hiring', 1, 'linda', 'The HR office. Linda has a blank form open and a pen in her hand.', '인사팀 사무실입니다. 린다가 빈 양식을 띄워 놓고 펜을 들고 있습니다.', 'Hi, Priya! Maya told me you''d stop by. A new position, how exciting! Is it a new role or a backfill?', '안녕하세요, 프리야! 마야가 들를 거라고 했어요. 새 자리라니, 신나네요! 새로 생기는 자리예요, 아니면 결원 충원이에요?', 'Answer her question, and say what the job is and which project it''s for.', '질문에 답하고, 어떤 자리이며 어느 프로젝트를 위한 것인지 말하세요.', '[{"any":["new role","full time developer"]}]', 'It''s a new role: a full-time developer for the Summit Retail project.', '새로 생기는 자리예요. 서밋 리테일 프로젝트를 맡을 정규직 개발자요.', '["It''s a backfill. We''re replacing a developer who left last month.","It''s a new role: a part-time contractor for the Summit Retail project.","It''s for Summit Retail. Maya''s really excited about it, too."]', '["결원 충원이에요. 지난달에 나간 개발자 자리를 채우는 거예요.","새로 생기는 자리예요. 서밋 리테일 프로젝트를 맡을 시간제 계약직이요.","서밋 리테일 때문이에요. 마야도 정말 기대하고 있어요."]', '["Oh? I don''t have anyone leaving on my list. Who was it?","Part-time? Maya''s note says one full-time position.","Great! But is it a new role, or are we replacing someone?"]', '["어? 제 명단엔 퇴사자가 없는데요. 누구였어요?","시간제요? 마야 메모에는 정규직 한 자리라고 되어 있어요.","좋네요! 그런데 새 자리예요, 아니면 누굴 대신하는 거예요?"]', '["A \\"backfill\\" replaces someone who left. This job did not exist before.","Key words: a new role, a full-time developer"]', '["backfill은 나간 사람의 자리를 채우는 것입니다. 이번 자리는 전에 없던 자리입니다.","핵심 단어: a new role, a full-time developer"]', 'linda', 'Wonderful. Then we need a job requisition. We call it a req.', '잘됐네요. 그러면 채용 요청서가 필요해요. 줄여서 req라고 불러요.'),
  ('pr_d12_hiring', 2, 'linda', 'Linda moves to the second line of the form.', '린다가 양식의 둘째 줄로 넘어갑니다.', 'Who''s the hiring manager? That''s the person the new hire reports to.', '채용 책임자는 누구예요? 새 직원이 보고하게 될 사람이요.', 'Tell her the new hire will report to Maya, and who will do the interviews: you and Derek.', '새 직원은 마야에게 보고하게 된다고 하고, 면접은 당신과 데릭이 본다고 말하세요.', '[{"any":["hiring manager","interview panel"]}]', 'Maya is the hiring manager. I''ll be on the interview panel, along with Derek.', '채용 책임자는 마야예요. 저는 데릭과 함께 면접관으로 들어갈게요.', '["I''m the hiring manager. Maya and Derek will be on the interview panel.","Maya is the hiring manager. I''ll be on the panel, along with Jun.","Derek, I think. He''s the one who''d be working with the new hire every single day."]', '["채용 책임자는 저예요. 마야와 데릭이 면접관으로 들어갈 거예요.","채용 책임자는 마야예요. 저는 준과 함께 면접관으로 들어갈게요.","데릭일 것 같아요. 새 직원이랑 매일매일 같이 일할 사람이 데릭이니까요."]', '["Hmm, Maya''s note says the role reports to her.","Jun, okay. Wait, isn''t he pretty new himself?","Not quite. I mean who they report to, not who they sit next to."]', '["음, 마야 메모에는 이 자리가 마야한테 보고한다고 되어 있는데요.","준이요, 알겠어요. 잠깐, 준도 꽤 신입 아니에요?","그게 아니라요. 옆자리에 앉을 사람 말고, 보고받을 사람이요."]', '["Answer her question, then say what your own part is.","Key words: the hiring manager, on the interview panel, along with Derek"]', '["질문에 답한 뒤, 당신이 맡을 역할을 말하세요.","핵심 단어: the hiring manager, on the interview panel, along with Derek"]', 'linda', 'Maya, you and Derek. Got it.', '마야, 프리야, 데릭. 알겠어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_hiring', 3, 'linda', 'You have a number in your head, but it is only a guess.', '머릿속에 숫자가 하나 있지만, 짐작일 뿐입니다.', 'Do you have a salary range in mind? We have to list it in the posting.', '생각해 둔 연봉 범위가 있어요? 공고에 적어야 하거든요.', 'You don''t want to make up a number. Ask her what''s been approved for a mid-level role.', '숫자를 지어내고 싶지 않습니다. 중간급 자리에 승인된 범위를 물어보세요.', '[{"any":["approved range","pay band","rather not guess"]}]', 'I''d rather not guess. What''s the approved range for a mid-level developer?', '짐작으로 말하고 싶진 않아요. 중간급 개발자에게 승인된 범위가 어떻게 돼요?', '["I was thinking around one twenty to one forty, so we can attract the best people.","Whatever Derek makes would be a good starting point, I think.","Does it have to go in the posting? I''d rather keep it private."]', '["12만에서 14만 정도를 생각했어요. 그래야 제일 좋은 사람들을 데려올 수 있으니까요.","데릭이 받는 연봉 정도면 괜찮은 출발점이 될 것 같아요.","꼭 공고에 넣어야 해요? 그건 공개 안 했으면 좋겠는데요."]', '["That''s above the approved band. Let me check what we actually have.","I can''t share anyone''s salary, Priya. Let''s use the approved band.","It does, I''m afraid. We list a range on every posting."]', '["그건 승인된 범위보다 높아요. 실제로 얼마가 있는지 확인해 볼게요.","다른 사람 연봉은 알려 줄 수 없어요, 프리야. 승인된 범위로 가죠.","안타깝지만 넣어야 해요. 모든 공고에 범위를 적거든요."]', '["\\"I''d rather not …\\" is a polite way to decline. Then ask the expert.","Key words: I''d rather not guess, the approved range, mid-level developer"]', '["\\"I''d rather not …\\"은 정중히 사양하는 말입니다. 그리고 전문가에게 물어보세요.","핵심 단어: I''d rather not guess, the approved range, mid-level developer"]', 'linda', 'For that level, it''s ninety-five to one hundred fifteen thousand a year, plus benefits.', '그 직급이면 연 9만 5천에서 11만 5천 달러이고, 복리후생은 별도예요.'),
  ('pr_d12_hiring', 4, 'linda', 'Phase one is due on November first.', '1단계의 기한은 11월 1일입니다.', 'And how soon do you need someone?', '그리고 사람은 얼마나 빨리 필요해요?', 'Give her your timeline, six weeks if possible, and ask how long hiring normally takes.', '가능하면 6주라는 일정을 말하고, 채용이 보통 얼마나 걸리는지 물어보세요.', '[{"any":["ideally","how long","six weeks"]}]', 'Ideally within six weeks. How long does the process usually take?', '가능하면 6주 안이면 좋겠어요. 보통 절차가 얼마나 걸려요?', '["As soon as possible. Could we have someone start next Monday?","Sometime in the spring is fine. There''s no real rush on this one.","Six weeks. And can the job be fully remote, or is it on-site?"]', '["최대한 빨리요. 다음 주 월요일부터 출근할 수 있을까요?","봄쯤이면 괜찮아요. 이건 딱히 급하지 않아요.","6주요. 그리고 완전 재택도 되나요, 아니면 출근해야 해요?"]', '["Monday? We haven''t even posted the job yet!","Spring? I thought Maya said this was urgent.","We can get to that. First, let''s see if six weeks is even doable."]', '["월요일이요? 아직 공고도 안 올렸는데요!","봄이요? 마야는 급하다고 한 것 같은데요.","그건 차차 얘기해요. 먼저 6주가 되긴 하는지부터 보죠."]', '["\\"Ideally\\" gives your wish without making it a demand.","Key words: ideally, within six weeks, how long, the process"]', '["ideally는 요구가 아니라 바람으로 말하게 해 줍니다.","핵심 단어: ideally, within six weeks, how long, the process"]', 'linda', 'From posting to offer, about five weeks if we move quickly. Referrals are faster, and there''s a referral bonus.', '공고부터 입사 제안까지, 서두르면 5주쯤 걸려요. 추천은 더 빠르고, 추천 보너스도 있어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_hiring', 5, 'linda', 'Your draft of the job description is almost done.', '직무 기술서 초안은 거의 다 써 두었습니다.', 'I''ll need the job description before I can post it. When can you get it to me?', '공고를 올리려면 직무 기술서가 있어야 해요. 언제쯤 줄 수 있어요?', 'Promise her a draft by 4 p.m., and invite her to make any changes she wants.', '오후 네 시까지 초안을 주겠다고 하고, 얼마든지 고쳐도 된다고 하세요.', '[{"any":["draft","mark it up"]}]', 'You''ll have a draft by four o''clock. Feel free to mark it up.', '네 시까지 초안 보내 드릴게요. 얼마든지 마음껏 고쳐 주세요.', '["You''ll have a draft by Monday. Feel free to mark it up.","By four. Just please don''t change it, it''s already final.","Could you write it yourself? You''ve done a lot more of these."]', '["월요일까지 초안 보내 드릴게요. 얼마든지 마음껏 고쳐 주세요.","네 시까지요. 근데 고치진 말아 주세요. 이미 최종본이에요.","직접 써 줄 수 있어요? 이런 건 린다가 훨씬 많이 써 봤잖아요."]', '["Monday? Then it won''t go up until midweek.","Oh. Well, I usually have to edit for legal wording.","I can help, but I don''t know the role like you do."]', '["월요일이요? 그럼 공고는 주중에나 올라가겠네요.","아. 그런데 보통은 제가 법적 표현을 손봐야 하거든요.","도와줄 순 있지만, 그 일은 프리야만큼 잘 몰라요."]', '["Give the time, then invite her changes.","Key words: a draft by four o''clock, feel free to, mark it up"]', '["시간을 말하고, 고쳐도 좋다고 말하세요.","핵심 단어: a draft by four o''clock, feel free to, mark it up"]', 'linda', 'I will. We''ll have it posted by Monday morning. And congratulations on the contract!', '그럴게요. 월요일 아침까지 공고를 올릴게요. 그리고 계약 축하해요!'),
  ('pr_d12_signed', 1, 'jun', 'Friday morning, partly sunny. Maya signed from her office a few minutes ago. Your phone rings.', '구름 사이로 해가 나는 금요일 아침입니다. 몇 분 전에 마야가 사무실에서 서명했습니다. 휴대전화가 울립니다.', 'Priya! It''s signed. Greg signed right after Maya. It''s official!', '프리야! 서명했어요. 마야 다음에 그렉이 바로 서명했어요. 공식적으로 끝났어요!', 'Celebrate with him, and make it clear this win is his.', '함께 기뻐하고, 이번 성과는 준의 것이라고 분명히 말해 주세요.', '[{"any":["congratulations","congrats","pulled it off"]}]', 'That''s fantastic news! Congratulations, Jun. You pulled it off.', '정말 멋진 소식이에요! 축하해요, 준. 해냈네요.', '["That''s great news! I knew my prep notes would get us over the line.","Good. Send me the signed copy and your notes by end of day.","Fantastic news! So Maya still has to sign it this afternoon?"]', '["좋은 소식이네요! 내 준비 메모가 결국 통할 줄 알았어요.","좋아요. 서명본이랑 메모는 오늘 퇴근 전까지 보내 줘요.","멋진 소식이에요! 그럼 마야는 오늘 오후에 서명하면 되는 거죠?"]', '["Uh, yeah. Your notes helped a lot.","Oh. Sure, I''ll send it over.","No, she signed first. It''s done, Priya!"]', '["어, 네. 메모가 많이 도움이 됐어요.","아. 네, 보내 드릴게요.","아니요, 마야가 먼저 했어요. 다 끝났다니까요, 프리야!"]', '["\\"Pull it off\\" = succeed at something difficult.","Key words: fantastic news, congratulations, you pulled it off"]', '["pull it off는 어려운 일을 해낸다는 뜻입니다.","핵심 단어: fantastic news, congratulations, you pulled it off"]', 'jun', 'I can''t believe it. My hands are still shaking. I almost froze when he asked about the cancellation clause.', '믿기지 않아요. 아직도 손이 떨려요. 해지 조항을 물었을 때는 얼어붙을 뻔했어요.'),
  ('pr_d12_signed', 2, 'jun', '"Almost" is the important word.', '중요한 말은 "뻔했다"입니다.', 'For a second, my mind went blank.', '잠깐 머릿속이 하얘졌어요.', 'Point out that he got through it anyway, and ask what he did.', '그래도 결국 버텨 냈다는 걸 짚어 주고, 어떻게 했는지 물어보세요.', '[{"any":["handle it","handled it","what did you say"]}]', 'But you didn''t freeze. How did you handle it?', '그래도 얼어붙지 않았잖아요. 어떻게 넘겼어요?', '["Was it the uptime question? What did you say?","You can''t freeze up in front of a client, Jun.","That happens. Anyway, when''s your flight home?"]', '["가동률 질문 때문이었어요? 뭐라고 했어요?","고객 앞에서 얼어붙으면 안 돼요, 준.","그럴 수 있죠. 그건 그렇고, 돌아오는 비행기는 언제예요?"]', '["No, the cancellation clause. Uptime was easy.","I know. That''s why I said \\"almost.\\"","Oh. At three. But don''t you want to hear how it went?"]', '["아니요, 해지 조항이요. 가동률은 쉬웠어요.","알아요. 그래서 \\"뻔했다\\"고 한 거예요.","아. 세 시요. 그런데 어떻게 됐는지 안 궁금해요?"]', '["Let him tell the story. \\"How did you handle it?\\"","Key words: you didn''t freeze, how did you handle it"]', '["준이 직접 이야기하게 하세요. \\"How did you handle it?\\"","핵심 단어: you didn''t freeze, how did you handle it"]', 'jun', 'I said seven days was too short for us and asked for thirty. He said, "That''s fair."', '7일은 우리에게 너무 짧다고 하고 30일을 요청했어요. 그랬더니 "타당하네요"라고 하더라고요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_signed', 3, 'jun', 'He is giving the credit away. You give it back.', '준이 공을 남에게 돌리고 있습니다. 당신은 그 공을 돌려줍니다.', 'I just did what you told me.', '저는 그냥 프리야가 시킨 대로 했을 뿐이에요.', 'He''s giving you the credit. Don''t take it; hand it back to him.', '준이 공을 당신에게 돌리고 있습니다. 받지 말고 준에게 돌려주세요.', '[{"any":["give yourself","credit","in the room"]}]', 'No, you were the one in the room. Give yourself some credit.', '아니에요, 그 자리에 있던 건 준이었잖아요. 자기 공도 좀 인정해요.', '["Well, it was good advice. Glad I could get you ready for it.","Don''t thank me. Maya''s the one who made this deal happen.","Still, you asked for sixty days on your own. That was smart."]', '["뭐, 좋은 조언이긴 했죠. 준비시켜 줄 수 있어서 다행이에요.","나한테 고마워하지 마요. 이 계약을 성사시킨 건 마야예요.","그래도 60일은 준이 알아서 요청했잖아요. 그건 똑똑했어요."]', '["Yeah. Thanks for that.","Maya did a lot, sure. But I was the one sweating in there.","Thirty, actually. I stuck to the plan."]', '["네. 그건 고마워요.","마야가 많이 하긴 했죠. 그래도 거기서 진땀 뺀 건 저예요.","사실 30일이었어요. 계획대로 했어요."]', '["Praise works best when it says what the person did.","Key words: you were the one in the room, give yourself some credit"]', '["칭찬은 그 사람이 무엇을 했는지 짚어 줄 때 가장 힘이 있습니다.","핵심 단어: you were the one in the room, give yourself some credit"]', 'jun', 'Okay. Maybe a little. Oh, and Greg asked who to call day to day. I said you''re his main point of contact.', '네. 조금은요. 아, 그리고 그렉이 평소에 누구에게 연락하면 되는지 물어서, 프리야가 주 담당자라고 했어요.'),
  ('pr_d12_signed', 4, 'jun', 'Signed is not finished. The real work starts now.', '서명했다고 끝난 것이 아닙니다. 진짜 일은 이제 시작입니다.', 'I also told him about the kickoff next week and the status update every Friday. Was that okay?', '다음 주 킥오프랑 매주 금요일 현황 보고 얘기도 했어요. 괜찮았죠?', 'Confirm he handled it well, and say you''ll arrange next week''s kickoff with both teams.', '잘 처리했다고 확인해 주고, 다음 주에 양쪽 팀이 함께하는 킥오프를 잡겠다고 하세요.', '[{"any":["set up","both teams","exactly right"]}]', 'That''s exactly right. I''ll set up the kickoff with both teams for next week.', '딱 맞게 했어요. 다음 주에 양쪽 팀이 다 모이는 킥오프는 내가 잡을게요.', '["That''s exactly right. I''ll set up the kickoff for the week after next.","You should have checked with me first. I''ll decide when the kickoff happens.","Every Friday? Let''s make it monthly. Weekly is too much for our team."]', '["딱 맞게 했어요. 양쪽 팀 킥오프는 다다음 주로 잡을게요.","먼저 나한테 확인했어야죠. 킥오프를 언제 할지는 내가 정해요.","매주 금요일이요? 월 1회로 하죠. 매주는 우리 팀한테 너무 많아요."]', '["The week after? I told Greg next week.","Oh. Sorry. I thought that was the plan.","But we promised weekly updates. Greg was really happy about that."]', '["다다음 주요? 그렉한테는 다음 주라고 했는데요.","아. 죄송해요. 그게 계획인 줄 알았어요.","그래도 매주 보고하기로 약속했잖아요. 그렉이 그걸 정말 좋아했어요."]', '["Confirm his promise, then say what you will do next.","Key words: exactly right, set up the kickoff, both teams, next week"]', '["준의 약속이 옳았다고 확인해 주고, 당신이 다음에 할 일을 말하세요.","핵심 단어: exactly right, set up the kickoff, both teams, next week"]', 'jun', 'Great. My flight''s at three. Should I come into the office tonight?', '좋아요. 비행기는 세 시예요. 오늘 저녁에 사무실에 들를까요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d12_signed', 5, 'jun', 'He has been up since five two days in a row.', '준은 이틀 연속 새벽 다섯 시에 일어났습니다.', 'I could write up the trip report.', '출장 보고서를 써 둘 수도 있어요.', 'He''s exhausted. Turn down his offer firmly, send him home, and plan to celebrate after the weekend.', '준은 지쳐 있습니다. 단호하게 거절하고 집으로 보내세요. 축하는 주말이 지나고 하자고 하세요.', '[{"any":["get some rest","straight home","celebrate"]}]', 'Absolutely not. Go straight home and get some rest. We''ll celebrate on Monday.', '절대 안 돼요. 곧장 집에 가서 쉬어요. 축하는 월요일에 해요.', '["Sure, if you''re up for it. Just send it to me before you leave tonight.","Absolutely not. Go home and rest, and we''ll celebrate tomorrow at the office.","Skip the report. Come in tonight, though, so we can plan the kickoff together."]', '["그래요, 할 수 있겠으면요. 오늘 밤 퇴근 전에만 보내 줘요.","절대 안 돼요. 집에 가서 쉬고, 축하는 내일 사무실에서 해요.","보고서는 됐어요. 대신 오늘 저녁에 들러요. 킥오프 계획을 같이 짜게요."]', '["Okay... I''ll try. I''m pretty tired, though.","Tomorrow''s Saturday, Priya. You''re working the weekend?","Tonight? I''ve been up since five two days in a row."]', '["네… 해 볼게요. 좀 피곤하긴 하지만요.","내일은 토요일이에요, 프리야. 주말에도 일해요?","오늘 저녁이요? 이틀 연속 새벽 다섯 시에 일어났는데요."]', '["A kind order: \\"Go straight home.\\" Then something to look forward to.","Key words: absolutely not, go straight home, get some rest, celebrate on Monday"]', '["다정한 명령입니다. \\"Go straight home.\\" 그리고 기대할 일을 하나 말해 주세요.","핵심 단어: absolutely not, go straight home, get some rest, celebrate on Monday"]', 'jun', 'Deal. Have a great weekend, Priya!', '좋아요. 주말 잘 보내세요, 프리야!'),
  ('pr_d2_design', 1, 'derek', 'After the design review with Jun, Derek waves you over to his desk.', '준과 디자인 리뷰를 마친 뒤, 데릭이 자기 자리로 오라고 손짓합니다.', 'So, I looked at the new checkout mockups. They look great, but honestly, I have some concerns.', '그래서, 새 결제 목업 봤어요. 멋지긴 한데, 솔직히 걱정되는 게 좀 있어요.', 'You want to hear him out. Invite him to explain.', '그의 이야기를 들어 보고 싶습니다. 설명해 달라고 하세요.', '[{"any":["concerns","all ears","worried","worries"]}]', 'I''m all ears. What are your concerns?', '잘 들을게요. 뭐가 걱정이에요?', '["Really? The client already loves them.","Thanks! So you''re good to start building?","Concerns? It''s a bit late for that, Derek."]', '["그래요? 고객은 벌써 좋아하는데요.","고마워요! 그럼 바로 개발 시작해도 되죠?","걱정이요? 이제 와서요, 데릭?"]', '["Maybe, but they haven''t seen the cost yet.","Not quite. I said I have concerns.","Wow. Okay. I''m just trying to help here."]', '["그렇겠죠. 근데 비용은 아직 안 봤잖아요.","그건 아니고요. 걱정되는 게 있다니까요.","와. 그래요. 난 그냥 도우려는 건데."]', '["\\"I''m all ears\\" = I am listening carefully.","Key words: all ears, concerns"]', '["\\"I''m all ears\\"는 귀 기울여 듣겠다는 뜻입니다.","핵심 단어: all ears, concerns"]', 'derek', 'Okay. It''s the one-page layout.', '좋아요. 문제는 한 페이지짜리 레이아웃이에요.'),
  ('pr_d2_design', 2, 'derek', 'He turns his monitor toward you.', '데릭이 모니터를 당신 쪽으로 돌립니다.', 'Putting everything on one page means rewriting the address form. That''s two weeks, easy.', '전부 한 페이지에 넣으려면 주소 입력 양식을 다시 짜야 해요. 넉넉히 2주예요.', 'Two weeks is too long. Look for a lighter option that''s almost as good.', '2주는 너무 깁니다. 거의 비슷한 효과를 내는 더 가벼운 방법을 찾아보세요.', '[{"any":["simpler","easier","smaller version","lighter","most of the way"]}]', 'Is there a simpler version that gets us most of the way there?', '대부분의 효과는 내면서 더 단순한 버전은 없을까요?', '["Two weeks? Can''t you just work faster and get it done in one?","Two weeks is fine. Let''s go ahead with the full rewrite, then.","Why didn''t anyone flag this before the design got approved?"]', '["2주요? 그냥 더 빨리 해서 1주 만에 끝내면 안 돼요?","2주면 괜찮아요. 그럼 전부 다시 짜는 걸로 가죠.","디자인 승인 나기 전에 왜 아무도 이 얘길 안 했어요?"]', '["That''s not how it works, Priya. Faster means buggier.","Really? The demo''s Monday, though.","I''m flagging it now. That''s what reviews are for."]', '["그렇게 되는 게 아니에요, 프리야. 서두르면 버그만 늘어요.","정말요? 데모가 월요일인데요.","지금 말하잖아요. 리뷰가 그러라고 있는 거죠."]', '["Do not say no. Ask for a smaller option.","Key words: a simpler version, most of the way there"]', '["안 된다고 하지 말고, 더 작은 선택지를 물어보세요.","핵심 단어: a simpler version, most of the way there"]', 'derek', 'We could keep the old form and tuck it into a section that opens and closes. Three days, maybe.', '기존 양식을 그대로 두고 접었다 펴는 영역에 넣을 수 있어요. 사흘쯤 걸릴 거예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d2_design', 3, 'derek', 'Two weeks against three days. You like the sound of that.', '2주 대 사흘. 듣기에 좋습니다.', 'It''s not perfect, though.', '근데 완벽하진 않아요.', 'The idea sounds good, but find out what you''d be giving up.', '좋은 생각 같지만, 대신 무엇을 포기하게 되는지 알아보세요.', '[{"any":["trade off","tradeoff","downside","catch"]}]', 'I like that. What''s the trade-off?', '좋네요. 대신 잃는 건 뭐예요?', '["Perfect. So it''s just as good?","I like that. So, about two weeks?","Fine. Just do whatever''s fastest, then."]', '["완벽하네요. 그럼 똑같이 좋은 거죠?","좋네요. 그럼 2주쯤이요?","좋아요. 그냥 제일 빠른 걸로 해요."]', '["Not exactly. That''s what I''m saying.","No, three days. That''s the whole point.","Sure, but you should know what we''d lose."]', '["꼭 그렇진 않아요. 그 얘기를 하는 거예요.","아뇨, 사흘이요. 그게 핵심이에요.","그래요, 근데 뭘 잃는지는 알아야죠."]', '["Every shortcut costs something. Ask what.","Key words: I like that, trade-off"]', '["지름길에는 대가가 있습니다. 그것이 무엇인지 물어보세요.","핵심 단어: I like that, trade-off"]', 'derek', 'It won''t look as slick on mobile. Users have to tap one more time.', '모바일에서는 덜 매끈해 보일 거예요. 사용자가 한 번 더 눌러야 하고요.'),
  ('pr_d2_design', 4, 'derek', 'One more tap. The client demo is on Monday.', '한 번 더 누르기. 고객 데모는 월요일입니다.', 'Can you live with that?', '그 정도는 괜찮겠어요?', 'One extra tap is acceptable for now. Make the call.', '탭 한 번 더는 지금은 감수할 만합니다. 결정하세요.', '[{"any":["live with","go with","simpler version"]}]', 'I can live with that. Let''s go with the simpler version for now.', '그 정도는 괜찮아요. 일단 단순한 버전으로 가죠.', '["Not really. Let''s do the full one-page version after all.","Sure. Let''s go simple, as long as it''s ready for Friday''s client demo.","I don''t know. Let''s ask Maya and see what she thinks first."]', '["별로요. 결국 한 페이지짜리 전체 버전으로 가죠.","좋아요. 단순하게 가요, 금요일 고객 데모까지만 되면요.","모르겠어요. 마야한테 먼저 물어보고 생각을 들어 보죠."]', '["The full version? Two weeks? We''d miss the demo.","Friday? I thought the demo was Monday.","We could, but this is your call, Priya."]', '["전체 버전이요? 2주요? 데모를 놓쳐요.","금요일이요? 데모는 월요일인 줄 알았는데.","그래도 되지만, 이건 프리야가 정할 일이에요."]', '["Accept the downside, then decide: \\"Let''s go with …\\".","Key words: I can live with that, let''s go with"]', '["단점을 받아들이고 결정하세요. \\"Let''s go with …\\".","핵심 단어: I can live with that, let''s go with"]', 'derek', 'Cool. Good call.', '좋아요. 잘 정했어요.'),
  ('pr_d2_design', 5, 'derek', 'Derek opens the design doc.', '데릭이 디자인 문서를 엽니다.', 'Want me to write that up?', '제가 정리해 둘까요?', 'Accept, and make sure the decision gets recorded where the whole team can see it.', '그러자고 하고, 팀 전체가 볼 수 있는 곳에 결정을 기록해 달라고 하세요.', '[{"any":["design doc","same page","document","doc"]}]', 'Yes, please. Could you add it to the design doc so we''re all on the same page?', '네, 부탁해요. 다들 같은 내용을 알 수 있게 디자인 문서에 넣어 줄래요?', '["No need. We''ll both remember it. Let''s just get started on it.","Yes, please. Could you just send it to me in a private message?","Yes. And write it all up properly, so nobody can blame me if the client hates it."]', '["괜찮아요. 우리 둘 다 기억하잖아요. 그냥 바로 시작하죠.","네, 부탁해요. 그냥 저한테 개인 메시지로 보내 줄래요?","네. 고객이 싫어해도 제 탓 안 되게 꼭 적어 둬요."]', '["You sure? Jun and the client will ask why it changed.","Just you? The rest of the team should see it too.","Ha. Nobody''s blaming anyone. But sure."]', '["정말요? 준이랑 고객이 왜 바뀌었는지 물어볼 텐데요.","프리야한테만요? 팀 다른 사람들도 봐야죠.","하. 아무도 누구 탓 안 해요. 그래도 알겠어요."]', '["A decision that is not written down gets forgotten.","Key words: add it to the design doc, on the same page"]', '["적어 두지 않은 결정은 잊힙니다.","핵심 단어: add it to the design doc, on the same page"]', 'derek', 'Will do. It''ll be in there by end of day.', '그럴게요. 오늘 퇴근 전까지 넣어 둘게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d2_find_time', 1, 'jun', 'After standup you stop by Jun''s desk. He is reading the team wiki.', '스탠드업이 끝나고 준의 자리에 들릅니다. 준은 팀 위키를 읽고 있습니다.', 'Oh, hi, Priya! Did you need something?', '어, 안녕하세요, 프리야! 뭐 필요한 거 있으세요?', 'Ask if he''s free to look at the checkout designs together. You were thinking one o''clock.', '결제 화면 디자인을 같이 볼 시간이 있는지 물어보세요. 한 시쯤을 생각하고 있습니다.', '[{"any":["does one","at one","one oclock","one work"]},{"all":["checkout"],"any":["go over","walk through","review","look at"]}]', 'Do you have a sec? I want to go over the checkout designs with you. Does one o''clock work?', '잠깐 시간 돼요? 결제 화면 디자인을 같이 보고 싶어서요. 한 시 괜찮아요?', '["Hey, got a minute? I''d like to walk you through the checkout designs. Is three o''clock okay?","I need you in the small room at one for the checkout designs. Clear your calendar.","Do you have a sec? I want to go over the payment module rewrite. Is right now good?"]', '["잠깐 시간 있어요? 결제 화면 디자인을 같이 보고 싶어서요. 세 시 괜찮아요?","한 시에 결제 디자인 보게 작은 방으로 와요. 일정 비워 두고요.","잠깐 시간 돼요? 결제 모듈 재작성 얘기를 하고 싶어서요. 지금 괜찮아요?"]', '["Three should work. Weren''t you thinking earlier, though?","Oh, um… I have IT at one. Is that okay?","The payment module? I thought Derek was taking that offline."]', '["세 시면 될 것 같아요. 근데 더 일찍 하려던 거 아니었어요?","아, 음… 한 시에 IT 예약이 있는데. 괜찮을까요?","결제 모듈이요? 그건 데릭이랑 따로 얘기하기로 한 줄 알았는데요."]', '["Three steps: \\"Do you have a sec?\\", the topic, then the time.","Key words: go over, checkout designs, does one o''clock work"]', '["세 단계입니다. \\"Do you have a sec?\\", 주제, 그리고 시간.","핵심 단어: go over, checkout designs, does one o''clock work"]', 'jun', 'Sorry, I have an appointment with IT at one.', '죄송해요, 한 시에 IT 예약이 있어요.'),
  ('pr_d2_find_time', 2, 'jun', 'Jun checks his calendar.', '준이 달력을 확인합니다.', 'Could we move it to two o''clock instead?', '대신 두 시로 옮길 수 있을까요?', 'Accept his time, and say you''ll put it on his calendar.', '그가 말한 시간을 받아들이고, 일정에 넣어 주겠다고 하세요.', '[{"any":["works","invite","fine"]}]', 'Two works for me. I''ll send you a calendar invite.', '두 시 좋아요. 캘린더 초대 보낼게요.', '["Three works for me. I''ll send you a calendar invite.","Two works. Could you send me the calendar invite?","Fine, two. But please don''t make me reschedule again."]', '["세 시 좋아요. 캘린더 초대 보낼게요.","두 시 좋아요. 캘린더 초대 좀 보내 줄래요?","알았어요, 두 시. 근데 또 시간 옮기게 하진 마요."]', '["Three? I said two, I think.","Oh, sure. How do I do that in this calendar?","Oh. Sorry. I''ll be there."]', '["세 시요? 저 두 시라고 한 것 같은데요.","아, 네. 근데 이 캘린더에서 그거 어떻게 해요?","아. 죄송해요. 꼭 갈게요."]', '["Accept the time, then promise the invite.","Key words: works for me, calendar invite"]', '["시간을 받아들이고 초대장을 약속하세요.","핵심 단어: works for me, calendar invite"]', 'jun', 'Great, thank you!', '좋아요, 고맙습니다!'),
  ('pr_d2_find_time', 3, 'jun', 'He opens a new block on his calendar.', '준이 달력에 새 일정을 만듭니다.', 'How long will it take? I want to block out the time.', '얼마나 걸려요? 시간을 비워 두려고요.', 'Half an hour is plenty. Also tell him where you''ll meet: the small room next to the kitchen.', '30분이면 충분합니다. 어디서 볼지도 말하세요. 탕비실 옆 작은 방입니다.', '[{"any":["thirty","30","half an hour"]}]', 'Thirty minutes should do it. I''ll book the small room by the kitchen.', '30분이면 될 거예요. 탕비실 옆 작은 방을 잡아 둘게요.', '["About two hours, I''d say. I''ll book the large meeting room.","As long as it takes. Just keep your whole afternoon open.","Thirty minutes should do it. Could you book a room for the two of us, then?"]', '["두 시간쯤 걸릴 거예요. 큰 회의실을 잡아 둘게요.","걸리는 만큼이요. 오후는 통째로 비워 둬요.","30분이면 될 거예요. 방은 준이 잡아 줄래요?"]', '["Two hours? Wow, okay. I''ll clear the afternoon.","Oh… the whole afternoon? I''ll try.","Sure, um… how do I book a room here?"]', '["두 시간이요? 와, 알겠어요. 오후를 비워 둘게요.","아… 오후 내내요? 해 볼게요.","네, 음… 여기선 방을 어떻게 잡아요?"]', '["Give the length: \\"… should do it\\" means it is enough.","Key words: thirty minutes, should do it"]', '["길이를 말하세요. \\"… should do it\\"은 그 정도면 충분하다는 뜻입니다.","핵심 단어: thirty minutes, should do it"]', 'jun', 'Thirty minutes. Got it.', '30분. 알겠습니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d2_find_time', 4, 'jun', 'Jun picks up his notebook.', '준이 공책을 집어 듭니다.', 'Should I prepare anything?', '뭐 준비해야 할 거 있어요?', 'There''s nothing to prepare, but a quick look at the screens first would help.', '준비할 건 없지만, 화면 시안을 미리 한번 보면 도움이 됩니다.', '[{"any":["mockups","mockup","no prep","take a look","beforehand"]}]', 'No prep needed. Just take a look at the mockups beforehand if you have time.', '준비할 건 없어요. 시간 되면 목업만 미리 한번 봐 둬요.', '["Yes, please read the whole design doc and write up your feedback first.","No prep needed. Just bring your laptop, and we''ll look at the code together.","Not really. Honestly, I mostly just need you there to listen."]', '["네, 디자인 문서 전체를 읽고 피드백을 먼저 써 와요.","준비할 건 없어요. 노트북만 가져와요, 코드를 같이 볼 거니까요.","딱히요. 솔직히 그냥 와서 듣기만 하면 돼요."]', '["The whole doc? Okay… by two?","The code? I thought we were looking at designs.","Oh. Okay. I''ll just listen, then."]', '["문서 전체요? 네… 두 시까지요?","코드요? 디자인을 보는 줄 알았는데요.","아. 네. 그럼 듣기만 할게요."]', '["\\"No prep needed\\" + one small thing he could do before.","Key words: no prep needed, mockups, beforehand"]', '["\\"No prep needed\\"라고 하고, 미리 할 수 있는 작은 일 하나를 말하세요.","핵심 단어: no prep needed, mockups, beforehand"]', 'jun', 'Will do. I''ll look at them before lunch.', '그럴게요. 점심 전에 볼게요.'),
  ('pr_d2_find_time', 5, 'jun', 'He hesitates for a second.', '준이 잠깐 머뭇거립니다.', 'And, um, what if IT runs long?', '그리고, 음, IT가 길어지면 어떡하죠?', 'Reassure him. If IT takes longer, he only needs to let you know and you''ll move it later.', '안심시키세요. IT가 길어지면 알려 주기만 하면 시간을 뒤로 옮기겠다고요.', '[{"any":["message","ping","let me know","push it","text"]}]', 'No worries. Just shoot me a message and we''ll push it back.', '걱정 마요. 메시지만 보내 주면 시간 뒤로 미룰게요.', '["Then you''ll just have to leave IT a little early, I guess.","No worries. If you''re running late, I''ll just start without you.","That''s fine, we''ll just cancel it then. No big deal."]', '["그럼 IT에서 좀 일찍 나와야겠네요.","걱정 마요. 늦으면 그냥 준 없이 시작할게요.","괜찮아요, 그럼 그냥 취소하죠. 별일 아니에요."]', '["Leave early? But they''re setting up my laptop.","Oh. Okay. I''ll try not to be late.","Cancel it? But don''t we need it for the demo?"]', '["일찍 나오라고요? 노트북 세팅 중일 텐데요.","아. 네. 안 늦도록 해 볼게요.","취소요? 데모 때문에 필요한 거 아니에요?"]', '["Tell him how to reach you and what you will do.","Key words: shoot me a message, push it back"]', '["어떻게 연락하면 되는지, 그러면 어떻게 할지 말하세요.","핵심 단어: shoot me a message, push it back"]', 'jun', 'Thanks, Priya. I''ll keep you posted.', '고마워요, 프리야. 계속 알려 드릴게요.'),
  ('pr_d3_one_on_one', 1, 'maya', 'Rain taps on the window of Maya''s office. You shake out your umbrella at the door.', '마야의 사무실 창문에 빗방울이 떨어집니다. 당신은 문 앞에서 우산을 텁니다.', 'Come on in. Is it still raining out there?', '들어와요. 밖에 아직 비 와요?', 'Answer her about the weather this morning.', '오늘 아침 날씨에 대해 대답하세요.', '[{"any":["umbrella","on and off","raining","pouring"]}]', 'It''s been on and off all morning. Good thing I brought an umbrella.', '아침 내내 왔다 갔다 해요. 우산 챙겨 오길 잘했어요.', '["No, it stopped about an hour ago. I didn''t even need my umbrella.","Ugh, don''t ask. My shoes are soaked and the whole day''s ruined.","It''s supposed to clear up by the weekend, at least."]', '["아뇨, 한 시간쯤 전에 그쳤어요. 우산 쓸 일도 없었어요.","말도 마세요. 신발 다 젖었고 오늘 하루 완전히 망했어요.","그래도 주말쯤엔 날이 갠다고 하더라고요, 다행히."]', '["Huh. Your umbrella''s dripping on my floor, though.","Oh no. Well, let''s try to make the rest of it better.","Sure, but is it raining right now?"]', '["어라. 그런데 우산에서 물이 뚝뚝 떨어지는데요.","저런. 그럼 남은 하루는 좀 낫게 만들어 봐요.","그렇군요. 그런데 지금은 비가 와요?"]', '["Rain that starts and stops is \\"on and off\\".","Key words: on and off, good thing, umbrella"]', '["오다 말다 하는 비는 on and off라고 합니다.","핵심 단어: on and off, good thing, umbrella"]', 'maya', 'Smart. I left mine in the car, of course.', '현명하네요. 저는 당연히 차에 두고 왔어요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_one_on_one', 2, 'maya', 'Maya closes her laptop to give you her full attention.', '마야가 노트북을 덮고 당신에게 집중합니다.', 'So, what''s on your mind?', '그래서, 무슨 얘기 하고 싶어요?', 'You want to hear what she honestly thought of your roadmap presentation last week.', '지난주 로드맵 발표를 그녀가 솔직히 어떻게 봤는지 듣고 싶습니다.', '[{"all":["feedback"]}]', 'I''d love your feedback on my roadmap presentation from last week.', '지난주 제 로드맵 발표에 대해 피드백을 듣고 싶어요.', '["I''d love your thoughts on my budget presentation from yesterday.","I just need you to tell me that my roadmap talk last week was good.","Not much, really. The roadmap presentation went fine last week."]', '["어제 제 예산 발표에 대해 의견을 듣고 싶어요.","지난주 로드맵 발표 잘했다고 한마디만 해 주시면 돼요.","딱히 없어요. 지난주 로드맵 발표는 무난하게 끝났고요."]', '["Yesterday? I don''t think I saw a budget presentation.","Well, I''d rather give you something useful than a pat on the back.","Oh. Okay. Then is there anything else you wanted to cover?"]', '["어제요? 예산 발표는 못 본 것 같은데요.","음, 칭찬 한마디보다는 도움이 되는 얘기를 해 주고 싶어요.","아, 그래요. 그럼 다른 얘기할 건 있어요?"]', '["Ask directly: \\"I''d love your feedback on …\\".","Key words: I''d love your feedback, roadmap presentation"]', '["직접 부탁하세요. \\"I''d love your feedback on …\\".","핵심 단어: I''d love your feedback, roadmap presentation"]', 'maya', 'Overall, it was strong. The story was clear. One thing: there were a lot of slides, and you ran out of time for questions.', '전체적으로 좋았어요. 흐름이 분명했어요. 한 가지, 슬라이드가 많아서 질문받을 시간이 없었어요.'),
  ('pr_d3_one_on_one', 3, 'maya', 'It stings a little. You are the one who keeps meetings on time.', '조금 따끔합니다. 회의 시간을 지키는 사람이 바로 당신이니까요.', 'Does that sound fair?', '그 정도면 공정한 평가 같아요?', 'It stings, but she has a point. Accept it and say what you''ll do differently.', '따끔하지만 맞는 말입니다. 받아들이고 다음엔 무엇을 다르게 할지 말하세요.', '[{"any":["fair","good point","cut it","cut","leave time","fewer slides"]}]', 'That''s fair. I''ll cut it down and leave time for Q&A next time.', '맞는 말이에요. 다음엔 분량을 줄이고 질의응답 시간을 남길게요.', '["Honestly, the slides were fine. People just kept showing up late.","That''s fair. I''ll add more slides so the story is even clearer.","That''s fair. I''ll skip the Q&A next time so we finish on time."]', '["솔직히 슬라이드는 괜찮았어요. 사람들이 자꾸 늦게 들어와서 그렇죠.","맞는 말이에요. 흐름이 더 분명하게 슬라이드를 더 넣을게요.","맞는 말이에요. 다음엔 제시간에 끝나게 질의응답을 빼 버릴게요."]', '["Hmm. I''m not sure that''s what happened. I was there.","More slides? I''d actually go the other way.","Skip it? The questions are the part people need most."]', '["음. 제가 보기엔 그런 것 같지 않았어요. 저도 거기 있었잖아요.","슬라이드를 더요? 저라면 오히려 반대로 하겠어요.","빼요? 사람들한테 제일 필요한 게 질문 시간인데요."]', '["Do not defend yourself. Agree, then say what you will change.","Key words: that''s fair, cut it down, leave time for Q&A"]', '["변명하지 마세요. 동의하고, 무엇을 바꿀지 말하세요.","핵심 단어: that''s fair, cut it down, leave time for Q&A"]', 'maya', 'Great. Also, try leading with the bottom line.', '좋아요. 그리고 결론부터 말해 보세요.'),
  ('pr_d3_one_on_one', 4, 'maya', '"The bottom line"? You want to be sure you understand.', '"결론부터"? 정확히 이해하고 싶습니다.', 'Executives want the ask first, and the details second.', '임원들은 요청을 먼저 듣고, 세부 사항은 그다음에 듣고 싶어 해요.', 'You''re not sure what that looks like in practice. Ask her to make it concrete.', '실제로 어떻게 하라는 건지 잘 모르겠습니다. 구체적으로 보여 달라고 하세요.', '[{"any":["example","for instance"]}]', 'Could you give me an example of what you mean?', '무슨 뜻인지 예를 하나 들어 주실 수 있어요?', '["Got it. So I should put the details first, then?","But I did lead with the bottom line, didn''t I?","So executives just skip the slides entirely?"]', '["알겠어요. 그럼 세부 사항을 먼저 말하면 되는 거죠?","그런데 저 결론부터 말하지 않았어요?","그럼 임원들은 슬라이드는 아예 안 본다는 거예요?"]', '["Other way around. The ask comes first.","Not really. As I remember, you started with the background.","No, they still want the slides. Just after the point."]', '["반대예요. 요청이 먼저예요.","글쎄요. 제 기억엔 배경 설명부터 시작했어요.","아뇨, 슬라이드는 봐요. 핵심 다음에요."]', '["When feedback is general, ask for one real case.","Key words: give me an example, what you mean"]', '["피드백이 막연하면 실제 사례를 하나 물어보세요.","핵심 단어: give me an example, what you mean"]', 'maya', 'Sure. Start with: "We need two more weeks for checkout, and here''s why." Then the slides.', '그럼요. "결제 기능에 2주가 더 필요합니다. 이유는 이렇습니다."로 시작하고, 슬라이드는 그다음에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_one_on_one', 5, 'maya', 'You write it down. Maya smiles.', '당신은 받아 적습니다. 마야가 미소 짓습니다.', 'Now your turn. Is there anything I could be doing better?', '이제 프리야 차례예요. 제가 더 잘할 수 있는 게 있을까요?', 'Give her one honest request: you keep finding out about client threads late.', '솔직한 요청을 하나 하세요. 고객과 오가는 메일을 늘 늦게 알게 됩니다.', '[{"any":["loop me in","looped me in","looped","cc","copy me","earlier","sooner"]}]', 'It would help if you looped me in on client emails earlier.', '고객 이메일에 저를 좀 더 일찍 넣어 주시면 도움이 될 것 같아요.', '["No, I think everything''s great. I can''t think of anything.","Honestly, you keep me in the dark on clients. It''s frustrating.","It would help if you sent me fewer emails about the client."]', '["아뇨, 다 좋은 것 같아요. 딱히 떠오르는 게 없어요.","솔직히 고객 건은 늘 저만 모르게 하시잖아요. 답답해요.","고객 관련 메일을 좀 덜 보내 주시면 도움이 될 것 같아요."]', '["Really? Nothing at all? I''d genuinely like to hear it.","Oh. I didn''t realize it felt that way. Thanks for telling me.","Fewer? I thought you''d want to know more, not less."]', '["정말요? 하나도요? 진심으로 듣고 싶어서 묻는 건데.","아. 그렇게 느끼는 줄 몰랐어요. 말해 줘서 고마워요.","덜요? 더 알고 싶어 할 줄 알았는데요."]', '["Soft and clear: \\"It would help if you …\\".","Key words: it would help if, looped me in, earlier"]', '["부드럽지만 분명하게: \\"It would help if you …\\".","핵심 단어: it would help if, looped me in, earlier"]', 'maya', 'That''s fair. I''ll cc you from now on. Let me know if you have any questions.', '맞는 말이에요. 앞으로는 참조로 넣을게요. 궁금한 게 있으면 말해 줘요.'),
  ('pr_d3_planning', 1, 'derek', 'Two o''clock. Wet umbrellas are drying in the corner of the meeting room.', '두 시입니다. 회의실 구석에서 젖은 우산들이 마르고 있습니다.', 'We''re all here. The floor is yours.', '다 모였어요. 시작하세요.', 'Open the meeting and tell everyone how it''s going to work.', '회의를 열고 오늘 어떻게 진행할지 모두에게 알려 주세요.', '[{"any":["estimate","go through","tickets"]}]', 'Welcome to sprint planning. We''ll go through the tickets and estimate each one.', '스프린트 플래닝에 오신 걸 환영해요. 티켓을 하나씩 보면서 각각 추정할게요.', '["Welcome to the retro. Let''s start with what went well this sprint.","Okay, let''s be quick. I already estimated everything, so just agree with me.","Thanks for coming, everyone. Any questions before we wrap up?"]', '["회고에 오신 걸 환영해요. 이번 스프린트에서 잘된 점부터 시작하죠.","자, 빨리 끝내죠. 추정은 제가 다 해 놨으니 그냥 동의해 주세요.","다들 와 줘서 고마워요. 마무리하기 전에 질문 있어요?"]', '["Retro''s on Friday, Priya. Today''s planning.","Uh, then why are we all here?","Wrap up? We haven''t even started."]', '["회고는 금요일이에요, 프리야. 오늘은 플래닝이고요.","어, 그럼 우린 왜 모인 거예요?","마무리요? 아직 시작도 안 했는데요."]', '["Say what the meeting is and what you will do in it.","Key words: sprint planning, go through the tickets, estimate"]', '["무슨 회의인지, 무엇을 할지 말하세요.","핵심 단어: sprint planning, go through the tickets, estimate"]', 'jun', 'Quick question: what does one story point mean for this team?', '잠깐 질문인데요, 이 팀에서 스토리 포인트 1은 무슨 뜻이에요?'),
  ('pr_d3_planning', 2, 'jun', 'It is Jun''s first planning meeting.', '준에게는 첫 플래닝 회의입니다.', 'So a point isn''t the same as an hour?', '그러니까 1포인트가 1시간이랑 같은 건 아니에요?', 'He''s on the right track. Confirm it and explain what a point measures here.', '준이 제대로 짚었습니다. 맞다고 해 주고, 여기서 포인트가 무엇을 재는지 설명하세요.', '[{"any":["effort","complexity","not hours"]}]', 'Right. It''s about effort and complexity, not hours. A one is tiny, an eight is big.', '맞아요. 시간이 아니라 노력과 복잡도예요. 1은 아주 작은 거고, 8은 큰 거예요.', '["Well, roughly. On this team, one point is about half a day of work.","Pretty much, yes. One point is one hour, so an eight is a full day.","Come on, Jun, you really should know this by now. Just look it up after the meeting."]', '["음, 대충은요. 우리 팀에선 1포인트가 반나절 정도 일이에요.","거의 같아요. 1포인트가 1시간이니까 8이면 하루 꼬박이죠.","준, 이 정도는 알고 있어야죠. 회의 끝나고 따로 찾아보세요."]', '["Half a day? I thought it wasn''t about time at all.","Oh. Then why don''t we just estimate in hours?","Oh. Sorry. I''ll look it up."]', '["반나절이요? 시간이랑은 상관없는 줄 알았는데요.","아. 그럼 그냥 시간으로 추정하면 되잖아요?","아. 죄송해요. 찾아볼게요."]', '["A point measures how hard the work is, not how long.","Key words: effort, complexity, not hours"]', '["포인트는 걸리는 시간이 아니라 일이 얼마나 어려운지를 잽니다.","핵심 단어: effort, complexity, not hours"]', 'jun', 'That makes sense. Thanks.', '이해됐어요. 고맙습니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_planning', 3, 'derek', 'The first ticket is on the screen: a "save card for later" checkbox at checkout.', '첫 티켓이 화면에 떠 있습니다. 결제 화면의 "카드 저장" 체크박스입니다.', 'I''d call that one a three.', '저는 그거 3이라고 봐요.', 'Derek gave his number. Get the new guy''s view before you settle on it.', '데릭은 자기 숫자를 말했습니다. 정하기 전에 신입의 생각도 들어 보세요.', '[{"all":["jun"],"any":["estimate","think","say","points","number"]},{"all":["what would you estimate"]}]', 'Jun, what would you estimate?', '준, 준은 얼마로 추정해요?', '["Great, three it is. Next ticket.","Derek, what would you estimate?","Jun, you agree it''s a three, right?"]', '["좋아요, 3으로 하죠. 다음 티켓.","데릭, 얼마로 추정해요?","준, 3 맞죠? 동의하죠?"]', '["Hold on. Shouldn''t we hear from Jun, too?","I just said three. Were you listening?","Uh... sure, I guess."]', '["잠깐만요. 준 얘기도 들어 봐야 하지 않아요?","방금 3이라고 했잖아요. 듣고 있었어요?","어... 네, 그런 것 같아요."]', '["Bring in the quiet person by name.","Key words: Jun, what would you estimate"]', '["조용한 사람을 이름으로 불러 참여시키세요.","핵심 단어: Jun, what would you estimate"]', 'jun', 'I''d say a three. The UI is simple, but we need to test it carefully.', '3이라고 생각해요. 화면은 단순하지만 꼼꼼히 테스트해야 하니까요.'),
  ('pr_d3_planning', 4, 'derek', 'Three it is. The next ticket comes up.', '3으로 정했습니다. 다음 티켓이 뜹니다.', 'Next is the refund bug. The ticket''s pretty vague.', '다음은 환불 버그예요. 티켓 내용이 꽤 모호하네요.', 'Find someone with room in their week to own it.', '이번 주에 여유가 있어서 이 티켓을 맡을 사람을 찾으세요.', '[{"any":["capacity","who wants","who can","volunteers","volunteer","anybody want","anyone want"]}]', 'Who has the capacity to take this one?', '이번 주에 이거 맡을 여유 있는 사람 있어요?', '["Jun, you''re taking this one. No arguments.","Let''s skip it. Nobody likes vague tickets.","Who wrote this ticket? It makes no sense."]', '["준, 이건 준이 맡아요. 토 달지 말고요.","이건 건너뛰죠. 모호한 티켓은 다들 싫어해요.","이 티켓 누가 썼어요? 말이 안 되는데요."]', '["Whoa. Maybe ask him first?","We can''t skip it. Customers are hitting this bug.","Does it matter? Someone still needs to take it."]', '["워. 본인한테 먼저 물어보는 게 어때요?","건너뛸 순 없어요. 고객들이 이 버그를 겪고 있어요.","그게 중요해요? 어쨌든 누군가는 맡아야죠."]', '["Ask for an owner without pointing at anyone.","Key words: who has the capacity, take this one"]', '["누구를 지목하지 말고 맡을 사람을 구하세요.","핵심 단어: who has the capacity, take this one"]', 'jun', 'I can take it, but I''ll need more details first.', '제가 맡을 수 있어요. 다만 먼저 자세한 내용이 필요해요.'),
  ('pr_d3_planning', 5, 'jun', 'Jun has his pen ready.', '준이 펜을 들고 기다립니다.', 'Could you add the customer''s steps to the ticket?', '티켓에 고객이 한 단계들을 추가해 주실 수 있어요?', 'Agree, and promise to have them in before you leave today.', '그러겠다고 하고, 오늘 퇴근 전까지 넣어 두겠다고 약속하세요.', '[{"any":["steps","end of day","eod","by tonight"]}]', 'Sure. I''ll add the steps to reproduce it by end of day.', '그럼요. 오늘 퇴근 전까지 재현 단계를 넣어 둘게요.', '["Sure. I''ll add the steps sometime next week, I think.","Can''t you just ask the customer yourself? I''m swamped.","Sure. I''ll add the customer''s email so you can ask her."]', '["그럼요. 다음 주 언젠가 단계를 넣어 둘게요, 아마도.","고객한테 직접 물어보면 안 돼요? 저 지금 정신없어요.","그럼요. 고객 이메일을 넣어 둘 테니 직접 물어보세요."]', '["Next week? I was hoping to start on it tomorrow.","Oh. Okay. I just thought you''d have the details.","Hmm. I''d rather have the steps in the ticket, if possible."]', '["다음 주요? 내일부터 시작하려고 했는데요.","아. 네. 프리야가 자세한 걸 알 줄 알았어요.","음. 가능하면 티켓에 단계가 들어 있으면 좋겠어요."]', '["Promise what and by when.","Key words: steps to reproduce, by end of day"]', '["무엇을 언제까지 할지 약속하세요.","핵심 단어: steps to reproduce, by end of day"]', 'jun', 'Perfect. Thank you!', '좋아요. 고맙습니다!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_planning', 6, 'derek', 'Derek adds up the numbers on the whiteboard.', '데릭이 화이트보드의 숫자를 더합니다.', 'That''s thirty-four points. We usually finish about thirty-five.', '34포인트네요. 우리는 보통 35 정도 끝내요.', 'The sprint is full. Check whether the team is comfortable with the load.', '스프린트가 꽉 찼습니다. 팀이 이 양을 감당할 만한지 확인하세요.', '[{"any":["at capacity","capacity","too much","overcommitted"]}]', 'Then we''re at capacity. Does anyone feel like this is too much?', '그럼 수용량이 꽉 찼네요. 혹시 너무 많다고 느끼는 사람 있어요?', '["Then we still have room. Let''s pull in two more tickets.","Great, then it''s settled. Everyone just needs to push a little.","That''s way over our usual. Should we drop a ticket or two?"]', '["그럼 아직 여유가 있네요. 티켓 두 개 더 넣죠.","좋아요, 그럼 확정이에요. 다들 조금만 더 힘내면 돼요.","평소보다 훨씬 많네요. 그럼 티켓을 한두 개 빼야 할까요?"]', '["Two more? We''ve got one point left.","Push a little? That''s how people burn out.","Over? Thirty-four is under thirty-five."]', '["두 개 더요? 1포인트 남았는데요.","조금만 더 힘내라고요? 그러다 다들 지쳐요.","많다고요? 34는 35보다 적은데요."]', '["Check before you commit: is the sprint too full?","Key words: at capacity, too much"]', '["확정하기 전에 확인하세요. 스프린트가 너무 찼나요?","핵심 단어: at capacity, too much"]', 'derek', 'Looks doable to me. Let''s lock it in.', '할 만해 보여요. 이대로 확정하죠.'),
  ('pr_d4_client', 1, 'greg', 'The meeting room is empty. You dial Greg''s number on the speakerphone Tom tested on Monday.', '회의실이 비어 있습니다. 톰이 월요일에 점검해 둔 스피커폰으로 그렉의 번호를 누릅니다.', 'Greg Whitfield.', '그렉 휘트필드입니다.', 'Introduce yourself properly and check that he can talk.', '제대로 자신을 소개하고, 지금 통화할 수 있는지 확인하세요.', '[{"any":["good time","bad time","a minute","a few minutes","a moment"]}]', 'Hi, Greg. It''s Priya Nair from Seaside Labs. Is now a good time?', '안녕하세요, 그렉. 시사이드 랩스의 프리야 나이르입니다. 지금 통화 괜찮으세요?', '["Hi, Greg. It''s Priya Nair from Summit Retail. Is now a good time?","Hey, Greg, Priya here. Got a sec? Got some news. Kind of a bummer.","Hi, Greg. It''s Priya. So, we''ve got a problem with the refunds."]', '["안녕하세요, 그렉. 서밋 리테일의 프리야 나이르입니다. 지금 통화 괜찮으세요?","안녕, 그렉, 프리야예요. 잠깐 돼요? 소식이 있는데 좀 별로예요.","안녕하세요, 그렉. 프리야예요. 그게, 환불 쪽에 문제가 생겼어요."]', '["Summit Retail? That''s us. Who is this?","A bummer? Okay. Who is this, exactly?","Priya who? Hold on. Which company?"]', '["서밋 리테일이요? 그건 우리 회사인데요. 누구십니까?","별로라고요? 네. 그런데 정확히 누구십니까?","프리야 누구요? 잠깐만요. 어느 회사입니까?"]', '["On the phone: your name, your company, then \\"Is now a good time?\\"","Key words: it''s Priya from Seaside Labs, is now a good time"]', '["전화에서는 이름, 회사, 그리고 \\"Is now a good time?\\" 순서입니다.","핵심 단어: it''s Priya from Seaside Labs, is now a good time"]', 'greg', 'I''ve got five minutes. What''s the bottom line?', '5분 있습니다. 결론이 뭡니까?'),
  ('pr_d4_client', 2, 'greg', 'Maya told you yesterday: lead with the bottom line.', '어제 마야가 말했습니다. 결론부터 말하라고.', 'Go ahead.', '말씀하세요.', 'Get straight to it: when the card refund fix and the gift card refunds will each be ready.', '바로 본론으로 가세요. 카드 환불 수정과 기프트 카드 환불이 각각 언제 준비되는지요.', '[{"all":["expectations"]},{"all":["wednesday"]}]', 'I want to set expectations. The card refund fix ships Friday, but gift card refunds will slip to Wednesday.', '미리 기대치를 맞춰 두고 싶습니다. 카드 환불 수정은 금요일에 나가지만, 기프트 카드 환불은 수요일로 밀립니다.', '["I want to set expectations. Gift card refunds ship Friday, but the card refund fix will slip to Wednesday.","So, a little background first. The refund code is quite old, the ticket was vague, and we found that...","Bad news, I''m afraid. Our new developer underestimated the refund bug, so gift cards will be late."]', '["미리 기대치를 맞춰 두고 싶습니다. 기프트 카드 환불은 금요일에 나가지만, 카드 환불 수정은 수요일로 밀립니다.","그게, 배경부터 말씀드릴게요. 환불 코드가 꽤 오래됐고 티켓도 모호했는데, 알고 보니...","안 좋은 소식입니다. 저희 신입 개발자가 환불 버그를 얕봐서 기프트 카드가 늦어지게 됐습니다."]', '["Hold on. The card fix is what slips? That''s the one I care about.","Priya, I have five minutes. Bottom line, please.","I don''t need to know whose fault it is. When do I get it?"]', '["잠깐만요. 밀리는 게 카드 수정입니까? 제가 신경 쓰는 게 그건데요.","프리야, 저 5분밖에 없습니다. 결론만 말해 주세요.","누구 잘못인지는 알 필요 없습니다. 언제 받을 수 있습니까?"]', '["Start with \\"I want to set expectations\\", then the good news and the bad news.","Key words: set expectations, ships Friday, slip to Wednesday"]', '["\\"I want to set expectations\\"로 시작하고, 좋은 소식과 나쁜 소식을 말하세요.","핵심 단어: set expectations, ships Friday, slip to Wednesday"]', 'greg', 'Slip? Why am I only hearing about this now?', '밀린다고요? 왜 이제야 그 얘기를 듣는 겁니까?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_client', 3, 'greg', 'He does not sound happy. You stay calm.', '그렉의 목소리가 좋지 않습니다. 당신은 침착함을 잃지 않습니다.', 'Well?', '그래서요?', 'Stay calm. Tell him when the problem came up and why you''re calling him now.', '침착하게, 문제가 언제 드러났는지, 왜 지금 전화했는지 말하세요.', '[{"any":["this morning","right away","hear it from me","as soon as","first"]}]', 'We found the issue this morning, and I wanted you to hear it from me right away.', '오늘 아침에 문제를 발견했고, 다른 데서 듣기 전에 제가 직접 바로 말씀드리고 싶었습니다.', '["We actually found the issue last week, and I wanted to be sure before I called you.","Honestly, the original ticket was vague. It''s not really on our side.","Things slip sometimes, Greg. That''s software. It''s only a few days."]', '["사실 문제는 지난주에 발견했는데, 확실해진 다음에 전화드리고 싶었습니다.","솔직히 원래 티켓이 모호했습니다. 저희 쪽 문제라고 보긴 어렵습니다.","일정은 원래 좀 밀리기도 해요, 그렉. 소프트웨어가 그렇죠. 며칠뿐이에요."]', '["Last week? And I''m only hearing about it now?","Not on your side? It''s your code, isn''t it?","A few days matter to me, Priya. My boss is asking."]', '["지난주요? 그런데 이제야 저한테 말하는 겁니까?","그쪽 문제가 아니라고요? 그쪽 코드 아닙니까?","저한텐 며칠도 중요합니다, 프리야. 제 상사가 묻고 있어요."]', '["Say when you found out and why you are calling now.","Key words: found the issue this morning, hear it from me"]', '["언제 알게 됐는지, 왜 지금 전화하는지 말하세요.","핵심 단어: found the issue this morning, hear it from me"]', 'greg', 'All right. I appreciate that. Does this affect Monday''s demo?', '알겠습니다. 그건 고맙군요. 월요일 데모에 영향이 있습니까?'),
  ('pr_d4_client', 4, 'greg', 'This is the question that matters most to him.', '그렉에게 가장 중요한 질문입니다.', 'I have my whole team coming on Monday.', '월요일에 우리 팀 전체가 옵니다.', 'Put his mind at ease about Monday, and tell him why.', '월요일 걱정은 덜어 드리고, 그 이유를 말하세요.', '[{"any":["not affected","will not affect","does not affect","no impact","not part","on track"]}]', 'No, the demo is not affected. Gift card refunds aren''t part of it.', '아뇨, 데모에는 영향이 없습니다. 기프트 카드 환불은 데모에 들어 있지 않거든요.', '["No, the demo''s fine. Card refunds aren''t part of it, so we''re safe.","I don''t think so, but honestly, I''d have to check with the team.","A little. We''ll have to skip the refund part on Monday, sorry."]', '["아뇨, 데모는 괜찮습니다. 카드 환불은 데모에 없으니 문제없어요.","아닐 거예요. 그런데 솔직히 팀에 확인해 봐야 알 것 같습니다.","조금요. 월요일엔 환불 부분은 빼야 할 것 같아요. 죄송합니다."]', '["Card refunds? I thought those were shipping Friday.","You don''t know? My whole team is coming Monday.","Skip it? Then what exactly am I showing my team?"]', '["카드 환불이요? 그건 금요일에 나간다고 하지 않았습니까?","모르신다고요? 월요일에 우리 팀 전체가 온다니까요.","뺀다고요? 그럼 우리 팀한테 대체 뭘 보여 줍니까?"]', '["Answer the question first: no. Then one reason.","Key words: the demo is not affected, not part of it"]', '["질문에 먼저 답하세요. 아니요. 그다음 이유 하나.","핵심 단어: the demo is not affected, not part of it"]', 'greg', 'Good. Can you guarantee Wednesday?', '좋습니다. 수요일은 확실히 보장할 수 있습니까?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_client', 5, 'greg', 'A guarantee is a big word. Greg likes honest answers.', '보장은 무거운 말입니다. 그렉은 솔직한 답을 좋아합니다.', 'I need something I can tell my boss.', '제 상사한테 전할 말이 필요합니다.', 'Be honest: no guarantee, but you believe in the date. Offer to check in with him the day before.', '솔직하게 말하세요. 보장은 못 해도 그 날짜에 자신은 있다고요. 하루 전에 상황을 알려 주겠다고 하세요.', '[{"any":["overpromise","over promise","confident","update"]}]', 'I don''t want to overpromise. I''m confident in Wednesday, and I''ll send you an update on Tuesday.', '지키지 못할 약속은 드리고 싶지 않습니다. 수요일은 자신 있고, 화요일에 진행 상황을 보내 드리겠습니다.', '["Absolutely. I guarantee Wednesday. You can tell your boss it''s a done deal.","I don''t want to overpromise. I''m confident in Friday, and I''ll send you an update on Thursday.","Honestly, I can''t promise anything. It depends on what the team finds next week."]', '["물론입니다. 수요일은 제가 보장합니다. 상사분께 확정이라고 전하셔도 됩니다.","지키지 못할 약속은 드리고 싶지 않습니다. 금요일은 자신 있고, 목요일에 진행 상황을 보내 드리겠습니다.","솔직히 아무것도 약속드릴 수 없습니다. 다음 주에 팀이 뭘 찾아내느냐에 달렸어요."]', '["A done deal? All right. I''ll hold you to that, Priya.","Friday? I thought you said Wednesday.","That''s not something I can take to my boss."]', '["확정이라고요? 좋습니다. 그 말 꼭 기억하겠습니다, 프리야.","금요일이요? 수요일이라고 하지 않았습니까?","그걸로는 제 상사한테 아무 말도 못 합니다."]', '["Be honest about the risk, then say when he will hear from you.","Key words: don''t want to overpromise, confident, send you an update"]', '["위험을 솔직히 말하고, 언제 다시 연락할지 알려 주세요.","핵심 단어: don''t want to overpromise, confident, send you an update"]', 'greg', 'Fair enough. I like a straight answer. Talk to you Monday, Priya.', '좋습니다. 솔직한 답이 마음에 드네요. 월요일에 봅시다, 프리야.'),
  ('pr_d4_scope', 1, 'derek', 'A gray, cool morning. Jun has just told you the refund bug is taking longer than he expected.', '흐리고 선선한 아침입니다. 준이 방금 환불 버그가 예상보다 오래 걸린다고 알려 왔습니다.', 'Hey. I heard about the refund bug. Jun''s deep in the legacy code, huh?', '안녕하세요. 환불 버그 얘기 들었어요. 준이 레거시 코드에 푹 빠져 있죠?', 'Give Jun credit for raising it in time, then get Derek''s take.', '준이 제때 알려 준 걸 인정해 주고, 데릭은 어떻게 보는지 물어보세요.', '[{"any":["your read","your take","what do you think","how bad"]}]', 'Yeah. He flagged it early, which I appreciate. What''s your read on it?', '네. 일찍 알려 줘서 고마웠어요. 데릭은 어떻게 봐요?', '["Yeah. He should''ve seen this coming, though. Why didn''t he ask for help sooner?","Yeah. Can you take it over? He''s clearly in over his head.","Yeah. Honestly, I think it''s a one-line fix. Let''s not worry."]', '["네. 그래도 예상은 했어야죠. 왜 도와 달라고 안 했대요?","네. 데릭이 넘겨받으면 안 돼요? 준한테는 확실히 벅차 보여요.","네. 솔직히 한 줄만 고치면 될 것 같아요. 걱정 말죠."]', '["Easy. It''s legacy code nobody''s touched in years.","Whoa, not so fast. He''s doing fine. It''s just messy code.","One line? I wish. It''s bigger than that."]', '["살살 해요. 몇 년 동안 아무도 안 건드린 레거시 코드예요.","워, 너무 앞서가지 마요. 준은 잘하고 있어요. 코드가 엉망일 뿐이에요.","한 줄이요? 그러면 좋겠네요. 그보다 커요."]', '["\\"What''s your read on it?\\" asks for an expert''s opinion.","Key words: flagged it early, what''s your read"]', '["\\"What''s your read on it?\\"은 전문가의 판단을 묻는 말입니다.","핵심 단어: flagged it early, what''s your read"]', 'derek', 'It''s two bugs, really. Card refunds and gift card refunds. No tests on either one.', '사실은 버그가 두 개예요. 카드 환불과 기프트 카드 환불. 둘 다 테스트가 없어요.'),
  ('pr_d4_scope', 2, 'derek', 'Two bugs, not one. You need a date.', '버그가 하나가 아니라 둘입니다. 날짜가 필요합니다.', 'So it''s more work than the ticket says.', '그러니까 티켓에 적힌 것보다 일이 많아요.', 'You need a date. Find out how long the whole thing would take.', '날짜가 필요합니다. 전부 고치려면 얼마나 걸리는지 알아보세요.', '[{"any":["eta","how long","when would","when will","when can"]}]', 'What''s the ETA if we fix both?', '둘 다 고치면 언제쯤 끝나요?', '["Can we have both done by Friday?","What''s the ETA on the card fix alone?","Why weren''t there any tests on these?"]', '["둘 다 금요일까지 끝낼 수 있죠?","카드 환불만 고치면 언제 끝나요?","왜 둘 다 테스트가 하나도 없었어요?"]', '["Friday? Not a chance. Not both.","Just the card one? Let''s start with the full picture.","Ancient history. Do you want a date or not?"]', '["금요일이요? 절대 안 돼요. 둘 다는요.","카드 쪽만요? 일단 전체 그림부터 보죠.","그건 옛날 얘기고요. 날짜 필요한 거 아니에요?"]', '["ETA = estimated time of arrival: when will it be done?","Key words: what''s the ETA, fix both"]', '["ETA는 예상 완료 시점입니다. 언제 끝나는지 물어보세요.","핵심 단어: what''s the ETA, fix both"]', 'derek', 'Both? End of next week, realistically.', '둘 다요? 현실적으로 다음 주 말이에요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_scope', 3, 'derek', 'The client demo is on Monday. End of next week is too late.', '고객 데모는 월요일입니다. 다음 주 말은 너무 늦습니다.', 'I know that''s not what you wanted to hear.', '듣고 싶은 대답이 아니라는 건 알아요.', 'That''s too late for the client. Find out how to get just the card part out this week.', '고객 일정에는 너무 늦습니다. 카드 쪽만이라도 이번 주에 내보낼 방법을 알아보세요.', '[{"all":["what would it take"]},{"all":["friday"],"any":["ship","card","fix","release"]}]', 'The client demo is on Monday. What would it take to ship the card fix by Friday?', '고객 데모가 월요일이에요. 카드 수정을 금요일까지 내보내려면 뭐가 필요해요?', '["The client demo is on Friday. What would it take to ship both fixes by then?","That doesn''t work for me. You and Jun will just have to get both done by Friday.","Okay, end of next week, then. I''ll tell the client the demo has to wait."]', '["고객 데모가 금요일이에요. 그때까지 둘 다 내보내려면 뭐가 필요해요?","그건 안 돼요. 데릭이랑 준이 어떻게든 금요일까지 둘 다 끝내 줘야 해요.","알겠어요, 그럼 다음 주 말로 하죠. 고객한테 데모는 미루자고 할게요."]', '["Friday? I thought the demo was Monday.","That''s not how this works, Priya. Both won''t fit.","Push the demo? That''s a big ask for the client."]', '["금요일이요? 데모는 월요일인 줄 알았는데요.","그렇게는 안 돼요, 프리야. 둘 다는 못 들어가요.","데모를 미뤄요? 고객한테 그건 큰 부탁인데요."]', '["Do not demand. Ask \\"What would it take to …?\\"","Key words: what would it take, ship, by Friday"]', '["요구하지 말고 \\"What would it take to …?\\"로 물어보세요.","핵심 단어: what would it take, ship, by Friday"]', 'derek', 'If I pair with Jun and we leave the gift cards for later, Friday''s doable.', '제가 준과 같이 작업하고 기프트 카드를 뒤로 미루면 금요일은 가능해요.'),
  ('pr_d4_scope', 4, 'derek', 'That is a plan you can take to the client.', '고객에게 가져갈 수 있는 계획입니다.', 'But the gift card part needs a new date.', '그런데 기프트 카드 쪽은 새 날짜가 필요해요.', 'Offer a plan with a new date for the gift cards, next Wednesday, and make sure he''s on board.', '기프트 카드에 새 날짜(다음 주 수요일)를 넣은 계획을 내놓고, 데릭이 동의하는지 확인하세요.', '[{"all":["wednesday"]},{"any":["does that work","work for you"]}]', 'Let''s do card refunds on Friday and gift cards by next Wednesday. Does that work for you?', '카드 환불은 금요일, 기프트 카드는 다음 주 수요일까지로 하죠. 괜찮아요?', '["Let''s do card refunds on Friday and gift cards by this Monday. Does that work?","Card refunds Friday, gift cards next Wednesday. I''m telling the client, so make it happen.","Let''s do gift cards on Friday and card refunds by next Wednesday. Does that work for you?"]', '["카드 환불은 금요일, 기프트 카드는 이번 월요일까지로 하죠. 괜찮아요?","카드 환불은 금요일, 기프트 카드는 다음 주 수요일. 고객한테 그렇게 말할 테니 꼭 맞춰요.","기프트 카드는 금요일, 카드 환불은 다음 주 수요일까지로 하죠. 괜찮아요?"]', '["By Monday? That''s three days away, with a weekend in between.","Whoa. Maybe ask me before you promise it to anyone?","Other way around. The card fix is the one that''s close."]', '["월요일까지요? 주말 끼고 사흘 남았는데요.","워. 누구한테 약속하기 전에 저한테 먼저 물어봐 줄래요?","반대예요. 거의 다 된 건 카드 쪽이에요."]', '["Offer two dates, then check: \\"Does that work for you?\\"","Key words: card refunds on Friday, next Wednesday, does that work for you"]', '["날짜 두 개를 제안한 뒤 확인하세요. \\"Does that work for you?\\"","핵심 단어: card refunds on Friday, next Wednesday, does that work for you"]', 'derek', 'Wednesday works. But then I have to drop the search filter ticket.', '수요일 괜찮아요. 그런데 그러려면 검색 필터 티켓은 내려놓아야 해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_scope', 5, 'derek', 'Something has to give. You decide quickly.', '무언가는 포기해야 합니다. 당신은 빠르게 결정합니다.', 'Are you okay with that?', '그래도 괜찮겠어요?', 'Accept the trade-off. Say where that ticket goes and who you''ll tell.', '맞바꿈을 받아들이세요. 그 티켓을 어디로 옮기고 누구에게 알릴지 말하세요.', '[{"any":["next sprint","move it","push it","backlog"]}]', 'That''s fine. I''ll move it to the next sprint and let the client know.', '괜찮아요. 그건 다음 스프린트로 옮기고 고객한테 알릴게요.', '["Hmm, can''t you squeeze it in over the weekend? The client wants it.","That''s fine. We''ll just quietly drop it. The client won''t notice.","That''s fine. I''ll move the refund bug to the next sprint instead, then."]', '["음, 주말에 어떻게 끼워 넣을 수 없어요? 고객이 원하는 건데.","괜찮아요. 그냥 조용히 빼죠. 고객은 눈치 못 챌 거예요.","괜찮아요. 그럼 대신 환불 버그를 다음 스프린트로 옮길게요."]', '["The weekend? No. I''m not doing that to Jun or to me.","Quietly? That usually comes back to bite you.","The refund bug? No, I meant the search filter."]', '["주말이요? 안 돼요. 준한테도 저한테도 그렇게는 못 해요.","조용히요? 그러면 꼭 나중에 탈이 나요.","환불 버그요? 아뇨, 검색 필터 말한 거예요."]', '["Make the cut, and say who you will tell.","Key words: move it to the next sprint, let the client know"]', '["뺄 것을 정하고, 누구에게 알릴지 말하세요.","핵심 단어: move it to the next sprint, let the client know"]', 'derek', 'Thanks for not asking for everything at once. I''ll grab Jun.', '한꺼번에 다 해 달라고 하지 않아서 고마워요. 준을 데려올게요.'),
  ('pr_d5_demo', 1, 'derek', 'Friday, eleven o''clock. The sun is out and the card fix shipped this morning.', '금요일 열한 시입니다. 해가 났고, 카드 환불 수정은 오늘 아침에 배포됐습니다.', 'Everybody''s here, and the projector actually works today.', '다 왔어요. 오늘은 프로젝터도 제대로 되네요.', 'Kick off the demo and hand it to Jun first, with his card fix.', '데모를 시작하고, 첫 순서로 준에게 카드 수정을 보여 달라고 넘기세요.', '[{"any":["up first","go first","demo time","show us"]}]', 'Okay, demo time! Jun, you''re up first. Want to show us the card payment fix?', '좋아요, 데모 시간이에요! 준, 첫 순서예요. 카드 결제 수정 보여 줄래요?', '["Okay, demo time! Jun, you''re up first. Want to show us the gift card fix?","Okay, retro time! Let''s start with what went well this week. Jun?","Okay, demo time! Derek, why don''t you show Jun''s fix for him? It''ll be faster."]', '["좋아요, 데모 시간이에요! 준, 첫 순서예요. 기프트 카드 수정 보여 줄래요?","좋아요, 회고 시간이에요! 이번 주에 잘된 점부터 시작하죠. 준?","좋아요, 데모 시간이에요! 데릭, 준이 고친 거 데릭이 대신 보여 줘요. 그게 빨라요."]', '["Gift cards? Those aren''t done until Wednesday.","Retro already? I thought we were doing the demo first.","Me? It''s his work. Let him show it."]', '["기프트 카드요? 그건 수요일에야 끝나요.","벌써 회고요? 데모부터 하는 줄 알았는데요.","제가요? 준이 한 일이잖아요. 준이 보여 주게 해요."]', '["\\"You''re up first\\" tells someone it is their turn to present.","Key words: demo time, you''re up first, show us"]', '["\\"You''re up first\\"는 발표할 첫 순서라는 말입니다.","핵심 단어: demo time, you''re up first, show us"]', 'jun', 'Sure. Let me share my screen.', '네. 화면을 공유할게요.'),
  ('pr_d5_demo', 2, 'jun', 'Jun''s screen appears on the wall.', '준의 화면이 벽에 뜹니다.', 'Can everyone see it?', '다들 보여요?', 'Confirm it''s showing, and ask him to take you through the changes step by step.', '화면이 보인다고 하고, 바뀐 점을 하나씩 설명해 달라고 하세요.', '[{"any":["walk us through","walk me through","go ahead","we can see"]}]', 'We can see it. Go ahead and walk us through what changed.', '잘 보여요. 뭐가 바뀌었는지 차근차근 설명해 줘요.', '["Not yet, it''s still loading. Can you share it again?","We can see it. Can you show us the gift card refunds too?","We can see it. Go ahead and show us the code line by line."]', '["아직요, 로딩 중이에요. 다시 공유해 줄래요?","잘 보여요. 기프트 카드 환불도 같이 보여 줄래요?","잘 보여요. 코드를 한 줄씩 보여 주면서 설명해 줘요."]', '["Really? It''s up on the wall for me.","Gift cards aren''t done yet. That''s next Wednesday.","Line by line? I was going to show how it works for users."]', '["그래요? 제 쪽에선 벽에 떠 있는데요.","기프트 카드는 아직이에요. 다음 주 수요일이요.","한 줄씩요? 사용자 입장에서 어떻게 되는지 보여 드리려고 했는데요."]', '["\\"Walk us through …\\" asks for a step-by-step explanation.","Key words: we can see it, walk us through"]', '["\\"Walk us through …\\"는 단계별로 설명해 달라는 말입니다.","핵심 단어: we can see it, walk us through"]', 'jun', 'Now, if a payment fails, the user sees a clear error message, and we retry once automatically.', '이제 결제가 실패하면 사용자에게 분명한 오류 메시지가 보이고, 자동으로 한 번 다시 시도합니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d5_demo', 3, 'derek', 'Everyone claps. Derek raises a finger. You look at the clock: ten minutes left.', '모두 박수를 칩니다. 데릭이 손가락을 듭니다. 시계를 보니 10분 남았습니다.', 'That reminds me: we should rethink the whole retry library.', '그러고 보니, 재시도 라이브러리 전체를 다시 생각해 봐야 해요.', 'Good idea, wrong time. Set it aside for now and say why.', '좋은 생각이지만 지금은 때가 아닙니다. 일단 미뤄 두자고 하고 이유를 말하세요.', '[{"any":["park","offline","circle back","parking lot"]}]', 'Can we park that? We have ten minutes left, and I want to get to the retro.', '그건 잠깐 미뤄 둘까요? 10분 남았고, 회고로 넘어가고 싶어요.', '["Can we save that? We''ve got two minutes left, and I want to get to the retro.","Derek, not now. Nobody wants to hear about the retry library.","Good point. Let''s talk it through right now. What would you change first?"]', '["그건 나중에 할까요? 2분 남았고, 회고로 넘어가고 싶어요.","데릭, 지금은 아니에요. 재시도 라이브러리 얘기 듣고 싶은 사람 없어요.","좋은 지적이에요. 지금 바로 얘기해 보죠. 뭐부터 바꾸고 싶어요?"]', '["Two? The clock says ten.","Okay... noted. Pretty sure some people do.","Uh, sure. But do we have time for that?"]', '["2분이요? 시계는 10분 남았다는데요.","네... 알겠어요. 듣고 싶은 사람도 있을 텐데요.","어, 좋아요. 그런데 그럴 시간이 있어요?"]', '["\\"Park\\" an idea = save it for later, like a car in a parking lot.","Key words: can we park that, ten minutes left"]', '["아이디어를 park한다는 것은 주차하듯 나중을 위해 세워 둔다는 뜻입니다.","핵심 단어: can we park that, ten minutes left"]', 'derek', 'Parked. Put it on the list.', '미뤄 둘게요. 목록에 적어 두세요.'),
  ('pr_d5_demo', 4, 'derek', 'You draw three columns on the whiteboard.', '화이트보드에 세 칸을 그립니다.', 'Okay. Retro time.', '좋아요. 회고 시간이에요.', 'Begin with the positives and open the floor.', '좋았던 점부터 시작하고, 말할 사람을 받으세요.', '[{"all":["went well"]}]', 'Let''s start with what went well. Who wants to go first?', '잘된 점부터 시작하죠. 누가 먼저 말해 볼래요?', '["Let''s start with what went wrong. Who wants to go first?","Let''s start with the action items. Who owns the ticket template?","Let''s start with what went well. Jun, you first, since you''re new."]', '["잘못된 점부터 시작하죠. 누가 먼저 말해 볼래요?","액션 아이템부터 시작하죠. 티켓 양식은 누가 맡을래요?","잘된 점부터 시작하죠. 준, 신입이니까 준이 먼저 해요."]', '["Ouch, straight to the bad stuff? We usually warm up first.","Action items already? Nobody''s said anything yet.","Easy. Let him jump in if he wants to."]', '["아이고, 바로 나쁜 얘기부터요? 보통은 좀 풀고 시작하잖아요.","벌써 액션 아이템이요? 아직 아무도 말 안 했는데요.","살살 해요. 하고 싶으면 알아서 하게 둬요."]', '["A retro has three parts. Begin with the good one.","Key words: what went well, who wants to go first"]', '["회고는 세 부분입니다. 좋은 것부터 시작하세요.","핵심 단어: what went well, who wants to go first"]', 'jun', 'The team was really supportive, and the code reviews were super helpful.', '팀이 정말 많이 도와줬고, 코드 리뷰가 큰 도움이 됐어요.'),
  ('pr_d5_demo', 5, 'jun', 'Second column: what could be better. Jun takes a breath.', '둘째 칸은 더 나아질 점입니다. 준이 숨을 고릅니다.', 'Some tickets could be clearer before planning. The refund bug was a little vague.', '플래닝 전에 티켓이 좀 더 분명하면 좋겠어요. 환불 버그는 좀 모호했어요.', 'He''s right, and the tickets are your job. Own it and say what you''ll change.', '준의 말이 맞고, 티켓은 당신 몫입니다. 인정하고 무엇을 바꿀지 말하세요.', '[{"any":["acceptance criteria","fair","criteria"]}]', 'Totally fair. I''ll add acceptance criteria to every ticket from now on.', '정말 맞는 말이에요. 앞으로는 모든 티켓에 인수 조건을 넣을게요.', '["That''s fair, but you could''ve asked me for details sooner, too.","Totally fair. Derek will add acceptance criteria to every ticket from now on.","Totally fair. I''ll rewrite every ticket in the backlog by Monday."]', '["맞는 말인데, 준도 자세한 걸 좀 더 일찍 물어볼 수 있었잖아요.","정말 맞는 말이에요. 앞으로는 데릭이 모든 티켓에 인수 조건을 넣을 거예요.","정말 맞는 말이에요. 월요일까지 백로그 티켓을 전부 다시 쓸게요."]', '["Oh. Okay. I did ask as soon as I could, though.","Derek? I thought writing tickets was your thing.","All of them by Monday? That sounds like a lot."]', '["아. 네. 그래도 저는 최대한 빨리 물어본 건데요.","데릭이요? 티켓은 프리야가 쓰는 줄 알았어요.","월요일까지 전부요? 그건 너무 많은 것 같은데요."]', '["The feedback is about your tickets. Take it well and promise a change.","Key words: totally fair, acceptance criteria, from now on"]', '["당신의 티켓에 대한 피드백입니다. 잘 받아들이고 바꾸겠다고 약속하세요.","핵심 단어: totally fair, acceptance criteria, from now on"]', 'derek', 'I''ll second that. Clear tickets save everybody time.', '저도 동의해요. 티켓이 분명하면 모두의 시간이 절약되죠.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d5_demo', 6, 'derek', 'Two minutes left. Third column: action items.', '2분 남았습니다. 셋째 칸은 액션 아이템입니다.', 'Are we done? I can smell the weekend.', '끝났어요? 주말 냄새가 나는데.', 'Not quite. Sum up who''s doing what: you take the ticket template, Derek takes the refund tests.', '아직입니다. 누가 무엇을 하는지 정리하세요. 티켓 양식은 당신이, 환불 테스트는 데릭이 맡습니다.', '[{"all":["action items"]},{"all":["recap"]}]', 'Almost. Let''s recap the action items: I own the ticket template, and Derek adds tests for refunds.', '거의요. 액션 아이템을 정리하죠. 티켓 양식은 제가 맡고, 환불 테스트는 데릭이 추가해요.', '["Almost. Let''s recap the action items: Derek owns the ticket template, and I add tests for refunds.","Almost. Quick recap: Jun owns the ticket template, and Derek rewrites the retry library.","Yep, we''re done here. Have a great weekend, everyone, and thanks for coming!"]', '["거의요. 액션 아이템을 정리하죠. 티켓 양식은 데릭이 맡고, 환불 테스트는 제가 추가해요.","거의요. 짧게 정리하면, 티켓 양식은 준이 맡고, 재시도 라이브러리는 데릭이 다시 짜요.","네, 다 끝났어요. 다들 주말 잘 보내요. 오늘 와 줘서 정말 고마워요!"]', '["Wait, I''m on the template? I thought that was yours.","The retry library? I thought we parked that.","Hang on. Don''t we usually go over the action items?"]', '["잠깐, 양식을 제가요? 그건 프리야 거 아니었어요?","재시도 라이브러리요? 그건 미뤄 둔 줄 알았는데요.","잠깐만요. 보통 액션 아이템은 정리하고 끝내지 않아요?"]', '["End with who does what: the \\"action items\\".","Key words: recap, action items, I own"]', '["누가 무엇을 하는지, 즉 action items로 마무리하세요.","핵심 단어: recap, action items, I own"]', 'derek', 'On it. And we''re done two minutes early!', '맡을게요. 그리고 2분 일찍 끝났네요!'),
  ('pr_d5_happy_hour', 1, 'derek', 'Friday afternoon. The sky is clear and half the office is already looking at the door.', '금요일 오후입니다. 하늘은 맑고, 사무실 사람 절반은 벌써 문 쪽을 보고 있습니다.', 'Hey, a bunch of us are going to happy hour at the Anchor after work. You in?', '저기, 퇴근하고 몇 명이서 앵커로 해피 아워 가요. 같이 갈래요?', 'You''d like to go, but you owe the client an update first.', '가고 싶지만, 그 전에 고객에게 진행 상황을 보내야 합니다.', '[{"any":["i am in","count me in","i will be there","love to"]}]', 'I''m in! I just need to send the client an update first.', '갈래요! 먼저 고객한테 진행 상황만 보내고요.', '["I can''t, sorry. I need to send the client an update first.","I''m in! Could you send the client update for me, though?","I''m in! I just need to finish the gift card fix first."]', '["미안해요, 못 가요. 고객한테 먼저 보낼 게 있어서요.","갈래요! 그런데 고객 업데이트는 데릭이 대신 보내 줄래요?","갈래요! 기프트 카드 수정만 먼저 끝내고요."]', '["Aw, come on. It''s Friday. It can''t wait an hour?","Ha. Nice try. That one''s all yours.","You''re fixing gift cards? Since when do you write code?"]', '["에이, 왜요. 금요일인데. 한 시간도 못 기다려요?","하. 그렇게는 안 되죠. 그건 프리야 일이에요.","기프트 카드를 프리야가 고쳐요? 언제부터 코드 짰어요?"]', '["Answer \\"You in?\\" with \\"I''m in!\\"","Key words: I''m in, send the client an update"]', '["\\"You in?\\"에는 \\"I''m in!\\"으로 답합니다.","핵심 단어: I''m in, send the client an update"]', 'derek', 'Nice. We''re heading out at five thirty.', '좋아요. 우리는 다섯 시 반에 나가요.'),
  ('pr_d5_happy_hour', 2, 'derek', 'The update to Greg will take a while.', '그렉에게 보낼 글은 시간이 좀 걸릴 것 같습니다.', 'It''s perfect patio weather, so we''ll be outside.', '테라스에 앉기 딱 좋은 날씨라서 밖에 있을 거예요.', 'Warn him you''ll be a bit behind everyone, and ask him to hold a spot for you.', '다른 사람들보다 조금 늦을 거라고 미리 말하고, 자리를 맡아 달라고 하세요.', '[{"any":["save me","few minutes late","running late","a little late","catch up"]}]', 'I might be a few minutes late. Save me a seat?', '몇 분 늦을 수도 있어요. 자리 좀 맡아 줄래요?', '["I might be a couple of hours late. Start without me.","Outside? Could we sit inside instead? I get cold.","Grab me the best table, and order for me, too."]', '["두어 시간 늦을 수도 있어요. 먼저 시작해요.","밖이요? 안에 앉으면 안 돼요? 저 추위 타요.","제일 좋은 자리 잡아 두고, 주문도 해 놔요."]', '["A couple of hours? We''ll be gone by then.","Inside? It''s seventy degrees and sunny, Priya.","Order for you? I don''t even know what you drink."]', '["두어 시간이요? 그땐 우리 다 가고 없어요.","안에요? 21도에 화창한데요, 프리야.","주문까지요? 뭐 마시는지도 모르는데요."]', '["\\"I might be …\\" is softer than \\"I will be …\\".","Key words: a few minutes late, save me a seat"]', '["\\"I might be …\\"는 \\"I will be …\\"보다 부드럽습니다.","핵심 단어: a few minutes late, save me a seat"]', 'derek', 'You got it. Best seat on the patio.', '그럼요. 테라스에서 제일 좋은 자리로요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d5_happy_hour', 3, 'derek', 'Derek nods toward Jun''s empty chair.', '데릭이 준의 빈 의자 쪽으로 고개를 끄덕입니다.', 'I asked Jun, too, but he''s wiped out. He took a rain check.', '준한테도 물어봤는데, 완전히 녹초래요. 다음에 오겠대요.', 'Jun is worn out. Say you understand, and say something nice about his week.', '준은 지쳤습니다. 이해한다고 하고, 그의 한 주에 대해 좋은 말을 해 주세요.', '[{"any":["no wonder","great first week","did great","great job","great week"]}]', 'No wonder. He had a great first week.', '그럴 만하죠. 첫 주를 정말 잘 보냈잖아요.', '["Really? It''s his first happy hour, though.","No wonder. He worked all weekend, too.","Oh no, is it supposed to rain tonight?"]', '["정말요? 그래도 첫 해피 아워인데요.","그럴 만하죠. 주말 내내 일했잖아요.","어머, 오늘 밤에 비 온대요? 몰랐네요."]', '["Come on. The guy''s earned a quiet night.","The weekend? It hasn''t even started yet.","Ha, no. It means he''ll come next time."]', '["에이. 조용한 밤 보낼 자격은 있죠.","주말이요? 아직 시작도 안 했는데요.","하, 아뇨. 다음에 온다는 뜻이에요."]', '["\\"No wonder\\" = that is not surprising.","Key words: no wonder, a great first week"]', '["\\"No wonder\\"는 놀랄 일이 아니라는 뜻입니다.","핵심 단어: no wonder, a great first week"]', 'derek', 'He really did. Flagging that bug early saved us.', '정말 그래요. 그 버그를 일찍 알려 준 덕에 살았죠.'),
  ('pr_d5_happy_hour', 4, 'derek', 'Derek gets a little serious for a moment.', '데릭이 잠깐 진지해집니다.', 'By the way, thanks for handling the client yesterday. That could have gone badly.', '그나저나, 어제 고객 응대해 줘서 고마워요. 잘못하면 일 커질 뻔했어요.', 'Accept the thanks, and give him credit for the part he played.', '고맙다는 말을 받고, 데릭이 맡은 역할을 인정해 주세요.', '[{"any":["could not have","means a lot","team effort","without you"]}]', 'Thanks, that means a lot. I couldn''t have done it without you pairing with Jun.', '고마워요, 그 말 정말 힘이 되네요. 데릭이 준이랑 같이 작업해 주지 않았으면 못 했을 거예요.', '["Thanks, that means a lot. I couldn''t have done it without Maya on the call.","Oh, it was nothing. Greg''s easy to handle if you know how to play him.","Thanks. Honestly, I was terrified Greg would yell at me the whole time we talked."]', '["고마워요, 그 말 정말 힘이 되네요. 통화에 마야가 같이 있어 주지 않았으면 못 했을 거예요.","에이, 별거 아니었어요. 그렉 같은 사람은 어떻게 다뤄야 하는지만 알면 쉬워요.","고마워요. 솔직히 통화 내내 그렉이 소리 지를까 봐 무서워 죽는 줄 알았어요."]', '["Maya? I didn''t know she was on the call.","Huh. Didn''t sound that easy from where I sat.","Ha. Well, you didn''t sound it. You were great."]', '["마야요? 마야가 통화에 있었는지 몰랐네요.","흠. 제가 보기엔 그렇게 쉬워 보이진 않던데요.","하. 전혀 그렇게 안 들렸어요. 잘했어요."]', '["Accept the compliment, then share the credit.","Key words: that means a lot, couldn''t have done it without you"]', '["칭찬을 받아들인 뒤 공을 나누세요.","핵심 단어: that means a lot, couldn''t have done it without you"]', 'derek', 'Team effort. Okay, enough of that.', '다 같이 한 거죠. 자, 이런 얘기는 그만하고.'),
  ('pr_d5_happy_hour', 5, 'derek', 'He grabs his jacket off the chair.', '데릭이 의자에 걸린 재킷을 집어 듭니다.', 'First round''s on me.', '첫 잔은 제가 살게요.', 'Insist on buying the first drinks yourself. He deserves it.', '첫 잔은 당신이 사겠다고 우기세요. 데릭은 그럴 만합니다.', '[{"any":["on me","my treat","i am buying","i will get"]}]', 'No way. The first round is on me. You earned it.', '무슨 소리예요. 첫 잔은 제가 살게요. 데릭이 고생했잖아요.', '["Great, thanks! Then I''ll get the second round.","No way. You''re buying all night. You owe me.","No way. The first round''s on Jun. He earned it."]', '["좋아요, 고마워요! 그럼 두 번째는 제가 살게요.","무슨 소리예요. 오늘은 밤새 데릭이 사요. 저한테 빚졌잖아요.","무슨 소리예요. 첫 잔은 준이 사야죠. 준이 고생했잖아요."]', '["Ha. Deal. But I''m holding you to it.","Owe you? For what, exactly?","Jun''s not even coming, remember?"]', '["하. 좋아요. 그 말 꼭 지켜요.","빚졌다고요? 정확히 뭘요?","준은 안 온다잖아요, 기억 안 나요?"]', '["\\"It''s on me\\" = I will pay.","Key words: the first round is on me, you earned it"]', '["\\"It''s on me\\"는 내가 사겠다는 뜻입니다.","핵심 단어: the first round is on me, you earned it"]', 'derek', 'I won''t argue with that. See you at the Anchor!', '그건 사양 안 할게요. 앵커에서 봐요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_coffee', 1, 'nina', 'Monday morning. The fog on Lake Avenue is so thick that you hear Nina''s cart before you see it.', '월요일 아침입니다. 레이크 애비뉴에 안개가 짙어서 니나의 카트는 보이기 전에 소리부터 들립니다.', 'Morning, Priya! Can you believe this fog? I almost walked right past my own cart.', '좋은 아침이에요, 프리야! 이 안개 좀 봐요. 제 카트를 지나칠 뻔했다니까요.', 'Agree with her, and pass on the forecast: it should clear up around midday.', '맞장구치고, 일기예보를 전해 주세요. 한낮쯤이면 걷힌다고 합니다.', '[{"any":["barely see","burn off","burns off","hardly see"]}]', 'I know! I could barely see across the street. It''s supposed to burn off by noon.', '그러니까요! 길 건너편이 거의 안 보였어요. 정오쯤이면 걷힌대요.', '["I know! I could barely see across the street. It''s supposed to last all week.","Really? It wasn''t that bad by my place. I could see all the way down the block, easy.","Ugh, don''t. I hate fog. It makes me want to crawl back into bed all day."]', '["그러니까요! 길 건너편이 거의 안 보였어요. 일주일 내내 이렇대요.","그래요? 저희 집 쪽은 별로 안 심했어요. 블록 끝까지 다 보이던데요.","아, 말도 마요. 안개 너무 싫어요. 하루 종일 침대로 돌아가고 싶어져요."]', '["All week? Oh, don''t say that. I''ll lose all my customers.","Really? You must live on the sunny side of town.","Ha. Me too. But somebody''s got to make the coffee."]', '["일주일 내내요? 아, 그런 말 마요. 손님 다 끊기겠어요.","정말요? 동네에서 해 드는 쪽에 사나 봐요.","하. 저도요. 그래도 커피는 누군가 만들어야죠."]', '["Fog does not \\"go away\\". It \\"burns off\\" when the sun comes out.","Key words: barely see, supposed to, burn off by noon"]', '["안개는 해가 나면 burn off한다고 말합니다.","핵심 단어: barely see, supposed to, burn off by noon"]', 'nina', 'Let''s hope so. Nobody can find me in this.', '그러길 바라야죠. 이래서는 아무도 저를 못 찾아요.'),
  ('pr_d8_coffee', 2, 'nina', 'You have a kickoff call at eleven, and Derek is running the demo. He could use a coffee, too.', '열한 시에 킥오프 콜이 있고, 데모는 데릭이 맡습니다. 데릭에게도 커피가 필요할 것 같습니다.', 'So, the usual? Medium oat latte, extra shot?', '늘 마시던 걸로요? 귀리 우유 라테 미디엄, 샷 추가?', 'Big day: you want more than usual for yourself, plus a plain brewed coffee for Derek.', '중요한 날입니다. 당신 것은 평소보다 크게, 그리고 데릭에게 줄 평범한 커피도 하나 주문하세요.', '[{"any":["large","coworker","colleague","drip coffee"]}]', 'Yes, but make it a large today. And a drip coffee for my coworker, please.', '네, 그런데 오늘은 큰 컵으로요. 그리고 동료 줄 드립 커피도 하나 주세요.', '["Yes, but make it a small today. And a drip coffee for my coworker, please.","Yes, but make it a large today. And another oat latte for my coworker.","No, something different today. Surprise me, and one for my coworker."]', '["네, 그런데 오늘은 작은 컵으로요. 그리고 동료 줄 드립 커피도 하나 주세요.","네, 그런데 오늘은 큰 컵으로요. 그리고 동료 줄 귀리 라테도 하나 더요.","아뇨, 오늘은 다른 걸로요. 알아서 해 주시고, 동료 것도 하나요."]', '["A small? On a day like this?","Two oat lattes? Does your coworker even like oat milk?","Surprise you? Okay... and what for your coworker?"]', '["작은 컵이요? 이런 날에요?","귀리 라테 두 잔이요? 동료분도 귀리 우유 좋아해요?","알아서요? 음... 그럼 동료분 건 뭘로요?"]', '["Change your usual order with \\"make it a …\\", then add one more drink.","Key words: make it a large, a drip coffee, for my coworker"]', '["\\"make it a …\\"로 평소 주문을 바꾸고, 음료를 하나 더 주문하세요.","핵심 단어: make it a large, a drip coffee, for my coworker"]', 'nina', 'One large oat latte, one drip. Does your coworker take cream or sugar?', '귀리 우유 라테 큰 컵 하나, 드립 하나. 동료분은 크림이나 설탕 넣어요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_coffee', 3, 'nina', 'Good question. You have no idea how Derek takes his coffee.', '좋은 질문입니다. 데릭이 커피를 어떻게 마시는지 전혀 모릅니다.', 'Cream? Sugar? Both?', '크림? 설탕? 둘 다?', 'You don''t know how Derek takes it. Cover both possibilities.', '데릭이 커피를 어떻게 마시는지 모릅니다. 두 경우 다 대비하세요.', '[{"any":["room for cream","leave room","just in case","sugar packets"]}]', 'I''m not sure. Could you leave room for cream? I''ll grab some sugar packets just in case.', '잘 모르겠어요. 크림 넣을 자리 좀 남겨 주실래요? 혹시 모르니 설탕 봉지도 몇 개 챙길게요.', '["Both, I think. Lots of cream and three sugars, please. He''ll love that.","I''m not sure. Black, I guess. If he doesn''t like it, that''s on him.","No cream, just sugar, please. Derek told me he always takes two sugars in his coffee."]', '["둘 다요, 아마. 크림 듬뿍에 설탕 세 개 넣어 주세요. 좋아할 거예요.","잘 모르겠어요. 그냥 블랙으로요. 마음에 안 들면 본인 사정이죠, 뭐.","크림은 빼고 설탕만 넣어 주세요. 데릭이 늘 커피에 설탕 두 개 넣는다고 했거든요."]', '["You sure? That''s a lot of sugar if you''re just guessing.","Ha, cold. Hope he likes it black, then.","Two sugars it is. Stirred in?"]', '["정말요? 짐작으로 넣기엔 설탕이 너무 많은데요.","하, 냉정하네. 블랙 좋아하길 바라야겠네요.","설탕 두 개요. 저어 드릴까요?"]', '["\\"Room for cream\\" means the cup is not filled to the top.","Key words: leave room for cream, sugar packets, just in case"]', '["\\"room for cream\\"은 컵을 끝까지 채우지 않고 자리를 남긴다는 뜻입니다.","핵심 단어: leave room for cream, sugar packets, just in case"]', 'nina', 'Smart. Room for cream it is.', '현명하네요. 크림 자리 남겨 둘게요.'),
  ('pr_d8_coffee', 4, 'nina', 'Two hot cups, a laptop bag and an umbrella. You only have two hands.', '뜨거운 컵 두 개에 노트북 가방과 우산까지. 손은 둘뿐입니다.', 'Here you go. How are you going to carry all that?', '여기요. 그걸 다 어떻게 들고 가려고요?', 'Your hands are full. Ask for something to hold both cups.', '손이 꽉 찼습니다. 컵 두 개를 담을 것을 달라고 하세요.', '[{"any":["carrier","drink tray","cup holder"]}]', 'Good question. Could I get a drink carrier?', '그러게요. 음료 캐리어 하나 주실래요?', '["Easy. I''ll just stack one cup on top of the other.","No idea. Could you walk them over for me?","Good question. Could I get lids for these?"]', '["간단해요. 컵 하나를 다른 컵 위에 얹으면 돼요.","모르겠어요. 사무실까지 좀 갖다주실래요?","그러게요. 컵 뚜껑 좀 주실래요?"]', '["Stack them? With hot coffee? Please don''t.","Ha. I''d love to, but who''d run the cart?","They''ve got lids. It''s your hands I''m worried about."]', '["쌓는다고요? 뜨거운 커피를? 제발 그러지 마요.","하. 그러고 싶지만 카트는 누가 봐요?","뚜껑은 있어요. 걱정되는 건 손이에요."]', '["The cardboard tray that holds several cups is a \\"drink carrier\\".","Key words: could I get, a drink carrier"]', '["컵 여러 개를 담는 종이 받침을 drink carrier라고 합니다.","핵심 단어: could I get, a drink carrier"]', 'nina', 'Sure thing. That''s eight fifty, so nine twenty with tax.', '그럼요. 8달러 50센트니까, 세금 포함해서 9달러 20센트예요.'),
  ('pr_d8_coffee', 5, 'nina', 'You tap your card. Nina looks you up and down.', '카드를 갖다 댑니다. 니나가 당신을 위아래로 훑어봅니다.', 'You''ve got your game face on. Big meeting?', '비장한 얼굴인데요. 큰 회의 있어요?', 'Tell her about the big client call later this morning, and ask for her good wishes.', '오늘 오전에 있을 중요한 고객 통화 얘기를 하고, 응원해 달라고 하세요.', '[{"any":["kicking off","kick off","kickoff","wish me luck"]}]', 'We''re kicking off a new project with a client at eleven. Wish me luck!', '열한 시에 고객이랑 새 프로젝트를 시작해요. 행운을 빌어 줘요!', '["We''re kicking off a new project with a client at two today. Wish me luck!","Ugh, yes. If this call goes badly, I might lose the whole account.","Not really. Just a regular Monday with the same old meetings."]', '["오늘 두 시에 고객이랑 새 프로젝트를 시작해요. 행운을 빌어 줘요!","아, 네. 이 통화 망치면 고객사를 통째로 잃을지도 몰라요.","아뇨. 늘 똑같은 회의만 있는 평범한 월요일이에요."]', '["At two? Then why the game face this early?","Whoa. No pressure, huh? You''ll be fine.","Really? You look like you''re heading into battle."]', '["두 시요? 그런데 아침부터 왜 그렇게 비장해요?","와. 부담 엄청나겠네요. 잘될 거예요.","정말요? 전쟁하러 가는 사람 같은데요."]', '["\\"To kick off\\" a project is to start it, usually with a meeting.","Key words: kicking off, a new project, wish me luck"]', '["프로젝트를 kick off한다는 것은 보통 회의를 열어 시작한다는 뜻입니다.","핵심 단어: kicking off, a new project, wish me luck"]', 'nina', 'You don''t need luck. But good luck! Careful, they''re hot.', '프리야는 운이 필요 없죠. 그래도 행운을 빌어요! 뜨거우니까 조심하고요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_kickoff', 1, 'greg', 'Eleven o''clock. The fog has lifted. Greg Whitfield appears on the big screen with two people beside him.', '열한 시입니다. 안개가 걷혔습니다. 큰 화면에 그렉 휫필드가 두 사람과 함께 나타납니다.', 'Morning, Priya. I''ve got my team here, and a hard stop at noon.', '안녕하세요, 프리야. 우리 팀도 같이 왔고, 정오에는 반드시 끝내야 합니다.', 'Show you value their time, and get everyone to say who they are.', '시간을 내 준 데 감사를 표하고, 모두가 누구인지 소개하게 하세요.', '[{"any":["introductions","making the time","introduce ourselves"]}]', 'Thanks for making the time, everyone. Let''s do a quick round of introductions.', '모두 시간 내 주셔서 감사합니다. 짧게 돌아가면서 소개부터 하죠.', '["Thanks, Greg. Before we start, let me walk you all through our company''s history.","Thanks for making the time, everyone. Let''s go until one, if that''s okay.","Great. Let''s skip the introductions and jump right into the demo."]', '["감사합니다, 그렉. 시작하기 전에 저희 회사 연혁부터 소개해 드릴게요.","모두 시간 내 주셔서 감사합니다. 괜찮으시면 한 시까지 하죠.","좋습니다. 소개는 건너뛰고 바로 데모로 들어가죠."]', '["Priya, I said a hard stop. Let''s keep it moving.","One? I said noon. I meant it.","My team''s never met yours. Let''s at least do names."]', '["프리야, 시간이 정해져 있다고 했습니다. 빨리 진행하죠.","한 시요? 정오라고 했습니다. 진심이에요.","우리 팀은 그쪽 팀을 처음 봅니다. 이름 정도는 알고 시작하죠."]', '["Thank them, then ask everyone to say who they are.","Key words: thanks for making the time, a quick round of introductions"]', '["고맙다고 한 뒤, 저마다 자신을 소개하게 하세요.","핵심 단어: thanks for making the time, a quick round of introductions"]', 'greg', 'Sure. I''m Greg, VP of operations. With me are Dana from IT and Luis from finance.', '그러죠. 저는 운영 담당 부사장 그렉입니다. 옆에는 IT의 데이나와 재무의 루이스가 있습니다.'),
  ('pr_d8_kickoff', 2, 'greg', 'Derek and Jun sit on either side of you.', '데릭과 준이 당신의 양옆에 앉아 있습니다.', 'And who do we have on your side?', '그쪽은 누가 나와 계십니까?', 'Introduce your two colleagues and their roles. Jun will build most of the dashboard.', '두 동료와 각자의 역할을 소개하세요. 대시보드는 대부분 준이 만듭니다.', '[{"any":["on our side","senior developer","building most"]}]', 'On our side, this is Derek, our senior developer, and Jun, who''ll be building most of the dashboard.', '저희 쪽은 시니어 개발자 데릭, 그리고 대시보드 대부분을 만들 준입니다.', '["On our side, this is Jun, our senior developer, and Derek, who''ll be building most of the dashboard.","On our side, this is Derek, our senior developer, and Jun. He''s new, so go easy on him.","On our side, this is Derek, our senior developer, and Jun, from our finance team."]', '["저희 쪽은 시니어 개발자 준, 그리고 대시보드 대부분을 만들 데릭입니다.","저희 쪽은 시니어 개발자 데릭, 그리고 준입니다. 신입이니 살살 대해 주세요.","저희 쪽은 시니어 개발자 데릭, 그리고 재무팀의 준입니다."]', '["Jun''s your senior developer? I thought that was Derek.","Noted. Let''s hope the dashboard isn''t new to him.","Finance? I thought he was one of your developers."]', '["준이 시니어 개발자입니까? 데릭인 줄 알았는데요.","알겠습니다. 대시보드까지 처음은 아니길 바랍니다.","재무요? 개발자인 줄 알았습니다."]', '["Name, then role: \\"This is …, our …\\".","Key words: on our side, this is, our senior developer, building the dashboard"]', '["이름을 말하고 역할을 덧붙이세요. \\"This is …, our …\\".","핵심 단어: on our side, this is, our senior developer, building the dashboard"]', 'jun', 'Hi, Greg. Nice to meet you. I''m looking forward to working with you.', '안녕하세요, 그렉. 만나서 반갑습니다. 함께 일하게 되어 기대됩니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_kickoff', 3, 'greg', 'Greg looks at his watch. One hour, no more.', '그렉이 시계를 봅니다. 주어진 시간은 딱 한 시간입니다.', 'Likewise. So what''s the plan for the hour?', '저도요. 그럼 한 시간 동안 어떻게 진행합니까?', 'Lay out the hour, following the plan you gave your team, with the dashboard part about what he wants.', '팀에게 말한 계획대로 한 시간 일정을 알려 주세요. 대시보드 부분은 그렉이 원하는 것 중심으로요.', '[{"any":["agenda","three items","three things"]}]', 'We have three items on the agenda: the checkout demo, your goals for the dashboard, and next steps.', '안건은 세 가지입니다. 결제 화면 데모, 대시보드에 대한 그렉의 목표, 그리고 다음 단계입니다.', '["We have three items on the agenda: the checkout demo, pricing for the dashboard, and then next steps.","Well, it depends. We could do the demo, or talk dashboard, or whatever you''d like to start with.","We have three items on the agenda: the gift card demo, the mobile app, and a date for launch."]', '["안건은 세 가지입니다. 결제 화면 데모, 대시보드 가격, 그리고 다음 단계입니다.","글쎄요, 상황 봐서요. 데모를 해도 되고, 대시보드 얘기를 해도 되고, 원하시는 걸로 하죠.","안건은 세 가지입니다. 기프트 카드 데모, 모바일 앱, 그리고 출시 날짜입니다."]', '["Pricing? Luis will be thrilled, but I thought this was a kickoff.","Priya, you called the meeting. You tell me.","Gift cards? I thought I was seeing the new checkout."]', '["가격이요? 루이스는 좋아하겠지만, 오늘은 킥오프 아닙니까?","프리야, 회의를 잡은 건 그쪽입니다. 그쪽이 정해 주세요.","기프트 카드요? 새 결제 화면을 보는 줄 알았는데요."]', '["Say how many items there are, then list them.","Key words: three items on the agenda, demo, goals, next steps"]', '["안건이 몇 개인지 말한 뒤 하나씩 말하세요.","핵심 단어: three items on the agenda, demo, goals, next steps"]', 'greg', 'Works for me. Show me the demo.', '좋습니다. 데모를 보여 주세요.'),
  ('pr_d8_kickoff', 4, 'greg', 'Derek''s demo of the new checkout runs without a hitch. Greg''s team claps.', '데릭의 새 결제 화면 데모가 매끄럽게 끝납니다. 그렉의 팀이 박수를 칩니다.', 'Nice. My team loved it. Now, the dashboard. Where do you want to start?', '좋네요. 우리 팀이 아주 좋아했습니다. 이제 대시보드죠. 어디서부터 시작할까요?', 'Before any features, find out what he wants to have achieved half a year from now.', '기능 얘기 전에, 반년 뒤에 그가 무엇을 이뤄 놓고 싶은지 알아보세요.', '[{"all":["success"]}]', 'Let''s start with the goal. What does success look like for you six months from now?', '목표부터 시작하죠. 6개월 뒤에 어떤 모습이면 성공이라고 보십니까?', '["Let''s start with the features. Which screens do you want on the dashboard first?","Let''s start with the goal. What does success look like for you six weeks from now?","Let''s start with the budget. How much are you planning to spend on this one?"]', '["기능부터 시작하죠. 대시보드에 어떤 화면부터 넣고 싶으세요?","목표부터 시작하죠. 6주 뒤에 어떤 모습이면 성공이라고 보십니까?","예산부터 시작하죠. 이번 건에 얼마나 쓰실 계획이세요?"]', '["Screens? Let me tell you the problem first.","Six weeks? We''re thinking bigger than that.","Money already? Let''s see what we''re building first."]', '["화면이요? 문제부터 말씀드리죠.","6주요? 우리는 그보다 크게 보고 있습니다.","벌써 돈 얘기요? 뭘 만들지부터 봅시다."]', '["Do not ask about features first. Ask what a good result would be.","Key words: what does success look like, six months from now"]', '["기능부터 묻지 말고, 어떤 결과가 나오면 좋은지 물어보세요.","핵심 단어: what does success look like, six months from now"]', 'greg', 'Simple. Our store managers are flying blind. I want live inventory for all forty stores on one screen.', '간단합니다. 우리 매장 관리자들은 정보 없이 감으로 일하고 있어요. 40개 매장의 실시간 재고를 한 화면에서 보고 싶습니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_kickoff', 5, 'greg', 'Jun asks how the stores send their data and explains that nightly files will not be enough. Greg nods.', '준이 매장에서 데이터를 어떻게 보내는지 묻고, 밤마다 올리는 파일로는 부족하다고 설명합니다. 그렉이 고개를 끄덕입니다.', 'Fine. You''ll have API access by Wednesday. What else do you need from me?', '좋습니다. 수요일까지 API 접근 권한을 드리죠. 그 밖에 저한테 필요한 게 있습니까?', 'Ask for one person on his team who can make calls, so nothing stalls.', '일이 멈추지 않도록, 그쪽 팀에서 결정할 수 있는 사람 한 명을 정해 달라고 하세요.', '[{"any":["point of contact","one person","decision maker"]}]', 'One thing: a single point of contact on your side, so decisions don''t get stuck.', '한 가지요. 결정이 막히지 않도록 그쪽에서 담당자 한 분을 정해 주세요.', '["One thing: API access by Friday, so the team isn''t stuck waiting around.","One thing: we''ll need you personally on every call, so that decisions don''t stall.","One thing: your sign-off on a November launch date, so we can plan around it."]', '["한 가지요. 팀이 기다리지 않도록 API 접근 권한을 금요일까지 주세요.","한 가지요. 결정이 막히지 않도록 매번 통화에 그렉이 직접 들어와 주세요.","한 가지요. 저희가 계획을 세울 수 있게 11월 출시 날짜를 승인해 주세요."]', '["Friday? I just said Wednesday.","Every call? I run operations for forty stores, Priya.","A date already? Let''s see the scope first."]', '["금요일이요? 방금 수요일이라고 했습니다.","매번이요? 저는 매장 40곳 운영을 맡고 있습니다, 프리야.","벌써 날짜요? 범위부터 봅시다."]', '["Ask for one person who can answer questions and say yes or no.","Key words: a single point of contact, on your side, decisions"]', '["질문에 답하고 결정을 내려 줄 수 있는 사람 한 명을 부탁하세요.","핵심 단어: a single point of contact, on your side, decisions"]', 'greg', 'That''s Dana. She has the authority to say yes or no.', '데이나가 맡을 겁니다. 결정할 권한이 있어요.'),
  ('pr_d8_kickoff', 6, 'greg', 'The clock says 11:55. Greg starts to gather his papers.', '시계가 11시 55분을 가리킵니다. 그렉이 서류를 챙기기 시작합니다.', 'Five minutes. Where does that leave us?', '5분 남았습니다. 그래서 정리하면요?', 'Repeat back what you agreed on. One more thing was set: the scope talk is tomorrow at ten thirty.', '합의한 내용을 되짚어 말하세요. 하나 더 정해진 게 있습니다. 범위 논의는 내일 10시 30분입니다.', '[{"any":["play that back","play it back"]},{"all":["wednesday","tomorrow"]}]', 'Let me play that back: API access by Wednesday, Dana is our point of contact, and we talk scope tomorrow at ten thirty.', '정리해 보겠습니다. 수요일까지 API 접근 권한, 담당자는 데이나, 범위 논의는 내일 10시 30분입니다.', '["Let me play that back: API access by Wednesday, Luis is our point of contact, and we talk scope tomorrow at ten thirty.","Let me play that back: API access by Friday, Dana is our point of contact, and we talk scope next week at ten thirty.","Great call, everyone. We''ll get started today, and you''ll have the whole dashboard by the end of the year."]', '["정리해 보겠습니다. 수요일까지 API 접근 권한, 담당자는 루이스, 범위 논의는 내일 10시 30분입니다.","정리해 보겠습니다. 금요일까지 API 접근 권한, 담당자는 데이나, 범위 논의는 다음 주 10시 30분입니다.","좋은 회의였습니다. 오늘 바로 시작해서 연말까지 대시보드 전체를 드리겠습니다."]', '["Luis? No, Dana''s your contact. Luis is finance.","Wednesday, and tomorrow. Write it down, Priya.","End of the year? We haven''t even talked scope."]', '["루이스요? 아뇨, 담당자는 데이나입니다. 루이스는 재무예요.","수요일, 그리고 내일입니다. 적어 두세요, 프리야.","연말이요? 범위 얘기도 아직 안 했습니다."]', '["\\"Play it back\\" = repeat what was agreed so that everyone hears the same thing.","Key words: let me play that back, by Wednesday, point of contact, tomorrow at ten thirty"]', '["play it back은 합의한 내용을 되짚어 모두가 같은 내용을 듣게 하는 것입니다.","핵심 단어: let me play that back, by Wednesday, point of contact, tomorrow at ten thirty"]', 'greg', 'That''s it. And one minute early. Talk tomorrow.', '맞습니다. 게다가 1분 일찍 끝났네요. 내일 이야기합시다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_prep', 1, 'derek', 'Standup is at nine thirty this week to make room for the client calls. Afterwards Derek and Jun roll their chairs over.', '고객 통화 시간을 내려고 이번 주 스탠드업은 9시 30분입니다. 끝난 뒤 데릭과 준이 의자를 끌고 옵니다.', 'So, eleven o''clock with Summit Retail. What''s the plan?', '그래서, 열한 시에 서밋 리테일이랑. 계획이 뭐예요?', 'Walk them through the order of the call: the checkout demo, then the dashboard project, then next steps.', '통화 순서를 알려 주세요. 결제 화면 데모, 대시보드 프로젝트, 그리고 다음 단계 순입니다.', '[{"any":["game plan","demo first"]},{"all":["demo","dashboard"]}]', 'Here''s the game plan: the checkout demo first, then the dashboard project, then next steps.', '계획은 이래요. 먼저 결제 화면 데모, 다음은 대시보드 프로젝트, 그다음은 다음 단계예요.', '["Here''s the game plan: the dashboard project first, then the checkout demo, then pricing.","Honestly, I thought we''d just wing it and see what Greg wants to talk about.","Here''s the game plan: the gift card demo first, then the mobile app, and then next steps."]', '["계획은 이래요. 먼저 대시보드 프로젝트, 다음은 결제 화면 데모, 그다음은 가격 얘기예요.","솔직히 그냥 그때그때 대응하면서 그렉이 무슨 얘기를 하고 싶은지 보려고 했어요.","계획은 이래요. 먼저 기프트 카드 데모, 다음은 모바일 앱, 그리고 그다음은 다음 단계예요."]', '["Dashboard first? Shouldn''t we warm them up with the demo?","Wing it? With Greg? That''s brave.","Gift cards? I thought I was demoing the new checkout."]', '["대시보드부터요? 데모로 분위기부터 띄워야 하지 않아요?","즉흥으로요? 그렉 상대로? 용감하네요.","기프트 카드요? 저는 새 결제 화면을 데모하는 줄 알았는데요."]', '["A \\"game plan\\" is the plan for how you will handle something. Give three steps.","Key words: game plan, the checkout demo first, then, next steps"]', '["game plan은 일을 어떻게 풀어 갈지에 대한 계획입니다. 세 단계로 말하세요.","핵심 단어: game plan, the checkout demo first, then, next steps"]', 'derek', 'Short and sweet. I like it.', '짧고 분명하네요. 마음에 들어요.'),
  ('pr_d8_prep', 2, 'derek', 'Three people on one call. Everyone needs a job.', '한 통화에 세 사람이 들어갑니다. 저마다 맡을 일이 있어야 합니다.', 'So who''s doing what?', '그럼 누가 뭘 해요?', 'Hand out the roles: Derek shows the demo, Jun handles the technical questions, and you start and wrap up the call.', '역할을 나누세요. 데모는 데릭, 기술 질문은 준, 통화의 시작과 마무리는 당신입니다.', '[{"any":["technical questions","open and close","run the demo"]}]', 'Derek, you run the demo. Jun, you take the technical questions. I''ll open and close.', '데릭은 데모를 맡아 줘요. 준은 기술 질문을 받아 주고요. 시작과 마무리는 제가 할게요.', '["Jun, you run the demo. Derek, you take the technical questions. I''ll open and close.","I''ll do all the talking. You two just stay on mute unless I call on you.","Derek, you run the demo. Jun, you handle pricing. I''ll open and close the call."]', '["준은 데모를 맡아 줘요. 데릭은 기술 질문을 받아 주고요. 시작과 마무리는 제가 할게요.","말은 제가 다 할게요. 두 사람은 제가 부를 때까지 음소거하고 있어요.","데릭은 데모를 맡아 줘요. 준은 가격 얘기를 맡고요. 시작과 마무리는 제가 할게요."]', '["Jun on the demo? It''s his first client call, Priya.","On mute? Then why are we even on the call?","Jun on pricing? He''s been here two weeks."]', '["준이 데모를요? 고객이랑 처음 하는 통화예요, 프리야.","음소거요? 그럼 우리가 왜 들어가요?","준이 가격을요? 온 지 2주밖에 안 됐는데요."]', '["Give each person one job: \\"You run …\\", \\"You take …\\", \\"I''ll …\\".","Key words: you run the demo, you take the technical questions, I''ll open and close"]', '["사람마다 일을 하나씩 주세요. \\"You run …\\", \\"You take …\\", \\"I''ll …\\".","핵심 단어: you run the demo, you take the technical questions, I''ll open and close"]', 'jun', 'Technical questions. Okay. But what if Greg asks something I can''t answer?', '기술 질문이요. 알겠습니다. 그런데 그렉이 제가 대답 못 할 걸 물으면요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d8_prep', 3, 'jun', 'It is Jun''s first call with a client. He is turning his pen over and over.', '준에게는 고객과의 첫 통화입니다. 펜을 자꾸 돌리고 있습니다.', 'I don''t want to make something up and get it wrong.', '괜히 지어냈다가 틀리고 싶지 않아요.', 'Jun is afraid of guessing wrong. Give him an honest line he can fall back on.', '준은 잘못 짐작해서 틀릴까 봐 걱정합니다. 기댈 수 있는 솔직한 한마디를 알려 주세요.', '[{"any":["find out","look into it"]}]', 'Then say, "I don''t know, but I''ll find out." Greg respects that.', '그럼 "잘 모르겠지만 알아보겠습니다"라고 하면 돼요. 그렉은 그런 답을 높이 사요.', '["Then just give your best guess. Greg won''t know the difference.","Don''t worry, he won''t ask you anything. He only talks to me.","Then stay quiet and let Derek answer. That''s safer for everyone."]', '["그럼 그냥 최대한 그럴듯하게 짐작해서 말해요. 그렉은 차이를 몰라요.","걱정 마요, 준한테는 아무것도 안 물어볼 거예요. 그렉은 저랑만 얘기해요.","그럼 가만히 있고 데릭이 대답하게 해요. 그게 다들 안전해요."]', '["Guess? That''s exactly what I didn''t want to do.","But I''m the one taking the technical questions, right?","Oh. Then what am I there for?"]', '["짐작이요? 그게 바로 제가 안 하고 싶은 건데요.","그래도 기술 질문은 제가 받기로 했잖아요?","아. 그럼 저는 왜 들어가요?"]', '["An honest \\"I don''t know\\" plus a promise is better than a guess.","Key words: I don''t know, but I''ll find out"]', '["짐작으로 답하는 것보다, 모른다고 솔직히 말하고 알아보겠다고 약속하는 편이 낫습니다.","핵심 단어: I don''t know, but I''ll find out"]', 'jun', 'That I can do.', '그건 할 수 있어요.'),
  ('pr_d8_prep', 4, 'derek', 'Derek has been on calls with Greg before.', '데릭은 전에도 그렉과 통화해 본 적이 있습니다.', 'And what if he brings up money? He always brings up money.', '그리고 그렉이 돈 얘기를 꺼내면요? 그 사람은 꼭 돈 얘기를 해요.', 'Money is your area. Make sure any pricing question ends up with you.', '돈 문제는 당신 담당입니다. 가격 질문이 나오면 반드시 당신에게 오게 하세요.', '[{"any":["do the talking","send it my way","leave the pricing","leave pricing"]}]', 'Let me do the talking on pricing. If money comes up, just send it my way.', '가격 얘기는 제가 할게요. 돈 얘기가 나오면 그냥 저한테 넘겨요.', '["Derek, you handle pricing. You know Greg better than I do.","If he asks, just offer him twenty percent off. Keep him happy.","Relax, he won''t bring it up today. This call is only about the checkout demo."]', '["데릭, 가격은 데릭이 맡아요. 저보다 그렉을 잘 알잖아요.","물어보면 그냥 20퍼센트 깎아 준다고 해요. 기분 좋게요.","걱정 마요, 오늘은 안 꺼낼 거예요. 이번엔 결제 화면 데모뿐이에요."]', '["Me? Numbers aren''t my thing. That''s your job.","Twenty percent? Did finance sign off on that?","Trust me, he will. He always does."]', '["제가요? 숫자는 제 분야가 아니에요. 그건 프리야 일이죠.","20퍼센트요? 재무팀에서 승인했어요?","두고 봐요, 꺼낼 거예요. 늘 그래요."]', '["\\"Let me do the talking\\" = I will be the one who speaks about this.","Key words: let me do the talking, on pricing, send it my way"]', '["\\"Let me do the talking\\"은 그 이야기는 내가 하겠다는 뜻입니다.","핵심 단어: let me do the talking, on pricing, send it my way"]', 'derek', 'Gladly. I write code, not invoices.', '기꺼이요. 저는 코드를 쓰지 청구서를 쓰지는 않으니까요.'),
  ('pr_d8_prep', 5, 'jun', 'Jun writes "pricing = Priya" in his notebook and underlines it twice.', '준이 공책에 "가격 = 프리야"라고 쓰고 밑줄을 두 번 긋습니다.', 'Is there anything we shouldn''t say?', '하면 안 되는 말이 있어요?', 'No promises about timing today. Tell them what to say instead if Greg presses.', '오늘은 일정에 관한 약속은 금지입니다. 그렉이 밀어붙이면 대신 뭐라고 할지 알려 주세요.', '[{"any":["commit to","in writing","promise any"]}]', 'Don''t commit to any dates on the call. If he pushes, say we''ll follow up in writing.', '통화 중에는 어떤 날짜도 약속하지 마요. 그렉이 밀어붙이면 글로 정리해서 드리겠다고 해요.', '["Don''t commit to any dates on the call. If he pushes, just tell him November first.","Don''t mention the demo at all. If he asks, say it''s still being tested.","Don''t say anything unless I nod at you first. I mean it, both of you."]', '["통화 중에는 어떤 날짜도 약속하지 마요. 그렉이 밀어붙이면 그냥 11월 1일이라고 해요.","데모 얘기는 아예 꺼내지 마요. 물어보면 아직 테스트 중이라고 해요.","제가 먼저 고개를 끄덕이기 전에는 아무 말도 하지 마요. 진심이에요, 둘 다요."]', '["Wait, isn''t saying November first a date?","But isn''t Derek running the demo?","Uh... okay. That''s a little scary."]', '["잠깐, 11월 1일이라고 하는 것도 날짜 아니에요?","그런데 데모는 데릭이 하기로 했잖아요?","어... 네. 좀 무섭네요."]', '["\\"To commit to\\" a date is to promise it. Tell them what to say instead.","Key words: don''t commit to any dates, follow up in writing"]', '["날짜에 commit한다는 것은 그 날짜를 약속한다는 뜻입니다. 대신 뭐라고 말할지도 알려 주세요.","핵심 단어: don''t commit to any dates, follow up in writing"]', 'derek', 'No dates, no dollars. Got it. See you in there at five to eleven.', '날짜 얘기도, 돈 얘기도 안 하기. 알겠어요. 10시 55분에 회의실에서 봐요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_actions', 1, 'jun', 'It is still raining. Jun is at his desk with three pages of notes from the call.', '비가 아직도 옵니다. 준이 통화에서 적은 메모 세 장을 들고 자리에 앉아 있습니다.', 'That was intense. I wrote down everything, but I''m not sure who''s doing what.', '정신없었어요. 다 적긴 했는데 누가 뭘 하는지 모르겠어요.', 'Suggest sorting out who does what right now, before anything slips through the cracks.', '놓치는 게 생기기 전에, 지금 바로 누가 무엇을 할지 정리하자고 하세요.', '[{"any":["nail down","fresh","pin down"]}]', 'Let''s nail down the action items while it''s still fresh.', '기억이 생생할 때 액션 아이템을 확실히 정해 두죠.', '["Let''s sort it out tomorrow. I''m too tired right now.","You should''ve asked during the call. Why didn''t you?","Just send me your notes, and I''ll figure the rest out myself."]', '["내일 정리해요. 지금은 너무 피곤해요.","통화 중에 물어봤어야죠. 왜 안 물어봤어요?","메모만 보내 줘요. 나머지는 제가 알아서 정리할게요."]', '["Tomorrow? I might forget half of it by then.","Sorry. It was moving really fast.","Oh. Okay. Should I still keep a copy?"]', '["내일이요? 그때쯤이면 반은 잊어버릴 것 같은데요.","죄송해요. 너무 빨리 지나가서요.","아. 네. 그래도 사본은 갖고 있을까요?"]', '["\\"Nail down\\" = make something definite. Do it right after the meeting.","Key words: nail down, the action items, while it''s still fresh"]', '["nail down은 확실히 정한다는 뜻입니다. 회의가 끝난 직후에 하세요.","핵심 단어: nail down, the action items, while it''s still fresh"]', 'jun', 'Good idea. I have three so far.', '좋은 생각이에요. 지금까지 세 가지예요.'),
  ('pr_d9_actions', 2, 'jun', 'Jun turns to the first page.', '준이 첫 장을 펼칩니다.', 'First, the updated timeline for Greg. Is that mine?', '첫째, 그렉한테 보낼 수정 일정표요. 그거 제 일이에요?', 'That one is yours, not his. Tell him when Greg will get it: noon tomorrow.', '그건 준이 아니라 당신 일입니다. 그렉이 언제 받을지 말하세요. 내일 정오입니다.', '[{"any":["i will take that","noon tomorrow","that one is mine"]}]', 'I''ll take that one. Greg will have it by noon tomorrow.', '그건 제가 할게요. 내일 정오까지 그렉한테 보낼게요.', '["Yes, that''s yours. Send it to Greg by noon tomorrow.","I''ll take that one. Greg will have it by noon on Friday.","I''ll take that one. Greg will get it at some point."]', '["네, 그건 준 일이에요. 내일 정오까지 그렉한테 보내요.","그건 제가 할게요. 금요일 정오까지 그렉한테 보낼게요.","그건 제가 할게요. 그렉한텐 언젠가 보낼게요."]', '["Me? I don''t even know the phase dates by heart.","Friday? Didn''t you tell him tomorrow?","Should I write a date? Every item needs one, right?"]', '["제가요? 단계별 날짜도 아직 다 못 외웠는데요.","금요일이요? 그렉한테 내일이라고 하지 않았어요?","날짜를 적을까요? 항목마다 있어야 하잖아요."]', '["Claim the task, then give the day and the time.","Key words: I''ll take that one, by noon tomorrow"]', '["일을 맡겠다고 하고, 날짜와 시간을 말하세요.","핵심 단어: I''ll take that one, by noon tomorrow"]', 'jun', 'Okay. Timeline: Priya, noon tomorrow.', '네. 일정표: 프리야, 내일 정오.'),
  ('pr_d9_actions', 3, 'jun', 'Jun flies to Ridgeport on Thursday morning.', '준은 목요일 아침에 리지포트로 떠납니다.', 'Second, the estimate for the wish list in phase two.', '둘째, 2단계 위시리스트 추정치요.', 'Ask him to take this one on. It doesn''t need to be exact, but you need it before his Thursday trip.', '준에게 이걸 맡아 달라고 하세요. 정확하지 않아도 되지만, 목요일 출장 전에는 필요합니다.', '[{"any":["rough estimate","ballpark","own that"]}]', 'Can you own that one? A rough estimate is fine, but I need it before you fly out on Thursday.', '그건 준이 맡아 줄래요? 대략적인 추정치면 되는데, 목요일에 떠나기 전까지는 필요해요.', '["Can you own that one? A rough estimate is fine, but I''ll need it once you''re back from your trip.","Can you own that one? It has to be exact, down to the day. No guessing this time.","Derek can own that one. You''re too new to estimate something like this."]', '["그건 준이 맡아 줄래요? 대략적인 추정치면 되는데, 출장 다녀온 다음에 주면 돼요.","그건 준이 맡아 줄래요? 하루 단위까지 정확해야 해요. 이번엔 짐작은 안 돼요.","그건 데릭이 맡으면 돼요. 준은 이런 걸 추정하기엔 아직 너무 신입이에요."]', '["After? I thought you needed it before I fly out.","Down to the day? For a rough feature? That''s tough.","Oh. Okay. I thought I could do it with his help."]', '["다녀온 다음이요? 떠나기 전에 필요한 줄 알았는데요.","하루 단위까지요? 아직 대충 잡힌 기능인데요? 어렵네요.","아. 네. 데릭 도움 받으면 할 수 있을 줄 알았어요."]', '["Ask him to be the owner, say how exact it must be, and give the deadline.","Key words: can you own that one, a rough estimate, before you fly out"]', '["담당자가 되어 달라고 하고, 얼마나 정확해야 하는지와 기한을 말하세요.","핵심 단어: can you own that one, a rough estimate, before you fly out"]', 'jun', 'Sure. I''ll sit down with Derek this afternoon.', '그럼요. 오늘 오후에 데릭과 같이 앉아서 볼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_actions', 4, 'derek', 'Derek walks by with a mug of coffee and looks over Jun''s shoulder.', '데릭이 커피 잔을 들고 지나가다 준의 어깨 너머로 메모를 봅니다.', 'Don''t forget the API access. Greg promised it by tomorrow, and nobody''s chasing it.', 'API 접근 권한 잊지 마요. 그렉이 내일까지 준다고 했는데, 아무도 챙기는 사람이 없어요.', 'He''s right. Say you''ll chase their point of contact early tomorrow morning.', '맞는 말입니다. 내일 아침 일찍 그쪽 담당자에게 확인하겠다고 하세요.', '[{"any":["follow up","first thing","check in with"]}]', 'You''re right. I''ll follow up with Dana first thing tomorrow.', '맞아요. 내일 아침 제일 먼저 데이나한테 확인할게요.', '["You''re right. I''ll follow up with Luis first thing tomorrow.","That''s Jun''s job, isn''t it? He was the one taking notes.","You''re right. Let''s give Greg a few days. He''ll get to it."]', '["맞아요. 내일 아침 제일 먼저 루이스한테 확인할게요.","그건 준 일 아니에요? 메모한 사람이 준이잖아요.","맞아요. 그렉한테 며칠 줘 보죠. 알아서 해 주겠죠."]', '["Luis? He''s finance. Dana''s the one who can say yes.","Whoa. He''s two weeks in. Someone senior should chase it.","A few days? Then the dashboard waits a few days."]', '["루이스요? 재무잖아요. 결정할 수 있는 건 데이나예요.","워. 온 지 2주 된 사람이에요. 이런 건 선임이 챙겨야죠.","며칠이요? 그럼 대시보드도 며칠 밀리는 거예요."]', '["\\"Follow up with\\" a person = contact them again to check on a promise.","Key words: follow up with Dana, first thing tomorrow"]', '["누구에게 follow up한다는 것은 약속한 일을 확인하려고 다시 연락한다는 뜻입니다.","핵심 단어: follow up with Dana, first thing tomorrow"]', 'derek', 'Perfect. No access, no dashboard.', '좋아요. 접근 권한이 없으면 대시보드도 없으니까요.'),
  ('pr_d9_actions', 5, 'jun', 'Three items, three owners. Jun opens a new email.', '세 가지 일에 담당자도 셋입니다. 준이 새 이메일 창을 엽니다.', 'Should I send these notes to everyone?', '이 메모 다 같이 보내 드릴까요?', 'Say yes, today. Tell him what each item needs next to it, and to copy your manager.', '네, 오늘 보내라고 하세요. 항목마다 무엇을 적어야 하는지 말하고, 당신의 매니저를 참조로 넣으라고 하세요.', '[{"any":["due date","cc maya","an owner"]}]', 'Yes, please send them out today, with an owner and a due date next to each item. And cc Maya.', '네, 오늘 보내 줘요. 항목마다 옆에 담당자랑 기한을 적어서요. 그리고 마야도 참조로 넣어 주고요.', '["Yes, please send them out today, with an owner and a due date next to each item. And cc Greg.","Yes, but hold them until Friday, so we can add anything else that comes up this week.","No, just keep them for yourself. Everyone was on the call, so they already know what to do."]', '["네, 오늘 보내 줘요. 항목마다 옆에 담당자랑 기한을 적어서요. 그리고 그렉도 참조로 넣어 주고요.","네, 그런데 금요일까지 갖고 있어요. 이번 주에 더 생기는 것까지 넣어서 보내게요.","아뇨, 그냥 준만 갖고 있어요. 다들 통화에 있었으니까 뭘 할지 이미 알아요."]', '["Greg? I thought these were just for us.","Friday? I''ll be in Ridgeport by then.","Really? I''m not sure Derek remembers all of it."]', '["그렉이요? 이건 우리끼리 보는 건 줄 알았는데요.","금요일이요? 그땐 저 리지포트에 가 있을 거예요.","정말요? 데릭이 다 기억할지 모르겠는데요."]', '["An action item has three parts: the task, the owner, the due date.","Key words: send them out today, an owner, a due date, cc Maya"]', '["액션 아이템은 할 일, 담당자, 기한의 세 부분으로 이루어집니다.","핵심 단어: send them out today, an owner, a due date, cc Maya"]', 'jun', 'Owner, due date, cc Maya. They''ll go out within the hour.', '담당자, 기한, 마야 참조. 한 시간 안에 보낼게요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_scope', 1, 'greg', 'Rain runs down the meeting room window. You sent Greg the gift card update this morning, as promised. Now he is back on the screen, and he sounds rushed.', '회의실 창문에 빗물이 흘러내립니다. 약속한 대로 오늘 아침 그렉에게 기프트 카드 진행 상황을 보냈습니다. 그렉이 다시 화면에 나타났는데, 급한 기색입니다.', 'Our board wants the dashboard and the mobile app live by November first. And while you''re at it, the wish list.', '이사회는 11월 1일까지 대시보드랑 모바일 앱이 나오길 원합니다. 하는 김에 위시리스트도요.', 'Don''t refuse him. Show you understand, and suggest sorting out what''s essential for that date.', '거절하지 마세요. 이해한다는 걸 보여 주고, 그 날짜에 꼭 필요한 게 뭔지 함께 가려 보자고 하세요.', '[{"any":["i hear you","can follow","has to be live"]}]', 'I hear you. Let''s look at what has to be live on November first, and what can follow.', '무슨 말씀인지 알겠습니다. 11월 1일에 꼭 나가야 하는 것과 뒤따라가도 되는 것을 같이 보시죠.', '["That''s not possible, Greg. Three projects by November first just won''t happen.","No problem at all. We''ll find a way to get all three live by November first.","I hear you. Let''s look at what has to be live on December first, and what can follow."]', '["그건 불가능합니다, 그렉. 11월 1일까지 세 가지를 다 하는 건 절대 안 됩니다.","전혀 문제없습니다. 11월 1일까지 세 가지 다 나가게 어떻게든 해 보겠습니다.","무슨 말씀인지 알겠습니다. 12월 1일에 꼭 나가야 하는 것과 뒤따라가도 되는 것을 같이 보시죠."]', '["I didn''t call to hear what won''t happen.","Good. That''s exactly what I told the board.","December? I said November first."]', '["안 된다는 소리 들으려고 전화한 게 아닙니다.","좋습니다. 제가 이사회에 말한 그대로네요.","12월이요? 11월 1일이라고 했습니다."]', '["\\"I hear you\\" shows you understand, without agreeing.","Key words: I hear you, has to be live, what can follow"]', '["\\"I hear you\\"는 동의하지는 않으면서 이해했다는 것을 보여 줍니다.","핵심 단어: I hear you, has to be live, what can follow"]', 'greg', 'Everything has to be live. That''s what I told the board.', '전부 나가야 합니다. 이사회에 그렇게 말했어요.'),
  ('pr_d9_scope', 2, 'greg', 'The dashboard alone is eight weeks of work. The mobile app is another eight.', '대시보드만 해도 8주가 걸립니다. 모바일 앱은 8주가 더 필요합니다.', 'So what can you realistically deliver by November first?', '그럼 11월 1일까지 현실적으로 뭘 해 줄 수 있습니까?', 'Split the work into two stages: the dashboard by his date, the mobile app in January.', '일을 두 단계로 나누세요. 대시보드는 그가 말한 날짜에, 모바일 앱은 1월에요.', '[{"any":["phase one","phase two","i would propose"]}]', 'Here''s what I''d propose: phase one is the dashboard on November first. Phase two is the mobile app, in January.', '이렇게 제안드리고 싶습니다. 1단계는 11월 1일에 대시보드, 2단계는 1월에 모바일 앱입니다.', '["Here''s what I''d propose: phase one is the mobile app on November first. Phase two is the dashboard, in January.","Here''s what I''d propose: phase one is the dashboard on November first. Phase two is the mobile app, a week later.","Honestly, Greg, if your board wanted all three, they should have come to us months ago."]', '["이렇게 제안드리고 싶습니다. 1단계는 11월 1일에 모바일 앱, 2단계는 1월에 대시보드입니다.","이렇게 제안드리고 싶습니다. 1단계는 11월 1일에 대시보드, 2단계는 일주일 뒤에 모바일 앱입니다.","솔직히 그렉, 이사회가 세 가지를 다 원했으면 몇 달 전에 말씀하셨어야죠."]', '["The app first? The dashboard is what my managers need.","A week later? That sounds too good to be true.","Well, they didn''t. So what can you do?"]', '["앱이 먼저요? 우리 관리자들한테 필요한 건 대시보드입니다.","일주일 뒤요? 너무 좋아서 믿기지가 않네요.","글쎄요, 안 했습니다. 그래서 뭘 해 줄 수 있습니까?"]', '["Open with \\"Here''s what I''d propose\\", then give each phase a date.","Key words: here''s what I''d propose, phase one, phase two, January"]', '["\\"Here''s what I''d propose\\"로 시작하고, 단계마다 날짜를 붙이세요.","핵심 단어: here''s what I''d propose, phase one, phase two, January"]', 'greg', 'Phased… okay, I could sell that to the board. But the wish list goes into phase one, right? It''s a tiny feature.', '단계별이라… 좋아요, 그거면 이사회를 설득할 수 있겠어요. 그런데 위시리스트는 1단계에 들어가는 거죠? 아주 작은 기능이잖아요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_scope', 3, 'greg', 'It is not tiny. Derek''s estimate for the wish list was three weeks.', '작지 않습니다. 데릭이 추정한 위시리스트 작업은 3주였습니다.', 'Come on. It''s just a button.', '에이. 그냥 버튼 하나잖아요.', 'It''s three weeks of work, not a button. Show you want it too, but explain what it would do to his date.', '버튼 하나가 아니라 3주짜리 일입니다. 당신도 원한다는 걸 보여 주되, 그 날짜에 어떤 영향을 주는지 설명하세요.', '[{"any":["at risk","on the roadmap","jeopardize"]}]', 'I''d love to get to it, and it''s on the roadmap. But adding it now would put November first at risk.', '저도 꼭 하고 싶고, 로드맵에도 있습니다. 하지만 지금 넣으면 11월 1일이 위험해집니다.', '["It''s not just a button, Greg. With all due respect, that''s simply not how software works.","I''d love to get to it, and it''s on the roadmap. But it''s three days of work, not just a button.","Okay, fair enough. If it''s that small, we''ll find a way to squeeze it into phase one."]', '["그냥 버튼이 아닙니다, 그렉. 죄송하지만 소프트웨어는 그렇게 돌아가지 않아요.","저도 꼭 하고 싶고, 로드맵에도 있습니다. 하지만 버튼 하나가 아니라 사흘짜리 작업이에요.","네, 알겠습니다. 그렇게 작다면 어떻게든 1단계에 끼워 넣어 보겠습니다."]', '["Excuse me? I know enough to know I''m paying for it.","Three days? Then what''s the problem?","Great. I knew you''d see it my way."]', '["뭐라고요? 돈 내는 사람이 저라는 건 알 만큼은 압니다.","사흘이요? 그럼 뭐가 문제입니까?","좋습니다. 제 말이 맞다는 걸 알아줄 줄 알았어요."]', '["Yes to the idea, no to the timing: say what the cost would be.","Key words: I''d love to, on the roadmap, put November first at risk"]', '["아이디어에는 찬성하되 시기에는 반대하세요. 지금 하면 무엇을 잃는지 말합니다.","핵심 단어: I''d love to, on the roadmap, put November first at risk"]', 'greg', 'I can''t move November first.', '11월 1일은 옮길 수 없어요.'),
  ('pr_d9_scope', 4, 'greg', 'Greg leans back and crosses his arms.', '그렉이 의자에 기대며 팔짱을 낍니다.', 'So you''re telling me no.', '그러니까 안 된다는 거군요.', 'Make it clear you''re delaying it, not refusing it, and offer it first place in the next phase.', '거절이 아니라 미루는 것뿐이라고 분명히 하고, 다음 단계에서 가장 먼저 하겠다고 제안하세요.', '[{"any":["not yet","top of phase two"]}]', 'It''s not a no. It''s a not yet. We can put the wish list at the top of phase two.', '안 된다는 게 아니라 아직은 아니라는 겁니다. 위시리스트를 2단계 맨 앞에 두겠습니다.', '["Yes, I''m telling you no. The wish list isn''t happening this year.","It''s not a no. It''s a not yet. We can put the wish list at the end of phase two.","No, no, of course not. I''ll talk to the team, and we''ll see what we can do."]', '["네, 안 된다는 겁니다. 위시리스트는 올해 안에는 절대 없을 겁니다, 그렉.","안 된다는 게 아니라 아직은 아니라는 겁니다. 위시리스트를 2단계 맨 끝에 두겠습니다.","아뇨, 아뇨, 그럴 리가요. 팀이랑 얘기해서 뭘 할 수 있는지 보겠습니다."]', '["Not this year? Then we have a problem, Priya.","The end of phase two? That''s not much of an offer.","So that''s a yes? Good."]', '["올해 안에는 없다고요? 그럼 문제가 있네요, 프리야.","2단계 맨 끝이요? 그건 제안이라고 하기도 어렵네요.","그럼 된다는 거죠? 좋습니다."]', '["Turn \\"no\\" into \\"not yet\\", and say exactly when.","Key words: not a no, a not yet, at the top of phase two"]', '["\\"no\\"를 \\"not yet\\"으로 바꾸고, 정확히 언제 할지 말하세요.","핵심 단어: not a no, a not yet, at the top of phase two"]', 'greg', 'Top of phase two. Hmm. And what if I want it sooner anyway?', '2단계의 맨 위라. 흠. 그래도 더 빨리 받고 싶다면요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d9_scope', 5, 'greg', 'He tries one more time. You give him the choice instead of the answer.', '그렉이 한 번 더 밀어붙입니다. 당신은 답 대신 선택지를 줍니다.', 'It''s my money. Put it in phase one.', '제 돈입니다. 1단계에 넣어 주세요.', 'Don''t argue. Show him the trade-off and let him pick.', '따지지 마세요. 무엇을 맞바꿔야 하는지 보여 주고 그가 고르게 하세요.', '[{"any":["come out","would you rather","comes out"]}]', 'If the wish list comes in, something has to come out. Which would you rather have on November first?', '위시리스트가 들어오면 다른 게 빠져야 합니다. 11월 1일에 어느 쪽을 받으시겠습니까?', '["You''re right, it''s your money. We''ll put it in phase one and make it all work.","It may be your money, Greg, but it''s my team. My answer is still phase two.","If the wish list comes in, we''ll need more budget, Greg. So how much more are you able to spend on it?"]', '["맞습니다, 그렉의 돈이죠. 1단계에 넣고 어떻게든 다 맞춰 보겠습니다.","그렉의 돈일지는 몰라도 제 팀입니다. 제 답은 여전히 2단계입니다.","위시리스트가 들어오면 예산이 더 필요합니다, 그렉. 그럼 얼마나 더 쓰실 수 있습니까?"]', '["Make it work? You just told me it puts the date at risk.","Your team? I''m the client here, Priya.","More money? I thought this was about time."]', '["다 맞춘다고요? 방금 날짜가 위험해진다고 했잖습니까.","제 팀이라고요? 고객은 저입니다, 프리야.","돈을 더요? 시간 문제인 줄 알았는데요."]', '["Show the trade, then let the client choose.","Key words: something has to come out, which would you rather"]', '["맞바꿔야 하는 것을 보여 주고, 고객이 고르게 하세요.","핵심 단어: something has to come out, which would you rather"]', 'greg', 'The dashboard. No question. Fine, you win. Phase two.', '대시보드죠. 말할 것도 없어요. 좋아요, 당신이 이겼어요. 2단계로 합시다.'),
  ('pr_d9_scope', 6, 'greg', 'Jun is taking notes as fast as he can.', '준이 있는 힘껏 받아 적고 있습니다.', 'So what am I telling my board?', '그럼 이사회에는 뭐라고 하면 됩니까?', 'Sum up the deal for his board, and promise him the revised schedule tomorrow.', '이사회에 전할 합의 내용을 요약하고, 수정한 일정표를 내일 보내겠다고 하세요.', '[{"all":["november"],"any":["january","timeline"]}]', 'Dashboard live on November first, mobile app and wish list in January. You''ll have the updated timeline tomorrow.', '대시보드는 11월 1일에 오픈, 모바일 앱과 위시리스트는 1월입니다. 수정한 일정표는 내일 보내 드리겠습니다.', '["Dashboard live on November first, mobile app in January, and the wish list in phase one. Timeline''s coming tomorrow.","Dashboard and mobile app live on November first, wish list in January. You''ll have the timeline tomorrow.","Just tell them we''re working on it, and that we''ll get back to them soon with all the details."]', '["대시보드는 11월 1일에 오픈, 모바일 앱은 1월, 위시리스트는 1단계입니다. 일정표는 내일 보내 드리겠습니다.","대시보드와 모바일 앱은 11월 1일에 오픈, 위시리스트는 1월입니다. 일정표는 내일 보내 드리겠습니다.","그냥 지금 작업 중이고, 곧 자세한 내용을 전부 정리해서 알려 드리겠다고 전해 주세요."]', '["Phase one? I just agreed to phase two.","Both on November first? That''s not what we just said.","My board won''t accept ''soon,'' Priya."]', '["1단계요? 방금 2단계로 하자고 했잖습니까.","둘 다 11월 1일이요? 방금 그렇게 얘기하지 않았습니다.","우리 이사회는 ''곧''이라는 말을 안 받아 줍니다, 프리야."]', '["Give him one sentence he can repeat to his board, then the next step.","Key words: live on November first, in January, the updated timeline tomorrow"]', '["그렉이 이사회에 그대로 전할 수 있는 한 문장을 주고, 다음 단계를 말하세요.","핵심 단어: live on November first, in January, the updated timeline tomorrow"]', 'greg', 'Sounds like a plan. Thanks for being straight with me.', '좋은 계획이네요. 솔직하게 말해 줘서 고마워요.'),
  ('pr_w_brunch', 1, 'rosa', 'A sunny weekend morning. The diner smells like coffee and bacon.', '화창한 주말 아침입니다. 다이너에 커피와 베이컨 냄새가 가득합니다.', 'Morning, hon! Just you today?', '안녕, 손님! 오늘은 혼자예요?', 'You''re eating alone. Ask for a seat where you can look out at the street.', '혼자 왔습니다. 바깥 거리가 보이는 자리를 부탁하세요.', '[{"any":["window","just me","table for one"]}]', 'Just me today. Could I get a table by the window?', '오늘은 혼자예요. 창가 자리로 앉을 수 있을까요?', '["Two of us, actually. Could we get a booth in the back?","Yeah. Give me the window table. That one, right there.","Just coffee for now. Could I see a menu, please?"]', '["사실 두 명이에요. 안쪽 부스 자리로 앉을 수 있을까요?","네. 창가 테이블 줘요. 저기 저거요.","일단 커피만요. 메뉴판 좀 볼 수 있을까요?"]', '["Two? Is someone joining you, hon?","Okay... sure. It''s all yours.","Sure, hon. But first, how many in your party?"]', '["두 명이요? 누가 더 와요?","네... 그래요. 앉아요.","그럼요. 그런데 먼저, 몇 분이세요?"]', '["Answer her question, then ask for the seat you want.","Key words: just me, a table by the window"]', '["질문에 답한 뒤 원하는 자리를 부탁하세요.","핵심 단어: just me, a table by the window"]', 'rosa', 'Sure thing. Right this way.', '그럼요. 이쪽으로 와요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_brunch', 2, 'rosa', 'Rosa comes over with a pot of coffee.', '로사가 커피 주전자를 들고 옵니다.', 'Coffee to start?', '커피부터 드릴까요?', 'Accept the coffee, and find out what''s good today that isn''t on the regular menu.', '커피는 받고, 오늘 메뉴판에 없는 특별 메뉴가 뭔지 알아보세요.', '[{"any":["specials","special"]}]', 'Yes, please. What are the brunch specials today?', '네, 주세요. 오늘 브런치 스페셜은 뭐예요?', '["No, thanks. What are the brunch specials today?","Yes, please. Could I take a look at the dinner menu?","Yes. And hurry, please. I''m starving here."]', '["아뇨, 괜찮아요. 오늘 브런치 스페셜은 뭐예요?","네, 주세요. 저녁 메뉴판 좀 볼 수 있어요?","네. 그리고 빨리 좀 주세요. 배고파 죽겠어요."]', '["No coffee? Okay, hon. Water, then?","Dinner? Hon, it''s ten in the morning.","Coming right up. No need to rush me, though."]', '["커피 안 마셔요? 알았어요. 그럼 물 줄까요?","저녁이요? 손님, 지금 아침 열 시예요.","금방 가요. 그렇게 재촉 안 해도 돼요."]', '["\\"Specials\\" are dishes only on today''s menu.","Key words: yes please, brunch specials"]', '["specials는 오늘만 파는 메뉴입니다.","핵심 단어: yes please, brunch specials"]', 'rosa', 'We''ve got a veggie omelet with home fries and toast, or blueberry pancakes.', '채소 오믈렛에 홈 프라이와 토스트가 나오는 것, 아니면 블루베리 팬케이크가 있어요.'),
  ('pr_w_brunch', 3, 'rosa', 'She takes a pencil from behind her ear.', '로사가 귀 뒤에 꽂아 둔 연필을 뺍니다.', 'What''ll it be, hon?', '뭘로 할래요?', 'Order the omelet, but you''d rather have wheat bread than white.', '오믈렛을 주문하되, 빵은 흰 빵보다 통밀이 좋습니다.', '[{"all":["omelet"]},{"all":["omelette"]}]', 'I''ll have the veggie omelet. Can I get wheat toast instead of white?', '채소 오믈렛으로 할게요. 토스트는 흰 빵 말고 통밀로 해 주실 수 있어요?', '["I''ll have the veggie omelet. Can I get hash browns instead of toast?","I''ll have the blueberry pancakes. Can I get wheat toast with them?","The omelet. And wheat toast. Your white bread is awful, honestly."]', '["채소 오믈렛으로 할게요. 토스트 대신 해시 브라운으로 해 주실 수 있어요?","블루베리 팬케이크로 할게요. 통밀 토스트도 같이 주실 수 있어요?","오믈렛이요. 토스트는 통밀로요. 여기 흰 빵은 솔직히 별로예요."]', '["It already comes with home fries, hon. So no toast at all?","Pancakes and toast? That''s a lot of bread, hon.","Well, our regulars like it fine. Wheat it is."]', '["홈 프라이는 원래 나와요. 그럼 토스트는 아예 빼요?","팬케이크에 토스트까지요? 빵이 너무 많은데요.","글쎄요, 단골들은 잘만 먹던데. 통밀로 할게요."]', '["\\"I''ll have …\\" orders. \\"… instead of …\\" changes one thing.","Key words: I''ll have the veggie omelet, wheat toast instead of white"]', '["\\"I''ll have …\\"로 주문하고 \\"… instead of …\\"로 하나를 바꿉니다.","핵심 단어: I''ll have the veggie omelet, wheat toast instead of white"]', 'rosa', 'Wheat toast, you got it. It''ll be right out.', '통밀 토스트, 알겠어요. 금방 나와요.'),
  ('pr_w_brunch', 4, 'rosa', 'The plate is empty. Rosa stops by with the coffee pot again.', '접시가 비었습니다. 로사가 다시 커피 주전자를 들고 들릅니다.', 'How was everything?', '식사는 어땠어요?', 'Tell her you enjoyed it like always, and that you''re ready to pay.', '늘 그렇듯 맛있었다고 하고, 계산하겠다고 하세요.', '[{"any":["check","bill"]}]', 'Delicious, as always. Could I get the check, please?', '언제나처럼 맛있었어요. 계산서 좀 주시겠어요?', '["Delicious, thanks. Could I get a coffee refill, please?","Fine. The eggs were a bit dry. Check, please.","Delicious. Could I get this to go, please?"]', '["맛있었어요, 고마워요. 커피 리필 좀 해 주시겠어요?","그냥 그랬어요. 달걀이 좀 퍽퍽했어요. 계산서요.","맛있었어요. 이거 포장해 주시겠어요?"]', '["Sure thing. Anything else, or just the coffee?","Oh. I''m sorry, hon. I''ll let the kitchen know.","To go? Hon, you cleaned the plate."]', '["그럼요. 다른 건요, 커피만요?","어머. 미안해요. 주방에 말할게요.","포장이요? 손님, 접시를 싹 비웠는데요."]', '["A compliment first, then \\"Could I get the check?\\"","Key words: delicious, as always, the check"]', '["먼저 칭찬하고, \\"Could I get the check?\\"이라고 하세요.","핵심 단어: delicious, as always, the check"]', 'rosa', 'Here you go, hon. Eighteen forty with tax. No rush.', '여기요. 세금 포함해서 18달러 40센트예요. 천천히 해요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_brunch', 5, 'rosa', 'The check says $17.00 plus $1.40 tax. Twenty percent of seventeen dollars is $3.40.', '계산서에는 17달러에 세금 1달러 40센트라고 적혀 있습니다. 17달러의 20퍼센트는 3달러 40센트입니다.', 'Cash or card?', '현금이에요, 카드예요?', 'Pay with plastic, and leave her a good tip: twenty percent.', '카드로 내고, 팁을 넉넉히 20퍼센트 남기세요.', '[{"all":["tip"]},{"any":["twenty percent","20 percent","gratuity"]}]', 'I''ll put it on my card. And please add a twenty percent tip.', '카드로 할게요. 그리고 팁 20퍼센트 더해 주세요.', '["I''ll put it on my card. And please add a ten percent tip.","Card, please. And add three forty, so it comes to twenty even.","I''ll pay in cash. Here''s a twenty. Keep the change."]', '["카드로 할게요. 그리고 팁 10퍼센트 더해 주세요.","카드로요. 팁 3달러 40센트 더해서 딱 20달러 맞춰 주세요.","현금으로 할게요. 여기 20달러요. 잔돈은 가지세요."]', '["Ten percent. Okay, hon. Thanks.","Twenty even? I think that''d be twenty-one eighty, hon.","Oh. Well, thank you, hon."]', '["10퍼센트요. 네, 고마워요.","딱 20달러요? 그러면 21달러 80센트일 텐데요.","아. 네, 고마워요."]', '["Tip 15 to 20 percent of the price before tax.","Key words: put it on my card, twenty percent tip"]', '["팁은 세전 가격의 15~20퍼센트입니다.","핵심 단어: put it on my card, twenty percent tip"]', 'rosa', 'Aw, thank you, hon! You have a great weekend.', '어머, 고마워요! 주말 잘 보내요.'),
  ('pr_w_farmers', 1, 'carl', 'Seaside Park on a sunny morning. Carl is on his usual bench with a paper bag full of peaches.', '화창한 아침의 시사이드 공원입니다. 칼이 늘 앉는 벤치에 복숭아가 가득 든 종이봉투를 들고 있습니다.', 'Well, look who it is! Morning, Priya. Beautiful day, huh?', '아니, 이게 누구야! 좋은 아침이야, 프리야. 날씨 좋지?', 'You''re on your way to the farmers market. Agree about the day, and ask if that''s why he''s here.', '당신은 파머스 마켓에 가는 길입니다. 날씨에 맞장구치고, 칼도 그래서 왔는지 물어보세요.', '[{"any":["farmers market","market"]}]', 'Gorgeous! Are you here for the farmers market too?', '정말 좋네요! 칼도 파머스 마켓 오셨어요?', '["Is it? I hadn''t noticed. Are you on your way home?","Gorgeous! I wish I could enjoy it. I''ve got work to do.","Morning, Carl! Did you get those peaches at the store?"]', '["그래요? 몰랐어요. 댁에 가시는 길이에요?","정말 좋네요! 즐기고 싶은데 저는 일이 있어서요.","안녕하세요, 칼! 그 복숭아 마트에서 사셨어요?"]', '["Hadn''t noticed? Kid, look up. Not a cloud in the sky.","Work? On a day like this? Put the laptop away.","The store? Never. Right here at the market."]', '["몰랐다고? 이 사람아, 고개 좀 들어 봐. 구름 한 점 없잖아.","일? 이런 날에? 노트북은 좀 덮어 둬.","마트? 무슨. 바로 여기 마켓에서 샀지."]', '["Agree about the weather, then ask why he is here.","Key words: gorgeous, farmers market"]', '["날씨에 맞장구친 뒤 여기 온 이유를 물어보세요.","핵심 단어: gorgeous, farmers market"]', 'carl', 'Already been. Got the peaches from the stand by the fountain. Best in town.', '벌써 다녀왔지. 분수대 옆 가판에서 복숭아를 샀어. 이 동네 최고야.'),
  ('pr_w_farmers', 2, 'carl', 'He holds up a peach the size of a baseball.', '칼이 야구공만 한 복숭아를 들어 보입니다.', 'Look at that. You don''t get these at the store.', '이것 좀 봐. 마트에선 이런 거 못 사.', 'Say something nice about the fruit, and find out what they cost.', '복숭아를 칭찬하고, 값이 얼마인지 알아보세요.', '[{"any":["how much","price","cost"]}]', 'They look amazing. How much are they?', '정말 맛있어 보여요. 그거 얼마예요?', '["They look okay. Are they worth the money?","They look amazing. Can I have one of yours?","They look amazing. Which store has them?"]', '["그냥 괜찮아 보이네요. 돈 값은 해요?","정말 맛있어 보여요. 하나 주실래요?","정말 맛있어 보여요. 어느 마트예요?"]', '["Okay? Kid, these are the best in town.","Ha! Get your own. The stand''s right over there.","A store? I just told you, they''re from the market."]', '["괜찮아 보인다고? 이 동네 최고라니까.","하! 자네 건 자네가 사. 가판이 바로 저기야.","마트? 방금 마켓에서 샀다고 했잖아."]', '["Ask the price with \\"How much …?\\"","Key words: look amazing, how much"]', '["\\"How much …?\\"로 값을 물어보세요.","핵심 단어: look amazing, how much"]', 'carl', 'Four dollars a pound, or three pounds for ten. Tell them Carl sent you.', '1파운드에 4달러, 3파운드에 10달러야. 칼이 보냈다고 해.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_farmers', 3, 'carl', 'He points across the grass at the white tents.', '칼이 잔디밭 건너 하얀 천막들을 가리킵니다.', 'Bring cash, though. Some of the stands don''t take cards.', '그래도 현금은 챙겨. 카드 안 받는 가판도 있거든.', 'Thank him for the heads-up. You don''t have any cash on you.', '미리 알려 줘서 고맙다고 하세요. 지금 현금이 하나도 없습니다.', '[{"all":["atm"]},{"any":["cash machine","get cash"]}]', 'Good to know. Is there an ATM nearby?', '알려 주셔서 다행이에요. 근처에 ATM 있어요?', '["Good to know. I''ll just pay by card, then.","Seriously? Who doesn''t take cards these days?","Good to know. Could I borrow some cash?"]', '["그렇군요. 그럼 그냥 카드로 낼게요.","진짜요? 요즘 카드 안 받는 데가 어디 있어요?","그렇군요. 현금 좀 빌려주실 수 있어요?"]', '["Card? Didn''t you hear me? Some don''t take them.","The farmers, that''s who. Small stands, small margins.","Ha! From your landlord? Nice try, kid."]', '["카드? 내 말 못 들었어? 안 받는 데도 있다니까.","농부들이 그래. 작은 가판은 남는 게 별로 없거든.","하! 집주인한테? 꿈도 꾸지 마."]', '["A machine that gives you cash is an ATM.","Key words: good to know, ATM nearby"]', '["현금을 뽑는 기계는 ATM입니다.","핵심 단어: good to know, ATM nearby"]', 'carl', 'There''s one by the park entrance, right next to the coffee cart.', '공원 입구에 하나 있어. 커피 카트 바로 옆이야.'),
  ('pr_w_farmers', 4, 'carl', 'Carl moves over to make room on the bench.', '칼이 벤치 옆자리를 내줍니다.', 'So how''s work? Still running all those meetings?', '일은 어때? 아직도 그 회의들 다 진행하나?', 'Tell him how your week went: it was crazy, but the team got the release out on schedule.', '이번 주가 어땠는지 말하세요. 정신없었지만 팀이 일정대로 배포했습니다.', '[{"any":["hectic","busy","shipped","on time","crazy"]}]', 'Always. It was a hectic week, but we shipped on time.', '늘 그렇죠. 정신없는 한 주였는데, 제때 배포했어요.', '["Always. It was a hectic week, and we missed the deadline.","Don''t get me started. The client yelled and Jun nearly quit.","Not really. I mostly just write code these days, Carl."]', '["늘 그렇죠. 정신없는 한 주였고, 마감은 놓쳤어요.","말도 마세요. 고객은 소리 지르고, 준은 그만둘 뻔했어요.","아뇨. 요즘은 거의 코드만 짜요, 칼."]', '["Ah, that''s too bad. Next week, then.","Whoa. That bad? Sounds like you need this sun.","Code? I thought you were the boss of the meetings."]', '["아, 저런. 다음 주엔 되겠지.","저런. 그렇게 심했어? 이 햇볕 좀 쬐어야겠네.","코드? 자네가 회의 대장인 줄 알았는데."]', '["One word for the week, then the good result.","Key words: hectic week, shipped on time"]', '["한 주를 한 단어로 말하고, 좋은 결과를 덧붙이세요.","핵심 단어: hectic week, shipped on time"]', 'carl', 'That''s what I like to hear. But you work too hard, you know.', '듣기 좋은 소식이네. 그런데 자네는 일을 너무 많이 해.'),
  ('pr_w_farmers', 5, 'carl', 'Music drifts over from the market.', '마켓 쪽에서 음악 소리가 들려옵니다.', 'What are you doing this weekend to relax?', '이번 주말엔 쉬려고 뭐 할 거야?', 'Tell him your plan: a meal at home from whatever you find here, then a lazy afternoon.', '계획을 말하세요. 여기서 고른 걸로 집에서 요리하고, 오후엔 느긋하게 보낼 겁니다.', '[{"any":["cook","take it easy","relax","fresh"]}]', 'I''m going to cook with whatever looks fresh, and then take it easy.', '싱싱해 보이는 걸로 요리하고, 그다음엔 푹 쉬려고요.', '["Honestly, I''ll probably catch up on work and get ready for Monday.","I''m going to grab a frozen pizza and then take it easy.","Not sure yet. Why, is something wrong at the apartment?"]', '["솔직히 밀린 일 하고 월요일 준비나 할 것 같아요.","냉동 피자 하나 사다 먹고 푹 쉬려고요.","아직 몰라요. 왜요, 집에 무슨 문제 있어요?"]', '["Work? On a weekend? Kid, you''re hopeless.","Frozen pizza? With all this fresh stuff around?","No, no. I''m just asking how you are."]', '["일? 주말에? 이 사람, 못 말리겠네.","냉동 피자? 이렇게 싱싱한 게 널렸는데?","아니, 아니. 그냥 어떻게 지내나 물어본 거야."]', '["\\"I''m going to …\\" for plans. \\"Take it easy\\" = rest.","Key words: cook, whatever looks fresh, take it easy"]', '["계획은 \\"I''m going to …\\"로 말합니다. take it easy는 쉰다는 뜻입니다.","핵심 단어: cook, whatever looks fresh, take it easy"]', 'carl', 'That''s the spirit. Here, take a peach for the road.', '바로 그거야. 자, 가는 길에 복숭아 하나 먹어.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_grocery', 1, 'mike', 'Fairview Market. Your cart is full for the week: vegetables, eggs, cheese, coffee beans.', '페어뷰 마켓입니다. 채소, 달걀, 치즈, 커피 원두까지 한 주 먹을 것으로 카트가 가득합니다.', 'Hi there! Did you find everything okay?', '안녕하세요! 찾으시는 건 다 찾으셨어요?', 'Answer him, and let him know you won''t need the store''s bags today.', '대답하고, 오늘은 가게 봉투가 필요 없다고 알려 주세요.', '[{"any":["own bags","my bags","reusable","own bag"]}]', 'I did, thanks. Oh, and I brought my own bags.', '네, 고마워요. 아, 그리고 장바구니 가져왔어요.', '["I did, thanks. Could I get a few extra bags?","Almost. I couldn''t find the coffee beans.","Yeah. Just ring it up, please. I''m in a hurry."]', '["네, 고마워요. 봉투 몇 개 더 주실 수 있어요?","거의요. 커피 원두는 못 찾았어요.","네. 그냥 빨리 계산해 주세요. 저 바빠요."]', '["Sure. They''re ten cents each, though.","Oh? Looks like there''s a bag of them right here.","Sure thing. I''ll be quick."]', '["그럼요. 근데 하나에 10센트예요.","네? 여기 원두 한 봉지 있는 것 같은데요.","네, 빨리 해 드릴게요."]', '["Answer yes, then tell him about your bags.","Key words: I did, brought my own bags"]', '["네라고 답한 뒤 장바구니 이야기를 하세요.","핵심 단어: I did, brought my own bags"]', 'mike', 'Nice! That''s five cents off for each bag.', '좋네요! 봉투 하나에 5센트씩 빼 드려요.'),
  ('pr_w_grocery', 2, 'mike', 'You watch the prices on the screen. The cheddar comes up as $4.49, but the sign on the shelf said $3.49.', '화면에 찍히는 값을 봅니다. 체다 치즈가 4달러 49센트로 찍혔는데, 진열대 표지에는 3달러 49센트라고 돼 있었습니다.', 'Did you know the ice cream is two for eight this week?', '이번 주에 아이스크림 두 개에 8달러인 거 아셨어요?', 'He''s talking about ice cream, but the cheese came up a dollar too high. Bring it up politely.', '그는 아이스크림 얘기를 하지만, 치즈 값이 1달러 더 찍혔습니다. 정중하게 말하세요.', '[{"any":["rang up","wrong price","on sale","sign said","overcharged"]}]', 'Sorry, I think the cheese rang up wrong. The sign said it was on sale.', '죄송한데, 치즈 값이 잘못 찍힌 것 같아요. 진열대엔 할인이라고 돼 있었어요.', '["Sorry, I think the eggs rang up wrong. The sign said they were on sale.","Hey, you overcharged me for the cheese. Fix that, please.","Two for eight? Great, I''ll grab two. Can you hold my spot?"]', '["죄송한데, 달걀 값이 잘못 찍힌 것 같아요. 진열대엔 할인이라고 돼 있었어요.","저기요, 치즈 값을 더 받으셨잖아요. 그거 지금 바로 고쳐 주세요.","두 개에 8달러요? 좋네요, 두 개 가져올게요. 자리 좀 맡아 줄래요?"]', '["The eggs? They came up two ninety-nine. That''s the sale price.","Whoa, okay. Let me take a look. It''s just the system.","Sure. Freezers are in aisle nine."]', '["달걀이요? 2달러 99센트로 찍혔는데요. 그게 할인가예요.","워, 네. 확인해 볼게요. 시스템이 그런 거예요.","그럼요. 냉동 코너는 9번 통로예요."]', '["\\"Ring up\\" = enter the price at the register. Past: rang up.","Key words: I think, rang up wrong, on sale"]', '["ring up은 계산대에서 값을 찍는다는 뜻입니다. 과거형은 rang up.","핵심 단어: I think, rang up wrong, on sale"]', 'mike', 'Let me check. You''re right, it''s three forty-nine. I''ll fix that.', '확인해 볼게요. 맞네요, 3달러 49센트예요. 고쳐 드릴게요.'),
  ('pr_w_grocery', 3, 'mike', 'You take a coupon out of your wallet.', '지갑에서 쿠폰을 꺼냅니다.', 'Anything else before I total it up?', '합계 내기 전에 더 필요한 거 있으세요?', 'Before he totals it, hand over the coupon you brought for the coffee.', '합계를 내기 전에, 커피 원두용으로 가져온 쿠폰을 내미세요.', '[{"all":["coupon"]}]', 'Can I use this coupon? It''s for the coffee beans.', '이 쿠폰 쓸 수 있어요? 커피 원두 쿠폰이에요.', '["Can I use this coupon? It''s for the ice cream.","No, that''s it. Go ahead and total it up.","I want this coupon used. Don''t tell me it''s expired."]', '["이 쿠폰 쓸 수 있어요? 아이스크림 쿠폰이에요.","아뇨, 그게 다예요. 합계 내 주세요.","이 쿠폰 꼭 써야 돼요. 기한 지났다는 말은 마세요."]', '["This one? It says coffee beans on it.","Okay. Oh, wait. Is that a coupon in your hand?","Whoa, easy. Let me look. It''s good till tomorrow."]', '["이거요? 커피 원두라고 적혀 있는데요.","네. 아, 잠깐만요. 손에 든 거 쿠폰이에요?","워, 진정하세요. 볼게요. 내일까지 쓸 수 있어요."]', '["Hand it over and ask \\"Can I use …?\\"","Key words: use this coupon, coffee beans"]', '["쿠폰을 내밀며 \\"Can I use …?\\"로 물어보세요.","핵심 단어: use this coupon, coffee beans"]', 'mike', 'Sure. It expires tomorrow, so you''re just in time. Two dollars off.', '그럼요. 내일까지라서 딱 맞춰 오셨네요. 2달러 할인입니다.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_grocery', 4, 'mike', 'The total appears on the card reader.', '카드 단말기에 합계가 뜹니다.', 'Debit or credit?', '체크카드예요, 신용카드예요?', 'You''re using your credit card. You don''t want to hold on to the receipt: have it go with the groceries.', '신용카드로 냅니다. 영수증은 들고 있기 싫으니 장 본 물건과 같이 넣어 달라고 하세요.', '[{"all":["credit"]}]', 'Credit, please. And could you put the receipt in the bag?', '신용카드요. 그리고 영수증은 봉투에 넣어 주실래요?', '["Debit, please. And could you put the receipt in the bag?","Credit, please. And no receipt, thanks. I won''t need it.","Credit. Receipt goes in the bag. Hurry, there''s a line."]', '["체크카드요. 그리고 영수증은 봉투에 넣어 주실래요?","신용카드요. 영수증은 괜찮아요. 필요 없을 거예요.","신용카드. 영수증은 봉투에. 빨리요, 뒤에 줄 섰어요."]', '["Debit, okay. Go ahead and enter your PIN.","No receipt? Okay. You sure?","Uh, okay. Doing my best here."]', '["체크카드요, 네. 비밀번호 눌러 주세요.","영수증 필요 없어요? 네. 정말요?","어, 네. 최대한 빨리 하고 있어요."]', '["Choose one of the two, then say where the receipt goes.","Key words: credit, receipt in the bag"]', '["둘 중 하나를 고르고, 영수증을 어디에 둘지 말하세요.","핵심 단어: credit, receipt in the bag"]', 'mike', 'You got it. You''re all set.', '알겠어요. 다 됐습니다.'),
  ('pr_w_grocery', 5, 'mike', 'Two full bags. They are heavier than they look.', '가득 찬 봉투가 둘입니다. 보기보다 무겁습니다.', 'Need a hand out to your car?', '차까지 들어다 드릴까요?', 'Turn down the help politely. You don''t have far to go.', '도움은 정중하게 사양하세요. 멀리 가지 않습니다.', '[{"any":["got it","i am good","around the corner","manage"]},{"all":["no"],"any":["thanks","thank"]}]', 'No, thanks. I''ve got it. I live just around the corner.', '괜찮아요, 고마워요. 들 수 있어요. 바로 근처에 살아요.', '["Yes, please. My car''s parked way out in the back.","No. I can carry my own groceries. I''m not helpless.","Sure, thanks. Could you carry them home for me? It''s close."]', '["네, 부탁해요. 차를 저 뒤쪽 끝에 세웠어요.","아뇨. 장 본 건 제가 들어요. 저 그렇게 약하지 않거든요.","네, 고마워요. 집까지 들어다 주실래요? 가까워요."]', '["Sure thing. Which row are you in?","Oh, no, I didn''t mean it like that. Have a good one.","Home? Uh, I can only go as far as the parking lot."]', '["그럼요. 몇 번째 줄이에요?","아, 그런 뜻이 아니었어요. 좋은 하루 보내세요.","집까지요? 어, 저는 주차장까지만 갈 수 있어요."]', '["A polite no, then \\"I''ve got it.\\"","Key words: no thanks, I''ve got it, around the corner"]', '["정중히 거절하고 \\"I''ve got it.\\"이라고 하세요.","핵심 단어: no thanks, I''ve got it, around the corner"]', 'mike', 'Have a good one! Enjoy the rest of your weekend.', '좋은 하루 보내세요! 남은 주말 잘 보내시고요.'),
  ('pr_w2_carl', 1, 'carl', 'Saturday morning, sunny and warm. Carl is on his bench with a bag of charcoal at his feet.', '화창하고 따뜻한 토요일 아침입니다. 칼이 발치에 숯 한 봉지를 두고 늘 앉는 벤치에 앉아 있습니다.', 'There she is! You look like somebody who had a good week.', '왔구먼! 한 주 잘 보낸 사람 얼굴인데.', 'Share your good news from work yesterday.', '어제 회사에서 있었던 좋은 소식을 전하세요.', '[{"any":["big deal","closed a","closed the","signed"]}]', 'I did! We closed a big deal yesterday.', '맞아요! 어제 큰 계약을 따냈어요.', '["I did! We closed a big deal on Monday.","Not really. Just a long, busy week.","I did! I closed the biggest deal ever."]', '["맞아요! 월요일에 큰 계약을 따냈어요.","별로요. 그냥 길고 바쁜 한 주였어요.","맞아요! 제가 역대 최대 계약을 따냈어요."]', '["Monday? Then why''d you look so tired all week?","Really? With that smile? I don''t buy it.","Ever? Well, look at you. All by yourself, huh?"]', '["월요일? 그럼 한 주 내내 왜 그렇게 피곤해 보였나?","정말? 그렇게 웃으면서? 못 믿겠는걸.","역대? 이야, 대단하네. 혼자서 다 했다는 건가?"]', '["To \\"close a deal\\" is to finish it with a signed agreement.","Key words: we closed a big deal, yesterday"]', '["close a deal은 서명까지 마쳐 거래를 성사시킨다는 뜻입니다.","핵심 단어: we closed a big deal, yesterday"]', 'carl', 'Well, how about that! Congratulations. So what did you have to give up to get it?', '이야, 그것참 잘됐네! 축하해. 그래, 그걸 따내려고 뭘 내줬나?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_carl', 2, 'carl', 'Carl bought bus parts for thirty years. He knows there is no deal without a price.', '칼은 30년 동안 버스 부품을 사들였습니다. 대가 없는 거래가 없다는 것을 잘 압니다.', 'Nobody signs for free.', '공짜로 서명하는 사람은 없지.', 'Tell him what you gave up and what you got back, and how you see the trade.', '무엇을 내주고 무엇을 받았는지, 그리고 그 거래를 어떻게 보는지 말하세요.', '[{"any":["in return","win win"]}]', 'A small discount, but we got a one-year contract in return. I''d call that a win-win.', '할인을 조금 해 줬지만, 그 대신 1년 계약을 받았어요. 서로 좋은 거래라고 봐요.', '["A small discount, but we got a five-year support contract in return. A great trade.","We didn''t give up a thing, actually. They took our price, and that was that.","Five percent off one eighty, plus Net 45, and a one-year support contract for Summit."]', '["할인을 조금 해 줬지만, 그 대신 5년짜리 지원 계약을 받았어요. 아주 좋은 거래죠.","사실 하나도 안 내줬어요. 그쪽이 우리 가격을 받아들였고, 그걸로 끝이었어요.","18만에서 5퍼센트 할인, 거기에 Net 45, 그리고 서밋과 1년 지원 계약이요."]', '["Five years, huh? Hope you read the fine print on that one.","Nothing at all? In thirty years, I never once saw that.","Whoa, I don''t need the whole contract. Is that stuff even public?"]', '["5년이라? 깨알 같은 조항까지 잘 읽어 봤길 바라네.","하나도? 30년 동안 그런 건 한 번도 못 봤는데.","어이쿠, 계약서를 통째로 읊을 필요는 없어. 그런 거 밖에 말해도 되나?"]', '["What you gave, what you got \\"in return\\", and a name for the result.","Key words: a small discount, in return, a win-win"]', '["무엇을 주었는지, 그 대신(in return) 무엇을 받았는지, 그리고 그 결과를 한마디로 말하세요.","핵심 단어: a small discount, in return, a win-win"]', 'carl', 'Win-win. That''s how I bought parts for thirty years. So, what are you doing with your Saturday? Don''t tell me you''re working.', '양쪽 다 좋은 거래라. 나도 30년 동안 그렇게 부품을 샀지. 그래, 토요일엔 뭘 하나? 설마 일한다는 건 아니겠지.'),
  ('pr_w2_carl', 3, 'carl', 'Your laptop is at home, closed. Maya told you to take the weekend off.', '노트북은 집에 덮어 두고 왔습니다. 마야도 주말에는 쉬라고 했습니다.', 'You work too hard. I''ve said it before.', '자네는 일을 너무 많이 해. 전에도 말했지.', 'Assure him you''re taking a real break from work this weekend.', '이번 주말에는 일에서 제대로 손을 놓는다고 안심시키세요.', '[{"any":["unplugging","unplug","no email"]}]', 'No way. I''m unplugging this weekend. No email until Monday.', '절대 아니에요. 이번 주말엔 일 완전히 끊어요. 월요일까지 이메일도 안 봐요.', '["I know. I''ll just check my email a few times this weekend.","Not this weekend. My laptop''s at the office, so no email till Monday.","Well, someone has to. The team would fall apart without me."]', '["알아요. 그래도 이번 주말엔 이메일을 몇 번만 확인하고 말게요.","이번 주말은 아니에요. 노트북을 회사에 두고 와서 월요일까지 이메일은 못 봐요.","뭐, 누군가는 해야죠. 솔직히 제가 없으면 팀이 금방 무너질걸요."]', '["A few times? That''s how it starts.","At the office? I saw you carry it home Friday night.","Nobody''s that important, kid. Trust me."]', '["몇 번만? 원래 그렇게 시작하는 거야.","회사에? 금요일 밤에 들고 들어가는 걸 봤는데.","그렇게까지 대단한 사람은 없어. 내 말 믿게."]', '["\\"Unplug\\" = stop working and stay away from screens.","Key words: I''m unplugging, no email until Monday"]', '["unplug는 일을 멈추고 화면에서 떨어져 지낸다는 뜻입니다.","핵심 단어: I''m unplugging, no email until Monday"]', 'carl', 'I''ll believe it when I see it.', '눈으로 봐야 믿겠는걸.'),
  ('pr_w2_carl', 4, 'carl', 'He taps the bag of charcoal with his shoe.', '칼이 구두로 숯 봉지를 툭 칩니다.', 'I''m having a barbecue for my tenants at four. Jun''s coming, the new kid from your office. Why don''t you swing by?', '네 시에 세입자들 불러서 바비큐를 할 거야. 자네 회사 신참 준도 온다더군. 들르지 그래?', 'Accept the invitation, and offer to bring something.', '초대를 받아들이고, 뭔가 가져가겠다고 하세요.', '[{"any":["can i bring","should i bring","love to"]}]', 'I''d love to. What can I bring?', '좋아요. 뭘 가져갈까요?', '["I''d love to. Is it at five o''clock?","Maybe. I''ll see how I feel.","Sure. Should I invite Jun?"]', '["좋아요. 다섯 시였던가요?","글쎄요. 그때 봐서요.","그럼요. 준도 부를까요?"]', '["Four, I said. Four sharp.","Suit yourself. Ribs won''t wait, though.","Already did. He said yes before you did."]', '["네 시라니까. 네 시 정각.","마음대로 하게. 갈비는 안 기다려 주지만.","벌써 불렀지. 자네보다 먼저 온다고 했어."]', '["At an American cookout a guest always asks \\"What can I bring?\\"","Key words: I''d love to, what can I bring"]', '["미국에서 바비큐에 초대받은 손님은 으레 \\"What can I bring?\\" 하고 묻습니다.","핵심 단어: I''d love to, what can I bring"]', 'carl', 'Just yourself. Well, maybe some of that lemonade from the market.', '몸만 오면 돼. 뭐, 마켓에서 파는 그 레모네이드나 좀 가져오든가.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_carl', 5, 'carl', 'Carl stands up and lifts the charcoal onto his shoulder.', '칼이 일어나 숯 봉지를 어깨에 멥니다.', 'Four o''clock, the yard behind Maple Street Apartments. Don''t be late. The ribs go fast.', '네 시, 메이플 스트리트 아파트 뒤뜰이야. 늦지 말고. 갈비는 금방 동나니까.', 'Tell him you''ll definitely be there, on time, with what he asked for.', '꼭 가겠다고 하세요. 제시간에, 그가 부탁한 것을 들고요.', '[{"any":["would not miss","be there","see you at four"]}]', 'I wouldn''t miss it. I''ll be there at four, lemonade in hand.', '절대 안 빠지죠. 네 시에 레모네이드 들고 갈게요.', '["Wouldn''t miss it. I''ll be there at four with some iced tea.","Sounds good. I might be a little late, but save me some ribs.","I''ll be there. The yard behind Oak Street, right? At four."]', '["절대 안 빠지죠. 네 시에 아이스티 좀 들고 갈게요.","좋아요. 조금 늦을 수도 있는데, 갈비 좀 남겨 주세요.","갈게요. 오크 스트리트 뒤뜰 맞죠? 네 시에요."]', '["Iced tea? I was hoping for that lemonade.","Late? I told you, the ribs go fast.","Maple Street Apartments, Priya. I just told you."]', '["아이스티? 그 레모네이드를 기대했는데.","늦는다고? 갈비는 금방 동난다고 했잖나.","메이플 스트리트 아파트야, 프리야. 방금 말했잖나."]', '["\\"I wouldn''t miss it\\" is a warm, strong yes.","Key words: I wouldn''t miss it, I''ll be there at four"]', '["\\"I wouldn''t miss it\\"은 따뜻하면서도 힘 있는 승낙입니다.","핵심 단어: I wouldn''t miss it, I''ll be there at four"]', 'carl', 'See you at four, Priya. Bring an appetite.', '네 시에 보세, 프리야. 배는 비워서 오고.'),
  ('pr_w2_rainy', 1, 'rosa', 'Sunday. The shower starts when you are one block from the diner. You run the rest of the way.', '일요일입니다. 다이너까지 한 블록 남았을 때 소나기가 쏟아집니다. 남은 길을 뛰어갑니다.', 'Hi, hon! Look at you, you''re soaked. Did you get caught in the rain?', '어서 와요! 세상에, 흠뻑 젖었네. 비 맞았어요?', 'Explain why you''re soaked, and ask whether you can take a seat at the counter.', '왜 흠뻑 젖었는지 말하고, 카운터에 앉아도 되는지 물어보세요.', '[{"any":["downpour","caught in","at the counter"]}]', 'I got caught in a downpour without my umbrella. Is it okay if I sit at the counter?', '우산 없이 나왔다가 소나기를 만났어요. 카운터에 앉아도 될까요?', '["I got caught in the rain because my umbrella broke on the way. Can I sit at a booth?","Yeah, obviously. Can I get a towel or something? I''m dripping everywhere here.","It''s really pouring out there. Could I just get a coffee to go, please?"]', '["오는 길에 우산이 망가져서 비를 맞았어요. 부스 자리에 앉아도 돼요?","보면 알잖아요. 수건 같은 거 있어요? 여기 물이 줄줄 흐르는데요.","밖에 비가 엄청 쏟아져요. 그냥 커피 한 잔만 포장해 갈 수 있을까요?"]', '["A booth? Sure, though the counter''s warmer, hon.","Well, hello to you too. I''ll see what I can find.","To go? In this? Sit down a minute, hon."]', '["부스요? 그래요. 카운터가 더 따뜻하긴 하지만요.","어머, 인사부터 하지. 뭐가 있나 볼게요.","포장이요? 이 비에요? 잠깐 앉았다 가요."]', '["\\"Get caught in\\" the rain = be outside when it starts. Very heavy rain is a \\"downpour\\".","Key words: got caught in a downpour, sit at the counter"]', '["비에 get caught in했다는 것은 밖에 있다가 비를 만났다는 뜻입니다. 아주 세찬 비는 downpour입니다.","핵심 단어: got caught in a downpour, sit at the counter"]', 'rosa', 'Sit anywhere, hon. Let me get you some coffee to warm you up.', '아무 데나 앉아요. 몸 좀 녹이게 커피부터 줄게요.'),
  ('pr_w2_rainy', 2, 'rosa', 'The coffee is hot and the windows are steamed up.', '커피는 뜨겁고 창문에는 김이 서려 있습니다.', 'Now, what can I get you?', '자, 뭐 줄까요?', 'Let her choose: ask what''s good when it''s cold and wet out.', '로사에게 맡겨 보세요. 이렇게 춥고 비 오는 날에는 뭐가 좋은지 물어보세요.', '[{"any":["recommend","day like this","what is good"]}]', 'What do you recommend on a day like this?', '이런 날에는 뭐가 좋아요? 추천해 주세요.', '["Just a salad and an iced tea, please.","Whatever''s fastest. I don''t want to wait.","What''s popular for brunch on a Saturday?"]', '["그냥 샐러드랑 아이스티 한 잔 주세요.","제일 빨리 되는 걸로요. 기다리기 싫어요.","토요일 브런치로는 뭐가 인기예요?"]', '["Iced tea? You sure, hon? You''re shivering.","Okay... the kitchen''s quick today anyway.","It''s Sunday, hon. But I know just the thing."]', '["아이스티요? 정말요? 덜덜 떨고 있는데.","그래요… 어차피 오늘은 주방이 빨라요.","오늘 일요일이에요. 그래도 딱 맞는 게 있죠."]', '["Let the expert choose: \\"What do you recommend …?\\"","Key words: what do you recommend, on a day like this"]', '["전문가에게 맡기세요. \\"What do you recommend …?\\"","핵심 단어: what do you recommend, on a day like this"]', 'rosa', 'Chicken noodle soup and a grilled cheese. It''s what I''d have. Cup or bowl?', '치킨 누들 수프에 그릴드 치즈죠. 나라면 그걸 먹겠어요. 컵으로 줄까요, 볼로 줄까요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_rainy', 3, 'rosa', 'A cup is small. A bowl is a meal.', '컵은 작습니다. 볼은 한 끼가 됩니다.', 'Cup or bowl, hon?', '컵으로 줄까요, 볼로 줄까요?', 'Go for the bigger size, take the sandwich too, and say you need something warm and filling.', '큰 쪽으로 하고 샌드위치도 같이 시키세요. 따뜻하고 든든한 게 필요하다고요.', '[{"any":["bowl","comfort food"]}]', 'A bowl, please, with the grilled cheese. I could use some comfort food.', '볼로 주세요. 그릴드 치즈도요. 마음 편해지는 음식이 좀 필요하네요.', '["A cup, please, with the grilled cheese. I''m really hungry today.","A bowl, please, but skip the grilled cheese. I''m not all that hungry today.","Whichever''s bigger, I guess. Just bring it out fast, I''m starving."]', '["컵으로 주세요. 그릴드 치즈도요. 오늘 정말 배고프거든요.","볼로 주세요. 그릴드 치즈는 빼고요. 오늘은 그렇게 배고프진 않아요.","큰 걸로요, 뭐. 빨리만 갖다주세요. 배고파 죽겠어요."]', '["A cup won''t fill you up, hon. You sure?","No grilled cheese? Your loss. It''s the best in town.","Coming, coming. The kitchen''s doing its best."]', '["컵으로는 배 안 찰 텐데요. 괜찮겠어요?","그릴드 치즈를 빼요? 손해예요. 이 동네에서 제일 맛있는데.","가요, 가요. 주방도 최선을 다하고 있어요."]', '["\\"I could use …\\" = I would really like or need it.","Key words: a bowl, the grilled cheese, I could use, comfort food"]', '["\\"I could use …\\"는 그것이 정말 필요하거나 반갑겠다는 뜻입니다.","핵심 단어: a bowl, the grilled cheese, I could use, comfort food"]', 'rosa', 'One bowl, one grilled cheese. Coming right up.', '수프 한 볼, 그릴드 치즈 하나. 금방 나와요.'),
  ('pr_w2_rainy', 4, 'rosa', 'The bowl is empty. Outside it is still coming down.', '그릇이 비었습니다. 밖에는 아직도 비가 쏟아집니다.', 'More coffee, hon? Refills are free.', '커피 더 줄까요? 리필은 공짜예요.', 'Accept the refill, and tell her you plan to stay until the rain stops.', '리필을 받고, 비가 그칠 때까지 있겠다고 하세요.', '[{"any":["wait out","no hurry","no rush"]}]', 'Yes, please. I''m in no hurry. I''ll wait out the rain.', '네, 주세요. 급할 거 없어요. 비 그칠 때까지 있을게요.', '["No, thanks. I should get going before it gets worse.","Yes, please. How much do I owe you for the refill, then?","Fill it up. And keep it coming, I''m staying a while."]', '["아니요, 괜찮아요. 더 심해지기 전에 가 봐야겠어요.","네, 주세요. 그런데 리필은 얼마 드리면 되나요?","가득 채워요. 계속 갖다주고요. 한참 있을 거니까."]', '["In this? You''ll get soaked all over again.","Nothing, hon. Refills are free, like I said.","All right, all right. Coming right up."]', '["이 비에요? 또 흠뻑 젖을 텐데.","안 줘도 돼요. 말했잖아요, 리필은 공짜라고.","알았어요, 알았어. 바로 갖다줄게요."]', '["\\"Wait out\\" the rain = stay inside until it stops.","Key words: I''m in no hurry, wait out the rain"]', '["비를 wait out한다는 것은 그칠 때까지 안에서 기다린다는 뜻입니다.","핵심 단어: I''m in no hurry, wait out the rain"]', 'rosa', 'Stay as long as you like. Pie of the day is apple. Can I tempt you with a slice?', '있고 싶은 만큼 있어요. 오늘의 파이는 사과예요. 한 조각 어때요?'),
  ('pr_w2_rainy', 5, 'rosa', 'The pie looks wonderful. But the bowl was big.', '파이가 정말 맛있어 보입니다. 하지만 수프가 한가득이었습니다.', 'It came out of the oven an hour ago.', '한 시간 전에 오븐에서 꺼낸 거예요.', 'You''re too full to eat it now. Find a way to have some later.', '지금은 배가 불러 못 먹습니다. 나중에 먹을 방법을 찾아보세요.', '[{"any":["to go","stuffed"]}]', 'I''m stuffed, but could I get a slice to go?', '배가 꽉 찼는데, 한 조각 포장해 갈 수 있을까요?', '["I''m stuffed. Could I get a slice of cherry to go?","Sure, I''ll have a slice here with my coffee.","No pie for me. Just bring me the check."]', '["배가 꽉 찼어요. 체리 파이 한 조각 포장해 갈 수 있을까요?","좋아요, 여기서 커피랑 한 조각 먹을게요.","파이는 됐어요. 계산서나 갖다주세요."]', '["Cherry''s gone, hon. Apple''s the pie of the day.","Room for pie after that bowl? I''m impressed.","Oh. Okay, hon. Here it comes."]', '["체리는 다 나갔어요. 오늘의 파이는 사과예요.","그 수프를 다 먹고도 파이 들어갈 자리가 있어요? 대단하네.","아. 그래요. 여기 있어요."]', '["\\"Stuffed\\" = very full. Food you take with you is \\"to go\\".","Key words: I''m stuffed, a slice to go"]', '["stuffed는 배가 아주 부르다는 뜻입니다. 가지고 가는 음식은 to go라고 합니다.","핵심 단어: I''m stuffed, a slice to go"]', 'rosa', 'One slice of apple, boxed up. Here''s your check, hon: sixteen dollars, so seventeen thirty-two with tax.', '사과 파이 한 조각, 포장해 줄게요. 계산서 여기 있어요. 16달러니까, 세금 포함해서 17달러 32센트예요.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w2_rainy', 6, 'rosa', 'You put a twenty on the counter. That leaves $2.68 for Rosa, about seventeen percent of sixteen dollars.', '카운터에 20달러 지폐를 올려놓습니다. 로사에게 2달러 68센트가 남으니, 16달러의 17퍼센트쯤 됩니다.', 'Let me get your change.', '거스름돈 갖다줄게요.', 'The $2.68 left over is a fair tip. Let her know she doesn''t need to bring anything back.', '남는 2달러 68센트면 적당한 팁입니다. 아무것도 가져다줄 필요 없다고 하세요.', '[{"any":["keep the change","keep it"]}]', 'That''s okay. Keep the change.', '괜찮아요. 잔돈은 가지세요.', '["Just give me back two dollars.","Thanks. I''ll tip on my card.","Sure. Can I get it in quarters?"]', '["2달러만 거슬러 주세요.","고마워요. 팁은 카드로 줄게요.","네. 25센트짜리로 줄 수 있어요?"]', '["Two dollars. Sure, hon.","Your card? You paid cash, hon.","Quarters? Let me check the register."]', '["2달러요. 그래요.","카드요? 현금으로 냈잖아요.","25센트짜리요? 계산대 좀 볼게요."]', '["With cash, the change can be the tip. Check that it is 15 to 20 percent.","Key words: that''s okay, keep the change"]', '["현금으로 낼 때는 거스름돈을 팁으로 남길 수 있습니다. 15~20퍼센트가 되는지 확인하세요.","핵심 단어: that''s okay, keep the change"]', 'rosa', 'Thank you, hon! Look, the sun''s coming out. Stay dry out there.', '고마워요! 저기 봐요, 해가 나네요. 비 맞지 말고 가요.'),
  ('w_brunch', 1, 'rosa', 'It is a weekend morning and the diner is busy. Rosa comes over with a coffee pot.', '주말 아침, 다이너가 붐빕니다. 로사가 커피 주전자를 들고 옵니다.', 'Morning, hon! Coffee to start?', '좋은 아침이에요, 자기! 커피부터 줄까요?', 'You''d love a coffee. You also need to see what they''re serving.', '커피를 마시고 싶습니다. 무엇을 파는지도 봐야 합니다.', '[{"all":["menu"]},{"all":["yes","please"]},{"all":["coffee","please"]}]', 'Yes, please. And could I see the brunch menu?', '네, 주세요. 그리고 브런치 메뉴 좀 볼 수 있을까요?', '["No thanks, just water. Can I see the menu?","Sure. And hurry with the menu, I''m starving.","Yes, please. And could I see the dinner menu?"]', '["아뇨, 물만 주세요. 메뉴 좀 볼 수 있을까요?","네. 메뉴도 빨리 줘요, 배고파 죽겠어요.","네, 주세요. 그리고 저녁 메뉴 좀 볼 수 있을까요?"]', '["Water it is. You sure? It''s a fresh pot.","Okay, okay. Hold your horses, hon.","Dinner? Hon, it''s ten in the morning. Here''s brunch."]', '["물로 할게요. 정말요? 방금 내린 커피인데.","알았어요, 알았어. 진정해요, 자기.","저녁이요? 자기, 지금 아침 열 시예요. 여기 브런치 메뉴요."]', '["Accept the coffee and ask for something to read.","Key words: yes please, brunch menu"]', '["커피를 받고 메뉴를 달라고 하세요.","핵심 단어: yes please, brunch menu"]', 'rosa', 'Here you go. The special today is the veggie omelet.', '여기요. 오늘의 스페셜은 채소 오믈렛이에요.'),
  ('w_brunch', 2, 'rosa', 'You know exactly what you want.', '먹고 싶은 게 분명합니다.', 'Ready to order?', '주문하시겠어요?', 'Order what you want: two eggs flipped with the yolks still runny, plus bacon and wheat toast.', '원하는 걸 주문하세요. 노른자가 흐르게 뒤집어 익힌 달걀 두 개, 베이컨, 통밀 토스트입니다.', '[{"any":["over easy","scrambled","sunny side up","eggs","omelet","pancakes","waffles"]}]', 'Yes. Can I get two eggs over easy, with bacon and wheat toast?', '네. 달걀 두 개 오버 이지로, 베이컨이랑 통밀 토스트 주실래요?', '["Yes. Can I get two eggs sunny side up, with sausage and white toast?","Two eggs, bacon, wheat toast. And don''t mess up the eggs this time.","What do you recommend? I can''t decide between all of these."]', '["네. 달걀 두 개 서니 사이드 업으로, 소시지랑 흰 식빵 토스트 주실래요?","달걀 두 개, 베이컨, 통밀 토스트요. 이번엔 달걀 망치지 마시고요.","뭐가 맛있어요? 이것저것 많아서 못 고르겠어요."]', '["Sunny side up, sausage, white toast. You got it.","Wow, okay. I''ll tell the cook to be extra careful.","The special''s good. But you look like you know what you want."]', '["서니 사이드 업, 소시지, 흰 식빵. 알겠어요.","와, 그래요. 요리사한테 특별히 조심하라고 할게요.","스페셜이 맛있어요. 근데 먹고 싶은 게 있는 얼굴인데요."]', '["Say how you want your eggs.","Key words: can I get, eggs over easy"]', '["달걀을 어떻게 해 달라고 할지 말하세요.","핵심 단어: can I get, eggs over easy"]', 'rosa', 'You got it. Hash browns or home fries with that?', '알겠어요. 해시 브라운이요, 홈 프라이요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_brunch', 3, 'rosa', 'Both are fried potatoes, cut differently.', '둘 다 감자 요리인데 써는 방식이 다릅니다.', 'Hash browns or home fries?', '해시 브라운이요, 홈 프라이요?', 'You like the shredded, crispy kind. Pick that one.', '잘게 채 썰어 바삭하게 부친 쪽이 좋습니다. 그걸 고르세요.', '[{"any":["hash browns","hash brown","home fries"]}]', 'Hash browns, please.', '해시 브라운으로 주세요.', '["Home fries, please.","Both, if that''s okay?","Whatever. Doesn''t matter."]', '["홈 프라이로 주세요.","둘 다 주시면 안 돼요?","아무거나요. 상관없어요."]', '["Home fries it is. The chunky ones, right?","Both? That''s extra, hon. Just pick one?","Okay… I''ll surprise you, then."]', '["홈 프라이로요. 깍둑썰기한 거 맞죠?","둘 다요? 그럼 추가 요금이에요, 자기. 하나만 고를래요?","그래요… 그럼 내 맘대로 줄게요."]', '["Pick a side.","Key words: hash browns or home fries"]', '["곁들임을 고르세요.","핵심 단어: hash browns 또는 home fries"]', 'rosa', 'Great choice. Coming right up.', '좋은 선택이에요. 금방 나와요.'),
  ('w_brunch', 4, 'rosa', 'You have finished eating. Your coffee cup is empty.', '다 먹었습니다. 커피 잔이 비었습니다.', 'How''s everything tasting?', '음식은 입에 맞아요?', 'You enjoyed it. You''d like more coffee, and you''re ready to pay.', '맛있게 먹었습니다. 커피를 더 마시고 싶고, 계산할 준비가 됐습니다.', '[{"any":["refill","check","bill","top up"]}]', 'Everything''s great, thanks. Could I get a refill and the check, please?', '다 맛있어요, 고마워요. 커피 리필이랑 계산서 좀 주실래요?', '["Everything''s great, thanks. Could I get a refill and a slice of apple pie?","Fine. The eggs were a bit cold. Just bring me the check already.","It''s great! Could you wrap up the rest for me to take home?"]', '["다 맛있어요, 고마워요. 커피 리필이랑 사과 파이 한 조각 주실래요?","그냥 그래요. 달걀이 좀 식었더라고요. 계산서나 빨리 줘요.","맛있어요! 남은 건 싸 가게 포장해 주실래요?"]', '["Sure! One slice of apple pie. I''ll hold the check, then.","Oh, sorry, hon. I can have them make you fresh ones.","Wrap it? Your plate''s clean, hon!"]', '["그럼요! 사과 파이 한 조각이요. 그럼 계산서는 이따 줄게요.","어머, 미안해요, 자기. 새로 만들어 달라고 할게요.","포장이요? 접시가 싹 비었는데요, 자기!"]', '["Ask for more coffee and the bill.","Key words: refill, the check"]', '["커피 한 잔 더와 계산서를 달라고 하세요.","핵심 단어: refill, the check"]', 'rosa', 'Sure thing. That''s fourteen fifty. No rush.', '그럼요. 14달러 50센트예요. 천천히 하세요.'),
  ('w_brunch', 5, 'rosa', 'The bill is $14.50. You pay with a twenty, and the rest is her tip.', '14달러 50센트입니다. 20달러를 내고 나머지는 팁으로 줍니다.', 'Do you need change?', '거스름돈 드릴까요?', 'The extra $5.50 is her tip. Let her know.', '남는 5달러 50센트는 팁입니다. 그렇게 전하세요.', '[{"all":["keep the change"]},{"all":["keep it"]},{"all":["no change"]},{"all":["all set"]}]', 'No, keep the change. Thanks, Rosa!', '아뇨, 잔돈은 가지세요. 고마워요, 로사!', '["Yes, could I get five fifty back?","Just a dollar back, please, thanks.","Keep it. You''ll need it more than me."]', '["네, 5달러 50센트 거슬러 주실래요?","1달러만 거슬러 주세요, 고마워요.","가지세요. 저보다 더 필요하실 테니까."]', '["Sure thing. Be right back with your change.","One dollar back. Here you go, hon.","Uh… thanks, I guess."]', '["그럼요. 금방 거스름돈 가져올게요.","1달러 거스름돈요. 여기요, 자기.","어… 고맙다고 해야겠죠."]', '["Let her keep the rest as a tip.","Key words: keep the change"]', '["나머지를 팁으로 주세요.","핵심 단어: keep the change"]', 'rosa', 'Aw, thanks, hon. Have a good weekend!', '어머, 고마워요. 좋은 주말 보내요!'),
  ('w_faucet', 1, 'carl', 'Your kitchen faucet dripped all night. You find Carl watering the plants in front of the building.', '부엌 수도꼭지가 밤새 똑똑 샜습니다. 건물 앞에서 화초에 물을 주는 칼을 만납니다.', 'Morning, kid! Everything okay up there?', '잘 잤어? 위층은 별일 없고?', 'Tell him about the problem in your kitchen.', '부엌에 생긴 문제를 그에게 말하세요.', '[{"any":["leaking","leaky","leaks","dripping","drips","faucet"]}]', 'Not really. My kitchen faucet is leaking. It dripped all night.', '별로요. 부엌 수도꼭지가 새요. 밤새 똑똑 떨어졌어요.', '["Not really. My bathroom sink is leaking. It dripped all night.","Not really. The plumbing in this place is a total mess.","Yeah, all good! Just a tiny drip in the kitchen, no big deal."]', '["별로요. 화장실 세면대가 새요. 밤새 똑똑 떨어졌어요.","별로요. 이 집 배관은 완전 엉망이에요.","네, 괜찮아요! 부엌에서 조금 새는 정도라 별거 아니에요."]', '["The bathroom? Huh. I just fixed that one last month.","Whoa, easy. What''s going on exactly?","A drip''s never no big deal, kid. That''s my water bill."]', '["화장실? 허. 그건 지난달에 고쳤는데.","어이, 진정해. 정확히 뭐가 문젠데?","새는 게 별게 아닐 리 없지. 내 수도 요금이라고."]', '["Say what is wrong in your kitchen.","Key words: faucet, leaking"]', '["부엌에 무엇이 문제인지 말하세요.","핵심 단어: faucet, leaking"]', 'carl', 'Ah, shoot. Probably the washer. Happens in these old buildings.', '아이고. 아마 고무 패킹일 거야. 이런 오래된 건물에선 흔해.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_faucet', 2, 'carl', 'Carl puts down the watering can.', '칼이 물뿌리개를 내려놓습니다.', 'I can come take a look. When''s a good time?', '내가 가서 봐 줄게. 언제가 좋아?', 'You''ll be home all day. Ask him to come later today.', '오늘 하루 종일 집에 있습니다. 오늘 중으로 와 달라고 하세요.', '[{"any":["afternoon","today","now","this morning","tonight","anytime","any time"]}]', 'Could you come by this afternoon? I''ll be home all day.', '오늘 오후에 와 주실 수 있어요? 하루 종일 집에 있어요.', '["Could you come by this afternoon? I''ll be at work till six.","Can you come right now? It''s driving me crazy.","Whenever. Or I can just call a plumber myself."]', '["오늘 오후에 와 주실 수 있어요? 전 여섯 시까지 회사에 있어요.","지금 바로 와 주실래요? 미치겠어요.","아무 때나요. 아니면 제가 배관공 부를게요."]', '["At work on a Saturday? Then when do you want me?","Hold your horses, I''m in the middle of the plants here.","No, no, don''t do that. I handle the repairs here."]', '["토요일에 회사? 그럼 언제 오라는 거야?","진정해, 나 지금 화초에 물 주는 중이야.","아냐, 그러지 마. 여기 수리는 내가 해."]', '["Use \\"Could you come by …?\\"","Key words: come by, this afternoon"]', '["\\"Could you come by …?\\"를 쓰세요.","핵심 단어: come by, this afternoon"]', 'carl', 'Sure thing.', '그러지.'),
  ('w_faucet', 3, 'carl', 'He checks his watch.', '그가 시계를 봅니다.', 'How''s three o''clock? I''ll bring my toolbox.', '세 시 어때? 공구 상자 들고 갈게.', 'The time he suggests works for you. Let him know and thank him.', '그가 말한 시간이 괜찮습니다. 그렇게 전하고 고맙다고 하세요.', '[{"any":["three","3","works","perfect","great","sounds good"]}]', 'Three works. Thanks a lot.', '세 시 좋아요. 정말 고마워요.', '["Two works. Thanks a lot.","Okay. Don''t be late, though.","Should I buy the parts first?"]', '["두 시 좋아요. 정말 고마워요.","네. 늦지만 마세요.","제가 부품을 먼저 사 둘까요?"]', '["I said three, kid. I''ve got to eat lunch first.","Ha. I''ve been fixing this place since before you were born.","Nah, I''ve got washers. So does three work or not?"]', '["세 시라니까. 점심부터 먹어야지.","하. 네가 태어나기 전부터 이 집 고쳐 왔어.","아냐, 패킹은 있어. 그래서 세 시 괜찮아?"]', '["Say the time is okay.","Key words: three works"]', '["그 시간이 괜찮다고 하세요.","핵심 단어: three works"]', 'carl', 'No problem.', '별말을.'),
  ('w_faucet', 4, 'carl', 'You also have a pile of laundry and no idea where to wash it.', '빨래도 잔뜩 쌓였는데 어디서 빨아야 할지 모릅니다.', 'Anything else while I''m at it?', '온 김에 또 필요한 거 있어?', 'Your dirty clothes are piling up. Find out where to wash them and what it costs.', '빨랫감이 쌓여 있습니다. 어디서 빨 수 있는지, 얼마인지 물어보세요.', '[{"all":["laundry"]},{"all":["washer"]},{"all":["washing"]},{"all":["dryer"]}]', 'Actually, yes. Where''s the laundry room, and how much is a load?', '사실 있어요. 세탁실이 어디예요? 한 번 돌리는 데 얼마예요?', '["Actually, yes. Could you do my laundry too while you''re up there this afternoon?","Actually, yes. Is the laundromat on Main open on weekends?","Actually, yes. Could you lower my rent since the sink leaks?"]', '["사실 있어요. 오후에 올라오신 김에 제 빨래도 좀 해 주실래요?","사실 있어요. 메인가 빨래방이 주말에도 열어요?","사실 있어요. 싱크대가 새니까 월세 좀 깎아 주실래요?"]', '["Ha! Nice try. I''m a landlord, not a laundromat.","Why pay downtown prices? We''ve got machines right here.","Whoa, it''s a drip, not a flood. I''m fixing it today."]', '["하! 꿈도 크네. 난 집주인이지 빨래방이 아니야.","왜 시내 가격을 내? 여기 건물에도 기계 있어.","어이, 물 좀 새는 거지 홍수가 아니잖아. 오늘 고칠 거야."]', '["Ask \\"Where''s the …, and how much is …?\\"","Key words: laundry room, a load"]', '["\\"Where''s the …, and how much is …?\\"로 물어보세요.","핵심 단어: laundry room, a load"]', 'carl', 'Basement, next to the storage lockers. Two seventy-five a load. It takes quarters or the app.', '지하실, 창고 사물함 옆이야. 한 번에 2달러 75센트. 25센트 동전이나 앱으로 돼.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_market', 1, 'mike', 'Mike recognizes you from your first visit.', '마이크가 처음 왔을 때의 당신을 알아봅니다.', 'Hey, welcome back! Stocking up for the week?', '어서 오세요, 또 오셨네요! 일주일 치 장 보시는 거예요?', 'Say yes, and check that the strawberry deal is still on: buy a box, get a second one free.', '그렇다고 하고, 딸기 행사가 아직 하는지 확인하세요. 한 상자를 사면 한 상자가 공짜예요.', '[{"any":["sale","bogo","buy one","deal","discount","free"]}]', 'Yeah. Are the strawberries still buy one, get one free?', '네. 딸기 아직 하나 사면 하나 공짜예요?', '["Yeah. Are the strawberries still half off this week?","Yeah. Can you just ring me up fast? I''m in a rush.","No, just a few things. Do you have reusable bags?"]', '["네. 딸기 이번 주에 아직 반값이에요?","네. 그냥 빨리 계산해 주실래요? 제가 급해서요.","아뇨, 몇 개만요. 장바구니 있어요?"]', '["Half off? No, it''s a different deal. You get a free box.","Sure thing. No rush, though, nobody''s behind you.","Bags are a dime each. Anything else you wanted to ask?"]', '["반값요? 아뇨, 다른 행사예요. 한 상자를 공짜로 드려요.","그럼요. 근데 서두를 필요 없어요, 뒤에 아무도 없어요.","봉투는 하나에 10센트예요. 다른 거 물어볼 거 있으세요?"]', '["Ask about the deal on strawberries.","Key words: buy one, get one free"]', '["딸기 할인에 대해 물어보세요.","핵심 단어: buy one, get one free"]', 'mike', 'They sure are. Looks like you only grabbed one box, though.', '네, 맞아요. 그런데 한 상자만 가져오셨네요.'),
  ('w_market', 2, 'mike', 'There is nobody behind you in line.', '당신 뒤에 줄 선 사람이 없습니다.', 'Want to go grab another one? I can wait.', '하나 더 가져올래요? 기다릴게요.', 'You''d like the free second box. Take him up on his offer.', '공짜 두 번째 상자를 받고 싶습니다. 그의 제안을 받아들이세요.', '[{"all":["right back"]},{"all":["be quick"]},{"all":["one sec"]},{"all":["one second"]},{"all":["be back"]}]', 'Oh, thanks! I''ll be right back.', '어, 고마워요! 금방 올게요.', '["No thanks, one box is plenty.","Can you go get it for me?","Sure! Let the next person go ahead."]', '["괜찮아요, 한 상자면 충분해요.","가서 좀 가져다주실래요?","네! 다음 분 먼저 하세요."]', '["Your call, but the second one''s free.","Uh, I kind of have to stay at the register.","Ha, there''s nobody back there. Go ahead, I''ll wait."]', '["알아서 하세요, 근데 두 번째는 공짜예요.","어, 저는 계산대를 지켜야 해서요.","하, 뒤에 아무도 없어요. 다녀와요, 기다릴게요."]', '["Say you will come back very soon.","Key words: right back"]', '["금방 돌아오겠다고 하세요.","핵심 단어: right back"]', 'mike', 'Take your time.', '천천히 다녀와요.'),
  ('w_market', 3, 'mike', 'You come back with a second box of strawberries.', '딸기 한 상자를 더 들고 돌아옵니다.', 'Alright. Did you want to use your rewards number today?', '좋아요. 오늘 리워드 번호 쓰실 거예요?', 'Say yes, and that you''ll enter your phone number on the keypad yourself.', '네라고 하고, 키패드에 직접 전화번호를 입력하겠다고 하세요.', '[{"any":["phone","number","type","enter","punch"]}]', 'Yes, please. I''ll punch in my phone number.', '네, 쓸게요. 전화번호 누를게요.', '["No thanks, I don''t really care about points.","Yes, please. I''ll scan my rewards card.","Yeah, whatever saves me money. Just hurry, please."]', '["아뇨, 전 포인트에 별 관심 없어요.","네, 쓸게요. 리워드 카드 찍을게요.","네, 돈 아끼는 거면 뭐든요. 빨리만 해 주세요."]', '["You sure? You''d miss out on the sale prices.","Sure. Wait, didn''t you sign up with your phone last time?","Okay, okay. The keypad''s right there."]', '["정말요? 할인가를 못 받으실 텐데요.","그러세요. 어, 지난번에 전화번호로 가입하지 않았어요?","네, 네. 키패드 바로 거기 있어요."]', '["Remember \\"punch in\\" from the checkout last time.","Key words: punch in, phone number"]', '["지난번 계산대에서 배운 punch in을 떠올리세요.","핵심 단어: punch in, phone number"]', 'mike', 'You saved four dollars and twelve cents today. Nice!', '오늘 4달러 12센트 아끼셨어요. 좋네요!'),
  ('w_market', 4, 'mike', 'The card reader shows a question.', '카드 단말기에 질문이 뜹니다.', 'Would you like any cash back?', '현금 인출도 해 드릴까요?', 'You don''t need any cash today. Decline.', '오늘은 현금이 필요 없습니다. 거절하세요.', '[{"all":["no"],"any":["thanks","thank","good","fine","okay"]},{"all":["i am good"]},{"all":["all set"]}]', 'No, thanks. I''m good.', '아뇨, 괜찮아요. 됐어요.', '["Yes, twenty, please.","No. Why would I?","Is there a fee for that?"]', '["네, 20달러요.","아뇨. 제가 왜요?","그거 수수료 있어요?"]', '["Twenty? Sure, just hit Yes on the reader.","Just asking. Some folks like it.","Nope, it''s free. So, any cash back?"]', '["20달러요? 네, 단말기에서 ''예'' 누르세요.","그냥 여쭤본 거예요. 좋아하는 분들도 있어서요.","아뇨, 무료예요. 그래서, 인출하실래요?"]', '["A polite no: \\"No, thanks. I''m good.\\"","Key words: no thanks, I''m good"]', '["정중한 거절: \\"No, thanks. I''m good.\\"","핵심 단어: no thanks, I''m good"]', 'mike', 'You got it. Here''s your receipt. Have a good weekend!', '알겠어요. 영수증 여기요. 좋은 주말 보내요!');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_neighbor_bbq', 1, 'carl', 'It is the weekend. Carl is out by the bus stop, walking his dog.', '주말입니다. 칼이 버스 정류장 근처에서 개를 산책시키고 있습니다.', 'Hey, stranger! Haven''t seen you around all week.', '이게 누구야! 일주일 내내 통 안 보이던데.', 'Tell him why you''ve been gone: work took you to Ridgeport all week.', '왜 안 보였는지 말하세요. 일 때문에 한 주 내내 리지포트에 있었습니다.', '[{"all":["trip"]},{"any":["traveling","travelling"]},{"all":["ridgeport"]},{"all":["out of town"]}]', 'Yeah, I was on a business trip to Ridgeport. I just got back last night.', '네, 리지포트로 출장 갔었어요. 어젯밤에 막 돌아왔어요.', '["Yeah, I was visiting family over in Ridgeport. I just got back last night.","I''ve been around. I just don''t really like hanging out outside much.","Have you? I''ve been busy. Your dog''s gotten so big, by the way!"]', '["네, 리지포트에 가족 보러 갔었어요. 어젯밤에 막 왔어요.","있긴 있었어요. 그냥 밖에 잘 안 나다녀서요.","그래요? 좀 바빴어요. 그나저나 강아지 많이 컸네요!"]', '["Oh, nice! I didn''t know you had family out there.","Ha, fair enough. Just making sure you''re alive in there.","Ha, she eats like a horse. But seriously, where''ve you been?"]', '["오, 좋네요! 거기 가족이 있는 줄은 몰랐어요.","하, 그럴 수 있죠. 그냥 살아 있나 확인한 거예요.","하, 얘가 엄청 먹어요. 근데 진짜 어디 갔었어요?"]', '["Say where you were.","Key words: business trip, just got back"]', '["어디 있었는지 말하세요.","핵심 단어: business trip, just got back"]', 'carl', 'Ridgeport! How''d it go?', '리지포트! 어떻게 됐어요?'),
  ('w_neighbor_bbq', 2, 'carl', 'The contract was signed on Friday.', '금요일에 계약이 체결됐습니다.', 'How''d it go?', '어떻게 됐어요?', 'Share the good news from Friday.', '금요일에 있었던 좋은 소식을 전하세요.', '[{"all":["closed"]},{"all":["signed"]},{"all":["went","well"]},{"all":["deal"]}]', 'It went really well. We closed the deal!', '아주 잘 됐어요. 계약 따냈어요!', '["Not great, honestly. The client backed out.","Pretty good. I''ll know if we got it next week.","Amazing. Basically I closed it all by myself."]', '["솔직히 별로였어요. 고객이 발을 뺐어요.","괜찮았어요. 따냈는지는 다음 주에 알아요.","끝내줬죠. 사실상 저 혼자 다 따냈어요."]', '["Oh no, sorry to hear that. Their loss.","Well, fingers crossed, then!","Ha! Look at you. I''m sure your boss helped a little."]', '["저런, 안됐네요. 그쪽 손해죠.","그럼 잘 되길 빌게요!","하! 대단하네. 그래도 상사가 좀 도와줬겠죠."]', '["Share the good news.","Key words: went really well, closed the deal"]', '["좋은 소식을 전하세요.","핵심 단어: went really well, closed the deal"]', 'carl', 'Well, look at you! Big shot. Hey, did you catch the game last night? What a finish!', '와, 대단한데요! 거물이네. 참, 어젯밤 경기 봤어요? 마무리 끝내줬는데!'),
  ('w_neighbor_bbq', 3, 'carl', 'You did not see the football game. You were busy traveling.', '풋볼 경기를 못 봤습니다. 이동하느라 바빴습니다.', 'Did you catch the game? What a finish!', '경기 봤어요? 마무리 끝내줬는데!', 'You didn''t see it. Be honest, and find out the result.', '경기를 못 봤습니다. 솔직히 말하고 결과를 알아보세요.', '[{"all":["who won"]},{"all":["missed"]},{"all":["final score"]},{"all":["did not see"]}]', 'No, I missed it. I was on a plane. Who won?', '아뇨, 못 봤어요. 비행기 안이었거든요. 누가 이겼어요?', '["Yeah, what a game! Did you see that last play?","No. I don''t really care about football, sorry.","No, I missed it. I was at the office late. Who won?"]', '["네, 경기 대박이었죠! 마지막 플레이 봤어요?","아뇨. 풋볼엔 별 관심이 없어서요, 미안해요.","아뇨, 못 봤어요. 회사에서 늦게까지 있었거든요. 누가 이겼어요?"]', '["Which one? The big catch or the field goal?","Oh. Well, fair enough. Not everybody''s a fan.","At the office? I thought you were out of town."]', '["어떤 거요? 그 멋진 캐치요, 필드골이요?","아. 뭐, 그럴 수 있죠. 다들 팬은 아니니까.","회사에요? 출장 간 줄 알았는데."]', '["Admit you didn''t watch it and ask about the result.","Key words: I missed it, who won"]', '["못 봤다고 하고 결과를 물어보세요.","핵심 단어: I missed it, who won"]', 'carl', 'We did, with a field goal in overtime! Hey, I''m grilling this afternoon. Want to come over?', '우리가 이겼죠, 연장전 필드골로! 참, 오늘 오후에 고기 굽는데 올래요?');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_neighbor_bbq', 4, 'carl', 'Carl is inviting you to his backyard barbecue.', '칼이 뒷마당 바비큐에 초대합니다.', 'Nothing fancy. Burgers, hot dogs, a few neighbors. Four o''clock?', '별거 없어요. 버거, 핫도그, 이웃 몇 명. 4시 어때요?', 'You''d like to go. Offer to contribute something.', '가고 싶습니다. 뭔가 보태겠다고 하세요.', '[{"all":["bring"]},{"all":["what can i"]}]', 'I''d love to! What can I bring?', '좋죠! 뭐 가져갈까요?', '["Sure! See you at seven, then.","I''d love to, but I''m totally wiped.","Sure. Will there be real food, too?"]', '["좋아요! 그럼 7시에 봬요.","가고 싶은데 완전 지쳤어요.","제대로 된 음식도 있죠?"]', '["Seven? No, four! The burgers''ll be gone by seven.","No worries. Rest up. Maybe next time.","Hey, burgers are real food! But okay…"]', '["7시요? 아니, 4시요! 7시면 버거 다 없어져요.","괜찮아요. 푹 쉬어요. 다음에 오면 되죠.","이봐요, 버거도 제대로 된 음식이에요! 뭐, 알았어요…"]', '["Say yes and offer to bring something.","Key words: I''d love to, what can I bring"]', '["좋다고 하고 무언가 가져가겠다고 하세요.","핵심 단어: I''d love to, what can I bring"]', 'carl', 'Just yourself. Maybe some chips if you want. See you at four!', '몸만 와요. 원하면 칩 정도요. 4시에 봐요!'),
  ('w_neighbor_bbq', 5, 'carl', 'At four you show up in Carl''s backyard with a bag of chips. The grill is smoking.', '4시에 칩 한 봉지를 들고 칼의 뒷마당에 갑니다. 그릴에서 연기가 납니다.', 'There you are! How do you like your burger?', '왔네요! 버거는 어떻게 해 줄까요?', 'Tell him how you like it: with cheese, cooked all the way through.', '어떻게 먹고 싶은지 말하세요. 치즈를 얹고 속까지 완전히 익혀서요.', '[{"any":["cheese","cheeseburger","well done","medium","medium rare","no onions","plain"]}]', 'With cheese, please. Well done, if that''s okay.', '치즈 넣어 주세요. 괜찮으면 바싹 익혀서요.', '["With cheese, please. Medium rare, if that''s okay.","Oh, I brought chips. Where should I put them?","Well done, with cheese. And not too greasy, okay?"]', '["치즈 넣어 주세요. 괜찮으면 미디엄 레어로요.","아, 칩 가져왔어요. 어디 둘까요?","바싹 익혀서 치즈 넣고요. 너무 기름지지 않게요, 알았죠?"]', '["Medium rare, you got it. Nice and pink in the middle.","Just on the table there. Thanks! So, how do you want your burger?","Ha, I''ll do my best, chef."]', '["미디엄 레어, 알겠어요. 속은 분홍빛으로.","저 테이블에 두면 돼요. 고마워요! 그래서 버거는 어떻게 해 줄까요?","하, 최선을 다해 보죠, 셰프님."]', '["Say how you want your burger cooked.","Key words: with cheese, well done"]', '["버거를 어떻게 해 줄지 말하세요.","핵심 단어: with cheese, well done"]', 'carl', 'Coming right up. Grab a drink from the cooler and make yourself at home.', '금방 돼요. 아이스박스에서 음료 꺼내고 편하게 있어요.'),
  ('w_park', 1, 'carl', 'It is a sunny weekend morning. Carl is on a park bench with a newspaper and a paper cup of coffee.', '화창한 주말 아침입니다. 칼이 공원 벤치에서 신문과 종이컵 커피를 들고 있습니다.', 'Hey, neighbor! You survived your first week?', '어이, 이웃 양반! 첫 주는 무사히 넘겼나?', 'Tell him how the week went: a lot of work, but you liked it.', '한 주가 어땠는지 말하세요. 일은 많았지만 좋았어요.', '[{"any":["busy","survived","barely","good","great","long","crazy","intense"]}]', 'Barely! It was busy, but good.', '겨우요! 바빴지만 좋았어요.', '["Not really. I think I''m quitting.","Yes, but it''s my second week now.","Barely. Why, did I miss the rent?"]', '["아뇨. 그만둘까 봐요.","네, 근데 이제 둘째 주예요.","겨우요. 왜요, 제가 월세 밀렸어요?"]', '["Whoa, already? That bad, huh?","Second? You just started Monday, kid.","Ha, no! Just being neighborly."]', '["어이쿠, 벌써? 그렇게 힘들었어?","둘째 주? 월요일에 막 시작했잖아.","하, 아니야! 그냥 이웃끼리 인사지."]', '["Answer with one word, then add how the week was.","Key words: barely, busy but good"]', '["한 단어로 답한 뒤 한 주가 어땠는지 덧붙이세요.","핵심 단어: barely, busy but good"]', 'carl', 'Ha! That''s how it goes. The first week''s always a blur.', '하! 원래 그래. 첫 주는 늘 정신없이 지나가지.');
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, line_ko, prompt, prompt_ko, answers, model, model_ko, distractors, distractors_ko, reactions, reactions_ko, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('w_park', 2, 'carl', 'You can hear music and smell kettle corn from the other side of the park.', '공원 건너편에서 음악 소리와 캐틀콘 냄새가 납니다.', 'So, what brings you to the park?', '그래, 공원엔 웬일이야?', 'You came for the weekend market people told you about. Say so.', '사람들이 말해 준 주말 장터 때문에 왔다고 말하세요.', '[{"any":["farmers market","market","farmers"]}]', 'I heard about the farmers market, so I came to check it out.', '파머스 마켓 얘기를 들어서 구경하러 왔어요.', '["I heard there''s a concert today, so I came to see it.","Nothing much. I just wanted to get out of that tiny apartment.","I walk through here every day on my way to the bus stop."]', '["오늘 콘서트가 있다고 해서 보러 왔어요.","별거 아니에요. 그냥 그 좁은 집에서 좀 나오고 싶었어요.","버스 정류장 가는 길에 매일 여길 지나가요."]', '["Concert? Nah, that music''s coming from the market.","Hey, that tiny apartment''s a great deal, kid.","On a Saturday? Ha. Well, since you''re here, look around."]', '["콘서트? 아냐, 그 음악은 장터에서 나는 거야.","이봐, 그 좁은 집이 얼마나 싼 건데.","토요일에? 하. 뭐, 온 김에 구경이나 해."]', '["Use \\"I heard about …, so …\\".","Key words: farmers market, check it out"]', '["\\"I heard about …, so …\\"를 쓰세요.","핵심 단어: farmers market, check it out"]', 'carl', 'Good call. Get the peaches from the stand by the fountain. Best in town.', '잘 왔네. 분수대 옆 가판에서 복숭아를 사. 이 동네 최고야.'),
  ('w_park', 3, 'carl', 'Carl folds his newspaper.', '칼이 신문을 접습니다.', 'Oh, one more thing. Trash and recycling go out Monday night. Bins go out to the curb.', '아, 하나 더. 쓰레기랑 재활용은 월요일 밤에 내놔. 통은 길가에 내놓고.', 'Thank him, then find out which bin your empty bottles and cans go in.', '알려 줘서 고맙다고 하고, 빈 병과 캔은 어느 통에 넣는지 물어보세요.', '[{"all":["which"],"any":["bin","recycling","one","color"]},{"all":["recycling"]}]', 'Thanks for the heads-up. Which bin is for recycling?', '알려 줘서 고마워요. 어느 통이 재활용이에요?', '["Thanks. So the bins go out Tuesday morning, right?","Can''t you just take the bins out for me? I''m pretty busy.","Thanks. Where''s the closest place to buy trash bags?"]', '["고마워요. 그럼 통은 화요일 아침에 내놓는 거죠?","그냥 대신 통 좀 내놔 주시면 안 돼요? 제가 좀 바빠서요.","고마워요. 쓰레기봉투는 어디서 제일 가깝게 사요?"]', '["Monday night, kid. Truck comes early Tuesday.","Ha! I''m your landlord, not your butler.","Hardware store on Elm. But you still need to know the bins."]', '["월요일 밤이야. 트럭이 화요일 새벽에 와.","하! 난 집주인이지 집사가 아니야.","엘름가 철물점. 근데 통부터 알아야지."]', '["Ask \\"Which bin is for …?\\"","Key words: which bin, recycling"]', '["\\"Which bin is for …?\\"로 물어보세요.","핵심 단어: which bin, recycling"]', 'carl', 'Blue one''s recycling, green''s yard waste, and the black one''s regular trash.', '파란 건 재활용, 초록은 정원 쓰레기, 검은 건 일반 쓰레기야.'),
  ('w_park', 4, 'carl', 'He holds up a finger.', '그가 손가락 하나를 들어 보입니다.', 'Just rinse out the cans and bottles first, or the city won''t take ''em.', '캔이랑 병은 먼저 헹궈서 내놔. 안 그러면 시에서 안 가져가.', 'Let him know you''ve taken his tip on board.', '그의 조언을 잘 새겨듣겠다고 하세요.', '[{"any":["remember","got it","will do","okay","ok","sounds good","noted","good to know"]}]', 'Got it. I''ll remember that.', '알겠어요. 기억할게요.', '["Oh. I usually toss them in dirty.","Okay. I''ll rinse the paper too.","Is that really necessary, though?"]', '["아. 전 보통 그냥 버리는데요.","네. 종이도 헹굴게요.","그거 꼭 해야 해요?"]', '["Well, not anymore you don''t.","Paper? No, don''t get paper wet!","It is if you don''t want a fine, kid."]', '["이제부턴 그러면 안 되지.","종이? 아냐, 종이는 적시면 안 돼!","벌금 안 내고 싶으면 해야지."]', '["Say you understand and will remember.","Key words: got it, I''ll remember"]', '["알겠다고, 기억하겠다고 하세요.","핵심 단어: got it, I''ll remember"]', 'carl', 'Enjoy the market, kid.', '마켓 구경 잘 해.');
REPLACE INTO messages (id, hero, day, time, kind, sender, subject, body, body_ko, subject_ko) VALUES
  ('m01_lofts', 'priya', 1, '18:40', 'email', 'Cedar Street Lofts', 'Elevator maintenance on Wednesday', 'The elevator will be out of service Wednesday from 9 to 11 AM for maintenance. We apologize for the inconvenience.', '엘리베이터는 점검 때문에 수요일 오전 9시부터 11시까지 운행하지 않습니다. 불편을 드려 죄송합니다. (out of service: 운행 중지)', '수요일 엘리베이터 점검'),
  ('m01_tom', 'all', 1, '13:10', 'email', 'tom', 'Lunch & Learn this month', 'Hi all, this month''s Lunch & Learn is on the 29th at noon. Pizza is on us. Please RSVP by the 27th so I can get a headcount.', '여러분, 이달의 런치 앤드 런은 29일 정오입니다. 피자는 회사가 삽니다. 인원을 파악할 수 있게 27일까지 참석 여부를 알려 주세요. (RSVP: 참석 여부 회신, headcount: 인원수)', '이달의 런치 앤드 런'),
  ('m03_sam', 'all', 3, '09:40', 'email', 'sam', 'Your password expires in 5 days', 'Your network password expires in 5 days. Change it from the login screen: at least 12 characters, and don''t reuse an old one. IT will never ask for your password by email.', '네트워크 비밀번호가 5일 뒤에 만료됩니다. 로그인 화면에서 바꾸세요. 12자 이상이어야 하고 예전 것을 다시 쓰면 안 됩니다. IT 팀은 이메일로 비밀번호를 묻지 않습니다. (expire: 만료되다)', '비밀번호가 5일 뒤 만료됩니다'),
  ('m05_linda', 'all', 5, '10:00', 'email', 'linda', 'Open enrollment starts Monday', 'Open enrollment for health, dental and vision runs October 12 through 23. If you do nothing, your current plan carries over. New hires have 30 days from their start date. Questions? My door is always open.', '건강·치과·안과 보험의 정기 가입 기간은 10월 12일부터 23일까지입니다. 아무것도 하지 않으면 지금 보험이 그대로 이어집니다. 신입 사원은 입사일부터 30일 안에 가입하면 됩니다. (open enrollment: 보험 정기 가입 기간, carry over: 이어지다)', '월요일부터 보험 정기 가입 기간'),
  ('m06_market', 'all', 6, '09:00', 'email', 'Fairview Market', 'This week''s deals', 'Strawberries are buy one, get one free. Rain in the forecast? Compact umbrellas are in aisle 3. Prices are good through Sunday.', '딸기는 하나 사면 하나 더 드립니다. 비 예보가 있나요? 접이식 우산은 3번 통로에 있습니다. 행사 가격은 일요일까지입니다. (aisle: 통로, good through: ~까지 유효)', '이번 주 할인 상품'),
  ('m07_tom', 'all', 7, '18:00', 'email', 'tom', 'Monday is a regular workday', 'Reminder: the office is open tomorrow. It is a federal holiday, so banks and the post office are closed and the buses run on the weekend timetable. Plan your commute!', '알림: 내일 사무실은 정상 근무입니다. 연방 공휴일이라 은행과 우체국은 쉬고 버스는 주말 시간표로 다닙니다. 출근 계획을 세우세요!', '월요일은 정상 근무일입니다'),
  ('m09_sam', 'all', 9, '15:00', 'email', 'sam', 'Phishing test results', 'Thanks to everyone who reported last week''s test email. If you clicked the link, you will get a short training. When in doubt, forward it to IT.', '지난주 모의 피싱 메일을 신고해 주신 분들 고맙습니다. 링크를 누른 분은 짧은 교육을 받게 됩니다. 의심스러우면 IT 팀으로 전달하세요. (when in doubt: 의심스러울 때는)', '모의 피싱 결과'),
  ('m10_airline', 'jun', 10, '17:00', 'email', 'Crestline Air', 'Check in for your flight to Ridgeport', 'It is time to check in for your flight tomorrow. Check in now to get your boarding pass. Checked bags must be dropped off at least 45 minutes before departure.', '내일 항공편의 체크인이 시작되었습니다. 지금 체크인하고 탑승권을 받으세요. 부치는 짐은 출발 45분 전까지 맡겨야 합니다. (boarding pass: 탑승권)', '리지포트행 항공편 체크인 안내'),
  ('m10_linda', 'all', 10, '09:30', 'email', 'linda', 'Flu shots next Wednesday', 'Free flu shots in the lobby next Wednesday, 10 AM to 2 PM. Bring your insurance card. Walk-ins are welcome.', '다음 주 수요일 오전 10시부터 오후 2시까지 로비에서 독감 예방주사를 무료로 놓아 드립니다. 보험 카드를 가져오세요. 예약 없이 와도 됩니다. (flu shot: 독감 주사, walk-in: 예약 없이 오는 사람)', '다음 주 수요일 독감 예방주사'),
  ('m11_tom', 'all', 11, '08:45', 'email', 'tom', 'Fridge cleanout on Friday', 'Anything left in the kitchen fridge after 4 PM on Friday gets tossed. Please label your food. Thanks for keeping the kitchen clean!', '금요일 오후 4시 이후에 탕비실 냉장고에 남은 것은 모두 버립니다. 음식에 이름을 적어 두세요. (get tossed: 버려지다)', '금요일 냉장고 정리');
REPLACE INTO mail (id, hero, day, kind, sender, subject, body, body_ko, subject_ko) VALUES
  ('mail01_card', 'all', 1, 'letter', 'Fairview Credit Union', 'Your new debit card', 'Your new debit card is enclosed. To activate it, call the number on the sticker. Keep your PIN private, and never write it on the card.', '새 체크카드가 들어 있습니다. 사용하려면 스티커에 적힌 번호로 전화해 활성화하세요. 비밀번호(PIN)는 남에게 알리지 말고 카드에 적지 마세요. (activate: 활성화하다)', '새 체크카드가 도착했습니다'),
  ('mail01_preapproved', 'all', 1, 'junk', 'Current Resident', 'You may already be pre-approved!', 'Congratulations! You may already be pre-approved for a low-rate credit card. Call now. No obligation. This offer expires soon.', '축하합니다! 낮은 금리의 신용카드에 이미 사전 승인되었을 수 있습니다. 지금 전화하세요. (광고 우편입니다. 버려도 됩니다. pre-approved: 사전 승인된)', '이미 사전 승인되셨을 수 있습니다!'),
  ('mail02_laundry_jun', 'jun', 2, 'notice', 'Cedar Court Apartments', 'Laundry room rules', 'The laundry room in the basement is open 7 AM to 10 PM. Washers and dryers are $2.50 a cycle with the laundry app. Please take your clothes out when the cycle ends and clean the lint trap after every load.', '지하 세탁실은 오전 7시부터 오후 10시까지 엽니다. 세탁기와 건조기는 앱으로 1회 2.50달러입니다. 세탁이 끝나면 옷을 바로 꺼내고, 매번 보풀 필터를 청소해 주세요. (cycle: 세탁·건조 1회, lint trap: 건조기 보풀 필터)', '세탁실 이용 규칙'),
  ('mail02_laundry_priya', 'priya', 2, 'notice', 'Cedar Street Lofts', 'Laundry room reminder', 'Friendly reminder: the laundry room on the ground floor is open 7 AM to 10 PM. Machines take the laundry app, $2.50 a cycle. Please don''t leave wet clothes in the washers.', '안내: 1층 세탁실은 오전 7시부터 오후 10시까지 엽니다. 기계는 세탁 앱으로 1회 2.50달러입니다. 젖은 빨래를 세탁기에 두고 가지 마세요. (ground floor: 1층, friendly reminder: 다시 한번 알려 드립니다)', '세탁실 이용 안내'),
  ('mail02_pizza', 'all', 2, 'junk', 'Pizza Palace', 'Two large pizzas, $19.99', 'Two large one-topping pizzas for $19.99. Carry-out or delivery. Expires Oct 31. One coupon per order.', '토핑 하나 라지 피자 두 판에 19.99달러. 포장 또는 배달. 10월 31일까지. 주문 한 건에 쿠폰 한 장. (carry-out: 포장, expires: 만료되다)', '라지 피자 두 판 19.99달러'),
  ('mail02_power', 'all', 2, 'bill', 'Fairview Power & Light', 'Your bill is ready', 'Statement date: Oct 6. Your bill is ready to view online. Your autopay is set up, so you do not need to do anything. Thank you for being a customer.', '명세서 날짜: 10월 6일. 요금 고지서를 온라인에서 볼 수 있습니다. 자동이체가 설정되어 있어 따로 하실 일은 없습니다. (statement: 명세서, autopay: 자동이체)', '요금 고지서가 나왔습니다'),
  ('mail03_hardware', 'all', 3, 'junk', 'Fairview Hardware', 'Fall sale: up to 30% off', 'Rakes, gloves and leaf bags are up to 30% off through Sunday. Bring this flyer to the register.', '갈퀴, 장갑, 낙엽 봉투가 일요일까지 최대 30% 할인입니다. 계산대에 이 전단지를 가져오세요. (flyer: 전단지, register: 계산대)', '가을 세일: 최대 30% 할인'),
  ('mail03_missed', 'all', 3, 'notice', 'Fairview Post Office', 'Sorry we missed you', 'We tried to deliver a package that needed a signature. Pick it up at the post office within 15 days. Bring a photo ID.', '서명이 필요한 소포를 배달하려 했지만 만나지 못했습니다. 15일 안에 우체국에서 찾아가세요. 사진이 붙은 신분증을 가져오세요. (a photo ID: 사진이 붙은 신분증)', '부재중 배달 안내'),
  ('mail04_derek', 'derek', 4, 'card', 'Aunt Rosa', 'Thinking of you', 'Just a little note to say hello. Come by for dinner when you have a free Sunday. We miss you. Love, Aunt Rosa', '안부를 전하려고 몇 자 적어요. 일요일에 시간 나면 저녁 먹으러 와요. 보고 싶어요. 로사 이모가. (come by: 들르다)', '네 생각이 나서'),
  ('mail04_jun', 'jun', 4, 'card', 'Grandma', 'Congratulations on the new job!', 'Congratulations on your new job! I am so proud of you. Have a nice lunch on me. Love, Grandma', '새 직장을 축하한다! 정말 자랑스럽구나. 맛있는 점심을 먹으렴. 사랑한다, 할머니가. (have ... on me: 내가 살게)', '취직 축하한다!'),
  ('mail04_priya', 'priya', 4, 'card', 'Aunt Meera', 'Congratulations, Priya!', 'We heard about your promotion. Congratulations! Your mother tells everyone. Come visit soon. Love, Aunt Meera', '승진 소식 들었다. 축하해! 네 엄마가 만나는 사람마다 자랑한단다. 조만간 놀러 오렴. 미라 이모가. (promotion: 승진)', '축하해, 프리야!'),
  ('mail05_eob', 'all', 5, 'letter', 'Fairview Health Plan', 'Explanation of Benefits', 'This is not a bill. It shows what your plan paid for your recent visit. Keep it for your records.', '청구서가 아닙니다. 최근 진료에서 보험이 무엇을 부담했는지 보여 줍니다. 기록으로 보관하세요. (EOB: 보험금 지급 내역서, records: 기록)', '보험금 지급 내역서'),
  ('mail06_ad', 'all', 6, 'junk', 'Fairview Market', 'Weekly ad', 'Fresh salmon $9.99 a pound. Apples 3 for $2. Fall pumpkins are here! Prices good through Friday.', '신선한 연어 파운드당 9.99달러. 사과 세 개에 2달러. 가을 호박이 나왔어요! 금요일까지 행사 가격입니다. (a pound: 1파운드에)', '주간 전단 광고'),
  ('mail09_fiber', 'all', 9, 'junk', 'Fairview Fiber', 'Switch and save', 'Internet 300 Mbps for $39.99 a month for 12 months, then the regular price applies. Taxes and fees extra.', '인터넷 300Mbps를 12개월 동안 월 39.99달러에 드립니다. 이후에는 정상 요금이 적용됩니다. 세금과 수수료는 별도입니다. (then the regular price applies: 그 뒤에는 정가)', '바꾸고 절약하세요');
REPLACE INTO mail (id, hero, day, kind, sender, subject, body, body_ko, subject_ko) VALUES
  ('mail09_vote', 'all', 9, 'notice', 'City of Fairview', 'Election Day is November 3', 'Election Day is Nov 3. Register to vote by Oct 13, or check your registration online. Polls are open from 7 AM to 8 PM.', '선거일은 11월 3일입니다. 10월 13일까지 유권자 등록을 하거나 등록 상태를 온라인에서 확인하세요. 투표소는 오전 7시부터 오후 8시까지 엽니다. (register to vote: 유권자 등록, polls: 투표소)', '선거일은 11월 3일입니다'),
  ('mail10_statement', 'all', 10, 'letter', 'Fairview Credit Union', 'Your statement is ready', 'Your monthly statement for checking ···4821 is ready. View it online or in the app. Report any error within 60 days.', '입출금 계좌 ···4821의 월 명세서가 나왔습니다. 온라인이나 앱에서 확인하세요. 오류가 있으면 60일 안에 알려 주세요. (statement: 거래 명세서)', '거래 명세서가 나왔습니다'),
  ('mail11_jury', 'all', 11, 'notice', 'Fairview County Court', 'Jury service questionnaire', 'You may be selected for jury service. Complete the questionnaire online within 10 days. Failure to respond may result in a fine.', '배심원으로 선정될 수 있습니다. 10일 안에 온라인으로 설문지를 작성하세요. 답하지 않으면 벌금이 나올 수 있습니다. (jury: 배심원단, fine: 벌금)', '배심원 설문지'),
  ('mail11_lawn', 'all', 11, 'junk', 'Green Thumb Landscaping', 'Fall cleanup special', 'Leaves raked and gutters cleaned, from $99. Free estimates. Call today!', '낙엽 치우기와 배수로 청소가 99달러부터. 견적은 무료입니다. 오늘 전화하세요! (estimate: 견적)', '가을맞이 마당 청소 특가'),
  ('mail12_coupon', 'all', 12, 'junk', 'Fairview Market', '$5 off $30', 'Save $5 when you spend $30 or more. Valid Oct 12 to 18. Not valid with other offers.', '30달러 이상 사면 5달러를 깎아 드립니다. 10월 12일부터 18일까지 유효. 다른 할인과 중복 불가입니다. (valid: 유효한)', '30달러 이상 구매 시 5달러 할인'),
  ('mail12_vision', 'all', 12, 'junk', 'Fairview Vision', 'Your eyes matter', 'It has been over a year since your last eye exam. Book one this month and get 20% off frames.', '마지막 시력 검사를 받은 지 1년이 넘었습니다. 이달에 예약하면 안경테를 20% 깎아 드립니다. (frames: 안경테)', '눈 건강을 챙기세요'),
  ('mail13_derek', 'derek', 13, 'notice', 'Fairview Waste Services', 'New recycling rules', 'Starting Nov 1, greasy pizza boxes go in the trash, not the recycling. Please rinse cans and bottles.', '11월 1일부터 기름이 밴 피자 상자는 재활용이 아니라 일반 쓰레기로 버립니다. 캔과 병은 헹궈 주세요. (rinse: 헹구다)', '재활용 규정 변경'),
  ('mail13_jun', 'jun', 13, 'notice', 'Cedar Court Apartments', 'Notice of entry', 'Maintenance will enter your unit on Tuesday between 9 AM and noon to check the smoke detectors. You do not need to be home.', '화요일 오전 9시부터 정오 사이에 화재 감지기를 점검하러 관리인이 들어갑니다. 집에 계실 필요는 없습니다. (smoke detector: 화재 감지기)', '세대 출입 안내'),
  ('mail13_priya', 'priya', 13, 'notice', 'Cedar Street Lofts', 'Parking permit renewal', 'Resident parking permits expire Oct 31. Renew at the leasing office with your license and registration.', '입주민 주차 허가증이 10월 31일에 만료됩니다. 운전면허증과 차량 등록증을 가지고 관리사무소에서 갱신하세요. (permit: 허가증, renew: 갱신하다)', '주차 허가증 갱신 안내');
