  ('trip_client_dinner', 'Client dinner for two, with tip', '고객 저녁 2인(팁 포함)', 'meal', 197, 'plate-dinner', 0, NULL, 'company card: $164 plus a 20% tip', NULL, 1, 0, '법인카드: 164달러에 팁 20%'),
  ('trip_flight', 'Round-trip flight, Fairview to Ridgeport (main cabin)', '페어뷰–리지포트 왕복 항공권(일반석)', 'ticket', 386, NULL, 0, NULL, 'booked by Tom on the company card, not sold in a shop', NULL, 1, 0, '톰이 법인카드로 예약, 가게에서는 안 팖'),
