REPLACE INTO bills (id, name, name_ko, amount, day, every, note, note_ko) VALUES
  ('internet', 'Home internet', '인터넷 요금', 55, 16, 30, '300 Mbps, no contract', '300Mbps, 약정 없음'),
  ('phone', 'Phone plan', '휴대전화 요금', 45, 8, 30, 'unlimited talk and text, autopay discount', '통화·문자 무제한, 자동이체 할인'),
  ('renters_insurance', 'Renters insurance', '세입자 보험', 14, 3, 30, 'autopay from your checking account', '입출금 계좌에서 자동이체'),
  ('streaming', 'Streaming subscription', '스트리밍 구독', 15.49, 10, 30, 'renews every month until you cancel', '해지할 때까지 매달 갱신'),
