REPLACE INTO heroes (id, name, full_name, role, role_ko, model, bio, bio_ko, home_zone, home_name, home_name_ko, home_bed, home_kitchen, home_desk, home_door, desk, start_money, salary_net, salary_gross, housing, housing_name, level, level_ko, sort, housing_name_ko, name_ko, full_name_ko) VALUES
  ('derek', 'Derek', 'Derek Alvarez', 'Senior developer, onboarding buddy', '시니어 개발자, 온보딩 버디', 'man-hoodie', 'Six years at Seaside Labs. Reviews the code, is on call when things break, and shows the new hire the ropes.', '시사이드 랩스 6년 차. 코드를 리뷰하고, 장애가 나면 호출을 받고, 신입에게 일을 가르칩니다.', 'home_derek', 'House on River Road', '리버 로드의 단독 주택', 'derek_bed', 'derek_kitchen', 'derek_desk', 'derek_door', 'office_desk_team', 5400, 3900, 5770, 2150, 'Mortgage', 'Mentoring, code review, pushing back', '멘토링·코드 리뷰·반대 의견 말하기', 2, '주택담보대출 상환금', '데릭', '데릭 알바레스'),
  ('jun', 'Jun', 'Jun Kim', 'Software developer, new hire', '신입 소프트웨어 개발자', 'man-casual-3', 'Just moved to Fairview for a first job in the US. Everything is new: the badge, the standup, the tipping.', '미국 첫 직장 때문에 페어뷰로 막 이사 왔습니다. 출입증도, 스탠드업도, 팁도 모두 처음입니다.', 'home', 'Studio at Maple Street Apartments', '메이플 스트리트 아파트의 원룸', 'home_bed', 'home_kitchen', 'home_desk', 'apartment_door', 'office_desk', 1200, 2600, 3654, 1450, 'Rent', 'Everyday and first-week English', '일상·입사 첫 주 영어', 1, '월세', '준', '준 김'),
  ('priya', 'Priya', 'Priya Nair', 'Product manager', '프로덕트 매니저', 'woman-casual-2', 'Runs the standup, owns the roadmap and talks to the client. Every meeting ends on time.', '스탠드업을 진행하고, 로드맵을 책임지고, 고객과 이야기합니다. 회의는 늘 제시간에 끝납니다.', 'home_priya', 'Loft at Cedar Street Lofts', '시더 스트리트 로프트', 'priya_bed', 'priya_kitchen', 'priya_desk', 'priya_door', 'office_desk_priya', 3800, 3500, 5000, 1900, 'Rent', 'Running meetings, negotiating, stakeholders', '회의 진행·협상·이해관계자 소통', 3, '월세', '프리야', '프리야 네어');
REPLACE INTO npcs (id, name, role, role_ko, model, place, voice_pitch, voice_rate, voice_like, bio, bio_ko, name_ko) VALUES
  ('amy', 'Amy', 'Airline check-in agent', '항공사 체크인 직원', 'woman-formal-3', 'airport_checkin', 1.1, 0.98, 'Cora|Ana|Shelley|Flo', 'Quick, polite airline agent who has heard every excuse for an overweight bag.', '빠르고 공손한 항공사 직원으로, 무게 초과 가방에 대한 온갖 변명을 다 들어 봤습니다.', '에이미'),
  ('carl', 'Carl', 'Your neighbor and landlord', '이웃이자 집주인', 'man-farmer', 'bus_stop', 0.8, 0.9, 'Fred|Ralph|Grandpa|Christopher', 'Retired bus mechanic who owns your building and lives on the first floor. Calls you "kid" and has an opinion about everything.', '은퇴한 버스 정비사로, 당신이 사는 건물의 주인이고 1층에 삽니다. 당신을 "kid"라고 부르고, 모든 일에 한마디씩 합니다.', '칼'),
  ('derek', 'Derek Alvarez', 'Senior developer, your onboarding buddy', '시니어 개발자, 온보딩 버디', 'man-hoodie', 'office_desk_team', 0.9, 0.98, 'Guy|Davis|Alex|Tony', 'Laid-back senior developer who reviews code carefully but kindly. Says "No rush" and "Just ping me" a lot.', '느긋한 시니어 개발자로, 코드 리뷰는 꼼꼼하지만 친절합니다. "No rush", "Just ping me"를 입에 달고 삽니다.', '데릭 알바레스'),
  ('greg', 'Greg Whitfield', 'VP at Summit Retail (client)', '서밋 리테일 부사장(고객사)', 'man-suit', 'client_meeting', 0.85, 0.93, 'Christopher|Steffan|Bruce|Albert', 'Busy, direct client who wants the bottom line first. Friendly once he trusts you, and he likes people who say "I don''t know, but I''ll find out."', '결론부터 듣고 싶어 하는 바쁘고 직설적인 고객입니다. 믿음이 생기면 다정해지고, "모르지만 알아보겠습니다"라고 말하는 사람을 좋아합니다.', '그렉 휘트필드'),
  ('jun', 'Jun Kim', 'Software developer, new hire', '신입 소프트웨어 개발자', 'man-casual-3', 'office_desk', 1.02, 0.97, 'Eric|Brandon|Reed|Aaron', 'The new developer on the team, in his first week. Eager, polite, and full of questions he is a little shy to ask.', '팀에 새로 온 개발자로 첫 주를 보내는 중입니다. 열심이고 공손하며, 묻기 조금 쑥스러운 질문이 많습니다.', '준 김'),
  ('kelly', 'Kelly', 'Hotel front desk', '호텔 프런트 직원', 'woman-suit-2', 'hotel_desk', 1.05, 0.96, 'Michelle|Joanna|Kendra|Ivy', 'Warm hotel receptionist who always knows a good place to eat nearby.', '근처 맛집을 늘 알고 있는 친절한 호텔 프런트 직원입니다.', '켈리'),
  ('lee', 'Lee', 'TSA officer at airport security', '공항 보안 검색 요원', 'man-worker-2', 'airport_security', 0.92, 0.92, 'Roger|Tony|Albert|David', 'Calm, firm security officer. Short sentences, clear instructions, and the occasional dry joke.', '침착하고 단호한 보안 요원입니다. 짧은 문장과 분명한 지시, 가끔 건조한 농담을 합니다.', '리'),
  ('linda', 'Linda Park', 'HR and payroll', '인사·급여 담당', 'woman-formal-2', 'office_hr', 1, 0.92, 'Susan|Victoria|Elizabeth|Nancy', 'Patient HR specialist who explains forms slowly and clearly. She loves a good acronym: W-4, PTO, FICA, 401(k).', '서류를 천천히, 알기 쉽게 설명해 주는 인사 담당자입니다. W-4, PTO, FICA, 401(k) 같은 약어를 좋아합니다.', '린다 박'),
  ('maya', 'Maya Chen', 'Engineering manager', '엔지니어링 매니저', 'woman-suit', 'office_manager', 1.05, 0.94, 'Jenny|Samantha|Michelle|Zira', 'Calm and organized, with a checklist for everything. She ends almost every talk with "Let me know if you have any questions."', '차분하고 꼼꼼해서 모든 일에 체크리스트가 있습니다. 대화 끝에는 거의 늘 "Let me know if you have any questions."라고 합니다.', '마야 첸'),
  ('mike', 'Mike', 'Cashier at Fairview Market', '페어뷰 마켓 계산원', 'man-worker', 'market_checkout', 0.97, 0.98, 'Junior|Andrew|Eddy|Brian', 'College student working the evening shift. Knows every sale in the store and talks about them whether you ask or not.', '저녁 교대로 일하는 대학생입니다. 가게의 할인 상품을 전부 꿰고 있어서, 묻지 않아도 알려 줍니다.', '마이크'),
  ('nina', 'Nina', 'Barista at the coffee cart', '커피 카트 바리스타', 'woman-adventurer-2', 'coffee_cart', 1.2, 1, 'Sara|Amber|Nicky|Emma', 'Cheerful early bird who runs the coffee cart on Lake Avenue. Remembers regulars'' orders after two visits.', '레이크 애비뉴에서 커피 카트를 하는 명랑한 아침형 인간입니다. 두 번만 오면 단골의 주문을 기억합니다.', '니나'),
  ('priya', 'Priya Nair', 'Product manager', '프로덕트 매니저', 'woman-casual-2', 'office_meeting', 1.12, 1, 'Aria|Ava|Allison|Ashley', 'Upbeat product manager who keeps every meeting on time. Her favorite question is "Any blockers?"', '회의를 늘 제시간에 끝내는 밝은 프로덕트 매니저입니다. 제일 좋아하는 질문은 "Any blockers?"입니다.', '프리야 네어'),
  ('rosa', 'Rosa', 'Server at the Sunny Side Diner', '서니 사이드 다이너 종업원', 'woman-casual-3', 'diner_counter', 1.15, 1, 'Kathy|Monica|Sandy|Jane', 'Has worked the diner counter for twenty years. Calls everyone "hon" and remembers how you like your eggs.', '20년째 다이너 카운터를 지키고 있습니다. 누구에게나 "hon"이라고 부르고, 손님이 계란을 어떻게 먹는지 기억합니다.', '로사'),
